import * as THREE from 'three';

/**
 * The events' particles (docs/events.html): fireworks, sparks, ticker tape and confetti, from one pool of
 * POOL points shared by every event on stage. Sparks glow (added to what is behind them); paper is lit and
 * flutters as it falls. A particle that would go past the pool takes the oldest one's place. Below quality Low
 * the pool is not drawn at all (`enabled`), the first thing an event gives up.
 */

export const POOL = 2000;
/** Of the pool, the share that is paper and the share that is smoke; the rest are sparks. */
const PAPER = 650, SMOKE = 450;
type Kind = 'spark' | 'paper' | 'smoke';

interface Emit {
  x: number; y: number; z: number;
  vx: number; vy: number; vz: number;
  /** Seconds it lives. */
  life: number;
  colour: number;
  /** World units across. */
  size: number;
  /** Units a second² downward (paper falls at its own pace whatever this is). */
  gravity?: number;
  /** Share of its speed lost a second. */
  drag?: number;
  /** How opaque at most (smoke and paper), 0..1. */
  alpha?: number;
}

class Pool {
  readonly points: THREE.Points;
  private pos: Float32Array; private col: Float32Array; private siz: Float32Array; private alp: Float32Array;
  private vel: Float32Array; private life: Float32Array; private max: Float32Array; private grav: Float32Array; private drag: Float32Array;
  private base: Float32Array; private seed: Float32Array; private top: Float32Array;
  private next = 0;
  private live = 0;
  private c = new THREE.Color();

  readonly paper: boolean;
  constructor(readonly n: number, readonly kind: Kind) {
    this.paper = kind === 'paper';
    const paper = this.paper, smoke = kind === 'smoke';
    this.pos = new Float32Array(n * 3); this.col = new Float32Array(n * 3); this.siz = new Float32Array(n); this.alp = new Float32Array(n);
    this.vel = new Float32Array(n * 3); this.life = new Float32Array(n); this.max = new Float32Array(n); this.grav = new Float32Array(n); this.drag = new Float32Array(n);
    this.base = new Float32Array(n); this.seed = new Float32Array(n); this.top = new Float32Array(n).fill(1);
    for (let i = 0; i < n; i++) this.seed[i] = Math.random() * 100;
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(this.pos, 3).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute('aCol', new THREE.BufferAttribute(this.col, 3).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute('aSize', new THREE.BufferAttribute(this.siz, 1).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute('aAlpha', new THREE.BufferAttribute(this.alp, 1).setUsage(THREE.DynamicDrawUsage));
    g.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 1e7);
    const mat = new THREE.ShaderMaterial({
      uniforms: { uScale: SCALE },
      vertexShader: /* glsl */ `
        attribute vec3 aCol; attribute float aSize; attribute float aAlpha;
        uniform float uScale;
        varying vec3 vCol; varying float vAlpha;
        void main() {
          vCol = aCol; vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_Position = projectionMatrix * mv;
          gl_PointSize = aAlpha > 0.0 ? max(1.5, aSize * uScale / max(0.1, -mv.z)) : 0.0;
        }`,
      fragmentShader: smoke ? /* glsl */ `
        varying vec3 vCol; varying float vAlpha;
        void main() {
          float d = length(gl_PointCoord - 0.5) * 2.0;
          if (d > 1.0 || vAlpha <= 0.0) discard;
          gl_FragColor = vec4(vCol, vAlpha * (1.0 - d * d) * 0.85);
        }` : paper ? /* glsl */ `
        varying vec3 vCol; varying float vAlpha;
        void main() {
          if (vAlpha <= 0.0) discard;
          vec2 p = gl_PointCoord - 0.5;
          // a slip of paper, not a disc
          if (abs(p.y) > 0.22) discard;
          gl_FragColor = vec4(vCol, vAlpha);
        }` : /* glsl */ `
        varying vec3 vCol; varying float vAlpha;
        void main() {
          float d = length(gl_PointCoord - 0.5);
          if (d > 0.5 || vAlpha <= 0.0) discard;
          float k = (1.0 - d * 2.0);
          gl_FragColor = vec4(vCol * (0.6 + 1.6 * k * k) * vAlpha, 1.0);
        }`,
      transparent: true,
      depthWrite: false,
      blending: paper || smoke ? THREE.NormalBlending : THREE.AdditiveBlending,
    });
    this.points = new THREE.Points(g, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 3;
  }

  emit(e: Emit): void {
    const i = this.next;
    this.next = (this.next + 1) % this.n;
    if (this.life[i] <= 0) this.live++;
    this.pos.set([e.x, e.y, e.z], i * 3);
    this.vel.set([e.vx, e.vy, e.vz], i * 3);
    this.c.setHex(e.colour);
    this.col.set([this.c.r, this.c.g, this.c.b], i * 3);
    this.life[i] = this.max[i] = e.life;
    this.base[i] = e.size;
    this.top[i] = e.alpha ?? 1;
    this.grav[i] = e.gravity ?? (this.kind === 'spark' ? 1.6 : 0);
    this.drag[i] = e.drag ?? (this.kind === 'spark' ? 0.9 : 1.4);
  }

  update(dt: number, t: number): void {
    if (!this.live) return;
    let live = 0;
    const { pos, vel, life, max, alp, siz } = this;
    for (let i = 0; i < this.n; i++) {
      if (life[i] <= 0) continue;
      life[i] -= dt;
      if (life[i] <= 0) { alp[i] = 0; continue; }
      live++;
      const k = i * 3, f = Math.max(0, 1 - this.drag[i] * dt);
      vel[k] *= f; vel[k + 1] = vel[k + 1] * f - this.grav[i] * dt; vel[k + 2] *= f;
      if (this.paper) {
        // paper settles to a slow fall and swings from side to side
        const s = this.seed[i];
        vel[k + 1] += (-0.22 - vel[k + 1]) * Math.min(1, dt * 2.5);
        pos[k] += (vel[k] + Math.sin(t * 2.3 + s) * 0.12) * dt;
        pos[k + 2] += (vel[k + 2] + Math.cos(t * 1.9 + s * 1.3) * 0.12) * dt;
        pos[k + 1] += vel[k + 1] * dt;
        // a turning slip catches the light and loses it
        siz[i] = this.base[i] * (0.55 + 0.45 * Math.abs(Math.sin(t * 6 + s)));
        if (pos[k + 1] < this.floor(pos[k], pos[k + 2])) life[i] = Math.min(life[i], 1.2), vel[k] = vel[k + 1] = vel[k + 2] = 0;
      } else {
        pos[k] += vel[k] * dt; pos[k + 1] += vel[k + 1] * dt; pos[k + 2] += vel[k + 2] * dt;
        // smoke spreads as it thins
        siz[i] = this.kind === 'smoke' ? this.base[i] * (1 + (1 - life[i] / max[i]) * 2.2) : this.base[i];
      }
      const age = life[i] / max[i];
      alp[i] = this.top[i] * (this.paper ? Math.min(1, life[i] / 1.2) : this.kind === 'smoke' ? Math.min(1, age * 1.6) * Math.min(1, (1 - age) * 8) : Math.min(1, age * 2.2) * (0.75 + 0.25 * Math.sin(t * 40 + i)));
    }
    this.live = live;
    const g = this.points.geometry;
    g.attributes.position.needsUpdate = true;
    g.attributes.aCol.needsUpdate = true;
    g.attributes.aSize.needsUpdate = true;
    g.attributes.aAlpha.needsUpdate = true;
  }

  /** The ground a slip of paper settles on (set by the stage). */
  floor: (x: number, z: number) => number = () => -Infinity;

  clear(): void { this.life.fill(0); this.alp.fill(0); this.live = 0; }
}

/** Pixels per world unit at a distance of one, from the camera (set each frame). */
const SCALE = { value: 400 };

export class EventParticles {
  readonly group = new THREE.Group();
  private sparks = new Pool(POOL - PAPER - SMOKE, 'spark');
  private paper = new Pool(PAPER, 'paper');
  private smoke = new Pool(SMOKE, 'smoke');
  private t = 0;
  /** Off below quality Low: nothing is emitted or drawn. */
  enabled = true;

  constructor(parent: THREE.Object3D) {
    this.group.add(this.sparks.points, this.paper.points, this.smoke.points);
    this.group.name = 'event particles';
    parent.add(this.group);
  }

  set floor(f: (x: number, z: number) => number) { this.paper.floor = f; }

  spark(e: Emit): void { if (this.enabled) this.sparks.emit(e); }
  slip(e: Emit): void { if (this.enabled) this.paper.emit(e); }
  /** A puff of smoke (a display team's trail, mist in the streets), soft and spreading. */
  puff(e: Emit): void { if (this.enabled) this.smoke.emit(e); }

  /** A firework's burst at a point: a sphere of sparks in one or two colours, and a few slower trails. */
  burst(x: number, y: number, z: number, colours: number[], n = 70, speed = 2.6): void {
    if (!this.enabled) return;
    const shape = Math.random();
    for (let i = 0; i < n; i++) {
      // a ball, or a ring tilted at random
      let dx: number, dy: number, dz: number;
      if (shape < 0.75) {
        const u = Math.random() * 2 - 1, a = Math.random() * Math.PI * 2, r = Math.sqrt(1 - u * u);
        dx = r * Math.cos(a); dy = u; dz = r * Math.sin(a);
      } else {
        const a = (i / n) * Math.PI * 2;
        dx = Math.cos(a); dy = Math.sin(a) * 0.4; dz = Math.sin(a);
      }
      const v = speed * (0.85 + Math.random() * 0.3);
      this.sparks.emit({ x, y, z, vx: dx * v, vy: dy * v + 0.4, vz: dz * v, life: 1.4 + Math.random() * 0.9, colour: colours[i % colours.length], size: 0.24, gravity: 1.1, drag: 1.1 });
    }
  }

  /** A rocket's trail going up: a few sparks left behind it. */
  trail(x: number, y: number, z: number): void {
    if (!this.enabled) return;
    this.sparks.emit({ x, y, z, vx: (Math.random() - 0.5) * 0.2, vy: -0.3, vz: (Math.random() - 0.5) * 0.2, life: 0.5, colour: 0xffd8a0, size: 0.09, gravity: 0.5, drag: 2 });
  }

  update(dt: number, camera: THREE.PerspectiveCamera, heightPx: number): void {
    this.t += dt;
    SCALE.value = heightPx / (2 * Math.tan((camera.fov * Math.PI) / 360));
    this.group.visible = this.enabled;
    if (!this.enabled) { this.clear(); return; }
    this.sparks.update(dt, this.t);
    this.paper.update(dt, this.t);
    this.smoke.update(dt, this.t);
  }

  clear(): void { this.sparks.clear(); this.paper.clear(); this.smoke.clear(); }

  dispose(): void {
    this.group.removeFromParent();
    for (const p of [this.sparks, this.paper, this.smoke]) { p.points.geometry.dispose(); (p.points.material as THREE.Material).dispose(); }
  }
}
