import { CONTINUOUS, DEEDS, TIERS, TIER_COLOURS, TIER_POINTS, milestonesFor, type Deed, type Deeds, type Landed, type Milestone } from './deeds';
import type { Sfx } from './sfx';
import { ringStamp } from './passportStamps';

/** An achievement's seal, inked in its tier (as the Passport's visa pages show it): grey before Bronze. */
const TIER_INK = ['#a3adb3', '#8a5a2b', '#5f6b75', '#b8860b', '#2f8f96', '#2f6fc4'];
export const sealOf = (d: Deed, tier: number): string => ringStamp(`deed:${d.id}`, d.icon, '', TIER_INK[tier], 64);
import { speedIn, speedText } from './units';

/**
 * Achievement cards, the way a phone does notifications: one card at a time slides down from above the
 * top of the screen with a little spring, and slides back up and away when it is done.
 *
 * Three kinds of card, most urgent first:
 *   - landed: a tier has been reached. Its colour, its pip, a chime, a shine across the card.
 *   - soon: a smoothly climbing deed (a distance, the speedo, a slide) is five seconds from its next tier
 *     at the rate it is climbing. The card comes down early with a live bar, and when the bar fills it
 *     turns into the landed card in place. Stop short and it goes back up.
 *   - milestone: part of the way along a rung (deeds.ts `milestonesFor`), with the bar stepping forward.
 *
 * A card waits while a menu is open or the band is shut for a cut. It lives in the notice stack at the
 * top middle of the screen (#notices), below an ordinary toast (a town's name, a landform) rather than
 * queueing behind it.
 */

type Kind = 'soon' | 'landed' | 'milestone';

interface Card {
  kind: Kind;
  deed: Deed;
  /** The tier it is heading for or has reached, 1..5. */
  to: number;
  from: number;
  /** Seconds since it came down. */
  age: number;
  /** Seconds it stays down (Infinity for a countdown still counting). */
  hold: number;
  /** The bar's start and end, for a milestone's step forward. */
  barFrom: number;
  barTo: number;
}

/** How far ahead of a tier the countdown card comes down, in seconds at the current rate. */
const LEAD = 5;
/** A countdown gives up when the tier drifts this far off. */
const GIVE_UP = 12;
const SHOW_LANDED = 4.2, SHOW_MILESTONE = 2.8, SLIDE_OUT = 0.45, GAP = 0.3;

export class DeedCards {
  private el = document.createElement('div');
  private icon = document.createElement('div');
  private name = document.createElement('b');
  private chip = document.createElement('span');
  private line = document.createElement('div');
  private fill = document.createElement('i');
  private card: Card | null = null;
  private leaving = 0;
  private gap = 0;
  /** Each smoothly climbing deed's last value and its rate of climb (per second), smoothed. */
  private rates = new Map<string, { last: number; rate: number }>();
  /** Seconds before a countdown that gave up may come down again. */
  private rest = new Map<string, number>();
  /** Seconds a countdown's tier has been further off than GIVE_UP. */
  private drifting = 0;
  private lastText = '';
  /** A tier landed: into the notification history, with its seal. */
  onLanded: (title: string, body: string, seal: string) => void = () => {};
  /**
   * Set, and tiers and milestones are handed here as they come (the stamp cards' stream shows one card in
   * fifteen seconds, the batch's best: docs/passport.html) instead of coming down on a card of their own. The
   * countdown card, five seconds from a tier, belongs to a card of its own and is not shown then.
   */
  stream: ((n: { deed: Deed; tier: number; from: number; title: string; body: string; seal: () => string; milestone: boolean }) => void) | null = null;
  /** Something else is using the notice stack (a Passport stamp's card): nothing new comes down meanwhile. */
  blocked: () => boolean = () => false;

  constructor(private deeds: Deeds, private sfx: Sfx) {
    this.el.id = 'deed-card';
    this.el.className = 'notice';
    this.el.setAttribute('role', 'status');
    this.el.setAttribute('aria-live', 'polite');
    this.icon.className = 'dc-icon';
    const body = document.createElement('div');
    body.className = 'dc-body';
    const top = document.createElement('div');
    top.className = 'dc-top';
    this.name.className = 'dc-name';
    this.chip.className = 'dc-chip';
    top.append(this.name, this.chip);
    this.line.className = 'dc-line';
    const bar = document.createElement('div');
    bar.className = 'dc-bar';
    bar.append(this.fill);
    body.append(top, this.line, bar);
    this.el.append(this.icon, body);
    document.getElementById('notices')!.insertBefore(this.el, document.getElementById('earnings'));
  }

  /** Every frame. `hold` is true while a menu is open or a cut has the screen: nothing new comes down. */
  update(dt: number, hold: boolean): void {
    if (this.stream) {
      if (!this.deeds.active) return;
      for (let l = this.deeds.next(); l; l = this.deeds.next()) {
        const d = l.deed, to = l.to;
        let gems = 0;
        for (let k = l.from; k < to; k++) gems += TIER_POINTS[k];
        const at = d.kind === 'set' && d.of ? `${this.deeds.value(d)} of ${d.of}` : count(d, this.deeds.value(d));
        this.stream({ deed: d, tier: to, from: l.from, milestone: false, title: `${d.name} · ${TIERS[to - 1]}`, body: `${at} · +◆ ${gems}${to < 5 ? ` · ${TIERS[to]} at ${count(d, d.ladder[to], true)}` : ' · every tier'}`, seal: () => sealOf(d, to) });
      }
      for (let m = this.deeds.nextMilestone(); m; m = this.deeds.nextMilestone()) {
        const d = m.deed;
        this.stream({ deed: d, tier: m.to, from: m.to - 1, milestone: true, title: d.name, body: `${Math.round(m.frac * 100)}% of the way to ${TIERS[m.to - 1]} · ${count(d, this.deeds.value(d))} of ${count(d, d.ladder[m.to - 1], true)}`, seal: () => sealOf(d, m.to - 1) });
      }
      void hold;
      return;
    }
    this.measure(dt);
    for (const [id, s] of this.rest) this.rest.set(id, s - dt);

    if (this.leaving > 0) {
      this.leaving -= dt;
      if (this.leaving <= 0) { this.card = null; this.el.classList.remove('out', 'landed', 'soon', 'milestone'); this.gap = GAP; }
      return;
    }
    const c = this.card;
    if (c) {
      c.age += dt;
      if (c.kind === 'soon') this.countdown(c, dt);
      else if (c.age >= c.hold) this.dismiss();
      // a tier landing, or a countdown due, pushes a milestone card off early; a countdown due pushes
      // a landed card off once it has had its moment, so the next one still gets its five seconds
      else if (c.kind === 'milestone' && c.age > 0.9 && (this.deeds.waiting || this.dueSoon())) this.dismiss();
      else if (c.kind === 'landed' && c.age > 1.9 && this.dueSoon()) this.dismiss();
      if (this.card) this.paint(this.card);
      return;
    }
    this.gap -= dt;
    if (hold || this.gap > 0 || !this.deeds.active || this.blocked()) return;
    const landed = this.deeds.next();
    if (landed) { this.show(this.landedCard(landed)); return; }
    const soon = this.dueSoon();
    if (soon) { this.show({ kind: 'soon', deed: soon, to: this.deeds.tier(soon) + 1, from: this.deeds.tier(soon), age: 0, hold: Infinity, barFrom: 0, barTo: 0 }); return; }
    const m = this.deeds.nextMilestone();
    if (m) this.show(this.milestoneCard(m));
  }

  // ---- the kinds ----

  private landedCard(l: Landed): Card {
    return { kind: 'landed', deed: l.deed, to: l.to, from: l.from, age: 0, hold: SHOW_LANDED, barFrom: 1, barTo: 1 };
  }

  private milestoneCard(m: Milestone): Card {
    // the bar steps forward from the milestone before to this one
    const steps = [0, ...milestonesFor(m.deed, m.to - 1)];
    const before = steps.filter((s) => s < m.frac).pop() ?? 0;
    return { kind: 'milestone', deed: m.deed, to: m.to, from: m.to - 1, age: 0, hold: SHOW_MILESTONE, barFrom: before, barTo: m.frac };
  }

  /** The smoothly climbing deed nearest its next tier, if that is within LEAD seconds. */
  private dueSoon(): Deed | null {
    let best: Deed | null = null, bestEta = LEAD;
    for (const d of DEEDS) {
      if (!CONTINUOUS.has(d.stat) || (this.rest.get(d.id) ?? 0) > 0) continue;
      const eta = this.eta(d);
      if (eta !== null && eta <= bestEta) { bestEta = eta; best = d; }
    }
    return best;
  }

  /** Seconds to the deed's next tier at its current rate, or null when it isn't climbing. */
  private eta(d: Deed): number | null {
    const tier = this.deeds.tier(d);
    if (tier >= 5) return null;
    const r = this.rates.get(d.id);
    if (!r || r.rate < 1e-3) return null;
    const left = d.ladder[tier] - this.deeds.raw(d);
    // a tier already reached waits for the once-a-second stamp, which the countdown asks for itself
    return left <= 0 ? 0 : left / r.rate;
  }

  /** Keep a countdown true: fill the bar, turn it into the landed card, or give up and go. */
  private countdown(c: Card, dt: number): void {
    const d = c.deed;
    if (this.deeds.raw(d) >= d.ladder[c.to - 1]) {
      this.deeds.tick();
      const l = this.deeds.takeLanded(d);
      if (l) {
        Object.assign(c, { kind: 'landed', to: l.to, from: l.from, age: 0, hold: SHOW_LANDED, barFrom: 1, barTo: 1 });
        this.land(c);
        return;
      }
    }
    const eta = this.eta(d);
    this.drifting = eta === null || eta > GIVE_UP ? this.drifting + dt : 0;
    if (this.drifting > 1.5) {
      this.rest.set(d.id, 6);
      this.dismiss();
    }
  }

  // ---- showing ----

  private show(c: Card): void {
    this.card = c;
    this.drifting = 0;
    this.lastText = '';
    this.el.classList.remove('out', 'landed', 'soon', 'milestone', 'pop');
    this.el.classList.add(c.kind);
    this.el.style.setProperty('--tier', TIER_COLOURS[c.to - 1]);
    // the seal it has, until a tier lands and the next is pressed on
    this.icon.replaceChildren(sealImg(sealOf(c.deed, c.kind === 'landed' ? c.from : this.deeds.tier(c.deed))));
    this.name.textContent = c.deed.name;
    // a milestone's bar starts where the last one left off, then steps forward once the card is down
    this.fill.style.transition = 'none';
    this.fill.style.width = `${(c.kind === 'milestone' ? c.barFrom : c.kind === 'landed' ? 0.94 : this.frac(c)) * 100}%`;
    void this.el.offsetWidth;
    this.fill.style.transition = '';
    this.paint(c);
    this.el.classList.add('in');
    if (c.kind === 'landed') this.land(c);
    else if (c.kind === 'milestone') this.sfx.nudge();
  }

  /** A tier lands on the card showing: the colour, the chime, the pop and the shine. */
  private land(c: Card): void {
    this.el.classList.remove('soon', 'milestone');
    this.el.classList.add('landed');
    this.el.style.setProperty('--tier', TIER_COLOURS[c.to - 1]);
    // restart the pop and the shine even when the card was already down
    this.el.classList.remove('pop');
    void this.el.offsetWidth;
    this.el.classList.add('pop');
    this.sfx.chime(c.to);
    this.lastText = '';
    // the new tier's seal pressed onto the card, and kept in the history
    const seal = sealOf(c.deed, c.to);
    this.icon.replaceChildren(sealImg(seal));
    this.el.classList.remove('stamping');
    void this.el.offsetWidth;
    this.el.classList.add('stamping');
    const at = c.deed.kind === 'set' && c.deed.of ? `${this.deeds.value(c.deed)} of ${c.deed.of}` : count(c.deed, this.deeds.value(c.deed));
    this.onLanded(`${c.deed.name} · ${TIERS[c.to - 1]}`, `${at}${c.to < 5 ? ` · ${TIERS[c.to]} at ${count(c.deed, c.deed.ladder[c.to], true)}` : ' · every tier'}`, seal);
  }

  /** Is a card down (or going)? */
  get busy(): boolean { return !!this.card || this.leaving > 0; }

  private dismiss(): void {
    this.el.classList.remove('in', 'stamping');
    this.el.classList.add('out');
    this.leaving = SLIDE_OUT;
  }

  /** How far along the rung toward `to` the deed is, 0..1. */
  private frac(c: Card): number {
    const d = c.deed, lo = c.to > 1 ? d.ladder[c.to - 2] : 0, hi = d.ladder[c.to - 1];
    return Math.max(0, Math.min(1, (this.deeds.raw(d) - lo) / Math.max(1e-6, hi - lo)));
  }

  private paint(c: Card): void {
    const d = c.deed, tier = TIERS[c.to - 1];
    let chip: string, line: string, width: number;
    if (c.kind === 'landed') {
      const reached = c.to - c.from > 1 ? `${TIERS.slice(c.from, c.to - 1).join(', ')} and ${tier}` : tier;
      // every tier pays its points in diamonds (docs/territory.html)
      let gems = 0;
      for (let k = c.from; k < c.to; k++) gems += TIER_POINTS[k];
      chip = `<i class="pip">${c.to}</i>${reached} <em class="gem">+◆ ${gems}</em>`;
      const at = d.kind === 'set' && d.of ? `${this.deeds.value(d)} of ${d.of}` : count(d, this.deeds.value(d));
      line = `${at}${c.to < 5 ? ` · ${TIERS[c.to]} at ${count(d, d.ladder[c.to], true)}` : ' · every tier'}`;
      width = 1;
    } else if (c.kind === 'soon') {
      const f = this.frac(c);
      chip = `${tier} <em>${Math.floor(f * 100)}%</em>`;
      const left = Math.max(0, d.ladder[c.to - 1] - this.deeds.raw(d));
      line = `${count(d, this.deeds.raw(d))} of ${count(d, d.ladder[c.to - 1], true)} · ${count(d, Math.ceil(left))} to go`;
      width = f;
    } else {
      chip = `${Math.round(c.barTo * 100)}% to ${tier}`;
      line = `${count(d, this.deeds.value(d))} of ${count(d, d.ladder[c.to - 1], true)}`;
      width = c.age > 0.35 ? c.barTo : c.barFrom;
    }
    // the chip and the line are written apart: the line ticks on as the count climbs, and rewriting the
    // chip with it would put a fresh medal under the .pop class each time, popping it over and over
    if (chip !== this.lastText) {
      this.lastText = chip;
      this.chip.innerHTML = chip;
    }
    if (this.line.textContent !== line) this.line.textContent = line;
    const w = `${(width * 100).toFixed(2)}%`;
    if (this.fill.style.width !== w) this.fill.style.width = w;
  }

  /** Each smoothly climbing deed's rate, smoothed over about a second. */
  private measure(dt: number): void {
    if (dt <= 0) return;
    for (const d of DEEDS) {
      if (!CONTINUOUS.has(d.stat)) continue;
      const v = this.deeds.raw(d);
      const r = this.rates.get(d.id);
      if (!r || v < r.last) { this.rates.set(d.id, { last: v, rate: 0 }); continue; }
      const inst = (v - r.last) / dt;
      // a jump no driving could make (a teleport, the console) doesn't count as climbing
      r.rate += ((inst > 400 ? 0 : inst) - r.rate) * Math.min(1, dt / 1.1);
      r.last = v;
    }
  }
}


function sealImg(src: string): HTMLImageElement {
  const i = document.createElement('img');
  i.src = src;
  i.alt = '';
  return i;
}

/** A deed's number in its unit: "1,234 tiles", "$5,000"; `bare` drops the word after it. */
function count(d: Deed, v: number, bare = false): string {
  if (d.unit === 'km/h') return bare ? String(speedIn(Math.floor(v))) : speedText(Math.floor(v));
  const n = Math.floor(v).toLocaleString('en-US');
  if (d.unit === '$') return `$${n}`;
  return bare ? n : `${n} ${d.unit}`;
}
