import type { TownKind } from '../../world/tiles';

/**
 * What is said in a tavern (game/tavern/tavern.ts): sixty-four stories, each a paragraph of local talk
 * about the town it is told in — the mayor, the shops, what is going up, who has come to town, the
 * haulage firms, a load that went astray, the trains, the airships, the sea. Half of them end in work:
 * a job worth more than $1,000 that is hard in some way (hidden, hot, far, timed, or wanting a particular
 * vehicle), taken there and then from the tavern card. A few tell of a vehicle nobody has claimed, and
 * some jobs pay in such a tip as well as cash.
 *
 * A story's words are a function of the town it is told in (`TaleCtx`), so the same story told in two
 * towns names two mayors, two bakeries and two roads. `needs` says what a story can't be told without.
 */

/** What a job asks for. The tavern finds the place (and, for a smuggle, the buyer) when the story is told. */
export type JobSpec =
  /** A place whose ring is hidden until the player is within a few tiles; stop in it. */
  | { k: 'treasure'; at: 'summit' | 'landmark' | 'lighthouse' | 'wonder' | 'cabin' | 'derelict' | 'beach' }
  /** Contraband in the hold here and now, a buyer in another town, the police out for it. */
  | { k: 'smuggle' }
  /** Somewhere the player has never seen: a wonder, a megalopolis, a biome, a lonely landmark. */
  | { k: 'explore'; what: 'wonder' | 'mega' | 'biome' | 'far' }
  /** Somewhere named, against the clock. */
  | { k: 'timed'; to: 'town' | 'port' | 'station' | 'airfield' }
  /** Somewhere named and back to this tavern's door, against the clock. */
  | { k: 'fetch'; from: 'port' | 'station' | 'town' | 'airfield' | 'farm' }
  /** Come back in a particular vehicle and do what only it can. */
  | { k: 'ride'; ride: 'wrecker' | 'ambulance' | 'bus' | 'limo' | 'heli' | 'boat' | 'quad' };

/** A job as found in this town: what the story says of it. */
export interface BoundJob {
  /** Dollars, or for a smuggle the likely range ("$1,400–$2,600"). */
  pay: string;
  /** The place named ("Harwick Station"), or for a hidden one what the story may say of it. */
  place: string;
  /** Time allowed, in plain words ("four minutes"), or null. */
  limit: string | null;
  /** The vehicle wanted, plainly ("a tow truck"), or null. */
  ride: string | null;
  /** Straight-line tiles to it, or null. */
  far: number | null;
  /** Whether finishing also buys a tip about a hidden vehicle. */
  clue: boolean;
}

export interface TaleCtx {
  town: string;
  townKind: TownKind;
  /** The county (or island) the tavern stands in. */
  county: string;
  mayor: string;
  /** The tavern's own name and its sort ("Saloon"). */
  tavern: string;
  word: string;
  /** A business in town, with its article ("the bakery", "the bank"), and another. */
  biz: string;
  biz2: string;
  /** Another town in reach. */
  other: string | null;
  /** A haulage firm about the place, how many vehicles it runs, and its home town. */
  firm: { name: string; units: number; town: string } | null;
  station: string | null;
  port: string | null;
  airfield: string | null;
  wonder: string | null;
  /** A named landform (a mountain, a lake, a gorge). */
  landmark: string | null;
  /** A building going up or just up in town ("a new cinema"). */
  newBuild: string | null;
  /** A hidden vehicle within reach: what people call it and where they say it is. */
  stash: { noun: string; hint: string } | null;
  job: BoundJob | null;
}

export interface Story {
  id: string;
  topic: 'mayor' | 'business' | 'building' | 'newcomers' | 'fleets' | 'cargo' | 'rail' | 'sky' | 'sea' | 'land' | 'legend' | 'underworld' | 'finds';
  /** Who tells it, if the story wants someone in particular ("a woman in a wet oilskin"). */
  who?: string;
  needs?: (c: TaleCtx) => boolean;
  job?: JobSpec & { clue?: boolean };
  /** It tells where a hidden vehicle is: written in the notebook. */
  tip?: boolean;
  text: (c: TaleCtx) => string;
}

const j = (c: TaleCtx): BoundJob => c.job!;
const tip = (c: TaleCtx): string => (j(c).clue ? ' And I’ll throw in something better than money: I know where a vehicle’s sitting that nobody’s claimed.' : '');
const cap = (s: string): string => s[0].toUpperCase() + s.slice(1);

