import { idx, type Building, type World } from '../world/tiles';
import { CARRIAGES, type VehicleDef } from './vehicles';

/**
 * Horse-drawn carriages in the traffic (game/traffic.ts spawn): the old towns and the tourist towns keep them,
 * a landau or a hackney carriage trotting from one of the town's sights or squares to another. Which styles
 * do, and how often a car that would have set off in such a town is a carriage instead.
 */
const CARRIAGE_STYLES = new Set<string>([
  'medieval', 'tudor', 'london', 'paris', 'venice', 'budapest', 'dutch', 'victorian', 'neworleans', 'havana',
  'roman', 'moorish', 'western', 'colonial', 'shire', 'steampunk', 'newyork', 'adriatic', 'whitecity',
]);
/** The share of a county's new trips that are carriages when every one of its towns keeps them. */
const SHARE = 0.14;

const towns = new WeakMap<World, { ids: Set<number>; share: number }>();

function carriageTowns(w: World): { ids: Set<number>; share: number } {
  let t = towns.get(w);
  if (!t) {
    const ids = new Set<number>();
    let all = 0, old = 0;
    for (const town of w.towns) {
      const n = town.buildings.length;
      all += n;
      if (CARRIAGE_STYLES.has(town.style)) { ids.add(town.id); old += n; }
    }
    t = { ids, share: all ? (SHARE * old) / all : 0 };
    towns.set(w, t);
  }
  return t;
}

/** How likely a new trip in this county is a carriage (0 where no town keeps them). */
export const carriageShare = (w: World): number => carriageTowns(w).share;

/** Is this building in a town that keeps carriages? */
export function carriageTown(w: World, b: Building | undefined): number | null {
  if (!b) return null;
  const id = w.townId[idx(b.x, b.z)];
  return id >= 0 && carriageTowns(w).ids.has(id) ? id : null;
}

const isCarriage = (d: VehicleDef): boolean => d.id === 'carriage' || d.id.startsWith('carriage');

export const pickCarriage = (): VehicleDef => CARRIAGES[Math.floor(Math.random() * CARRIAGES.length) % CARRIAGES.length];
