function factionJob(f: FactionId): Template {
  const d = FACTIONS[f];
  return {
    id: `fac:${f}`, thread: 'town', kind: 'job', side: true, cooldown: 18,
    gate() {
      if (reputation.rung(f) < RUNG.friend) return `${d.name} don’t know you yet`;
      return null;
    },
    bind(c: MissionCtx, h: number): Draft | null {
      const list = JOBS[f];
      const spec = list[h % list.length];
      const at = hall(c, f, 220);
      // one done from the hall (a round of stations, a meeting): only with a hall to give it
      if (spec.build) {
        if (!at) return null;
        const objs = spec.build(c, at);
        if (!objs.length || objs.some((o) => !o)) return null;
        const pay = (objs as Obj[]).reduce((t, o) => t + (o.t === 'deliver' ? o.value : 0), 0);
        return {
          title: spec.title, why: spec.why,
          details: `${d.name} pays for its own work at its own rate: the friendlier you are, the better.`,
          giver: giverAt(f, at), hero: hero(f, at), caption: `${d.icon} ${d.name}`,
          objs: objs as Obj[], reward: [cash(Math.round((pay * 1.6) / 10) * 10 + 160)], hours: 10,
        };
      }
      const obj = job(c, spec.cargo, spec.from, spec.to, 1, at ?? undefined);
      if (!obj || obj.t !== 'deliver') return null;
      const type = cargoById(spec.cargo);
      const from = c.sites(spec.from).find((s) => Math.hypot(s.x - obj.from.x, s.z - obj.from.z) < 2);
      return {
        title: spec.title, why: spec.why,
        details: `${d.name} pays for its own work at its own rate: the friendlier you are, the better.`,
        giver: at ? giverAt(f, at) : from ? giverSite(f, from) : { who: GIVER[f].who, name: GIVER[f].name, at: obj.from, town: null },
        hero: hero(f, at), caption: `${d.icon} ${d.name}`,
        objs: [obj], reward: [cash(Math.round((obj.value * 1.6) / 10) * 10 + 60)], hours: 10,
        ...(type ? {} : {}),
      };
    },
  };
}

