/** Three of a faction's places after dark, a few minutes at each. */
function nightRound(c: MissionCtx, s: Spot, kinds: string[]): (Obj | null)[] {
  const out: Spot[] = [];
  for (let k = 0; k < 3; k++) {
    const p = findSpot(c, kinds, out[k - 1] ?? s, 260, name, [s, ...out]);
    if (!p) break;
    out.push(p);
  }
  if (out.length < 2) return [null];
  return out.map((p, k) => meet(p, ['Visit the station after dark', 'Visit the next station', 'Visit the last station'][k], '🚓', { when: 'night', hold: 6 }));
}

