/** Each stronghold as its people call it on a card ("You've never seen the Yard"). */
const HOME: Record<FactionId, string> = {
  police: 'the Yard', family: 'the villa', ministry: 'the Citadel', visitors: 'Site Null', unions: 'Federation House',
  post: 'the GPO', army: 'the base', studios: 'the Lot', guild: 'Corran Harbour', press: 'Vane House',
};

/** What a stronghold step's objectives are made with: places at the stronghold, and loads into it or out of it. */
interface Aims {
  /** Drive to the stronghold's gate, door or stage; `after`–`before` the hours it counts in, `hold` seconds stopped there. */
  reach(at: AimAt, label: string, icon: string, o?: { when?: 'night' | 'midnight' | 'dawn'; after?: number; before?: number; hold?: number; r?: number }): Obj;
  /** A load of the faction's from the nearest of `from` by the hall, into the stronghold's door. */
  into(cargo: string, from: string[], label: string): Obj | null;
  /** A load out of the stronghold's door to the nearest of `to` by the hall. */
  out(cargo: string, to: string[], label: string): Obj | null;
}

const WHEN: Record<'night' | 'midnight' | 'dawn', [number, number]> = { night: [21, 4], midnight: [23, 1], dawn: [4, 8] };
const SH_KIND: SiteRef['kind'] = 'stronghold';

function aimsFor(c: MissionCtx, f: FactionId, s: Spot): Aims {
  const spot = (at: AimAt) => strongholdSpot(c.seed, c.worlds, f, here(c), at);
  // a site near the hall, else anywhere in the Oath's reach (a load never strands the step on the hall's county)
  const near = (kinds: string[]) => siteNear(c, kinds, s.at, 0, 260) ?? siteNear(c, kinds, here(c), 0, OATH_REACH);
  const load = (cargo: string, site: Site | null, end: 'from' | 'to', label: string): Obj | null => {
    const type = cargoById(cargo);
    if (!type || !site) return null;
    const sp = spot('door');
    const sh: SiteRef = { ...sp.at, kind: SH_KIND };
    const value = Math.round((40 + aimTiles(site, sp.at) * 0.9) / 5) * 5;
    return {
      t: 'deliver', label, icon: type.icon, cargo: type.id, n: 1, value,
      from: end === 'to' ? siteRef(site) : sh, to: end === 'to' ? sh : siteRef(site),
      stronghold: { ...sp.aim, end },
    };
  };
  return {
    reach(at, label, icon, o = {}) {
      const sp = spot(at);
      const hours = o.when ? WHEN[o.when] : o.after !== undefined && o.before !== undefined ? [o.after, o.before] : null;
      return {
        t: 'reach', label, icon, at: sp.at, r: o.r ?? (at === 'gate' ? 5 : 4), stronghold: sp.aim,
        ...(hours ? { after: hours[0], before: hours[1] } : {}), ...(o.hold ? { stop: true, hold: o.hold } : {}),
      };
    },
    into: (cargo, from, label) => load(cargo, near(from), 'to', label),
    out: (cargo, to, label) => load(cargo, near(to), 'from', label),
  };
}

