/** The stronghold on the card's plinth. */
function shHero(f: FactionId): HeroSpec {
  const kind = STRONGHOLD_OF[f], [w, d] = INFO_080[kind].size;
  return { kind: 'building', b: kind, arch: 'classic', w, d, floors: 2 };
}

const arcId = (f: FactionId) => `oath-${f}`;
const oathTpl = (f: FactionId, i: number) => `oath:${f}:${i + 1}`;

/** The Oath's step a template id is, or null. */
export function oathOf(tpl: string): { f: FactionId; i: number } | null {
  const m = /^oath:([a-z]+):(\d)$/.exec(tpl);
  return m && m[1] in FACTIONS ? { f: m[1] as FactionId, i: Number(m[2]) - 1 } : null;
}

/** How far off an Oath's hall may be: it is the one mission a faction offers at 9,999, so worth a drive. */
const OATH_REACH = 1200;

/** The faction's halls of each kind nearest the player, out to OATH_REACH, nearest first. */
function oathHalls(c: MissionCtx, f: FactionId): Spot[] {
  const out: Spot[] = [];
  for (const k of FACTIONS[f].hall) {
    const s = findSpot(c, [k], here(c), OATH_REACH, name);
    if (s) out.push(s);
  }
  return out.sort((a, b) => Math.hypot(a.at.x - c.at.x, a.at.z - c.at.z) - Math.hypot(b.at.x - c.at.x, b.at.z - c.at.z));
}

function oathStep(f: FactionId, i: number): Template {
  const d = FACTIONS[f];
  const ride = d.unlocks[1].model;
  const rideName = d.unlocks[1].name;
  // 0.8.0: steps 1, 3 and 5 are at the stronghold and take any vehicle; 2 and 4 are begun at a hall in the Honoured one
  const step080 = (): Oath080 | null => (NEXT_080 ? OATHS_080[f][i] : null);
  return {
    id: oathTpl(f, i), thread: 'town', kind: 'job', arc: arcId(f),
    gate(c: MissionCtx, ms: Missions) {
      if ((ms.arcs?.get(arcId(f)) ?? 0) !== i) return 'not its turn';
      if (reputation.sworn(f)) return 'sworn already';
      if (!reputation.oathOpen(f)) return `${d.name} must count you Honoured to ${OATH_AT.toLocaleString('en-GB')}`;
      const s = step080();
      if ((!s || 'hall' in s) && !c.units.some((u) => u.model === ride)) return `needs the ${rideName}`;
      return null;
    },
    bind(c: MissionCtx): Draft | null {
      const s080 = step080();
      if (s080 && !('hall' in s080)) return strongholdStep(c, f, i, s080);
      // the nearest hall where this step can happen, out to OATH_REACH: not only the nearest hall (one with no bus
      // station or crash site in reach left the Army's Oath never posted); failing every hall, one of the faction's
      // own jobs from there stands in for the step, so an Oath is never stuck on a county's geography
      const step = s080 ? s080.hall : OATHS[f][i];
      let s: Spot | null = null, objs: (Obj | null)[] = [];
      const halls = oathHalls(c, f);
      for (const h of halls) {
        objs = step.build(c, h);
        if (objs.every((o) => !!o)) { s = h; break; }
      }
      if (!s) {
        for (const h of halls) {
          const o = JOBS[f].map((j) => (j.cargo ? job(c, j.cargo, j.from, j.to, 1, h) : null)).find((x) => !!x);
          if (o) { s = h; objs = [o]; break; }
        }
      }
      if (!s) return null;
      const start: Obj = { t: 'reach', label: `Bring the ${rideName}`.slice(0, 28), icon: d.icon, at: s.at, r: 6, ride: { ids: [ride], label: `the ${rideName}` } };
      return {
        title: `${step.title}`, why: step.why,
        details: `The Oath of ${d.name}, step ${i + 1} of 5, begun at their hall in the ${rideName}. ${i === 4 ? 'The last step: done, and they count you Sworn.' : 'Each step done moves you on to the next.'}`,
        giver: giverAt(f, s), hero: { kind: 'vehicle', model: ride }, caption: `${d.icon} The Oath · ${i + 1} of 5`,
        objs: [start, ...(objs as Obj[])], reward: [cash(400 + 200 * i)], hours: 24,
      };
    },
  };
}

/**
 * A step at the stronghold (steps 1, 3 and 5 of the 0.8.0 Oath): offered at the nearest hall that can bind it, as Oath
 * offers are, in any vehicle, 48 game hours to do it and pay for the distance on top. Failing every hall's loads, a
 * faction load of its own goes into the stronghold instead (and the swearing still follows), so the Oath never sticks.
 */
function strongholdStep(c: MissionCtx, f: FactionId, i: number, step: Extract<Oath080, { build: unknown }>): Draft | null {
  const d = FACTIONS[f];
  const halls = oathHalls(c, f);
  let s: Spot | null = null, objs: (Obj | null)[] = [];
  for (const h of halls) {
    objs = step.build(c, h, aimsFor(c, f, h));
    if (objs.every((o) => !!o)) { s = h; break; }
  }
  if (!s) {
    for (const h of halls) {
      const a = aimsFor(c, f, h);
      const o = JOBS[f].map((j) => (j.cargo ? a.into(j.cargo, j.from, 'Bring the load in') : null)).find((x) => !!x);
      if (o) { s = h; objs = i === 4 ? [o, a.reach('stage', 'Reach the stage', d.icon, { hold: 25 })] : [o]; break; }
    }
  }
  if (!s) return null;
  const door = strongholdSpot(c.seed, c.worlds, f, here(c), 'door');
  const far = aimTiles(s.at, door.at);
  return {
    title: step.title, why: step.why,
    details: `The Oath, step ${i + 1} of 5, at ${door.at.name}, in any vehicle. ${i === 4 ? 'Done, and they count you Sworn.' : 'Done, and the next step comes.'}`,
    // the summons is a letter from the top
    giver: i === 0 ? { ...giverAt(f, s), name: LEADER[f] } : giverAt(f, s), hero: shHero(f), caption: `${d.icon} The Oath · ${i + 1} of 5`,
    objs: objs as Obj[], reward: [cash(400 + 200 * i + Math.round((far * 0.5) / 10) * 10)], hours: 48,
  };
}

/** Already Sworn before the strongholds (0.8.0): once, a letter from the leader asks them to come and see it. */
const swornArc = (f: FactionId) => `sworn-${f}`;
const swornTpl = (f: FactionId) => `sworn:${f}`;

function swornVisit(f: FactionId): Template {
  const d = FACTIONS[f];
  return {
    id: swornTpl(f), thread: 'town', kind: 'trip', arc: swornArc(f),
    gate(_c: MissionCtx, ms: Missions) {
      if (!NEXT_080) return 'no strongholds yet';
      if ((ms.arcs?.get(swornArc(f)) ?? 0) !== 0) return 'been already';
      if (!reputation.sworn(f)) return `not sworn to ${d.name}`;
      return null;
    },
    bind(c: MissionCtx): Draft | null {
      const s = oathHalls(c, f)[0];
      if (!s) return null;
      const a = aimsFor(c, f, s);
      const door = strongholdSpot(c.seed, c.worlds, f, here(c), 'door');
      return {
        title: 'Come and See', why: `${LEADER[f]} writes: “You’ve never seen ${HOME[f]}. Come and see what you swore to.”`,
        details: `${d.name} have a stronghold now: ${door.at.name}. Its gate opens to you, Sworn as you are. A visit, if you like; nothing rides on it.`,
        giver: { ...giverAt(f, s), name: LEADER[f] }, hero: shHero(f), caption: `${d.icon} ${d.name}`,
        objs: [a.reach('door', `Visit ${HOME[f]}`, d.icon, { hold: 5 })], reward: [cash(500 + Math.round((aimTiles(s.at, door.at) * 0.3) / 10) * 10)], hours: 72,
      };
    },
  };
}

export const FACTION_TEMPLATES: Template[] = (Object.keys(FACTIONS) as FactionId[]).flatMap((f) => [factionJob(f), ...[0, 1, 2, 3, 4].map((i) => oathStep(f, i)), swornVisit(f)]);

export const OATH_ARCS: Arc[] = (Object.keys(FACTIONS) as FactionId[]).flatMap((f) => [
  { id: arcId(f), title: `The Oath of ${FACTIONS[f].name}`, thread: 'town', who: GIVER[f].name, tpls: [0, 1, 2, 3, 4].map((i) => oathTpl(f, i)) },
  { id: swornArc(f), title: `${FACTIONS[f].name}: the stronghold`, thread: 'town', who: LEADER[f], tpls: [swornTpl(f)] },
] as Arc[]);

void siteAt;
