import * as THREE from 'three';
import { N, STEP, heightAt, type Arch, type Building, type World } from '../world/tiles';
import { stadiumFrame, stadiumToIsland } from '../world/stadiums';
import { hashString, mulberry32 } from '../world/rng';
import { REELS, Reels } from '../render/reels';
import { MarqueeTextures, boardPlace, marqueeBill } from '../render/marquee';
import { builtShare } from '../render/townMesh';

/**
 * Moving pictures in the world (render/reels.ts): the drive-in's screen plays a feature through the
 * evening, a new one every so often, and the busiest crossings of a New York, Tokyo or Modernist
 * megalopolis are hung with video billboards, Times Square fashion, cycling the same cartoons all day.
 * Screens are built for each county as it comes into memory and go with it; only those near the camera
 * show (and only the cartoons they show are drawn).
 *
 * And the marquees: every picture palace's and playhouse's letter boards (render/marquee.ts) carry the day's
 * bill, picked from the game day, so the titles change each morning. `update` is given the game clock in
 * hours since day 0 (days × 24 + hour); only the hour of it matters to the drive-in and the billboards.
 */

/** Megalopolises in these styles get billboard crossings. */
const BILLBOARD_STYLES = new Set<Arch>(['newyork', 'tokyo', 'modernist', 'osaka']);
/** Crossings per megalopolis, and how far apart they must be, in tiles. */
const CROSSINGS = 2, APART = 10;
/** A corner building must stand this tall over its ground to carry a screen. */
const TALL = 1.3;
/** Screens show within this many tiles of the camera. */
const SHOW_R = 230;
/** The drive-in's programme: evenings from 19:00 to half past midnight, a new feature every FEATURE real seconds. */
const SHOW_FROM = 19, SHOW_TO = 24.5, FEATURE = 45;
/** A billboard changes picture every so often. */
const BOARD_EVERY = 9;
/** Marquee boards show within this many tiles of the camera: the letters are too small to read further off. */
const MARQUEE_R = 110;
/** The darkened screen round a drive-in's picture. */
const BACK = new THREE.MeshBasicMaterial({ color: 0x0c1018, toneMapped: false, fog: false });

interface Screen {
  mesh: THREE.Mesh;
  mat: THREE.MeshBasicMaterial;
  kind: 'drivein' | 'board';
  /** A dark backing behind the picture, over the rest of a drive-in's wide white panel. */
  back?: THREE.Mesh;
  reel: number;
  /** Seconds until the next picture. */
  next: number;
  rng: () => number;
}

/** One letter board on a marquee: the building it hangs on, its text today and the material showing it. */
interface Board { b: Building; i: number; mesh: THREE.Mesh; mat: THREE.MeshBasicMaterial; text: string; aspect: number }

export class Screens {
  readonly root = new THREE.Group();
  private reels = new Reels();
  private byWorld = new Map<World, Screen[]>();
  private letters = new MarqueeTextures();
  private boards = new Map<World, { rev: number; list: Board[] }>();
  private day = Number.NaN;

  constructor(scene: THREE.Scene) {
    this.root.name = 'screens';
    scene.add(this.root);
  }

  /** Each frame: the counties in memory, the game clock in hours, and where the camera looks (world tiles). */
  update(dt: number, worlds: Iterable<World>, hour: number, focus: { x: number; z: number }): void {
    const live = new Set(worlds);
    for (const [w, list] of this.byWorld) if (!live.has(w)) { for (const s of list) this.drop(s); this.byWorld.delete(w); }
    for (const w of live) if (!this.byWorld.has(w)) this.byWorld.set(w, this.build(w));
    this.marquees(live, hour, focus);
    const h = ((hour % 24) + 24) % 24;
    const evening = h >= SHOW_FROM || h < SHOW_TO - 24;
    for (const list of this.byWorld.values()) {
      for (const s of list) {
        s.next -= dt;
        if (s.next <= 0) {
          s.reel = this.another(s.reel, s.rng);
          s.mat.map = this.reels.texture(s.reel);
          s.mat.needsUpdate = true;
          s.next = s.kind === 'drivein' ? FEATURE * (0.8 + s.rng() * 0.5) : BOARD_EVERY * (0.7 + s.rng() * 0.6);
        }
        const on = s.kind === 'board' || evening;
        const near = Math.hypot(s.mesh.position.x - focus.x, s.mesh.position.z - focus.z) < SHOW_R;
        s.mesh.visible = on && near;
        if (s.back) s.back.visible = s.mesh.visible;
        if (s.mesh.visible) this.reels.want(s.reel);
      }
    }
    this.reels.update(dt);
  }

  /**
   * The marquees: boards built for each county as it arrives (and again when its buildings change), the
   * day's bill put up when the day turns, and only the boards near the camera shown.
   */
  private marquees(live: Set<World>, hours: number, focus: { x: number; z: number }): void {
    const day = Math.floor(hours / 24), turned = day !== this.day;
    this.day = day;
    for (const [w, set] of this.boards) {
      if (live.has(w) && set.rev === w.revision) continue;
      // the county changed, but a town growing a house doesn't touch its picture palaces: the revision goes
      // up with every new building, and rebuilding (and redrawing) every board each time was a frame hitch
      if (live.has(w) && set.list.every((bd) => !bd.b.gone) && this.palaces(w) === set.list.length) { set.rev = w.revision; continue; }
      for (const bd of set.list) this.dropBoard(bd);
      this.boards.delete(w);
    }
    for (const w of live) if (!this.boards.has(w)) this.boards.set(w, { rev: w.revision, list: this.buildBoards(w, day) });
    const h = ((hours % 24) + 24) % 24;
    this.letters.light(h >= 18.5 || h < 6 ? 1 : h >= 17 ? (h - 17) / 1.5 : h < 7 ? 7 - h : 0);
    for (const [w, set] of this.boards) {
      const cell = `${w.cx},${w.cz}`;
      let bill: ReturnType<typeof marqueeBill> = null, of: Building | null = null;
      for (const bd of set.list) {
        if (turned) {
          if (of !== bd.b) { of = bd.b; bill = marqueeBill(bd.b, cell, day); }
          const text = bill?.[bd.i]?.text;
          if (text && text !== bd.text) {
            this.letters.give(bd.mat);
            bd.mat = this.letters.take(text, bd.aspect);
            bd.mesh.material = bd.mat;
            bd.text = text;
          }
        }
        const b = bd.b, p = bd.mesh.position;
        bd.mesh.visible = !b.gone && !b.derelict && builtShare(b) >= 1 && Math.hypot(p.x - focus.x, p.z - focus.z) < MARQUEE_R;
      }
    }
  }

  /** How many boards a county's cinemas and theatres carry now: compared with what is built to see if they changed. */
  private palaces(w: World): number {
    const day = this.day, cell = `${w.cx},${w.cz}`;
    let n = 0;
    for (const b of w.allBuildings) {
      if (b.gone || (b.kind !== 'cinema' && b.kind !== 'theatre' && b.kind !== 'chicagoTheatre')) continue;
      n += marqueeBill(b, cell, day)?.length ?? 0;
    }
    return n;
  }

  private buildBoards(w: World, day: number): Board[] {
    const out: Board[] = [];
    const cell = `${w.cx},${w.cz}`;
    for (const b of w.allBuildings) {
      if (b.gone || (b.kind !== 'cinema' && b.kind !== 'theatre' && b.kind !== 'chicagoTheatre')) continue;
      const bill = marqueeBill(b, cell, day);
      if (!bill) continue;
      bill.forEach(({ spot, text }, i) => {
        const aspect = spot.w / spot.h;
        const mat = this.letters.take(text, aspect);
        const mesh = new THREE.Mesh(new THREE.PlaneGeometry(spot.w, spot.h), mat);
        const at = boardPlace(b, spot);
        mesh.position.set(w.ox + at.x, b.level * STEP + spot.y, w.oz + at.z);
        mesh.rotation.y = at.yaw;
        mesh.visible = false;
        this.root.add(mesh);
        out.push({ b, i, mesh, mat, text, aspect });
      });
    }
    return out;
  }

  private dropBoard(bd: Board): void {
    this.root.remove(bd.mesh);
    bd.mesh.geometry.dispose();
    this.letters.give(bd.mat);
  }

  private another(cur: number, rng: () => number): number {
    const k = Math.floor(rng() * (REELS.length - 1));
    return k >= cur ? k + 1 : k;
  }

  private screen(kind: Screen['kind'], w: number, h: number, x: number, y: number, z: number, yaw: number, seed: number): Screen {
    const rng = mulberry32(seed);
    const reel = Math.floor(rng() * REELS.length);
    const mat = new THREE.MeshBasicMaterial({ map: this.reels.texture(reel), toneMapped: false, fog: false });
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat);
    mesh.position.set(x, y, z);
    mesh.rotation.y = yaw;
    mesh.visible = false;
    this.root.add(mesh);
    return { mesh, mat, kind, reel, next: 2 + rng() * (kind === 'board' ? BOARD_EVERY : FEATURE), rng };
  }

  private drop(s: Screen): void {
    if (s.back) { this.root.remove(s.back); s.back.geometry.dispose(); }
    this.root.remove(s.mesh);
    s.mesh.geometry.dispose();
    s.mat.dispose();
  }

  private build(w: World): Screen[] {
    const out: Screen[] = [];
    for (const b of w.allBuildings) if (b.kind === 'driveIn' && !b.gone && !b.derelict) out.push(this.driveIn(w, b));
    for (const t of w.towns) {
      if (t.kind !== 'mega' || !BILLBOARD_STYLES.has(t.style)) continue;
      out.push(...this.crossings(w, t.id, t.x0 + t.size / 2, t.z0 + t.size / 2, t.x0, t.z0, t.size));
    }
    return out;
  }

  /** The drive-in's picture, over the white panel of its screen (render/buildings/novelty.ts driveIn). */
  private driveIn(w: World, b: Building): Screen {
    const alongZ = b.facing % 2 === 1;
    const W = alongZ ? b.w : b.d, D = alongZ ? b.d : b.w;
    const sw = Math.min(W - 0.9, 4.6), sh = 1.15;
    const bz = -D / 2 + 0.3;
    const p = stadiumToIsland(b, 0, bz + 0.08);
    const f = stadiumFrame(b);
    // 16:9 inside the panel, centred on it
    const ph = sh - 0.16, pw = Math.min(sw - 0.16, ph * 16 / 9);
    const y = b.level * STEP + 0.22 + (sh - 0.14) / 2;
    const scr = this.screen('drivein', pw, ph, w.ox + p.x, y, w.oz + p.z, f.yaw, hashString(`drivein|${w.cx},${w.cz}|${b.uid}`));
    // the rest of the wide panel goes dark while the film runs, so the picture isn't flanked by glowing white
    const q = stadiumToIsland(b, 0, bz + 0.07);
    const back = new THREE.Mesh(new THREE.PlaneGeometry(sw - 0.1, sh - 0.1), BACK);
    back.position.set(w.ox + q.x, y, w.oz + q.z);
    back.rotation.y = f.yaw;
    back.visible = false;
    this.root.add(back);
    scr.back = back;
    return scr;
  }

  /**
   * The billboards at a megalopolis's crossings: the junctions nearest its middle, a screen on each face
   * of the tall corner buildings that looks onto the crossing.
   */
  private crossings(w: World, town: number, mx: number, mz: number, x0: number, z0: number, size: number): Screen[] {
    const juncs: { x: number; z: number; d: number }[] = [];
    for (let z = Math.max(1, z0); z < Math.min(N - 1, z0 + size); z++) {
      for (let x = Math.max(1, x0); x < Math.min(N - 1, x0 + size); x++) {
        const i = z * N + x;
        if (w.townId[i] !== town || w.roadAxis[i] !== 3 || w.roadCover[i] < 2) continue;
        juncs.push({ x, z, d: Math.hypot(x + 0.5 - mx, z + 0.5 - mz) });
      }
    }
    juncs.sort((a, b) => a.d - b.d);
    const picked: { x: number; z: number }[] = [];
    for (const j of juncs) {
      if (picked.length >= CROSSINGS) break;
      if (picked.some((p) => Math.hypot(p.x - j.x, p.z - j.z) < APART)) continue;
      picked.push(j);
    }
    const out: Screen[] = [];
    for (const j of picked) {
      for (const [dx, dz] of [[1, 1], [1, -1], [-1, 1], [-1, -1]]) {
        // out along the diagonal to the first tall building on that corner
        for (let s = 1; s <= 5; s++) {
          const tx = j.x + dx * s, tz = j.z + dz * s;
          if (tx < 0 || tz < 0 || tx >= N || tz >= N) break;
          const i = tz * N + tx;
          if (w.road[i]) continue;
          const ground = heightAt(w, tx + 0.5, tz + 0.5);
          const tall = w.roof[i] - ground;
          if (!(w.roof[i] > 0) || tall < TALL) break;
          const sh = Math.min(0.9, tall * 0.45), sw = sh * 16 / 9;
          const y = ground + Math.min(tall - sh / 2 - 0.15, 1.7);
          const seed = hashString(`board|${w.cx},${w.cz}|${tx},${tz}`);
          // the face looking back along x at the crossing, and the one looking back along z
          const fx = dx > 0 ? tx - 0.03 : tx + 1.03, fz = dz > 0 ? tz - 0.03 : tz + 1.03;
          out.push(this.screen('board', sw, sh, w.ox + fx, y, w.oz + tz + 0.5, Math.atan2(-dx, 0), seed));
          out.push(this.screen('board', sw, sh, w.ox + tx + 0.5, y, w.oz + fz, Math.atan2(0, -dz), seed ^ 0x5bd1));
          break;
        }
      }
    }
    return out;
  }

  dispose(): void {
    for (const list of this.byWorld.values()) for (const s of list) this.drop(s);
    this.byWorld.clear();
    for (const set of this.boards.values()) for (const bd of set.list) this.dropBoard(bd);
    this.boards.clear();
    this.letters.dispose();
    this.reels.dispose();
    this.root.removeFromParent();
  }
}
