/**
 * The 0.8.0 world's big complexes (world/complexes.ts), drawn from the same block plans their footprints are
 * (world/complexPlans.ts): each block by its type, then the open ground between.
 *
 * - **University campus**: the domed library at the head of the quad, lecture halls down its sides, halls of
 *   residence behind, a chapel, a clock tower and the student union by the gate; in one of four looks (collegiate
 *   gothic in grey stone, a Georgian yard in red brick and white cupolas, the Lawn's white rotunda and colonnades,
 *   or concrete and glass), diagonal paths across the quad, students on them
 * - **Zoological park**: the gate and ticket hall, a savanna paddock with giraffes, zebra and an elephant, a big
 *   cats' rock island behind its moat, a penguin pool, a primate island, an aviary under its mesh dome, the reptile
 *   house and a café, a looping path between them
 * - **Castle school**: a great hall with tall lit windows, long wings, a keep, spires of every height, a cloister
 *   court, a gatehouse and glasshouses
 * - **Baronial castle**: a Highland tower house of pink-grey harl, round turrets under cones, crow-stepped gables, a
 *   great round tower, a stable court and a terraced parterre down to the gate
 * - **Desert ksar**: a granary of vaulted cells stacked three high round its court with stairs up the outside, white
 *   domed houses, two pit courts sunk in the ground, a field of dew-catcher towers, the well and a market under awnings
 * - the air force base's **headquarters**, **jets on the line** and **helipads**
 */
import { hex, type RGB } from '../../world/biomes';
import { complexBlocks, type Block } from '../../world/complexPlans';
import type { Rng } from '../../world/rng';
import type { Building } from '../../world/tiles';
import { GLASS, METAL, TAU, WHITE, windowGlow, windowSched, type Draw, type Kit, type P3 } from './kit';

const LAWN = hex(0x7fb35e), PATH = hex(0xd8cfbb), STONE = hex(0xb7ae9f), SLATE = hex(0x4a5560);

/** Lit windows in a row along the front (+z) of a block, one row per height in `ys`. */
function frontWindows(k: Kit, b: Building, r: Rng, x: number, z: number, w: number, ys: number[], n: number, ww = 0.16, wh = 0.2): void {
  const s = windowSched(b.kind, r), g = windowGlow(b.kind, r);
  for (const y of ys) for (let i = 0; i < n; i++) k.pane(x + (n === 1 ? 0 : (i / (n - 1) - 0.5) * (w - 0.5)), y, z, ww, wh, 1, GLASS, s, g);
}

function people(k: Kit, r: Rng, x0: number, z0: number, w: number, d: number, n: number): void {
  const cols = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf28c38, 0xf4f2ec].map(hex);
  for (let i = 0; i < n; i++) {
    const x = x0 + (r() - 0.5) * w, z = z0 + (r() - 0.5) * d;
    k.box(x, 0.02, z, 0.08, 0.13, 0.06, cols[i % cols.length]);
    k.box(x, 0.15, z, 0.06, 0.06, 0.06, hex(0xe0b08a));
  }
}

// ---- the campus ---------------------------------------------------------------------------------------------------

interface CampusLook { wall: RGB; roof: RGB; trim: RGB; dome: RGB; pointed: boolean; glass: boolean }
const LOOKS: CampusLook[] = [
  { wall: hex(0xb3aa98), roof: SLATE, trim: hex(0x8f8676), dome: hex(0x6f7f6f), pointed: true, glass: false },     // collegiate gothic
  { wall: hex(0xa4553e), roof: hex(0x4d5862), trim: WHITE, dome: hex(0x4f8a6a), pointed: false, glass: false },    // Georgian yard
  { wall: hex(0xb24d3a), roof: hex(0x3e4a52), trim: WHITE, dome: WHITE, pointed: false, glass: false },            // the Lawn
  { wall: hex(0xd8d4cc), roof: hex(0x6a7078), trim: hex(0x2f3438), dome: hex(0x9fb4bf), pointed: false, glass: true }, // modern
];

const campus: Draw = (k, W, D, b, r) => {
  const look = LOOKS[b.seed % LOOKS.length];
  k.box(0, 0, 0, W - 0.1, 0.012, D - 0.1, LAWN);
  for (const bl of complexBlocks('campus')) {
    const { x, z, w, d, h } = bl;
    switch (bl.type) {
      case 'quad': {
        // diagonal paths corner to corner, a path round, a fountain where they cross, students crossing
        for (const s of [-1, 1]) k.bar([x - w / 2, 0.016, z - s * d / 2], [x + w / 2, 0.016, z + s * d / 2], 0.18, PATH);
        k.box(x, 0.014, z + d / 2 + 0.3, w + 0.6, 0.006, 0.3, PATH);
        k.box(x, 0.014, z + d / 2 + 2.0, 1.0, 0.006, 3.4, PATH);
        k.cyl(x, 0.02, z, 0.45, 0.08, STONE, 14);
        k.cyl(x, 0.1, z, 0.06, 0.3, STONE, 6);
        people(k, r, x, z, w, d, 14);
        break;
      }
      case 'library': {
        k.box(x, 0, z, w, h * 0.6, d, look.wall);
        if (look.glass) k.box(x, h * 0.6, z, w - 0.2, h * 0.3, d - 0.2, hex(0x9fc0d0));
        else {
          // the dome over the reading room, a portico of columns out front
          k.cyl(x, h * 0.6, z, 1.05, 0.25, look.trim, 16);
          k.dome(x, h * 0.6 + 0.25, z, 1.05, look.dome, 16, 5);
          for (let i = 0; i < 6; i++) k.cyl(x - 1.25 + i * 0.5, 0, z + d / 2 + 0.3, 0.06, h * 0.55, look.trim, 8);
          k.box(x, h * 0.55, z + d / 2 + 0.3, 3.0, 0.08, 0.7, look.trim);
          k.gable(x, h * 0.55 + 0.08, z + d / 2 + 0.3, 3.0, 0.32, 0.7, look.roof, look.trim);
        }
        frontWindows(k, b, r, x, z + d / 2 + 0.005, w, [0.2], 6);
        break;
      }
      case 'hall': case 'dorm': {
        k.box(x, 0, z, w, h, d, look.wall);
        if (look.glass) k.box(x, h, z, w + 0.06, 0.05, d + 0.06, look.trim);
        else k.gable(x, h, z, w + 0.06, look.pointed ? 0.6 : 0.4, d + 0.06, look.roof, look.wall, bl.type === 'hall');
        // windows on the side facing the quad
        const s = windowSched(b.kind, r), g = windowGlow(b.kind, r);
        const face = bl.type === 'hall' ? (x < 0 ? 0 : 2) : 1;
        const n = bl.type === 'hall' ? 7 : 5, len = bl.type === 'hall' ? d : w;
        for (const y of [0.18, 0.62]) for (let i = 0; i < n; i++) {
          const t = (i / (n - 1) - 0.5) * (len - 0.6);
          if (face === 1) k.pane(x + t, y, z + d / 2 + 0.005, 0.16, 0.2, 1, GLASS, s, g);
          else k.pane(x + (face === 0 ? w / 2 + 0.005 : -w / 2 - 0.005), y, z + t, 0.16, 0.2, face, GLASS, s, g);
        }
        if (!look.glass && look.trim === WHITE && bl.type === 'hall') { k.cyl(x, h + 0.35, z, 0.2, 0.3, WHITE, 8); k.cone(x, h + 0.65, z, 0.24, 0.3, look.dome, 8); }
        break;
      }
      case 'chapel': {
        k.box(x, 0, z, w * 0.6, h, d, look.wall);
        k.gable(x, h, z, w * 0.6 + 0.06, 0.6, d + 0.06, look.roof, look.wall, true);
        k.box(x, 0, z + d / 2 - 0.2, 0.6, h + 0.7, 0.6, look.wall);
        if (look.pointed || !look.glass) k.cone(x, h + 0.7, z + d / 2 - 0.2, 0.42, 0.8, look.roof, 4);
        frontWindows(k, b, r, x, z + d / 2 + 0.105, 0.5, [0.25], 1, 0.18, 0.4);
        break;
      }
      case 'tower': {
        // the clock tower: a tall shaft, the clock faces, a lantern and a spire or cupola on top
        k.box(x, 0, z, w * 0.8, h, d * 0.8, look.wall);
        for (const [fx, fz] of [[0, 1], [1, 0], [0, -1], [-1, 0]]) k.disc(x + fx * (w * 0.4 + 0.005), h - 0.45, z + fz * (d * 0.4 + 0.005), 0.26, WHITE, 12, 0.26);
        k.box(x, h, z, w * 0.9, 0.08, d * 0.9, look.trim);
        if (look.pointed) k.cone(x, h + 0.08, z, w * 0.55, 1.0, look.roof, 4);
        else { k.cyl(x, h + 0.08, z, 0.32, 0.3, look.trim, 8); k.dome(x, h + 0.38, z, 0.32, look.dome, 8, 3); }
        break;
      }
      case 'union': {
        k.box(x, 0, z, w, h, d, look.glass ? hex(0xb8c6cc) : look.wall);
        k.box(x, h, z, w + 0.2, 0.06, d + 0.2, look.trim);
        frontWindows(k, b, r, x, z + d / 2 + 0.005, w, [0.2], 4, 0.3, 0.3);
        break;
      }
    }
  }
  // the gate on the drive in, the university's crest over it
  for (const s of [-1, 1]) k.box(s * 0.7, 0, D / 2 - 0.2, 0.22, 0.6, 0.22, look.wall);
  k.box(0, 0.5, D / 2 - 0.2, 1.62, 0.16, 0.16, look.wall);
  k.box(0, 0.3, D / 2 - 0.1, 0.3, 0.3, 0.02, hex(0x2f4d7a));
};

// ---- the zoo ------------------------------------------------------------------------------------------------------

function animal(k: Kit, kind: string, x: number, z: number, yaw: number): void {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  const at = (a: number, y: number): P3 => [x + s * a, y, z + c * a];
  switch (kind) {
    case 'giraffe':
      k.box(x, 0, z, 0.06, 0.28, 0.06, hex(0xd9a441));
      k.bar(at(0, 0.32), at(0.12, 0.62), 0.05, hex(0xd9a441));
      k.box(...at(0.15, 0.64), 0.07, 0.06, 0.1, hex(0xc8902f));
      k.box(...at(-0.05, 0.3), 0.12, 0.1, 0.22, hex(0xd9a441));
      break;
    case 'zebra': k.box(...at(0, 0.12), 0.08, 0.1, 0.2, hex(0xf4f2ec)); k.box(...at(0.12, 0.2), 0.05, 0.07, 0.07, hex(0x2a2a2a)); break;
    case 'elephant': k.box(...at(0, 0.1), 0.24, 0.24, 0.36, hex(0x8a8a88)); k.box(...at(0.22, 0.26), 0.16, 0.16, 0.12, hex(0x8a8a88)); k.bar(at(0.28, 0.2), at(0.32, 0.02), 0.035, hex(0x8a8a88)); break;
    case 'lion': k.box(...at(0, 0.08), 0.1, 0.1, 0.24, hex(0xc89a4a)); k.box(...at(0.14, 0.14), 0.12, 0.12, 0.1, hex(0x8a5a2a)); break;
    case 'penguin': k.box(x, 0.02, z, 0.05, 0.1, 0.04, hex(0x1f2328)); k.box(x, 0.04, z + 0.022, 0.035, 0.06, 0.005, WHITE); break;
    case 'monkey': k.box(x, 0.3, z, 0.05, 0.07, 0.05, hex(0x6a4a2a)); break;
  }
}

const zooPark: Draw = (k, W, D, _b, r) => {
  const WALL = hex(0xc9b896), FENCE = hex(0x5a4a3a), WATER = hex(0x5aa8c8);
  k.box(0, 0, 0, W - 0.1, 0.012, D - 0.1, LAWN);
  for (const bl of complexBlocks('zooPark')) {
    const { x, z, w, d } = bl;
    switch (bl.type) {
      case 'paths': {
        // the loop round the park, from the gate and back
        const pts: [number, number][] = [[0, 4.4], [-1.6, 2.4], [-1.0, -4.2], [2.0, -5.6], [1.8, -0.9], [2.1, 3.4], [0, 4.4]];
        for (let i = 0; i + 1 < pts.length; i++) k.bar([pts[i][0], 0.015, pts[i][1]], [pts[i + 1][0], 0.015, pts[i + 1][1]], 0.5, PATH);
        people(k, r, 0, 0, 3, 9, 16);
        break;
      }
      case 'zooGate': {
        k.box(x, 0, z, w, 0.55, d, hex(0xe6dcc4));
        k.gable(x, 0.55, z, w + 0.1, 0.3, d + 0.1, hex(0x3f7a3c), hex(0xe6dcc4));
        k.box(x, 0, z + d / 2 + 0.01, 0.8, 0.4, 0.02, hex(0x3a3f45));
        k.box(x, 0.62, z + d / 2 + 0.06, 1.6, 0.18, 0.04, hex(0xf2c14e));
        break;
      }
      case 'savanna': {
        k.box(x, 0.012, z, w, 0.01, d, hex(0xcab673));
        for (const [a, b2] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) k.box(x + a * w / 2, 0, z + b2 * d / 2, a ? 0.05 : w, 0.22, b2 ? 0.05 : d, FENCE);
        k.cyl(x + 1.4, 0, z - 1.6, 0.05, 0.4, hex(0x6a5038), 5);
        k.cyl(x + 1.4, 0.38, z - 1.6, 0.5, 0.08, hex(0x6f9a3c), 10);
        k.cyl(x - 1.6, 0.012, z + 1.6, 0.6, 0.01, WATER, 12);
        animal(k, 'giraffe', x - 1.2, z - 1.0, 0.4); animal(k, 'giraffe', x + 0.4, z - 1.8, 2.2);
        for (let i = 0; i < 4; i++) animal(k, 'zebra', x - 0.6 + i * 0.4, z + 1.0 + (i % 2) * 0.3, 1.2 + i);
        animal(k, 'elephant', x + 1.4, z + 1.4, 3.6);
        break;
      }
      case 'rocks': {
        // the big cats' island: rocks behind a dry moat, a ledge to lie on
        k.cyl(x, 0, z, w * 0.5, 0.06, hex(0x8a7a6a), 14, hex(0x8a7a6a), d * 0.5);
        k.cyl(x, 0.06, z, w * 0.38, 0.4, hex(0xb59a7a), 9, hex(0xc4ab8a), d * 0.36);
        k.cyl(x - 0.4, 0.46, z - 0.2, 0.6, 0.3, hex(0xa88d6c), 7);
        animal(k, 'lion', x + 0.6, z + 0.5, 1.0); animal(k, 'lion', x - 0.5, z - 0.1, -0.5);
        k.box(x, 0, z + d / 2, w * 0.8, 0.25, 0.06, WALL);
        break;
      }
      case 'penguins': {
        k.box(x, 0.01, z, w, 0.03, d, hex(0xe8eef2));
        k.box(x + 0.4, 0.02, z, w * 0.55, 0.012, d * 0.7, WATER);
        for (let i = 0; i < 6; i++) animal(k, 'penguin', x - 1.2 + (i % 3) * 0.22, z - 0.6 + Math.floor(i / 3) * 0.4, 0);
        k.box(x, 0, z + d / 2, w, 0.2, 0.05, hex(0x9fb4bf));
        break;
      }
      case 'primates': {
        // an island in a pond, climbing frames and a rope bridge, monkeys up them
        k.cyl(x, 0.012, z, w * 0.5, 0.01, WATER, 14);
        k.cyl(x, 0.015, z, w * 0.32, 0.06, hex(0x6f9a3c), 12);
        for (const [a, b2] of [[-0.3, -0.2], [0.35, 0.25]]) { k.cyl(x + a, 0.06, z + b2, 0.03, 0.45, hex(0x6a5038), 5); animal(k, 'monkey', x + a, z + b2, 0); }
        k.bar([x - 0.3, 0.46, z - 0.2], [x + 0.35, 0.46, z + 0.25], 0.015, hex(0xc8a878));
        break;
      }
      case 'aviary': {
        k.cyl(x, 0, z, w * 0.45, 0.04, hex(0x8a7a6a), 12);
        for (let i = 0; i < 8; i++) {
          const a = (i / 8) * TAU;
          k.bar([x + Math.cos(a) * w * 0.45, 0, z + Math.sin(a) * w * 0.45], [x, 1.2, z], 0.02, METAL);
        }
        k.hoop(x, 0.5, z, w * 0.4, 0.015, METAL, 16, 'xz');
        for (let i = 0; i < 5; i++) k.box(x + (r() - 0.5), 0.3 + r() * 0.6, z + (r() - 0.5), 0.05, 0.03, 0.04, [hex(0xe2412f), hex(0x2f7fb5), hex(0xf2c14e)][i % 3]);
        break;
      }
      case 'reptiles': case 'cafe': {
        k.box(x, 0, z, w, bl.h, d, bl.type === 'reptiles' ? hex(0x6f8a5a) : hex(0xf2e6d0));
        k.box(x, bl.h, z, w + 0.12, 0.06, d + 0.12, bl.type === 'reptiles' ? hex(0x3f5a3a) : hex(0xd8342a));
        if (bl.type === 'cafe') for (let i = 0; i < 3; i++) { k.cyl(x - 0.7 + i * 0.7, 0, z + d / 2 + 0.4, 0.015, 0.3, WHITE, 4); k.cone(x - 0.7 + i * 0.7, 0.3, z + d / 2 + 0.4, 0.28, 0.1, hex(0xf2c14e), 8); }
        break;
      }
    }
  }
};

// ---- the castles --------------------------------------------------------------------------------------------------

function crenels(k: Kit, x: number, y: number, z: number, w: number, d: number, col: RGB): void {
  const n = Math.max(2, Math.round(w / 0.3)), m = Math.max(2, Math.round(d / 0.3));
  for (let i = 0; i < n; i += 2) for (const s of [-1, 1]) k.box(x - w / 2 + (i + 0.5) * (w / n), y, z + s * d / 2, w / n, 0.12, 0.08, col);
  for (let i = 0; i < m; i += 2) for (const s of [-1, 1]) k.box(x + s * w / 2, y, z - d / 2 + (i + 0.5) * (d / m), 0.08, 0.12, d / m, col);
}

const schoolCastle: Draw = (k, W, D, b, r) => {
  const WALLS = hex(0x9e968a), ROOF = hex(0x3e4650), DARK = hex(0x5a544c);
  k.box(0, 0, 0, W - 0.1, 0.012, D - 0.1, hex(0x7a9a5a));
  const s = windowSched(b.kind, r), g = windowGlow(b.kind, r);
  for (const bl of complexBlocks('schoolCastle')) {
    const { x, z, w, d, h } = bl;
    switch (bl.type) {
      case 'greatHall': {
        k.box(x, 0, z, w, h, d, WALLS);
        k.gable(x, h, z, w + 0.1, 1.1, d + 0.1, ROOF, WALLS);
        // the tall windows of the hall, lit for supper
        for (let i = 0; i < 6; i++) k.pane(x - w / 2 + 0.6 + i * ((w - 1.2) / 5), 0.4, z + d / 2 + 0.005, 0.24, 1.2, 1, GLASS, [16, 23.5, 3.2], hex(0xffc978));
        break;
      }
      case 'wing': case 'keep': case 'gatehouse': {
        k.box(x, 0, z, w, h, d, WALLS);
        crenels(k, x, h, z, w, d, WALLS);
        if (bl.type === 'wing') {
          k.gable(x, h, z, w - 0.3, 0.7, d - 0.3, ROOF, WALLS, true);
          for (let i = 0; i < 8; i++) for (const y of [0.3, 0.9]) k.pane(x + (x < 0 ? w / 2 : -w / 2) * 1.002, y, z - d / 2 + 0.6 + i * ((d - 1.2) / 7), 0.12, 0.26, x < 0 ? 0 : 2, GLASS, s, g);
        }
        if (bl.type === 'gatehouse') { k.box(x, 0, z + d / 2 + 0.01, 1.0, 0.9, 0.02, DARK); for (const sx of [-1, 1]) { k.cyl(x + sx * w / 2, 0, z, 0.45, h + 0.4, WALLS, 10); k.cone(x + sx * w / 2, h + 0.4, z, 0.5, 0.9, ROOF, 10); } }
        break;
      }
      case 'spire': {
        k.cyl(x, 0, z, w * 0.5, h, WALLS, 10);
        k.cone(x, h, z, w * 0.62, h * 0.45, ROOF, 10);
        k.cyl(x, h + h * 0.45, z, 0.015, 0.3, METAL, 4);
        for (let i = 0; i < 3; i++) k.pane(x, 0.6 + i * (h - 1) / 3, z + w * 0.5 + 0.005, 0.1, 0.18, 1, GLASS, s, g);
        break;
      }
      case 'cloister': {
        // the court: a lawn with a path round it under an arcade, a fountain in the middle
        k.box(x, 0.014, z, w - 0.6, 0.006, d - 0.6, hex(0x86b862));
        for (let i = 0; i <= 10; i++) for (const sz of [-1, 1]) k.cyl(x - w / 2 + 0.3 + i * ((w - 0.6) / 10), 0, z + sz * (d / 2 - 0.3), 0.05, 0.55, WALLS, 6);
        for (const sz of [-1, 1]) k.box(x, 0.55, z + sz * (d / 2 - 0.3), w - 0.4, 0.1, 0.5, ROOF);
        k.cyl(x, 0.02, z, 0.5, 0.12, WALLS, 12);
        k.cyl(x, 0.14, z, 0.08, 0.35, WALLS, 6);
        people(k, r, x, z, w - 2, d - 2, 12);
        break;
      }
      case 'glasshouse': {
        k.box(x, 0, z, w, 0.1, d, WALLS);
        k.gable(x, 0.1, z, w, 0.42, d, hex(0xbfe0e8), hex(0xbfe0e8));
        break;
      }
    }
  }
};

const baronialCastle: Draw = (k, W, D, b, r) => {
  const HARL = hex(0xd8bfae), ROOF = hex(0x45505a), TRIM = hex(0xa89480), HEDGE = hex(0x3f7a3c);
  k.box(0, 0, 0, W - 0.1, 0.012, D - 0.1, LAWN);
  const s = windowSched(b.kind, r), g = windowGlow(b.kind, r);
  for (const bl of complexBlocks('baronialCastle')) {
    const { x, z, w, d, h } = bl;
    switch (bl.type) {
      case 'towerHouse': {
        k.box(x, 0, z, w, h, d, HARL);
        k.gable(x, h, z, w - 0.1, 0.9, d - 0.2, ROOF, HARL);
        // crow-stepped gables at each end, and dormers
        for (const sx of [-1, 1]) for (let i = 0; i < 4; i++) k.box(x + sx * (w / 2 - 0.05), h + i * 0.22, z, 0.12, 0.22, d - 0.3 - i * 0.62, TRIM);
        for (let i = 0; i < 3; i++) { k.box(x - 1.6 + i * 1.6, h + 0.2, z + d / 2 - 0.25, 0.4, 0.36, 0.3, HARL); k.gable(x - 1.6 + i * 1.6, h + 0.56, z + d / 2 - 0.25, 0.44, 0.2, 0.34, ROOF, HARL, true); }
        for (const y of [0.3, 0.95]) for (let i = 0; i < 6; i++) k.pane(x - w / 2 + 0.6 + i * ((w - 1.2) / 5), y, z + d / 2 + 0.005, 0.18, 0.3, 1, GLASS, s, g);
        k.box(x, 0, z + d / 2 + 0.01, 0.5, 0.6, 0.02, hex(0x4a3a2e));
        break;
      }
      case 'turret': case 'bigTower': {
        const R = w / 2, base = bl.type === 'turret' ? 0.9 : 0;
        if (bl.type === 'turret') { k.box(x, 0, z, 0.2, base, 0.2, HARL); k.cone(x, base - 0.25, z, R, 0.25, HARL, 10); }
        k.cyl(x, base, z, R, h - base, HARL, 12);
        k.cone(x, h, z, R * 1.15, bl.type === 'turret' ? 0.9 : 1.2, ROOF, 12);
        k.cyl(x, h + (bl.type === 'turret' ? 0.9 : 1.2), z, 0.012, 0.25, METAL, 4);
        k.pane(x, h - 0.6, z + R + 0.005, 0.12, 0.24, 1, GLASS, s, g);
        break;
      }
      case 'stable': {
        k.box(x, 0, z, w, h, d, HARL);
        k.gable(x, h, z, w + 0.06, 0.4, d + 0.06, ROOF, HARL, true);
        for (let i = 0; i < 3; i++) k.box(x + w / 2 + 0.005, 0.05, z - 0.9 + i * 0.9, 0.01, 0.42, 0.4, hex(0x5a4030));
        break;
      }
      case 'parterre': {
        // terraces down to the gate: low box hedges in a pattern round a sundial, gravel walks, a fire bowl lit at night
        k.box(x, 0.014, z, 1.0, 0.006, d, PATH);
        k.box(x, 0.014, z - d / 2 + 0.3, w, 0.006, 0.4, PATH);
        for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
          const cx = x + sx * w / 4, cz = z + sz * d / 4;
          k.box(cx, 0, cz, w / 2 - 1.0, 0.1, 0.08, HEDGE);
          k.box(cx, 0, cz + sz * 0.6, w / 2 - 1.0, 0.1, 0.08, HEDGE);
          k.cyl(cx, 0, cz + sz * 0.3, 0.3, 0.1, HEDGE, 10);
        }
        k.cyl(x, 0, z, 0.12, 0.3, STONE, 8);
        k.cyl(x + 1.2, 0, z + 1.6, 0.12, 0.18, hex(0x3a3f45), 8);
        k.glowBox(x + 1.2, 0.18, z + 1.6, 0.1, 0.08, 0.1, hex(0xf28c38), [17, 24, 2], hex(0xffa040));
        for (const sx of [-1, 1]) k.box(x + sx * 0.75, 0, D / 2 - 0.2, 0.2, 0.7, 0.2, TRIM);
        break;
      }
    }
  }
};

// ---- the ksar -----------------------------------------------------------------------------------------------------

const ksarVillage: Draw = (k, W, D, b, r) => {
  const MUD = hex(0xd6b07c), MUD2 = hex(0xc49a64), LIME = hex(0xf3efe6), AWNING = hex(0xc8502e);
  k.box(0, 0, 0, W - 0.1, 0.012, D - 0.1, hex(0xe3c88e));
  const s = windowSched(b.kind, r), g = windowGlow(b.kind, r);
  for (const bl of complexBlocks('ksarVillage')) {
    const { x, z, w, d, h } = bl;
    switch (bl.type) {
      case 'granary': {
        // vaulted cells stacked three high round three sides of a court, stairs climbing their faces
        const cells = 9, cw = w / cells;
        for (let tier = 0; tier < 3; tier++) for (let i = 0; i < cells; i++) {
          const cx = x - w / 2 + cw * (i + 0.5), y = tier * (h / 3);
          k.box(cx, y, z, cw - 0.04, h / 3 - 0.03, d * 0.45, tier % 2 ? MUD : MUD2);
          k.cyl(cx, y + h / 3 - 0.05, z, cw * 0.48, d * 0.45, tier % 2 ? MUD : MUD2, 8);
          k.box(cx, y + 0.06, z + d * 0.225 + 0.005, cw * 0.4, h / 6, 0.01, hex(0x5a3e2a));
        }
        for (let i = 0; i < 3; i++) k.wedge(x - w / 2 + 1 + i * 2.5, 0, z + d * 0.3, 0.25, h * 0.66, 0.5, MUD2);
        break;
      }
      case 'dome': {
        // a whitewashed house under its dome, half sunk in the sand
        k.box(x, 0, z, w * 0.7, 0.32, d * 0.7, LIME);
        k.dome(x, 0.32, z, w * 0.36, LIME, 10, 4);
        k.box(x, 0, z + d * 0.35 + 0.005, 0.18, 0.24, 0.01, hex(0x2f6fa8));
        k.pane(x + 0.22, 0.14, z + d * 0.35 + 0.006, 0.08, 0.08, 1, GLASS, s, g);
        break;
      }
      case 'pit': {
        // a pit court: a round courtyard dug into the ground, rooms opening off it, a ladder down
        k.cyl(x, 0, z, w * 0.5, 0.15, MUD2, 16);
        k.cyl(x, 0.12, z, w * 0.38, 0.04, hex(0x8a6a48), 16);
        for (let i = 0; i < 5; i++) { const a = (i / 5) * TAU; k.box(x + Math.cos(a) * w * 0.36, 0.12, z + Math.sin(a) * w * 0.36, 0.14, 0.03, 0.14, hex(0x3a2a1e)); }
        k.bar([x + w * 0.42, 0.15, z], [x + w * 0.3, 0.02, z], 0.03, hex(0x6a5038));
        break;
      }
      case 'dew': {
        // dew-catchers: tall lattice towers hung with mesh, a row of them on the edge of the village
        for (let i = 0; i < 3; i++) {
          const tx = x - w / 2 + 0.4 + i * (w - 0.8) / 2;
          for (const [a, c] of [[-0.12, -0.12], [0.12, -0.12], [0, 0.14]]) k.bar([tx + a, 0, z + c], [tx, h, z], 0.025, hex(0x8a7a5a));
          k.cone(tx, h * 0.45, z, 0.22, h * 0.45, hex(0xe8e2d0), 6);
          k.cyl(tx, 0, z, 0.15, 0.1, hex(0x9a9286), 8);
        }
        break;
      }
      case 'well': {
        k.cyl(x, 0, z, 0.32, 0.22, MUD, 10);
        k.cyl(x, 0.2, z, 0.24, 0.02, hex(0x3a5a6a), 10);
        for (const sx of [-1, 1]) k.box(x + sx * 0.3, 0.2, z, 0.05, 0.4, 0.05, hex(0x6a5038));
        k.box(x, 0.6, z, 0.66, 0.05, 0.05, hex(0x6a5038));
        break;
      }
      case 'market': {
        for (let i = 0; i < 4; i++) {
          const mx = x - w / 2 + 0.45 + i * (w - 0.9) / 3;
          for (const sx of [-1, 1]) k.box(mx + sx * 0.32, 0, z, 0.03, h, 0.03, hex(0x6a5038));
          k.box(mx, h, z, 0.78, 0.03, d, i % 2 ? AWNING : hex(0xe8d8a0));
          k.box(mx, 0.12, z, 0.6, 0.08, d * 0.6, [hex(0xd8342a), hex(0xf2c14e), hex(0x3f9b4a), hex(0xf28c38)][i]);
        }
        break;
      }
      case 'square': people(k, r, x, z, w, d, 10); break;
    }
  }
};

