import * as THREE from 'three';
import type { FollowCamera } from '../game/camera';
import type { Sfx } from '../game/sfx';
import type { Impact, VehicleState } from '../game/vehicles';

/**
 * What a collision looks, sounds and feels like. Each knock is answered all at once and scaled by
 * how hard it was: sparks off a wall, dust off a curb, splinters or stones off a fence; a jolt of
 * the camera toward the obstacle; a knock, a thump or a crack; a buzz in a gamepad; and, for the
 * hardest hits only, a few hundredths of a second of hitstop, so the big ones land and the small
 * ones stay out of the way. A car grinding along a wall throws a stream of sparks and rasps.
 */

const SPARKS = 200;
const BITS = 160;

const VERT = /* glsl */ `
attribute float aSize;
attribute float aAlpha;
attribute vec3 aColor;
uniform float uScale;
varying float vAlpha;
varying vec3 vColor;
void main() {
  vAlpha = aAlpha;
  vColor = aColor;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = aAlpha > 0.0 ? max(2.0, aSize * uScale / -mv.z) : 0.0;
}`;
const FRAG = /* glsl */ `
varying float vAlpha;
varying vec3 vColor;
void main() {
  vec2 c = gl_PointCoord - 0.5;
  if (dot(c, c) > 0.25) discard;
  gl_FragColor = vec4(vColor, vAlpha);
}`;

/** A pool of short-lived points: position, velocity, life, colour, size and how hard gravity pulls. */
class Pool {
  readonly points: THREE.Points;
  private pos: Float32Array;
  private col: Float32Array;
  private size: Float32Array;
  private alpha: Float32Array;
  private vel: Float32Array;
  private life: Float32Array;
  private age: Float32Array;
  private grav: Float32Array;
  private base: Float32Array;
  private next = 0;
  private live = 0;

  constructor(private max: number, additive: boolean) {
    this.pos = new Float32Array(max * 3);
    this.col = new Float32Array(max * 3);
    this.base = new Float32Array(max * 3);
    this.size = new Float32Array(max);
    this.alpha = new Float32Array(max);
    this.vel = new Float32Array(max * 3);
    this.life = new Float32Array(max);
    this.age = new Float32Array(max);
    this.grav = new Float32Array(max);
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(this.pos, 3).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    g.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1).setUsage(THREE.DynamicDrawUsage));
    const m = new THREE.ShaderMaterial({
      vertexShader: VERT, fragmentShader: FRAG, uniforms: { uScale: { value: 400 } },
      transparent: true, depthWrite: false, blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
    });
    this.points = new THREE.Points(g, m);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    // points are sized in tiles: the pixels a tile covers at unit distance, read off the camera and the canvas
    this.points.onBeforeRender = (renderer, _scene, camera) => {
      const cam = camera as THREE.PerspectiveCamera;
      const h = renderer.getContext().drawingBufferHeight;
      m.uniforms.uScale.value = (h * 0.5) / Math.tan(THREE.MathUtils.degToRad((cam.fov ?? 18) / 2));
    };
  }

  spawn(x: number, y: number, z: number, vx: number, vy: number, vz: number, life: number, r: number, g: number, b: number, size: number, grav: number): void {
    const k = this.next;
    this.next = (this.next + 1) % this.max;
    this.pos.set([x, y, z], k * 3);
    this.vel.set([vx, vy, vz], k * 3);
    this.base.set([r, g, b], k * 3);
    this.col.set([r, g, b], k * 3);
    this.life[k] = life;
    this.age[k] = 0;
    this.size[k] = size;
    this.alpha[k] = 1;
    this.grav[k] = grav;
    this.live = this.max;
    (this.points.geometry.getAttribute('aSize') as THREE.BufferAttribute).needsUpdate = true;
  }

  /** `floorY` is roughly where the ground is, so bits bounce once and settle rather than fall forever. */
  update(dt: number, floorY: number, fade: boolean): void {
    if (!this.live || dt <= 0) return;
    let any = 0;
    for (let k = 0; k < this.max; k++) {
      if (this.alpha[k] <= 0) continue;
      this.age[k] += dt;
      const t = this.age[k] / this.life[k];
      if (t >= 1) { this.alpha[k] = 0; continue; }
      any++;
      const j = k * 3;
      this.vel[j + 1] -= this.grav[k] * dt;
      // air drag, stronger on dust than on sparks and splinters
      const drag = Math.max(0, 1 - dt * (this.grav[k] < 1 ? 3 : 0.8));
      this.vel[j] *= drag;
      this.vel[j + 2] *= drag;
      this.pos[j] += this.vel[j] * dt;
      this.pos[j + 1] += this.vel[j + 1] * dt;
      this.pos[j + 2] += this.vel[j + 2] * dt;
      if (this.pos[j + 1] < floorY && this.vel[j + 1] < 0) {
        this.pos[j + 1] = floorY;
        this.vel[j + 1] *= -0.3;
        this.vel[j] *= 0.5;
        this.vel[j + 2] *= 0.5;
      }
      if (fade) {
        // sparks cool from white-hot through orange as they die (additive: darker is fainter)
        const heat = 1 - t;
        this.col[j] = this.base[j] * heat;
        this.col[j + 1] = this.base[j + 1] * heat * heat;
        this.col[j + 2] = this.base[j + 2] * heat * heat * heat;
      } else {
        this.alpha[k] = t < 0.7 ? 1 : 1 - (t - 0.7) / 0.3;
      }
    }
    this.live = any;
    const g = this.points.geometry;
    (g.getAttribute('position') as THREE.BufferAttribute).needsUpdate = true;
    (g.getAttribute('aColor') as THREE.BufferAttribute).needsUpdate = true;
    (g.getAttribute('aAlpha') as THREE.BufferAttribute).needsUpdate = true;
  }
}

const rnd = (a: number, b: number) => a + Math.random() * (b - a);

/** A gamepad's rumble motor, where the browser offers one. */
interface Actuator { playEffect?: (type: string, p: Record<string, number>) => Promise<unknown> }

export class ImpactFx {
  private sparks = new Pool(SPARKS, true);
  private bits = new Pool(BITS, false);
  /** Real seconds of hitstop left. */
  private stop = 0;
  private sparkDebt = 0;
  private rumbleWait = 0;
  private lastY = 0;

  constructor(parent: THREE.Object3D, private cam: FollowCamera, private sfx: Sfx) {
    parent.add(this.sparks.points, this.bits.points);
  }

  /**
   * Nitrous burning out of the back of vehicle `s` (half length `hl`): a stream of blue-white flame
   * thrown back from the tail, the sparks' pool in a cold tint.
   */
  flame(s: VehicleState, hl: number, dt: number): void {
    const fx = Math.sin(s.heading), fz = Math.cos(s.heading);
    const n = Math.min(12, Math.round(220 * dt + Math.random()));
    for (let k = 0; k < n; k++) {
      const back = rnd(1.2, 2.6);
      this.sparks.spawn(
        s.x - fx * hl * 1.05 + rnd(-0.02, 0.02), s.y + rnd(0.05, 0.1), s.z - fz * hl * 1.05 + rnd(-0.02, 0.02),
        -fx * back + rnd(-0.2, 0.2) + fx * s.v, rnd(0, 0.35), -fz * back + rnd(-0.2, 0.2) + fz * s.v,
        rnd(0.1, 0.22), 0.45, 0.7, 1, rnd(0.05, 0.09), 0,
      );
    }
  }

  /** How fast the world runs this frame: nearly frozen during hitstop. */
  get timeScale(): number { return this.stop > 0 ? 0.06 : 1; }

  /**
   * Answer one collision of vehicle `s` (half length `hl`), in its island's tile coordinates. The
   * vehicle's centre stops on the obstacle's face, so its nose is what shows touching: that's where
   * the sparks and the dust come from, not the middle of the body.
   */
  hit(imp: Impact, s: VehicleState, hl: number): void {
    const str = imp.strength;
    const y = s.y + 0.14;
    const { nx, nz } = imp;
    const dir = Math.sign(s.v) || 1;
    const nose = imp.kind === 'break' ? 0 : hl * 0.85;
    const px = imp.px + Math.sin(s.heading) * dir * nose * (s.v === 0 ? 0 : 1), pz = imp.pz + Math.cos(s.heading) * dir * nose * (s.v === 0 ? 0 : 1);
    this.lastY = s.y;
    if (imp.kind === 'hard') {
      this.cam.kick(-nx, -nz, str);
      this.sfx.knock(str);
      this.rumble(0.25 + 0.75 * str, 0.4 + 0.5 * str, 90 + 160 * str);
      // the big ones land: a beat of hitstop, longer the harder the hit
      if (str > 0.45) this.stop = Math.max(this.stop, 0.03 + 0.07 * (str - 0.45) / 0.55);
      const n = Math.round(8 + 26 * str);
      for (let k = 0; k < n; k++) {
        // thrown back off the wall and fanned out along it
        const out = rnd(0.6, 2.2) * (0.6 + str), side = rnd(-2, 2), up = rnd(0.6, 2.6) * (0.7 + 0.5 * str);
        this.sparks.spawn(px, y + rnd(-0.04, 0.06), pz, nx * out + nz * side, up, nz * out - nx * side, rnd(0.25, 0.55), 1, 0.72, 0.25, rnd(0.07, 0.12), 7);
      }
      this.dust(px, s.y + 0.05, pz, nx, nz, Math.round(2 + 5 * str), 0.62, 0.6, 0.56);
    } else if (imp.kind === 'soft') {
      this.cam.kick(-nx, -nz, str * 0.45, false);
      this.sfx.thump(str);
      this.rumble(0.35 * str + 0.1, 0.15, 80 + 60 * str);
      this.dust(px, s.y + 0.03, pz, nx, nz, Math.round(4 + 10 * str), 0.66, 0.58, 0.46);
    } else {
      const stone = imp.fence?.kind === 'drystoneWall';
      this.cam.kick(-nx, -nz, str * (stone ? 0.55 : 0.3), stone);
      this.sfx.crack(stone, str);
      this.rumble(stone ? 0.5 : 0.2, stone ? 0.5 : 0.45, stone ? 150 : 90);
      if (stone && str > 0.6) this.stop = Math.max(this.stop, 0.03);
      const n = stone ? 14 : 12;
      const [r, g, b] = imp.fence?.kind === 'snowFence' ? [0.55, 0.42, 0.3] : imp.fence?.kind === 'hedge' ? [0.34, 0.52, 0.26] : stone ? [0.56, 0.54, 0.5] : [0.62, 0.48, 0.32];
      // thrown on ahead of the car, the way it was going
      for (let k = 0; k < n; k++) {
        const fwd = rnd(0.5, 2) * (0.6 + str), side = rnd(-1.4, 1.4);
        const shade = rnd(0.8, 1.15);
        this.bits.spawn(px + rnd(-0.3, 0.3) * Math.abs(nz), s.y + rnd(0.05, 0.2), pz + rnd(-0.3, 0.3) * Math.abs(nx),
          -nx * fwd + nz * side, rnd(0.8, 2.4), -nz * fwd - nx * side, rnd(0.6, 1.1),
          r * shade, g * shade, b * shade, stone ? rnd(0.08, 0.13) : rnd(0.06, 0.1), 6);
      }
      this.dust(px, s.y + 0.05, pz, -nx, -nz, 6, 0.7, 0.66, 0.58);
    }
  }

  /**
   * A building coming down (a mission's knock-down, missions/workTemplates.ts): a cloud of dust rolling out over
   * its footprint (x0, z0, w by d tiles, `h` high, standing at `y`), rubble thrown up off it, a stone crack and a
   * long shake. In its island's tile coordinates.
   */
  collapse(x0: number, z0: number, w: number, d: number, y: number, h: number): void {
    this.lastY = y;
    this.cam.kick(0, 0, 1, true);
    this.sfx.crack(true, 1);
    this.sfx.knock(1);
    this.rumble(1, 0.8, 700);
    const cx = x0 + w / 2, cz = z0 + d / 2;
    const n = Math.min(70, Math.round(24 + w * d * 6));
    for (let k = 0; k < n; k++) {
      const x = x0 + Math.random() * w, z = z0 + Math.random() * d;
      const ox = x - cx, oz = z - cz, l = Math.hypot(ox, oz) || 1, out = rnd(0.4, 1.4), shade = rnd(0.85, 1.1);
      this.bits.spawn(x, y + rnd(0, h * 0.7), z, (ox / l) * out, rnd(0.2, 0.9), (oz / l) * out,
        rnd(1.6, 2.8), 0.68 * shade, 0.63 * shade, 0.56 * shade, rnd(0.45, 0.85), 0.12);
    }
    for (let k = 0; k < 40; k++) {
      const x = x0 + Math.random() * w, z = z0 + Math.random() * d;
      const ox = x - cx, oz = z - cz, l = Math.hypot(ox, oz) || 1, out = rnd(0.6, 2.6), shade = rnd(0.75, 1.15);
      // brick, stone and old timber
      const [r, g, b] = k % 3 === 0 ? [0.62, 0.36, 0.28] : k % 3 === 1 ? [0.58, 0.56, 0.52] : [0.5, 0.38, 0.26];
      this.bits.spawn(x, y + rnd(0.2, Math.max(0.4, h * 0.6)), z, (ox / l) * out, rnd(1, 3.4), (oz / l) * out,
        rnd(0.9, 1.6), r * shade, g * shade, b * shade, rnd(0.08, 0.16), 6);
    }
  }

  private dust(x: number, y: number, z: number, nx: number, nz: number, n: number, r: number, g: number, b: number): void {
    for (let k = 0; k < n; k++) {
      const out = rnd(0.2, 0.8), side = rnd(-0.8, 0.8), shade = rnd(0.9, 1.1);
      this.bits.spawn(x + rnd(-0.1, 0.1), y, z + rnd(-0.1, 0.1), nx * out + nz * side, rnd(0.2, 0.6), nz * out - nx * side,
        rnd(0.5, 0.9), r * shade, g * shade, b * shade, rnd(0.14, 0.24), 0.3);
    }
  }

  /**
   * Every frame. `dt` is real time (0 while paused), `simDt` the world's time; `scrape` is how hard
   * vehicle `s` is grinding along a wall, 0 when it isn't.
   */
  update(dt: number, simDt: number, scrape: number, s: VehicleState, hl: number): void {
    if (dt > 0) this.stop = Math.max(0, this.stop - dt);
    this.sfx.scrape(dt > 0 ? scrape : 0);
    if (scrape > 0 && simDt > 0 && s.contactNx !== undefined) {
      const nx = s.contactNx, nz = s.contactNz ?? 0;
      const dir = Math.sign(s.v) || 1;
      const fx = Math.sin(s.heading) * dir, fz = Math.cos(s.heading) * dir;
      this.sparkDebt += simDt * 60 * scrape;
      while (this.sparkDebt >= 1) {
        this.sparkDebt--;
        // they trail off behind the car along the wall, and kick up and away from it
        const back = rnd(0.3, 1.2) * (0.5 + scrape), out = rnd(0.2, 0.9);
        // from the front corner rubbing on the wall
        const along = hl * rnd(0.5, 0.95);
        this.sparks.spawn(s.x - nx * 0.02 + fx * along, s.y + rnd(0.08, 0.16), s.z - nz * 0.02 + fz * along,
          -fx * back + nx * out, rnd(0.4, 1.8), -fz * back + nz * out, rnd(0.15, 0.35), 1, 0.72, 0.25, rnd(0.06, 0.1), 7);
      }
      this.rumbleWait -= dt;
      if (this.rumbleWait <= 0) { this.rumbleWait = 0.1; this.rumble(0, 0.15 + 0.35 * scrape, 120); }
    } else {
      this.sparkDebt = 0;
    }
    if (scrape > 0 || this.stop > 0) this.lastY = s.y;
    this.sparks.update(simDt, this.lastY, true);
    this.bits.update(simDt, this.lastY, false);
  }

  private rumble(strong: number, weak: number, ms: number): void {
    const pads = navigator.getGamepads?.() ?? [];
    for (const p of pads) {
      const a = (p as (Gamepad & { vibrationActuator?: Actuator }) | null)?.vibrationActuator;
      a?.playEffect?.('dual-rumble', { startDelay: 0, duration: Math.round(ms), strongMagnitude: Math.min(1, strong), weakMagnitude: Math.min(1, weak) })?.catch(() => {});
    }
  }
}
