/**
 * The hero (docs/missions.html, The hero): the prize a mission card is about, turning slowly on a plinth.
 *
 * One renderer on one canvas for the whole game, moved into whichever card or journal pane is showing a
 * mission; it draws only while it is on the page and visible, and builds each model once, keeping the
 * last few. Vehicles are the game's own meshes with their parts on; a building is drawn by the town
 * mesher in its town's style, alone on a scratch island; everything else comes from haulMeshes.ts.
 */
import { JOBS } from '../game/factions/paintjobs';
import * as THREE from 'three';
import { CHUNK, World, type Building, type Town } from '../world/tiles';
import { buildVehicleMesh, disposeVehicleMesh } from './vehicleMeshes';
import { buildTownChunk } from './townMesh';
import { buildCar } from './trainMeshes';
import { dressTrainTreats } from './treats';
import { SETS } from '../game/rollingStock';
import { compileReady } from './compileReady';
import { buildCrate, buildFerry, buildHaul, buildPart, buildStamp, buildTrophy, disposeGroup } from './haulMeshes';
import { applyParts } from '../game/parts';
import { defOf } from '../game/fleet';
import type { HeroSpec } from '../game/missions/model';

const FOV = 24;
/** A full turn every this many seconds. */
const TURN_SECONDS = 16;
const CACHE = 8;

interface Built { obj: THREE.Object3D; dispose(): void; lift: number; /** A box to frame by, when the model's own bounds can't be trusted. */ frame?: THREE.Box3 }

class HeroStage {
  readonly canvas = document.createElement('canvas');
  private renderer: THREE.WebGLRenderer | null = null;
  private scene = new THREE.Scene();
  private cam = new THREE.PerspectiveCamera(FOV, 1, 0.05, 400);
  private pivot = new THREE.Group();
  private plinth: THREE.Mesh;
  private rim: THREE.DirectionalLight;
  private cache = new Map<string, Built>();
  private showing: Built | null = null;
  private key = '';
  private raf = 0;
  private last = 0;
  /** The size of the card slot it sits in, kept by a ResizeObserver: reading it each frame forced a page layout. */
  private slot = { el: null as HTMLElement | null, w: 0, h: 0 };
  private sizer = typeof ResizeObserver !== 'undefined' ? new ResizeObserver((es) => {
    for (const e of es) if (e.target === this.slot.el) { this.slot.w = Math.round(e.contentRect.width); this.slot.h = Math.round(e.contentRect.height); }
  }) : null;
  /** Seconds since the last frame it drew: it turns slowly, so 30 a second is plenty beside the game's own. */
  private since = 0;
  private t = 0;
  private yaw = -0.7;
  private drag: { x: number; yaw: number } | null = null;
  private idle = 99;
  private calm = typeof matchMedia !== 'undefined' && matchMedia('(prefers-reduced-motion: reduce)').matches;
  private scratch: World | null = null;
  /** What is showing, so a thumbnail taken in between can put it back. */
  private spec: HeroSpec | null = null;
  private tint = 0xffffff;
  /** Framing for the current model: centre and distance. */
  private frame = { cx: 0, cy: 0.3, cz: 0, dist: 3, size: 1 };
  /** The model's height on the plinth before the bob. */
  private baseY = 0;

  constructor() {
    this.canvas.className = 'hero-canvas';
    this.scene.add(new THREE.HemisphereLight(0xfff4dc, 0x7a6a50, 1.1));
    const sun = new THREE.DirectionalLight(0xfff1d6, 2.2);
    sun.position.set(3, 6, 4);
    this.scene.add(sun);
    this.rim = new THREE.DirectionalLight(0xe2412f, 1.1);
    this.rim.position.set(-4, 2.5, -3.5);
    this.scene.add(this.rim);
    this.plinth = new THREE.Mesh(new THREE.CylinderGeometry(1, 1.04, 0.12, 48), new THREE.MeshStandardMaterial({ color: 0xc9a85a, roughness: 0.8 }));
    this.plinth.position.y = -0.06;
    this.scene.add(this.plinth, this.pivot);
    this.canvas.addEventListener('pointerdown', (e) => { this.drag = { x: e.clientX, yaw: this.yaw }; this.canvas.setPointerCapture(e.pointerId); });
    this.canvas.addEventListener('pointermove', (e) => { if (this.drag) { this.yaw = this.drag.yaw + (e.clientX - this.drag.x) * 0.012; this.idle = 0; } });
    this.canvas.addEventListener('pointerup', () => { this.drag = null; });
  }

  /** Put the canvas into this element (it fills it). */
  mount(el: HTMLElement): void {
    if (this.canvas.parentElement !== el) el.prepend(this.canvas);
    if (this.slot.el !== el) {
      if (this.slot.el) this.sizer?.unobserve(this.slot.el);
      this.slot = { el, w: el.clientWidth, h: el.clientHeight };
      this.sizer?.observe(el);
    }
    this.start();
  }

  /** Show a mission's hero, the plinth's rim lit in its thread's colour. */
  show(spec: HeroSpec, tint: number): void {
    this.spec = spec;
    this.tint = tint;
    this.rim.color.setHex(tint);
    const key = keyOf(spec);
    if (key === this.key && this.showing) return;
    this.key = key;
    if (this.showing) this.pivot.remove(this.showing.obj);
    let b = this.cache.get(key);
    if (!b) {
      b = this.build(spec);
      this.cache.set(key, b);
      if (this.cache.size > CACHE) {
        const [k0, old] = this.cache.entries().next().value as [string, Built];
        if (old !== b) { old.dispose(); this.cache.delete(k0); }
      }
    }
    this.showing = b;
    this.pivot.add(b.obj);
    // frame it by its bounding box, standing on the plinth, measured square on
    this.pivot.rotation.y = 0;
    b.obj.position.set(0, 0, 0);
    this.pivot.updateMatrixWorld(true);
    const box = b.frame ? b.frame.clone() : new THREE.Box3().setFromObject(b.obj);
    const size = box.getSize(new THREE.Vector3()), centre = box.getCenter(new THREE.Vector3());
    b.obj.position.set(-centre.x, -box.min.y, -centre.z);
    this.baseY = -box.min.y;
    const r = Math.max(size.x, size.z) * 0.62 + 0.05;
    this.plinth.scale.set(r, 1, r);
    this.plinth.position.y = -0.06 * Math.max(0.4, r);
    this.plinth.scale.y = Math.max(0.4, r);
    const radius = Math.max(size.length() * 0.5, 0.2);
    this.frame = { cx: 0, cy: size.y * 0.45, cz: 0, dist: radius / Math.sin(THREE.MathUtils.degToRad(FOV / 2)) * 1.08, size: radius };
    this.cam.near = this.frame.dist / 50;
    this.cam.far = this.frame.dist * 10;
    this.cam.updateProjectionMatrix();
    this.idle = 99;
  }

  /** A still of what is showing, for a list thumbnail. */
  still(spec: HeroSpec, tint: number, w = 96, h = 96): string {
    const was = this.spec, wasTint = this.tint;
    this.show(spec, tint);
    const r = this.ensure();
    const prev = new THREE.Vector2();
    r.getSize(prev);
    r.setSize(w, h, false);
    this.cam.aspect = w / h;
    this.place(0.6);
    r.render(this.scene, this.cam);
    const url = this.canvas.toDataURL();
    r.setSize(prev.x || 1, prev.y || 1, false);
    if (was) this.show(was, wasTint);
    return url;
  }

  /**
   * Build the renderer and compile these heroes' shaders in the background, before any card needs
   * them: the first card of a game used to stall a third of a second making its WebGL context and
   * compiling, and every new kind of hero after it (a first vehicle) another tenth or more.
   */
  async warm(specs: HeroSpec[]): Promise<void> {
    if (this.raf) return; // a card is up: it is warm enough already
    const r = this.ensure();
    const was = this.spec, wasTint = this.tint;
    for (const spec of specs) {
      if (this.raf) break;
      try {
        this.show(spec, this.tint || 0xffffff);
        await compileReady(r, this.scene, this.cam);
      } catch { /* a hero that can't be built shows itself when it is needed */ }
    }
    if (was && !this.raf) this.show(was, wasTint);
  }

  /**
   * A still of any little scene through this stage's renderer (it is the one spare WebGL context the game
   * keeps), as a PNG: the HUD's tool buttons draw their pictures with it once.
   */
  render(scene: THREE.Scene, cam: THREE.Camera, w: number, h: number): string {
    const r = this.ensure();
    const prev = new THREE.Vector2();
    r.getSize(prev);
    r.setSize(w, h, false);
    r.render(scene, cam);
    const url = this.canvas.toDataURL();
    r.setSize(prev.x || 1, prev.y || 1, false);
    return url;
  }

  hide(): void {
    cancelAnimationFrame(this.raf);
    this.raf = 0;
  }

  private ensure(): THREE.WebGLRenderer {
    if (!this.renderer) {
      // no preserveDrawingBuffer: every still is read back in the same task it is drawn in, and keeping the
      // buffer cost a copy on every frame of the turntable
      this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, alpha: true });
      this.renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
      this.renderer.toneMapping = THREE.NeutralToneMapping;
      this.renderer.toneMappingExposure = 1.05;
    }
    return this.renderer;
  }

  private start(): void {
    if (this.raf) return;
    this.last = performance.now();
    const tick = (now: number) => {
      this.raf = requestAnimationFrame(tick);
      this.since += Math.min(0.25, (now - this.last) / 1000);
      this.last = now;
      if (this.since < 1 / 31) return;
      const dt = Math.min(0.05, this.since);
      this.since = 0;
      this.draw(dt);
    };
    this.raf = requestAnimationFrame(tick);
  }

  private draw(dt: number): void {
    const el = this.canvas.parentElement;
    // its card has gone (closed, hidden, emptied): the loop stops until a card mounts it again. It used to
    // run all session after the first card, reading the slot's size every frame and forcing a page layout
    if (!el || !this.showing || !this.canvas.isConnected || el !== this.slot.el || el.closest('[hidden]')) { this.hide(); return; }
    const W = this.slot.w, H = this.slot.h;
    if (!W || !H) return;
    const r = this.ensure();
    const size = r.getSize(new THREE.Vector2());
    if (size.x !== W || size.y !== H) { r.setSize(W, H, false); }
    this.cam.aspect = W / H;
    this.t += dt;
    this.idle += dt;
    if (!this.calm && !this.drag && this.idle > 2.5) this.yaw += (dt * Math.PI * 2) / TURN_SECONDS;
    this.place(this.calm ? 0.6 : this.yaw);
    this.showing.obj.position.y = this.baseY + this.showing.lift + (this.calm ? 0 : Math.sin(this.t * 1.3) * this.frame.size * 0.015);
    r.render(this.scene, this.cam);
  }

  /** The camera three-quarters on and a little above, the model turned to `yaw`. */
  private place(yaw: number): void {
    this.pivot.rotation.y = yaw;
    this.plinth.rotation.y = yaw;
    const f = this.frame;
    const dir = new THREE.Vector3(0, 0.42, 1).normalize();
    // fit the narrower way: in a tall, thin slot the width is what crops, not the height
    const half = Math.tan(THREE.MathUtils.degToRad(FOV / 2));
    const dist = f.dist * Math.max(1, half / Math.max(1e-3, half * Math.min(1, this.cam.aspect)) * 0.82);
    this.cam.position.set(f.cx + dir.x * dist, f.cy + dir.y * dist, f.cz + dir.z * dist);
    this.cam.lookAt(f.cx, f.cy * 0.85, f.cz);
    this.cam.updateProjectionMatrix();
  }

  /** A model of the spec, built fresh (not cached): the cards' heroes, and the loading screen's showcase. */
  build(spec: HeroSpec): Built {
    const plain = (g: THREE.Object3D): Built => ({ obj: g, lift: 0, dispose: () => disposeGroup(g) });
    switch (spec.kind) {
      case 'vehicle': {
        // a train is its engine alone: a whole consist would be a speck on the plinth. The cars' meshes
        // share their geometry with every train in the world, so there is nothing to dispose
        const set = SETS.find((s) => s.id === spec.model);
        if (set) {
          const car = buildCar(set.cars[0], 0);
          // its topper or crown on the cab, its gold, as on the line (the user, 6 Nov 2026: trains showed bare here)
          dressTrainTreats([car], applyParts(defOf(spec.model), spec.parts));
          const g = new THREE.Group();
          g.add(car.group);
          return { obj: g, lift: 0, dispose: () => {} };
        }
        let def = applyParts(defOf(spec.model), spec.parts);
        // a paintjob (docs/factions.html): the faction's colour over the body, and its rules on it
        const job = spec.job ? JOBS[spec.job] : undefined;
        if (job) def = { ...def, color: job.body, job: job.id };
        const m = buildVehicleMesh(def);
        m.body.position.y = m.lift ?? 0;
        const g = new THREE.Group();
        g.add(m.holder);
        return { obj: g, lift: 0, dispose: () => disposeVehicleMesh(m) };
      }
      case 'part': return plain(buildPart(spec.slot, spec.tier));
      case 'load': return plain(buildHaul(spec.load));
      case 'trophy': return plain(buildTrophy());
      case 'ferry': return plain(buildFerry());
      case 'stamp': return plain(buildStamp());
      case 'crate': return plain(buildCrate(spec.colour));
      case 'building': {
        const g = this.building(spec);
        // the town mesher's chunk carries more than the building: frame by the footprint and its height
        const all = new THREE.Box3().setFromObject(g);
        const top = Math.max(0.4, Math.min(all.max.y, spec.floors * 0.5 + 3));
        const frame = new THREE.Box3(new THREE.Vector3(4, 0, 4), new THREE.Vector3(4 + spec.w, top, 4 + spec.d));
        return { obj: g, lift: 0, frame, dispose: () => g.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) m.geometry.dispose(); }) };
      }
    }
  }

  /** One building on a scratch island, drawn by the town mesher in its style. */
  private building(spec: Extract<HeroSpec, { kind: 'building' }>): THREE.Group {
    if (!this.scratch) {
      this.scratch = new World();
      this.scratch.corners.fill(4);
    }
    const w = this.scratch;
    const r = spec.real;
    const b: Building = {
      kind: spec.b, x: 4, z: 4, w: spec.w, d: spec.d, facing: (r?.facing ?? 1) as Building['facing'], floors: spec.floors,
      seed: r?.seed ?? 4242, solid: true, level: 4, uid: r?.uid ?? -1, ...(r?.style ? { style: r.style } : {}), ...(r?.derelict ? { derelict: true } : {}),
    };
    const t: Town = { id: 0, kind: 'city', name: 'Hero', x0: 0, z0: 0, size: 4 + Math.max(spec.w, spec.d) + 2, level: 4, style: spec.arch, buildings: [b], roads: 0, entry: [] };
    w.towns = [t];
    w.allBuildings = [b];
    // a real building keeps its cell and uid, so the mesher finds the livery painted on it; a stand-in's
    // uid is -1, which nobody owns
    w.cx = r?.cx ?? 0;
    w.cz = r?.cz ?? 0;
    // the mesher draws a building in the chunk its middle stands in: a lot wider than a chunk (a race circuit, an
    // airport) has its middle out past the first, which drew nothing (the user, 28 Oct 2026: a circuit HQ's plinth stood empty)
    const mx = Math.floor((b.x + b.w / 2) / CHUNK), mz = Math.floor((b.z + b.d / 2) / CHUNK);
    let g: THREE.Group;
    try { g = buildTownChunk(w, mx, mz) ?? new THREE.Group(); } finally {
      w.towns = [];
      w.allBuildings = [];
      w.cx = 0;
      w.cz = 0;
    }
    // the mesher puts the ground at its level: bring the building down to the plinth
    const out = new THREE.Group();
    out.add(g);
    g.position.y = -2;
    return out;
  }
}

function keyOf(s: HeroSpec): string {
  switch (s.kind) {
    case 'vehicle': return `v:${s.model}:${JSON.stringify(s.parts ?? {})}:${s.job ?? ''}`;
    case 'part': return `p:${s.slot}:${s.tier}`;
    case 'building': return `b:${s.b}:${s.arch}:${s.w}x${s.d}x${s.floors}${s.real ? `:${s.real.cx},${s.real.cz}#${s.real.uid}:${s.real.seed}:${s.real.facing}:${s.real.style ?? ''}:${s.real.derelict ? 1 : 0}` : ''}`;
    case 'load': return `l:${s.load}`;
    case 'crate': return `c:${s.colour}`;
    default: return s.kind;
  }
}

/** The one hero stage the game has. */
export const hero = new HeroStage();
