import { N } from '../world/tiles';
import type { CellKind } from '../world/tiles';
import { deeds } from './deeds';
import { rewards } from './passportRewards';
import { money } from './cargoHud';
import { Chain, frontierOf } from '../../shared/range';

/**
 * Range (docs/exploration.html, phase 1): how far from home the player has taken each vehicle at the
 * wheel, and cash for every cell the fleet sets foot in for the first time.
 *
 * Home is a fixed point in world tiles, set once per career: the HQ the fleet started with (every new
 * fleet owns its starter house), else where the car first stood. It never follows a new HQ, so moving
 * house can neither reset a record nor inflate one.
 *
 * Only continuous travel counts. The player carries a `budget`: the distance credited when the chain
 * last began, plus every tile driven since. A frame that moves four tiles or more (the odometer's own
 * test for a jump) is a placement, not driving: the garage, Unstick, the airlift home, a debug hop.
 * After one, the budget falls back to what was already credited, so a teleport outward claims nothing
 * until the vehicle drives that far for itself. Driving out from home always credits the full distance,
 * since the road travelled is never shorter than the straight line.
 */

export type RangeKind = 'land' | 'water' | 'air' | 'rail';

export interface RangeSave {
  /** Home, world tiles. */
  home: [number, number];
  /** Best tiles from home at the wheel of each model, by model id. */
  model: Record<string, number>;
  /** Best by kind of vehicle. */
  kind: Partial<Record<RangeKind, number>>;
  /** Best of anything. */
  all: number;
  /** Best tiles from the world's origin, tile 0,0 of cell 0,0. */
  frontier: number;
  /** The chain's credit when the game saved, so a reload carries on from where it stood. */
  credit: number;
  /** The shakedown rungs paid per model: a bitmask over RUNGS. */
  paid: Record<string, number>;
  /** Cells set foot in and settled ("cx,cz"): each pays once. */
  found: string[];
  /** Islands and continents whose landfall bonus is settled. */
  lands: string[];
  /** Everything discovery has paid, bonuses included. */
  earned: number;
  /** The Wanderlust purse has been paid. */
  wander?: boolean;
  /** Cells this fleet was the first of anyone to reach (online, docs/exploration.html phase 2). */
  firsts?: number;
}

/** One-off payments for taking a model far from home (docs/exploration.html, "Per vehicle"). */
export const RUNGS: { tiles: number; pay: number; name: string }[] = [
  { tiles: 1000, pay: 200, name: 'Run in' },
  { tiles: 3000, pay: 600, name: 'Shaken down' },
  { tiles: 8000, pay: 1500, name: 'Proven' },
];
/** Models run in (past the first rung) for the Wanderlust purse, and what it pays. */
const WANDER_MODELS = 25;
const WANDER_PAY = 10000;

/** Discovery pay: a base, a step for every ring of cells out from home, half for open sea. */
export const DISCOVER = { base: 40, ring: 20, sea: 0.5, landfall: 100 };
/** What a cell pays on first setting foot in it, before any landfall bonus. */
export const discoverPay = (ring: number, sea: boolean): number => Math.round((DISCOVER.base + DISCOVER.ring * ring) * (sea ? DISCOVER.sea : 1));
/** A frame moving this far or further is a placement, not driving (the odometer's test). */
const JUMP = 4;
/** A record is told on the pill each time it passes another of these, at most once a game hour per model. */
const TELL_EVERY = 500;

export interface RangeHost {
  /** Money in on the books' Exploration line. */
  earn(amount: number): void;
  /** The notification pill. */
  say(title: string, body: string): void;
  /** A green "+$X" over the car. */
  float(text: string): void;
  /** The game hour, for spacing the pill out. */
  hours(): number;
  /** The fleet's HQ in world tiles, if it has one: the first home of a game that had none saved. */
  hq(): [number, number] | null;
  /** A model's name for the pill. */
  nameOf(model: string): string;
}

/** Tiles written for a person: "1,540 tiles", and the cells too once it's two of them. */
export function tilesText(t: number): string {
  const n = Math.floor(t);
  const s = `${n.toLocaleString('en-US')} tile${n === 1 ? '' : 's'}`;
  return n >= 2 * N ? `${s} (${Math.round(n / N)} cells)` : s;
}

const blank = (): Omit<RangeSave, 'home'> => ({ model: {}, kind: {}, all: 0, frontier: 0, credit: 0, paid: {}, found: [], lands: [], earned: 0 });

export class Range {
  home: [number, number] | null = null;
  model: Record<string, number> = {};
  kind: Partial<Record<RangeKind, number>> = {};
  all = 0;
  frontier = 0;
  paid: Record<string, number> = {};
  earned = 0;
  wander = false;
  private found = new Set<string>();
  private lands = new Set<string>();
  /** The honest-travel chain (shared/range.ts): its credit is what this drive may claim. */
  private chain = new Chain();
  /** What each cell paid when it was found this session, so First Footing can pay it again. */
  private paidAt = new Map<string, number>();
  /** Cells the server says this fleet reached first, and how many. */
  firsts = 0;
  /** The game hour each model was last told on the pill, and the step of TELL_EVERY it was told at. */
  private told = new Map<string, { h: number; step: number }>();
  /** Bumped when a record or the home moves, for the map's ring. */
  version = 0;

  constructor(private host: RangeHost) {}

  /** A new game: nothing found, home set by the first frame. */
  reset(): void { this.load(null); }

  /**
   * From a save. Without a range block (version 25 and older): home is the HQ, else the middle of the
   * cell the game began in; every cell the save has set foot in is settled without pay; and the car is
   * trusted where it stands, since it got there before anything was counting.
   */
  load(s: RangeSave | null | undefined, legacy?: { start?: [number, number] | null; seen?: string[] }): void {
    const b = { ...blank(), ...(s ?? {}) };
    this.home = s?.home ? [s.home[0], s.home[1]] : null;
    this.model = { ...b.model };
    this.kind = { ...b.kind };
    this.all = b.all || 0;
    this.frontier = b.frontier || 0;
    this.paid = { ...b.paid };
    this.earned = b.earned || 0;
    this.wander = !!b.wander;
    this.found = new Set(b.found);
    this.lands = new Set(b.lands);
    this.chain = new Chain(s ? b.credit || 0 : 0);
    this.firsts = b.firsts || 0;
    this.paidAt.clear();
    this.told.clear();
    if (!s && legacy) {
      for (const c of legacy.seen ?? []) this.found.add(c);
      const hq = this.host.hq();
      if (hq) this.home = hq;
      else if (legacy.start) this.home = [(legacy.start[0] + 0.5) * N, (legacy.start[1] + 0.5) * N];
      this.chain = new Chain(Infinity);
    }
    this.version++;
  }

  toSave(): RangeSave | undefined {
    if (!this.home) return undefined;
    return {
      home: [Math.round(this.home[0] * 10) / 10, Math.round(this.home[1] * 10) / 10],
      model: Object.fromEntries(Object.entries(this.model).map(([k, v]) => [k, Math.floor(v)])),
      kind: Object.fromEntries(Object.entries(this.kind).map(([k, v]) => [k, Math.floor(v ?? 0)])),
      all: Math.floor(this.all), frontier: Math.floor(this.frontier), credit: Math.floor(this.chain.credit),
      paid: { ...this.paid }, found: [...this.found], lands: [...this.lands], earned: Math.round(this.earned),
      ...(this.wander ? { wander: true } : {}),
      ...(this.firsts ? { firsts: this.firsts } : {}),
    };
  }

  /** Home, set the first time it's needed: the HQ if there is one, else wherever the car is. */
  private ensureHome(gx: number, gz: number): [number, number] {
    if (!this.home) { this.home = this.host.hq() ?? [gx, gz]; this.version++; }
    return this.home;
  }

  /** Tiles from home, for anything that asks (the map, the inspector, missions later). */
  fromHome(gx: number, gz: number): number {
    const h = this.home;
    return h ? Math.hypot(gx - h[0], gz - h[1]) : 0;
  }

  /** The cell home is in. */
  homeCell(): [number, number] | null {
    return this.home ? [Math.floor(this.home[0] / N), Math.floor(this.home[1] / N)] : null;
  }

  /** How many models are past the first rung. */
  runIn(): number {
    let n = 0;
    for (const v of Object.values(this.model)) if (v >= RUNGS[0].tiles) n++;
    return n;
  }

  /**
   * A frame of the player at the wheel: `gx, gz` in world tiles after the step, `model` and `kind` what
   * they are driving. Called only in play, only when the simulation moved.
   */
  step(gx: number, gz: number, model: string, kind: RangeKind): void {
    const [hx, hz] = this.ensureHome(gx, gz);
    // a placement keeps what was credited, if it is still that far out; driving adds what it drove
    const c = this.chain.step(gx, gz, hx, hz, (moved) => moved >= JUMP);
    if (c <= 0) return;

    deeds.best('range', c);
    if (c > this.all) this.all = c;
    if (c > (this.kind[kind] ?? 0)) this.kind[kind] = c;
    // the furthest from the origin this chain could honestly be: never beyond home's own distance plus the credit
    const fo = frontierOf(gx, gz, hx, hz, c);
    deeds.best('frontier', fo);
    if (fo > this.frontier) this.frontier = fo;

    const was = this.model[model] ?? 0;
    if (c <= was) return;
    this.model[model] = c;
    this.version++;
    if (c >= RUNGS[0].tiles) deeds.mark('rangeModels', model);
    this.rungs(model, c);
    this.tell(model, was, c);
  }

  /** Pay any shakedown rung this model has just passed, and the Wanderlust purse. */
  private rungs(model: string, c: number): void {
    let mask = this.paid[model] ?? 0;
    for (let k = 0; k < RUNGS.length; k++) {
      const r = RUNGS[k];
      if (c < r.tiles || mask & (1 << k)) continue;
      mask |= 1 << k;
      this.paid[model] = mask;
      this.host.earn(r.pay);
      this.host.float(`+${money(r.pay)} ${r.name}`);
      this.host.say(`${r.name} · ${this.host.nameOf(model)}`, `${money(r.pay)} for taking it ${tilesText(r.tiles)} from home`);
      this.told.set(model, { h: this.host.hours(), step: Math.floor(c / TELL_EVERY) });
    }
    if (!this.wander && this.runIn() >= WANDER_MODELS) {
      this.wander = true;
      this.host.earn(WANDER_PAY);
      this.host.float(`+${money(WANDER_PAY)} Wanderlust`);
      this.host.say('Wanderlust', `${money(WANDER_PAY)} for running in ${WANDER_MODELS} different vehicles a thousand tiles from home`);
    }
  }

  /** "Furthest yet in the Sunny": each time a record passes another 500 tiles, once a game hour at most. */
  private tell(model: string, was: number, c: number): void {
    const step = Math.floor(c / TELL_EVERY);
    if (step < 1 || step <= Math.floor(was / TELL_EVERY)) return;
    const h = this.host.hours(), last = this.told.get(model);
    if (last && (last.step >= step || h - last.h < 1)) return;
    this.told.set(model, { h, step });
    const best = c >= this.all - 0.5;
    this.host.say(`Furthest yet in the ${this.host.nameOf(model)}`, `${tilesText(c)} from home${best ? ' · your best in anything' : ''}`);
  }

  /**
   * The player has set foot in a cell (main.ts arrived()). The first time, it pays: more the further it
   * lies from home, half for open sea, and a landfall bonus for an island or continent new to the fleet.
   * Returns what was paid.
   */
  discovered(cx: number, cz: number, gx: number, gz: number, w: { kind: CellKind; name: string; continent: string }): number {
    const [hx, hz] = this.ensureHome(gx, gz);
    const k = `${cx},${cz}`;
    const sea = w.kind === 'sea';
    const land = sea ? '' : w.kind === 'continent' && w.continent ? `c:${w.continent}` : w.name ? `i:${w.name}` : '';
    const ring = Math.max(Math.abs(cx - Math.floor(hx / N)), Math.abs(cz - Math.floor(hz / N)));
    if (this.found.has(k) || ring === 0) {
      // settled already (or home itself): its land is settled with it, so a return never pays
      this.found.add(k);
      if (land) this.lands.add(land);
      return 0;
    }
    this.found.add(k);
    // every landform stamped (game/passportRewards.ts): the Explorer's lantern pays a tenth more
    let pay = Math.round(discoverPay(ring, sea) * rewards.discoveryMul());
    this.paidAt.set(k, pay);
    let bonus = 0;
    if (land && !this.lands.has(land)) { this.lands.add(land); bonus = DISCOVER.landfall; }
    pay += bonus;
    this.earned += pay;
    deeds.add('discoverPay', pay);
    this.host.earn(pay);
    this.host.float(`+${money(pay)} ${bonus ? 'Landfall' : 'New ground'}`);
    return pay;
  }

  /**
   * The server says this fleet was the first of anyone to set foot in a cell (docs/exploration.html, First
   * Footing): the cell's discovery pay again. Returns what was paid.
   */
  firstFooting(cx: number, cz: number, sea: boolean): number {
    const k = `${cx},${cz}`;
    const hc = this.homeCell();
    const ring = hc ? Math.max(1, Math.abs(cx - hc[0]), Math.abs(cz - hc[1])) : 1;
    const pay = this.paidAt.get(k) ?? discoverPay(ring, sea);
    this.firsts++;
    this.earned += pay;
    deeds.add('firsts');
    deeds.add('discoverPay', pay);
    this.host.earn(pay);
    this.host.float(`+${money(pay)} First Footing`);
    return pay;
  }

  /** The server keeps this home: the game takes it, so both measure from the same place. */
  adoptHome(x: number, z: number): void {
    if (this.home && Math.abs(this.home[0] - x) < 0.5 && Math.abs(this.home[1] - z) < 0.5) return;
    this.home = [x, z];
    this.chain.restart(0);
    this.version++;
  }

  /** The chain's credit now: what the current drive may claim. */
  get credit(): number { return this.chain.credit; }

  /** How many cells the fleet has set foot in, and which ("cx,cz"): the Surveyor's Commission counts them. */
  get foundCount(): number { return this.found.size; }
  foundCells(): string[] { return [...this.found]; }
}
