/**
 * Missions (docs/missions.html): the director that decides what is offered, the objectives that run
 * once one is taken, the rewards when it is done, and the save.
 *
 * Nothing here draws anything or touches the world directly: the card, the journal, the rival and the
 * tow are all the host's, and the host is told what to do through `MissionHost`. What this keeps is the
 * list — offered, under way and done — each town's standing, how far each arc has got, and the Passport.
 */
import { retextMission } from './textEdits';
import { KIND_IN } from './text';
import { MEET_MIN, messageSpot } from './story/kit';
import { hashString } from '../../world/rng';
import { N, type World, type Port } from '../../world/tiles';
import type { CargoItem, Site } from '../cargo';
import type { Place } from '../fit';
import type { VehicleDef } from '../vehicles';
import type { KnownAirport } from '../../world/surveyor';
import { tierPrice, type SlotId } from '../parts';
import { isHelicopter } from '../vehicles';
import { isNight } from '../nightRules';
import { cargoById } from '../cargoTypes';
import { Bus } from './bus';
import { MEDAL_ICON, MEDAL_NAME, medalBonus, medalFor, medalled, medalRun, medalTimes, nextMedal, type Medal } from './medals';
import { Passport, type SavedPassport } from './passport';
import { THREADS, type Arc, type Giver, type Kind, type Mission, type Obj, type Reward, type Thread, type TownRef } from './model';
import { ARCS, TEMPLATES, templateById, townRef, type Template } from './templates';
import { CIRCUIT_NEAR, circuitsNear } from './circuitTemplates';
import { EVENT_ENTRIES, openEntries } from './eventTemplates';
import { actKeyOf } from './actTemplates';
import { ACT_BOARD } from './actBoard';
import { rivalById } from './rivals';
import { speedText } from '../units';
import { RUNG, RUNGS } from '../carriage';

/** At most this many offered at once, and under way. */
const MAX_OFFERED = 5, MAX_ACTIVE = 5;
/** A side offer nobody took goes after this many game hours; a rejected one is not offered again for this long. */
const OFFER_HOURS = 48, REJECT_HOURS = 7 * 24;
/** An arc mission turned down, failed or lost comes back after this many hours. */
const ARC_BACK = 24;
/**
 * Real seconds between offers: none for five minutes after the first drive, then one at most every
 * nine, so each new card is an event rather than one of a pile. (Were three and five: players found
 * the cards coming too often, 1 Oct 2026.)
 */
const FIRST_GAP = 300, OFFER_GAP = 540;
/** Real seconds before the director may offer once the tutorial (first drive + getting started) is done or skipped. */
export const AFTER_TUTORIAL = 30;
/** Why nothing but the tutorial's own missions can be taken on while it runs (user rule, 6 Oct 2026). */
const LEARNING_WHY = 'Finish (or skip) the tutorial first';
/**
 * Real seconds between night ops offered while the player flies a helicopter after dark, outside the
 * director's usual gap: a night is under five minutes of play, so an op can't wait for the next slot.
 */
const NIGHT_GAP = 40;
/**
 * After a mission ends, nothing new is offered to a helicopter until REST_MIN–REST_MAX real seconds have
 * passed AND the pilot has flown on to a different town (within REST_TOWN tiles of it), so each job
 * starts somewhere new rather than on the heels of the last.
 */
const REST_MIN = 60, REST_MAX = 120, REST_TOWN = 40;
/** A knack job (missions/workTemplates.ts) turned down comes back after this many game hours, not a week later. */
const WORK_BACK = 12;
/** A dash made with the siren sounded on the way pays this much more. */
const SIREN_PAY = 1.2;
/** "0:42": a dash's clock. */
export const clockText = (s: number): string => `${Math.floor(Math.max(0, s) / 60)}:${String(Math.floor(Math.max(0, s) % 60)).padStart(2, '0')}`;
/** Whether the player is somewhere a night op could be offered: in a helicopter, after dark. */
const nightFlying = (c: MissionCtx): boolean => isHelicopter(c.def) && isNight(((c.hours % 24) + 24) % 24);
/** A template the first drive owns: offered only by the tutorial, and never turned down or given up. */
export const isIntro = (tpl: string): boolean => tpl.startsWith('first:');
/**
 * A faction's Oath step (missions/factionTemplates.ts): the one thing a faction offers at 9,999, so it keeps a
 * slot of its own (never held back by the mission cap) and its diamond stays on the map past MAP_CAP (7 Nov 2026).
 */
export const isOath = (tpl: string): boolean => tpl.startsWith('oath:');
/** Counts against the mission slots: everything but the first drive's missions and the Oaths. */
const slotted = (tpl: string): boolean => !isIntro(tpl) && !isOath(tpl);
/**
 * An offer that waits where its giver is, as a diamond the player drives to, stops in and presses Space at
 * to see the card (missions/wire.ts), rather than popping up wherever they are. The first drive's own work
 * still comes to them, and so does work that is already about where they are: a circuit's as they come up
 * to it, a night op to a helicopter in the air.
 */
/** "21:00". */
const hh = (h: number): string => `${String(((h % 24) + 24) % 24).padStart(2, '0')}:00`;
/** Why a story meeting can't happen now (outside its hours), or null when it can. */
function reachOff(o: Extract<Obj, { t: 'reach' }>, hours: number): string | null {
  if (o.after === undefined || o.before === undefined) return null;
  const h = ((hours % 24) + 24) % 24;
  const inside = o.after <= o.before ? h >= o.after && h < o.before : h >= o.after || h < o.before;
  return inside ? null : `Come back between ${hh(o.after)} and ${hh(o.before)}`;
}
/**
 * A posted offer that opens with a meeting is taken somewhere the meeting isn't: a giver stood at the
 * meeting place itself (a faction's hall, say: "Meet Rourke at the station", taken at the station) is moved
 * to a public building MEET_MIN or more away (kit.ts messageSpot), so the first step is a drive and not a
 * formality (the user, 18 Oct 2026). Where there is nowhere like that, a meeting that asks nothing but
 * turning up is dropped when more follows, and otherwise the offer waits for a better place (false).
 */
export function apartMeeting(m: Mission, c: MissionCtx): boolean {
  const o = m.objs[0];
  if (!o || o.t !== 'reach' || o.door || o.hidden) return true;
  if (Math.hypot(o.at.x - m.giver.at.x, o.at.z - m.giver.at.z) >= MEET_MIN) return true;
  const s = messageSpot(c, o.at);
  if (s) {
    m.giver = { ...m.giver, at: s.at, town: s.town ? townRef(s.w, s.town) : m.giver.town };
    return true;
  }
  const bare = o.hold === undefined && o.after === undefined && !o.with && !o.ride;
  if (bare && m.objs.length > 1) { m.objs = m.objs.slice(1); return true; }
  return false;
}

export const isPosted = (m: Mission): boolean => m.state === 'offered' && !isIntro(m.tpl) && m.kind !== 'op' && !m.tpl.startsWith('circuit:');
/** The most offer diamonds on the map at once (the user, 1 Nov 2026), and how much nearer another must be to take one's place. */
export const MAP_CAP = 2;
const SWAP_GAP = 40;
const COMPASS = ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'];
/**
 * The getting-started track that follows the first drive (game/fleetTrack.ts): a second vehicle, a hired
 * driver out on the road in it, then an HQ upgraded to two slots (a new fleet owns its house, a one-slot
 * HQ, from the start: 14 Oct 2026). `Missions.trackStep` is the step under way, 1–3, or TRACK_DONE.
 */
export const TRACK = ['first:car', 'first:crew', 'first:hq'];
export const TRACK_DONE = TRACK.length + 1;
/**
 * The first drive's three missions, in order (the helping hand was slotted in third on 2 Nov 2026: `ms.intro` saved
 * before then reads one lower past it, game/save.ts). A Friend's Handbrake and Drift the Block were the fourth and
 * fifth until 8 Nov 2026 (the user): a save on one of them picks up past the hand, so the first drive ends, and they
 * come at diamonds later (game/driftLessons.ts).
 */
export const INTRO = ['first:parts', 'first:nitrous', 'first:hand'];
/** The handbrake and the drift (game/driftLessons.ts): first: missions, so locked like the rest, but not the tutorial's to skip. */
export const DRIFT_LESSONS: readonly string[] = ['first:friend', 'first:drift'];
/**
 * The first drive's two control cards (game/tutorial.ts): the welcome card's driving keys and the camera card. A save
 * with none recorded, or one from before the cards (7 Nov 2026), whose tips were taught one by one on the road
 * (OLD_TIPS), counts as having had both: nobody part way through a game is shown them.
 */
export const TAUGHT_ALL = ['drive', 'camera'];
const OLD_TIPS = ['stop', 'turn', 'zoom', 'orbit', 'pitch', 'lock', 'relock', 'sheet'];
/** Standing: the names of the five rungs of the carriage ladder (docs/standing.html). */
export const STANDING = RUNGS.map((r) => r.name);
/** The town ladder's tier (templates' `ladder`) a rung is offered: Territory has none left. */
const LADDER_TIER = [0, 0, 1, 2, 3];

/** What a template reads the world and the company through. */
export interface MissionCtx {
  seed: string;
  hours: number;
  stage: number;
  /** Islands in memory, the player's first. */
  worlds: World[];
  home: World;
  at: Place;
  def: VehicleDef;
  /** Every unit: its model, whether a driver is in it, whether it is a road vehicle, and its pull. */
  units: { uid: number; model: string; name: string; crew: boolean; land: boolean; pull: number }[];
  /** The ridden unit's pull, and its fitted part count. */
  pull: number;
  parts: number;
  drivers: number;
  buildings: number;
  standing(key: string): number;
  owns(w: World, uid: number): boolean;
  /** Why a building is somebody else's (a CPU fleet's or another player's), or null: a knock-down leaves those be. */
  held?(w: World, b: World['allBuildings'][number]): string | null;
  passport: Passport;
  sites(kinds: string[]): Site[];
  /** Car ferries from the harbours of the player's island: where each sails to. */
  ferries: { from: Port; to: { w: World; port: Port } }[];
  beaten: Set<string>;
  done: Map<string, number>;
  /** Top speed of the ridden vehicle, tiles a second. */
  top: number;
  /** Room left in the hold, in cargo units, and cash in hand: what the director weighs an offer against. */
  free: number;
  cash: number;
  /** The fleet slots the player's HQ opens (0 without one): the story chains' second act asks for an HQ. */
  hqSlots?: number;
  /** The fleet's livery colours (body, accent), so a card can show a car painted to stand apart from them. */
  livery?: number[];
  /** Rival firms' depots in memory, world tiles (a tail can follow one of their vans home). */
  depots?: { id: string; name: string; colour: number; x: number; z: number; cell: [number, number]; town: string }[];
  /** Hidden vehicles nobody has claimed in memory, in their cells' tiles (a courier's tail can lead to one). */
  stashes?: { key: string; model: string; cx: number; cz: number; x: number; z: number; place: string }[];
  /** Range (game/range.ts): home, the best of anything, each model's best, and the cells set foot in ("cx,cz"). */
  range?: { home: [number, number]; all: number; model: Record<string, number>; found: string[] };
  /** Every airport surveyed, near and far (world/surveyor.ts): where a Jumbo carrying an act can fly (missions/actTemplates.ts). */
  airports?: KnownAirport[];
}

export interface MissionHost {
  hours(): number;
  ctx(): MissionCtx | null;
  /** The player in world tiles, and how fast they are going; `sounded` a submarine down on the bottom. Null with nobody out. */
  player(): { x: number; z: number; v: number; sounded?: boolean; agl?: number } | null;
  /** Put a delivery objective's goods on the ground, held for this mission. Null while its island isn't in memory. */
  /** Put a delivery step's load out (`also`: its second load instead, the same from and to). */
  spawn(m: Mission, o: Extract<Obj, { t: 'deliver' }>, also?: { cargo: string; value: number }): CargoItem | null;
  /** Let a held load go back to being anybody's. */
  release(it: CargoItem): void;
  /** Give the player one reward. A string when it could not be done (it is then paid in cash). */
  grant(m: Mission, r: Reward): string | null;
  /** A race or a tow step has become the current one (arm it), or is over or abandoned (stand it down). */
  arm(m: Mission, o: Obj): void;
  disarm(m: Mission): void;
  /** Whether a tow's helpers have mustered at the load. */
  crewReady(m: Mission, o: Obj): boolean;
  /** Why the player can't take this right now in what they drive, beyond the engine's own checks. */
  whyNot(m: Mission): string | null;
  /**
   * Could any vehicle the player owns do this (not only the one they are in)? An offer nobody in the fleet
   * could take isn't posted at a diamond: the player isn't sent somewhere to be told they can't.
   */
  couldDo?(m: Mission): boolean;
  /** A rush has one of the map's diamonds (game/rushes), leaving one fewer for offers. */
  rushUp?(): boolean;
  /** How many may be under way at once now, and what opens the next slot (MAX_ACTIVE when absent). */
  activeCap?(): { n: number; next: string };
  /** The model being driven, for a step that must be done in one (`reach.ride`). */
  riding?(): string | null;
  /** Units the player owns now. */
  units(): number;
  /** The fleet slots the HQ opens (0 without one), and vehicles out on the road with a hired driver. */
  hqSlots?(): number;
  driversOut?(): number;
  /** The ridden unit's fitted tier in a slot. */
  fitted(slot: SlotId): number;
  /** How many of the player's vehicles are formed up behind them in Follow mode (a `reach.with` step). */
  followers?(): number;
  /**
   * Range (game/range.ts) for the Surveyor's Commission: home in world tiles, this drive's honest distance from
   * it, cells set foot in, and the kind and model being driven. Null before there is a home.
   */
  range?(): { home: [number, number]; credit: number; found: number; kind: string; model: string } | null;
  announce(title: string, body: string): void;
  /** Pop the offer card for this mission. */
  offer(m: Mission): void;
  /** A mission is done: the card of what it gave. */
  completed(m: Mission, gave: string[]): void;
  changed(): void;
  /** Whether a card or menu is open, so nothing pops over it. */
  busy(): boolean;
}

export interface SavedMissions {
  v: 1;
  next: number;
  day: number;
  list: Mission[];
  arcs: [string, number][];
  standing: [string, number][];
  cool: [string, number][];
  done: [string, number][];
  beaten: string[];
  passport: SavedPassport;
  freeze: [string, number][];
  intro?: number;
  gap?: number;
  /** The control tips the first drive has taught (game/tutorial.ts); absent on saves from before they were spread out, which had them all. */
  taught?: string[];
  /** The getting-started track's step (TRACK); absent on saves from before it. */
  track?: number;
  /** Handbrake drifts the player has made (game/driftLessons.ts); absent on saves from before 8 Nov 2026. */
  drifts?: number;
  /** Seconds of play at which the helping hand may be offered (game/tutorial.ts); absent for at once. */
  handDue?: number;
  /** The best medal won on each delivery mission (missions/medals.ts), by template; absent on saves from before them. */
  medals?: [string, number][];
  /** No mission tracked by choice, so the arrows lead to the cargo aboard; absent (false) on saves from before. */
  loose?: boolean;
}

export class Missions {
  readonly bus = new Bus();
  readonly passport = new Passport();
  list: Mission[] = [];
  /** Per arc, the index of the next template to offer; its length once the capstone is done. */
  readonly arcs = new Map<string, number>();
  /**
   * Standing is the player's rung of each town's carriage ladder (docs/standing.html), keyed like the ledger
   * ("cx,cz#id"): the host reads it, lists it, and credits it when a mission makes a town talk you up.
   */
  rungOf: (key: string) => number = () => 0;
  rungsAll: () => { key: string; rung: number }[] = () => [];
  talkUp: (key: string, n: number) => number = () => 0;
  /** Mission standing from a save made before it was the carriage's: the host tops the carriage up with it once. */
  readonly legacy = new Map<string, number>();
  /** Templates (with their giver) that may not be offered again until this hour. */
  private cool = new Map<string, number>();
  /** How many times each template has been finished. */
  readonly done = new Map<string, number>();
  /** The best medal won on each delivery mission, by template: 1 bronze, 2 silver, 3 gold (missions/medals.ts). */
  readonly medals = new Map<string, Medal>();
  readonly beaten = new Set<string>();
  private nextId = 1;
  private lastDay = -1;
  private fillTimer = 0;
  private tickTimer = 0;
  private nightGap = 0;
  /** Real seconds left of the helicopter's rest after the last mission ended, and the town it ended at. */
  private rest = 0;
  private restTown: string | null = null;
  /** The offers whose diamonds are up (onMap), kept from one frame to the next so two near-equal ones don't swap. */
  private onShow: number[] = [];
  /** While the first-drive tutorial runs, nothing else is offered and nobody announces work. */
  hold = false;
  /** Which of the first drive's three missions is current (1–3), or 0 once it is over (or never ran). Saved. */
  intro = 0;
  /** Handbrake drifts the player has made, counted by game/driftLessons.ts. Saved. */
  drifts = 0;
  /** Seconds of play at which the helping hand may be offered (game/tutorial.ts HAND_LATER); 0 for at once. Saved. */
  handDue = 0;
  /** Real seconds before the director may offer the next mission. Saved. */
  gap = 0;
  /**
   * The getting-started track after the first drive (game/fleetTrack.ts): 0 not yet begun, 1–3 the step
   * under way (TRACK), TRACK_DONE when the player has a second vehicle, a driver out and a two-slot HQ. Saved.
   */
  trackStep = 0;
  /**
   * The player has let go of every mission (clicked the tracked one again): nothing is tracked until they pick
   * one, and the arrows go to the cargo aboard (the user, 29 Oct 2026: two missions kept the arrows for good).
   */
  loose = false;
  /** The control tips taught so far, each once, when it first comes up on the road (game/tutorial.ts). Saved. */
  readonly taught = new Set<string>();
  /** Loads on the ground for a mission, by mission id. */
  private items = new Map<number, CargoItem>();
  /** A delivery step's second load (`deliver.also`), put out beside the first, by mission id. */
  private alsoItems = new Map<number, CargoItem>();
  /** A mission has just been taken on: the first drive's helping hand joins the fleet at that moment (missions/wire.ts). */
  onAccept: ((m: Mission) => void) | null = null;
  /** An offer turned down (the play reports count it: net/stats.ts). */
  onReject: ((m: Mission) => void) | null = null;
  /** Missions whose player has pulled up at the place in the wrong vehicle, told so once. */
  private wrongRide = new Set<number>();
  /** When a convoy's load was last held back for want of its vehicles, by mission: told again after a while. */
  private heldTold = new Map<number, number>();
  /** Seconds the player has stayed stopped at a `reach.hold` step, by mission. */
  private held = new Map<number, number>();

  constructor(private host: MissionHost) {
    this.bus.on('delivered', ({ it }) => this.onDelivered(it));
    this.bus.on('ferried', () => this.advanceWhere((o) => o.t === 'ferry'));
    // road tiles, unlocks and asks, counted up to the step's n (the teaching missions, game/coach.ts)
    this.bus.on('made', (e) => {
      for (const m of [...this.active]) {
        const o = m.objs[m.step];
        if (!o || o.t !== 'make' || o.what !== e.what) continue;
        // the bridge built: the next step's ring goes where it actually stands ("Cross your new bridge")
        const next = m.objs[m.step + 1];
        if (e.at && next?.t === 'reach' && next.at.name === 'your new bridge') next.at = { ...next.at, x: e.at.x, z: e.at.z, cell: e.at.cell };
        m.count = Math.min(o.n, m.count + e.n);
        if (m.count >= o.n) this.advance(m); else this.host.changed();
      }
    });
    this.bus.on('stamped', (e) => this.advanceWhere((o) => o.t === 'visit' && o.what === e.what && (o.key === '*' || o.key === e.key)));
    this.bus.on('fitted', (e) => this.advanceWhere((o) => o.t === 'fit' && (o.slot === null || o.slot === e.slot) && e.tier > 0));
    this.bus.on('raceEnd', (e) => this.onRaceEnd(e.id, e.won, e.margin));
    this.bus.on('towEnd', (e) => this.onTowEnd(e.id, e.ok, e.snaps, e.scrapes));
    this.bus.on('opEnd', (e) => this.onOpEnd(e.id, e.ok, e.score, e.line));
    this.bus.on('tailEnd', (e) => this.onTailEnd(e.id, e.ok, e.made, e.score, e.line));
    this.bus.on('circuitLap', (e) => this.onLap(e.key, e.secs));
    this.bus.on('circuitRace', (e) => this.onCircuitRace(e.key, e.place, e.of));
    this.bus.on('drifted', (e) => {
      for (const m of this.active) {
        const o = m.objs[m.step];
        if (o?.t === 'drift' && o.dir === e.dir && m.step === m.objs.length - 1) m.outcome = 'Both corners, sideways';
      }
      this.advanceWhere((o) => o.t === 'drift' && o.dir === e.dir);
    });
  }

  /**
   * The single gate for the user's rule (6 Oct 2026): "until the player completes (or purposefully
   * abandons) tutorial missions, no other missions should be introduced or available to the player".
   * True while the first drive (game/tutorial.ts) or the getting-started track after it
   * (game/fleetTrack.ts) runs. Every other source of missions asks this: the director (fill, which also
   * makes night ops, circuit work, tails and rescues), offers popping up, diamonds and pins (they read
   * `offered`, which hides other work while it is true), accept/adopt (taverns), tavern jobs and night-run
   * contacts (main.ts). `skipTutorial` ends it on purpose.
   */
  learning(): boolean {
    return this.hold || this.intro > 0 || (this.trackStep > 0 && this.trackStep < TRACK_DONE);
  }
  /** Was it learning last frame: the director is woken when the tutorial ends. */
  private wasLearning = false;
  /** The tutorial has been skipped (game/tutorial.ts puts its guide away). */
  skipped: (() => void) | null = null;

  /** Offers waiting; while the tutorial runs only its own (anything else made before is kept, unseen). */
  get offered(): Mission[] {
    const l = this.learning();
    return this.list.filter((m) => m.state === 'offered' && (!l || isIntro(m.tpl)));
  }
  get active(): Mission[] { return this.list.filter((m) => m.state === 'active'); }
  get finished(): Mission[] { return this.list.filter((m) => m.state === 'done' || m.state === 'failed').sort((a, b) => (b.ended ?? 0) - (a.ended ?? 0)); }
  get tracked(): Mission | null {
    const act = this.active;
    return act.find((m) => m.tracked) ?? (this.loose ? null : act.sort((a, b) => b.step / b.objs.length - a.step / a.objs.length)[0] ?? null);
  }
  byId(id: number): Mission | null { return this.list.find((m) => m.id === id) ?? null; }

  /** A town's standing: the player's rung there, 0–4 (RUNG). */
  standingOf(key: string): number { return this.rungOf(key); }
  townKeyOf(t: TownRef): string { return `${t.cell[0]},${t.cell[1]}#${t.id}`; }

  clear(): void {
    for (const m of this.active) this.stopRunning(m);
    this.list = [];
    this.arcs.clear();
    this.legacy.clear();
    this.cool.clear();
    this.done.clear();
    this.medals.clear();
    this.beaten.clear();
    this.passport.clear();
    this.nextId = 1;
    this.lastDay = -1;
    this.intro = 0;
    this.drifts = 0;
    this.handDue = 0;
    this.gap = 0;
    this.taught.clear();
    this.trackStep = 0;
    this.rest = 0;
    this.restTown = null;
    this.wasLearning = false;
  }

  /**
   * The first drive is over. The getting-started track follows (game/fleetTrack.ts); it is begun here so
   * the gate (`learning`) never opens between the two, and the rest of the game's work comes after it.
   */
  introEnd(): void {
    this.intro = 0;
    this.hold = false;
    this.gap = FIRST_GAP;
    this.fillTimer = 0;
    if (this.trackStep === 0) this.trackStep = 1;
  }

  /**
   * The player skipped the tutorial on purpose (the journal's "Skip the tutorial"): its missions are
   * dropped (one under way ends as skipped), the getting-started track is marked done, and the rest of the
   * game's work opens straight away.
   */
  skipTutorial(): void {
    if (!this.learning()) return;
    const hours = this.host.hours();
    for (const m of this.list) {
      if (!isIntro(m.tpl) || DRIFT_LESSONS.includes(m.tpl)) continue;
      if (m.state === 'active') {
        this.stopRunning(m);
        m.state = 'failed';
        m.outcome = 'Skipped';
        m.ended = hours;
        m.tracked = false;
      } else if (m.state === 'offered') m.state = 'rejected';
    }
    this.list = this.list.filter((m) => m.state !== 'rejected');
    this.intro = 0;
    this.hold = false;
    this.trackStep = TRACK_DONE;
    this.skipped?.();
    this.host.changed();
  }

  // ---- the frame ------------------------------------------------------------------------------

  update(dt: number): void {
    const hours = this.host.hours();
    const day = Math.floor(hours / 24);
    // deadlines, a dash's clock, and offers that have waited long enough
    for (const m of this.list) {
      if (m.state === 'active' && m.notes?.left !== undefined && m.objs[m.step]?.t === 'deliver') {
        m.notes.left -= dt;
        // the patient stays aboard as an ordinary fare: the call is lost, not the patient
        if (m.notes.left <= 0) { this.fail(m, 'Out of time', 'Out of time: no bonus, but get them in all the same'); continue; }
      }
      // a delivery's medal clock, from its first load aboard to its last drop (missions/medals.ts)
      if (m.state === 'active' && m.notes?.mT !== undefined && !m.notes.mX) m.notes.mT += dt;
      if (m.state === 'active' && m.due !== null && hours > m.due) this.fail(m, 'Out of time');
      // the first drive's offers wait for as long as it takes: its guide offers each one once
      else if (m.state === 'offered' && !m.arc && !isIntro(m.tpl) && hours - m.posted > OFFER_HOURS) { m.state = 'rejected'; this.host.changed(); }
    }
    this.list = this.list.filter((m) => m.state !== 'rejected');
    // the tutorial just ended (done or skipped): the director may offer soon, not a whole gap later
    const learning = this.learning();
    if (this.wasLearning && !learning) { this.gap = Math.min(this.gap, AFTER_TUTORIAL); this.fillTimer = 0; }
    this.wasLearning = learning;
    if (!learning) this.gap = Math.max(0, this.gap - dt);
    this.nightGap = Math.max(0, this.nightGap - dt);
    this.rest = Math.max(0, this.rest - dt);
    // the director fills the list on the day's turn, and every little while in case the player has moved on
    this.fillTimer -= dt;
    if (day !== this.lastDay || this.fillTimer <= 0) {
      this.lastDay = day;
      this.fill();
      // nothing found yet (the island's sites are still being laid out, say): look again soon
      this.fillTimer = this.offered.length ? 20 : 3;
    }
    this.tickTimer -= dt;
    if (this.tickTimer <= 0) {
      this.tickTimer = 0.25;
      for (const m of this.active) this.tick(m);
      this.maybeOffer();
    }
  }

  /** The objectives that are measured rather than told: arriving, owning, a crew mustered, goods waiting to be put down. */
  private tick(m: Mission): void {
    const o = m.objs[m.step];
    if (!o) return;
    const p = this.host.player();
    switch (o.t) {
      case 'reach':
        // a door waits for Space in its entrance ring (`enter`)
        if (!o.door && p && Math.hypot(p.x - o.at.x, p.z - o.at.z) <= o.r) {
          if ((o.stop || o.hold) && Math.abs(p.v) > 0.35) { this.held.delete(m.id); break; }
          // under the waves: only on the bottom (docs/underwater.html)
          if (o.dived && !p.sounded) {
            this.held.delete(m.id);
            if (!this.wrongRide.has(m.id)) { this.wrongRide.add(m.id); this.host.announce(m.title, 'Go down to the bottom here: dive (Shift), stop, then Shift again'); }
            break;
          }
          // a crop duster's pass: only low over the field
          if (o.low !== undefined && (p.agl ?? 0) > o.low) {
            if (!this.wrongRide.has(m.id)) { this.wrongRide.add(m.id); this.host.announce(m.title, 'Too high to spray: come down low over the field and fly through the ring again'); }
            break;
          }
          if (o.ride && !o.ride.ids.includes(this.host.riding?.() ?? '')) {
            // told once each time they pull up in the wrong thing
            if (!this.wrongRide.has(m.id)) { this.wrongRide.add(m.id); this.host.announce(m.title, `Come back in ${o.ride.label}`); }
            break;
          }
          // the story's meetings: only in their hours, only with the fleet behind, and held for a while
          const off = reachOff(o, this.host.hours());
          if (off) {
            if (!this.wrongRide.has(m.id)) { this.wrongRide.add(m.id); this.host.announce(m.title, off); }
            break;
          }
          if (o.with && (this.host.followers?.() ?? 0) < o.with) {
            if (!this.wrongRide.has(m.id)) { this.wrongRide.add(m.id); this.host.announce(m.title, `Come back with ${o.with} of your vehicles following you: F, then Follow`); }
            break;
          }
          if (o.hold) {
            const t = (this.held.get(m.id) ?? 0) + 0.25;
            this.held.set(m.id, t);
            if (t < o.hold) { if (Math.floor(t) !== Math.floor(t - 0.25) && Math.floor(t) % 5 === 0) this.host.changed(); break; }
            this.held.delete(m.id);
          }
          this.advance(m);
        } else if (p) { this.wrongRide.delete(m.id); this.held.delete(m.id); }
        break;
      case 'own':
        if (this.host.units() >= o.n) this.advance(m);
        break;
      case 'hq':
        if ((this.host.hqSlots?.() ?? 0) >= o.slots) this.advance(m);
        break;
      case 'driving':
        if ((this.host.driversOut?.() ?? 0) >= o.n) this.advance(m);
        break;
      case 'fit':
        if (o.slot && this.host.fitted(o.slot) > 0) this.advance(m);
        break;
      case 'crew':
        if (this.host.crewReady(m, o)) this.advance(m);
        break;
      case 'speed':
        if (p && p.v * 12 >= o.kmh) { m.outcome = `Hit ${speedText(p.v * 12)}`; this.advance(m); }
        break;
      case 'range': {
        const r = this.host.range?.();
        if (r && r.credit >= o.tiles && (!o.kind || r.kind === o.kind) && (!o.model || r.model === o.model)) {
          m.outcome = `${Math.round(r.credit).toLocaleString('en-US')} tiles out`;
          this.advance(m);
        }
        break;
      }
      case 'discover': {
        const r = this.host.range?.();
        if (!r) break;
        // counted from when the step came up: the cells found before it are noted once
        m.notes ??= {};
        const k = `found${m.step}`;
        if (m.notes[k] === undefined) { m.notes[k] = r.found; this.host.changed(); }
        if (r.found - m.notes[k] !== m.count) { m.count = Math.min(o.n, r.found - m.notes[k]); this.host.changed(); }
        if (m.count >= o.n) this.advance(m);
        break;
      }
      case 'deliver': {
        if (!this.items.has(m.id) && !m.notes?.mainDone) {
          const it = this.host.spawn(m, o);
          if (it) this.items.set(m.id, it);
        }
        if (o.also && !this.alsoItems.has(m.id) && !m.notes?.alsoDone) {
          const it = this.host.spawn(m, o, o.also);
          if (it) this.alsoItems.set(m.id, it);
        }
        // a dash: the clock starts the moment the load is aboard
        const it = this.items.get(m.id);
        if (o.clock && it && it.marker === null && m.notes?.left === undefined) {
          m.notes = { ...(m.notes ?? {}), left: o.clock };
          this.host.announce(m.title, `${clockText(o.clock)} to get them to the ${o.to.name.replace(/^the /, '')}${o.ride ? ' · K for the siren' : ''}`);
          this.host.changed();
        }
        // a delivery mission's medal times: set once, the moment its first load is aboard, for what picked it up
        if (it && it.marker === null && m.notes?.mT === undefined && medalled(m)) {
          const c = this.host.ctx();
          if (c) {
            const run = medalRun(m, c.def, c.worlds);
            const t = medalTimes(run.tiles, run.stops, c.def.topSpeed);
            m.notes = { ...(m.notes ?? {}), mT: 0, mB: t.b, mS: t.s, mG: t.g };
            this.host.announce(m.title, `Medal times · 🥇 ${clockText(t.g)} · 🥈 ${clockText(t.s)} · 🥉 ${clockText(t.b)}`);
            this.host.changed();
          }
        }
        break;
      }
      default:
    }
  }

  /** The player went in at a mission's door (stopped in its entrance ring and pressed Space). */
  enter(id: number): void {
    const m = this.active.find((q) => q.id === id);
    const o = m?.objs[m.step];
    if (m && o && o.t === 'reach' && o.door) this.advance(m);
  }

  /**
   * The offers on the map: no more than MAP_CAP diamonds at once (the user, 1 Nov 2026), the nearest ones the
   * vehicle being driven could do. One up stays up while it can, unless another comes SWAP_GAP tiles nearer than
   * the farthest; the rest wait in the journal and take a slot when one frees.
   */
  onMap(): Mission[] {
    const p = this.host.player();
    const far = (m: Mission): number => (p ? Math.hypot(m.giver.at.x - p.x, m.giver.at.z - p.z) : 0);
    const can = this.offered.filter((m) => !isPosted(m) || this.host.couldDo?.(m) !== false).sort((a, b) => far(a) - far(b));
    // an Oath waiting at its hall is always up, over and above the cap
    const oaths = can.filter((m) => isOath(m.tpl));
    for (const m of oaths) can.splice(can.indexOf(m), 1);
    const up = can.filter((m) => this.onShow.includes(m.id));
    const cap = MAP_CAP - (this.host.rushUp?.() ? 1 : 0);
    while (up.length > cap) up.pop();
    for (const m of can) if (up.length < cap && !up.includes(m)) up.push(m);
    const next = can.find((m) => !up.includes(m));
    if (next && up.length && cap > 0) {
      const worst = up.reduce((a, b) => (far(b) > far(a) ? b : a));
      if (far(next) + SWAP_GAP < far(worst)) up[up.indexOf(worst)] = next;
    }
    up.push(...oaths);
    this.onShow = up.map((m) => m.id);
    return up;
  }

  /** Open the card for a new offer the next time the player stops, once; it waits in the journal after that. */
  private maybeOffer(): void {
    if (this.host.busy() || this.hold) return;
    const p = this.host.player();
    // a new offer at a diamond: said once, with where it is, wherever the player is and however fast (only once it is on the map)
    if (p && !this.slotsFull()) {
      const q = this.onMap().find((x) => isPosted(x) && !x.marked && !this.partsHad(x));
      if (q) {
        q.marked = true;
        const dx = q.giver.at.x - p.x, dz = q.giver.at.z - p.z;
        const way = COMPASS[((Math.round(Math.atan2(dx, -dz) / (Math.PI / 4)) % 8) + 8) % 8];
        this.host.announce(`◆ ${q.title}`, `${q.giver.name} has work · ${q.giver.at.name}, ${Math.round(Math.hypot(dx, dz))} tiles ${way} · drive to the diamond and press Space`);
        this.host.changed();
        return;
      }
    }
    if (!p || Math.abs(p.v) > 1) return;
    if (this.restTown !== null) { const c = this.host.ctx(); if (c && this.resting(c)) return; }
    // with every slot full, only the getting-started missions come up (they keep a slot of their own)
    const full = this.slotsFull();
    // an offer made before the part it pays in was fitted is quietly dropped, not shown
    // and one whose every goal the player has since met is taken down, waiting at its diamond or not (16 Oct 2026)
    const stale = this.offered.filter((q) => (!q.shown && this.partsHad(q)) || this.alreadyMet(q));
    if (stale.length) { this.list = this.list.filter((q) => !stale.includes(q)); this.host.changed(); }
    // only what comes to the player pops up; the rest waits at its diamond
    const m = this.offered.find((q) => !q.shown && !isPosted(q) && (!full || isIntro(q.tpl)));
    if (!m) return;
    m.shown = true;
    this.host.offer(m);
  }

  /**
   * Is every slot for ordinary missions taken (missions/wire.ts activeCap)? Then nothing new is offered
   * until one is done or given up. The getting-started missions never count against the slots, and are
   * offered whatever this says (game/tutorial.ts, game/fleetTrack.ts).
   */
  slotsFull(): boolean {
    const cap = this.host.activeCap?.() ?? { n: MAX_ACTIVE, next: '' };
    return this.active.filter((q) => slotted(q.tpl)).length >= cap.n;
  }

  // ---- the director ---------------------------------------------------------------------------

  /** What each thread is short of for the stage the player is at: the director offers the hungriest first. */
  hunger(c: MissionCtx): Record<Thread, number> {
    const want = [
      { car: 0, fleet: 1, hold: 0, town: 1 },
      { car: 1, fleet: 2, hold: 0, town: 2 },
      { car: 2, fleet: 3, hold: 1, town: 3 },
      { car: 3, fleet: 4, hold: 2, town: 4 },
      { car: 5, fleet: 6, hold: 4, town: 6 },
    ][Math.min(4, c.stage)];
    const known = this.rungsAll().length;
    return {
      car: want.car - c.parts,
      fleet: want.fleet - c.units.length,
      hold: want.hold - c.buildings,
      town: want.town - known,
    };
  }

  /**
   * Offer the next mission, if it is time. Every candidate the world can bind now — the arcs' next
   * steps, each nearby town's next ask on its ladder, side jobs — is weighed against where the player
   * is, what they drive, what they carry and what they have in the bank, and only the best is offered.
   * Then the director waits OFFER_GAP real seconds before it looks again.
   */
  fill(): void {
    // nothing at all (night ops and circuit work included) while the tutorial runs
    if (this.learning()) return;
    // a faction's Oath, once its bar is at 9,999 and the fleet has the ride: whatever the gap or the slots
    if (this.nearOath()) return;
    // no new work while every mission slot is taken: none waiting to be turned down when a slot frees
    if (this.slotsFull()) return;
    { const c = this.host.ctx(); if (c && this.resting(c)) return; }
    // after dark in a helicopter, a night op when none is waiting or under way, whatever the usual gap
    if (this.nightGap <= 0 && !this.list.some((m) => m.kind === 'op' && (m.state === 'offered' || m.state === 'active'))) {
      const c = this.host.ctx();
      if (c && nightFlying(c) && this.offered.length < MAX_OFFERED) {
        this.nightGap = NIGHT_GAP;
        const op = this.rank(c).find((q) => q.m.kind === 'op');
        if (op) {
          this.list.push(op.m);
          this.host.announce(`${op.m.giver.name} has a night op`, `${op.m.title} · J for the journal`);
          this.host.changed();
          return;
        }
      }
    }
    if (this.nearEvent()) return;
    if (this.nearCircuit()) return;
    if (this.nearWork()) return;
    if (this.nearConvoy()) return;
    if (this.nearActs()) return;
    if (this.gap > 0) return;
    const c = this.host.ctx();
    if (!c || this.offered.length >= MAX_OFFERED) return;
    // work posted at a diamond must be work the fleet can do: none of it waits for a vehicle not yet bought
    const ranked = this.rank(c).filter((q) => !isPosted(q.m) || this.host.couldDo?.(q.m) !== false);
    if (!ranked.length) return;
    const best = ranked[0].m;
    this.list.push(best);
    this.gap = OFFER_GAP;
    // a posted offer is announced with where its diamond is (maybeOffer); anything else as before
    if (!isPosted(best)) this.host.announce(`${best.giver.name} has work`, `${best.title} · J for the journal`);
    this.host.changed();
  }

  /**
   * The factions' Oaths (missions/factionTemplates.ts): each faction's next step posted at its hall as soon as its
   * gate opens, whatever the gap, the slots or how many offers wait, so a player who has worked a bar up to 9,999
   * finds it on the map rather than waiting for the director to pick it from everything else (7 Nov 2026). With
   * no hall in reach it looks again in a game hour. True when something was offered.
   */
  private nearOath(): boolean {
    const c = this.host.ctx();
    if (!c) return false;
    for (const arc of ARCS) {
      // and a Sworn player's one invitation to the stronghold (0.8.0, missions/factionTemplates.ts swornVisit)
      if (!arc.id.startsWith('oath-') && !arc.id.startsWith('sworn-')) continue;
      const id = arc.tpls[this.arcs.get(arc.id) ?? 0];
      if (!id || this.running(id) || this.cooling(id, '')) continue;
      const tp = templateById(id);
      if (!tp || tp.gate(c, this)) continue;
      const m = this.make(tp, c, hashString(`${c.seed}|${id}|${Math.floor(c.hours)}`));
      if (!m) { this.cool.set(`${id}|`, this.host.hours() + 1); continue; }
      this.list.push(m);
      this.host.changed();
      return true;
    }
    return false;
  }

  /**
   * An event near the player taking entries (docs/events.html, game/missions/eventTemplates.ts): its entry waits
   * at its diamond, whatever the gap, once per event. An entry still waiting when the event stops taking them is
   * taken down. True when something was offered.
   */
  private nearEvent(): boolean {
    const open = new Set(EVENT_ENTRIES.list.map((e) => e.key));
    const gone = this.list.filter((m) => m.tpl.startsWith('event:') && m.state === 'offered' && !open.has(m.notes?.event ?? -1));
    if (gone.length) { this.list = this.list.filter((m) => !gone.includes(m)); this.host.changed(); }
    const c = this.host.ctx();
    if (!c || this.offered.length >= MAX_OFFERED) return false;
    if (this.list.some((m) => m.tpl.startsWith('event:') && (m.state === 'offered' || m.state === 'active'))) return false;
    for (const e of openEntries(c)) {
      if (this.cooling('event', e.id)) continue;
      this.cool.set(`event|${e.id}`, this.host.hours() + 72);
      for (const tp of TEMPLATES) {
        if (tp.id !== `event:${e.kind}` || tp.gate(c, this)) continue;
        const m = this.make(tp, c, hashString(`${c.seed}|${e.id}|${tp.id}`));
        if (!m) continue;
        m.notes = { ...(m.notes ?? {}), event: e.key };
        this.list.push(m);
        this.host.changed();
        return true;
      }
    }
    return false;
  }

  /**
   * Coming up to a circuit (docs/circuits.html): its work is offered there and then, whatever the gap,
   * once per circuit every half a day or so. True when something was offered.
   */
  private nearCircuit(): boolean {
    const c = this.host.ctx();
    if (!c || c.def.kind !== 'land' || this.offered.length >= MAX_OFFERED) return false;
    if (this.list.some((m) => m.tpl.startsWith('circuit:') && (m.state === 'offered' || m.state === 'active'))) return false;
    const near = circuitsNear(c, CIRCUIT_NEAR)[0];
    if (!near || this.cooling('circuit', near.key)) return false;
    const h0 = hashString(`${c.seed}|circuit|${near.key}|${Math.floor(c.hours / 12)}`);
    const cands: Mission[] = [];
    for (const tp of TEMPLATES) {
      if (!tp.id.startsWith('circuit:') || this.running(tp.id) || this.cooling(tp.id, '') || tp.gate(c, this)) continue;
      const m = this.make(tp, c, hashString(`${h0}|${tp.id}`));
      if (m) cands.push(m);
    }
    this.cool.set(`circuit|${near.key}`, this.host.hours() + 12);
    const best = cands.map((m) => ({ m, s: this.relevance(m, c) + (m.seed % 7) * 0.4 })).sort((a, b) => b.s - a.s)[0]?.m;
    if (!best) return false;
    this.list.push(best);
    this.host.announce(`${best.giver.name} has work`, `${best.title} · J for the journal`);
    this.host.changed();
    return true;
  }

  /**
   * Work for the knack of the vehicle being driven (missions/workTemplates.ts): in the Dozer, the mayor's
   * knock-down; in an ambulance, an emergency dash. It is about what the player is in, so it is offered
   * whatever the gap, one at a time, each again only after its cooldown. True when something was offered.
   */
  private nearWork(): boolean {
    const c = this.host.ctx();
    if (!c || this.offered.length >= MAX_OFFERED) return false;
    if (this.list.some((m) => m.tpl.startsWith('work:') && (m.state === 'offered' || m.state === 'active'))) return false;
    for (const tp of TEMPLATES) {
      if (!tp.id.startsWith('work:') || this.cooling(tp.id, '') || tp.gate(c, this)) continue;
      const m = this.make(tp, c, hashString(`${c.seed}|${tp.id}|${Math.floor(c.hours)}`));
      // nothing in reach: look again in a game hour, not every few seconds
      this.cool.set(`${tp.id}|`, this.host.hours() + (m ? tp.cooldown ?? 4 : 1));
      if (!m) continue;
      this.list.push(m);
      this.host.changed();
      return true;
    }
    return false;
  }

  /**
   * The convoys (missions/convoyTemplates.ts): each offered once, in order, when the fleet is big enough to
   * make it, whatever the gap; turned down, it comes back after WORK_BACK; done, never again.
   */
  private nearConvoy(): boolean {
    const c = this.host.ctx();
    if (!c || this.offered.length >= MAX_OFFERED) return false;
    if (this.list.some((m) => m.tpl.startsWith('convoy:') && (m.state === 'offered' || m.state === 'active'))) return false;
    for (const tp of TEMPLATES) {
      if (!tp.id.startsWith('convoy:') || this.cooling(tp.id, '') || tp.gate(c, this)) continue;
      const m = this.make(tp, c, hashString(`${c.seed}|${tp.id}|${Math.floor(c.hours)}`));
      if (!m) { this.cool.set(`${tp.id}|`, this.host.hours() + 1); continue; }
      this.list.push(m);
      this.host.announce(`${m.giver.name}: a convoy`, `${m.title} · J for the journal`);
      this.host.changed();
      return true;
    }
    return false;
  }

  /**
   * The acts' rides (missions/actTemplates.ts): a band or a side to get to its next stadium, offered about what is
   * driven (a bus, a passenger train, the Jumbo) whatever the gap, one at a time, each template again after its
   * cooldown. One whose show or kick-off has come before it was taken is taken down. True when something was offered.
   */
  private nearActs(): boolean {
    ACT_BOARD.missions ??= () => this.list;
    const now = this.host.hours();
    const late = this.list.filter((m) => m.tpl.startsWith('act:') && m.state === 'offered' && (m.notes?.by ?? Infinity) <= now + 0.5);
    if (late.length) { this.list = this.list.filter((m) => !late.includes(m)); this.host.changed(); }
    const c = this.host.ctx();
    if (!c || this.offered.length >= MAX_OFFERED) return false;
    if (this.list.some((m) => m.tpl.startsWith('act:') && (m.state === 'offered' || m.state === 'active'))) return false;
    for (const tp of TEMPLATES) {
      if (!tp.id.startsWith('act:') || this.cooling(tp.id, '') || tp.gate(c, this)) continue;
      const m = this.make(tp, c, hashString(`${c.seed}|${tp.id}|${Math.floor(c.hours)}`));
      this.cool.set(`${tp.id}|`, now + (m ? tp.cooldown ?? 2 : 1));
      if (!m) continue;
      this.list.push(m);
      this.host.changed();
      return true;
    }
    return false;
  }

  /** Is this ride (a tour's leg `t<id>`, a fixture `f<hash>`) on the list already, or lately turned down? */
  actTaken(key: string): boolean {
    return this.cooling('act', key) || this.list.some((m) => m.tpl.startsWith('act:') && actKeyOf(m.notes) === key);
  }

  /**
   * Whether a load may not be put down yet: a convoy's (`deliver.with`) waits until that many of the player's
   * vehicles are formed up behind them. The reason (told now and then while they wait), or null to let it go.
   */
  heldBack(it: CargoItem): string | null {
    for (const m of this.active) {
      const o = m.objs[m.step];
      if (!o || o.t !== 'deliver' || !o.with || (this.items.get(m.id) !== it && this.alsoItems.get(m.id) !== it)) continue;
      if ((this.host.followers?.() ?? 0) >= o.with) return null;
      // the helping hand's own load waits for her, by name
      const why = o.also ? `Wait for ${m.giver.name.split(' ')[0]} to pull in behind you before you unload`
        : `Wait for the convoy: ${o.with} of your vehicles following you (F, then Follow)`;
      const now = this.host.hours();
      if (now - (this.heldTold.get(m.id) ?? -1) > 0.4) { this.heldTold.set(m.id, now); this.host.announce(m.title, why); }
      return why;
    }
    return null;
  }

  /** Whether a mission's load can't be picked up in this model: it rides only in its `ride` (an act's bus, a patient's Medic). */
  loadWhy(it: CargoItem, model: string): string | null {
    for (const m of this.active) {
      const o = m.objs[m.step];
      if (o && o.t === 'deliver' && o.ride && this.items.get(m.id) === it && !o.ride.ids.includes(model)) return `Take it in ${o.ride.label}`;
    }
    return null;
  }

  /** Everything that could be offered now, bound, best first. */
  rank(c: MissionCtx): { m: Mission; s: number }[] {
    const h0 = hashString(`${c.seed}|missions|${Math.floor(c.hours / 24)}`);
    const cands: Mission[] = [];
    const bind = (tp: Template, salt: string, town?: { w: World; t: World['towns'][number] }): boolean => {
      const m = this.make(tp, c, hashString(`${h0}|${tp.id}|${salt}`), town);
      if (m) cands.push(m);
      return !!m;
    };
    // 1. every arc's next step, once its gate is open
    for (const arc of ARCS) {
      const i = this.arcs.get(arc.id) ?? 0;
      const id = arc.tpls[i];
      if (!id || this.running(id) || this.cooling(id, '')) continue;
      const tp = templateById(id);
      if (!tp || tp.gate(c, this)) continue;
      const ok = bind(tp, `arc${i}`);
      // a step whose every goal the player already has (a part fitted, vehicles owned): passed over, and the
      // chain goes on to its next step (the user, 16 Oct 2026: "Needs More Go" offered with an engine fitted)
      const met = ok ? cands[cands.length - 1] : null;
      if (met && met.tpl === id && this.alreadyMet(met)) {
        cands.pop();
        this.done.set(id, (this.done.get(id) ?? 0) + 1);
        this.arcs.set(arc.id, i + 1);
        this.host.changed();
        continue;
      }
      // a long story's step with nowhere in reach to happen (docs/storychains.html): after five days of
      // looking it is passed over, so no chain is ever stuck on its county's geography
      if (!ok && arc.acts && this.storyMissed?.(arc.id, id, i, Math.floor(c.hours / 24))) {
        this.arcs.set(arc.id, i + 1);
        this.host.changed();
      }
    }
    // 2. the towns near the player, each asking the next thing on its ladder
    const towns = c.worlds.flatMap((w) => w.towns.map((t) => ({ w, t }))).filter(({ w, t }) => w.cx === c.home.cx && w.cz === c.home.cz || Math.hypot(w.ox + t.x0 + t.size / 2 - c.at.x, w.oz + t.z0 + t.size / 2 - c.at.z) < 260)
      .sort((a, b) => dist(a, c) - dist(b, c)).slice(0, 4);
    for (const { w, t } of towns) {
      const key = `${w.cx},${w.cz}#${t.id}`;
      if (this.list.some((m) => (m.state === 'offered' || m.state === 'active') && m.giver.town && this.townKeyOf(m.giver.town) === key)) continue;
      const rung = this.standingOf(key);
      if (rung >= RUNG.territory || this.cooling('town', key)) continue;
      const level = LADDER_TIER[rung];
      const bag = TEMPLATES.filter((tp) => tp.ladder === level && !tp.gate(c, this, { w, t }));
      const start = bag.length ? hashString(`${h0}|${key}`) % bag.length : 0;
      for (let k = 0; k < bag.length; k++) {
        if (bind(bag[(start + k) % bag.length], key, { w, t })) break;
      }
    }
    // 3. side jobs, the hungriest thread first, with no more than two waiting at once
    const hunger = this.hunger(c);
    if (this.offered.filter((m) => !m.arc && !m.tpl.startsWith('t:')).length < 2) {
      // night ops first while flying a helicopter after dark: it is the only time they can be done
      const night = nightFlying(c);
      const side = TEMPLATES.filter((tp) => tp.side && !this.running(tp.id) && !this.cooling(tp.id, '') && !tp.gate(c, this))
        .sort((a, b) => (night ? +(b.kind === 'op') - +(a.kind === 'op') : 0) || hunger[b.thread] - hunger[a.thread] || (this.done.get(a.id) ?? 0) - (this.done.get(b.id) ?? 0));
      for (const tp of side.slice(0, 6)) bind(tp, 'side');
    }
    // nothing that pays in a part the car already has (docs: the user asked, 4 Oct 2026)
    // nor anything whose every goal the player already has (16 Oct 2026)
    return cands.filter((m) => !this.partsHad(m) && !this.alreadyMet(m)).map((m) => ({ m, s: this.relevance(m, c, hunger) })).sort((a, b) => b.s - a.s);
  }

  /**
   * Does this mission pay in a part the vehicle being driven already has fitted, at that tier or better?
   * Then it isn't worth offering. The getting-started missions are exempt: they teach the part.
   */
  partsHad(m: Mission): boolean {
    if (isIntro(m.tpl)) return false;
    return m.reward.some((r) => r.r === 'part' && this.host.fitted(r.slot) >= r.tier);
  }

  /**
   * Is every goal of this mission something the player already has: a part fitted in the slot it names,
   * the vehicles it wants owned, the HQ slots, the drivers out, the stamp in the passport? Then there is
   * nothing to do and it isn't offered (the user, 16 Oct 2026). The same tests startStep finishes such a
   * step on. The first drive's missions are exempt: they teach the thing, even to someone who has it.
   */
  alreadyMet(m: Mission): boolean {
    if (isIntro(m.tpl) || !m.objs.length) return false;
    return m.objs.every((o) =>
      (o.t === 'fit' && !!o.slot && this.host.fitted(o.slot) > 0)
      || (o.t === 'own' && this.host.units() >= o.n)
      || (o.t === 'hq' && (this.host.hqSlots?.() ?? 0) >= o.slots)
      || (o.t === 'driving' && (this.host.driversOut?.() ?? 0) >= o.n)
      || (o.t === 'visit' && o.key !== '*' && this.passport.has(o.what === 'town' ? 'town' : o.what, o.key)));
  }

  /**
   * How well a mission suits the player right now: one they can take in what they drive, near where
   * they are, that the hold has room for and the wallet can pay into, on the thread they are short of.
   */
  relevance(m: Mission, c: MissionCtx, hunger = this.hunger(c)): number {
    let s = 0;
    if (this.whyNot(m)) s -= 100;
    const at = placeOf(m.objs[0]) ?? m.giver.at;
    s -= Math.hypot(at.x - c.at.x, at.z - c.at.z) / 25;
    s += 2 * Math.max(-2, Math.min(3, hunger[m.thread]));
    if (m.arc) s += 3;
    if (m.kind === 'op' && nightFlying(c)) s += 6;
    s -= (this.done.get(m.tpl) ?? 0) * 0.5;
    for (const o of m.objs) {
      if (o.t === 'deliver') {
        const type = cargoById(o.cargo);
        if (type && type.units > c.free) s -= 6;
      } else if (o.t === 'fit' && c.cash < tierPrice(c.def, o.slot ?? 'engine', 1)) s -= 6;
      else if (o.t === 'own' && c.units.length < o.n && c.cash < 1500) s -= 5;
      else if ((o.t === 'crew' || o.t === 'tow') && c.drivers === 0) s -= 4;
    }
    // short of cash: the ones that pay in cash come first
    if (c.cash < 400 && m.reward.some((r) => r.r === 'cash')) s += 2;
    return s + (m.seed % 100) / 200;
  }

  /** The key of the town the player is in or over (within REST_TOWN tiles of its edge), or null out in the country. */
  townAt(c: MissionCtx): string | null {
    let best: string | null = null, bd = Infinity;
    for (const w of c.worlds) for (const t of w.towns) {
      const d = Math.hypot(w.ox + t.x0 + t.size / 2 - c.at.x, w.oz + t.z0 + t.size / 2 - c.at.z) - t.size / 2;
      if (d < REST_TOWN && d < bd) { bd = d; best = `${w.cx},${w.cz}#${t.id}`; }
    }
    return best;
  }

  /** A mission has just ended: a helicopter gets nothing new for a while, and not in this town. */
  private startRest(): void {
    this.rest = REST_MIN + Math.random() * (REST_MAX - REST_MIN);
    const c = this.host.ctx();
    this.restTown = c ? this.townAt(c) ?? '' : '';
  }

  /** Whether a helicopter is still resting after the last mission: too soon, or not yet at another town. */
  resting(c: MissionCtx): boolean {
    if (this.restTown === null || !isHelicopter(c.def)) return false;
    if (this.rest > 0) return true;
    const here = this.townAt(c);
    if (!here || here === this.restTown) return true;
    this.restTown = null;
    return false;
  }

  private running(tpl: string): boolean { return this.list.some((m) => m.tpl === tpl && (m.state === 'offered' || m.state === 'active')); }
  private cooling(tpl: string, giver: string): boolean { return (this.cool.get(`${tpl}|${giver}`) ?? -1) > this.host.hours(); }

  /** Bind a template now: a mission ready to offer, or null when the world has nothing that fits. */
  make(tp: Template, c: MissionCtx, h: number, town?: { w: World; t: { id: number } & World['towns'][number] }): Mission | null {
    const d = tp.bind(c, h, this, town);
    if (!d) return null;
    const arc = tp.arc ? ARCS.find((a) => a.id === tp.arc) : undefined;
    const m: Mission = {
      id: this.nextId++, tpl: tp.id, seed: h, thread: tp.thread, also: tp.also, kind: tp.kind,
      title: d.title, why: d.why, details: d.details, giver: d.giver, hero: d.hero, caption: d.caption, objs: d.objs,
      step: 0, count: 0, reward: d.reward, state: 'offered', posted: c.hours, due: d.hours ? c.hours + d.hours : null,
      arc: arc ? { id: arc.id, i: arc.tpls.indexOf(tp.id), of: arc.tpls.length } : undefined,
      form: d.form,
      ...(d.notes ? { notes: { ...d.notes } } : {}),
    };
    if (isPosted(m) && !apartMeeting(m, c)) return null;
    return retextMission(m);
  }

  // ---- taking one, running it, ending it ------------------------------------------------------

  /** Why this can't be taken now, or null when it can. */
  whyNot(m: Mission): string | null {
    if (m.state !== 'offered') return null;
    const cap = this.host.activeCap?.() ?? { n: MAX_ACTIVE, next: '' };
    // the first drive's own missions come one after another and are never held back
    if (slotted(m.tpl) && this.active.filter((q) => slotted(q.tpl)).length >= cap.n) {
      return `${cap.n === 1 ? 'One mission' : `${cap.n} missions`} at a time for now${cap.next ? ` · ${cap.next}` : ''}`;
    }
    const race = m.objs.find((o) => o.t === 'race');
    const c = this.host.ctx();
    if (race && race.t === 'race' && c) {
      if (c.def.kind !== 'land') return 'Needs a road car';
    }
    if (m.kind === 'op' && c && !isHelicopter(c.def)) return 'Needs a helicopter';
    if (m.form === 'heli' && c && !isHelicopter(c.def)) return 'Take it in a helicopter';
    if (m.form === 'boat' && c && c.def.kind !== 'water') return 'Take it in a boat';
    if (m.form === 'sub' && c && !(c.def.kind === 'water' && c.def.dive)) return 'Take it in a submarine';
    if (m.kind === 'tail' && c && c.def.kind !== 'land') return 'Needs a road car';
    if (m.tpl.startsWith('convoy:') && c && c.def.kind !== 'land') return 'Lead it in a road vehicle';
    const ride = m.objs.find((o) => o.t === 'deliver' && o.ride);
    if (ride && ride.t === 'deliver' && ride.ride && !ride.ride.ids.includes(this.host.riding?.() ?? '')) return `Take it in ${ride.ride.label}`;
    if (c && c.def.kind !== 'land' && m.objs.some((o) => o.t === 'lap' || o.t === 'grid')) return 'Needs a road car';
    const tow = m.objs.find((o) => o.t === 'tow');
    if (tow && tow.t === 'tow' && c) {
      if (c.def.kind !== 'land') return 'Needs a road vehicle';
      const crew = c.units.filter((u) => u.crew && u.land).length;
      if (crew < tow.min - 1) return `Needs ${tow.min - 1} crewed road vehicle${tow.min > 2 ? 's' : ''}`;
    }
    return this.host.whyNot(m);
  }

  accept(m: Mission): string | null {
    if (this.learning() && !isIntro(m.tpl)) return LEARNING_WHY;
    const why = this.whyNot(m);
    if (why) return why;
    // the first drive's missions are one of each: a second copy (a card answered twice) is dropped, not run
    if (isIntro(m.tpl) && this.list.some((q) => q !== m && q.tpl === m.tpl && (q.state === 'active' || q.state === 'done'))) {
      this.list = this.list.filter((q) => q !== m);
      this.host.changed();
      return null;
    }
    m.state = 'active';
    m.shown = true;
    for (const q of this.active) q.tracked = false;
    m.tracked = true;
    this.loose = false;
    // a deadline fixed on the clock (an act's show, a kick-off) stays where it is; any other runs from now
    if (m.due !== null) m.due = m.notes?.by ?? this.host.hours() + (m.due - m.posted);
    this.onAccept?.(m);
    this.startStep(m);
    this.host.changed();
    return null;
  }

  /** An offer nobody has answered taken down quietly (game/fleetTrack.ts: a step met before it was taken on). */
  withdraw(m: Mission): void {
    if (m.state !== 'offered') return;
    this.list = this.list.filter((q) => q !== m);
    this.host.changed();
  }

  /** Turned down: a side offer goes for a week; an arc's comes back tomorrow. */
  reject(m: Mission): void {
    if (m.state !== 'offered' || isIntro(m.tpl)) return;
    m.state = 'rejected';
    const giver = m.giver.town ? this.townKeyOf(m.giver.town) : '';
    if (m.tpl.startsWith('t:') && giver) this.cool.set(`town|${giver}`, this.host.hours() + ARC_BACK);
    else this.cool.set(`${m.tpl}|`, this.host.hours() + (m.arc ? ARC_BACK : m.tpl.startsWith('work:') || m.tpl.startsWith('convoy:') || m.tpl.startsWith('act:') ? WORK_BACK : REJECT_HOURS));
    // an act's ride turned down is not asked again: that leg of the tour, that fixture
    const act = actKeyOf(m.notes);
    if (act) this.cool.set(`act|${act}`, m.notes?.by ?? this.host.hours() + WORK_BACK);
    this.onReject?.(m);
    this.list = this.list.filter((q) => q !== m);
    this.host.changed();
  }

  /**
   * Take on a mission made somewhere else (a tavern's job, game/tavern): it joins the list and is accepted
   * at once. The reason it can't be, or null.
   */
  adopt(m: Mission): string | null {
    if (this.learning() && !isIntro(m.tpl)) return LEARNING_WHY;
    m.id = this.nextId++;
    m.posted = this.host.hours();
    this.list.push(m);
    const why = this.accept(m);
    if (why) this.list = this.list.filter((q) => q !== m);
    this.host.changed();
    return why;
  }

  /** Given up part way: it goes back to Offered, from the first step. */
  abandon(m: Mission): void {
    if (m.state !== 'active' || isIntro(m.tpl)) return;
    this.stopRunning(m);
    m.state = 'offered';
    if (m.notes) delete m.notes.left;
    m.step = 0;
    m.count = 0;
    m.tracked = false;
    m.posted = this.host.hours();
    this.host.changed();
  }

  /** Track this mission, or, already tracked, let it go: none tracked, the arrows to the cargo aboard. */
  track(m: Mission): void {
    this.loose = !!m.tracked;
    for (const q of this.active) q.tracked = !this.loose && q === m;
    this.host.changed();
  }

  /** The step now current has started: goods put down, a start line or a load put out. */
  private startStep(m: Mission): void {
    const o = m.objs[m.step];
    if (!o) return;
    if (o.t === 'race' || o.t === 'tow' || o.t === 'crew' || o.t === 'op' || o.t === 'tail') this.host.arm(m, o);
    if (o.t === 'deliver') {
      if (!m.notes?.mainDone) {
        const it = this.host.spawn(m, o);
        if (it) this.items.set(m.id, it);
      }
      if (o.also && !m.notes?.alsoDone) {
        const it = this.host.spawn(m, o, o.also);
        if (it) this.alsoItems.set(m.id, it);
      }
    }
    // a stamp already in the book, or a part already fitted: done as soon as it starts
    if (o.t === 'visit' && o.key !== '*' && this.passport.has(o.what === 'town' ? 'town' : o.what, o.key)) this.advance(m);
    else if (o.t === 'fit' && o.slot && this.host.fitted(o.slot) > 0) this.advance(m);
    else if (o.t === 'own' && this.host.units() >= o.n) this.advance(m);
    else if (o.t === 'hq' && (this.host.hqSlots?.() ?? 0) >= o.slots) this.advance(m);
    else if (o.t === 'driving' && (this.host.driversOut?.() ?? 0) >= o.n) this.advance(m);
  }

  /** Goods on the ground or in the hold for this mission go back to being anybody's; a race or tow stands down. */
  private stopRunning(m: Mission): void {
    const it = this.items.get(m.id);
    if (it) { this.host.release(it); this.items.delete(m.id); }
    const also = this.alsoItems.get(m.id);
    if (also) { this.host.release(also); this.alsoItems.delete(m.id); }
    this.host.disarm(m);
  }

  private advanceWhere(test: (o: Obj) => boolean): void {
    for (const m of this.active) {
      const o = m.objs[m.step];
      if (o && test(o)) this.advance(m);
    }
  }

  private onDelivered(it: CargoItem): void {
    for (const m of this.active) {
      const o = m.objs[m.step];
      if (!o) continue;
      // the second of a pair of loads (`also`): one of the n, nothing put out in its place
      if (o.t === 'deliver' && o.also && this.alsoItems.get(m.id) === it) {
        this.alsoItems.delete(m.id);
        m.notes = { ...(m.notes ?? {}), alsoDone: 1 };
        m.count++;
        if (m.count >= o.n) this.advance(m); else this.host.changed();
        continue;
      }
      if (o.t === 'deliver' && this.items.get(m.id) === it) {
        this.items.delete(m.id);
        if (o.also) m.notes = { ...(m.notes ?? {}), mainDone: 1 };
        if (o.clock && m.notes?.left !== undefined) {
          const siren = !!m.notes.siren;
          m.outcome = `Made it with ${clockText(m.notes.left)} to spare${siren ? ', siren on' : ''}`;
          if (siren) m.reward = m.reward.map((r) => (r.r === 'cash' ? { ...r, n: Math.round((r.n * SIREN_PAY) / 5) * 5 } : r));
          delete m.notes.left;
        }
        m.count++;
        if (m.count >= o.n) this.advance(m);
        else if (o.also) this.host.changed();
        else {
          const next = this.host.spawn(m, o);
          if (next) this.items.set(m.id, next);
          this.host.changed();
        }
      } else if (o.t === 'loads' && it.chain === undefined) {
        const key = this.townKeyOf(o.town);
        const hit = (s: Site | null) => !!s && s.w.cx === o.town.cell[0] && s.w.cz === o.town.cell[1] && s.w.townId[Math.floor(s.lz) * N + Math.floor(s.lx)] === o.town.id;
        if (hit(it.from) || hit(it.to)) {
          m.count++;
          if (m.count >= o.n) this.advance(m);
          else this.host.changed();
        }
        void key;
      }
    }
  }

  /** A clean lap of a circuit: quick enough for a Hot Lap there, or told how far off it was. */
  private onLap(key: string, secs: number): void {
    for (const m of this.active) {
      const o = m.objs[m.step];
      if (!o || o.t !== 'lap' || o.key !== key) continue;
      if (secs <= o.secs) { m.outcome = `Lapped in ${secs.toFixed(1)} s`; this.advance(m); }
      else this.host.announce(m.title, `${secs.toFixed(1)} s · needs under ${o.secs.toFixed(1)} s`);
    }
  }

  /** A race at a circuit is over for the player: in the places, or not. */
  private onCircuitRace(key: string, place: number, of: number): void {
    for (const m of this.active) {
      const o = m.objs[m.step];
      if (!o || o.t !== 'grid' || o.key !== key) continue;
      m.notes = { ...(m.notes ?? {}), place };
      if (place >= 1 && place <= o.top) { m.outcome = place === 1 ? `Won, from ${of} cars` : `Finished P${place} of ${of}`; this.advance(m); }
      else this.fail(m, place ? `Finished P${place} of ${of}` : 'Missed the start', place ? 'Not in the places this time' : 'The race went without you');
    }
  }

  /** Whether a Race Day at this circuit is waiting for the player's car on the grid. */
  circuitEntry(key: string): boolean {
    return this.active.some((m) => { const o = m.objs[m.step]; return !!o && o.t === 'grid' && o.key === key; });
  }

  private onRaceEnd(id: number, won: boolean, margin: number): void {
    const m = this.byId(id);
    if (!m || m.state !== 'active') return;
    const o = m.objs[m.step];
    if (!o || o.t !== 'race') return;
    m.notes = { ...(m.notes ?? {}), margin };
    if (won) {
      this.beaten.add(o.rival);
      m.outcome = `Won by ${margin.toFixed(1)} s`;
      this.advance(m);
    } else {
      const r = rivalById(o.rival);
      this.fail(m, margin > 0 ? `Lost by ${margin.toFixed(1)} s` : 'Gave up the race', `${r.short} wins this one`);
    }
  }

  private onTowEnd(id: number, ok: boolean, snaps: number, scrapes: number): void {
    const m = this.byId(id);
    if (!m || m.state !== 'active') return;
    const o = m.objs[m.step];
    if (!o || o.t !== 'tow') return;
    m.notes = { ...(m.notes ?? {}), snaps, scrapes };
    if (ok) {
      m.outcome = snaps ? `Rope snapped ${snaps === 1 ? 'once' : snaps === 2 ? 'twice' : `${snaps} times`}` : 'Not a scratch on it';
      this.advance(m);
    } else this.fail(m, 'Given up');
  }

  private onOpEnd(id: number, ok: boolean, score: number, line: string): void {
    const m = this.byId(id);
    if (!m || m.state !== 'active') return;
    const o = m.objs[m.step];
    if (!o || o.t !== 'op') return;
    m.notes = { ...(m.notes ?? {}), score: Math.round(score * 100) };
    if (!ok) { this.fail(m, line); return; }
    // the pay goes with how well it was done: half for a scrape through, one and a half for a perfect job
    m.reward = m.reward.map((r) => (r.r === 'cash' ? { ...r, n: Math.max(5, Math.round((r.n * (0.5 + score)) / 5) * 5) } : r));
    m.outcome = line;
    this.advance(m);
  }

  /**
   * A tail is over (game/tail). Followed home unseen pays the cash at 0.75–1.25× (the less it ever suspected,
   * the more); made but run down, half. Whatever else it promised — the depot, the hideout, the contact — is
   * found either way. Lost, or made and lost, it fails.
   */
  private onTailEnd(id: number, ok: boolean, made: boolean, score: number, line: string): void {
    const m = this.byId(id);
    if (!m || m.state !== 'active') return;
    const o = m.objs[m.step];
    if (!o || o.t !== 'tail') return;
    m.notes = { ...(m.notes ?? {}), score: Math.round(score * 100), made: made ? 1 : 0 };
    if (!ok) { this.fail(m, line); return; }
    const mul = made ? 0.5 : 0.75 + 0.5 * score;
    m.reward = m.reward.map((r) => (r.r === 'cash' ? { ...r, n: Math.max(5, Math.round((r.n * mul) / 5) * 5) } : r));
    m.outcome = line;
    this.advance(m);
  }

  /**
   * The player has driven into building `uid` of cell `cell` at `kmh` in `model`: a knock-down step aimed at it
   * is done ('down': the host brings it down), or it was too gentle ('slow') or in the wrong vehicle ('ride').
   * `barred` is why it is no longer the town's to clear (somebody has bought it): the mission fails. Null when
   * no step is aimed at it.
   */
  rammed(cell: [number, number], uid: number, kmh: number, model: string, barred: string | null): 'down' | 'slow' | 'ride' | null {
    for (const m of this.active) {
      const o = m.objs[m.step];
      if (!o || o.t !== 'ram' || o.b.uid !== uid || o.b.cell[0] !== cell[0] || o.b.cell[1] !== cell[1]) continue;
      if (barred) { this.fail(m, 'Called off', `${barred}: the job is off`); return null; }
      if (!o.ride.ids.includes(model)) return 'ride';
      if (kmh < o.kmh) return 'slow';
      m.outcome = `Down at ${speedText(kmh)}`;
      this.advance(m);
      return 'down';
    }
    return null;
  }

  /** The siren was sounded: a dash under way with its load aboard pays the more for it. */
  siren(): boolean {
    let any = false;
    for (const m of this.active) if (m.notes?.left !== undefined) { m.notes.siren = 1; any = true; }
    return any;
  }

  /**
   * A delivery's medal, at its last drop: the time against the three set at pickup, what it adds to the pay,
   * and the best kept for the job. Slower than bronze pays just what the mission always did.
   */
  private settleMedal(m: Mission, gave: string[]): void {
    const n = m.notes;
    if (!n || n.mT === undefined) return;
    if (n.mX) { gave.push('No medal: airlifted on the way'); return; }
    const medal = medalFor(n.mT, n);
    n.medal = medal;
    if (!medal) { m.outcome = `${clockText(n.mT)} · no medal (bronze ${clockText(n.mB)})`; return; }
    const bonus = medalBonus(m, medal);
    if (bonus.cash > 0) this.host.grant(m, { r: 'cash', n: bonus.cash });
    if (bonus.gems > 0) this.host.grant(m, { r: 'gems', n: bonus.gems });
    m.outcome = `${MEDAL_ICON[medal]} ${MEDAL_NAME[medal]} · ${clockText(n.mT)}`;
    gave.push(`${MEDAL_ICON[medal]} ${MEDAL_NAME[medal]} medal: +$${bonus.cash.toLocaleString('en-US')}${bonus.gems ? ` and ◆${bonus.gems}` : ''}`);
    if (medal > (this.medals.get(m.tpl) ?? 0)) this.medals.set(m.tpl, medal);
  }

  /** Is this mission's current load aboard (not waiting at its pickup)? */
  aboard(m: Mission): boolean { return this.items.get(m.id)?.marker === null; }

  /** The player was airlifted: a medal clock running now can win nothing. */
  airlifted(): void {
    for (const m of this.active) if (m.notes?.mT !== undefined && !m.notes.mX) { m.notes.mX = 1; this.host.announce(m.title, 'Airlifted: no medal on this one, but the pay stands'); }
  }

  /** A running medal clock: the time so far and the next medal still to win (null when even bronze has gone). */
  medalOf(m: Mission): { secs: number; next: { medal: 1 | 2 | 3; left: number } | null } | null {
    const n = m.notes;
    if (m.state !== 'active' || !n || n.mT === undefined || n.mX) return null;
    return { secs: n.mT, next: nextMedal(n.mT, n) };
  }

  /** Seconds left on a dash's clock, or null when none is running. */
  clockOf(m: Mission): number | null {
    return m.state === 'active' && m.notes?.left !== undefined ? Math.max(0, m.notes.left) : null;
  }

  /** The current step is done: the next one starts, or the mission is finished. */
  private advance(m: Mission): void {
    if (m.state !== 'active') return;
    const o = m.objs[m.step];
    if (o && (o.t === 'race' || o.t === 'tow' || o.t === 'crew' || o.t === 'op' || o.t === 'tail')) {
      // the next step may be the same tow (crew → tow): leave it armed
      const next = m.objs[m.step + 1];
      if (!(o.t === 'crew' && next?.t === 'tow')) this.host.disarm(m);
    }
    m.step++;
    m.count = 0;
    if (m.step >= m.objs.length) { this.complete(m); return; }
    this.startStep(m);
    this.host.changed();
  }

  private complete(m: Mission): void {
    this.stopRunning(m);
    m.state = 'done';
    m.ended = this.host.hours();
    m.tracked = false;
    m.outcome ??= 'Done';
    const gave: string[] = [];
    for (const r of m.reward) {
      if (r.r === 'standing') {
        const key = this.townKeyOf(r.town);
        const now = this.talkUp(key, r.n);
        gave.push(`${r.town.name} talks you up: ${STANDING[now]}`);
        continue;
      }
      const why = this.host.grant(m, r);
      if (why) gave.push(why);
      else gave.push(chipText(r));
    }
    this.settleMedal(m, gave);
    this.done.set(m.tpl, (this.done.get(m.tpl) ?? 0) + 1);
    const tp = templateById(m.tpl);
    // the arc moves on
    if (m.arc) this.arcs.set(m.arc.id, Math.max(this.arcs.get(m.arc.id) ?? 0, m.arc.i + 1));
    if (tp?.cooldown) this.cool.set(`${m.tpl}|`, this.host.hours() + tp.cooldown);
    this.startRest();
    this.trim();
    this.host.completed(m, gave);
    this.host.changed();
    this.fillTimer = 0;
  }

  private fail(m: Mission, outcome: string, line?: string): void {
    this.stopRunning(m);
    m.state = 'failed';
    m.outcome = outcome;
    m.ended = this.host.hours();
    m.tracked = false;
    this.host.announce(m.title, line ?? outcome);
    // an arc (or a race) is never lost: it is offered again tomorrow
    this.cool.set(`${m.tpl}|`, this.host.hours() + ARC_BACK);
    if (m.giver.town && m.tpl.startsWith('t:')) this.cool.set(`town|${this.townKeyOf(m.giver.town)}`, this.host.hours() + ARC_BACK);
    this.startRest();
    this.trim();
    this.host.changed();
  }

  /** Keep the last 30 finished for the Done list. */
  private trim(): void {
    const ended = this.finished;
    if (ended.length <= 30) return;
    const drop = new Set(ended.slice(30));
    this.list = this.list.filter((m) => !drop.has(m));
  }

  /** The line under an under-way mission: the one thing to do next. */
  nextLine(m: Mission): string {
    const o = m.objs[m.step];
    if (!o) return '';
    switch (o.t) {
      case 'deliver': {
        const left = this.clockOf(m);
        if (left !== null) return `${clockText(left)} left · get them to the ${o.to.name.replace(/^the /, '')}`;
        const md = this.medalOf(m);
        if (md?.next && this.items.get(m.id)?.marker === null) return `${MEDAL_ICON[md.next.medal]} ${clockText(md.next.left)} · get it to the ${o.to.name.replace(/^the /, '')}`;
        const line = this.items.has(m.id) ? `${o.n > 1 ? `${m.count + 1} of ${o.n}: ` : ''}pick it up at the ${o.from.name}${o.clock ? ` · ${clockText(o.clock)} once aboard` : ''}` : `Head for ${o.from.name}`;
        return o.with ? `${line} · ${o.with} following` : line;
      }
      case 'ram': return `In ${o.ride.label}: hit it head on at ${speedText(o.kmh)}+`;
      case 'loads': return `${m.count} of ${o.n} done · any load to or from ${o.town.name}`;
      case 'reach': {
        if (o.hidden) return 'Somewhere out there: follow the clue';
        const held = this.held.get(m.id);
        if (o.hold && held !== undefined) return `Stay put: ${Math.max(0, Math.ceil(o.hold - held))} s`;
        const when = o.after !== undefined && o.before !== undefined ? ` between ${hh(o.after)} and ${hh(o.before)}` : '';
        const fleet = o.with ? ` with ${o.with} following` : '';
        // what to do once there, too: the ring on the ground, and how long to stop in it
        const stay = o.hold ? `, stop in the ring ${o.hold} s` : o.stop ? ', stop in the ring' : '';
        if (o.dived) return `Dive to ${o.at.name} and go down to the bottom${o.hold ? `, ${o.hold} s` : ''}`;
        return `${o.ride ? `In ${o.ride.label}: d` : 'D'}rive to ${o.at.name}${fleet}${when}${stay}`;
      }
      case 'visit': return o.at ? `Nearest: ${o.at.name}` : 'Anywhere new';
      case 'ferry': return 'Stop on a harbour slip, then F';
      case 'race': return `Stop at the start line, then Enter`;
      case 'crew': return 'Your crew is on the way';
      case 'tow': return 'Stop by the load, then Enter to hitch';
      case 'own': return 'Buy one at a Vehicle Dealer';
      case 'make': return o.what === 'road' ? `${m.count} / ${o.n} road tiles · B to build` : o.what === 'unlock' ? 'H → Tech: unlock a vehicle with ◆' : 'B, then H: ask a town for a building';
      case 'hq': return 'H → Where to buy one, or click a building';
      case 'driving': return 'H → Fleet → Hire…, then drag them into a seat';
      case 'fit': return 'Buy it at a Vehicle Shop';
      case 'speed': return `Hold W on a straight, then Shift · ${speedText(o.kmh)}`;
      case 'drift': return `Hold Space as you turn ${o.dir}`;
      case 'op': return this.opLine?.(m) ?? `Fly to ${o.at.name} after dark`;
      case 'lap': return `Lap ${o.at.name} under ${o.secs.toFixed(1)} s · cross the line to start`;
      case 'grid': return this.circuitLine?.(m) ?? `Drive to ${o.at.name}`;
      case 'tail': return this.tailLine?.(m) ?? (o.train ? `Wait at ${o.at.name} for the freight` : `Find ${o.car.name} at ${o.at.name}`);
      case 'range': {
        const r = this.host.range?.();
        const now = r && (!o.kind || r.kind === o.kind) && (!o.model || r.model === o.model) ? Math.round(r.credit) : 0;
        return `${now.toLocaleString('en-US')} / ${o.tiles.toLocaleString('en-US')} tiles out${o.mname ? ` in your ${o.mname}` : o.kind ? ` ${KIND_IN[o.kind]}` : ''}`;
      }
      case 'discover': return `${m.count} / ${o.n} new cells`;
    }
  }

  /**
   * The ring drawn on the ground at a mission's arrival step (missions/tracker.ts): where, how big (the
   * `r` it counts inside), what its sign says, and how far through a hold the player is (0 to 1). Null where
   * no ring belongs: another kind of step, a door (it has its own entrance ring), a place still hidden.
   */
  ringOf(m: Mission): { x: number; z: number; r: number; text: string; p: number; ok: boolean } | null {
    const o = m.objs[m.step];
    // a teaching mission's place to build at (game/coach.ts): the water to bridge, the ground to level
    if (o?.t === 'make' && o.at && m.state === 'active') return { x: o.at.x, z: o.at.z, r: o.r ?? 3, text: o.what === 'level' ? 'Level the ground in here' : o.what === 'bridge' ? 'Bridge the water here' : o.at.name, p: m.count / o.n, ok: true };
    if (!o || o.t !== 'reach' || o.door || m.state !== 'active') return null;
    if (o.hidden) {
      const pl = this.host.player();
      if (!pl || Math.hypot(pl.x - o.at.x, pl.z - o.at.z) > o.hidden) return null;
    }
    const off = reachOff(o, this.host.hours());
    const held = this.held.get(m.id);
    let text: string, p = 0;
    if (off) text = off.replace('Come back between', 'Open');
    else if (o.hold) {
      p = held !== undefined ? Math.min(1, held / o.hold) : 0;
      text = held !== undefined ? `Stay ${o.dived ? 'down' : 'stopped'} · ${Math.max(0, Math.ceil(o.hold - held))} s` : `${o.dived ? 'Go down to the bottom' : 'Stop here'} · ${o.hold} s`;
    } else text = o.dived ? 'Go down to the bottom' : o.stop ? 'Stop here' : 'Drive in';
    if (!off && o.with) text += ` · ${o.with} following`;
    if (!off && o.ride) text = `In ${o.ride.label} · ${text}`;
    return { x: o.at.x, z: o.at.z, r: o.r, text, p, ok: !off };
  }

  /** Where the tracked mission's next step is, in world tiles, for the HUD arrow and the beam. */
  target(m: Mission): { x: number; z: number; name: string } | null {
    const o = m.objs[m.step];
    if (!o) return null;
    switch (o.t) {
      case 'deliver': {
        // a second load still on the road (the helping hand's) is where to go before the drop
        const also = this.alsoItems.get(m.id);
        if (also && also.marker !== null && also.x !== undefined) return { x: also.x, z: also.z, name: o.from.name };
        const it = this.items.get(m.id);
        if (it && it.to && it.x !== undefined) {
          const held = it.marker === null;
          return held ? { x: it.to.x, z: it.to.z, name: o.to.name } : { x: it.x, z: it.z, name: o.from.name };
        }
        return { x: o.from.x, z: o.from.z, name: o.from.name };
      }
      case 'reach': {
        // a hidden place shows itself only close to
        if (o.hidden) {
          const p = this.host.player();
          if (!p || Math.hypot(p.x - o.at.x, p.z - o.at.z) > o.hidden) return null;
        }
        return { x: o.at.x, z: o.at.z, name: o.at.name };
      }
      case 'visit': return o.at ? { x: o.at.x, z: o.at.z, name: o.at.name } : null;
      case 'make': return o.at ? { x: o.at.x, z: o.at.z, name: o.at.name } : null;
      case 'ram': return { x: o.at.x, z: o.at.z, name: o.at.name };
      case 'race': return this.raceTarget?.(m) ?? { x: o.from.x, z: o.from.z, name: o.from.name };
      case 'crew': { const t = m.objs.find((q) => q.t === 'tow'); return t && t.t === 'tow' ? { x: t.from.x, z: t.from.z, name: 'the load' } : null; }
      case 'tow': return this.towTarget?.(m) ?? { x: o.from.x, z: o.from.z, name: 'the load' };
      case 'ferry': return o.at ? { x: o.at.x, z: o.at.z, name: o.at.name } : this.ferryTarget?.(m) ?? null;
      case 'op': return this.opTarget?.(m) ?? { x: o.at.x, z: o.at.z, name: o.at.name };
      case 'lap': case 'grid': return this.circuitTarget?.(m) ?? { x: o.at.x, z: o.at.z, name: o.at.name };
      case 'tail': return this.tailTarget?.(m) ?? { x: o.at.x, z: o.at.z, name: o.at.name };
      case 'range': {
        // no place: a point that far out, straight away from home through wherever the player is
        const r = this.host.range?.(), p = this.host.player();
        if (!r) return null;
        const dx = (p?.x ?? r.home[0]) - r.home[0], dz = (p?.z ?? r.home[1] + 1) - r.home[1], d = Math.hypot(dx, dz) || 1;
        return { x: r.home[0] + (dx / d) * o.tiles, z: r.home[1] + (dz / d) * o.tiles, name: `${o.tiles.toLocaleString('en-US')} tiles out` };
      }
      default: return null;
    }
  }

  /**
   * A long story's step that couldn't bind today: true when it should be passed over (its place exists
   * nowhere in reach, three days running). Set by the host, which asks the story why it failed.
   */
  storyMissed: ((arc: string, tpl: string, i: number, day: number) => boolean) | null = null;
  /** Where a race's tracker points: the start line until the lights go, then the finish. Set by the host. */
  raceTarget: ((m: Mission) => { x: number; z: number; name: string } | null) | null = null;
  /** Where a ferry step saved without its slip points: the slip nearest the far side. Set by the host. */
  ferryTarget: ((m: Mission) => { x: number; z: number; name: string } | null) | null = null;
  /** Where a night op's tracker points (the area, the fleeing car, the hospital pad), and its next line. Set by the host. */
  opTarget: ((m: Mission) => { x: number; z: number; name: string } | null) | null = null;
  opLine: ((m: Mission) => string | null) | null = null;
  /** Where a circuit step's tracker points (the grid slot, the gate), and a Race Day's next line. Set by the host. */
  circuitTarget: ((m: Mission) => { x: number; z: number; name: string } | null) | null = null;
  circuitLine: ((m: Mission) => string | null) | null = null;
  /** Where a tail's tracker points (the meet, then the target itself), and its next line. Set by the host. */
  tailTarget: ((m: Mission) => { x: number; z: number; name: string } | null) | null = null;
  tailLine: ((m: Mission) => string | null) | null = null;
  /** Where a tow's tracker points: the load until it is hitched, then its drop. Set by the host. */
  towTarget: ((m: Mission) => { x: number; z: number; name: string } | null) | null = null;

  /** The mission a held load belongs to, for its marker's colour. */
  itemOf(m: Mission): CargoItem | null { return this.items.get(m.id) ?? null; }

  // ---- saving ---------------------------------------------------------------------------------

  toSave(): SavedMissions {
    return {
      v: 1,
      next: this.nextId,
      day: this.lastDay,
      list: this.list.filter((m) => m.state !== 'rejected').map((m) => ({ ...m })),
      arcs: [...this.arcs],
      standing: [],
      cool: [...this.cool],
      done: [...this.done],
      beaten: [...this.beaten],
      passport: this.passport.toSave(),
      freeze: [],
      intro: this.intro,
      gap: this.gap,
      taught: [...this.taught],
      track: this.trackStep,
      drifts: this.drifts || undefined,
      handDue: this.handDue || undefined,
      medals: [...this.medals],
      loose: this.loose || undefined,
    };
  }

  /**
   * Put the missions back. They point at the world by tile and cell, which the same world at the same
   * generator version gives back exactly; one whose places have moved (a new generator) is dropped and
   * its arc offered again, so nothing is lost but the progress on that one step.
   */
  fromSave(s: SavedMissions | undefined, sameGen: boolean): void {
    this.clear();
    if (!s) return;
    this.nextId = s.next ?? 1;
    this.lastDay = -1;
    for (const [k, v] of s.arcs ?? []) this.arcs.set(k, v);
    for (const [k, v] of s.standing ?? []) if (v > 0) this.legacy.set(k, v);
    for (const [k, v] of s.cool ?? []) this.cool.set(k, v);
    for (const [k, v] of s.done ?? []) this.done.set(k, v);
    for (const r of s.beaten ?? []) this.beaten.add(r);
    for (const [k, v] of s.medals ?? []) if (v >= 1 && v <= 3) this.medals.set(k, v as Medal);
    this.passport.fromSave(s.passport);
    this.intro = s.intro ?? 0;
    this.gap = s.gap ?? 0;
    // a save from before the tips were spread out (they were all shown up front), or from before the two cards
    for (const k of s.taught ?? TAUGHT_ALL) this.taught.add(k);
    if (OLD_TIPS.some((k) => this.taught.has(k))) for (const k of TAUGHT_ALL) this.taught.add(k);
    this.trackStep = s.track ?? 0;
    this.drifts = s.drifts ?? 0;
    this.handDue = s.handDue ?? 0;
    this.loose = !!s.loose;
    for (const m of s.list ?? []) {
      if (!sameGen && (m.state === 'active' || m.state === 'offered')) continue;
      // a save with two of a first-drive mission (from before they were kept to one): keep the furthest along
      if (isIntro(m.tpl)) {
        const rank = (q: Mission) => (q.state === 'done' ? 3 : q.state === 'active' ? 2 : q.state === 'offered' ? 1 : 0);
        const twin = this.list.find((q) => q.tpl === m.tpl);
        if (twin) { if (rank(m) > rank(twin)) this.list[this.list.indexOf(twin)] = m; continue; }
      }
      this.list.push(m);
    }
    // one saved under way past its last step (its ending was cut short) is simply done
    for (const m of this.active) if (m.step >= m.objs.length) { m.state = 'done'; m.tracked = false; m.outcome ??= 'Done'; }
    // what was under way picks up at the step it was on
    for (const m of this.active) this.startStep(m);
  }

  // ---- the console ----------------------------------------------------------------------------

  /** pr.missions.list() */
  lines(): string[] {
    return this.list.map((m) => `${m.id} [${m.state}] ${m.tpl} · ${m.title} · step ${m.step + 1}/${m.objs.length} · ${m.giver.name}`);
  }

  /** pr.missions.offer('race-vera-1') — bind one now and put it at the top of Offered. */
  force(id: string): string {
    // one of each of the first drive's missions, ever
    const had = isIntro(id) ? this.list.find((q) => q.tpl === id && q.state !== 'rejected') : undefined;
    if (had) return `${had.title} is already ${had.state}`;
    const tp = templateById(id);
    const c = this.host.ctx();
    if (!tp || !c) return `no template ${id}`;
    const town = c.home.towns.length ? { w: c.home, t: c.home.towns[0] } : undefined;
    const m = this.make(tp, c, hashString(`${id}|${c.hours}`), tp.ladder !== undefined ? town : undefined);
    if (!m) return `${id}: nothing in reach fits`;
    this.list.push(m);
    this.host.changed();
    return `${m.title} offered by ${m.giver.name}`;
  }

  /** Why a template can't be offered at all now (its gate), or null; null too when there is no world to ask. */
  gateOf(id: string): string | null {
    const tp = templateById(id);
    const c = this.host.ctx();
    if (!tp || !c) return null;
    return tp.gate(c, this);
  }

  /** pr.missions.finish() — tick every step of the tracked mission and pay it out. */
  finishNow(): string {
    const m = this.tracked;
    if (!m) return 'nothing under way';
    this.stopRunning(m);
    m.step = m.objs.length - 1;
    this.advance(m);
    return `${m.title} done`;
  }

  /** pr.missions.step() — tick the current step of the tracked mission. */
  stepNow(): string {
    const m = this.tracked;
    if (!m) return 'nothing under way';
    this.advance(m);
    return `${m.title}: step ${m.step + 1}`;
  }

  /** Templates that exist, for the console. */
  templates(): string[] { return TEMPLATES.map((t) => `${t.id} (${t.thread}${t.ladder !== undefined ? `, ladder ${t.ladder}` : ''}${t.arc ? `, arc ${t.arc}` : ''})`); }
  arcsList(): Arc[] { return ARCS; }
  get giverKinds(): Giver['who'][] { return ['mayor', 'rival', 'mechanic', 'harbour', 'haulier', 'baker']; }
  get threads(): Thread[] { return THREADS; }
  get kinds(): Kind[] { return ['job', 'race', 'tow', 'trip', 'op', 'tail']; }
}

/** Where an objective happens first, if it has a place. */
function placeOf(o: Obj | undefined): { x: number; z: number } | null {
  if (!o) return null;
  switch (o.t) {
    case 'deliver': return o.from;
    case 'reach': return o.at;
    case 'ram': return o.at;
    case 'visit': return o.at;
    case 'race': case 'tow': return o.from;
    case 'op': return o.at;
    case 'lap': case 'grid': return o.at;
    case 'tail': return o.at;
    default: return null;
  }
}

const dist = (p: { w: World; t: World['towns'][number] }, c: MissionCtx): number =>
  Math.hypot(p.w.ox + p.t.x0 + p.t.size / 2 - c.at.x, p.w.oz + p.t.z0 + p.t.size / 2 - c.at.z);

export function chipText(r: Reward): string {
  switch (r.r) {
    case 'cash': return `$${r.n.toLocaleString('en-US')}`;
    case 'gems': return `◆ ${r.n}`;
    case 'part': return `${r.slot} T${r.tier}${r.all ? ' on every unit' : ''}`;
    case 'vehicle': return `${r.name ?? r.model} joins the fleet`;
    case 'building': return `${r.at.name}: the deed is yours`;
    case 'standing': return `${r.town.name} +${r.n}`;
    case 'effect': return r.line;
    case 'driver': return 'A new driver';
    case 'crew': return `${r.name} stays on, in her ${r.model}`;
    case 'livery': return `${r.name} paint`;
    case 'clue': return r.line;
    case 'reveal': return r.line;
  }
}
