/**
 * From a planned road route to a track spec (world/railBuild.ts): the rails' own rules over the route, the
 * rail-top heights along it, and the junction leads where an end sits on a line already there. Pure, so the
 * builder's Rails side (game/railBuilder.ts) and the headless harness (scripts/railbuild.ts) lay the same track.
 */
import { N, DIRS, STEP, RailBit, RoadType, World, tileMean, type Bridge, type RailEnd, type RailEra, type RailPath } from './tiles';
import { BROAD_RISE, deckHeightAt, nodeAt, nodeCenter, nodeProblem, routeWithBridges, seaNode, type Route, type RoutePlan, type StraitDeck } from './roads';
import { DEPART, LEAD, MAX_POINTS, nearestRail, railAt, type RailSpec } from './railBuild';
import { RAIL_LIFT } from './railPlan';

/** How near a point must be to a line (tiles) to mean "on this line". */
export const SNAP = 1.0;
/**
 * Steps over deep water a track begun out at sea must stand (the user, 3 Nov 2026: "an elevation above water that's
 * acceptable for all boats to cross under"): the most the game raises any deck over broad water for boats.
 */
export const SEA_CLEAR = BROAD_RISE;

/** Where a track begins or ends on a line already there: the path, where along it, and whether it carries on from that line's buffers. */
export interface Join { q: RailPath; s: number; cont: 'start' | 'end' | null }

/**
 * One end of a track, as the planner sees it: a node on open ground (or, `wet`, out over deep water, where only a
 * raised track may stand), and the join it leaves from (if any).
 */
export interface Anchor { node: number; join: Join | null; side: 1 | -1; wet?: boolean }

/**
 * The nearest node to a point that a track may run through and that is not on a line, within two tiles, or -1.
 * `afloat`: failing ground, a node out over deep water (a branch off a line on a viaduct over the sea).
 * `ahead`: a line's end being carried on (its point and the way it runs out): only nodes a tile or more past it, and
 * open sea as good as ground for a raised track, so the new track runs straight on. Without it a viaduct ending at the
 * shore took a shore tile beside or behind its buffers (ground was preferred), and the track doubled back to it and
 * out again in a knot (the user, 5 Nov 2026).
 */
export function freeNodeNear(w: World, x: number, z: number, afloat = false, ahead?: { x: number; z: number; tx: number; tz: number }): number {
  let best = -1, bestD = Infinity, sea = -1, seaD = Infinity;
  for (let dz = -2; dz <= 2; dz++) for (let dx = -2; dx <= 2; dx++) {
    const tx = Math.floor(x) + dx, tz = Math.floor(z) + dz;
    if (tx < 1 || tz < 1 || tx >= N - 1 || tz >= N - 1) continue;
    const n = tz * N + tx;
    const d = Math.hypot(tx + 0.5 - x, tz + 0.5 - z);
    // carrying a line on: only a node a tile or more past its end (see `ahead`)
    if (ahead && (tx + 0.5 - ahead.x) * ahead.tx + (tz + 0.5 - ahead.z) * ahead.tz < 1) continue;
    if (afloat && d < seaD && seaNode(w, n)) { seaD = d; sea = n; }
    if (nodeProblem(w, n, false) || (w.rail[n] & (RailBit.Track | RailBit.Pad | RailBit.Loop | RailBit.Deck))) continue;
    if (d < bestD) { bestD = d; best = n; }
  }
  // carried on straight: the nearer of ground and sea; otherwise ground first, as ever
  if (ahead && best >= 0 && sea >= 0) return seaD < bestD ? sea : best;
  return best >= 0 ? best : sea;
}

/**
 * The deck height (steps) a branch must leave a line at, or undefined for one on the ground: where the line stands on
 * a viaduct (over the sea, or more than a step over the ground beside it), a track off it starts at its height, as
 * one carried on from its buffers up there does.
 */
export function raisedJoin(w: World, a: Anchor): number | undefined {
  const j = a.join;
  if (!j || a.node < 0) return undefined;
  const deck = railAt(j.q, j.cont ? (j.cont === 'start' ? 0 : j.q.length) : j.s).y / STEP - RAIL_LIFT;
  const ground = Math.max(tileMean(w, a.node), w.water[a.node] >= 0 ? w.water[a.node] : -Infinity);
  return a.wet || deck - ground > 1 ? deck : undefined;
}

/** Is this node out over deep water (only a deck carries a track there)? */
export const wetNode = (w: World, n: number): boolean => n >= 0 && nodeProblem(w, n, false) !== null && seaNode(w, n);

/**
 * What a point on the ground means as a track's end: a join onto the line under it (the planner's node on
 * open ground just off it), else the tile node there. Null with why on bad ground.
 */
export function anchorAt(w: World, x: number, z: number, afloat = false): { a: Anchor | null; why: string } {
  const near = nearestRail(w, x, z, SNAP);
  if (near) {
    const q = near.p;
    const s = q.s[near.i];
    const at = railAt(q, s);
    // which side of the line the point is: the track leaves that way
    const side: 1 | -1 = -at.tz * (x - at.x) + at.tx * (z - at.z) > 0 ? 1 : -1;
    // at a dead end, carry the line on from its buffers: anywhere on the stretch too near the end for a junction
    // means that (the user, 2 Nov 2026: a click at the very end was refused, so the next one went on open ground
    // just off it and left a gap between the old track and the new)
    const tail = LEAD + DEPART + 1;
    const cont: Join['cont'] = s < tail && q.start.kind === 'stop' ? 'start' : q.length - s < tail && q.end.kind === 'stop' ? 'end' : null;
    if (!cont && (s < LEAD + DEPART + 1 || q.length - s < LEAD + DEPART + 1)) return { a: null, why: 'Too near the end of that line to make a junction' };
    // never inside a station's passing loop (or the turnout of another branch): a turnout on a turnout
    if (!cont) {
      const room = LEAD + DEPART + 2;
      for (const o of w.rails) {
        for (const e of [o.start, o.end]) {
          if (e.kind !== 'join' || e.path !== q.id || e.s === undefined) continue;
          const lo = o.kind === 'loop' ? Math.min(o.start.s ?? 0, o.end.s ?? 0) : e.s, hi = o.kind === 'loop' ? Math.max(o.start.s ?? 0, o.end.s ?? 0) : e.s;
          if (s > lo - room && s < hi + room) return { a: null, why: o.kind === 'loop' ? 'That is the station’s passing loop: join the line beyond it' : 'Too near another junction: join the line further along' };
        }
      }
    }

    let node = -1;
    if (cont) {
      const e = railAt(q, cont === 'start' ? 0 : q.length);
      const out = cont === 'start' ? -1 : 1;
      // straight on from the buffers, a little further each try: a line laid close beside another has its own and
      // the other's track on every tile just past its end (2 Nov 2026: a parallel line couldn't be carried on)
      const way = { x: e.x, z: e.z, tx: e.tx * out, tz: e.tz * out };
      for (const k of [1.6, 3, 4.5, 6]) if ((node = freeNodeNear(w, e.x + e.tx * out * k, e.z + e.tz * out * k, afloat, way)) >= 0) break;
    } else node = freeNodeNear(w, at.x - at.tz * side * 1.4, at.z + at.tx * side * 1.4, afloat);
    // carried on from buffers with no open ground past them (a line laid close beside another, a station's lot):
    // still a start, for Shift's parallel track, which runs from the buffers themselves (node -1: nothing to route from)
    if (node < 0 && cont) return { a: { node: -1, join: { q, s, cont }, side }, why: '' };
    if (node < 0) return { a: null, why: 'No open ground beside the line to leave it from' };
    return { a: { node, join: { q, s, cont }, side, ...(wetNode(w, node) ? { wet: true } : {}) }, why: '' };
  }
  const node = nodeAt(x, z, false);
  const p = nodeProblem(w, node, false);
  // out over deep water: an end only a raised track may have (the builder holds it to SEA_CLEAR)
  if (p && afloat && seaNode(w, node)) return { a: { node, join: null, side: 1, wet: true }, why: '' };
  if (p) return { a: null, why: p };
  if (w.rail[node] & (RailBit.Track | RailBit.Pad | RailBit.Loop)) return { a: null, why: 'A railway is in the way: click on the line itself to join it' };
  return { a: { node, join: null, side: 1 }, why: '' };
}

/**
 * The first piece of a track from an anchor, for the builder's ghost before the first click (the user, 2 Nov
 * 2026: it should show whether the click starts a new track or carries one on): from a line's buffers to the
 * node, a turnout's lead off a line to the node, or on open ground a tile's stub. Null where none fits.
 */
export function firstPiece(w: World, a: Anchor, era: RailEra, lift = 0): RailSpec | null {
  if (a.node < 0) return null;
  const [cx, cz] = nodeCenter(a.node, false);
  if (a.join) {
    const q = a.join.q;
    const at = railAt(q, a.join.cont ? (a.join.cont === 'start' ? 0 : q.length) : a.join.s);
    const lead = leadOf(a.join, cx - at.x, cz - at.z, true);
    if (!lead) return null;
    // off a line on a viaduct (out over the water, or high over the ground), the branch leaves at the line's own height
    const y = raisedJoin(w, a) !== undefined ? lead.pts[lead.pts.length - 1] : tileMean(w, a.node) + RAIL_LIFT;
    return { p: [...lead.pts, cx, cz, y], era, a: lead.end };
  }
  for (const step of [1, N, -1, -N]) {
    const b = a.node + step;
    const bWet = a.wet && wetNode(w, b);
    if (b < 0 || b >= N * N || (!bWet && nodeProblem(w, b, false)) || (w.rail[b] & (RailBit.Track | RailBit.Pad | RailBit.Loop))) continue;
    const r: Route = { nodes: [a.node, b], bridges: [] };
    if (!a.wet && !lift) return { p: pointsOf(r, heightsOf(w, r)), era };
    // raised (over the sea, its surface's height plus the lift): a level stub at that height
    const top = (n: number) => Math.max(tileMean(w, n), w.water[n] >= 0 ? w.water[n] : -Infinity) + lift + RAIL_LIFT;
    const y = Math.max(top(a.node), top(b));
    return { p: pointsOf(r, [y, y]), era };
  }
  return null;
}

/** DIRS index from node a to the next node b along a route, or -1 off the grid. */
const dirOf = (a: number, b: number): number => { const d = b - a; return d === 1 ? 0 : d === N ? 1 : d === -1 ? 2 : d === -N ? 3 : -1; };

/** The rails' own rules over a planned route: never along a road, never across a line on the level, not too long. */
export function routeProblem(w: World, r: Route): string | null {
  const n = r.nodes;
  const onDeck = new Set<number>();
  for (const b of r.bridges) if (!b.level && !b.tunnel) for (let k = b.from + 1; k < b.to; k++) onDeck.add(k);
  let run = 0, runDir = -1;
  for (let k = 0; k < n.length; k++) {
    const t = n[k];
    const rb = w.rail[t];
    if (k > 0 && k < n.length - 1 && !onDeck.has(k) && (rb & (RailBit.Track | RailBit.Pad | RailBit.Loop))) return 'It would cross a line on the level: raise it over (+ with Big bridges), or join the line instead';
    if (w.road[t] && !onDeck.has(k) && !w.deckAxis[t]) {
      const d = k > 0 ? dirOf(n[k - 1], t) : -1;
      run = run && d === runDir ? run + 1 : 1;
      runDir = d;
      if (run > 3 || (k + 1 < n.length && run > 1 && dirOf(t, n[k + 1]) !== runDir)) return 'A railway doesn’t run along a road: cross it square on, or lay the track beside it';
    } else run = 0;
  }
  if (n.length > MAX_POINTS - 12) return `Too long for one track: lay it in two (${MAX_POINTS} tiles at most)`;
  return null;
}

/** Rail-top heights per node, in steps: the ground plus the rail's lift, or the deck a bridge puts under it. */
export function heightsOf(w: World, r: Route): number[] {
  const h = r.nodes.map((n) => tileMean(w, n) + RAIL_LIFT);
  for (const b of r.bridges) {
    const L = b.to - b.from;
    if (b.level) { h[b.from] = b.h0 / STEP + RAIL_LIFT; continue; }
    for (let k = b.from; k <= b.to; k++) {
      const y = deckHeightAt(b, L, k - b.from) / STEP + RAIL_LIFT;
      h[k] = b.tunnel ? y : Math.max(h[k], y);
    }
  }
  return h;
}

/** The route's points as a spec takes them: tile centres and heights. */
export function pointsOf(r: Route, h: number[]): number[] {
  const out: number[] = [];
  r.nodes.forEach((n, k) => { const [x, z] = nodeCenter(n, false); out.push(x, z, h[k]); });
  return out;
}

/**
 * The shared stretch of a junction: for a start, points along the line up to DEPART short of the foot, from
 * which the track slants off to its first node; for an end, from where it slants onto the line and along it.
 * (vx, vz) is the way the track runs at that end, which picks the way along the line it merges. Null when
 * the line is too short there.
 */
export function leadOf(j: Join, vx: number, vz: number, atStart: boolean): { pts: number[]; end: RailEnd } | null {
  const q = j.q;
  if (j.cont) {
    const sE = j.cont === 'start' ? 0 : q.length;
    const e = railAt(q, sE);
    return { pts: [e.x, e.z, e.y / STEP], end: { kind: 'join', path: q.id, s: sE, dir: j.cont === 'start' ? 1 : -1 } };
  }
  const at = railAt(q, j.s);
  let lam: 1 | -1 = vx * at.tx + vz * at.tz >= 0 ? 1 : -1;
  const fits = (l: 1 | -1) => (atStart ? j.s - l * (DEPART + LEAD) >= 0 && j.s - l * (DEPART + LEAD) <= q.length : j.s + l * (DEPART + LEAD) >= 0 && j.s + l * (DEPART + LEAD) <= q.length);
  if (!fits(lam)) { if (fits(-lam as 1 | -1)) lam = -lam as 1 | -1; else return null; }
  const pts: number[] = [];
  if (atStart) {
    const s0 = j.s - lam * (DEPART + LEAD);
    for (let k = 0; k <= LEAD; k++) { const a = railAt(q, s0 + lam * k); pts.push(a.x, a.z, a.y / STEP); }
    return { pts, end: { kind: 'join', path: q.id, s: s0, dir: -lam as 1 | -1 } };
  }
  const sD = j.s + lam * DEPART, s1 = sD + lam * LEAD;
  for (let k = 0; k <= LEAD; k++) { const a = railAt(q, sD + lam * k); pts.push(a.x, a.z, a.y / STEP); }
  return { pts, end: { kind: 'join', path: q.id, s: s1, dir: lam } };
}

/** The spec a route between two anchors lays: its points, with the junction leads and joins at either end. Null with why. */
export function specOf(w: World, r: Route, a: Anchor, b: Anchor, era: RailEra): { spec: RailSpec; why?: undefined } | { spec: null; why: string } {
  const h = heightsOf(w, r);
  const pts = pointsOf(r, h);
  if (pts.length < 6) return { spec: null, why: 'Too short to lay' };
  const spec: RailSpec = { p: pts, era };
  if (a.join) {
    const lead = leadOf(a.join, pts[3] - pts[0], pts[4] - pts[1], true);
    if (!lead) return { spec: null, why: 'No room along that line for the junction' };
    spec.p = [...lead.pts, ...pts];
    spec.a = lead.end;
  }
  if (b.join) {
    const L = pts.length;
    const lead = leadOf(b.join, pts[L - 3] - pts[L - 6], pts[L - 2] - pts[L - 5], false);
    if (!lead) return { spec: null, why: 'No room along that line for the junction' };
    spec.p = [...spec.p, ...lead.pts];
    spec.b = lead.end;
  }
  return { spec };
}

/**
 * A track over the strait to the next county, as a road's (game/roadBuilder.ts straitParts): the near half out
 * from the shore to a platform on the border tile, the far half from the platform across the line down to the
 * far shore and on (world/roads.ts StraitDeck). `back` is the far half's route as the plan across found it.
 */
export function straitRoutes(plan: RoutePlan, d: number, sd: StraitDeck, back: Route): { halves: [Route, Route] } | { why: string } {
  const near = routeWithBridges(plan, sd.n, RoadType.Paved, { boats: true, notArriving: (d + 2) & 3 });
  if (!near) return { why: 'No way to the shore the bridge leaves from' };
  const step = DIRS[d][0] + DIRS[d][1] * N;
  const under = new Set<number>();
  for (let t = sd.n + step; t !== sd.a + step; t += step) under.add(t);
  if (near.nodes.some((t) => under.has(t))) return { why: 'The track would run under its own bridge: start it from inland of the shore' };
  const nodes = [...near.nodes];
  const iN = nodes.length - 1;
  for (let t = sd.n + step; t !== sd.a; t += step) nodes.push(t);
  nodes.push(sd.a);
  const iA = nodes.length - 1;
  const bridges: Bridge[] = [...near.bridges, { ...sd.near, from: iN, to: iA }, { from: iA, to: iA, h0: sd.h, h1: sd.h, raised: 1, level: true }];
  const farNodes = [sd.b];
  for (let t = sd.b + step; t !== sd.m; t += step) farNodes.push(t);
  farNodes.push(sd.m);
  const iM = farNodes.length - 1;
  farNodes.push(...back.nodes.slice(1));
  const farBridges: Bridge[] = [
    { from: 0, to: 0, h0: sd.h, h1: sd.h, raised: 1, level: true }, { ...sd.far, from: 0, to: iM },
    ...back.bridges.map((b) => ({ ...b, from: b.from + iM, to: b.to + iM })),
  ];
  return { halves: [{ nodes, bridges }, { nodes: farNodes, bridges: farBridges }] };
}
