import type { Input } from './input';

/**
 * A PlayStation 5 DualSense (or any pad in the browser's standard layout) played through the
 * keyboard the game already understands. The browser only lets a page poll a pad, so once a frame
 * its buttons are read and each press is sent on as the key it stands for — a real keydown and
 * keyup on whatever has focus — so every hotkey, the pause menu and the panels take it unchanged.
 * The sticks and triggers are analog and read straight from the pad by Input.
 *
 *   R2 / L2          drive / brake and reverse        left stick   steer
 *   right stick      turn the camera, zoom            L3           camera lock (R)
 *   ✕                hold: handbrake, climb; tap: load cargo (Space)   ○   descend, nitrous (Shift)
 *   touchpad         load cargo (a tap of Space)
 *   □                take the wheel (Tab)             △            HQ window (H)
 *   L1 / R1          camera turn (Q / E)              R3           inventory (I)
 *   d-pad ↑ ↓ ← →    road builder, bulldozer, cash, settings (B X C O)
 *   Create           overview map (M)                 Options      pause (Esc)
 *
 * In a menu the d-pad moves, ✕ is Enter, ○ is Esc and L1 / R1 are Tab back and forward.
 * With the road builder or bulldozer out, the d-pad pans, ✕ clicks the middle of the screen,
 * □ switches the builder's mode (F), △ undoes (Z) and ○ steps back (Esc).
 */
type PadContext = 'play' | 'tool' | 'menu';

// standard-layout button indices
const CROSS = 0, CIRCLE = 1, SQUARE = 2, TRIANGLE = 3, L1 = 4, R1 = 5, CREATE = 8, OPTIONS = 9, L3 = 10, R3 = 11;
const UP = 12, DOWN = 13, LEFT = 14, RIGHT = 15, TOUCHPAD = 17;

/** A key, with Shift held for Shift+Tab. */
type Press = { code: string; shift?: boolean } | 'click' | null;

const ARROWS: Record<number, string> = { [UP]: 'ArrowUp', [DOWN]: 'ArrowDown', [LEFT]: 'ArrowLeft', [RIGHT]: 'ArrowRight' };

function mapButton(i: number, ctx: PadContext): Press {
  if (i === OPTIONS) return { code: 'Escape' };
  if (ctx === 'menu') {
    if (ARROWS[i]) return { code: ARROWS[i] };
    if (i === CROSS) return { code: 'Enter' };
    if (i === CIRCLE) return { code: 'Escape' };
    if (i === L1) return { code: 'Tab', shift: true };
    if (i === R1) return { code: 'Tab' };
    return null;
  }
  if (ctx === 'tool') {
    if (ARROWS[i]) return { code: ARROWS[i] };
    if (i === CROSS) return 'click';
    if (i === CIRCLE) return { code: 'Escape' };
    if (i === SQUARE) return { code: 'KeyF' };
    if (i === TRIANGLE) return { code: 'KeyZ' };
    if (i === L1) return { code: 'KeyQ' };
    if (i === R1) return { code: 'KeyE' };
    return null;
  }
  switch (i) {
    case CROSS: return { code: 'Space' };
    case CIRCLE: return { code: 'ShiftLeft' };
    case SQUARE: return { code: 'Tab' };
    case TRIANGLE: return { code: 'KeyH' };
    case L1: return { code: 'KeyQ' };
    case R1: return { code: 'KeyE' };
    case CREATE: return { code: 'KeyM' };
    case L3: return { code: 'KeyR' };
    case TOUCHPAD: return { code: 'Space' };
    case R3: return { code: 'KeyI' };
    case UP: return { code: 'KeyB' };
    case DOWN: return { code: 'KeyX' };
    case LEFT: return { code: 'KeyC' };
    case RIGHT: return { code: 'KeyO' };
  }
  return null;
}

const KEY_NAMES: Record<string, string> = {
  Space: ' ', Enter: 'Enter', Escape: 'Escape', Tab: 'Tab', ShiftLeft: 'Shift',
  ArrowUp: 'ArrowUp', ArrowDown: 'ArrowDown', ArrowLeft: 'ArrowLeft', ArrowRight: 'ArrowRight',
};

/** The DualSense first, then any other pad the browser lays out in the standard way. */
export function activePad(): Gamepad | null {
  const pads = navigator.getGamepads?.();
  if (!pads) return null;
  let other: Gamepad | null = null;
  for (const p of pads) {
    if (!p || !p.connected || p.mapping !== 'standard') continue;
    if (isDualSense(p)) return p;
    other ??= p;
  }
  return other;
}

/** Sony's vendor id and the DualSense (0ce6) or DualSense Edge (0df2) product. */
function isDualSense(p: Gamepad): boolean {
  const id = p.id.toLowerCase();
  return (id.includes('054c') && (id.includes('0ce6') || id.includes('0df2'))) || id.includes('dualsense');
}

/** Held long enough, a d-pad direction in a menu repeats like a held arrow key. */
const REPEAT_DELAY = 0.4, REPEAT_EVERY = 0.11;
/** Full right stick zooms by about e per second (the camera takes wheel deltas at 0.0012 each). */
const ZOOM_RATE = 800;
const DEAD = 0.15;

export class PadBridge {
  /** The press each held button sent, so its release lets go of the same key. */
  private held = new Map<number, Press>();
  private repeatAt = new Map<number, number>();
  private padId = '';
  private clock = 0;

  /** Announces a pad arriving or leaving (the HUD's toast). */
  onConnect: (name: string, connected: boolean) => void = () => {};

  constructor(private input: Input) {
    window.addEventListener('gamepadconnected', (e) => this.onConnect(padName(e.gamepad), true));
    window.addEventListener('gamepaddisconnected', (e) => {
      if (e.gamepad.id === this.padId) this.releaseAll();
      this.onConnect(padName(e.gamepad), false);
    });
    document.addEventListener('visibilitychange', () => { if (document.hidden) this.releaseAll(); });
  }

  /** Read the pad once, at the top of a frame, before anything asks Input what is pressed. */
  poll(dt: number, ctx: PadContext): void {
    this.clock += dt;
    const p = document.hidden ? null : activePad();
    if (!p) { this.releaseAll(); return; }
    if (p.id !== this.padId) { this.releaseAll(); this.padId = p.id; }

    for (let i = 0; i < p.buttons.length; i++) {
      const down = p.buttons[i].pressed;
      const was = this.held.has(i);
      if (down && !was) {
        const press = mapButton(i, ctx);
        this.held.set(i, press);
        this.send(press, 'keydown', false);
        if (ctx === 'menu' && ARROWS[i]) this.repeatAt.set(i, this.clock + REPEAT_DELAY);
      } else if (!down && was) {
        this.send(this.held.get(i)!, 'keyup', false);
        this.held.delete(i);
        this.repeatAt.delete(i);
      } else if (down) {
        const at = this.repeatAt.get(i);
        if (at !== undefined && this.clock >= at) {
          this.send(this.held.get(i)!, 'keydown', true);
          this.repeatAt.set(i, this.clock + REPEAT_EVERY);
        }
      }
    }

    // the right stick: across turns the camera (Input.orbit reads it), up and down zooms
    const zy = p.axes[3] ?? 0;
    if (ctx !== 'menu' && Math.abs(zy) > DEAD) this.input.wheel += Math.sign(zy) * (Math.abs(zy) - DEAD) / (1 - DEAD) * ZOOM_RATE * dt;

    // with a tool out, the pad's cursor is the middle of the screen, where the tool's focus sits
    if (ctx === 'tool' && this.touched(p)) this.input.aimAtCentre();
  }

  /** A short shake for a knock, harder the harder the hit (0..1). */
  rumble(strength: number): void {
    const act = activePad()?.vibrationActuator;
    if (!act || strength <= 0) return;
    const s = Math.min(1, strength);
    act.playEffect('dual-rumble', { duration: 80 + 160 * s, strongMagnitude: s, weakMagnitude: Math.min(1, 0.3 + s * 0.7) })
      .catch(() => { /* no rumble on this pad or browser */ });
  }

  private touched(p: Gamepad): boolean {
    return this.held.size > 0 || p.axes.some((a) => Math.abs(a) > DEAD) || (p.buttons[6]?.value ?? 0) > 0.12 || (p.buttons[7]?.value ?? 0) > 0.12;
  }

  private send(press: Press, type: 'keydown' | 'keyup', repeat: boolean): void {
    if (!press) return;
    if (press === 'click') { if (type === 'keydown') this.input.clickCentre(); return; }
    // sent where a real key would land, so a focused menu button sees it as its own
    const target = document.activeElement ?? document.body;
    target.dispatchEvent(new KeyboardEvent(type, {
      code: press.code, key: KEY_NAMES[press.code] ?? press.code.replace(/^Key/, '').toLowerCase(),
      shiftKey: !!press.shift, repeat, bubbles: true, cancelable: true,
    }));
  }

  private releaseAll(): void {
    for (const press of this.held.values()) this.send(press, 'keyup', false);
    this.held.clear();
    this.repeatAt.clear();
    this.padId = '';
  }
}

function padName(p: Gamepad): string {
  return isDualSense(p) ? 'DualSense controller' : p.id.replace(/\s*\(.*$/, '') || 'Controller';
}
