/**
 * The bar a visitor from a postcard's link sees (docs/postcards.html, phase 3), and nothing else of the HUD:
 * what the postcard is and whose, how many are playing, and three ways on. Take a car makes a fleet in one
 * click; Look around folds the bar into a pill and gives them the camera; I have a fleet goes to the title.
 * On a phone, which can watch but not drive, Take a car is Send this to my computer (the link copied).
 */

interface GuestBarHost {
  take(): void;
  have(): void;
  /** The postcard's link, to copy. */
  link(): string;
  /** Report the postcard's picture (shown to whoever opens the link as its preview); whether it went. */
  report(): Promise<boolean>;
  /** Whether it has a picture to report. */
  hasPicture(): boolean;
}

const esc = (s: string): string => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));

/** A touch screen with no mouse: watching only (index.html says the same on its mobile card). */
function touchOnly(): boolean {
  const mm = (q: string) => !!window.matchMedia?.(q).matches;
  return (mm('(pointer: coarse)') && !mm('(any-pointer: fine)')) || /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);
}

export class GuestBar {
  private el = document.createElement('div');
  private folded = false;
  private info = { title: '', fleet: '', colour: 0, players: 0 };
  private note = '';
  private busy = '';
  readonly touch = touchOnly();
  /** The visitor has turned the camera, zoomed or clicked something (counted once, for the funnel). */
  onLooked: () => void = () => {};
  private hasLooked = false;
  private reported = false;

  constructor(private host: GuestBarHost) {
    this.el.id = 'guest-bar';
    this.el.hidden = true;
    document.body.append(this.el);
    this.el.addEventListener('click', (e) => {
      const b = (e.target as HTMLElement).closest('button[data-g]') as HTMLElement | null;
      if (!b || this.busy) return;
      const g = b.dataset.g;
      if (g === 'take') this.host.take();
      else if (g === 'look') { this.folded = true; this.looked(); this.render(); }
      else if (g === 'open') { this.folded = false; this.render(); }
      else if (g === 'have') this.host.have();
      else if (g === 'report') {
        void this.host.report().then((ok) => { this.reported = true; this.note = ok ? 'Thanks: the picture has been reported, and will be looked at.' : 'That didn’t go: try again in a moment.'; this.render(); });
      }
      else if (g === 'copy') {
        const url = this.host.link();
        void navigator.clipboard.writeText(url).then(() => { this.note = 'Copied: open it on a computer to drive'; this.render(); },
          () => { this.note = url; this.render(); });
      }
    });
  }

  show(info: { title: string; fleet: string; colour: number; players: number }): void {
    this.info = info;
    this.folded = false;
    this.note = '';
    this.busy = '';
    this.hasLooked = false;
    this.reported = false;
    this.el.hidden = false;
    this.render();
  }

  hide(): void { this.el.hidden = true; }

  /** Something is under way (making the fleet): the buttons wait. */
  wait(text: string): void { this.busy = text; this.folded = false; this.render(); }
  /** It didn't work: say why, and the buttons are back. */
  fail(why: string): void { this.busy = ''; this.note = why; this.folded = false; this.render(); }

  looked(): void {
    if (this.hasLooked) return;
    this.hasLooked = true;
    this.onLooked();
  }

  private render(): void {
    const i = this.info;
    const dot = `<i class="dot" style="background:#${i.colour.toString(16).padStart(6, '0')}"></i>`;
    const take = this.touch
      ? '<button type="button" data-g="copy" class="go">📲 Send this to my computer</button>'
      : '<button type="button" data-g="take" class="go">🚗 Take a car</button>';
    if (this.folded) {
      this.el.className = 'folded';
      this.el.innerHTML = `<span class="gb-tip">${this.touch ? 'Watching' : 'Drag to turn · scroll to zoom · click a vehicle to follow it'}</span>`
        + take + '<button type="button" data-g="open" class="quiet">📮</button>';
      return;
    }
    this.el.className = '';
    this.el.innerHTML = `<div class="gb-head"><b>${esc(i.title)}</b><small>${dot}a postcard from ${esc(i.fleet)}</small>`
      + `<small class="gb-n">${i.players ? `${i.players} fleet${i.players === 1 ? ' is' : 's are'} playing now` : 'a shared world anyone can drive into'}</small></div>`
      + (this.busy ? `<div class="gb-busy">${esc(this.busy)}</div>`
        : `<div class="gb-acts">${take}${this.touch ? '' : '<button type="button" data-g="look">Look around</button>'}`
          + '<button type="button" data-g="have" class="quiet">I have a fleet</button></div>')
      + (this.note ? `<p class="gb-note">${esc(this.note)}</p>` : '')
      + (this.touch ? '<p class="gb-note">TinyFleet is driven with a keyboard: on a phone you can watch.</p>' : '')
      + (this.host.hasPicture() && !this.reported ? '<button type="button" data-g="report" class="gb-report">Report this postcard’s picture</button>' : '');
  }
}
