import { Atlas, MAP_PIX, PALETTE, TILES_PER_PIX } from '../world/atlas';
import type { KnownAirport } from '../world/surveyor';
import { MUNI, MUNI_PER } from '../world/municipality';
import { BLOB_MIN, TerritoryLegend, drawCell, haloFor, onTerritoryShown, territoryButton, territoryShown, type TerritoryPaint } from '../render/territoryLayer';

/** Cells across the little map in the corner. */
const MINI_CELLS = 5;
const MINI = MINI_CELLS * MAP_PIX;
/** Cells of empty sea kept around the explored edge, so the world always looks like it goes on. */
const PAD = 1;

const rgb = (i: number): [number, number, number] => {
  const c = PALETTE[i] ?? PALETTE[0];
  return [(c >> 16) & 255, (c >> 8) & 255, c & 255];
};

/** The player's marker, and the ring around it that keeps it findable on a busy map. */
const YOU = [226, 65, 47] as const;
const YOU_RING = [255, 255, 255] as const;
/** One of the player's vehicles on the road to them, and its ring. */
const MINE = [30, 158, 74] as const;
const MINE_RING = [255, 255, 255] as const;

/** A vehicle of the player's somewhere on the lattice, in world tiles, with how long it has left. */
export interface Pip { x: number; z: number; eta: string; name: string }

/** The town selected as a whole (docs/towns.html): its border in world tiles, and how far into its breath the pulse is. */
interface MapTown { key: string; name: string; loops: Float32Array[]; centre: { x: number; z: number } | null; breath: number }

/** A town's size as the world map ranks its name: the bigger, the sooner (zoomed out) and the bolder it is written. */
const TOWN_RANK: Record<string, number> = { mega: 4, metro: 3, city: 2, suburb: 1, rural: 0 };
/** Each rank's lettering: a megalopolis and a metro in spaced capitals, a city bold, a town plain, a village small and soft. */
const NAME_STYLE: { font: string; h: number; caps: boolean; fill: string; halo: number }[] = [
  { font: '500 10px "IBM Plex Sans", "Segoe UI", system-ui, sans-serif', h: 11, caps: false, fill: '#dfe6e1', halo: 2.5 },
  { font: '600 11px "IBM Plex Sans", "Segoe UI", system-ui, sans-serif', h: 12, caps: false, fill: '#f4f7f1', halo: 3 },
  { font: '700 12px "IBM Plex Sans", "Segoe UI", system-ui, sans-serif', h: 13, caps: false, fill: '#ffffff', halo: 3 },
  { font: '700 12px "IBM Plex Sans", "Segoe UI", system-ui, sans-serif', h: 14, caps: true, fill: '#fff6dc', halo: 3.5 },
  { font: '800 14px "IBM Plex Sans", "Segoe UI", system-ui, sans-serif', h: 16, caps: true, fill: '#ffe9a8', halo: 4 },
];

/** Whether town names on the big map are hidden or shown, remembered on this device. */
const NAMES_KEY = 'pocket-roads-map-names';

/** A rival firm's depot: its cell, the place in it, its body and accent colours and its name. */
/** A rival depot on the map; `pref` when the firm is some town's preferred carrier (only those are named: nearly every county has a firm). */
interface FirmPin { cx: number; cz: number; x: number; z: number; colour: number; accent: number; name: string; pref?: boolean }

/** A selected unit's manifest: where it is and the calls it has still to make, in world tiles. */
export interface Round { x: number; z: number; stops: { x: number; z: number; drop: boolean }[] }

/** The round's line, and its calls: a pickup blue, a drop green, as on the inspector's card. */
const ROUTE = [255, 214, 90] as const;
const PICKUP = [79, 159, 207] as const;
const DROP = [57, 211, 83] as const;


/**
 * The map.
 *
 * In the island overview a small square in the corner shows the cells around the player. Clicking
 * it opens the whole explored world at eight tiles to the pixel: everywhere the player has been
 * within fifty tiles of, drawn as it looked, and flat black everywhere else.
 */
export class MapView {
  /** True while the full map is up; the game waits, as it does for any other panel. */
  open = false;
  /** The player's lots, for gold pins: cell and place in it. */
  pins: (() => { cx: number; cz: number; x: number; z: number }[]) | null = null;
  /** Lit bookmarks and waiting import crates (docs/passport.html): a star each, with its name; `hot` pulses the one just asked for. */
  stars: (() => { cx: number; cz: number; x: number; z: number; label: string; hot?: boolean; crate?: boolean }[]) | null = null;
  /** The depots of rival firms met (docs/rivals.html), for a flag each in their livery. */
  firms: (() => FirmPin[]) | null = null;
  /** Today's events within reach (docs/events.html): their icon and what and when, on both maps. */
  events: (() => { cx: number; cz: number; x: number; z: number; icon: string; label: string; now: boolean }[]) | null = null;
  private mini = document.createElement('canvas');
  private miniWrap = document.createElement('button');
  private overlay = document.createElement('div');
  private big = document.createElement('canvas');
  private caption = document.createElement('div');
  private miniCtx: CanvasRenderingContext2D;
  private bigCtx: CanvasRenderingContext2D;
  private miniImg: ImageData;
  /** Everything of the player's on the road after them, for the dots on both maps. */
  pips: () => Pip[] = () => [];
  /** Online: the other players, in world tiles, dotted like the fleet on its way. */
  players: () => { x: number; z: number }[] = () => [];
  /** The manifest of the unit picked in the inspector, drawn as a line through its remaining calls. */
  route: () => Round | null = () => null;
  /** The town selected as a whole, drawn over both maps. */
  town: () => MapTown | null = () => null;
  /** A town's name on the big map has been clicked. */
  onPickTown: ((key: string) => void) | null = null;
  /** Every surveyed airport while the player flies, for their codes on the big map; null on the ground. */
  airports: () => KnownAirport[] | null = () => null;
  /** The region map's button beside the corner map (game/regionView.ts). */
  onRegion: (() => void) | null = null;
  /** The town register, from the big map's header (docs/townregister.html). */
  onTowns: (() => void) | null = null;
  private regionBtn = document.createElement('button');
  /** The big map's names and the selected town's line, drawn sharp over the pixels at screen resolution. */
  private bigWrap = document.createElement('div');
  private over = document.createElement('canvas');
  private overCtx: CanvasRenderingContext2D;
  private showNames = true;
  private namesBtn = document.createElement('button');
  /** Where each name was drawn last, in the wrap's CSS pixels, for clicking. */
  private hits: { key: string; x: number; y: number; w: number }[] = [];
  /** The territory layer (docs/territory.html), set by main; and the legend and hover lines it writes. */
  set territory(p: TerritoryPaint | null) {
    this.terr = p;
    this.terrLegend?.el.remove();
    this.terrLegend = p ? new TerritoryLegend(p) : null;
    if (this.terrLegend) this.overlay.append(this.terrLegend.el);
  }
  get territory(): TerritoryPaint | null { return this.terr; }
  private terr: TerritoryPaint | null = null;
  /** The key to the colours, in the map's corner while territory shows. */
  private terrLegend: TerritoryLegend | null = null;
  /** The legend under the map: each holder's name, towns and diamonds a day. */
  legend: (() => string) | null = null;
  /** What the pointer is over: a municipality's line ("Clover Flats · yours · weak · 58% of trade"). */
  describe: ((key: string) => string) | null = null;
  private hover = '';
  /** The overview's own territory toggle, above the region map's button. */
  private terrBtn = territoryButton('hud chip regionbtn terrbtn');
  /**
   * The last layout of the big map, for turning the pointer into a place: its top-left cell, screen pixels to a
   * map pixel, the map pixel at the view's top-left (from the top-left cell), and the view's size in CSS pixels.
   */
  private lastBig: { x0: number; z0: number; scale: number; ox: number; oy: number; fit: number; vw: number; vh: number } | null = null;
  /**
   * The big map zoomed in over the whole explored world (1) and the map pixel in the middle of the view, in
   * map pixels from the world's origin (null: the middle of the map). The user, 22 Oct 2026: the world map
   * zooms and pans.
   */
  private zoom = 1;
  private centre: { x: number; z: number } | null = null;
  private drag: { x: number; y: number; moved: number } | null = null;
  /** A drag just ended: the click it makes is not a click on a name. */
  private dragged = false;
  /** The player's place in map pixels, for "Centre on me". */
  private me = { x: 0, z: 0 };
  private zoomLabel = document.createElement('span');

  constructor() {

    this.miniWrap.className = 'hud chip minimap';
    this.miniWrap.type = 'button';
    this.miniWrap.hidden = true;
    this.mini.width = MINI;
    this.mini.height = MINI;
    const tag = document.createElement('span');
    tag.textContent = 'World map';
    this.miniWrap.append(this.mini, tag);
    this.miniWrap.addEventListener('click', () => this.toggle());
    document.body.append(this.miniWrap);
    // the region map sits between the two: seven by seven counties, in 3D
    this.regionBtn.className = 'hud chip regionbtn';
    this.regionBtn.type = 'button';
    this.regionBtn.hidden = true;
    this.regionBtn.innerHTML = '<b>Region map</b><kbd>Y</kbd>';
    this.regionBtn.addEventListener('click', () => this.onRegion?.());
    document.body.append(this.regionBtn);
    // and territory, one setting with the maps', over the overview's islands
    this.terrBtn.hidden = true;
    document.body.append(this.terrBtn);

    this.overlay.className = 'worldmap';
    this.overlay.hidden = true;
    const head = document.createElement('header');
    head.innerHTML = '<b>World map<span>.</span></b><span>drag to pan · wheel or <kbd>+</kbd> <kbd>−</kbd> to zoom · <kbd>M</kbd> or <kbd>Esc</kbd> close</span>';
    try { this.showNames = localStorage.getItem(NAMES_KEY) !== '0'; } catch { /* storage blocked */ }
    this.namesBtn.type = 'button';
    this.namesBtn.className = 'names';
    this.namesBtn.addEventListener('click', () => {
      this.showNames = !this.showNames;
      try { localStorage.setItem(NAMES_KEY, this.showNames ? '1' : '0'); } catch { /* storage blocked */ }
      this.namesBtn.textContent = this.showNames ? 'Hide town names' : 'Show town names';
    });
    this.namesBtn.textContent = this.showNames ? 'Hide town names' : 'Show town names';
    // the zoom: − and + (or the wheel, or + and − on the keyboard), back to the whole map, and onto the player
    const zoomBar = document.createElement('span');
    zoomBar.className = 'zoombar';
    const zb = (text: string, title: string, act: () => void) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.textContent = text;
      b.title = title;
      b.addEventListener('click', (e) => { e.stopPropagation(); act(); });
      return b;
    };
    this.zoomLabel.className = 'zl';
    zoomBar.append(
      zb('−', 'Zoom out (− or the wheel)', () => this.zoomBy(1 / 1.6)),
      this.zoomLabel,
      zb('+', 'Zoom in (+ or the wheel)', () => this.zoomBy(1.6)),
      zb('Whole map', 'See the whole explored world (0)', () => this.fit()),
      zb('Centre on me', 'Zoom in on where you are', () => { this.zoom = Math.max(this.zoom, 3); this.centre = { ...this.me }; }),
    );
    // the town register (docs/townregister.html): every town known, ranked
    const towns = document.createElement('button');
    towns.type = 'button';
    towns.className = 'names';
    towns.textContent = 'All towns';
    towns.title = 'Every town you know of, ranked and filtered';
    towns.addEventListener('click', (e) => { e.stopPropagation(); this.onTowns?.(); });
    head.append(zoomBar, this.namesBtn, towns, territoryButton());
    onTerritoryShown(() => { this.hover = ''; });
    this.bigWrap.addEventListener('mousemove', (e) => {
      if (!territoryShown() || !this.lastBig || !this.describe) { this.hover = ''; return; }
      const r = this.bigWrap.getBoundingClientRect();
      const L = this.lastBig;
      const gx = ((e.clientX - r.left) / L.scale + L.ox + L.x0 * MAP_PIX) * TILES_PER_PIX;
      const gz = ((e.clientY - r.top) / L.scale + L.oy + L.z0 * MAP_PIX) * TILES_PER_PIX;
      const cell = MAP_PIX * TILES_PER_PIX;
      const cx = Math.floor(gx / cell), cz = Math.floor(gz / cell);
      const m = this.atlasRef?.muni(cx, cz);
      const seen = this.atlasRef?.seenAt(gx, gz);
      const px = Math.floor((gx - cx * cell) / MUNI_PER), pz = Math.floor((gz - cz * cell) / MUNI_PER);
      const t = m && seen ? m[pz * MUNI + px] : -1;
      this.hover = t >= 0 ? this.describe(`${cx},${cz}#${t}`) : '';
    });
    this.bigWrap.addEventListener('mouseleave', () => { this.hover = ''; });
    this.caption.className = 'cap';
    this.bigWrap.className = 'bigwrap';
    this.over.className = 'over';
    this.bigWrap.append(this.big, this.over);
    // the wheel zooms about the pointer; dragging pans; a double click zooms in there
    this.bigWrap.addEventListener('wheel', (e) => {
      e.preventDefault();
      const r = this.bigWrap.getBoundingClientRect();
      this.zoomBy(Math.pow(1.0015, -e.deltaY * (e.deltaMode === 1 ? 33 : 1)), e.clientX - r.left, e.clientY - r.top);
    }, { passive: false });
    this.bigWrap.addEventListener('dblclick', (e) => {
      const r = this.bigWrap.getBoundingClientRect();
      this.zoomBy(2, e.clientX - r.left, e.clientY - r.top);
    });
    this.bigWrap.addEventListener('pointerdown', (e) => {
      if (e.button !== 0) return;
      this.drag = { x: e.clientX, y: e.clientY, moved: 0 };
      this.bigWrap.setPointerCapture(e.pointerId);
    });
    this.bigWrap.addEventListener('pointermove', (e) => {
      const d = this.drag, L = this.lastBig;
      if (!d || !L) return;
      const dx = e.clientX - d.x, dy = e.clientY - d.y;
      d.x = e.clientX;
      d.y = e.clientY;
      d.moved += Math.abs(dx) + Math.abs(dy);
      if (this.zoom <= 1) return;
      const c = this.centre ?? { x: L.ox + L.vw / L.scale / 2 + L.x0 * MAP_PIX, z: L.oy + L.vh / L.scale / 2 + L.z0 * MAP_PIX };
      this.centre = { x: c.x - dx / L.scale, z: c.z - dy / L.scale };
      this.bigWrap.classList.add('panning');
    });
    const up = (e: PointerEvent) => {
      if (!this.drag) return;
      this.dragged = this.drag.moved > 4;
      this.drag = null;
      this.bigWrap.classList.remove('panning');
      if (this.bigWrap.hasPointerCapture(e.pointerId)) this.bigWrap.releasePointerCapture(e.pointerId);
    };
    this.bigWrap.addEventListener('pointerup', up);
    this.bigWrap.addEventListener('pointercancel', up);
    this.bigWrap.addEventListener('click', (e) => {
      if (this.dragged) { this.dragged = false; return; }
      const r = this.bigWrap.getBoundingClientRect();
      const x = e.clientX - r.left, y = e.clientY - r.top;
      let best = '', bestD = 18;
      for (const h of this.hits) {
        const d = Math.max(0, Math.abs(x - h.x) - h.w / 2) + Math.abs(y - h.y);
        if (d < bestD) { bestD = d; best = h.key; }
      }
      if (best) this.onPickTown?.(best);
    });
    this.overlay.append(head, this.bigWrap, this.caption);
    this.overlay.addEventListener('click', (e) => { if (e.target === this.overlay) this.close(); });
    document.body.append(this.overlay);

    this.miniCtx = this.mini.getContext('2d')!;
    this.bigCtx = this.big.getContext('2d')!;
    this.overCtx = this.over.getContext('2d')!;
    this.miniCtx.imageSmoothingEnabled = false;
    this.bigCtx.imageSmoothingEnabled = false;
    this.miniImg = this.miniCtx.createImageData(MINI, MINI);
  }

  /** The corner map is only up while the island overview is. */
  setAvailable(v: boolean): void {
    this.miniWrap.hidden = !v;
    this.regionBtn.hidden = !v;
    this.terrBtn.hidden = !v;
    if (!v) this.close();
  }

  toggle(): void { if (this.open) this.close(); else this.show(); }
  show(): void { this.open = true; this.overlay.hidden = false; this.fit(); }

  /** The whole explored world in view. */
  fit(): void { this.zoom = 1; this.centre = null; }

  /**
   * Zoom by a factor, about a point of the view in CSS pixels (its middle when left out): the place under it
   * stays under it. From one map pixel to (about) forty-eight screen pixels across, a county to the screen.
   */
  zoomBy(f: number, px?: number, py?: number): void {
    const L = this.lastBig;
    if (!L) return;
    const max = Math.max(1, 48 / L.fit);
    const z = Math.max(1, Math.min(max, this.zoom * f));
    if (z === this.zoom) return;
    const ax = px ?? L.vw / 2, ay = py ?? L.vh / 2;
    // the map pixel under the anchor, before and after
    const mx = L.ox + ax / L.scale + L.x0 * MAP_PIX, mz = L.oy + ay / L.scale + L.z0 * MAP_PIX;
    const s2 = L.fit * z;
    this.zoom = z;
    this.centre = z <= 1 ? null : { x: mx - ax / s2 + L.vw / s2 / 2, z: mz - ay / s2 + L.vh / s2 / 2 };
  }
  close(): void { this.open = false; this.overlay.hidden = true; }

  private atlasRef: Atlas | null = null;

  /** Redraw both maps. `gx`, `gz` are the player's place in world tiles. */
  draw(atlas: Atlas, gx: number, gz: number): void {
    this.atlasRef = atlas;
    if (!this.miniWrap.hidden) this.drawMini(atlas, gx, gz);
    if (this.open) this.drawBig(atlas, gx, gz);
  }

  /**
   * Over the big map, at screen resolution: every known town's name where the player has seen it, and
   * the selected town's line with its name in a pill. `x0`, `z0` are the map's top-left cell.
   */
  private drawOver(atlas: Atlas, x0: number, z0: number, cw: number, ch: number, scale: number, ox: number, oy: number): void {
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    if (this.over.width !== Math.round(cw * dpr) || this.over.height !== Math.round(ch * dpr)) {
      this.over.width = Math.round(cw * dpr);
      this.over.height = Math.round(ch * dpr);
    }
    this.over.style.width = `${cw}px`;
    this.over.style.height = `${ch}px`;
    const ctx = this.overCtx;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, cw, ch);
    // world tiles to the view's CSS pixels, through the zoom and the pan
    const fx = (x: number) => (x / TILES_PER_PIX - x0 * MAP_PIX - ox) * scale;
    const fz = (z: number) => (z / TILES_PER_PIX - z0 * MAP_PIX - oy) * scale;
    // the cells in view, from the map's top-left one
    const i0 = Math.max(0, Math.floor(ox / MAP_PIX)), i1 = Math.ceil((ox + cw / scale) / MAP_PIX);
    const j0 = Math.max(0, Math.floor(oy / MAP_PIX)), j1 = Math.ceil((oy + ch / scale) / MAP_PIX);
    // territory (docs/territory.html): each seen county's municipalities in their holders' colours
    if (this.territory && territoryShown()) {
      for (let j = j0; j < j1; j++) {
        for (let i = i0; i < i1; i++) {
          const px = this.territory.cell(x0 + i, z0 + j);
          if (px) drawCell(ctx, px, (i * MAP_PIX - ox) * scale, (j * MAP_PIX - oy) * scale, MAP_PIX * scale);
        }
      }
    }
    const town = this.town();
    if (town?.loops.length) strokeLoops(ctx, town.loops, fx, fz, 2, 0.55 + 0.45 * town.breath);

    this.hits = [];
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const label = (key: string, name: string, x: number, y: number, big: boolean) => {
      ctx.font = `${big ? 700 : 600} ${big ? 13 : 11}px "IBM Plex Sans", "Segoe UI", system-ui, sans-serif`;
      const w = ctx.measureText(name).width;
      if (big) {
        ctx.fillStyle = 'rgba(255, 255, 255, 0.95)';
        ctx.strokeStyle = 'rgba(255, 200, 61, 1)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.roundRect(x - w / 2 - 8, y - 11, w + 16, 22, 11);
        ctx.fill();
        ctx.stroke();
        ctx.fillStyle = '#1f2b33';
        ctx.fillText(name, x, y + 0.5);
      } else {
        ctx.lineWidth = 3;
        ctx.strokeStyle = 'rgba(10, 13, 17, 0.75)';
        ctx.strokeText(name, x, y);
        ctx.fillStyle = '#f4f7f1';
        ctx.fillText(name, x, y);
      }
      this.hits.push({ key, x, y, w: w + (big ? 16 : 4) });
    };
    if (this.showNames) {
      // fewer names and clearer ones (the user, 5 Nov 2026: the whole map was a thicket of names): the biggest towns
      // first and boldest; a smaller town's name only once zoomed in far enough for it (cities and up at once, towns
      // from ×2, villages from ×3.5); and no name written over another already there
      const least = this.zoom >= 3.5 ? 0 : this.zoom >= 2 ? 1 : 2;
      const places = atlas.knownPlaces().filter((p) => (TOWN_RANK[p.kind] ?? 0) >= least)
        .sort((a, b) => (TOWN_RANK[b.kind] ?? 0) - (TOWN_RANK[a.kind] ?? 0));
      const taken: [number, number, number, number][] = [];
      ctx.save();
      for (const p of places) {
        const key = `${p.cx},${p.cz}#${p.id}`;
        if (town && key === town.key) continue;
        const x = fx(p.cx * MAP_PIX * TILES_PER_PIX + p.x), y = fz(p.cz * MAP_PIX * TILES_PER_PIX + p.z) - 8;
        if (x < -80 || y < -20 || x > cw + 80 || y > ch + 20) continue;
        const st = NAME_STYLE[TOWN_RANK[p.kind] ?? 0];
        const name = st.caps ? p.name.toUpperCase() : p.name;
        ctx.font = st.font;
        ctx.letterSpacing = st.caps ? '1px' : '0px';
        const w = ctx.measureText(name).width;
        const box: [number, number, number, number] = [x - w / 2 - 3, y - st.h / 2 - 1, x + w / 2 + 3, y + st.h / 2 + 1];
        if (taken.some((q) => box[0] < q[2] && box[2] > q[0] && box[1] < q[3] && box[3] > q[1])) continue;
        taken.push(box);
        ctx.lineJoin = 'round';
        ctx.lineWidth = st.halo;
        ctx.strokeStyle = 'rgba(10, 13, 17, 0.78)';
        ctx.strokeText(name, x, y);
        ctx.fillStyle = st.fill;
        ctx.fillText(name, x, y);
        this.hits.push({ key, x, y, w: w + 4 });
      }
      ctx.restore();
    }
    if (this.territory && territoryShown()) {
      // each fleet's name over its bigger stretches, in its colour, where the stretch has room for it
      const cells: [number, number][] = [];
      for (let j = j0; j < j1; j++) for (let i = i0; i < i1; i++) cells.push([x0 + i, z0 + j]);
      const src = this.territory.source;
      const pixPx = (MUNI_PER / TILES_PER_PIX) * scale;
      ctx.save();
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.lineJoin = 'round';
      ctx.font = '700 12px "IBM Plex Sans", "Segoe UI", system-ui, sans-serif';
      // clear of the town names already written: they were here first
      const taken: [number, number, number, number][] = this.hits.map((h) => [h.x - h.w / 2, h.y - 8, h.x + h.w / 2, h.y + 8]);
      for (const b of this.territory.blobs(cells, 'world')) {
        if (b.pixels < BLOB_MIN) break;
        const name = src.name(b.who).toUpperCase();
        const w = ctx.measureText(name).width + name.length * 1.2;
        // the stretch must be about as wide as its name on screen
        if (Math.sqrt(b.pixels) * pixPx < w * 0.8) continue;
        const x = fx(b.gx), y = fz(b.gz);
        const box: [number, number, number, number] = [x - w / 2 - 4, y - 9, x + w / 2 + 4, y + 9];
        if (taken.some((q) => box[0] < q[2] && box[2] > q[0] && box[1] < q[3] && box[3] > q[1])) continue;
        taken.push(box);
        const c = src.colour(b.who);
        ctx.letterSpacing = '1.2px';
        ctx.lineWidth = 3.5;
        ctx.strokeStyle = haloFor(c);
        ctx.strokeText(name, x, y);
        ctx.fillStyle = hex(c);
        ctx.fillText(name, x, y);
      }
      ctx.restore();
    }
    // the player's lots (docs/property.html): a gold pin each
    for (const p of this.pins?.() ?? []) {
      const x = fx(p.cx * MAP_PIX * TILES_PER_PIX + p.x), y = fz(p.cz * MAP_PIX * TILES_PER_PIX + p.z);
      if (x < -6 || y < -6 || x > cw + 6 || y > ch + 6) continue;
      ctx.beginPath();
      ctx.arc(x, y, 3.5, 0, Math.PI * 2);
      ctx.fillStyle = '#f2b632';
      ctx.fill();
      ctx.lineWidth = 1.5;
      ctx.strokeStyle = 'rgba(60, 40, 0, 0.9)';
      ctx.stroke();
    }
    for (const p of this.stars?.() ?? []) {
      const x = fx(p.cx * MAP_PIX * TILES_PER_PIX + p.x), y = fz(p.cz * MAP_PIX * TILES_PER_PIX + p.z);
      if (x < -6 || y < -6 || x > cw + 6 || y > ch + 6) continue;
      const r = p.hot ? 9 + 2 * Math.sin(performance.now() / 180) : 7;
      ctx.save();
      ctx.font = `${Math.round(r * 2)}px sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.lineWidth = 3;
      ctx.strokeStyle = 'rgba(40, 28, 0, 0.9)';
      ctx.fillStyle = p.crate ? '#ff8a5c' : '#ffd34d';
      const glyph = p.crate ? '◆' : '★';
      ctx.strokeText(glyph, x, y);
      ctx.fillText(glyph, x, y);
      ctx.font = '600 11px sans-serif';
      ctx.textBaseline = 'top';
      ctx.strokeText(p.label, x, y + r + 2);
      ctx.fillStyle = '#fff';
      ctx.fillText(p.label, x, y + r + 2);
      ctx.restore();
    }
    // rival firms met: a flag in their livery on the depot; the name under it only for a town's preferred carrier
    for (const p of this.firms?.() ?? []) {
      const x = fx(p.cx * MAP_PIX * TILES_PER_PIX + p.x), y = fz(p.cz * MAP_PIX * TILES_PER_PIX + p.z);
      if (x < -60 || y < -20 || x > cw + 60 || y > ch + 20) continue;
      firmFlag(ctx, x, y, 1, p.colour, p.accent);
      if (this.showNames && p.pref) {
        ctx.font = '600 10px "IBM Plex Sans", "Segoe UI", system-ui, sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.lineWidth = 3;
        ctx.strokeStyle = 'rgba(10, 13, 17, 0.8)';
        ctx.strokeText(p.name, x, y + 9);
        ctx.fillStyle = hex(p.colour, lum(p.colour) < 0.35 ? 0.55 : 0.15);
        ctx.fillText(p.name, x, y + 9);
      }
    }
    // the events on today (docs/events.html): the icon in a white disc, pulsing while it's on, and what and when under it
    for (const p of this.events?.() ?? []) {
      const x = fx(p.cx * MAP_PIX * TILES_PER_PIX + p.x), y = fz(p.cz * MAP_PIX * TILES_PER_PIX + p.z);
      if (x < -40 || y < -20 || x > cw + 40 || y > ch + 30) continue;
      // the icon always; what and when under it once zoomed in a little (at the whole map they crowded the names)
      eventPin(ctx, x, y, p.icon, this.showNames && this.zoom >= 2 ? p.label : '', p.now);
    }
    if (town?.centre) label(town.key, town.name, fx(town.centre.x), fz(town.centre.z) - 14, true);
    // flying: every airport's code in green, a chevron under it pointing at the strip
    const air = this.airports();
    if (air) {
      ctx.textAlign = 'center';
      ctx.textBaseline = 'alphabetic';
      ctx.font = '700 11px "IBM Plex Mono", "Consolas", monospace';
      for (const a of air) {
        const x = fx(a.gx), y = fz(a.gz);
        if (x < -20 || y < -20 || x > cw + 20 || y > ch + 20) continue;
        airCode(ctx, a.code, x, y);
      }
    }
  }

  private drawMini(atlas: Atlas, gx: number, gz: number): void {
    const cx = Math.floor(gx / (MAP_PIX * TILES_PER_PIX)), cz = Math.floor(gz / (MAP_PIX * TILES_PER_PIX));
    const half = (MINI_CELLS - 1) / 2;
    const d = this.miniImg.data;
    d.fill(0);
    for (let k = 0; k < MINI * MINI; k++) d[k * 4 + 3] = 255;
    for (let j = 0; j < MINI_CELLS; j++) {
      for (let i = 0; i < MINI_CELLS; i++) {
        const cell = atlas.revealed(cx - half + i, cz - half + j);
        if (!cell) continue;
        blit(d, MINI, cell, i * MAP_PIX, j * MAP_PIX);
      }
    }
    const round = this.route();
    if (round) drawRound(d, MINI, MINI, round, (cx - half) * MAP_PIX, (cz - half) * MAP_PIX);
    for (const b of this.stars?.() ?? []) {
      pip(d, MINI, MINI, Math.floor((b.cx * MAP_PIX * TILES_PER_PIX + b.x) / TILES_PER_PIX) - (cx - half) * MAP_PIX, Math.floor((b.cz * MAP_PIX * TILES_PER_PIX + b.z) / TILES_PER_PIX) - (cz - half) * MAP_PIX);
    }
    for (const p of [...this.pips(), ...this.players()]) {
      pip(d, MINI, MINI, Math.floor(p.x / TILES_PER_PIX) - (cx - half) * MAP_PIX, Math.floor(p.z / TILES_PER_PIX) - (cz - half) * MAP_PIX);
    }
    const px = Math.floor(gx / TILES_PER_PIX) - (cx - half) * MAP_PIX;
    const pz = Math.floor(gz / TILES_PER_PIX) - (cz - half) * MAP_PIX;
    marker(d, MINI, MINI, px, pz);
    this.miniCtx.putImageData(this.miniImg, 0, 0);
    // the selected town's border, drawn over the pixels
    const town = this.town();
    const ox = (cx - half) * MAP_PIX, oz = (cz - half) * MAP_PIX;
    if (town?.loops.length) {
      strokeLoops(this.miniCtx, town.loops, (x) => x / TILES_PER_PIX - ox, (z) => z / TILES_PER_PIX - oz, 1.5, 0.55 + 0.45 * town.breath);
    }
    // and the flags of rival depots in view
    for (const p of this.firms?.() ?? []) {
      const x = (p.cx * MAP_PIX * TILES_PER_PIX + p.x) / TILES_PER_PIX - ox, y = (p.cz * MAP_PIX * TILES_PER_PIX + p.z) / TILES_PER_PIX - oz;
      if (x < 0 || y < 0 || x > MINI || y > MINI) continue;
      firmFlag(this.miniCtx, x, y, 0.7, p.colour, p.accent);
    }
    // and today's events, their icons small
    for (const p of this.events?.() ?? []) {
      const x = (p.cx * MAP_PIX * TILES_PER_PIX + p.x) / TILES_PER_PIX - ox, y = (p.cz * MAP_PIX * TILES_PER_PIX + p.z) / TILES_PER_PIX - oz;
      if (x < 0 || y < 0 || x > MINI || y > MINI) continue;
      eventPin(this.miniCtx, x, y, p.icon, '', p.now, 0.65);
    }
  }


  private drawBig(atlas: Atlas, gx: number, gz: number): void {
    const b = atlas.bounds();
    if (!b) return;
    const x0 = b.x0 - PAD, z0 = b.z0 - PAD;
    const cols = b.x1 - b.x0 + 1 + PAD * 2, rows = b.z1 - b.z0 + 1 + PAD * 2;
    const W = cols * MAP_PIX, H = rows * MAP_PIX;
    if (this.big.width !== W || this.big.height !== H) {
      this.big.width = W;
      this.big.height = H;
    }
    const img = this.bigCtx.createImageData(W, H);
    const d = img.data;
    for (let k = 0; k < W * H; k++) d[k * 4 + 3] = 255;
    for (let j = 0; j < rows; j++) {
      for (let i = 0; i < cols; i++) {
        const cell = atlas.revealed(x0 + i, z0 + j);
        if (cell) blit(d, W, cell, i * MAP_PIX, j * MAP_PIX);
      }
    }
    const round = this.route();
    if (round) drawRound(d, W, H, round, x0 * MAP_PIX, z0 * MAP_PIX);
    const road = this.pips();
    const dots = [...road, ...this.players()];
    const px = Math.floor(gx / TILES_PER_PIX) - x0 * MAP_PIX;
    const pz = Math.floor(gz / TILES_PER_PIX) - z0 * MAP_PIX;
    // zoomed in, the dots and the player's marker go over the map at the whole map's size instead (below):
    // in its pixels they would grow with it
    const zoomed = this.zoom > 1;
    if (!zoomed) {
      for (const p of dots) pip(d, W, H, Math.floor(p.x / TILES_PER_PIX) - x0 * MAP_PIX, Math.floor(p.z / TILES_PER_PIX) - z0 * MAP_PIX);
      marker(d, W, H, px, pz);
    }
    this.bigCtx.putImageData(img, 0, 0);


    // the view: the whole map scaled up by a whole number of pixels (so the pixels stay square), and the
    // map zoomed and panned inside it
    const room = Math.min(window.innerWidth - 64, window.innerHeight - 150);
    const fit = Math.max(1, Math.min(8, Math.floor(room / Math.max(W, H))));
    const vw = W * fit, vh = H * fit;
    const scale = fit * this.zoom;
    const hw = vw / scale / 2, hh = vh / scale / 2;
    // the middle of the view, kept so the view never leaves the map
    const cx = Math.max(hw, Math.min(W - hw, this.centre ? this.centre.x - x0 * MAP_PIX : W / 2));
    const cz = Math.max(hh, Math.min(H - hh, this.centre ? this.centre.z - z0 * MAP_PIX : H / 2));
    if (this.centre) this.centre = { x: cx + x0 * MAP_PIX, z: cz + z0 * MAP_PIX };
    const ox = cx - hw, oy = cz - hh;
    this.me = { x: gx / TILES_PER_PIX, z: gz / TILES_PER_PIX };
    this.bigWrap.style.width = `${vw}px`;
    this.bigWrap.style.height = `${vh}px`;
    this.bigWrap.classList.toggle('zoomed', this.zoom > 1);
    this.big.style.width = `${W * scale}px`;
    this.big.style.height = `${H * scale}px`;
    this.big.style.transform = `translate(${-ox * scale}px, ${-oy * scale}px)`;
    this.zoomLabel.textContent = `${Math.round(this.zoom * 10) / 10}×`;
    this.lastBig = { x0, z0, scale, ox, oy, fit, vw, vh };
    this.drawOver(atlas, x0, z0, vw, vh, scale, ox, oy);
    if (zoomed) {
      const ctx = this.overCtx, k = fit;
      const rgb = (c: readonly [number, number, number]) => `rgb(${c[0]}, ${c[1]}, ${c[2]})`;
      // a map pixel's middle on screen
      const at = (mx: number, mz: number): [number, number] => [(mx + 0.5 - ox) * scale, (mz + 0.5 - oy) * scale];
      for (const p of dots) {
        const [x, y] = at(Math.floor(p.x / TILES_PER_PIX) - x0 * MAP_PIX, Math.floor(p.z / TILES_PER_PIX) - z0 * MAP_PIX);
        if (x < -4 * k || y < -4 * k || x > vw + 4 * k || y > vh + 4 * k) continue;
        ctx.fillStyle = rgb(MINE_RING);
        ctx.fillRect(x - 1.5 * k, y - 1.5 * k, 3 * k, 3 * k);
        ctx.fillStyle = rgb(MINE);
        ctx.fillRect(x - 1.5 * k, y - 0.5 * k, 3 * k, k);
        ctx.fillRect(x - 0.5 * k, y - 1.5 * k, k, 3 * k);
      }
      const [x, y] = at(px, pz);
      ctx.fillStyle = rgb(YOU_RING);
      ctx.fillRect(x - 2.5 * k, y - 2.5 * k, 5 * k, 5 * k);
      ctx.fillStyle = rgb(YOU);
      ctx.fillRect(x - 1.5 * k, y - 1.5 * k, 3 * k, 3 * k);
    }
    const tiles = Math.round(MAP_PIX * TILES_PER_PIX);
    const explored = `${atlas.cells} island${atlas.cells === 1 ? '' : 's'} explored · ${tiles} tiles to a square · ${TILES_PER_PIX} tiles to a pixel`;
    // while the fleet is coming, the caption says who is where rather than how big the map is
    const terr = territoryShown() ? (this.hover || this.legend?.() || '') : '';
    this.terrLegend?.update(territoryShown());
    this.caption.textContent = terr || (road.length
      ? `On the road to you · ${road.map((p) => `${p.name} ${p.eta}`).join(' · ')}`
      : explored);
  }
}

/** An airport's code over its strip: green letters on a dark halo, and a chevron pointing down at (x, y). */
function airCode(ctx: CanvasRenderingContext2D, code: string, x: number, y: number): void {
  ctx.save();
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  ctx.strokeStyle = 'rgba(6, 20, 10, 0.85)';
  ctx.lineWidth = 3;
  ctx.strokeText(code, x, y - 9);
  ctx.fillStyle = '#4ee06f';
  ctx.fillText(code, x, y - 9);
  const chevron = () => { ctx.beginPath(); ctx.moveTo(x - 4.5, y - 6); ctx.lineTo(x, y - 1.5); ctx.lineTo(x + 4.5, y - 6); };
  chevron();
  ctx.lineWidth = 4;
  ctx.stroke();
  chevron();
  ctx.strokeStyle = '#4ee06f';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.restore();
}

/** An event's pin: its icon in a white disc ringed in violet (pulsing while it is on), its line under it. */
function eventPin(ctx: CanvasRenderingContext2D, x: number, y: number, icon: string, label: string, on: boolean, s = 1): void {
  ctx.save();
  const r = (on ? 9 + 1.5 * Math.sin(performance.now() / 160) : 8) * s;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.95)';
  ctx.fill();
  ctx.lineWidth = 2 * s;
  ctx.strokeStyle = on ? '#c23cff' : '#6b2d8e';
  ctx.stroke();
  ctx.font = `${Math.round(11 * s)}px sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(icon, x, y + 0.5);
  if (label) {
    ctx.font = '600 10px "IBM Plex Sans", "Segoe UI", system-ui, sans-serif';
    ctx.textBaseline = 'top';
    ctx.lineWidth = 3;
    ctx.strokeStyle = 'rgba(30, 8, 40, 0.85)';
    ctx.strokeText(label, x, y + r + 2);
    ctx.fillStyle = '#f6e9ff';
    ctx.fillText(label, x, y + r + 2);
  }
  ctx.restore();
}

/** A colour as CSS, lifted toward white by `lift` (0 as it is) so a dark livery still reads on the map. */
function hex(c: number, lift = 0): string {
  const ch = (s: number) => Math.round(((c >> s) & 255) + (255 - ((c >> s) & 255)) * lift);
  return `rgb(${ch(16)}, ${ch(8)}, ${ch(0)})`;
}
const lum = (c: number): number => (0.2126 * ((c >> 16) & 255) + 0.7152 * ((c >> 8) & 255) + 0.0722 * (c & 255)) / 255;

/** A rival's depot: a pole standing on (x, y) with a pennant in the body colour, edged in the accent. */
function firmFlag(ctx: CanvasRenderingContext2D, x: number, y: number, s: number, body: number, accent: number): void {
  ctx.save();
  ctx.lineJoin = 'round';
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x, y - 12 * s);
  ctx.lineWidth = 3 * s;
  ctx.strokeStyle = 'rgba(10, 13, 17, 0.85)';
  ctx.stroke();
  ctx.lineWidth = 1.4 * s;
  ctx.strokeStyle = '#f4f7f1';
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x + 0.5 * s, y - 12 * s);
  ctx.lineTo(x + 9 * s, y - 9 * s);
  ctx.lineTo(x + 0.5 * s, y - 6 * s);
  ctx.closePath();
  ctx.fillStyle = hex(body);
  ctx.fill();
  ctx.lineWidth = 1.2 * s;
  ctx.strokeStyle = hex(accent);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(x, y, 1.8 * s, 0, Math.PI * 2);
  ctx.fillStyle = hex(body);
  ctx.fill();
  ctx.restore();
}

/** The selected town's line in the map's yellow, at the given width and strength, with a faint fill. */
function strokeLoops(ctx: CanvasRenderingContext2D, loops: Float32Array[], fx: (x: number) => number, fz: (z: number) => number, width: number, alpha: number): void {
  ctx.save();
  ctx.lineWidth = width;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = `rgba(255, 200, 61, ${alpha.toFixed(3)})`;
  ctx.fillStyle = `rgba(255, 200, 61, ${(alpha * 0.18).toFixed(3)})`;
  ctx.beginPath();
  for (const l of loops) {
    for (let k = 0; k < l.length; k += 2) {
      const x = fx(l[k]), z = fz(l[k + 1]);
      if (k === 0) ctx.moveTo(x, z); else ctx.lineTo(x, z);
    }
    ctx.closePath();
  }
  ctx.fill('evenodd');
  ctx.stroke();
  ctx.restore();
}

/** A smaller, greener marker: one of yours, on its way. */
function pip(d: Uint8ClampedArray, stride: number, rows: number, px: number, pz: number): void {
  const put = (x: number, z: number, c: readonly [number, number, number]) => {
    if (x < 0 || z < 0 || x >= stride || z >= rows) return;
    const o = (z * stride + x) * 4;
    d[o] = c[0]; d[o + 1] = c[1]; d[o + 2] = c[2];
  };
  for (let z = -1; z <= 1; z++) for (let x = -1; x <= 1; x++) {
    put(px + x, pz + z, Math.abs(x) + Math.abs(z) === 2 ? MINE_RING : MINE);
  }
}


/** A manifest on the map: a line from the vehicle through each call in turn, and a dot at every call. */
function drawRound(d: Uint8ClampedArray, stride: number, rows: number, r: Round, ox: number, oz: number): void {
  const put = (x: number, z: number, c: readonly [number, number, number]) => {
    if (x < 0 || z < 0 || x >= stride || z >= rows) return;
    const o = (z * stride + x) * 4;
    d[o] = c[0]; d[o + 1] = c[1]; d[o + 2] = c[2];
  };
  const at = (p: { x: number; z: number }) => [Math.floor(p.x / TILES_PER_PIX) - ox, Math.floor(p.z / TILES_PER_PIX) - oz];
  let [x, z] = at(r);
  for (const s of r.stops) {
    const [tx, tz] = at(s);
    const n = Math.max(Math.abs(tx - x), Math.abs(tz - z));
    for (let k = 0; k <= n; k++) put(Math.round(x + ((tx - x) * k) / Math.max(1, n)), Math.round(z + ((tz - z) * k) / Math.max(1, n)), ROUTE);
    x = tx; z = tz;
  }
  for (const s of r.stops) {
    const [sx, sz] = at(s);
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) if (Math.abs(dx) + Math.abs(dz) < 2) put(sx + dx, sz + dz, s.drop ? DROP : PICKUP);
  }
}

/** Copy one island's revealed pixels into the image, leaving fog as it is. */
function blit(d: Uint8ClampedArray, stride: number, cell: Uint8Array, ox: number, oz: number): void {
  for (let z = 0; z < MAP_PIX; z++) {
    for (let x = 0; x < MAP_PIX; x++) {
      const v = cell[z * MAP_PIX + x];
      if (!v) continue;
      const [r, g, b] = rgb(v);
      const o = ((oz + z) * stride + ox + x) * 4;
      d[o] = r; d[o + 1] = g; d[o + 2] = b;
    }
  }
}

/** A red dot for the player, inside a white ring so it shows up over anything. */
function marker(d: Uint8ClampedArray, stride: number, rows: number, px: number, pz: number): void {
  const put = (x: number, z: number, c: readonly [number, number, number]) => {
    if (x < 0 || z < 0 || x >= stride || z >= rows) return;
    const o = (z * stride + x) * 4;
    d[o] = c[0]; d[o + 1] = c[1]; d[o + 2] = c[2];
  };
  for (let z = -2; z <= 2; z++) for (let x = -2; x <= 2; x++) {
    const edge = Math.max(Math.abs(x), Math.abs(z));
    if (edge === 2) put(px + x, pz + z, YOU_RING);
    else if (edge <= 1) put(px + x, pz + z, YOU);
  }
}

/**
 * A saved game's explored map as a thumbnail, without an Atlas: decode the save's `explored` record
 * (run-length pairs of palette index and count, base64, one 32 × 32 stamp per cell) and draw
 * `cellsAcross` cells square into the canvas at the largest whole-number scale that fits, centred in
 * it, black where nobody has been. The view is centred on `centre` (a cell) or on the middle of the
 * explored cells.
 */
export function drawExplored(canvas: HTMLCanvasElement, explored: Record<string, string>, cellsAcross = 4, centre?: [number, number]): void {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const n = Math.max(1, Math.floor(cellsAcross));
  const S = n * MAP_PIX;

  const cells: { cx: number; cz: number; pix: Uint8Array }[] = [];
  let x0 = Infinity, x1 = -Infinity, z0 = Infinity, z1 = -Infinity;
  for (const [k, enc] of Object.entries(explored ?? {})) {
    const [cx, cz] = k.split(',').map(Number);
    if (!Number.isInteger(cx) || !Number.isInteger(cz)) continue;
    let s: string;
    try { s = atob(enc); } catch { continue; }
    const pix = new Uint8Array(MAP_PIX * MAP_PIX);
    let at = 0;
    for (let i = 0; i + 1 < s.length && at < pix.length; i += 2) {
      const v = s.charCodeAt(i), run = s.charCodeAt(i + 1);
      for (let r = 0; r < run && at < pix.length; r++) pix[at++] = v;
    }
    cells.push({ cx, cz, pix });
    x0 = Math.min(x0, cx); x1 = Math.max(x1, cx); z0 = Math.min(z0, cz); z1 = Math.max(z1, cz);
  }

  // the view's top-left in map pixels, so its middle sits on the chosen cell's middle
  const mx = centre ? (centre[0] + 0.5) * MAP_PIX : cells.length ? ((x0 + x1 + 1) / 2) * MAP_PIX : MAP_PIX / 2;
  const mz = centre ? (centre[1] + 0.5) * MAP_PIX : cells.length ? ((z0 + z1 + 1) / 2) * MAP_PIX : MAP_PIX / 2;
  const ox = Math.round(mx - S / 2), oz = Math.round(mz - S / 2);

  const img = new ImageData(S, S);
  const d = img.data;
  for (let k = 0; k < S * S; k++) d[k * 4 + 3] = 255;
  for (const { cx, cz, pix } of cells) {
    const bx = cx * MAP_PIX - ox, bz = cz * MAP_PIX - oz;
    if (bx >= S || bz >= S || bx + MAP_PIX <= 0 || bz + MAP_PIX <= 0) continue;
    for (let z = 0; z < MAP_PIX; z++) {
      const y = bz + z;
      if (y < 0 || y >= S) continue;
      for (let x = 0; x < MAP_PIX; x++) {
        const X = bx + x;
        const v = pix[z * MAP_PIX + x];
        if (!v || X < 0 || X >= S) continue;
        const [r, g, b] = rgb(v);
        const o = (y * S + X) * 4;
        d[o] = r; d[o + 1] = g; d[o + 2] = b;
      }
    }
  }

  const W = canvas.width, H = canvas.height;
  const scale = Math.max(1, Math.floor(Math.min(W, H) / S));
  const src = document.createElement('canvas');
  src.width = S; src.height = S;
  src.getContext('2d')!.putImageData(img, 0, 0);
  ctx.save();
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, W, H);
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(src, Math.floor((W - S * scale) / 2), Math.floor((H - S * scale) / 2), S * scale, S * scale);
  ctx.restore();
}
