/**
 * What the title reel can film, found rather than staged: every finder looks at a resident cell for
 * something that is really there — a village, a harbour, a landform, a ski field in winter, a
 * wonder — scores what it finds, and says how to frame it. The programme then orders the best of
 * them so that no two shots in a row are of one kind and a loop covers the world's range.
 */
import { N, STEP, type World, type TownKind } from '../world/tiles';
import { TOWN_INFO } from '../world/towns';
import { LANDFORM_LABEL } from '../world/landforms';
import { REGIONS } from '../world/regions';
import { cellKind, hasMega, regionAnchor, regionWonder } from '../world/macro';

export type Move = 'orbit' | 'dolly' | 'rise' | 'hold' | 'follow';
export type Category =
  | 'village' | 'suburb' | 'downtown' | 'megalopolis' | 'harbour' | 'rock' | 'county' | 'causeway'
  | 'landform' | 'works' | 'beach' | 'country' | 'hero' | 'biome' | 'wonder';

export interface Shot {
  cat: Category;
  caption: string;
  /** The cell the subject is in: it and its neighbours must be resident before the cut. */
  cx: number; cz: number;
  /** The subject, in global tiles, and the world height of its ground. */
  x: number; z: number; y: number;
  r: number;
  move: Move;
  /** Start and end of the move: yaw (radians), pitch (radians), distance. */
  yaw0: number; yaw1: number; pitch0: number; pitch1: number; dist0: number; dist1: number;
  /** A dolly glides the focus from -glide to +glide along its yaw's side vector. */
  glide: number;
  /** The hour the shot is set at, and the season (0 spring .. 3 winter), or null to leave it. */
  hour: number; season: number | null;
  /** Seconds on screen, and the half-height of the tilt-shift's sharp band. */
  len: number; band: number;
  /** A follow shot rides a CPU vehicle of this kind, spawned or found near the subject. */
  hero?: 'land' | 'water' | 'air' | 'rail';
  score: number;
}

const deg = (d: number) => (d * Math.PI) / 180;
const pick = <T>(list: T[], r: number): T => list[Math.floor(r * list.length) % list.length];

function base(w: World, cat: Category, caption: string, lx: number, lz: number, r: number, move: Move, rnd: () => number): Shot {
  const tx = Math.max(0, Math.min(N - 1, Math.floor(lx))), tz = Math.max(0, Math.min(N - 1, Math.floor(lz)));
  const b = (tz * N + tx) * 4, c = w.corners;
  const y = Math.max(1, (c[b] + c[b + 1] + c[b + 2] + c[b + 3]) / 4) * STEP;
  const yaw = rnd() * Math.PI * 2;
  const dist = Math.max(30, Math.min(150, r * 1.6));
  return {
    cat, caption, cx: w.cx, cz: w.cz, x: w.ox + lx, z: w.oz + lz, y, r, move,
    yaw0: yaw, yaw1: yaw + (rnd() < 0.5 ? 1 : -1) * deg(40), pitch0: deg(48), pitch1: deg(52), dist0: dist, dist1: dist * 0.92,
    glide: 0, hour: 12, season: null, len: 9, band: 0.12, score: 0,
  };
}

const TOWN_CAT: Record<TownKind, Category> = { rural: 'village', suburb: 'suburb', city: 'downtown', metro: 'downtown', mega: 'megalopolis' };

/** Every shot a cell offers, each scored. `rnd` makes the framing vary loop to loop. */
export function findShots(w: World, rnd: () => number): Shot[] {
  const out: Shot[] = [];
  const place = w.continent ? `${w.name}` : w.name;
  // ---- towns: a dolly down the village street, an orbit of a suburb, a rise over a city ----
  for (const t of w.towns) {
    const cat = TOWN_CAT[t.kind];
    const cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2;
    const s = base(w, cat, `${t.name} · ${TOWN_INFO[t.kind].label}${w.continent ? ` · ${place}` : ''}`, cx, cz, t.size / 2, 'orbit', rnd);
    const built = t.buildings.filter((b) => b.solid && !b.gone).length;
    s.score = Math.min(1, built / 80) + (t.region ? 0.4 : 0);
    if (cat === 'village') {
      Object.assign(s, { move: 'dolly', glide: t.size * 0.3, dist0: 38, dist1: 34, pitch0: deg(40), pitch1: deg(42), hour: 7.5 + rnd(), season: rnd() < 0.5 ? 0 : 2, band: 0.1 });
    } else if (cat === 'suburb') {
      Object.assign(s, { dist0: 60, dist1: 52, hour: 15 + rnd() * 2 });
    } else if (cat === 'downtown') {
      Object.assign(s, { move: 'rise', dist0: 34, dist1: 130, pitch0: deg(34), pitch1: deg(56), hour: 19.4 + rnd() * 0.6, len: 11, band: 0.14 });
      s.score += 0.3;
    } else {
      Object.assign(s, { move: 'rise', dist0: 50, dist1: 165, pitch0: deg(36), pitch1: deg(58), hour: 21 + rnd(), len: 11, band: 0.16 });
      s.score += 1.2;
    }
    out.push(s);
  }
  // ---- harbours: hold from the breakwater, then drift round ----
  for (const p of w.ports) {
    if (!p.major) continue;
    const s = base(w, 'harbour', `${p.name} · Major port`, p.x, p.z, 16, 'orbit', rnd);
    Object.assign(s, { dist0: 60, dist1: 56, yaw1: s.yaw0 + deg(22), hour: 11.5 + rnd(), score: 0.8 });
    out.push(s);
  }
  // ---- landforms: orbit at 1.4 × the radius, lower for towers and arches ----
  for (const l of w.landmarks) {
    const label = LANDFORM_LABEL[l.kind];
    if (!label || l.kind === 'skerries') continue;
    const r = Math.max(14, Math.min(90, l.r));
    const s = base(w, 'landform', `${l.name} · ${label}`, l.x, l.z, r, 'orbit', rnd);
    const low = l.kind === 'karstTowers' || l.kind === 'seaArch' || l.kind === 'naturalBridge' || l.kind === 'hoodoos' || l.kind === 'cascade' || l.kind === 'waterfall';
    Object.assign(s, { dist0: Math.min(150, r * 1.4 + 20), dist1: Math.min(140, r * 1.3 + 18), pitch0: deg(low ? 36 : 56), pitch1: deg(low ? 40 : 60), hour: 16.5 + rnd() * 1.5, season: rnd() < 0.3 ? 1 : null });
    const rare = ['volcano', 'caldera', 'glacier', 'karstTowers', 'fjordCoast', 'atoll', 'saltFlat', 'mesaCountry', 'riftValley', 'waterfall'].includes(l.kind);
    s.score = 0.4 + (rare ? 0.8 : 0) + Math.min(0.4, l.r / 150);
    out.push(s);
  }
  // ---- works: the airfield from down the runway, the ski field in winter, the quarry ----
  for (const g of w.works) {
    if (g.kind === 'wonder') {
      const s = base(w, 'wonder', `${g.name} · ${w.region ? `Wonder of ${REGIONS[w.region].title}` : 'Wonder'}`, g.x, g.z, 12, 'orbit', rnd);
      Object.assign(s, { dist0: 55, dist1: 44, pitch0: deg(40), pitch1: deg(46), hour: rnd() < 0.5 ? 17.8 : 10, score: 2 });
      out.push(s);
      continue;
    }
    const label = g.kind === 'ski' ? 'Ski field' : g.kind === 'airfield' ? (g.major ? 'International airport' : 'Airfield') : 'Quarry';
    const s = base(w, 'works', `${g.name} · ${label}`, g.x, g.z, g.kind === 'airfield' ? 24 : 16, 'orbit', rnd);
    if (g.kind === 'ski') Object.assign(s, { season: 3, hour: 10 + rnd() * 2, dist0: 70, dist1: 60, score: 0.9 });
    else if (g.kind === 'airfield') Object.assign(s, { move: 'hold', yaw0: g.facing % 2 ? 0 : Math.PI / 2, yaw1: (g.facing % 2 ? 0 : Math.PI / 2) + deg(8), dist0: 80, dist1: 76, hour: 9 + rnd() * 6, len: 8, score: 0.6 + (g.major ? 0.3 : 0) });
    else Object.assign(s, { hour: 13 + rnd() * 3, score: 0.35 });
    out.push(s);
  }
  // ---- beaches: a low dolly along the sand at noon in summer ----
  for (const b of w.spots) {
    if (b.kind !== 'beach') continue;
    const s = base(w, 'beach', `${b.name} · ${w.name}`, b.x, b.z, b.r, 'dolly', rnd);
    Object.assign(s, { glide: b.r * 0.5, dist0: 34, dist1: 30, pitch0: deg(36), pitch1: deg(38), hour: 12.5 + rnd(), season: 1, band: 0.09, score: 0.5 + (w.region === 'shallows' ? 0.6 : 0) });
    out.push(s);
  }
  // ---- country: between the turbines at sunset ----
  const turbines = w.countryside.filter((b) => b.kind === 'windTurbine' || b.kind === 'orchard' || b.kind === 'windmill');
  if (turbines.length >= 3) {
    const t = turbines[Math.floor(rnd() * turbines.length)];
    const s = base(w, 'country', `${w.name} · the countryside`, t.x + 0.5, t.z + 0.5, 14, 'dolly', rnd);
    Object.assign(s, { glide: 12, dist0: 44, dist1: 40, hour: 18.2 + rnd() * 0.5, season: 0, score: 0.35 });
    out.push(s);
  }
  // ---- a rock with nothing on it but a lighthouse ----
  if (w.kind === 'islet' || w.kind === 'atoll') {
    const light = w.pois.find((p) => p.type === 'lighthouse');
    const at = light ?? { x: N / 2, z: N / 2 };
    const s = base(w, 'rock', `${w.name} · ${w.kind === 'atoll' ? 'Atoll' : 'Islet'}`, at.x + 0.5, at.z + 0.5, 40, 'orbit', rnd);
    Object.assign(s, { dist0: 85, dist1: 78, hour: 18.6 + rnd() * 0.4, score: 0.7 });
    out.push(s);
  }
  // ---- a causeway between two islands ----
  for (const st of w.straits) {
    const lx = st.dir === 0 ? N - 8 : st.dir === 2 ? 8 : st.at, lz = st.dir === 1 ? N - 8 : st.dir === 3 ? 8 : st.at;
    const s = base(w, 'causeway', `${w.name} · Causeway`, lx, lz, 16, 'hold', rnd);
    Object.assign(s, { dist0: 46, dist1: 42, pitch0: deg(30), pitch1: deg(32), hour: 8 + rnd() * 3, len: 8, band: 0.09, score: 0.4 });
    out.push(s);
  }
  // ---- a county: land running off every edge ----
  if (w.kind === 'continent' && w.towns.length) {
    const t = w.towns[0];
    const s = base(w, 'county', `${w.name}${w.continent ? ` · ${w.continent}` : ''}`, t.x0 + t.size / 2 + 30, t.z0 + t.size / 2, 60, 'dolly', rnd);
    Object.assign(s, { glide: 30, dist0: 120, dist1: 110, pitch0: deg(50), pitch1: deg(52), hour: 8 + rnd(), season: 2, score: 0.5 });
    out.push(s);
  }
  // ---- a biome from the air: the whole look of it ----
  if (w.region) {
    const spec = REGIONS[w.region];
    const island = w.kind !== 'continent';
    const s = base(w, 'biome', island ? `the ${w.name} · ${spec.label[0].toUpperCase()}${spec.label.slice(1)} island` : `${w.name} · ${spec.title[0].toUpperCase()}${spec.title.slice(1)}`, N / 2, N / 2, 100, 'rise', rnd);
    Object.assign(s, { dist0: 90, dist1: 160, pitch0: deg(46), pitch1: deg(58), hour: pick([9, 11, 16.5], rnd()), len: 10, band: 0.18, score: 1.4 });
    // put the rise over its towns if it has any, where the look is densest
    if (w.towns.length) { s.x = w.ox + w.towns[0].x0 + w.towns[0].size / 2; s.z = w.oz + w.towns[0].z0 + w.towns[0].size / 2; }
    out.push(s);
  }
  // ---- heroes: follow a vehicle on the island's own traffic ----
  if (w.towns.length) {
    const t = w.towns[Math.floor(rnd() * w.towns.length)];
    for (const kind of ['land', 'water', 'air'] as const) {
      if (kind === 'water' && !w.ports.length) continue;
      const s = base(w, 'hero', '', t.x0 + t.size / 2, t.z0 + t.size / 2, 20, 'follow', rnd);
      Object.assign(s, { hero: kind, dist0: kind === 'air' ? 55 : 32, dist1: kind === 'air' ? 50 : 30, pitch0: deg(42), pitch1: deg(44), hour: 8 + rnd() * 9, len: 11, band: 0.08, score: 0.6 });
      out.push(s);
    }
  }
  // ---- a train: follow whatever is running on this cell's line, or the next one along it ----
  if (w.rails.some((p) => p.kind === 'main')) {
    const p = w.rails.find((q) => q.kind === 'main')!;
    const mid = Math.floor(p.s.length / 2);
    const s = base(w, 'hero', '', p.xz[mid * 2], p.xz[mid * 2 + 1], 24, 'follow', rnd);
    // a station on the line is worth more: trains call there
    Object.assign(s, { hero: 'rail', dist0: 58, dist1: 52, pitch0: deg(38), pitch1: deg(42), hour: 7 + rnd() * 10, len: 13, band: 0.09, score: w.stations.length ? 0.85 : 0.65 });
    out.push(s);
  }
  return out;
}

/** A cell further out the reel may travel to, and what it goes there for. */
export interface Stop { cx: number; cz: number; want: Category[] }

/**
 * Stops the macro layer promises within reach, from hashes alone: the nearest megalopolis, a county,
 * a lighthouse rock, and the nearest biome (its wonder if it has one).
 */
export function findStops(seedHash: number, cx: number, cz: number, reach = 9): Stop[] {
  const out: Stop[] = [];
  const found = new Set<string>();
  const ring = (test: (x: number, z: number) => boolean): [number, number] | null => {
    for (let r = 2; r <= reach; r++) {
      for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
        if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
        const x = cx + dx, z = cz + dz;
        if (!found.has(`${x},${z}`) && test(x, z)) return [x, z];
      }
    }
    return null;
  };
  const add = (at: [number, number] | null, want: Category[]) => {
    if (!at) return;
    found.add(`${at[0]},${at[1]}`);
    out.push({ cx: at[0], cz: at[1], want });
  };
  add(ring((x, z) => regionAnchor(seedHash, x, z) !== null && regionWonder(seedHash, x, z)), ['wonder', 'biome', 'hero']);
  add(ring((x, z) => hasMega(seedHash, x, z)), ['megalopolis', 'harbour', 'hero']);
  add(ring((x, z) => cellKind(seedHash, x, z) === 'continent'), ['county', 'village', 'landform']);
  add(ring((x, z) => cellKind(seedHash, x, z) === 'islet' || cellKind(seedHash, x, z) === 'atoll'), ['rock', 'beach']);
  return out;
}
