/**
 * The depot board (docs/hqwindow.html, "Fleet: the depot board"): the HQ window's Fleet tab. Three zones on
 * one screen so that moving things between them is a drag: what is on the map (a card per fleet slot, each
 * with its driver's seat docked to its right edge, and the vehicle you drive first), the garage (off the
 * map), and the bench (drivers not in a vehicle, and Hire…). Every drop calls the same function as the
 * pane's button for it and gives the same refusal; `dropWhy` is that rule, and `npm run hqwin` holds the
 * two to each other.
 */
import { esc, money } from './cargoHud';
import { defOf, type Fleet, type Unit } from './fleet';
import { licenceFor, mayDrive, moodWord, rankOf, type Driver } from './drivers';
import { portraitImg } from './crewPortrait';
import { canLoad } from './vehicles';
import { gradeName, gradePips } from './hqGrade';

/** What is being dragged. */
export type DragSrc = { k: 'driver'; id: number } | { k: 'unit'; uid: number };
/** Where it is dropped: `unit` is another vehicle's card, to swap places with it. */
export type DropTgt = { k: 'seat'; uid: number } | { k: 'bench' } | { k: 'free' } | { k: 'garage' } | { k: 'you' } | { k: 'unit'; uid: number };
/** One bubble of a tour of the Fleet tab: what it points at (a selector inside the HQ window), its heading and words (HTML). */
export interface TourStep { sel: string; title: string; html: string }

/** What the board asks of the game: the moves the pane's buttons make too. */
interface BoardMoves {
  deploy(u: Unit): string | null;
  swapIn(u: Unit): string | null;
  /** Why a garaged unit couldn't come out here (a boat needs water), checked before a drop lights up. */
  deployCheck?(u: Unit): string | null;
  /** The same, with one slot about to be freed by the vehicle it swaps with. */
  swapCheck?(u: Unit): string | null;
}

/** A vehicle swap: the one on the map that goes into the garage, and the garaged one that comes out for it. */
function swapPair(fleet: Fleet, src: Unit, uid: number): { out: Unit; inn: Unit } | string {
  const t = fleet.unit(uid);
  if (!t) return 'Gone';
  if (t === src) return 'That is the one you are holding';
  const inn = src.where === 'garaged' ? src : t.where === 'garaged' ? t : null;
  const out = inn === src ? t : src;
  if (!inn) return 'To swap, drag a vehicle from the garage onto one on the map (or the other way)';
  if (out.where === 'garaged') return 'Both are in the garage';
  return { out, inn };
}

/**
 * Why this drag can't be dropped here, or null when it can: the same refusals the pane's buttons give
 * (Put in, To the bench, Bring it out, To the garage, Drive it from here). A driver dropped on a seat that
 * has someone in it swaps with them, and a garaged vehicle dropped on one out on the map swaps places with it.
 */
export function dropWhy(fleet: Fleet, moves: BoardMoves, src: DragSrc, tgt: DropTgt): string | null {
  if (src.k === 'driver') {
    const d = fleet.driver(src.id);
    if (!d) return 'Gone';
    if (tgt.k === 'bench') return d.unit ? null : 'Already on the bench';
    if (tgt.k !== 'seat' && tgt.k !== 'unit') return 'Drivers go in a seat or on the bench';
    const u = fleet.unit(tgt.uid);
    if (!u) return 'Gone';
    if (u.driver === d.id) return 'Already in it';
    return fleet.cantPut(d, u, true);
  }
  const u = fleet.unit(src.uid);
  if (!u) return 'Gone';
  if (tgt.k === 'free') {
    if (u.where !== 'garaged') return 'Only a vehicle in the garage can be brought out';
    // the same refusal as Bring it out (main.ts deployWhy); without the game's own check, the slot count alone
    return moves.deployCheck ? moves.deployCheck(u) : fleet.free < 1 ? 'Every slot is taken' : null;
  }
  if (tgt.k === 'garage') return fleet.cantStore(u);
  if (tgt.k === 'you') return u.where === 'garaged' ? null : fleet.lockedWhy(u) ?? (u.where === 'towing' ? `${u.name} is on a tow truck` : null);
  if (tgt.k === 'unit') {
    const p = swapPair(fleet, u, tgt.uid);
    if (typeof p === 'string') return p;
    return fleet.cantStore(p.out) ?? (moves.swapCheck ? moves.swapCheck(p.inn) : null);
  }
  return 'Vehicles go in a slot, the garage, or onto yours';
}

/** Make the move (after dropWhy said yes): a refusal from the game itself, or null. */
function dropDo(fleet: Fleet, moves: BoardMoves, src: DragSrc, tgt: DropTgt): string | null {
  const why = dropWhy(fleet, moves, src, tgt);
  if (why) return why;
  if (src.k === 'driver') {
    const d = fleet.driver(src.id)!;
    if (tgt.k === 'bench') { const u = fleet.unit(d.unit); if (u) fleet.dismiss(u); return null; }
    const u = fleet.unit((tgt as { uid: number }).uid)!;
    const was = fleet.driverOf(u);
    if (!was) return fleet.put(d, u);
    // a swap: whoever is in it steps out, and takes the seat this driver left when they can drive that one
    const from = d.unit ? fleet.unit(d.unit) : null;
    fleet.dismiss(u);
    const no = fleet.put(d, u);
    if (no) { fleet.put(was, u); return no; }
    if (from && from !== u && !fleet.cantPut(was, from)) fleet.put(was, from);
    return null;
  }
  const u = fleet.unit(src.uid)!;
  if (tgt.k === 'free') return moves.deploy(u);
  if (tgt.k === 'garage') return fleet.store(u);
  if (tgt.k === 'unit') {
    const { out, inn } = swapPair(fleet, u, tgt.uid) as { out: Unit; inn: Unit };
    // the driver comes along into the one coming out, when they can drive it
    const crew = fleet.driverOf(out);
    const no = fleet.store(out) ?? moves.deploy(inn);
    if (no) return no;
    if (crew && !fleet.cantPut(crew, inn)) fleet.put(crew, inn);
    return null;
  }
  return moves.swapIn(u);
}

export interface BoardHost extends BoardMoves {
  /** A picture of the unit as it is (tuned, painted). */
  thumb(u: Unit): string | undefined;
  /** The dock's corner icon for it (🪝 🔗 ⏸). */
  icon(uid: number): string;
  /** The fleet's colours, for the seat discs and the cards. */
  colours(): { primary: string; pastel: string };
  /** The next grade's slots, for the zone caption. */
  next(): string;
  /** Something was picked. */
  pick(p: DragSrc | { k: 'hire' }): void;
  /** What is picked, to mark it. */
  picked(): string;
  say(text: string): void;
  changed(): void;
  /** Double-click on a map card: watch it. */
  watch(uid: number): void;
  /** The HQ window's Home tab, where the addresses to buy for an HQ are listed. */
  home?(): void;
}

const keyOfSrc = (p: DragSrc | { k: 'hire' }): string => (p.k === 'hire' ? 'hire' : p.k === 'driver' ? `d${p.id}` : `u${p.uid}`);
export const pickKey = keyOfSrc;

type Target = { el: HTMLElement; tgt: DropTgt };
/** A drag in progress: `ghost` is null until it has moved far enough to be one (else it was a click). */
interface Drag {
  src: DragSrc; from: HTMLElement; x: number; y: number;
  ghost: HTMLElement | null; hint: HTMLElement | null;
  /** Where the pointer holds the ghost, from its top middle. */
  dx: number; dy: number;
  px: number; py: number; lastX: number; vx: number; tilt: number;
  over: Target | null; said: string; raf: number; scroller: HTMLElement | null;
}

export class FleetBoard {
  readonly el = document.createElement('div');
  private html = '';
  private drag: Drag | null = null;
  /** A vehicle just bought: its card glows for a few seconds. */
  private fresh = { uid: 0, until: 0 };
  /** The first vehicle ever bought: two tips on what to do with it, until dismissed or it leaves the garage. */
  private coachUid = 0;

  constructor(private fleet: Fleet, private host: BoardHost) {
    this.el.className = 'hq-board';
    this.el.addEventListener('pointerdown', (e) => this.down(e));
    this.el.addEventListener('dblclick', (e) => {
      const c = (e.target as HTMLElement).closest<HTMLElement>('[data-uid]');
      if (c && c.closest('[data-zone="map"]')) this.host.watch(Number(c.dataset.uid));
    });
    window.addEventListener('pointermove', (e) => this.move(e));
    window.addEventListener('pointerup', (e) => this.up(e));
  }

  get dragging(): boolean { return !!this.drag?.ghost; }

  /** A card to glow for a few seconds (a vehicle just bought). */
  flash(uid: number): void {
    this.fresh = { uid, until: performance.now() + 6000 };
    this.render(true);
    requestAnimationFrame(() => this.el.querySelector(`[data-uid="${uid}"]`)?.scrollIntoView({ block: 'nearest' }));
  }

  /** The tips are brief: closing the window lets them go (a tour too). */
  endCoach(): void { this.coachUid = 0; this.endTour(); }

  // ---- a tour: one bubble at a time, each pinned to what it explains, Next to go on (docs/helpinghand.html) ----

  private tourSteps: TourStep[] = [];
  private tourAt = -1;
  private tourEl: HTMLElement | null = null;
  /** The tour is over (Done, or the window closed under it). */
  onTourEnd: (() => void) | null = null;

  get touring(): boolean { return this.tourAt >= 0; }

  /** Walk the Fleet tab one bubble at a time; the first-purchase tips stand aside meanwhile. */
  tour(steps: TourStep[]): void {
    this.coachUid = 0;
    this.tourSteps = steps;
    this.tourAt = steps.length ? 0 : -1;
    this.render(true);
  }

  private endTour(): void {
    if (this.tourAt < 0) return;
    this.tourAt = -1;
    this.tourEl?.remove();
    this.tourEl = null;
    for (const el of Array.from(document.querySelectorAll('.tour-glow'))) el.classList.remove('tour-glow');
    this.onTourEnd?.();
  }

  /** The bubble for the step up now, beside its target (right of it if there is room, else below, else left). */
  private placeTour(): void {
    const s = this.tourSteps[this.tourAt];
    if (!s) return;
    const root = this.el.closest('#hq') ?? document;
    const tgt = root.querySelector<HTMLElement>(s.sel);
    if (!this.tourEl) {
      this.tourEl = document.createElement('div');
      this.tourEl.className = 'hq-tour';
      this.tourEl.addEventListener('pointerdown', (e) => {
        const b = (e.target as HTMLElement).closest<HTMLElement>('[data-tour]');
        e.stopPropagation();
        if (!b) return;
        if (b.dataset.tour === 'next' && this.tourAt < this.tourSteps.length - 1) { this.tourAt++; this.placeTour(); }
        else this.endTour();
      });
      document.body.append(this.tourEl);
    }
    const last = this.tourAt === this.tourSteps.length - 1;
    const html = `<span class="n">${this.tourAt + 1} of ${this.tourSteps.length}</span><b>${s.title}</b>${s.html}
      <div class="acts">${last ? '' : '<button type="button" data-tour="skip" class="skip">Skip</button>'}<button type="button" data-tour="${last ? 'done' : 'next'}">${last ? 'Done' : 'Next'}</button></div>`;
    if (this.tourEl.dataset.k !== `${this.tourAt}|${s.title}`) {
      this.tourEl.dataset.k = `${this.tourAt}|${s.title}`;
      this.tourEl.innerHTML = html;
      this.tourEl.classList.remove('on');
      void this.tourEl.offsetWidth;
      this.tourEl.classList.add('on');
      tgt?.scrollIntoView({ block: 'nearest' });
    }
    for (const el of Array.from(document.querySelectorAll('.tour-glow'))) if (el !== tgt) el.classList.remove('tour-glow');
    const W = 260, bw = this.tourEl.offsetHeight;
    if (!tgt) {
      this.tourEl.className = 'hq-tour on mid';
      this.tourEl.style.left = `${Math.round(innerWidth / 2 - W / 2)}px`;
      this.tourEl.style.top = `${Math.round(innerHeight / 2 - bw / 2)}px`;
      return;
    }
    tgt.classList.add('tour-glow');
    const r = tgt.getBoundingClientRect();
    let side: 'right' | 'below' | 'left' = r.right + 14 + W <= innerWidth - 8 ? 'right' : r.bottom + 14 + bw <= innerHeight - 8 ? 'below' : 'left';
    if (side === 'left' && r.left - 14 - W < 8) side = 'below';
    this.tourEl.className = `hq-tour on ${side}`;
    const left = side === 'right' ? r.right + 14 : side === 'left' ? r.left - 14 - W : Math.min(innerWidth - W - 8, Math.max(8, r.left));
    const top = side === 'below' ? r.bottom + 12 : Math.min(innerHeight - bw - 8, Math.max(8, r.top));
    this.tourEl.style.left = `${Math.round(left)}px`;
    this.tourEl.style.top = `${Math.round(top)}px`;
  }

  /** The first vehicle ever bought: show how to drive it, or how to put it to work. */
  coach(uid: number): void {
    this.coachUid = uid;
    this.render(true);
  }

  /** Drop a drag in progress (Esc). True when there was one. */
  cancel(): boolean {
    const d = this.drag;
    if (!d) return false;
    this.settle(d, null);
    return true;
  }

  render(force = false): void {
    if (this.drag?.ghost) return; // not under a drag
    const f = this.fleet, c = this.host.colours();
    const ridden = f.ridden;
    const out = f.deployed;
    const free = Math.max(0, f.slots - out.length);
    const sel = this.host.picked();
    const caption = f.hq
      ? `HQ <b>${esc(f.hq.name)}</b> <span class="stars">${gradePips(f.hq.grade)}</span> ${esc(gradeName(f.hq))} · ${f.slots} slot${f.slots === 1 ? '' : 's'}${f.hqDown ? ' · <em>boarded up: one slot short</em>' : ''}${this.host.next() ? ` · next: ${esc(this.host.next())}` : ''}`
      : 'No HQ yet: only the vehicle you drive is out. Buy a house (or anything grander) and make it your HQ to open fleet slots';
    const you = ridden ? `<div class="hq-unit you${sel === `u${ridden.uid}` ? ' sel' : ''}" data-uid="${ridden.uid}" data-you data-drop="you">${this.cardInner(ridden)}<div class="hq-seat me"><i style="background:${c.primary}">★</i><small>you</small></div></div>` : '';
    const map = out.map((u) => {
      const d = f.driverOf(u);
      // jets (with no rating) and the things that never stop have no seat to fill; trains take a rail licence
      const def = defOf(u.model);
      const crewable = !!licenceFor(def) && canLoad(def);
      const seat = !crewable ? '' : d
        ? `<div class="hq-seat${sel === `d${d.id}` ? ' sel' : ''}" data-seat="${u.uid}" data-drop="seat"><span class="hq-drv" data-did="${d.id}" title="${esc(d.name)} · drag to another seat (swaps with whoever is in it) or to the bench"><i style="background:${c.primary}">${portraitImg(d.name, 26)}</i><small>${esc(d.name.split(' ')[0])}</small><small class="rk">${rankOf(d)}</small></span></div>`
        : `<div class="hq-seat empty" data-seat="${u.uid}" data-drop="seat"><small>no driver</small></div>`;
      return `<div class="hq-unit${sel === `u${u.uid}` ? ' sel' : ''}" data-uid="${u.uid}" data-drop="unit" style="--pastel:${c.pastel}">${this.cardInner(u)}${seat}</div>`;
    }).join('');
    const empties = Array.from({ length: free }, () => '<div class="hq-free" data-drop="free"><small>free slot</small><small>drag a vehicle from the garage here</small></div>').join('');
    const glow = performance.now() < this.fresh.until ? this.fresh.uid : 0;
    const garage = f.garaged.map((u) => `<div class="hq-unit shed${sel === `u${u.uid}` ? ' sel' : ''}${u.uid === glow ? ' fresh' : ''}" data-uid="${u.uid}" data-drop="unit">${this.cardInner(u, true)}</div>`).join('')
      || '<p class="none">Nothing in the garage. Buy vehicles at a Vehicle Dealer: drive into its striped ring and press Space.</p>';
    const bench = f.bench.map((d) => `<span class="hq-drv chip${sel === `d${d.id}` ? ' sel' : ''}" data-did="${d.id}" title="${esc(d.name)} · drag onto a vehicle to put them in its seat"><i style="background:${c.primary}">${portraitImg(d.name, 26)}</i><b>${esc(d.name)}</b><small>${esc(d.licences.join(' · '))} · ${rankOf(d)} · ${d.mood < 0.45 ? 'bored' : moodWord(d.mood)}</small></span>`).join('');
    // without an HQ there are no slots, so no driver can be signed: the chip says so, and the bench opens on why
    const hire = f.hq
      ? `<button type="button" class="hq-hire${sel === 'hire' ? ' sel' : ''}" data-hire-chip>+ Hire…</button>`
      : `<button type="button" class="hq-hire locked${sel === 'hire' ? ' sel' : ''}" data-hire-chip title="No hiring until you have an HQ">🔒 Hire… needs an HQ</button>`;
    const lock = f.hq ? '' : `<div class="hq-lock"><b>🔒 You can’t hire anyone yet: you need an HQ first.</b><span>Every driver takes a fleet slot, and fleet slots come only from your HQ. Buy a building (a house will do) and make it your HQ: it opens your first slots, and then you can hire drivers here.</span><button type="button" data-hq-home>Where to buy one →</button></div>`;
    // the bench first (the user, 15 Oct 2026): a driver is dragged down onto a seat, and with a long garage the
    // seats on the map would otherwise be a long way from the bench at the bottom
    const html = `<section class="hq-zone${f.hq ? '' : ' nohq'}" data-zone="bench" data-drop="bench"><h5>The bench · ${f.hq ? `${f.drivers.length} of ${f.slots} crew signed` : 'no hiring without an HQ'}</h5>${lock}<div class="hq-chips">${bench}${hire}</div></section>
      <section class="hq-zone" data-zone="map"><h5>On the map · ${out.length} of ${f.slots} slot${f.slots === 1 ? '' : 's'}</h5><p class="cap">${caption}</p><div class="hq-cards">${you}${map}${empties}</div></section>
      <section class="hq-zone" data-zone="garage" data-drop="garage"><h5>The garage · off the map${f.garaged.length ? ` · ${f.garaged.length}` : ''}</h5><div class="hq-cards">${garage}</div></section>`;
    if (force || html !== this.html) {
      this.html = html;
      this.el.innerHTML = html;
    }
    if (this.tourAt >= 0) { this.placeCoach(); requestAnimationFrame(() => { if (this.tourAt >= 0) this.placeTour(); }); return; }
    this.placeCoach();
  }

  /**
   * The first purchase's two tips, pinned beside what they point at: the new car in the garage (drive it
   * yourself), and a free slot and the Hire chip (put it to work). Gone once dismissed or it leaves the garage.
   */
  private placeCoach(): void {
    const old = Array.from(this.el.querySelectorAll<HTMLElement>('.hq-coach'));
    const u = this.coachUid ? this.fleet.unit(this.coachUid) : null;
    const clear = () => { for (const b of old) b.remove(); };
    if (!u || u.where !== 'garaged') { this.coachUid = 0; clear(); return; }
    const card = this.el.querySelector<HTMLElement>(`[data-zone="garage"] [data-uid="${u.uid}"]`);
    if (!card) { clear(); return; }
    const box = this.el.getBoundingClientRect();
    const want: { html: string; cls: string; left: string; top: string }[] = [];
    const pin = (el: HTMLElement, html: string, side: 'right' | 'below') => {
      const r = el.getBoundingClientRect();
      // kept inside the board: a bubble that would run off its right edge goes under its card instead
      const right = side === 'right' && r.right + 10 + 240 <= box.right;
      want.push({
        html: `${html}<button type="button" data-coach-ok>Got it</button>`, cls: `hq-coach ${right ? 'right' : 'below'}`,
        left: `${Math.round((right ? r.right + 10 : r.left) - box.left + this.el.scrollLeft)}px`,
        top: `${Math.round((right ? r.top : r.bottom + 8) - box.top + this.el.scrollTop)}px`,
      });
    };
    pin(card, `<b>① Drive it yourself</b>Drag ${esc(u.name)} onto your car (<i>★ you</i>) at the top, or press <em>Drive it from here</em> in the pane. The car you're in goes into the garage.`, 'right');
    // the last free slot, so the second tip sits clear of the first (which is beside the garage's card)
    const frees = this.el.querySelectorAll<HTMLElement>('[data-drop="free"]');
    const free = frees[frees.length - 1] ?? null;
    const hire = this.el.querySelector<HTMLElement>('[data-hire-chip]');
    const work = free
      ? `<b>② Or put it to work</b>Drag ${esc(u.name)} onto a free slot, then <em>+ Hire…</em> a driver and drag them into its seat: they drive it and pay you a cut of every load.`
      : `<b>② Or put it to work</b>That needs a free slot, and ${this.fleet.hq ? 'yours are full: a grander HQ opens more (Home → Move HQ…)' : 'slots come from an HQ: make a building you own your HQ (Home → Where to buy one)'}. Then <em>+ Hire…</em> a driver and drag them into its seat.`;
    if (free) pin(free, work, 'right');
    else if (hire) pin(hire, work, 'right');
    // the same bubbles where they already are stay put (a new one fades in; redrawing each tick would keep it faded)
    if (old.length === want.length && want.every((w, i) => old[i].dataset.sig === JSON.stringify(w))) return;
    clear();
    for (const w of want) {
      const b = document.createElement('div');
      b.className = w.cls;
      b.innerHTML = w.html;
      b.style.left = w.left;
      b.style.top = w.top;
      b.dataset.sig = JSON.stringify(w);
      this.el.append(b);
    }
  }

  private cardInner(u: Unit, shed = false): string {
    const def = defOf(u.model);
    const img = this.host.thumb(u);
    const ic = this.host.icon(u.uid);
    const aboard = u.agent?.run?.aboard?.length ?? u.run?.aboard?.length ?? 0;
    const line = shed ? `sells for ${money(this.fleet.resale(u))}` : this.fleet.stateLine(u);
    return `<div class="hq-card" title="${esc(u.name)}"><span class="th">${img ? `<img alt="" src="${img}" draggable="false">` : ''}</span>
      <b>${esc(u.name)}</b>${u.name !== def.name ? `<em>${esc(def.name)}</em>` : ''}<small data-line="${u.uid}">${esc(line)}</small>
      ${shed ? '' : `<small class="earn">${money(u.log.earned)} earned</small>`}${ic ? `<span class="ic">${ic}</span>` : ''}${aboard ? `<span class="box">📦${aboard}</span>` : ''}</div>`;
  }

  /** The lines that move, without a redraw. */
  refresh(): void {
    for (const el of Array.from(this.el.querySelectorAll<HTMLElement>('[data-line]'))) {
      const u = this.fleet.unit(Number(el.dataset.line));
      if (!u || u.where === 'garaged') continue;
      const t = this.fleet.stateLine(u);
      if (el.textContent !== t) el.textContent = t;
    }
  }

  // ---- picking and dragging ----
  //
  // What is held rides under the pointer (the user, 19 Oct 2026: a driver dragged off the bench used to show
  // nothing until let go): a driver as their disc and name, a vehicle as its card. It leans with the swing,
  // a pill under it says what letting go here would do (or why not), the page scrolls at its edges, and on
  // release it flies into its new place, or back to where it came from.

  private srcAt(t: HTMLElement): { src: DragSrc; el: HTMLElement } | null {
    const drv = t.closest<HTMLElement>('[data-did]');
    if (drv) return { src: { k: 'driver', id: Number(drv.dataset.did) }, el: drv };
    const card = t.closest<HTMLElement>('[data-uid]');
    if (card) return { src: { k: 'unit', uid: Number(card.dataset.uid) }, el: card };
    return null;
  }

  private down(e: PointerEvent): void {
    if (e.button !== 0) return;
    const t = e.target as HTMLElement;
    if (t.closest('[data-coach-ok]')) { this.coachUid = 0; this.placeCoach(); return; }
    if (t.closest('.hq-coach')) return;
    if (t.closest('[data-hire-chip]')) { this.host.pick({ k: 'hire' }); return; }
    if (t.closest('[data-hq-home]')) { this.host.home?.(); return; }
    const s = this.srcAt(t);
    if (!s) return;
    e.preventDefault();
    const r = s.el.getBoundingClientRect();
    this.drag = {
      src: s.src, x: e.clientX, y: e.clientY, ghost: null, hint: null, from: s.el, dx: e.clientX - r.left, dy: e.clientY - r.top,
      px: e.clientX, py: e.clientY, lastX: e.clientX, vx: 0, tilt: 0, over: null, said: '', raf: 0, scroller: null,
    };
  }

  /** Where this drag could go. A driver goes in a seat (a card stands for its seat), a vehicle onto a card to swap. */
  private targets(src: DragSrc): Target[] {
    const out: Target[] = [];
    for (const el of Array.from(this.el.querySelectorAll<HTMLElement>('[data-drop]'))) {
      const k = el.dataset.drop!;
      if (k === 'seat') { if (src.k === 'driver') out.push({ el, tgt: { k: 'seat', uid: Number(el.dataset.seat) } }); }
      else if (k === 'unit') { if (src.k === 'unit' && Number(el.dataset.uid) !== src.uid) out.push({ el, tgt: { k: 'unit', uid: Number(el.dataset.uid) } }); }
      else if (k === 'free' || k === 'garage' || k === 'bench' || k === 'you') out.push({ el, tgt: { k } as DropTgt });
    }
    return out;
  }

  private targetAt(x: number, y: number, src: DragSrc): Target | null {
    const hit = document.elementFromPoint(x, y) as HTMLElement | null;
    if (!hit || !this.el.contains(hit)) return null;
    // a driver over a vehicle's card means its seat: no need to find the narrow strip on its right
    if (src.k === 'driver') {
      const seat = hit.closest('[data-zone="map"] [data-uid]')?.querySelector<HTMLElement>('[data-drop="seat"]');
      if (seat) return { el: seat, tgt: { k: 'seat', uid: Number(seat.dataset.seat) } };
    }
    // the innermost target under the pointer: a seat or a card inside a zone wins over the zone
    let best: Target | null = null;
    for (const t of this.targets(src)) if (t.el.contains(hit) && (!best || best.el.contains(t.el))) best = t;
    return best;
  }

  /** Whether dropping here swaps with whoever (or whatever) is there now. */
  private swaps(src: DragSrc, tgt: DropTgt): boolean {
    if (tgt.k === 'unit') return true;
    return src.k === 'driver' && tgt.k === 'seat' && !!this.fleet.unit(tgt.uid)?.driver;
  }

  /** Can this driver drive that vehicle at all (its seat and where it stands aside)? */
  private licensed(d: Driver, u: Unit): boolean {
    const def = defOf(u.model);
    return !!licenceFor(def) && canLoad(def) && mayDrive(d, def);
  }

  /**
   * What letting go here would do, in a few words, or why it can't: the pill under what is held, and (when it
   * goes ahead) the line the board says after.
   */
  private hint(src: DragSrc, tgt: DropTgt): { ok: boolean; text: string; done: string } {
    const why = dropWhy(this.fleet, this.host, src, tgt);
    if (why) return { ok: false, text: why, done: '' };
    const f = this.fleet;
    if (src.k === 'driver') {
      const d = f.driver(src.id)!;
      if (tgt.k === 'bench') return { ok: true, text: 'To the bench', done: `${d.name} is on the bench` };
      const u = f.unit((tgt as { uid: number }).uid)!;
      const was = f.driverOf(u);
      if (!was) return { ok: true, text: `Drive the ${u.name}`, done: `${d.name} is out in ${u.name}` };
      const from = d.unit ? f.unit(d.unit) : null;
      const moves = !!from && from !== u && this.licensed(was, from) && !f.cantPut(was, from, true);
      return {
        ok: true,
        text: `⇄ Swap with ${was.name}${moves ? ` · they take the ${from!.name}` : ' · they go to the bench'}`,
        done: `${d.name} took over ${u.name}${moves ? ` · ${was.name} moved to ${from!.name}` : ` · ${was.name} is on the bench`}`,
      };
    }
    const u = f.unit(src.uid)!;
    if (tgt.k === 'free') return { ok: true, text: 'Bring it out', done: `${u.name} is out of the garage, beside you` };
    if (tgt.k === 'garage') return { ok: true, text: 'Into the garage', done: `${u.name} is in the garage` };
    if (tgt.k === 'you') {
      const ridden = f.ridden;
      return {
        ok: true,
        text: u.where === 'garaged' ? `Drive it${ridden ? ` · ${ridden.name} to the garage` : ''}` : 'Take the wheel',
        done: `You are driving ${u.name}`,
      };
    }
    const { out, inn } = swapPair(f, u, (tgt as { uid: number }).uid) as { out: Unit; inn: Unit };
    const crew = f.driverOf(out);
    const along = crew && this.licensed(crew, inn) ? ` · ${crew.name} moves over` : '';
    return { ok: true, text: `⇄ Swap: ${inn.name} out, ${out.name} in${along}`, done: `${inn.name} is out, ${out.name} is in the garage${along}` };
  }

  private move(e: PointerEvent): void {
    const d = this.drag;
    if (!d) return;
    d.px = e.clientX; d.py = e.clientY;
    if (!d.ghost) {
      if (Math.hypot(e.clientX - d.x, e.clientY - d.y) < 6) return;
      // a ridden car can't be dragged anywhere: it stays a click
      if (d.src.k === 'unit' && this.fleet.unit(d.src.uid)?.where === 'ridden') { this.drag = null; return; }
      this.lift(d);
    }
    d.vx = d.vx * 0.5 + (e.clientX - d.lastX) * 0.5;
    d.lastX = e.clientX;
    this.hover(d);
    this.place(d);
  }

  /** Pick it up: the thing held is drawn under the pointer, and every place it could go lights up. */
  private lift(d: Drag): void {
    const g = document.createElement('div');
    const c = this.host.colours();
    if (d.src.k === 'driver') {
      const dr = this.fleet.driver(d.src.id);
      g.className = 'hq-ghost tok';
      g.innerHTML = `<i style="background:${c.primary}">${dr ? portraitImg(dr.name, 26) : '?'}</i><b>${esc(dr?.name ?? '')}</b><small>${dr ? `${esc(dr.licences.join(' · '))} · ${rankOf(dr)}` : ''}</small><span class="hint"></span>`;
      // held by the middle of the disc, as a counter is
      d.dx = 0; d.dy = 22;
    } else {
      const u = this.fleet.unit(d.src.uid)!;
      g.className = 'hq-ghost card';
      if (u.where !== 'garaged') g.style.background = c.pastel;
      g.innerHTML = `${this.cardInner(u, u.where === 'garaged')}<span class="hint"></span>`;
      // held where it was grabbed (the seat strip is not part of the copy)
      d.dx = Math.min(d.dx, 130) - 69; d.dy = Math.min(d.dy, 100);
    }
    // inside the HQ window, where the card's own rules (its size, its thumbnail's) apply: on the page body
    // the copy lost them and the picture swelled to its full size (the user, 7 Oct 2026). The window fills
    // the screen, so its fixed position is the screen's.
    (this.el.closest('#hq') ?? document.body).append(g);
    d.ghost = g;
    d.hint = g.querySelector<HTMLElement>('.hint');
    d.from.classList.add('lifted');
    document.body.classList.add('hq-grabbing');
    // light up every place it could go, so the player learns where things go; a swap in amber
    for (const { el, tgt } of this.targets(d.src)) {
      const no = dropWhy(this.fleet, this.host, d.src, tgt);
      el.classList.add(no ? 'no' : 'ok');
      if (!no && this.swaps(d.src, tgt)) el.classList.add('swap');
    }
    d.scroller = this.scroller();
    const tick = () => {
      if (this.drag !== d) return;
      this.frame(d);
      d.raf = requestAnimationFrame(tick);
    };
    d.raf = requestAnimationFrame(tick);
  }

  /** The scrolling box the board sits in, to scroll when something held nears its top or bottom. */
  private scroller(): HTMLElement | null {
    for (let p = this.el as HTMLElement | null; p && p !== document.body; p = p.parentElement) {
      const o = getComputedStyle(p).overflowY;
      if ((o === 'auto' || o === 'scroll') && p.scrollHeight > p.clientHeight + 2) return p;
    }
    return null;
  }

  /** Each frame while held: the lean eases back upright, and the page scrolls at its edges. */
  private frame(d: Drag): void {
    d.vx *= 0.8;
    const sc = d.scroller;
    if (sc) {
      const r = sc.getBoundingClientRect(), edge = 56;
      const into = d.py < r.top + edge ? d.py - (r.top + edge) : d.py > r.bottom - edge ? d.py - (r.bottom - edge) : 0;
      if (into) {
        const before = sc.scrollTop;
        sc.scrollTop += Math.sign(into) * Math.min(22, 3 + Math.abs(into) * 0.3);
        if (sc.scrollTop !== before) this.hover(d);
      }
    }
    this.place(d);
  }

  private place(d: Drag): void {
    const g = d.ghost;
    if (!g) return;
    d.tilt += (Math.max(-9, Math.min(9, d.vx * 0.9)) - d.tilt) * 0.35;
    const over = d.over && g.classList.contains('ok') ? 0.95 : 1.04;
    g.style.transform = `translate(${Math.round(d.px - d.dx)}px, ${Math.round(d.py - d.dy)}px) translateX(-50%) rotate(${d.tilt.toFixed(1)}deg) scale(${over})`;
    // the pill stays level to read while what it hangs from swings
    if (d.hint) d.hint.style.rotate = `${(-d.tilt).toFixed(1)}deg`;
  }

  /** What is under the pointer now: that place marked, and the pill says what letting go would do. */
  private hover(d: Drag): void {
    const over = this.targetAt(d.px, d.py, d.src);
    if (over?.el !== d.over?.el) {
      d.over?.el.classList.remove('hover');
      over?.el.classList.add('hover');
      d.over = over;
    }
    const h = over ? this.hint(d.src, over.tgt) : null;
    const text = h?.text ?? '';
    if (text !== d.said && d.hint) { d.hint.textContent = text; d.said = text; }
    d.ghost?.classList.toggle('ok', !!h?.ok);
    d.ghost?.classList.toggle('no', !!h && !h.ok);
  }

  private up(e: PointerEvent): void {
    const d = this.drag;
    if (!d) return;
    if (!d.ghost) {
      // a click: pick it
      this.drag = null;
      this.host.pick(d.src);
      return;
    }
    d.px = e.clientX; d.py = e.clientY;
    const over = this.targetAt(e.clientX, e.clientY, d.src);
    const h = over ? this.hint(d.src, over.tgt) : null;
    const why = over ? dropDo(this.fleet, this.host, d.src, over.tgt) : 'nowhere';
    if (!over || why) {
      // back where it came from; a refusal is said, a drop on nothing just goes back
      this.settle(d, null);
      if (over && why) this.host.say(why);
      return;
    }
    // who else moved in a swap, to give them a bump as they land too
    const other = d.src.k === 'driver'
      ? (over.tgt.k === 'seat' ? this.fleet.unit(over.tgt.uid)?.driver ?? 0 : 0)
      : (over.tgt.k === 'unit' ? over.tgt.uid : 0);
    this.settle(d, over.el.getBoundingClientRect());
    this.host.say(h?.done || 'Done');
    this.host.pick(d.src);
    this.host.changed();
    this.render(true);
    const key = d.src.k === 'driver' ? 'did' : 'uid';
    const own = d.src.k === 'driver' ? d.src.id : d.src.uid;
    for (const id of [own, other]) if (id) for (const el of Array.from(this.el.querySelectorAll<HTMLElement>(`[data-${key}="${id}"]`))) el.classList.add('landed');
  }

  /** Let go: it flies to `to` and fades (a drop), or back to where it was picked up (null). */
  private settle(d: Drag, to: DOMRect | null): void {
    cancelAnimationFrame(d.raf);
    this.drag = null;
    document.body.classList.remove('hq-grabbing');
    for (const el of Array.from(this.el.querySelectorAll('.ok, .no, .hover, .swap'))) el.classList.remove('ok', 'no', 'hover', 'swap');
    const g = d.ghost;
    const from = d.from;
    if (!g) { from.classList.remove('lifted'); return; }
    const r = to ?? from.getBoundingClientRect();
    const gr = g.getBoundingClientRect();
    // the ghost's transform is centred on x by translateX(-50%); aim its middle at the middle of the place
    const x = r.left + r.width / 2, y = r.top + r.height / 2 - gr.height / 2;
    g.classList.add(to ? 'drop' : 'back');
    g.style.transition = 'transform .2s cubic-bezier(.25,.8,.35,1), opacity .2s ease-in';
    g.style.transform = `translate(${Math.round(x)}px, ${Math.round(y)}px) translateX(-50%) scale(${to ? 0.6 : 1})`;
    g.style.opacity = to ? '0' : '0.25';
    window.setTimeout(() => {
      g.remove();
      from.classList.remove('lifted');
      if (!to) this.render(true);
    }, 200);
  }
}
