/** A barrel vault over a w×d base, its ridge along x, ends closed. */
function vault(k: Kit, x: number, y: number, z: number, w: number, h: number, d: number, col: RGB, end: RGB): void {
  const n = 7, I: P3 = [x, y, z];
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * Math.PI, a1 = ((i + 1) / n) * Math.PI;
    const z0 = z + Math.cos(a0) * d / 2, z1 = z + Math.cos(a1) * d / 2, y0 = y + Math.sin(a0) * h, y1 = y + Math.sin(a1) * h;
    k.quad([x - w / 2, y0, z0], [x + w / 2, y0, z0], [x + w / 2, y1, z1], [x - w / 2, y1, z1], i % 2 ? col : scale(col, 0.94), I);
    for (const s of [-1, 1]) k.tri([x + s * w / 2, y, z], [x + s * w / 2, y0, z0], [x + s * w / 2, y1, z1], end, I);
  }
}

/** A prototype in dazzle camouflage. */
function dazzleCar(k: Kit, x: number, z: number, alongX: boolean): void {
  const B = body(k, x, z, alongX);
  B(0, 0.02, 0, 0.42, 0.09, 0.2, WHITE);
  B(-0.03, 0.11, 0, 0.22, 0.065, 0.17, DARK, WHITE);
  for (const [l, w] of [[-0.15, 0.05], [-0.04, 0.035], [0.06, 0.06], [0.17, 0.03]] as const) B(l, 0.02, 0, w, 0.093, 0.206, RUBBER);
  B(-0.06, 0.11, 0, 0.04, 0.068, 0.175, WHITE);
}

