  k.box(tx, 0.95, tz, 0.62, 0.24, 0.62, GLASS);
  for (let f = 0; f < 4; f++) k.pane(tx + [0.31, 0, -0.31, 0][f], 0.98, tz + [0, 0.31, 0, -0.31][f], 0.54, 0.18, f, GLASS_LIGHT, NIGHT, WARM_GLOW);
  k.box(tx, 1.19, tz, 0.74, 0.05, 0.74, WHITE);
  k.box(tx + 0.2, 1.24, tz - 0.2, 0.02, 0.3, 0.02, METAL);
