import type { TownDigest } from '../src/world/townDigest';
import type { Filters, SortId } from '../src/game/registerSorts';

/**
 * The world gazetteer on the wire (docs/townregister.html, phase 4; server/gazetteer.ts, net/townsNet.ts): every town any
 * player has had in memory, as its digest and what the shared books say of it, so the town register's World scope is the
 * same list for every player. Games report the towns on their islands; the server keeps the newest report of each and
 * answers ranked, filtered pages.
 */

/** What the shared books say of a town (the same for every player online: the cell's town ledger, culture, territory). */
export interface TownStats {
  /** Trade, $/h, and against the norm for its size. */
  rate: number;
  prosperity: number;
  /** Buildings grown over its last 30 days; boarded up. */
  grown30: number;
  blight: number;
  /** Culture points summed; styles at Influenced or above; each style's [points, rung, label]. */
  culture: number;
  cultures: number;
  styles: Record<string, [number, number, string]>;
  /** Its property's worth. */
  value: number;
  /** Whose territory, as a player id or a firm's id ('' nobody), and whether contested. */
  holder: string;
  contested: boolean;
}

/** One town as a game reports it and the server hands it back. */
export interface TownReport { d: TownDigest; s: TownStats }

/** A register query: the World scope's sort, filters and search, from row `at`, and where the asker stands (world tiles). */
export interface TownQuery {
  sort: SortId;
  flip?: boolean;
  /** The culture "Most of one culture" ranks by. */
  style?: string;
  f: Filters;
  q?: string;
  at: number;
  /** Where the asker's vehicle is, for "Nearest" and the distance filter. */
  me?: [number, number];
}

/** From a game: its towns to keep (`rep`), or a page to ask for (`ask`, answered with `TownsPage`). */
export interface TownsMsg { rep?: TownReport[]; ask?: TownQuery }

/** From the server: one page of the World scope, and how many towns pass in all (`known`: in the gazetteer at all). */
export interface TownsPage { page: { ask: TownQuery; rows: TownReport[]; total: number; known: number } }

/** A town key as the games write it: county and town id. */
export const TOWN_KEY = /^-?\d{1,4},-?\d{1,4}#\d{1,4}$/;
/** Towns a report may carry, and the gazetteer's most. */
export const TOWNS_PER_REPORT = 100;
export const TOWNS_MAX = 50_000;
/** Rows a page holds at most. */
export const TOWNS_PAGE = 150;
