import type { AirDef } from './vehicles';
import { frameOf, pointOf, type Runway } from '../world/runways';
import { GLIDE } from './air';
import { clamp } from '../util/math';

/**
 * A hired pilot's jet in the air (docs/rides.html, 0.7.0): scripted like the airports' own traffic
 * (game/skyTraffic.ts), on the same glide slope, runway geometry and runway lock, from a stand at one airport
 * to a stand at another, or out to an overseas point and back. Nothing is simulated, so nothing can crash: it
 * climbs over whatever ground lies ahead, never sits lower than the ground under it, holds short of a busy
 * runway and goes around when its runway is taken as it reaches the gate. Pure, so `npm run jetpilots` flies
 * it headless.
 */

export type JetPhase = 'stand' | 'taxiOut' | 'hold' | 'roll' | 'climb' | 'cruise' | 'inbound' | 'around' | 'final' | 'rollout' | 'taxiIn';

/** Where it is going: a runway it will land on, or a point overseas it hands loads over at in flight. */
export type JetGoal = { kind: 'runway'; r: Runway } | { kind: 'overseas'; x: number; z: number; name: string };

export interface JetEnv {
  /** Ground (or roof) height under a world tile, world units. */
  ground(gx: number, gz: number): number;
  /** May this flight have the runway (the player always has theirs), and take it or let it go. */
  free(r: Runway, id: number): boolean;
  take(r: Runway, id: number): void;
  release(r: Runway, id: number): void;
  /** The end a runway's traffic uses now (into the wind): 1 lands at A heading for B. */
  end(r: Runway): 1 | -1;
  /** Is stand k of this runway taken by some other flight? */
  standTaken(r: Runway, k: number, id: number): boolean;
  /** Which of an airport's runways flight `id` uses (a two-runway airport's either, world/runways.ts stripFor); else the one. */
  strip?(r: Runway, id: number): Runway;
}

interface JetPose {
  x: number; y: number; z: number; heading: number; v: number;
  pitch: number; roll: number; gear: number; wheelSpin: number; power: number;
}

export interface JetFlight {
  id: number;
  def: AirDef;
  phase: JetPhase;
  st: JetPose;
  goal: JetGoal;
  /** The runway it is on or using, the end it uses, the taxi route still to go and the stand it is bound for. */
  rw: Runway | null;
  dir: 1 | -1;
  path: { x: number; z: number }[];
  stand: number;
  /** The height it cruises at, world units, worked out at take-off. */
  alt: number;
  /** Go-arounds on this leg, seconds in this phase, and seconds on the stand still to wait. */
  arounds: number;
  t: number;
  wait: number;
}

/** Tiles out from the threshold where final begins, as the airports' own arrivals fly it. */
const GATE_OUT = 45;
const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));
/** Turn rate in the air (rad/s), and the radius that makes at a speed. */
const TURN = 0.35;
const radius = (v: number) => Math.max(8, v / TURN);

/** The speed it cruises at, tiles a second. */
export const cruiseV = (def: AirDef) => def.topSpeed * 0.8;

/** The threshold it lands at, the heading it lands on, and that heading's unit vector. */
function landing(r: Runway, dir: 1 | -1): { tx: number; tz: number; ux: number; uz: number; h: number } {
  const ux = r.ux * dir, uz = r.uz * dir;
  return { tx: dir === 1 ? r.ax : r.bx, tz: dir === 1 ? r.az : r.bz, ux, uz, h: Math.atan2(ux, uz) };
}

/** Where it sits against the approach: tiles out from the threshold (positive on the approach side), and across. */
function approachOf(f: JetFlight, r: Runway, dir: 1 | -1): { out: number; off: number; h: number } {
  const L = landing(r, dir), st = f.st;
  const dx = st.x - L.tx, dz = st.z - L.tz;
  return { out: -(dx * L.ux + dz * L.uz), off: dx * Math.cos(L.h) - dz * Math.sin(L.h), h: L.h };
}

/** The point well out on the extended centreline it joins the approach from, sized to its turn. */
function joinPoint(f: JetFlight, r: Runway, dir: 1 | -1): { x: number; z: number; out: number } {
  const L = landing(r, dir), out = GATE_OUT + 4 * radius(f.def.jet!.approach * 1.3);
  return { x: L.tx - L.ux * out, z: L.tz - L.uz * out, out };
}

/** A flight standing at stand k of runway r, its nose toward the strip. */
export function standing(id: number, def: AirDef, r: Runway, k: number, goal: JetGoal): JetFlight {
  const s = r.stands[k];
  return {
    id, def, phase: 'stand', goal, rw: r, dir: 1, path: [], stand: k, alt: 0, arounds: 0, t: 0, wait: 0,
    st: { x: s.x, y: r.y, z: s.z, heading: s.heading, v: 0, pitch: 0, roll: 0, gear: 1, wheelSpin: 0, power: 0.2 },
  };
}

/** Send a flight at its stand off to its goal: the route to the runway end into the wind, then the roll. */
export function depart(f: JetFlight, env: JetEnv): void {
  const r = (f.rw = env.strip ? env.strip(f.rw!, f.id) : f.rw!), s = r.stands[f.stand] ?? { x: f.st.x, z: f.st.z };
  f.dir = env.end(r);
  const fs = frameOf(r, s.x, s.z);
  const start = f.dir === 1 ? -1.5 : r.len + 1.5;
  f.path = [pointOf(r, fs.along, r.taxiOff), pointOf(r, start, r.taxiOff), pointOf(r, start, 0)];
  f.phase = 'taxiOut';
  f.t = 0;
  f.arounds = 0;
  f.stand = -1;
}

/** Pick the flight up in the air (a save loaded mid-flight): it cruises on toward its goal from here. */
export function airborne(f: JetFlight, env: JetEnv): void {
  f.phase = 'cruise';
  f.rw = null;
  f.st.v = Math.max(f.st.v, cruiseV(f.def) * 0.8);
  f.st.gear = 0;
  f.alt = cruiseAlt(f, env);
  f.t = 0;
}

/** The highest ground anywhere ahead, out to `look` tiles along its heading and a little either side. */
function groundAhead(f: JetFlight, env: JetEnv, look: number): number {
  const st = f.st, hx = Math.sin(st.heading), hz = Math.cos(st.heading);
  let g = env.ground(st.x, st.z);
  for (let d = 4; d <= look; d += 4) for (const s of [-3, 0, 3]) g = Math.max(g, env.ground(st.x + hx * d + hz * s, st.z + hz * d - hx * s));
  return g;
}

/** Its cruising height: well over the ground it leaves from and over whatever lies on the way out. */
function cruiseAlt(f: JetFlight, env: JetEnv): number {
  return Math.max((f.rw?.y ?? env.ground(f.st.x, f.st.z)) + f.def.cruiseClear, groundAhead(f, env, 80) + f.def.minClear + 3);
}

/** Turn toward a heading at no more than the air turn rate, banking into it. */
function steer(f: JetFlight, want: number, dt: number, rate = TURN): void {
  const st = f.st, d = wrap(want - st.heading);
  const turn = clamp(d * 1.5, -rate, rate);
  st.heading = wrap(st.heading + turn * dt);
  st.roll += (-clamp(turn * st.v * 0.1, -0.4, 0.4) - st.roll) * Math.min(1, dt * 3);
}

/** Toward a height, climbing at the model's rate and coming down a little slower. */
function holdHeight(f: JetFlight, y: number, dt: number): void {
  const st = f.st, up = f.def.climbRate * 0.8, down = f.def.climbRate * 0.5;
  st.y += clamp(y - st.y, -down * dt, up * dt);
  st.pitch += (clamp(-(y - st.y) * 0.05, -0.14, 0.08) - st.pitch) * Math.min(1, dt * 2);
}

const forward = (st: JetPose, dt: number) => { st.x += Math.sin(st.heading) * st.v * dt; st.z += Math.cos(st.heading) * st.v * dt; };

/** Follow the taxi route; true once at its end. */
function taxi(f: JetFlight, dt: number): boolean {
  const st = f.st, p = f.path[0], speed = f.def.jet!.taxi * 1.2;
  if (!p) return true;
  const dx = p.x - st.x, dz = p.z - st.z, d = Math.hypot(dx, dz);
  if (d < 0.25) { f.path.shift(); return f.path.length === 0; }
  const want = Math.atan2(dx, dz);
  st.heading = wrap(st.heading + clamp(wrap(want - st.heading), -1.4 * dt, 1.4 * dt));
  st.v += ((Math.abs(wrap(want - st.heading)) > 0.5 ? speed * 0.35 : speed) - st.v) * Math.min(1, dt * 2);
  forward(st, Math.min(dt, d / Math.max(0.1, st.v)));
  st.wheelSpin += st.v * dt * 6;
  st.roll = 0;
  st.pitch = 0;
  return false;
}

/** What happened this step, for whoever flies it: it left the ground, reached the overseas point, went around or parked. */
type JetEvent = 'airborne' | 'overseas' | 'around' | 'landed' | null;

/** One step of a flight. */
export function stepJet(f: JetFlight, dt: number, env: JetEnv): JetEvent {
  const st = f.st, def = f.def, j = def.jet!;
  f.t += dt;
  let ev: JetEvent = null;
  const air = f.phase === 'climb' || f.phase === 'cruise' || f.phase === 'inbound' || f.phase === 'around' || f.phase === 'final';
  switch (f.phase) {
    case 'stand': {
      st.v = 0;
      if (f.wait > 0) f.wait -= dt;
      break;
    }
    case 'taxiOut':
    case 'taxiIn': {
      if (taxi(f, dt)) {
        if (f.phase === 'taxiOut') { f.phase = 'hold'; f.t = 0; st.v = 0; }
        else {
          f.phase = 'stand'; f.t = 0; st.v = 0;
          const s = f.rw!.stands[f.stand];
          if (s) st.heading = s.heading;
          ev = 'landed';
        }
      }
      break;
    }
    case 'hold': {
      const r = f.rw!, rh = f.dir === 1 ? r.heading : wrap(r.heading + Math.PI);
      st.heading = wrap(st.heading + wrap(rh - st.heading) * Math.min(1, dt * 2));
      if (Math.abs(wrap(rh - st.heading)) < 0.05 && env.free(r, f.id)) {
        env.take(r, f.id);
        st.heading = rh;
        f.phase = 'roll'; f.t = 0;
      }
      break;
    }
    case 'roll': {
      st.v += j.groundAccel * 1.3 * dt;
      forward(st, dt);
      st.wheelSpin += st.v * dt * 6;
      const rot = clamp((st.v - j.rotate * 0.85) / (j.rotate * 0.15), 0, 1);
      st.pitch = -0.09 * rot;
      if (st.v >= j.rotate) { f.phase = 'climb'; f.t = 0; f.alt = cruiseAlt(f, env); ev = 'airborne'; }
      break;
    }
    case 'climb': {
      const r = f.rw;
      st.v = Math.min(cruiseV(def), st.v + def.accel * 0.6 * dt);
      forward(st, dt);
      st.y += def.climbRate * 0.7 * dt;
      st.pitch += (-0.14 - st.pitch) * Math.min(1, dt * 2);
      // straight out along the runway until well clear of it, then round toward the goal
      if (r && st.y - r.y > 3) { env.release(r, f.id); f.rw = null; }
      if (!f.rw) steer(f, aimOf(f, env), dt, TURN * 0.6);
      f.alt = Math.max(f.alt, groundAhead(f, env, 40) + def.minClear + 3);
      if (st.y >= f.alt - 1) { f.phase = 'cruise'; f.t = 0; }
      break;
    }
    case 'cruise': {
      const g = f.goal;
      steer(f, aimOf(f, env), dt);
      if (g.kind === 'overseas') {
        st.v += (cruiseV(def) - st.v) * Math.min(1, dt * 0.4);
        forward(st, dt);
        holdHeight(f, Math.max(f.alt, groundAhead(f, env, 60) + def.minClear + 3), dt);
        if (Math.hypot(g.x - st.x, g.z - st.z) < 10) { ev = 'overseas'; f.t = 0; }
        break;
      }
      const r = env.strip ? env.strip(g.r, f.id) : g.r, dir = env.end(r), J = joinPoint(f, r, dir);
      const dist = Math.hypot(J.x - st.x, J.z - st.z);
      // slowing to the approach speed and coming down the glide slope's line long before the join
      const slow = clamp((dist - 40) / 120, 0, 1);
      st.v += (j.approach * 1.3 + (cruiseV(def) - j.approach * 1.3) * slow - st.v) * Math.min(1, dt * 0.4);
      forward(st, dt);
      const down = r.y + (J.out + dist) * GLIDE * 0.9 + 1;
      holdHeight(f, Math.max(Math.min(f.alt, down), groundAhead(f, env, 60) + def.minClear + 3), dt);
      const ahead = (J.x - st.x) * Math.sin(st.heading) + (J.z - st.z) * Math.cos(st.heading);
      const R = radius(st.v);
      if (dist < R * 0.8 || (dist < 3 * R && ahead < 0)) { f.phase = 'inbound'; f.t = 0; f.rw = r; f.dir = dir; }
      break;
    }
    case 'around': {
      // out to the join point again, climbing back up to it, then in once more
      const r = f.rw!, J = joinPoint(f, r, f.dir);
      const dist = Math.hypot(J.x - st.x, J.z - st.z);
      steer(f, Math.atan2(J.x - st.x, J.z - st.z), dt);
      st.v += (j.approach * 1.4 - st.v) * Math.min(1, dt * 0.5);
      forward(st, dt);
      holdHeight(f, Math.max(r.y + J.out * GLIDE + 4, groundAhead(f, env, 50) + def.minClear + 2), dt);
      st.gear = Math.max(0, st.gear - dt);
      const ahead = (J.x - st.x) * Math.sin(st.heading) + (J.z - st.z) * Math.cos(st.heading);
      const R = radius(st.v);
      if (f.t > 6 && (dist < R * 0.8 || (dist < 3 * R && ahead < 0))) { f.phase = 'inbound'; f.t = 0; }
      break;
    }
    case 'inbound': {
      // intercept the extended centreline and track it in, down the glide slope's line, to the gate
      const r = f.rw!, a = approachOf(f, r, f.dir);
      steer(f, wrap(a.h - clamp(a.off * 0.06, -0.7, 0.7)), dt);
      st.v += (j.approach * 1.3 - st.v) * Math.min(1, dt * 0.5);
      forward(st, dt);
      holdHeight(f, Math.max(r.y + Math.max(GATE_OUT, a.out) * GLIDE + 1, groundAhead(f, env, 30) + def.minClear), dt);
      if (a.out < 30) st.gear = Math.min(1, st.gear + dt);
      if (a.out <= GATE_OUT + 1) {
        const lined = Math.abs(a.off) < 4 && Math.abs(wrap(a.h - st.heading)) < 0.35;
        if (lined && env.free(r, f.id)) { env.take(r, f.id); f.phase = 'final'; f.t = 0; }
        else { f.phase = 'around'; f.t = 0; f.arounds++; ev = 'around'; }
      } else if (f.t > 120) { f.phase = 'around'; f.t = 0; f.arounds++; ev = 'around'; }
      break;
    }
    case 'final': {
      const r = f.rw!, a = approachOf(f, r, f.dir);
      const d = wrap(a.h - clamp(a.off * 0.12, -0.4, 0.4) - st.heading);
      st.heading = wrap(st.heading + d * Math.min(1, dt * 2));
      st.roll = -d * 0.5;
      st.v += (j.approach - st.v) * Math.min(1, dt * 0.8);
      forward(st, dt);
      const target = r.y + Math.max(0, a.out) * GLIDE;
      st.y += (target - st.y) * Math.min(1, dt * 2);
      st.pitch += (-0.05 - st.pitch) * Math.min(1, dt * 2);
      st.gear = 1;
      if (a.out < 0 && st.y - r.y < 0.1) { st.y = r.y; f.phase = 'rollout'; f.t = 0; }
      else if (a.out > 4 && !env.free(r, f.id)) {
        // the player has taken the runway while it was on final: away, and round again
        f.phase = 'around'; f.t = 0; f.arounds++; ev = 'around';
      } else if (a.out < -r.len * 0.5) {
        // floated half the runway without touching down: climb away and come round again
        env.release(r, f.id);
        f.phase = 'around'; f.t = 0; f.arounds++; ev = 'around';
      }
      break;
    }
    case 'rollout': {
      const r = f.rw!;
      st.v = Math.max(j.taxi, st.v - j.groundBrake * 1.4 * dt);
      forward(st, dt);
      st.wheelSpin += st.v * dt * 6;
      st.pitch += (0 - st.pitch) * Math.min(1, dt * 3);
      st.roll = 0;
      st.y = r.y;
      const fr = frameOf(r, st.x, st.z);
      if (st.v <= j.taxi + 0.01 || fr.along < -1 || fr.along > r.len + 1) {
        // off the runway to the taxi line, along it to a free stand
        env.release(r, f.id);
        const k = r.stands.findIndex((_, i) => !env.standTaken(r, i, f.id));
        f.stand = k < 0 ? 0 : k;
        const s = r.stands[f.stand], fs = frameOf(r, s.x, s.z), along = clamp(fr.along, 0, r.len);
        f.path = [pointOf(r, along, r.taxiOff), pointOf(r, fs.along, r.taxiOff), { x: s.x, z: s.z }];
        f.phase = 'taxiIn'; f.t = 0;
      }
      break;
    }
  }
  if (air) {
    // never under the ground (or a roof) it is over, whatever the script says
    const g = env.ground(st.x, st.z) + (f.phase === 'final' ? 0.3 : def.minClear * 0.5);
    if (f.phase !== 'final' || frameOf(f.rw!, st.x, st.z).along < -2 || frameOf(f.rw!, st.x, st.z).along > f.rw!.len + 2) st.y = Math.max(st.y, g);
  }
  if (f.phase === 'climb' || f.phase === 'cruise') st.gear = Math.max(0, st.gear - dt);
  st.power = f.phase === 'roll' || f.phase === 'climb' ? 1 : f.phase === 'cruise' ? 0.7 : f.phase === 'taxiIn' || f.phase === 'taxiOut' ? 0.3 : f.phase === 'stand' ? 0.15 : 0.45;
  return ev;
}

/** The heading toward where it is going now: the overseas point, or its runway's join point. */
function aimOf(f: JetFlight, env: JetEnv): number {
  const g = f.goal, st = f.st;
  if (g.kind === 'overseas') return Math.atan2(g.x - st.x, g.z - st.z);
  const r = env.strip ? env.strip(g.r, f.id) : g.r, J = joinPoint(f, r, env.end(r));
  return Math.atan2(J.x - st.x, J.z - st.z);
}

/** Is it on the ground (taxiing, on the runway, at a stand)? */
export const onGround = (f: JetFlight) => f.phase === 'stand' || f.phase === 'taxiOut' || f.phase === 'hold' || f.phase === 'roll' || f.phase === 'rollout' || f.phase === 'taxiIn';
