import * as THREE from 'three';
import type { VehicleDef } from '../game/vehicles';
import { JOBS } from '../game/factions/paintjobs';
import { mulberry32, hashString } from '../world/rng';

/**
 * Paintjobs on a vehicle's body (docs/factions.html, "Paintjobs, not colours"). Like the workshop's
 * bolt-ons (render/boltOns.ts) nothing here knows a model: the body is measured once it is built — the box
 * its panels fill, how high it stands at a point, how far out its side is at a height — and the paintjob's
 * rules are laid on that: panels recoloured by where they are (the roof, the bonnet), bands, pinstripes and
 * a racing stripe as thin strips just proud of the panels, the crest and a word on the doors as small
 * pictures, camouflage as patches, and the bolt-ons on top. Runs before the parts are merged, so everything
 * but the pictures merges into the body.
 */

interface Part { mesh: THREE.Mesh; box: THREE.Box3 }

const DARK = 0x2a2a2e, CHROME = 0xd9dde2, WHITE = 0xf4f2ec;

/** Dress `body` in its definition's paintjob, if it has one. */
export function dressJob(root: THREE.Object3D, body: THREE.Group, def: VehicleDef, wheels: THREE.Object3D[]): void {
  const id = (def as { job?: string }).job;
  const job = id ? JOBS[id] : undefined;
  if (!job || def.kind === 'rail') return;
  root.updateMatrixWorld(true);
  const inWheel = new Set<THREE.Object3D>();
  for (const w of wheels) w.traverse((o) => inWheel.add(o));
  const parts: Part[] = [];
  body.traverse((o) => {
    const m = o as THREE.Mesh;
    if (!m.isMesh || inWheel.has(m)) return;
    m.geometry.computeBoundingBox();
    parts.push({ mesh: m, box: m.geometry.boundingBox!.clone().applyMatrix4(m.matrixWorld) });
  });
  if (!parts.length) return;
  const all = new THREE.Box3();
  for (const p of parts) all.union(p.box);
  const painted = parts.filter((p) => {
    const m = p.mesh.material as THREE.MeshStandardMaterial;
    return !Array.isArray(p.mesh.material) && m.isMeshStandardMaterial && m.color.getHex() === def.color && m.emissive.getHex() === 0;
  });
  const pb = new THREE.Box3();
  for (const p of painted) pb.union(p.box);
  const box = painted.length ? pb : all;
  const kit = new JobKit(body);
  const lo = box.min.y, hi = box.max.y, H = Math.max(0.05, hi - lo);
  const len = all.max.z - all.min.z, wid = all.max.x - all.min.x;
  const nose = all.max.z, tail = all.min.z, mid = (nose + tail) / 2;
  const air = def.kind === 'air', water = def.kind === 'water';

  const top = (x: number, z: number): number => {
    let y = -Infinity;
    for (const p of parts) {
      const b = p.box;
      if (x >= b.min.x - 0.02 && x <= b.max.x + 0.02 && z >= b.min.z - 0.02 && z <= b.max.z + 0.02) y = Math.max(y, b.max.y);
    }
    return Number.isFinite(y) ? y : all.max.y;
  };
  /** How far out the body's side is at height y and along z: the painted panels first. */
  const side = (y: number, z: number): number => {
    let x = 0;
    for (const p of painted.length ? painted : parts) {
      const b = p.box;
      if (y >= b.min.y - 0.01 && y <= b.max.y + 0.01 && z >= b.min.z - 0.01 && z <= b.max.z + 0.01) x = Math.max(x, b.max.x);
    }
    return x;
  };

  // ---- the panels ----
  const mats = new Map<string, THREE.MeshStandardMaterial>();
  const finish = (c: number): THREE.MeshStandardMaterial => {
    const k = `${c}|${job.finish ?? ''}`;
    let m = mats.get(k);
    if (!m) {
      const f = job.finish;
      m = new THREE.MeshStandardMaterial({
        color: c, flatShading: true,
        roughness: f === 'gloss' ? 0.22 : f === 'pearl' ? 0.3 : f === 'matte' ? 0.9 : 0.6,
        metalness: f === 'gloss' ? 0.3 : f === 'pearl' ? 0.25 : 0.05,
      });
      mats.set(k, m);
    }
    return m;
  };
  const cut = lo + H * 0.62;
  for (const p of painted) {
    const cy = (p.box.min.y + p.box.max.y) / 2, cz = (p.box.min.z + p.box.max.z) / 2;
    let c = job.body;
    if (job.upper !== undefined && painted.length > 1 && cy >= cut) c = job.upper;
    else if (job.bonnet !== undefined && cz > mid + len * 0.16 && cy < cut) c = job.bonnet;
    p.mesh.material = finish(c);
  }

  const r = mulberry32(hashString(`${job.id}|${def.id}`));
  // ---- camouflage: patches proud of the panels' tops and sides ----
  if (job.camo) {
    for (const p of painted) {
      const b = p.box, w = b.max.x - b.min.x, d = b.max.z - b.min.z, h = b.max.y - b.min.y;
      const n = Math.max(1, Math.min(4, Math.round((w * d) / 0.03)));
      for (let k = 0; k < n; k++) {
        const c = job.camo[Math.floor(r() * job.camo.length)];
        const pw = w * (0.25 + r() * 0.3), pd = d * (0.2 + r() * 0.3);
        kit.box(pw, 0.006, pd, c, b.min.x + pw / 2 + r() * (w - pw), b.max.y + 0.003, b.min.z + pd / 2 + r() * (d - pd));
      }
      if (h > 0.06) for (const sx of [-1, 1]) {
        const c = job.camo[Math.floor(r() * job.camo.length)];
        const ph = h * (0.3 + r() * 0.4), pd = d * (0.2 + r() * 0.4);
        kit.box(0.006, ph, pd, c, sx > 0 ? b.max.x + 0.003 : b.min.x - 0.003, b.min.y + ph / 2 + r() * (h - ph), b.min.z + pd / 2 + r() * (d - pd));
      }
    }
  }

  // ---- along the sides ----
  const z0 = tail + len * 0.1, z1 = nose - len * 0.1;
  const strip = (y: number, h: number, colours: number[]): void => {
    if (colours.length === 1) {
      // follow the body: a strip a segment at a time, each at the side's own reach there
      const n = 8;
      for (let k = 0; k < n; k++) {
        const za = z0 + ((z1 - z0) * k) / n, zb = z0 + ((z1 - z0) * (k + 1)) / n, zc = (za + zb) / 2;
        const x = side(y, zc);
        if (x <= 0) continue;
        for (const sx of [-1, 1]) kit.box(0.006, h, zb - za + 0.002, colours[0], sx * (x + 0.004), y, zc);
      }
      return;
    }
    const sq = Math.max(0.04, h);
    const n = Math.max(2, Math.floor((z1 - z0) / sq));
    for (let k = 0; k < n; k++) {
      const zc = z0 + (k + 0.5) * ((z1 - z0) / n);
      const x = side(y, zc);
      if (x <= 0) continue;
      for (const sx of [-1, 1]) kit.box(0.006, h, (z1 - z0) / n + 0.001, colours[k % colours.length], sx * (x + 0.004), y, zc);
    }
  };
  if (job.band) strip(lo + H * job.band.at, Math.min(0.08, H * job.band.h), job.band.colours);
  if (job.pin !== undefined) strip(lo + H * 0.56, 0.012, [job.pin]);
  if (job.racing !== undefined && !water) {
    const n = 10;
    for (let k = 0; k < n; k++) {
      const za = tail + (len * k) / n, zb = tail + (len * (k + 1)) / n, zc = (za + zb) / 2;
      const y = top(0, zc);
      if (y < lo + H * 0.5) continue;
      kit.box(Math.min(0.08, wid * 0.16), 0.006, zb - za + 0.002, job.racing, 0, y + 0.004, zc);
    }
  }
  // the crest on the doors, and a word along the sides
  if (job.roundel && !air) {
    const s = Math.min(0.15, H * 0.5, len * 0.18);
    const y = lo + H * (water ? 0.62 : 0.5), z = mid + len * 0.06;
    const x = side(y, z);
    if (x > 0) for (const sx of [-1, 1]) kit.decal(crestTexture(job.roundel), s, s, sx * (x + 0.009), y, z, sx);
  } else if (job.roundel && air) {
    const s = Math.min(0.2, H * 0.4);
    const y = lo + H * 0.55, z = mid;
    const x = side(y, z);
    if (x > 0) for (const sx of [-1, 1]) kit.decal(crestTexture(job.roundel), s, s, sx * (x + 0.009), y, z, sx);
  }
  // a picture the length of the sides (a skyline, a map's contours): laid a stretch at a time, each at the side's
  // own reach there, so it follows a body that narrows to the nose rather than standing off it
  const along = (tex: THREE.Texture, y0: number, h: number): void => {
    const n = 8, za = tail + len * 0.08, zb = nose - len * 0.08, Z = zb - za;
    for (let k = 0; k < n; k++) {
      const z0 = za + (Z * k) / n, z1 = za + (Z * (k + 1)) / n, zc = (z0 + z1) / 2;
      const x = Math.max(side(y0 + h * 0.25, zc), side(y0 + h * 0.6, zc));
      if (x <= 0) continue;
      for (const sx of [-1, 1]) {
        // read left to right from either side: u runs nose-ward on the left, tail-ward on the right
        const u0 = sx > 0 ? (zb - z1) / Z : (z0 - za) / Z;
        kit.decal(tex, z1 - z0 + 0.001, h, sx * (x + 0.008), y0 + h / 2, zc, sx, u0, u0 + (z1 - z0) / Z);
      }
    }
  };
  if (job.contours !== undefined) along(contourTexture(job.contours), lo + H * 0.08, Math.min(H * 0.3, 0.12));
  if (job.skyline) along(skylineTexture(job.skyline.fg, job.skyline.lit, hashString(def.id)), lo + H * job.skyline.at, H * job.skyline.h);
  if (job.word) {
    const h = Math.min(0.07, H * 0.26), w = Math.min(len * 0.42, h * 4);
    const y = lo + H * 0.28, z = mid - len * 0.16;
    const x = side(y, z);
    if (x > 0) for (const sx of [-1, 1]) kit.decal(wordTexture(job.word.text, job.word.bg, job.word.fg), w, h, sx * (x + 0.009), y, z, sx);
  }

  // ---- bolt-ons ----
  const roofZ = mid - len * 0.05, roof = top(0, roofZ);
  for (const b of job.bolts) {
    switch (b) {
      case 'lightbar': {
        const w = Math.min(0.3, wid * 0.6);
        kit.box(w, 0.03, 0.06, DARK, 0, roof + 0.015, roofZ);
        kit.box(w * 0.46, 0.035, 0.05, 0xd2342a, -w * 0.25, roof + 0.045, roofZ, 0.9);
        kit.box(w * 0.46, 0.035, 0.05, 0x2f6fe0, w * 0.25, roof + 0.045, roofZ, 0.9);
        break;
      }
      case 'amber': case 'beacon': {
        const z = roofZ + len * 0.12;
        kit.cyl(0.025, 0.04, b === 'amber' ? 0xf2a93b : 0xd2342a, 0, top(0, z) + 0.02, z, 'y', 0.9);
        break;
      }
      case 'redlight':
        kit.ball(0.03, 0xff3b30, 0, all.min.y - 0.02, mid, 0.9);
        kit.ball(0.025, 0xff3b30, 0, top(0, mid) + 0.025, mid, 0.9);
        break;
      case 'pushbar':
        if (def.kind === 'land') {
          const y = Math.max(0.18, all.min.y + 0.12);
          kit.box(wid * 0.7, 0.12, 0.03, DARK, 0, y, nose + 0.025);
        }
        break;
      case 'flags':
        for (const sx of [-1, 1]) {
          const x = sx * wid * 0.38, z = nose - len * 0.08, y = top(x, z);
          kit.box(0.008, 0.12, 0.008, CHROME, x, y + 0.06, z);
          kit.box(0.004, 0.05, 0.08, sx < 0 ? 0x2f4d7a : 0xd9b34a, x, y + 0.095, z - 0.04);
        }
        break;
      case 'ladder':
        if (def.kind === 'land') for (const sx of [-1, 1]) kit.box(0.018, 0.018, len * 0.55, CHROME, sx * wid * 0.22, roof + 0.03, roofZ - len * 0.05);
        if (def.kind === 'land') for (let k = 0; k < 5; k++) kit.box(wid * 0.44, 0.012, 0.012, CHROME, 0, roof + 0.03, roofZ - len * 0.3 + k * len * 0.12);
        break;
      case 'dish': {
        const z = roofZ - len * 0.12, y = top(0, z);
        kit.box(0.02, 0.06, 0.02, DARK, 0, y + 0.03, z);
        const d = kit.cyl(0.08, 0.012, WHITE, 0, y + 0.08, z, 'z');
        d.rotation.x = -0.6;
        break;
      }
      case 'mast': {
        // the telescoping mast, down and lying along the roof
        const z = roofZ, y = top(wid * 0.25, z);
        kit.cyl(0.012, len * 0.6, CHROME, wid * 0.25, y + 0.02, z, 'z');
        break;
      }
      case 'aerial': {
        const z = tail + len * 0.18;
        kit.box(0.006, 0.22, 0.006, DARK, wid * 0.3, top(wid * 0.3, z) + 0.11, z);
        break;
      }
      case 'searchlight': {
        const z = nose - len * 0.3, y = top(-wid * 0.25, z);
        kit.cyl(0.03, 0.05, DARK, -wid * 0.25, y + 0.03, z, 'z');
        kit.cyl(0.024, 0.006, 0xfff2b0, -wid * 0.25, y + 0.03, z + 0.028, 'z', 0.5);
        break;
      }
      case 'camera': {
        const z = tail + len * 0.18, y = top(0, z);
        kit.box(0.07, 0.05, 0.06, DARK, 0, y + 0.025, z);
        kit.cyl(0.018, 0.07, DARK, 0, y + 0.03, z + 0.06, 'z');
        break;
      }
      case 'plate':
        if (def.kind === 'land') {
          kit.box(0.09, 0.03, 0.006, WHITE, 0, Math.max(0.14, all.min.y + 0.1), tail - 0.004);
          kit.box(0.09, 0.03, 0.006, WHITE, 0, Math.max(0.14, all.min.y + 0.1), nose + 0.004);
        }
        break;
      case 'whitewalls':
        for (const w of wheels) {
          const g = new THREE.Box3().setFromObject(w);
          const rad = (g.max.y - g.min.y) / 2;
          if (rad <= 0) continue;
          const c = g.getCenter(new THREE.Vector3());
          const sx = c.x >= 0 ? 1 : -1;
          kit.cyl(rad * 0.72, 0.004, WHITE, sx > 0 ? g.max.x + 0.002 : g.min.x - 0.002, c.y, c.z, 'x');
        }
        break;
      case 'nets': {
        const z = tail + len * 0.16, y = top(0, z);
        kit.box(wid * 0.55, 0.05, len * 0.14, 0x3f5a3a, 0, y + 0.025, z);
        for (const sx of [-1, 1]) kit.ball(0.03, 0xf2832e, sx * wid * 0.32, y + 0.04, z);
        break;
      }
      case 'roofrack': {
        // rails and bars on the roof, a spare wheel lying on it and a crate (a car's: a boat's roof is a mast)
        if (def.kind !== 'land') break;
        const w = Math.min(0.42, wid * 0.62), d = Math.min(0.46, len * 0.4), z = roofZ - len * 0.04, y = top(0, z);
        for (const sx of [-1, 1]) kit.box(0.025, 0.025, d, DARK, sx * w * 0.5, y + 0.03, z);
        for (const dz of [-0.4, 0, 0.4]) kit.box(w, 0.018, 0.02, DARK, 0, y + 0.045, z + dz * d);
        const tr = Math.min(0.11, w * 0.28);
        kit.cyl(tr, 0.05, DARK, -w * 0.18, y + 0.08, z - d * 0.12, 'y');
        kit.cyl(tr * 0.45, 0.052, 0xc9b58a, -w * 0.18, y + 0.08, z - d * 0.12, 'y');
        kit.box(w * 0.34, 0.08, d * 0.36, 0x6b5b3a, w * 0.2, y + 0.095, z + d * 0.15);
        break;
      }
      case 'jerrycans': {
        // two cans, olive and red: on the tailgate of a car, on the after deck of a boat
        if (air) break;
        const cw = Math.min(0.09, wid * 0.16), ch = Math.min(0.13, H * 0.45), cd = cw * 0.55;
        for (const [k, c] of [[-1, 0x55663a], [1, 0xb83a2a]] as [number, number][]) {
          if (def.kind === 'land') kit.box(cw, ch, cd, c, k * cw * 0.65, lo + H * 0.42, tail - cd / 2 - 0.004);
          else { const z = tail + len * 0.1; kit.box(cw, ch, cd, c, k * cw * 0.65, top(k * cw * 0.65, z) + ch / 2, z); }
        }
        break;
      }
      case 'snorkel': {
        // up the side of the cab to just over its roof, as the workshop's tall suspension fits one
        if (def.kind !== 'land') break;
        const y0 = Math.max(0.25, all.min.y + 0.2), x = all.max.x + 0.015, z = nose - len * 0.3;
        const y1 = Math.min(top(x - 0.05, z) + 0.1, y0 + 0.55);
        if (y1 <= y0) break;
        kit.cyl(0.022, y1 - y0, DARK, x, (y0 + y1) / 2, z, 'y');
        kit.box(0.06, 0.05, 0.07, DARK, x, y1, z + 0.02);
        break;
      }
      case 'rust':
        for (let k = 0; k < 4; k++) {
          const z = z0 + r() * (z1 - z0), y = lo + H * (0.25 + r() * 0.3);
          const x = side(y, z);
          if (x > 0) kit.box(0.006, 0.05 + r() * 0.05, 0.015, 0x8a4a2a, (k % 2 ? 1 : -1) * (x + 0.005), y, z);
        }
        break;
      default:
        break;
    }
  }
}

/** Boxes, rods, balls and pictures added to a body, each colour one material. */
class JobKit {
  private mats = new Map<string, THREE.MeshStandardMaterial>();
  constructor(private body: THREE.Group) {}
  private mat(c: number, glow = 0): THREE.MeshStandardMaterial {
    const key = `${c}|${glow}`;
    let m = this.mats.get(key);
    if (!m) {
      m = new THREE.MeshStandardMaterial({ color: c, roughness: c === CHROME ? 0.35 : 0.6, metalness: c === CHROME ? 0.5 : 0.05, emissive: glow ? c : 0, emissiveIntensity: glow, flatShading: true });
      this.mats.set(key, m);
    }
    return m;
  }
  private put(geo: THREE.BufferGeometry, mat: THREE.Material, x: number, y: number, z: number): THREE.Mesh {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(x, y, z);
    m.castShadow = false;
    this.body.add(m);
    return m;
  }
  box(w: number, h: number, d: number, c: number, x: number, y: number, z: number, glow = 0): THREE.Mesh {
    return this.put(new THREE.BoxGeometry(w, h, d), this.mat(c, glow), x, y, z);
  }
  cyl(r: number, h: number, c: number, x: number, y: number, z: number, axis: 'x' | 'y' | 'z', glow = 0): THREE.Mesh {
    const g = new THREE.CylinderGeometry(r, r, h, 12);
    if (axis === 'x') g.rotateZ(-Math.PI / 2);
    else if (axis === 'z') g.rotateX(Math.PI / 2);
    return this.put(g, this.mat(c, glow), x, y, z);
  }
  ball(r: number, c: number, x: number, y: number, z: number, glow = 0): THREE.Mesh {
    return this.put(new THREE.IcosahedronGeometry(r, 1), this.mat(c, glow), x, y, z);
  }
  /** A picture on a side, facing out along x (sx: +1 the right side, −1 the left). */
  decal(tex: THREE.Texture, w: number, h: number, x: number, y: number, z: number, sx: number, u0 = 0, u1 = 1): THREE.Mesh {
    const g = new THREE.PlaneGeometry(w, h);
    if (u0 !== 0 || u1 !== 1) {
      // a stretch of a longer picture
      const uv = g.getAttribute('uv');
      for (let i = 0; i < uv.count; i++) uv.setX(i, u0 + uv.getX(i) * (u1 - u0));
    }
    g.rotateY(sx > 0 ? Math.PI / 2 : -Math.PI / 2);
    return this.put(g, decalMat(tex), x, y, z);
  }
}

// ---- the pictures, painted once each and shared ----

const textures = new Map<string, THREE.CanvasTexture>();
const decalMats = new Map<THREE.Texture, THREE.MeshStandardMaterial>();
const hex = (c: number): string => `#${c.toString(16).padStart(6, '0')}`;

function decalMat(t: THREE.Texture): THREE.MeshStandardMaterial {
  let m = decalMats.get(t);
  if (!m) { m = new THREE.MeshStandardMaterial({ map: t, transparent: false, alphaTest: 0.5, roughness: 0.6, metalness: 0, polygonOffset: true, polygonOffsetFactor: -2 }); decalMats.set(t, m); }
  return m;
}

function canvasTex(key: string, w: number, h: number, draw: (g: CanvasRenderingContext2D) => void): THREE.CanvasTexture {
  let t = textures.get(key);
  if (t) return t;
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const g = c.getContext('2d')!;
  draw(g);
  t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  textures.set(key, t);
  return t;
}

/** A disc with a glyph on it: a faction's crest on a door. */
function roundelTexture(glyph: string, bg: number, fg: number): THREE.CanvasTexture {
  return canvasTex(`r|${glyph}|${bg}|${fg}`, 64, 64, (g) => {
    g.fillStyle = hex(fg);
    g.beginPath(); g.arc(32, 32, 31, 0, Math.PI * 2); g.fill();
    g.fillStyle = hex(bg);
    g.beginPath(); g.arc(32, 32, 27, 0, Math.PI * 2); g.fill();
    g.fillStyle = hex(fg);
    g.font = 'bold 34px "Segoe UI Symbol", "Segoe UI", sans-serif';
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText(glyph, 32, 34);
  });
}

/** A crest: a glyph on a disc, or a compass rose. */
function crestTexture(r: { glyph: string; bg: number; fg: number; rose?: boolean }): THREE.CanvasTexture {
  if (!r.rose) return roundelTexture(r.glyph, r.bg, r.fg);
  return canvasTex(`rose|${r.bg}|${r.fg}`, 128, 128, (g) => {
    g.fillStyle = hex(r.fg);
    g.beginPath(); g.arc(64, 64, 62, 0, Math.PI * 2); g.fill();
    g.fillStyle = hex(r.bg);
    g.beginPath(); g.arc(64, 64, 56, 0, Math.PI * 2); g.fill();
    g.strokeStyle = hex(r.fg); g.lineWidth = 2;
    g.beginPath(); g.arc(64, 64, 44, 0, Math.PI * 2); g.stroke();
    // eight points, the four great ones long, each half dark and half light
    for (let k = 0; k < 8; k++) {
      const a = (k * Math.PI) / 4 - Math.PI / 2, long = k % 2 === 0, R = long ? 50 : 30, w = long ? 9 : 7;
      const tip = [64 + Math.cos(a) * R, 64 + Math.sin(a) * R];
      const l = [64 + Math.cos(a - Math.PI / 2) * w, 64 + Math.sin(a - Math.PI / 2) * w];
      const rr = [64 + Math.cos(a + Math.PI / 2) * w, 64 + Math.sin(a + Math.PI / 2) * w];
      g.fillStyle = hex(r.fg);
      g.beginPath(); g.moveTo(64, 64); g.lineTo(tip[0], tip[1]); g.lineTo(l[0], l[1]); g.closePath(); g.fill();
      g.fillStyle = k === 0 ? '#c8402a' : '#9a8a66';
      g.beginPath(); g.moveTo(64, 64); g.lineTo(tip[0], tip[1]); g.lineTo(rr[0], rr[1]); g.closePath(); g.fill();
    }
    g.fillStyle = hex(r.fg);
    g.font = 'bold 18px "Segoe UI", sans-serif';
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText(r.glyph, 64, 14);
  });
}

/** A city skyline in silhouette: towers, a spire, a dome, stepped tops and masts, with lit windows. Cut out (alphaTest). */
function skylineTexture(fg: number, lit: number, seed: number): THREE.CanvasTexture {
  return canvasTex(`sky|${fg}|${lit}|${seed % 4}`, 1024, 128, (g) => {
    const r = mulberry32((seed % 4) + 17);
    g.clearRect(0, 0, 1024, 128);
    g.fillStyle = hex(fg);
    const windows: [number, number, number, number][] = [];
    let x = 0;
    // a low run of roofs along the bottom, so the line never breaks
    g.fillRect(0, 104, 1024, 24);
    while (x < 1024) {
      const w = 26 + Math.floor(r() * 48), h = 30 + Math.floor(r() * 70), top = 128 - h, kind = r();
      g.fillRect(x, top, w, h);
      if (kind < 0.18) {
        // a spire
        g.beginPath(); g.moveTo(x + w * 0.2, top); g.lineTo(x + w / 2, Math.max(2, top - 26)); g.lineTo(x + w * 0.8, top); g.fill();
      } else if (kind < 0.3) {
        // a dome
        g.beginPath(); g.arc(x + w / 2, top, w * 0.42, Math.PI, 0); g.fill();
      } else if (kind < 0.5) {
        // stepped back
        g.fillRect(x + w * 0.18, top - 10, w * 0.64, 10);
        g.fillRect(x + w * 0.34, top - 18, w * 0.32, 8);
      } else if (kind < 0.62) {
        // a mast
        g.fillRect(x + w / 2 - 1, Math.max(2, top - 22), 3, 22);
      }
      for (let wy = top + 6; wy < 118; wy += 9) for (let wx = x + 4; wx < x + w - 6; wx += 8) if (r() < 0.35) windows.push([wx, wy, 4, 5]);
      x += w + Math.floor(r() * 6);
    }
    g.fillStyle = hex(lit);
    for (const [a, b2, c, d] of windows) g.fillRect(a, b2, c, d);
  });
}

/** A survey map's contour lines and a dashed route, on nothing (cut out). */
function contourTexture(c: number): THREE.CanvasTexture {
  return canvasTex(`contour|${c}`, 512, 64, (g) => {
    g.clearRect(0, 0, 512, 64);
    g.strokeStyle = hex(c);
    g.lineWidth = 3;
    for (let k = 0; k < 4; k++) {
      g.beginPath();
      for (let x = 0; x <= 512; x += 8) {
        const y = 10 + k * 13 + Math.sin(x * 0.021 + k * 1.3) * 5 + Math.sin(x * 0.057 + k) * 2.5;
        if (x === 0) g.moveTo(x, y); else g.lineTo(x, y);
      }
      g.stroke();
    }
    g.strokeStyle = '#b83a2a';
    g.lineWidth = 4;
    g.setLineDash([10, 8]);
    g.beginPath();
    for (let x = 0; x <= 512; x += 8) { const y = 34 + Math.sin(x * 0.013 + 2) * 18; if (x === 0) g.moveTo(x, y); else g.lineTo(x, y); }
    g.stroke();
    g.setLineDash([]);
  });
}

/** A word in a box: POLICE, PRESS. */
function wordTexture(text: string, bg: number, fg: number): THREE.CanvasTexture {
  return canvasTex(`w|${text}|${bg}|${fg}`, 128, 32, (g) => {
    g.fillStyle = hex(bg);
    g.fillRect(0, 0, 128, 32);
    g.fillStyle = hex(fg);
    g.font = 'bold 24px "Segoe UI", sans-serif';
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText(text, 64, 17);
  });
}
