import * as THREE from 'three';
import { buildVehicleMesh, disposeVehicleMesh, poseVehicleMesh, type VehicleMesh } from '../render/vehicleMeshes';
import { DIRS, N, SEA, STEP, heightAt, idx, inB, type World } from '../world/tiles';
import { NEXT_WORLD } from '../world/nextWorld';
import { VEHICLES, type Controls, type VehicleDef, type VehicleState } from './vehicles';
import { offshore } from './missions/templates';
import { rivalById } from './missions/rivals';
import { story } from './story';

/**
 * The story chains' props (docs/storychains.html, 0.7.0): what the world shows between missions besides the rocket,
 * the dish and the submarine. Each is a vehicle's own model standing still, put down while its place is in memory
 * and taken away when the story moves past it:
 *
 * - the Army's Tortoises parked at the launch pad's corners, from Stargazers' Convoy on;
 * - the Bastion moored off the fishing harbour, from Still Waters' Dry Dock until Sea Trials;
 * - Greywater's grey vans parked at the harbour after dark, from the wreck race until the raid.
 */

interface StorySceneHost {
  worldAt(cx: number, cz: number): World | null;
  /** How dark it is, 0 day to 1 night. */
  night(): number;
}

/** A prop's pose, in the shape poseVehicleMesh reads. */
class Still implements VehicleState {
  x = 0; y = 0; z = 0; heading = 0; v = 0;
  pitch = 0; roll = 0; bob = 0; lean = 0; wheelSpin = 0; steerVis = 0;
  power = 0; blocked = 0; trailerHeading = 0; sailAngle = 0; surfaceY = NaN;
  step(_w: World, _c: Controls, _dt: number): void { /* parked */ }
  status(): string { return ''; }
}

interface Want { key: string; def: VehicleDef; x: number; y: number; z: number; heading: number; w: World; float?: boolean; night?: boolean }
interface Prop { want: Want; mesh: VehicleMesh; st: Still }

const def = (id: string) => VEHICLES.find((d) => d.id === id)!;
/** Steps after which each prop shows, and (for the ones that go) the step it goes at. */
const TANKS_FROM = 12, BASTION = [10, 20], VANS = [6, 13];

export class StoryScene {
  readonly group = new THREE.Group();
  private props = new Map<string, Prop>();
  private t = 0;
  /** What was worked out for the anchors and steps last time, so it is only worked out again when they change. */
  private sig = '';
  private wants: Want[] = [];

  constructor(scene: THREE.Scene, private host: StorySceneHost) {
    scene.add(this.group);
  }

  update(dt: number): void {
    if (!NEXT_WORLD) return;
    this.t += dt;
    const pad = story.anchor('moon:pad'), dock = story.anchor('deep:dock');
    const sig = `${story.steps.moon}|${story.steps.deep}|${pad ? `${pad.cx},${pad.cz},${pad.bx},${pad.bz}` : ''}|${dock ? `${dock.x},${dock.z}` : ''}`
      + `|${pad && this.host.worldAt(pad.cx, pad.cz) ? 1 : 0}${dock && this.host.worldAt(dock.cx, dock.cz) ? 1 : 0}`;
    if (sig !== this.sig) { this.sig = sig; this.wants = this.wanted(); }
    const night = this.host.night() > 0.5;
    const keep = new Set<string>();
    for (const w of this.wants) {
      if (w.night && !night) continue;
      keep.add(w.key);
      let p = this.props.get(w.key);
      if (!p) {
        const mesh = buildVehicleMesh(w.def);
        this.group.add(mesh.holder);
        p = { want: w, mesh, st: new Still() };
        this.props.set(w.key, p);
      }
      const st = p.st;
      st.x = w.x; st.y = w.y; st.z = w.z; st.heading = w.heading;
      // a ship at anchor rides the swell a little
      if (w.float) { st.bob = Math.sin(this.t * 0.6) * 0.03; st.roll = Math.sin(this.t * 0.45) * 0.012; }
      poseVehicleMesh(p.mesh, st, w.def, w.w);
    }
    for (const [k, p] of this.props) if (!keep.has(k)) this.drop(k, p);
  }

  private drop(k: string, p: Prop): void {
    this.group.remove(p.mesh.holder);
    disposeVehicleMesh(p.mesh);
    this.props.delete(k);
  }

  /** Where every prop the story calls for stands now, for the places in memory. */
  private wanted(): Want[] {
    const out: Want[] = [];
    const pad = story.anchor('moon:pad'), dock = story.anchor('deep:dock');
    // the Tortoises at the pad's corners, noses out
    const pw = pad && pad.bx >= 0 ? this.host.worldAt(pad.cx, pad.cz) : null;
    const b = pw?.allBuildings.find((q) => q.x === pad!.bx && q.z === pad!.bz && !q.gone);
    if (pw && b && story.steps.moon >= TANKS_FROM) {
      const tank = def('tank');
      const corners: [number, number][] = [[b.x + 1.2, b.z + 1.2], [b.x + b.w - 1.2, b.z + 1.2], [b.x + 1.2, b.z + b.d - 1.2], [b.x + b.w - 1.2, b.z + b.d - 1.2]];
      corners.forEach(([x, z], k) => {
        const mx = b.x + b.w / 2, mz = b.z + b.d / 2;
        out.push({ key: `tank${k}`, def: tank, w: pw, x: pw.ox + x, z: pw.oz + z, y: heightAt(pw, x, z), heading: Math.atan2(x - mx, z - mz) });
      });
    }
    const dw = dock ? this.host.worldAt(dock.cx, dock.cz) : null;
    const port = dw && dock ? dw.ports.find((q) => Math.abs(dw.ox + q.x - dock.x) < 2 && Math.abs(dw.oz + q.z - dock.z) < 2) : null;
    if (dw && dock && port) {
      // the Bastion at anchor off the harbour, side on to the shore
      const s = story.steps.deep;
      if (s >= BASTION[0] && s < BASTION[1]) {
        const o = offshore(dw, port.root, port.dir, 3, 40, 80);
        if (o) {
          const [dx, dz] = DIRS[port.dir];
          out.push({ key: 'bastion', def: def('carrier'), w: dw, x: dw.ox + o.lx, z: dw.oz + o.lz, y: SEA * STEP, heading: Math.atan2(dz, -dx), float: true });
        }
      }
      // Greywater's vans, parked on the harbour road after dark
      if (s >= VANS[0] && s < VANS[1]) {
        const grey = { ...def('mule'), color: rivalById('greywater').colour } as VehicleDef;
        this.vanSpots(dw, dock.x - dw.ox, dock.z - dw.oz).forEach((p, k) => {
          out.push({ key: `van${k}`, def: grey, w: dw, x: dw.ox + p.x, z: dw.oz + p.z, y: heightAt(dw, p.x, p.z), heading: Math.atan2(dock.x - dw.ox - p.x, dock.z - dw.oz - p.z), night: true });
        });
      }
    }
    return out;
  }

  /** Two road tiles a few tiles from the harbour (clear of its entry) and a few apart, nearest first. */
  private vanSpots(w: World, lx: number, lz: number): { x: number; z: number }[] {
    const out: { x: number; z: number }[] = [];
    for (let r = 4; r <= 12 && out.length < 2; r++) {
      for (let dz = -r; dz <= r && out.length < 2; dz++) for (let dx = -r; dx <= r && out.length < 2; dx++) {
        if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
        const x = Math.floor(lx) + dx, z = Math.floor(lz) + dz;
        if (!inB(x, z) || x < 1 || z < 1 || x >= N - 1 || z >= N - 1) continue;
        const i = idx(x, z);
        if (!w.road[i] || w.blocked[i] || w.deckAxis[i] || w.water[i] >= 0) continue;
        if (out.some((q) => Math.hypot(q.x - x - 0.5, q.z - z - 0.5) < 3)) continue;
        out.push({ x: x + 0.5, z: z + 0.5 });
      }
    }
    return out;
  }

  /** What stands where, for the console. */
  list(): string[] { return [...this.props.values()].map((p) => `${p.want.key} ${p.want.def.name} at ${p.want.x.toFixed(0)},${p.want.z.toFixed(0)}`); }

  clear(): void {
    for (const [k, p] of this.props) this.drop(k, p);
    this.sig = '';
    this.wants = [];
  }
}
