/**
 * The interstate inside a county (docs/interstates.html, the user, 9 Nov 2026; 0.8.0 behind NEXT_080).
 *
 * world/interstate.ts says which routes cross a county and on which border tiles. Here each is planned, the ground
 * shaped for it and the road laid, before any town is built, so the towns and the county roads grow round it:
 *
 *  1. the line: an A* over a coarse lattice of long straights, from the border tile it enters by to the one it
 *     leaves by (or, at a terminus, to the edge of the town it ends at), dear to turn, kept off town squares,
 *     works, airfields and buildings, and kept straight wherever it has to cross water, a railway or a road;
 *  2. the profile: the ground along it smoothed at the road's grade (a step in two tiles), level at its border stubs
 *     so both counties meet on one height, flat round every corner, and raised over what it crosses: water, a
 *     railway, the county roads' underpasses and its own interchanges. Where it would stand well clear of the
 *     ground it is a viaduct rather than an embankment;
 *  3. decks over every stretch that isn't on the ground, and the ground under the rest graded to it, eased back to
 *     its own lie over a few tiles either side;
 *  4. the road, limited-access (Road.limited): no generated road may meet it on the level (world/roads.ts searchRoute),
 *     only pass under one of its decks square on;
 *  5. one or two interchanges a county (the user's rule): a diamond, four slip roads off and on by the taper the
 *     builder's ramps use (rampTaper), round a county road that passes under the interstate, joined to the town it
 *     serves once the towns are built (finishInterstates).
 *
 * Nothing here draws from the generator's random stream: every choice is from the ground and the hashes, so a county
 * with no route is generated exactly as before.
 */
import {
  N, STEP, Biome, Feature, Flag, RailBit, RoadType, World, DIRS, idx, inB, maxCorner, tileMean, waterDepth, type Bridge, type Road,
} from './tiles';
import { deckHeightAt, deckTiles, layRoad, nodeTiles, rebuildRoadTables } from './roads';
import { roadLine } from './diagonals';
import { linkRoadEnds } from './links';
import { exitNumber, interstateAt, interstateLines, routeLabel, type InterstateLine } from './interstate';
import type { TownPlan } from './towns';

// ---------------- tuning ----------------

/** Nodes of dead-straight, level road in from a border, so both counties meet head-on at one height. */
const STUB = 10;
/** Lines in from a border held at the height both counties share; past them the road may climb at its grade. */
const LEVEL_IN = 3;
/** Lattice spacing of the line search, in tiles: every straight is a whole number of these, give or take its ends. */
const LATTICE = 6;
/** What a turn costs the line search, in tiles of road: an interstate bends rarely. */
const TURN = 70;
/** The widest and narrowest radius of an interstate's bends, in tiles of its centre line (the user, 9 Nov 2026: long sweeping curves). */
const BEND_MAX = 14, BEND_MIN = 4;
/** Nodes either side of a 45° join its arc and level ground reach (the arc's radius is at most 16: 0.41 × 16, and a staircase's nodes are √½ apart). */
const DIAG_REACH = 12;
/** Nodes either side of a 45° join held level. */
const DIAG_LEVEL = 3;
/** Tiles round a town's square the interstate may not enter, and over which it pays to come nearer. */
const TOWN_KEEP = 6, TOWN_NEAR = 22;
/** Tiles round a turn kept clear of anything it would have to bridge, so every deck is straight. */
const TURN_CLEAR = 3;
/** Steps of fill past which a stretch of interstate stands on a viaduct rather than an embankment. */
const FILL_MAX = 3;
/** Tiles over which the ground either side of the interstate is eased back to its own lie. */
const EASE = 5;
/** Steps of air under a deck over a railway, a road or an underpass (UNDER_CLEARANCE is 2: this keeps it clear). */
const UNDER = 3;
/** Path tiles between one underpass and the next, roughly. */
const UNDERPASS_EVERY = 46;
/** An underpass's strip of graded ground across the interstate, tiles each way from its middle. */
const STRIP_HALF = 9;
/** An interchange's county road reaches this far each way from the interstate's middle, and its ramps join it this far out. */
const ROAD_HALF = 12, RAMP_MEET = 6;
/** Path tiles from an interchange's underpass to where its ramps leave and join the carriageways. */
const RAMP_REACH = 15;
/** The short slip roads of an exit squeezed onto a shorter straight. */
const RAMP_SHORT = 11;
/** The shortest, for a county whose line leaves it no longer straight. */
const RAMP_LEAST = 8;
/** Path tiles between a county's two interchanges, at the least. */
const EXITS_APART = 80;

const DX = [1, 0, -1, 0], DZ = [0, 1, 0, -1];

// ---------------- what the plan holds ----------------

/** An interchange as planned: where on the path its county road passes under, and the town it serves. */
interface ExitPlan { k: number; town: number; number: number; /** Path tiles from the county road to where its slip roads leave and join. */ reach: number }

/** One route's plan through the county. */
interface RoutePlan {
  line: InterstateLine;
  /** Tile nodes, border (or terminus) to border. */
  nodes: number[];
  /** Per node, the DIRS direction of travel (onward from it; the last copies the one before). */
  dirs: number[];
  /** Height in steps of each vertex line, line e lying between nodes e and e+1, offset by 2 (lines -2 … n). */
  q: Int16Array;
  /** Nodes on a deck rather than on graded ground. */
  air: Uint8Array;
  /** Path positions of underpasses (the county road's tile), with the ground under each. */
  unders: { k: number; g: number }[];
  exits: ExitPlan[];
  bridges: Bridge[];
  /** At a terminus, the town the route ends at and the node index of its end (always the last). */
  endTown: number;
  /** Tiles under an underpass's deck, graded to its strip's level later. */
  stripUnder: Set<number>;
  /** Plain ground under a deck, held at or below this many steps. */
  cuts: { tile: number; cap: number }[];
  /** Every tile under one of its decks. */
  deckTiles: Set<number>;
  /** The borders it crosses, in its order: the side and the tile along it. */
  ends: { d: number; at: number }[];
  /** Its sweeping bends: corner node → radius of the centre line. */
  bends: Map<number, number>;
  /** Per node, inside a bend's reach (its arc and the straight it trims): no deck, crossing or exit there. */
  bendZone: Uint8Array;
  /** Tiles the bends' arcs cross outside the road's own blocks: road all the same (graded level, driven on). */
  arcTiles: Set<number>;
  /** Its corners, by node: `sharp` 1 for 45°, 2 for a right angle; `diag` when a diagonal stretch meets there. */
  turns: { k: number; sharp: number; diag: boolean }[];
  /** Per node, on a diagonal's staircase. */
  diag: Uint8Array;
  /** Its centre line as drawn (world/diagonals.ts roadLine): tile middles, each diagonal one straight segment. */
  centre: [number, number][];
  /** Where it meets the other route through the county: that route's label, and its exit is this one's. */
  junction?: { to: string; at: number };
}

/** What a county's interstates came to, kept on the world for the maps, the cards and the gates. */
export interface InterstateInfo {
  key: string; number: number; name: string; label: string;
  /** Index in w.roads of the interstate itself. */
  road: number;
  sides: number[];
  terminus: boolean;
  /** `to`: at a junction, the other route this exit leads on to (by its link road). */
  exits: { number: number; town: string; x: number; z: number; to?: string }[];
  decks: number;
  /** True when this county's stretch could not be laid (the gate counts these). */
  failed?: string;
  /**
   * Its signs (render/interstateSigns.ts): an exit board before each off-ramp ('exit', reading its exit's number and
   * town), a route shield where each on-ramp leaves the county road ('shield'), and the route's board where it comes
   * into the county ('route'). Where it stands (tile units), and the way its face looks (a unit vector).
   */
  signs: InterstateSign[];
}

export interface InterstateSign { kind: 'exit' | 'shield' | 'route'; x: number; z: number; fx: number; fz: number; exit?: number }

export interface InterstateCtx {
  w: World;
  seedHash: number;
  towns: TownPlan[];
  /** The stage-three padded elevation and land, which a neighbour computes identically (as the railway's), and their width. */
  pE0: Float32Array | null;
  pLand0: Uint8Array | null;
  P: number;
  PAD: number;
}

/** Tiles either side of a land border whose stage-three ground both counties are sure to compute alike. */
const SHARED = 6;

/**
 * The height, in steps, a route crosses a land border at: the mean of the stage-three ground a few tiles either
 * side, across its three tiles, read in the same order by both counties (the finished corners at a border can
 * already disagree, a terrace wall on one side, so they won't do). Null without that ground.
 */
function sharedBorderHeight(ctx: InterstateCtx, side: number, at: number): number | null {
  const { w, pE0, pLand0, P, PAD } = ctx;
  if (!pE0 || !pLand0) return null;
  let sum = 0, n = 0;
  for (let u = -1; u <= 1; u++) {
    for (let off = -SHARED; off < SHARED; off++) {
      const gx = side % 2 === 0 ? w.ox + (side === 0 ? N : 0) + off : w.ox + at + u;
      const gz = side % 2 === 0 ? w.oz + at + u : w.oz + (side === 1 ? N : 0) + off;
      const px = gx - w.ox + PAD, pz = gz - w.oz + PAD;
      if (px < 0 || pz < 0 || px >= P || pz >= P) return null;
      const q = pz * P + px;
      if (!pLand0[q]) continue;
      sum += pE0[q]; n++;
    }
  }
  return n ? Math.round(sum / n) : null;
}

// ---------------- the cost of the ground ----------------

/** What a tile is to the line: passable at a cost, something to bridge (water, a railway, a road), or not at all. */
interface Ground { cost: Float32Array; bridge: Uint8Array; hard: Uint8Array }

function groundOf(ctx: InterstateCtx): Ground {
  const { w, towns } = ctx;
  const cost = new Float32Array(N * N), bridge = new Uint8Array(N * N), hard = new Uint8Array(N * N);
  // distance outside each town square, Chebyshev
  const townPen = new Float32Array(N * N);
  for (const t of towns) {
    const x0 = t.x0 - TOWN_NEAR, z0 = t.z0 - TOWN_NEAR, x1 = t.x0 + t.size + TOWN_NEAR, z1 = t.z0 + t.size + TOWN_NEAR;
    for (let z = Math.max(0, z0); z < Math.min(N, z1); z++) {
      for (let x = Math.max(0, x0); x < Math.min(N, x1); x++) {
        const dx = x < t.x0 ? t.x0 - x : x >= t.x0 + t.size ? x - (t.x0 + t.size - 1) : 0;
        const dz = z < t.z0 ? t.z0 - z : z >= t.z0 + t.size ? z - (t.z0 + t.size - 1) : 0;
        const d = Math.max(dx, dz);
        const i = idx(x, z);
        const pen = d < TOWN_KEEP ? Infinity : ((TOWN_NEAR - d) / (TOWN_NEAR - TOWN_KEEP)) * 1.0;
        townPen[i] = Math.max(townPen[i], pen);
      }
    }
  }
  for (let i = 0; i < N * N; i++) {
    const rb = w.rail[i];
    if (w.biome[i] === Biome.Ocean || w.blocked[i] || (w.flags[i] & Flag.Poi) || (w.feature[i] && w.feature[i] !== Feature.Beach)
      || (rb & (RailBit.Pad | RailBit.Loop | RailBit.Deck)) || townPen[i] === Infinity || w.deckAxis[i]) {
      cost[i] = Infinity; hard[i] = 1;
      continue;
    }
    const wet = w.water[i] >= 0 || waterDepth(w, i) > 0 || (w.flags[i] & (Flag.River | Flag.Stream)) !== 0;
    const track = (rb & RailBit.Track) !== 0;
    if (wet || track || w.road[i]) {
      bridge[i] = 1;
      // a lake is a long way round; a river or a railway is a deck's worth
      cost[i] = (w.water[i] >= 0 && !(w.flags[i] & (Flag.River | Flag.Stream)) ? 9 : 4) + townPen[i];
      continue;
    }
    // the middle of the county over its edges: a route that hugs a border runs beside its neighbour's
    const x = i % N, z = (i - x) / N, edge = Math.min(x, z, N - 1 - x, N - 1 - z);
    cost[i] = 1 + townPen[i] + (edge < 28 ? (28 - edge) * 0.03 : 0) + (maxCorner(w, i) - Math.min(w.corners[i * 4], w.corners[i * 4 + 1], w.corners[i * 4 + 2], w.corners[i * 4 + 3])) * 0.5
      + ((w.flags[i] & Flag.Field) ? 0.8 : 0);
  }
  return { cost, bridge, hard };
}

// ---------------- the line ----------------

/** The node a route's stretch starts or ends at on side d, crossing at tile `at`, and the way inward. */
function borderNode(d: number, at: number): { node: number; inward: number } {
  const inward = (d + 2) % 4;
  if (d === 0) return { node: idx(N - 2, at), inward };
  if (d === 2) return { node: idx(1, at), inward };
  if (d === 1) return { node: idx(at, N - 2), inward };
  return { node: idx(at, 1), inward };
}

const nodeX = (n: number) => n % N, nodeZ = (n: number) => (n - (n % N)) / N;

/** The eight headings a line may take, E SE S SW W NW N NE: the square ones are 2 × their DIRS index. */
const HX = [1, 1, 0, -1, -1, -1, 0, 1], HZ = [0, 1, 1, 1, 0, -1, -1, -1];
/** What a 45° turn costs the line search: a gentle one, taken where the country runs that way. */
const TURN45 = 26;

/**
 * The cheapest line from (sx, sz) heading `sd` (a DIRS index) to (tx, tz), over a lattice of long straights:
 * every node is on a lattice line LATTICE apart through the start, or on the start's or the target's own row or
 * column. It runs square to the grid or at 45° (the user, 9 Nov 2026: interstates run diagonally too), turns 45°
 * cheaply and 90° dearly, never more. A diagonal stretch stands on the ground the whole way, never a deck, and a
 * right-angle turn is only ever between two square stretches. Returns the corners, start and end included, or null.
 */
function searchLine(g: Ground, w: World, sx: number, sz: number, sd: number, tx: number, tz: number, td: number, diagonals = true): [number, number][] | null {
  // nowhere nearer a border than this but the stubs' own rows: a route never runs along the edge of its county
  const lo = 16, hi = N - 17;
  const lines = (a: number, b: number): number[] => {
    const s = new Set<number>([a, b]);
    for (let v = a % LATTICE; v <= hi; v += LATTICE) if (v >= lo) s.add(v);
    return [...s].sort((p, q) => p - q);
  };
  const XS = lines(sx, tx), ZS = lines(sz, tz);
  const nx = XS.length, nz = ZS.length;
  const xi = new Map(XS.map((v, i) => [v, i])), zi = new Map(ZS.map((v, i) => [v, i]));
  const si = xi.get(sx)!, sj = zi.get(sz)!, ti = xi.get(tx)!, tj = zi.get(tz)!;
  // what a tile of road costs running along x (axis 0) or z (axis 1): its three tiles across
  const band = (t: number, axis: number): number => {
    const o = axis === 0 ? N : 1;
    return g.cost[t - o] + g.cost[t] + g.cost[t + o];
  };
  const bridgeNear = (x: number, z: number, r: number): boolean => {
    for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
      if (!inB(x + dx, z + dz)) return true;
      const t = idx(x + dx, z + dz);
      if (g.bridge[t] || g.hard[t]) return true;
    }
    return false;
  };
  const turnOk = new Int8Array(nx * nz).fill(-1);
  const canTurn = (i: number, j: number): boolean => {
    const c = j * nx + i;
    if (turnOk[c] < 0) turnOk[c] = bridgeNear(XS[i], ZS[j], TURN_CLEAR) ? 0 : 1;
    return turnOk[c] === 1;
  };
  const H8 = 8;
  const S = nx * nz * H8;
  const dist = new Float64Array(S).fill(Infinity), prev = new Int32Array(S).fill(-1);
  const heap = new MinHeap();
  const h = (i: number, j: number) => {
    const ax = Math.abs(XS[i] - tx), az = Math.abs(ZS[j] - tz);
    return 3 * (Math.max(ax, az) + (Math.SQRT2 - 1) * Math.min(ax, az));
  };
  const s0 = (sj * nx + si) * H8 + sd * 2;
  dist[s0] = 0;
  heap.push(h(si, sj), s0);
  // a lattice step's cost, cached: from node (i, j) one on along heading e
  const stepCost = new Float64Array(nx * nz * H8).fill(NaN);
  const step = (i: number, j: number, e: number): number => {
    const c = (j * nx + i) * H8 + e;
    if (!Number.isNaN(stepCost[c])) return stepCost[c];
    const ni = i + HX[e], nj = j + HZ[e];
    let x = XS[i], z = ZS[j];
    const ex = XS[ni], ez = ZS[nj];
    let sum = 0, last = tileMean(w, idx(x, z));
    if (e % 2 === 0) {
      while (x !== ex || z !== ez) {
        x += Math.sign(ex - x); z += Math.sign(ez - z);
        const t = idx(x, z);
        const b = band(t, (e / 2) % 2);
        if (!(b < Infinity)) { sum = Infinity; break; }
        const m = tileMean(w, t);
        sum += b + Math.abs(m - last) * 2.5;
        last = m;
      }
    } else if (Math.abs(ex - x) !== Math.abs(ez - z)) {
      sum = Infinity;
    } else {
      // a staircase, a step along x then one along z: every node's block on clear ground, nothing to bridge
      const fx = Math.sign(ex - x), fz = Math.sign(ez - z);
      for (let k = 0; (x !== ex || z !== ez) && sum < Infinity; k++) {
        if (k % 2 === 0) x += fx; else z += fz;
        let b = 0;
        for (let dz = -1; dz <= 1 && b < Infinity; dz++) for (let dx = -1; dx <= 1; dx++) {
          const t = idx(x + dx, z + dz);
          if (g.bridge[t] || !(g.cost[t] < Infinity)) { b = Infinity; break; }
          b += g.cost[t];
        }
        if (!(b < Infinity)) { sum = Infinity; break; }
        const m = tileMean(w, idx(x, z));
        // each step is half a diagonal tile's length, √½ of a square one
        sum += (b / 3) * Math.SQRT1_2 + Math.abs(m - last) * 2.5;
        last = m;
      }
    }
    stepCost[c] = sum;
    return sum;
  };
  const turnCost = (from: number, to: number): number => {
    const a = Math.abs(from - to), d = Math.min(a, 8 - a);
    if (d === 0) return 0;
    if (d === 1) return TURN45;
    // a right angle only between two square stretches
    return d === 2 && from % 2 === 0 && to % 2 === 0 ? TURN : Infinity;
  };
  while (heap.size) {
    const key = heap.topKey();
    const s = heap.pop();
    const cell = Math.floor(s / H8), e0 = s % H8;
    const i = cell % nx, j = (cell - i) / nx;
    const gS = dist[s];
    if (key > gS + h(i, j) + 1e-9) continue;
    if (i === ti && j === tj) {
      // arriving the way its stub leaves, or turning onto it where a turn may stand
      if (td >= 0 && e0 !== td * 2 && (!canTurn(i, j) || !(turnCost(e0, td * 2) < Infinity))) continue;
      const out: [number, number][] = [];
      for (let c = s; c >= 0; c = prev[c]) {
        const cc = Math.floor(c / H8);
        out.push([XS[cc % nx], ZS[Math.floor(cc / nx)]]);
      }
      return out.reverse();
    }
    for (let e = 0; e < H8; e++) {
      if (!diagonals && e % 2) continue;
      const tc = turnCost(e0, e);
      if (!(tc < Infinity)) continue;
      const ni = i + HX[e], nj = j + HZ[e];
      if (ni < 0 || nj < 0 || ni >= nx || nj >= nz) continue;
      if (tc > 0 && (!canTurn(i, j) || (i === si && j === sj))) continue;
      const c = step(i, j, e);
      if (!(c < Infinity)) continue;
      const ns = (nj * nx + ni) * H8 + e;
      const ng = gS + c + tc + (td >= 0 && ni === ti && nj === tj ? Math.min(TURN, turnCost(e, td * 2)) : 0);
      if (ng < dist[ns]) { dist[ns] = ng; prev[ns] = s; heap.push(ng + h(ni, nj), ns); }
    }
  }
  return null;
}

/** A binary heap of state ids keyed by cost. */
class MinHeap {
  private k: number[] = [];
  private v: number[] = [];
  get size(): number { return this.k.length; }
  push(key: number, val: number): void {
    const k = this.k, v = this.v;
    let i = k.length;
    k.push(key); v.push(val);
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (k[p] <= key) break;
      k[i] = k[p]; v[i] = v[p]; i = p;
    }
    k[i] = key; v[i] = val;
  }
  topKey(): number { return this.k[0]; }
  pop(): number {
    const k = this.k, v = this.v;
    const top = v[0];
    const lk = k.pop()!, lv = v.pop()!;
    const n = k.length;
    if (n) {
      let i = 0;
      for (;;) {
        let c = 2 * i + 1;
        if (c >= n) break;
        if (c + 1 < n && k[c + 1] < k[c]) c++;
        if (k[c] >= lk) break;
        k[i] = k[c]; v[i] = v[c]; i = c;
      }
      k[i] = lk; v[i] = lv;
    }
    return top;
  }
}

/**
 * Tile nodes along the legs between corners, each corner once: a square leg tile by tile, a diagonal one as a
 * staircase (a step along x, then along z), which world/diagonals.ts reads as one straight 45° line. `at` is the
 * node index of each corner.
 */
function rasterise(corners: [number, number][]): { nodes: number[]; at: number[] } {
  const out: number[] = [idx(corners[0][0], corners[0][1])];
  const at = [0];
  for (let c = 1; c < corners.length; c++) {
    let [x, z] = corners[c - 1];
    const [ex, ez] = corners[c];
    const diag = x !== ex && z !== ez;
    for (let k = 0; x !== ex || z !== ez; k++) {
      if (!diag) { x += Math.sign(ex - x); z += Math.sign(ez - z); }
      else if (k % 2 === 0) x += Math.sign(ex - x);
      else z += Math.sign(ez - z);
      out.push(idx(x, z));
    }
    at.push(out.length - 1);
  }
  return { nodes: out, at };
}

// ---------------- planning one route ----------------

/** A town's importance for an exit: its kind first, then its size. */
const TOWN_RANK: Record<string, number> = { mega: 5, metro: 4, city: 3, suburb: 2, rural: 1 };
const townScore = (t: TownPlan): number => TOWN_RANK[t.kind] * 1000 + t.size;

/**
 * Where a route ending at a town comes to a stop: just outside its square on the side facing the border it came
 * in by, on a tile the line can reach, or null.
 */
function terminusTargets(g: Ground, t: TownPlan, from: number): [number, number][] {
  const out: [number, number][] = [];
  const cx = t.x0 + Math.floor(t.size / 2), cz = t.z0 + Math.floor(t.size / 2);
  const fx = nodeX(from), fz = nodeZ(from);
  // the side of the square facing the way in first, then the others
  const sides = [0, 1, 2, 3].sort((a, b) => {
    const sa = DX[a] * (fx - cx) + DZ[a] * (fz - cz), sb = DX[b] * (fx - cx) + DZ[b] * (fz - cz);
    return sb - sa;
  });
  for (const s of sides) {
    for (let off = TOWN_KEEP + 3; off <= TOWN_KEEP + 14; off += 2) {
      const half = Math.floor(t.size / 2) + off;
      const x = cx + DX[s] * half, z = cz + DZ[s] * half;
      if (x < 8 || z < 8 || x > N - 9 || z > N - 9) continue;
      let ok = true;
      for (let dz = -2; dz <= 2 && ok; dz++) for (let dx = -2; dx <= 2 && ok; dx++) {
        const i = idx(x + dx, z + dz);
        if (!(g.cost[i] < Infinity) || g.bridge[i]) ok = false;
      }
      // the nearest spot on each side
      if (ok) { out.push([x, z]); break; }
    }
  }
  return out;
}

/** A straight a line must run along, from (ax, az) to (bx, bz), heading d (a DIRS index) the whole way. */
interface Via { ax: number; az: number; bx: number; bz: number; d: number }

function planRoute(ctx: InterstateCtx, g: Ground, line: InterstateLine, diagonals = true, via?: Via): RoutePlan | string {
  const { w, seedHash, towns } = ctx;
  const ends = line.sides.map((d) => {
    const at = interstateAt(seedHash, w.cx, w.cz, d, line.key);
    return { d, at, ...borderNode(d, at) };
  });
  if (ends.some((e) => e.at < 0)) return 'no border tile';
  const a = ends[0];
  const stubEnd = (e: typeof a): [number, number] => [nodeX(e.node) + DX[e.inward] * STUB, nodeZ(e.node) + DZ[e.inward] * STUB];
  const [sx, sz] = stubEnd(a);
  let tx: number, tz: number, td: number, endTown = -1;
  let terminusCands: { k: number; at: [number, number] }[] = [];
  if (ends.length > 1) {
    [tx, tz] = stubEnd(ends[1]);
    td = ends[1].d;
  } else {
    // a terminus: on to the biggest town of the county
    const order = towns.map((t, k) => ({ t, k })).filter(({ t }) => t.kind !== 'suburb' || towns.length === 1).sort((p, q) => townScore(q.t) - townScore(p.t));
    const cands: { k: number; at: [number, number] }[] = [];
    for (const { t, k } of order) for (const at of terminusTargets(g, t, a.node)) cands.push({ k, at });
    if (!cands.length) return 'no town to end at';
    [tx, tz] = cands[0].at;
    endTown = cands[0].k;
    td = -1;
    terminusCands = cands;
  }
  // the stubs themselves must be clear ground or something to bridge
  for (const e of ends) {
    for (let s = 0; s <= STUB; s++) {
      const x = nodeX(e.node) + DX[e.inward] * s, z = nodeZ(e.node) + DZ[e.inward] * s;
      // past its level run at the border a stub may bridge what it meets: it runs straight, as a deck must
      for (const t of nodeTiles(idx(x, z), 'tri')) {
        if (g.hard[t] || (g.bridge[t] && s <= LEVEL_IN + 3)) {
          const what = w.biome[t] === Biome.Ocean ? 'sea' : w.blocked[t] ? 'building' : w.flags[t] & Flag.Poi ? 'a site' : w.feature[t] ? `feature ${w.feature[t]}` : w.rail[t] ? 'railway' : w.deckAxis[t] ? 'deck' : g.bridge[t] ? 'water' : 'a town';
          return `border stub blocked (${what} ${s} in)`;
        }
      }
    }
  }
  let corners: [number, number][] | null;
  if (via) {
    // up to the straight, along it, and on from its far end
    const first = searchLine(g, w, sx, sz, a.inward, via.ax, via.az, via.d, diagonals);
    const second = first && searchLine(g, w, via.bx, via.bz, via.d, tx, tz, td, diagonals);
    corners = first && second ? [...first, ...second] : null;
  } else corners = searchLine(g, w, sx, sz, a.inward, tx, tz, td, diagonals);
  // a terminus that can't reach the side of its town it faces tries the others, and the next town
  for (let c = 1; !corners && c < Math.min(terminusCands.length, 8); c++) {
    [tx, tz] = terminusCands[c].at;
    endTown = terminusCands[c].k;
    corners = searchLine(g, w, sx, sz, a.inward, tx, tz, td, diagonals);
  }
  if (!corners) return `no line (${sx},${sz} heading ${a.inward} to ${tx},${tz}${endTown >= 0 ? ' at ' + towns[endTown].kind : ''})`;
  const ras = rasterise(corners);
  const inner = ras.nodes;
  const head: number[] = [];
  for (let s = 0; s < STUB; s++) head.push(idx(nodeX(a.node) + DX[a.inward] * s, nodeZ(a.node) + DZ[a.inward] * s));
  const tail: number[] = [];
  if (ends.length > 1) {
    const b = ends[1];
    for (let s = STUB - 1; s >= 0; s--) tail.push(idx(nodeX(b.node) + DX[b.inward] * s, nodeZ(b.node) + DZ[b.inward] * s));
  }
  const nodes = [...head, ...inner, ...tail];
  // the line never comes back near itself: no tile of one node's block within another's that isn't a near neighbour
  const owner = new Map<number, number>();
  for (let k = 0; k < nodes.length; k++) {
    for (const t of nodeTiles(nodes[k], 'tri')) {
      const o = owner.get(t);
      if (o !== undefined && k - o > 4) return 'line meets itself';
      if (o === undefined) owner.set(t, k);
    }
  }
  const dirs = nodes.map((n, k) => (k + 1 < nodes.length ? dirOf(n, nodes[k + 1]) : dirOf(nodes[k - 1], n)));
  if (dirs.some((d) => d < 0)) return 'broken line';
  // the corners, by node, and how sharp: 1 for 45°, 2 for a right angle (the first and last are the line's ends)
  const off = head.length - 1;
  const turns: { k: number; sharp: number; diag: boolean }[] = [];
  for (let c = 1; c < corners.length - 1; c++) {
    const [ax, az] = corners[c - 1], [bx, bz] = corners[c], [qx, qz] = corners[c + 1];
    const h1 = heading8(bx - ax, bz - az), h2 = heading8(qx - bx, qz - bz);
    const d = Math.min(Math.abs(h1 - h2), 8 - Math.abs(h1 - h2));
    if (d) turns.push({ k: off + ras.at[c], sharp: d, diag: h1 % 2 === 1 || h2 % 2 === 1 });
  }
  // the nodes on a staircase (a diagonal's), which never carry a deck, a crossing or an exit
  const diag = new Uint8Array(nodes.length);
  for (let c = 1; c < corners.length; c++) {
    const [ax, az] = corners[c - 1], [bx, bz] = corners[c];
    if (ax !== bx && az !== bz) for (let k = off + ras.at[c - 1]; k <= off + ras.at[c]; k++) diag[k] = 1;
  }
  const centre = roadLine(RoadType.Interstate, nodes, true);
  return { turns, diag, centre: centre ? centre.pts : nodes.map((n) => [nodeX(n) + 0.5, nodeZ(n) + 0.5] as [number, number]), line, nodes, dirs, q: new Int16Array(nodes.length + 3), air: new Uint8Array(nodes.length), unders: [], exits: [], bridges: [], endTown, stripUnder: new Set(), cuts: [], deckTiles: new Set(), ends: ends.map((e) => ({ d: e.d, at: e.at })), bends: new Map(), bendZone: new Uint8Array(nodes.length), arcTiles: new Set() };
}

/** The heading (HX, HZ index) of a move. */
function heading8(dx: number, dz: number): number {
  const sx = Math.sign(dx), sz = Math.sign(dz);
  for (let e = 0; e < 8; e++) if (HX[e] === sx && HZ[e] === sz) return e;
  return -1;
}

function dirOf(a: number, b: number): number {
  const d = b - a;
  return d === 1 ? 0 : d === N ? 1 : d === -1 ? 2 : d === -N ? 3 : -1;
}

/** Is node k on a straight run reaching r nodes each way? */
function straightAround(p: RoutePlan, k: number, r: number): boolean {
  if (k - r < 0 || k + r >= p.nodes.length) return false;
  const d = p.dirs[k];
  for (let j = k - r; j < k + r; j++) if (p.dirs[j] !== d || p.bendZone[j] || p.diag[j]) return false;
  return true;
}

/** The tiles a bend's arc crosses, its whole width and a little over, round corner node k at radius r. */
function arcTilesOf(p: RoutePlan, k: number, r: number): number[] {
  const a = p.dirs[k - 1], b = p.dirs[k];
  const t = p.nodes[k], cx = nodeX(t) + 0.5, cz = nodeZ(t) + 0.5;
  const din = [DX[a], DZ[a]] as const, dout = [DX[b], DZ[b]] as const;
  const ox = cx - din[0] * r + dout[0] * r, oz = cz - din[1] * r + dout[1] * r;
  const out = new Set<number>();
  const steps = Math.ceil(r * 6);
  for (let s = 0; s <= steps; s++) {
    const phi = (s / steps) * (Math.PI / 2), cs = Math.cos(phi), sn = Math.sin(phi);
    const tx = din[0] * cs + dout[0] * sn, tz = din[1] * cs + dout[1] * sn;
    for (let o = -1.9; o <= 1.9; o += 0.2) {
      const x = ox - dout[0] * r * cs + din[0] * r * sn - tz * o, z = oz - dout[1] * r * cs + din[1] * r * sn + tx * o;
      const ix = Math.floor(x), iz = Math.floor(z);
      out.add(inB(ix, iz) ? idx(ix, iz) : -1);
    }
  }
  return [...out];
}

/**
 * The bends: at each corner as wide a sweep as the straights either side leave room for (the run back to the last
 * bend's end, half the run on to the next corner), no wider than BEND_MAX, and narrower until every tile its arc
 * crosses is clear country it can be graded over. A corner with no room for BEND_MIN keeps the narrow sweep the
 * road draws for itself (world/curves.ts).
 */
function planBends(g: Ground, p: RoutePlan): void {
  const n = p.nodes.length;
  // every corner, as a node: a right angle between square stretches gets a sweep, a 45° one the arc the road draws
  const corners = p.turns.map((t) => t.k);
  let free = LEVEL_IN + 3;
  p.turns.forEach(({ k, sharp, diag }, i) => {
    const next = corners[i + 1];
    if (sharp !== 2 || diag) {
      // a 45° join: the arc the road draws for it (render/roadMesh.ts) reaches about this far each way
      for (let j = k - DIAG_REACH; j <= k + DIAG_REACH; j++) if (j >= 0 && j < n) p.bendZone[j] = 1;
      free = k + DIAG_REACH;
      return;
    }
    const room = Math.min(k - free, next !== undefined ? Math.floor((next - k) / 2) : n - 1 - LEVEL_IN - 3 - k);
    let r = Math.min(BEND_MAX, room);
    for (; r >= BEND_MIN; r--) {
      if (arcTilesOf(p, k, r).every((t) => t >= 0 && g.cost[t] < Infinity && !g.bridge[t])) break;
    }
    if (r < BEND_MIN) { free = k + 2; return; }
    p.bends.set(k, r);
    for (let j = k - r - 2; j <= k + r + 2; j++) if (j >= 0 && j < n) p.bendZone[j] = 1;
    free = k + r;
  });
}

/** The tile at along-offset `u` across from node k (positive u to the left of travel... see `acrossDir`). */
function across(p: RoutePlan, k: number, u: number): number {
  const d = p.dirs[k], ad = acrossDir(d);
  const x = nodeX(p.nodes[k]) + DX[ad] * u, z = nodeZ(p.nodes[k]) + DZ[ad] * u;
  return inB(x, z) ? idx(x, z) : -1;
}
/** The across direction for travel along d: +z for a road along x, +x for one along z. */
const acrossDir = (d: number): number => (d % 2 === 0 ? 1 : 0);

/**
 * The underpasses and interchanges of a route: an interchange at the node nearest each town worth one (one or two
 * a county), then an underpass wherever the straight line between two towns, or from a town to a border road
 * crossing, meets the route, and one every UNDERPASS_EVERY tiles of path between, wherever the road runs straight
 * on the ground with clear country either side for a road to come through.
 */
/** The tests a place on the path must pass: a straight clear run, a strip of road under it, room for slip roads. */
function crossingTests(g: Ground, p: RoutePlan) {
  const n = p.nodes.length;
  const bridgeAt = new Uint8Array(n);
  for (let k = 0; k < n; k++) for (const t of nodeTiles(p.nodes[k], 'tri')) if (g.bridge[t]) bridgeAt[k] = 1;
  const clearRun = (k: number, r: number) => {
    for (let j = Math.max(0, k - r); j <= Math.min(n - 1, k + r); j++) if (bridgeAt[j]) return false;
    return straightAround(p, k, r);
  };
  /** Can a strip of road cross under at k, reaching `half` each side, every tile clear country? */
  const stripOk = (k: number, half: number, wide: number) => {
    for (let a = -wide; a <= wide; a++) {
      for (let u = -half; u <= half; u++) {
        const t = across(p, k + a, u);
        if (t < 0 || g.hard[t] || (g.bridge[t] && Math.abs(u) > 1)) return false;
      }
    }
    return true;
  };
  /** The ramps' ground: either side of the interstate, `reach` along each way, out to RAMP_MEET + 1. */
  const rampsOk = (k: number, reach: number) => {
    for (let a = -reach - 1; a <= reach + 1; a++) {
      for (const s of [-1, 1]) for (let u = 2; u <= RAMP_MEET + 1; u++) {
        const t = across(p, k + a, s * u);
        if (t < 0 || g.hard[t] || g.bridge[t]) return false;
      }
    }
    return true;
  };
  const inStub = (k: number, r: number) => k - r < STUB + 2 || (p.line.sides.length > 1 && k + r > n - 1 - STUB - 2);
  // an exit's slip roads may run out over a border stub's straight, just not onto its held lines
  const inEnds = (k: number, r: number) => k - r < LEVEL_IN + 4 || (p.line.sides.length > 1 && k + r > n - 1 - LEVEL_IN - 4);
  /** Can a diamond stand at k with slip roads `reach` long? */
  const exitAt = (k: number, reach: number) => !inEnds(k, reach + 2) && clearRun(k, reach + 2) && stripOk(k, ROAD_HALF, 1) && rampsOk(k, reach);
  return { clearRun, stripOk, inStub, exitAt };
}

function placeCrossings(ctx: InterstateCtx, g: Ground, p: RoutePlan): void {
  const { towns, w, seedHash } = ctx;
  const n = p.nodes.length;
  // (and where the other route crosses, at a junction: no underpass under its deck)
  const taken: number[] = [...p.exits.map((e) => e.k), ...(p.junction ? [p.junction.at] : [])];
  const near = (k: number, r: number) => taken.some((t) => Math.abs(t - k) < r);
  const { clearRun, stripOk, inStub, exitAt } = crossingTests(g, p);

  // interchanges: the best town first, the node of the path nearest its square; the long slip roads where they fit,
  // the short ones where they don't
  const order = towns.map((t, i) => ({ t, i })).sort((a, b) => townScore(b.t) - townScore(a.t));
  const exitsWanted = p.endTown >= 0 || p.junction ? 0 : 2;
  for (const { t, i } of order) {
    if (p.exits.length >= exitsWanted) break;
    if (p.exits.length === 1) {
      // a second exit only for a city or bigger, and a second town worth it far enough along
      const first = towns[p.exits[0].town];
      if (TOWN_RANK[first.kind] < 3 && TOWN_RANK[t.kind] < 3) break;
    }
    const cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2;
    const byDist = [...Array(n).keys()].map((k) => ({ k, d: Math.hypot(nodeX(p.nodes[k]) + 0.5 - cx, nodeZ(p.nodes[k]) + 0.5 - cz) })).sort((a, b) => a.d - b.d);
    let placed = false;
    for (const reach of [RAMP_REACH, RAMP_SHORT]) {
      for (const { k, d } of byDist) {
        if (d > t.size / 2 + 70) break;
        if (near(k, EXITS_APART) || !exitAt(k, reach)) continue;
        p.exits.push({ k, town: i, number: 0, reach });
        taken.push(k);
        placed = true;
        break;
      }
      if (placed) break;
    }
  }
  // a county with no town near enough still gets its exit: the clearest straight nearest the middle of the path
  if (!p.exits.length && p.endTown < 0 && !p.junction) {
    const mid = n / 2;
    const cands = [...Array(n).keys()].sort((a, b) => Math.abs(a - mid) - Math.abs(b - mid));
    for (const reach of [RAMP_REACH, RAMP_SHORT, RAMP_LEAST]) {
      const k = cands.find((c) => exitAt(c, reach));
      if (k === undefined) continue;
      // the town nearest, for its name
      let best = -1, bd = Infinity;
      towns.forEach((t, i) => { const d = Math.hypot(nodeX(p.nodes[k]) - t.x0 - t.size / 2, nodeZ(p.nodes[k]) - t.z0 - t.size / 2); if (d < bd) { bd = d; best = i; } });
      p.exits.push({ k, town: best, number: 0, reach });
      taken.push(k);
      break;
    }
  }
  p.exits.sort((a, b) => a.k - b.k);
  p.exits.forEach((e, j) => { e.number = exitNumber(seedHash, p.line, w.cx, w.cz, j); });
  for (const e of p.exits) p.unders.push({ k: e.k, g: 0 });

  // underpasses where the county's roads will want to cross: between towns either side, and every so often
  const want: number[] = [];
  const pts: [number, number][] = towns.map((t) => [t.x0 + t.size / 2, t.z0 + t.size / 2]);
  for (let a = 0; a < pts.length; a++) for (let b = a + 1; b < pts.length; b++) {
    const k = crossingOf(p, pts[a], pts[b]);
    if (k >= 0) want.push(k);
  }
  const nearExit = (k: number) => p.exits.some((e) => Math.abs(e.k - k) < e.reach + 10);
  const tryAt = (k: number, r: number): boolean => {
    for (let s = 0; s <= r; s++) {
      for (const kk of s ? [k - s, k + s] : [k]) {
        if (kk < 0 || kk >= n || inStub(kk, 6) || near(kk, 20) || nearExit(kk) || !clearRun(kk, 5) || !stripOk(kk, STRIP_HALF, 1)) continue;
        p.unders.push({ k: kk, g: 0 });
        taken.push(kk);
        return true;
      }
    }
    return false;
  };
  for (const k of want) tryAt(k, 14);
  for (let k = STUB + 12; k < n - STUB - 12; k++) if (!near(k, UNDERPASS_EVERY)) tryAt(k, 10);
  p.unders.sort((a, b) => a.k - b.k);
}

/** The node where the straight line from a to b crosses the route, or -1. */
function crossingOf(p: RoutePlan, a: [number, number], b: [number, number]): number {
  for (let k = 1; k < p.nodes.length; k++) {
    const x0 = nodeX(p.nodes[k - 1]) + 0.5, z0 = nodeZ(p.nodes[k - 1]) + 0.5, x1 = nodeX(p.nodes[k]) + 0.5, z1 = nodeZ(p.nodes[k]) + 0.5;
    const d1x = b[0] - a[0], d1z = b[1] - a[1], d2x = x1 - x0, d2z = z1 - z0;
    const den = d1x * d2z - d1z * d2x;
    if (Math.abs(den) < 1e-9) continue;
    const s = ((x0 - a[0]) * d2z - (z0 - a[1]) * d2x) / den, t = ((x0 - a[0]) * d1z - (z0 - a[1]) * d1x) / den;
    if (s >= 0 && s <= 1 && t >= 0 && t <= 1) return k;
  }
  return -1;
}

// ---------------- the profile ----------------

/** Mean of a node's 3×3 of ground, in steps. */
function nodeGround(w: World, n: number): number {
  let s = 0;
  for (const t of nodeTiles(n, 'tri')) s += tileMean(w, t);
  return s / 9;
}

/**
 * The vertical line, in steps per vertex line. The ground smoothed and tracked up and down at the grade (a step
 * over any two tiles), the middle of the two taken; raised over what it bridges and its underpasses, the raise
 * eased off at the grade; level along its border stubs at the height both counties share; flat round its corners.
 * False where those can't all be had.
 */
function profile(ctx: InterstateCtx, g: Ground, p: RoutePlan): string | null {
  const { w } = ctx;
  const n = p.nodes.length, L = n + 3; // lines -2 … n, at index e + 2
  const gN = p.nodes.map((v) => nodeGround(w, v));
  const ground = new Float64Array(L);
  for (let e = -2; e <= n; e++) {
    const a = gN[Math.max(0, Math.min(n - 1, e))], b = gN[Math.max(0, Math.min(n - 1, e + 1))];
    ground[e + 2] = (a + b) / 2;
  }
  // smoothed
  const sm = new Float64Array(L);
  for (let e = 0; e < L; e++) {
    let s = 0, c = 0;
    for (let j = Math.max(0, e - 4); j <= Math.min(L - 1, e + 4); j++) { s += ground[j]; c++; }
    sm[e] = s / c;
  }
  const up = Float64Array.from(sm), down = Float64Array.from(sm);
  const G = 0.5;
  for (let e = 1; e < L; e++) { up[e] = Math.max(up[e], up[e - 1] - G); down[e] = Math.min(down[e], down[e - 1] + G); }
  for (let e = L - 2; e >= 0; e--) { up[e] = Math.max(up[e], up[e + 1] - G); down[e] = Math.min(down[e], down[e + 1] + G); }
  const q = new Float64Array(L);
  for (let e = 0; e < L; e++) q[e] = Math.round((up[e] + down[e]) / 2);

  // the lower bounds: what each line must stand over, eased off at the deck's grade either side
  const need = new Float64Array(L).fill(-Infinity);
  const addNeed = (pos: number, h: number) => {
    // a tile at path position `pos` is spanned by lines pos-1 (its back edge) and pos (its front edge)
    for (let e = pos - 1 - 12; e <= pos + 12; e++) {
      if (e < -2 || e > n) continue;
      const dist = e < pos - 1 ? pos - 1 - e : e > pos ? e - pos : 0;
      need[e + 2] = Math.max(need[e + 2], h - Math.floor(dist * G));
    }
  };
  for (let k = 0; k < n; k++) {
    for (const t of tilesAt(p, k)) {
      if (!g.bridge[t]) continue;
      const wet = w.water[t] >= 0 || waterDepth(w, t) > 0;
      const h = wet && !(w.rail[t] & RailBit.Track) && !w.road[t] ? Math.max(w.water[t], maxCorner(w, t)) + 1 : maxCorner(w, t) + UNDER;
      addNeed(k, h);
    }
  }
  for (const u of p.unders) {
    // the ground under: the strip's level, the mean of the three tiles each side across the middle
    let s = 0, c = 0;
    for (let a = -1; a <= 1; a++) for (let v = -2; v <= 2; v++) { const t = across(p, u.k + a, v); if (t >= 0) { s += tileMean(w, t); c++; } }
    u.g = Math.round(s / Math.max(1, c));
    for (let a = -1; a <= 1; a++) {
      addNeed(u.k + a, u.g + UNDER);
      for (let v = -1; v <= 1; v++) { const t = across(p, u.k + a, v); if (t >= 0) p.stripUnder.add(t); }
    }
  }
  for (let e = 0; e < L; e++) if (need[e] > q[e]) q[e] = need[e];

  // fixed: the stubs, at the border's height
  const fixed = new Uint8Array(L);
  const borderH = (k: number) => {
    const e = p.ends[k === 0 ? 0 : 1];
    return e ? sharedBorderHeight(ctx, e.d, e.at) : nodeEdgeHeight(w, p, k);
  };
  const B0 = borderH(0);
  if (B0 === null) return 'no shared ground at the border';
  for (let e = -2; e < LEVEL_IN; e++) { q[e + 2] = B0; fixed[e + 2] = 1; }
  if (p.line.sides.length > 1) {
    const B1 = borderH(n - 1);
    if (B1 === null) return 'no shared ground at the border';
    for (let e = n - 1 - LEVEL_IN; e <= n; e++) { q[e + 2] = B1; fixed[e + 2] = 1; }
  }
  // corners: flat from two nodes before to two after
  const group = new Int32Array(L).map((_, e) => e);
  for (const { k, sharp, diag } of p.turns) {
    // a sweep is level all round; a 45° join only near its corner (its arc strays under a tile off the straight)
    const r = sharp === 2 && !diag ? (p.bends.get(k) ?? 0) : DIAG_LEVEL;
    const lo = Math.max(-2, k - 3 - r), hi = Math.min(n, k + 2 + r);
    const id = group[lo + 2];
    for (let e = lo; e <= hi; e++) group[e + 2] = id;
  }
  // groups as runs: every line takes its group's highest
  const flatten = () => {
    let e = 0;
    while (e < L) {
      let f = e;
      while (f + 1 < L && group[f + 1] === group[e]) f++;
      if (f > e) {
        let m = -Infinity, held = NaN;
        for (let j = e; j <= f; j++) { m = Math.max(m, q[j]); if (fixed[j]) held = q[j]; }
        const top = m;
        if (!Number.isNaN(held)) m = held;
        else for (let j = e; j <= f; j++) m = Math.min(m, cap[j]);
        for (let j = e; j <= f; j++) if (!fixed[j]) q[j] = m;
        // held below its own ground, the level corner holds the road either side down too, eased off at the grade
        // (else the next line on stands at the ground's height, a cliff above the corner)
        if (m < top) { for (let j = e; j <= f; j++) cap[j] = Math.min(cap[j], m); lowered = true; }
      }
      e = f + 1;
    }
  };
  // down from the stubs first (cut into a hill that rises off the border), then raise anything left too low
  for (let e = 0; e < L; e++) if (!fixed[e] && e > 0 && fixed[e - 1]) {
    for (let j = e; j < L && !fixed[j]; j++) q[j] = Math.min(q[j], q[j - 1] + 1, j >= 2 ? q[j - 2] + 1 : Infinity);
  }
  for (let e = L - 1; e >= 0; e--) if (!fixed[e] && e < L - 1 && fixed[e + 1]) {
    for (let j = e; j >= 0 && !fixed[j]; j--) q[j] = Math.min(q[j], q[j + 1] + 1, j + 2 < L ? q[j + 2] + 1 : Infinity);
  }
  // on a diagonal a line is only √½ a tile on from the last, so it climbs a step in three, not two
  const dl = new Uint8Array(L);
  for (let k = 0; k < n; k++) if (p.diag[k]) { dl[k + 1] = 1; dl[k + 2] = 1; }
  // the most any line may stand above the border heights it is held to, climbing off them at the grade
  const cap = new Float64Array(L).fill(Infinity);
  for (let f = 0; f < L; f++) if (fixed[f]) for (let e = 0; e < L; e++) cap[e] = Math.min(cap[e], q[f] + Math.ceil(Math.abs(e - f) / 2));
  // the caps eased off one another at the grade, a step in three along a diagonal (the checks below)
  const easeCaps = () => {
    for (let e = 1; e < L; e++) cap[e] = Math.min(cap[e], cap[e - 1] + 1, e >= 2 ? cap[e - 2] + 1 : Infinity, dl[e] && e >= 3 ? cap[e - 3] + 1 : Infinity);
    for (let e = L - 2; e >= 0; e--) cap[e] = Math.min(cap[e], cap[e + 1] + 1, e + 2 < L ? cap[e + 2] + 1 : Infinity, e + 3 < L && dl[e + 3] ? cap[e + 3] + 1 : Infinity);
  };
  let lowered = true;
  for (let pass = 0; pass < 8; pass++) {
    if (lowered) { easeCaps(); lowered = false; }
    for (let e = 0; e < L; e++) if (!fixed[e]) q[e] = Math.min(cap[e], Math.max(q[e], need[e], e >= 1 ? q[e - 1] - 1 : -Infinity, e >= 2 ? q[e - 2] - 1 : -Infinity, dl[e] && e >= 3 ? q[e - 3] - 1 : -Infinity));
    for (let e = L - 1; e >= 0; e--) if (!fixed[e]) q[e] = Math.min(cap[e], Math.max(q[e], e + 1 < L ? q[e + 1] - 1 : -Infinity, e + 2 < L ? q[e + 2] - 1 : -Infinity, e + 3 < L && dl[e + 3] ? q[e + 3] - 1 : -Infinity));
    flatten();
  }
  // check it all holds
  for (let e = 0; e < L; e++) {
    if (e >= 1 && Math.abs(q[e] - q[e - 1]) > 1) return `too steep at line ${e - 2} (${[...q.slice(Math.max(0, e - 4), e + 4)].join(' ')} over ground ${[...ground.slice(Math.max(0, e - 4), e + 4)].map((v) => v.toFixed(0)).join(' ')}, held ${[...fixed.slice(Math.max(0, e - 4), e + 4)].join('')})`;
    if (e >= 2 && Math.abs(q[e] - q[e - 2]) > 1) return `too steep at line ${e - 2}`;
    if (dl[e] && e >= 3 && Math.abs(q[e] - q[e - 3]) > 1) return `too steep on a diagonal at line ${e - 2}`;
    if (q[e] < need[e] - 1e-9) return `can't clear what it crosses at line ${e - 2}`;
    if (q[e] < -100 || q[e] > 120) return 'profile out of range';
  }
  for (let e = 0; e < L; e++) p.q[e] = q[e];

  // on a deck: everything it bridges, every underpass, and wherever it would stand on more than FILL_MAX of fill
  const corner = Uint8Array.from(p.bendZone);
  for (let k = 0; k < n; k++) if (p.diag[k]) corner[k] = 1;
  for (let k = 1; k < n - 1; k++) if (p.dirs[k - 1] !== p.dirs[k]) for (let j = k - 2; j <= k + 2; j++) if (j >= 0 && j < n) corner[j] = 1;
  for (let k = 0; k < n; k++) {
    const bridged = tilesAt(p, k).some((t) => g.bridge[t]);
    if (bridged) for (let j = k - 1; j <= k + 1; j++) if (j >= 0 && j < n) p.air[j] = 1;
  }
  for (const u of p.unders) for (let j = u.k - 2; j <= u.k + 2; j++) if (j >= 0 && j < n) p.air[j] = 1;
  // an interchange's stretch stays on its embankment, whatever the fill: its slip roads leave and join it there
  const exitZone = new Uint8Array(n);
  for (const e of p.exits) for (let j = e.k - e.reach - 4; j <= e.k + e.reach + 4; j++) if (j >= 0 && j < n) exitZone[j] = 1;
  for (let k = STUB; k < n - STUB; k++) {
    if (corner[k] || p.air[k] || exitZone[k]) continue;
    const top = Math.min(p.q[k + 1], p.q[k + 2]);
    if (top - gN[k] > FILL_MAX) p.air[k] = 1;
  }
  return null;
}

/** The tiles of node k's block that the line passes over at path position k: the three across it. */
function tilesAt(p: RoutePlan, k: number): number[] {
  const out: number[] = [];
  for (let u = -1; u <= 1; u++) { const t = across(p, k, u); if (t >= 0) out.push(t); }
  return out;
}

/** The height of the border edge under an end node's block, if its three tiles agree on it; else null. */
function nodeEdgeHeight(w: World, p: RoutePlan, k: number): number | null {
  const n = p.nodes[k], x = nodeX(n), z = nodeZ(n);
  const side = x <= 1 ? 2 : x >= N - 2 ? 0 : z <= 1 ? 3 : 1;
  // the four vertices along the border edge under the block
  const vs: number[] = [];
  for (let u = -1; u <= 2; u++) {
    if (side === 0) vs.push(vertexHeight(w, N, z + u));
    else if (side === 2) vs.push(vertexHeight(w, 0, z + u));
    else if (side === 1) vs.push(vertexHeight(w, x + u, N));
    else vs.push(vertexHeight(w, x + u, 0));
  }
  // the shared vertices are the same in both counties; their mean, rounded, is a height both can agree on
  return Math.round(vs.reduce((a, b) => a + b, 0) / vs.length);
}

/** A vertex's height, from whichever tile round it is in the county. */
function vertexHeight(w: World, vx: number, vz: number): number {
  for (const [tx, tz, q] of [[vx, vz, 0], [vx - 1, vz, 1], [vx - 1, vz - 1, 2], [vx, vz - 1, 3]] as const) {
    if (inB(tx, tz)) return w.corners[idx(tx, tz) * 4 + q];
  }
  return 0;
}

// ---------------- decks ----------------

/** The decks: every run of nodes off the ground, between the graded nodes either side of it. */
function decks(ctx: InterstateCtx, p: RoutePlan): string | null {
  const { w } = ctx;
  const n = p.nodes.length;
  // runs, merged where the ground between them is too short to stand an abutment on
  const runs: [number, number][] = [];
  for (let k = 0; k < n; k++) {
    if (!p.air[k]) continue;
    const last = runs[runs.length - 1];
    if (last && k - last[1] <= 4) { for (let j = last[1] + 1; j < k; j++) p.air[j] = 1; last[1] = k; }
    else runs.push([k, k]);
  }
  for (const [i, j] of runs) {
    const a = i - 1, b = j + 1;
    if (a < 0 || b >= n) return 'a deck runs off the end';
    const d = p.dirs[a];
    for (let k = a; k < b; k++) if (p.dirs[k] !== d) return 'a deck turns';
    const L = b - a - 3;
    if (L < 1) continue;
    const h0 = p.q[a + 1 + 2] * STEP, h1 = p.q[b - 2 + 2] * STEP;
    const br: Bridge = { from: a, to: b, h0, h1 };
    // clear everything under it: raise its middle where the straight deck would dip too low
    const tiles = deckTiles(p.nodes[a], p.nodes[b], d, 'tri');
    let peak = -Infinity;
    for (const { tile } of tiles) peak = Math.max(peak, needUnder(w, tile));
    peak *= STEP;
    // what each tile under it needs: an underpass's strip is graded to its level later, plain ground can be cut down
    const strip = (t: number) => p.stripUnder.has(t);
    const fixedNeed = (t: number) => !strip(t) && !shapeable(w, t);
    const deckAt = (x: Bridge, j: number, LL: number) => Math.min(deckHeightAt(x, LL, j - 1), deckHeightAt(x, LL, j));
    const clears = (x: Bridge) => tiles.every(({ tile, j, L: LL }) => !fixedNeed(tile) || deckAt(x, j, LL) >= needUnder(w, tile) * STEP - 1e-6);
    if (!clears(br)) {
      let withPeak: Bridge = { ...br, peak: Math.max(peak, h0, h1) };
      for (let r = Math.floor(L / 2); !clears(withPeak) && r >= 1; r--) {
        const steep: Bridge = { ...br, peak: Math.max(peak, h0, h1), ramp: r };
        if (clears(steep)) withPeak = steep;
      }
      if (!clears(withPeak)) {
        const miss = tiles.find(({ tile, j, L: LL }) => fixedNeed(tile) && deckAt(withPeak, j, LL) < needUnder(w, tile) * STEP - 1e-6)!;
        const t = miss.tile;
        const what = w.rail[t] ? 'rail' : w.road[t] ? `road ${w.road[t]}` : w.water[t] >= 0 ? `water ${w.water[t]}` : `other f${w.flags[t]} ft${w.feature[t]}`;
        return `a deck can't clear what is under it (${what} at ${t % N},${Math.floor(t / N)} tile ${miss.j}/${miss.L} of nodes ${a}-${b}: deck ${(deckAt(withPeak, miss.j, miss.L) / STEP).toFixed(1)}, needs ${needUnder(w, t).toFixed(1)})`;
      }
      br.peak = withPeak.peak;
      if (withPeak.ramp) br.ramp = withPeak.ramp;
    }
    for (const { tile, j, L: LL } of tiles) {
      if (w.blocked[tile] || (w.flags[tile] & Flag.Poi)) return 'a building under a deck';
      p.deckTiles.add(tile);
      if (strip(tile) || fixedNeed(tile)) continue;
      // plain ground under it: kept a step clear (cut down if it must be), whatever the grade does round it
      p.cuts.push({ tile, cap: Math.floor(deckAt(br, j, LL) / STEP + 1e-6) - 1 });
    }
    p.bridges.push(br);
  }
  return null;
}

/** The least height in steps a deck may pass over this tile at. */
function needUnder(w: World, t: number): number {
  const wet = w.water[t] >= 0 || waterDepth(w, t) > 0;
  if (w.rail[t] & RailBit.Track) return maxCorner(w, t) + UNDER - 0.5;
  if (w.road[t]) return maxCorner(w, t) + UNDER - 0.5;
  if (wet) return Math.max(w.water[t], maxCorner(w, t)) + 1;
  return maxCorner(w, t) + 1;
}

// ---------------- the ground ----------------

/**
 * Corner heights the plan sets, by tile × 4 + corner: the graded blocks, the underpass strips and the interchanges'
 * ground. Each is set from its vertex alone, so tiles that share a vertex agree; where two layers meet at a vertex
 * the first set wins.
 */
class Grade {
  corner = new Map<number, number>();
  vertex = new Map<number, number>();
  /** Tiles that carry a set surface (the road's own ground), to keep everything else off them. */
  owned = new Set<number>();
  /** Tiles the easing leaves alone: the ground under the decks. */
  keep = new Set<number>();
  setTile(t: number, h: (vx: number, vz: number) => number): void {
    const x = t % N, z = (t - x) / N;
    for (let q = 0; q < 4; q++) {
      const vx = x + (q === 1 || q === 2 ? 1 : 0), vz = z + (q >= 2 ? 1 : 0);
      const vk = vz * (N + 1) + vx;
      let v = this.vertex.get(vk);
      if (v === undefined) { v = h(vx, vz); this.vertex.set(vk, v); }
      this.corner.set(t * 4 + q, v);
    }
    this.owned.add(t);
  }
  /** Set a tile whose corners may disagree with what is already set (a wall under a deck). */
  setTileOwn(t: number, h: (vx: number, vz: number) => number): void {
    const x = t % N, z = (t - x) / N;
    for (let q = 0; q < 4; q++) {
      const vx = x + (q === 1 || q === 2 ? 1 : 0), vz = z + (q >= 2 ? 1 : 0);
      const v = h(vx, vz);
      this.corner.set(t * 4 + q, v);
      const vk = vz * (N + 1) + vx;
      if (!this.vertex.has(vk)) this.vertex.set(vk, v);
    }
    this.owned.add(t);
  }
}

/** May the plan reshape this tile's ground? */
function shapeable(w: World, t: number): boolean {
  return w.water[t] < 0 && waterDepth(w, t) === 0 && !(w.flags[t] & (Flag.River | Flag.Stream | Flag.Poi)) && !w.rail[t] && !w.blocked[t]
    && !w.road[t] && !w.deckAxis[t] && !(w.feature[t] && w.feature[t] !== Feature.Beach) && w.biome[t] !== Biome.Ocean;
}

/** How far off a diagonal's line its ribbon's tiles reach, by their middles: half its width and a tile's half-diagonal. */
const RIBBON_REACH = 2.25;

/** A diagonal's way along at node k, as a unit vector: the two steps either side of it, one along x, one along z. */
function diagDir(p: RoutePlan, k: number): [number, number] {
  const a = p.nodes[Math.max(0, k - 1)], b = p.nodes[Math.min(p.nodes.length - 1, k + 1)];
  let dx = nodeX(b) - nodeX(a), dz = nodeZ(b) - nodeZ(a);
  // at a staircase's end only one step is diagonal's: take the two on the inside
  if (Math.abs(dx) !== 1 || Math.abs(dz) !== 1) {
    const j = p.diag[k - 1] ? k - 1 : k + 1;
    const a2 = p.nodes[Math.max(0, j - 1)], b2 = p.nodes[Math.min(p.nodes.length - 1, j + 1)];
    dx = nodeX(b2) - nodeX(a2); dz = nodeZ(b2) - nodeZ(a2);
  }
  return [Math.sign(dx) * Math.SQRT1_2, Math.sign(dz) * Math.SQRT1_2];
}

/** The graded blocks of a route's ground nodes, and the strips under its underpasses. */
function gradeRoute(w: World, p: RoutePlan, gr: Grade): void {
  const n = p.nodes.length;
  const lineQ = (f: number) => {
    // the height at fractional line f (line e between nodes e and e+1), between the two lines either side
    const a = Math.floor(f), t = f - a;
    const at = (e: number) => p.q[Math.max(0, Math.min(p.q.length - 1, e + 2))];
    return Math.round(at(a) * (1 - t) + at(a + 1) * t);
  };
  for (let k = 0; k < n; k++) {
    if (p.air[k]) continue;
    const c = p.nodes[k], cx = nodeX(c) + 0.5, cz = nodeZ(c) + 0.5;
    if (p.diag[k]) {
      // on a diagonal: how far along its 45° line a vertex lies, in nodes (each √½ a tile on from the last)
      const [ux, uz] = diagDir(p, k);
      const heightAt = (vx: number, vz: number) => lineQ(k + ((vx - cx) * ux + (vz - cz) * uz) / Math.SQRT1_2 - 0.5);
      for (const t of nodeTiles(c, 'tri')) if (!gr.owned.has(t)) gr.setTile(t, heightAt);
      // and the tiles its straight 45° ribbon crosses past the staircase's blocks: road all the same
      for (let dz = -3; dz <= 3; dz++) for (let dx = -3; dx <= 3; dx++) {
        const tx = nodeX(c) + dx, tz = nodeZ(c) + dz;
        if (!inB(tx, tz)) continue;
        const t = idx(tx, tz);
        if (gr.owned.has(t) || !shapeable(w, t)) continue;
        const off = Math.abs((tx + 0.5 - cx) * uz - (tz + 0.5 - cz) * ux);
        const along = Math.abs((tx + 0.5 - cx) * ux + (tz + 0.5 - cz) * uz);
        if (off > RIBBON_REACH || along > 0.75) continue;
        gr.setTile(t, heightAt);
        p.arcTiles.add(t);
      }
      continue;
    }
    const d = p.dirs[k];
    for (const t of nodeTiles(c, 'tri')) {
      if (gr.owned.has(t)) continue;
      gr.setTile(t, (vx, vz) => {
        const o = (vx - cx) * DX[d] + (vz - cz) * DZ[d];
        const e = k + Math.round(o - 0.5);
        return p.q[Math.max(0, Math.min(p.q.length - 1, e + 2))];
      });
    }
  }
  // the bends: every tile their arcs cross, level at the bend's height (its whole reach is level: profile)
  for (const [k, r] of p.bends) {
    const h = p.q[k + 2];
    for (const t of arcTilesOf(p, k, r)) {
      if (t < 0 || gr.owned.has(t) || !shapeable(w, t)) continue;
      gr.setTileOwn(t, () => h);
      p.arcTiles.add(t);
    }
  }
  // the strips: the three tiles of path at each underpass, across, graded from the ground under the deck back out
  for (const u of p.unders) {
    const half = p.exits.some((e) => e.k === u.k) ? ROAD_HALF + 1 : STRIP_HALF;
    const end = (s: number) => { const t = across(p, u.k, s * half); return t >= 0 ? tileMean(w, t) : u.g; };
    const e0 = end(-1), e1 = end(1);
    const ad = acrossDir(p.dirs[u.k]), cx = nodeX(p.nodes[u.k]) + 0.5, cz = nodeZ(p.nodes[u.k]) + 0.5;
    const at = (vx: number, vz: number) => {
      const s = (vx - cx) * DX[ad] + (vz - cz) * DZ[ad];
      const a = Math.abs(s);
      if (a <= 1.5) return u.g;
      const far = s < 0 ? e0 : e1;
      const f = Math.min(1, (a - 1.5) / (half - 1.5));
      // never steeper than a step a tile
      const h = u.g + (far - u.g) * f;
      return Math.round(Math.max(u.g - (a - 1.5), Math.min(u.g + (a - 1.5), h)));
    };
    for (let a = -1; a <= 1; a++) for (let s = -half; s <= half; s++) {
      const t = across(p, u.k + a, s);
      if (t < 0 || gr.owned.has(t) || !shapeable(w, t)) continue;
      gr.setTileOwn(t, at);
    }
  }
}

/** Ease the ground round everything set back to its own lie, then write it all into the world. */
function applyGrade(w: World, gr: Grade): void {
  const V = N + 1;
  const dist = new Int8Array(V * V).fill(-1);
  const T = new Float64Array(V * V);
  let frontier: number[] = [];
  for (const [vk, h] of gr.vertex) { dist[vk] = 0; T[vk] = h; frontier.push(vk); }
  for (let r = 1; r <= EASE; r++) {
    const next: number[] = [];
    for (const vk of frontier) {
      const vx = vk % V, vz = (vk - vx) / V;
      for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
        const nx = vx + dx, nz = vz + dz;
        if (nx < 0 || nz < 0 || nx > N || nz > N) continue;
        const nk = nz * V + nx;
        if (dist[nk] >= 0) continue;
        dist[nk] = r; T[nk] = T[vk];
        next.push(nk);
      }
    }
    frontier = next;
  }
  const c = w.corners;
  for (const [ck, h] of gr.corner) c[ck] = h;
  // the eased ring: every tile near enough that the plan doesn't own, where the ground may be moved
  const seen = new Uint8Array(N * N);
  for (let vk = 0; vk < V * V; vk++) {
    if (dist[vk] < 0) continue;
    const vx = vk % V, vz = (vk - vx) / V;
    for (const [tx, tz] of [[vx, vz], [vx - 1, vz], [vx - 1, vz - 1], [vx, vz - 1]] as const) {
      if (!inB(tx, tz)) continue;
      const t = idx(tx, tz);
      if (seen[t] || gr.owned.has(t) || gr.keep.has(t)) continue;
      seen[t] = 1;
      if (!shapeable(w, t)) continue;
      for (let q = 0; q < 4; q++) {
        const ux = tx + (q === 1 || q === 2 ? 1 : 0), uz = tz + (q >= 2 ? 1 : 0);
        const uk = uz * V + ux;
        const d = dist[uk];
        if (d < 0) continue;
        // the county's own border line keeps its shared heights, save where the road itself meets it
        const edge = ux === 0 || uz === 0 || ux === N || uz === N;
        if (edge) continue;
        const orig = c[t * 4 + q];
        c[t * 4 + q] = d === 0 ? T[uk] : Math.round(T[uk] + (orig - T[uk]) * (d / (EASE + 1)));
      }
    }
  }
}

// ---------------- the interchanges ----------------

/** A slip road's tiles: a straight staircase from a to b, each tile a side-step from the last (as roads.ts lineTiles). */
function lineTiles(a: number, b: number): number[] {
  const ax = a % N, az = (a - ax) / N, bx = b % N, bz = (b - bx) / N;
  const nx = Math.abs(bx - ax), nz = Math.abs(bz - az), sx = Math.sign(bx - ax), sz = Math.sign(bz - az);
  const out = [a];
  let x = ax, z = az;
  for (let ix = 0, iz = 0; ix < nx || iz < nz;) {
    if (iz >= nz || (ix < nx && (0.5 + ix) / nx <= (0.5 + iz) / nz)) { x += sx; ix++; } else { z += sz; iz++; }
    out.push(z * N + x);
  }
  return out;
}

/** The county road under an interchange, across from -ROAD_HALF to +ROAD_HALF. */
function exitRoadNodes(p: RoutePlan, e: ExitPlan): number[] {
  const out: number[] = [];
  for (let s = -ROAD_HALF; s <= ROAD_HALF; s++) { const t = across(p, e.k, s); if (t >= 0) out.push(t); }
  return out;
}

/**
 * Which way the carriageway on side s of a road running along D flows (traffic keeps right: world/roads.ts applyRoad
 * lays an x-running road's low-z row eastbound, a z-running road's low-x column northbound).
 */
const flowOf = (D: number, s: number): number => (D % 2 === 0 ? (s < 0 ? 0 : 2) : (s < 0 ? 3 : 1));

/** How far along and out a slip road's taper runs (as world/roads.ts rampTaper: 1 in 3). */
const TAPER_LONG = 6, TAPER_OUT = 2;

/**
 * The four slip roads of a diamond: for each carriageway, an off-ramp leaving it RAMP_REACH tiles before the county
 * road and running to meet it RAMP_MEET out, and an on-ramp from there back onto it RAMP_REACH beyond. Each leaves
 * (or joins) along the traffic at the taper the builder's ramps use; worked out before anything is laid, so their
 * ground is graded with the interstate's.
 */
function rampNodes(p: RoutePlan, e: ExitPlan): number[][] | null {
  const out: number[][] = [];
  const D = p.dirs[e.k], ad = acrossDir(D);
  for (const s of [-1, 1]) {
    const flow = flowOf(D, s), sigma = flow === D ? 1 : -1;
    const outward = s < 0 ? (ad + 2) % 4 : ad;
    const meet = across(p, e.k, s * RAMP_MEET);
    const up = across(p, e.k - sigma * e.reach, s), down = across(p, e.k + sigma * e.reach, s);
    if (meet < 0 || up < 0 || down < 0) return null;
    const off = (t: number, sign: number) => {
      const x = nodeX(t) + DX[flow] * TAPER_LONG * sign + DX[outward] * TAPER_OUT, z = nodeZ(t) + DZ[flow] * TAPER_LONG * sign + DZ[outward] * TAPER_OUT;
      return inB(x, z) ? idx(x, z) : -1;
    };
    const pOff = off(up, 1), pOn = off(down, -1);
    if (pOff < 0 || pOn < 0) return null;
    out.push([...lineTiles(up, pOff), ...lineTiles(pOff, meet).slice(1)]);
    out.push([...lineTiles(meet, pOn), ...lineTiles(pOn, down).slice(1)]);
  }
  return out;
}

/** Ground for the ramps: each tile off the interstate graded along the straight line from its carriageway end to the county road. */
function gradeRamps(w: World, ramps: number[][], gr: Grade): void {
  for (const r of ramps) {
    // which end is on the interstate: the one whose height is already set
    const a = r[0], b = r[r.length - 1];
    const ax = nodeX(a) + 0.5, az = nodeZ(a) + 0.5, bx = nodeX(b) + 0.5, bz = nodeZ(b) + 0.5;
    const ha = tileHeight(gr, w, a), hb = tileHeight(gr, w, b);
    const len2 = (bx - ax) ** 2 + (bz - az) ** 2 || 1;
    for (const t of r) {
      if (gr.owned.has(t) || !shapeable(w, t)) continue;
      gr.setTile(t, (vx, vz) => {
        const f = Math.max(0, Math.min(1, ((vx - ax) * (bx - ax) + (vz - az) * (bz - az)) / len2));
        return Math.round(ha + (hb - ha) * f);
      });
    }
  }
}

/** A tile's mean height as the grade will leave it. */
function tileHeight(gr: Grade, w: World, t: number): number {
  let s = 0;
  for (let q = 0; q < 4; q++) s += gr.corner.get(t * 4 + q) ?? w.corners[t * 4 + q];
  return s / 4;
}

// ---------------- where two routes cross ----------------

/** Path tiles from the crossing to each route's exit at a junction, tried in this order. */
const JUNCTION_AT = [30, 26, 22, 34, 18, 38, 16, 44];
/** Tiles of straight a north–south route runs either side of where it crosses an east–west one at a junction. */
const JUNCTION_STRAIGHT = 40, JUNCTION_MIN = 26;
/** The farthest apart two routes' exits may be for a link road of their own to join them, in tiles. */
const JUNCTION_LINK_MAX = 220;

/**
 * Where two routes cross in one county (the east–west laid first, the north–south flying over it): a diamond on each,
 * the same distance out from the crossing on the same side of it, whose county roads a short link road joins, so
 * every way from one route onto the other is off at one exit, along the link and on at the other. The quadrant and
 * distance that both routes have clear straight road for, nearest first. Sets each plan's exit and returns the two
 * nodes the link road runs between (an end of each county road), or null where none fits.
 */
function placeJunction(ctx: InterstateCtx, gE: Ground, pE: RoutePlan, gN: Ground, pN: RoutePlan): { a: number; b: number } | null {
  const { towns } = ctx;
  // the crossing: the north–south route's node on the east–west route's centre line
  const onE = new Map(pE.nodes.map((t, k) => [t, k]));
  let kE = -1, kN = -1;
  for (let k = 0; k < pN.nodes.length; k++) { const e = onE.get(pN.nodes[k]); if (e !== undefined) { kE = e; kN = k; break; } }
  if (kE < 0) return null;
  const tE = crossingTests(gE, pE), tN = crossingTests(gN, pN);
  const nearestTown = (t: number) => {
    let best = -1, bd = Infinity;
    towns.forEach((tw, i) => { const d = Math.hypot(nodeX(t) - tw.x0 - tw.size / 2, nodeZ(t) - tw.z0 - tw.size / 2); if (d < bd) { bd = d; best = i; } });
    return best;
  };
  for (const D of JUNCTION_AT) {
    for (const sE of [1, -1]) for (const sN of [1, -1]) for (const reach of [RAMP_REACH, RAMP_SHORT, RAMP_LEAST]) {
      const ke = kE + sE * D, kn = kN + sN * D;
      if (ke < 0 || kn < 0 || ke >= pE.nodes.length || kn >= pN.nodes.length) continue;
      // each exit's slip roads clear of the crossing's deck, and the stretch between straight
      if (D < reach + 8) continue;
      if (!straightAround(pE, kE + sE * Math.floor(D / 2), Math.ceil(D / 2))) continue;
      if (!straightAround(pN, kN + sN * Math.floor(D / 2), Math.ceil(D / 2))) continue;
      if (!tE.exitAt(ke, reach)) continue;
      if (!tN.exitAt(kn, reach)) continue;
      const eE: ExitPlan = { k: ke, town: nearestTown(pE.nodes[ke]), number: 0, reach };
      const eN: ExitPlan = { k: kn, town: nearestTown(pN.nodes[kn]), number: 0, reach };
      const rE = exitRoadNodes(pE, eE), rN = exitRoadNodes(pN, eN);
      // the ends of the two county roads that face each other across the quadrant
      const toward = (r: number[], t: number) => (Math.hypot(nodeX(r[0]) - nodeX(t), nodeZ(r[0]) - nodeZ(t)) <= Math.hypot(nodeX(r[r.length - 1]) - nodeX(t), nodeZ(r[r.length - 1]) - nodeZ(t)) ? r[0] : r[r.length - 1]);
      const a = toward(rE, pN.nodes[kn]), b = toward(rN, pE.nodes[ke]);
      pE.exits = [eE]; pN.exits = [eN];
      pE.junction = { to: routeLabel(pN.line.number), at: kE }; pN.junction = { to: routeLabel(pE.line.number), at: kN };
      return { a, b };
    }
  }
  return null;
}

// ---------------- the signs ----------------

/** A sign beside node k of the path, `u` tiles across from its middle, its face looking along heading d. */
function signAt(p: RoutePlan, kind: InterstateSign['kind'], k: number, u: number, d: number, exit?: number): InterstateSign | null {
  if (k < 0 || k >= p.nodes.length) return null;
  const ad = acrossDir(p.dirs[k]);
  const x = nodeX(p.nodes[k]) + 0.5 + DX[ad] * u, z = nodeZ(p.nodes[k]) + 0.5 + DZ[ad] * u;
  if (x < 1 || z < 1 || x > N - 1 || z > N - 1) return null;
  return { kind, x, z, fx: DX[d], fz: DZ[d], ...(exit !== undefined ? { exit } : {}) };
}

/** An interchange's signs: for each carriageway, its exit board a little before the off-ramp leaves, on the verge, facing the traffic; and a route shield where the on-ramp leaves the county road. */
function exitSigns(p: RoutePlan, e: ExitPlan, exit: number): InterstateSign[] {
  const out: (InterstateSign | null)[] = [];
  const D = p.dirs[e.k], ad = acrossDir(D);
  for (const s of [-1, 1]) {
    const flow = flowOf(D, s), sigma = flow === D ? 1 : -1;
    out.push(signAt(p, 'exit', e.k - sigma * (e.reach + 7), s * 2.9, (flow + 2) % 4, exit));
    // beside the county road, where the on-ramp leaves it, facing the traffic coming down it from the town side
    const outward = s < 0 ? (ad + 2) % 4 : ad;
    out.push(signAt(p, 'shield', e.k + sigma * 2, s * (RAMP_MEET + 2), outward));
  }
  return out.filter((x): x is InterstateSign => x !== null);
}

/** The route's board just inside each border it comes over, beside the carriageway coming in, facing it. */
function routeSigns(p: RoutePlan): InterstateSign[] {
  const out: (InterstateSign | null)[] = [];
  const n = p.nodes.length;
  for (const [k, inward] of [[STUB - 3, p.dirs[STUB - 3]], [n - STUB + 2, (p.dirs[n - STUB + 2] + 2) % 4]] as const) {
    if (k === n - STUB + 2 && p.line.sides.length < 2) continue;
    // the carriageway that runs inward is the one whose traffic flows that way
    const D = p.dirs[k];
    const s = flowOf(D, -1) === inward ? -1 : 1;
    out.push(signAt(p, 'route', k, s * 2.9, (inward + 2) % 4));
  }
  return out.filter((x): x is InterstateSign => x !== null);
}

// ---------------- the county ----------------

/** What layInterstates hands on to finishInterstates once the towns stand. */
export interface InterstatePending {
  /** County-road ends to join to the network (an interchange's road, a terminus's), with that road's own tiles. */
  joins: { from: number; own: number[]; town?: TownPlan }[];
  /** Exits to name for the town they serve once it is built and named. */
  names: { rec: { town: string }; town: TownPlan }[];
}

/**
 * Plan, grade and lay every interstate through this county (before the towns are built). Returns the ends of the
 * county roads its interchanges and termini leave, for finishInterstates to join up once the towns stand.
 */
export function layInterstates(ctx: InterstateCtx): InterstatePending {
  const { w, seedHash } = ctx;
  const pending: InterstatePending = { joins: [], names: [] };
  const lines = interstateLines(seedHash, w.cx, w.cz);
  if (!lines.length) return pending;
  const infos: InterstateInfo[] = [];
  const order = [...lines].sort((a, b) => a.axis - b.axis);
  // each exit's county road, by route and its place in that route's exits: a junction joins two of them
  const exitRoads: { key: string; road: number[]; rec: number }[] = [];
  // where two routes cross here, both are planned before either is laid, so their interchange can be placed
  // (the north–south route planned with the east–west one's line in its way, to fly over it)
  const pre = new Map<string, RoutePlan>();
  let link: { a: number; b: number } | null = null;
  if (order.length === 2 && !order[0].terminus && !order[1].terminus) {
    const gE = groundOf(ctx);
    const pE = planRoute(ctx, gE, order[0]);
    if (typeof pE !== 'string') {
      planBends(gE, pE);
      const gN = groundOf(ctx);
      // it may cross only where the east–west line runs straight a long way to one side at least, so an exit
      // can stand on that straight (anywhere else the east–west line is a wall to it)
      const n = pE.nodes.length, runBack = new Int32Array(n), runOn = new Int32Array(n);
      const square = (k: number) => !pE.diag[k] && !pE.bendZone[k] && (k === 0 || pE.dirs[k - 1] === pE.dirs[k]);
      for (let k = 1; k < n; k++) runBack[k] = square(k) ? runBack[k - 1] + 1 : 0;
      for (let k = n - 2; k >= 0; k--) runOn[k] = square(k + 1) ? runOn[k + 1] + 1 : 0;
      const need = 16 + RAMP_LEAST + 4;
      for (let k = 0; k < n; k++) {
        const crossable = runBack[k] >= 6 && runOn[k] >= 6 && (runBack[k] >= need || runOn[k] >= need);
        for (const t of nodeTiles(pE.nodes[k], 'tri')) {
          if (gN.hard[t]) continue;
          if (crossable) { gN.bridge[t] = 1; gN.cost[t] = Math.max(gN.cost[t], 4); } else { gN.cost[t] = Infinity; gN.hard[t] = 1; }
        }
      }
      // where it crosses: a point on a long straight of the first route, square to the second, in line with one of the
      // second's border stubs or nearest the middle of its way through; the second made to run straight either side of it
      // the second route's way through: in from its first border, and the stub ends it runs between
      const sides = order[1].sides;
      const dIn = (sides[0] + 2) % 4, axis2 = dIn % 2;
      const stubOf = (d: number): [number, number] => {
        const at = interstateAt(seedHash, w.cx, w.cz, d, order[1].key), bn = borderNode(d, at);
        return [nodeX(bn.node) + DX[bn.inward] * STUB, nodeZ(bn.node) + DZ[bn.inward] * STUB];
      };
      const s0 = stubOf(sides[0]), s1 = stubOf(sides[1]);
      const along = (q: [number, number]) => (axis2 === 0 ? q[0] : q[1]), acrossOf = (q: [number, number]) => (axis2 === 0 ? q[1] : q[0]);
      const R = JUNCTION_STRAIGHT;
      // a straight either side of the crossing: as long as R, short of the room it needs to come across from its
      // stub, or all the way to the stub where the stub is already in line
      const reachTo = (c: [number, number], st: [number, number]) => {
        const dist = Math.abs(along(c) - along(st)), off = Math.abs(acrossOf(c) - acrossOf(st));
        return off === 0 ? dist : Math.min(R, dist - 24);
      };
      const cands: { k: number; before: number; after: number; score: number }[] = [];
      for (let k = 0; k < n; k++) {
        // a crossing square to the first route, on a long straight of it
        if (pE.dirs[k] % 2 === axis2 || !(runBack[k] >= 6 && runOn[k] >= 6 && (runBack[k] >= need || runOn[k] >= need))) continue;
        const c: [number, number] = [nodeX(pE.nodes[k]), nodeZ(pE.nodes[k])];
        const before = reachTo(c, s0), after = reachTo(c, s1);
        if (Math.max(before, after) < JUNCTION_MIN || Math.min(before, after) < 8) continue;
        // in line with a stub first, then nearest the straight way between them
        const mid = (acrossOf(s0) + acrossOf(s1)) / 2;
        cands.push({ k, before, after, score: Math.abs(acrossOf(c) - mid) - (acrossOf(c) === acrossOf(s0) || acrossOf(c) === acrossOf(s1) ? 1000 : 0) });
      }
      cands.sort((p, q) => p.score - q.score);
      let pN: RoutePlan | string = 'no crossing';
      const tried: number[] = [];
      for (const cd of cands) {
        if (tried.length >= 8) break;
        const x = nodeX(pE.nodes[cd.k]), z = nodeZ(pE.nodes[cd.k]);
        const q = axis2 === 0 ? z : x;
        if (tried.some((t) => Math.abs(t - q) < 6)) continue;
        tried.push(q);
        const via: Via = { ax: x - DX[dIn] * cd.before, az: z - DZ[dIn] * cd.before, bx: x + DX[dIn] * cd.after, bz: z + DZ[dIn] * cd.after, d: dIn };
        pN = planRoute(ctx, gN, order[1], true, via);
        if (typeof pN !== 'string') break;
      }
      if (typeof pN === 'string') pN = planRoute(ctx, gN, order[1]);
      if (typeof pN !== 'string') {
        planBends(gN, pN);
        // the east–west exit's room checked with the north–south line in it too
        for (const n of pN.nodes) for (const t of nodeTiles(n, 'tri')) if (!gE.hard[t]) gE.bridge[t] = 1;
        link = placeJunction(ctx, gE, pE, gN, pN);
        if (link) { pre.set(order[0].key, pE); pre.set(order[1].key, pN); }
      }
    }
  }
  // the east–west route first: a north–south one through the same county flies over it
  for (const line of order) {
    const info: InterstateInfo = { key: line.key, number: line.number, name: line.name, label: routeLabel(line.number), road: -1, sides: line.sides, terminus: line.terminus, exits: [], decks: 0, signs: [] };
    infos.push(info);
    const g = groundOf(ctx);
    let p: RoutePlan | string = pre.get(line.key) ?? planRoute(ctx, g, line);
    if (typeof p === 'string') { info.failed = p; continue; }
    if (!pre.has(line.key)) planBends(g, p);
    placeCrossings(ctx, g, p);
    // a line so diagonal it leaves no straight stretch for an exit is planned again square
    if (!p.exits.length && p.endTown < 0 && !p.junction && p.diag.some((v) => v)) {
      const sq = planRoute(ctx, g, line, false);
      if (typeof sq !== 'string') { planBends(g, sq); placeCrossings(ctx, g, sq); if (sq.exits.length) p = sq; }
    }
    let why = profile(ctx, g, p) ?? decks(ctx, p);
    // a diagonal line the ground won't grade is planned again square
    if (why && !p.junction && p.diag.some((v) => v)) {
      const sq = planRoute(ctx, g, line, false);
      if (typeof sq !== 'string') {
        planBends(g, sq);
        placeCrossings(ctx, g, sq);
        const why2 = profile(ctx, g, sq) ?? decks(ctx, sq);        if (!why2) { p = sq; why = null; }
      }
    }
    if (why) { info.failed = why; continue; }
    // the interchanges' slip roads, worked out now so their ground is graded with the road's
    const exits = p.exits.map((e) => ({ e, road: exitRoadNodes(p, e), ramps: rampNodes(p, e) }));
    const gr = new Grade();
    for (const t of p.deckTiles) gr.keep.add(t);
    gradeRoute(w, p, gr);
    for (const x of exits) if (x.ramps) gradeRamps(w, x.ramps, gr);
    applyGrade(w, gr);
    for (const { tile, cap } of p.cuts) for (let q = 0; q < 4; q++) w.corners[tile * 4 + q] = Math.min(w.corners[tile * 4 + q], cap);
    for (const t of gr.owned) { w.flags[t] = (w.flags[t] & ~Flag.Field) | Flag.Corridor; w.fieldId[t] = -1; }
    const road = layRoad(w, RoadType.Interstate, p.nodes, -1, p.bridges);
    road.limited = true;
    if (p.bends.size || p.arcTiles.size) {
      // the bends: their radii kept on the road, and the ground their arcs and its diagonals' ribbons cross made road too
      road.bends = [...p.bends];
      const own = new Set(road.tiles);
      for (const t of p.arcTiles) if (!own.has(t)) road.tiles.push(t);
      rebuildRoadTables(w);
    }
    info.road = w.roads.indexOf(road);
    info.decks = p.bridges.length;
    for (const { e, road: cr, ramps } of exits) {
      if (!ramps) continue;
      layRoad(w, RoadType.TwoLane, cr, -1);
      exitRoads.push({ key: line.key, road: cr, rec: info.exits.length });
      for (const r of ramps) {
        const rr = layRoad(w, RoadType.Ramp, r, -1);
        rr.limited = true;
      }
      const t = ctx.towns[e.town];
      // the end nearer the town it serves goes to that town; the other on to whatever road is nearest
      const tc = t ? [t.x0 + t.size / 2, t.z0 + t.size / 2] : [N / 2, N / 2];
      const dEnd = (n: number) => Math.hypot(nodeX(n) - tc[0], nodeZ(n) - tc[1]);
      const [near, far] = dEnd(cr[0]) <= dEnd(cr[cr.length - 1]) ? [cr[0], cr[cr.length - 1]] : [cr[cr.length - 1], cr[0]];
      pending.joins.push({ from: near, own: cr, town: t }, { from: far, own: cr });
      const mid = p.nodes[e.k];
      const rec: InterstateInfo['exits'][number] = { number: e.number, town: '', x: nodeX(mid) + 0.5, z: nodeZ(mid) + 0.5, ...(p.junction ? { to: p.junction.to } : {}) };
      info.exits.push(rec);
      if (t) pending.names.push({ rec, town: t });
      info.signs.push(...exitSigns(p, e, info.exits.length - 1));
    }
    info.signs.push(...routeSigns(p));
    // the end of the line: a two-lane road on from the last node's front, for the town to join
    if (p.endTown >= 0) {
      const last = p.nodes[p.nodes.length - 1], d = p.dirs[p.nodes.length - 1];
      const stub: number[] = [];
      for (let s = 1; s <= 6; s++) {
        const x = nodeX(last) + DX[d] * s, z = nodeZ(last) + DZ[d] * s;
        if (!inB(x, z)) break;
        const t = idx(x, z);
        if (s >= 2 && (w.blocked[t] || w.water[t] >= 0 || w.rail[t])) break;
        stub.push(t);
      }
      if (stub.length >= 3) {
        layRoad(w, RoadType.TwoLane, stub, -1);
        const t = ctx.towns[p.endTown];
        pending.joins.push({ from: stub[stub.length - 1], own: stub, town: t });
        const rec = { number: exitNumber(seedHash, line, w.cx, w.cz, 0), town: '', x: nodeX(last) + 0.5, z: nodeZ(last) + 0.5 };
        info.exits.push(rec);
        if (t) pending.names.push({ rec, town: t });
      }
    }
  }
  // the junction's link road, between the two county roads' facing ends, once both routes are laid
  if (link && infos.every((i) => !i.failed && i.road >= 0)) {
    if (!linkRoadEnds(w, link.a, link.b)) { for (const i of infos) for (const e of i.exits) delete e.to; link = null; }
  } else link = null;
  // where the two couldn't be placed together: the nearest two of their exits' county roads joined by a link road
  // of their own, so there is still a way from one route onto the other without going through a town
  if (!link && order.length === 2 && infos.every((i) => !i.failed && i.road >= 0)) {
    const ends = (r: number[]) => [r[0], r[r.length - 1]];
    const pairs: { a: number; b: number; ra: typeof exitRoads[number]; rb: typeof exitRoads[number]; d: number }[] = [];
    for (const ra of exitRoads.filter((x) => x.key === order[0].key)) for (const rb of exitRoads.filter((x) => x.key === order[1].key)) {
      for (const a of ends(ra.road)) for (const b of ends(rb.road)) {
        const d = Math.hypot(nodeX(a) - nodeX(b), nodeZ(a) - nodeZ(b));
        if (d <= JUNCTION_LINK_MAX) pairs.push({ a, b, ra, rb, d });
      }
    }
    // the nearest pair a road will go between
    for (const pr of pairs.sort((p, q) => p.d - q.d).slice(0, 4)) {
      if (!linkRoadEnds(w, pr.a, pr.b)) continue;
      infos[0].exits[pr.ra.rec].to = infos[1].label;
      infos[1].exits[pr.rb.rec].to = infos[0].label;
      break;
    }
  }
  w.interstates = infos;
  return pending;
}

/**
 * Once the towns stand: name each exit for the town it serves, and join each interchange's county road and each
 * terminus to the county's roads.
 */
export function finishInterstates(w: World, pending: InterstatePending, towns: TownPlan[], join: (from: number, own: number[], town: number) => void): void {
  if (!w.interstates?.length) return;
  for (const { rec, town } of pending.names) rec.town = w.towns.find((b) => b.x0 === town.x0 && b.z0 === town.z0)?.name ?? '';
  for (const info of w.interstates) {
    for (const e of info.exits) {
      if (e.town) continue;
      // the nearest built town
      let best = '', bd = Infinity;
      for (const t of w.towns) {
        const d = Math.hypot(t.x0 + t.size / 2 - e.x, t.z0 + t.size / 2 - e.z);
        if (d < bd) { bd = d; best = t.name; }
      }
      e.town = best;
    }
  }
  void towns;
  for (const j of pending.joins) {
    const built = j.town ? w.towns.find((b) => b.x0 === j.town!.x0 && b.z0 === j.town!.z0) : undefined;
    join(j.from, j.own, built ? built.id : -1);
  }
}

/** Is this road one of the limited-access interstates or their ramps? */
export const isLimited = (r: Road): boolean => !!r.limited;
