import type { CellDoc, ServerMsg, Welcome } from '../../shared/protocol';
import { FRONTIER_METRIC, RANGE_METRIC, type FrontierInfo, type ReachRow } from '../../shared/range';
import type { Online, OnlineExtra } from './online';
import { RUNGS, tilesText, type Range } from '../game/range';
import { esc, money } from '../game/cargoHud';
import { chip, css } from '../game/firmSpec';
import { inScope } from './boardScope';

/**
 * Range online (docs/exploration.html, phase 2), and the Explorers tab of Standings (I).
 *
 * The game tells the server where its home is once a sign-in, and takes the server's if the server already
 * keeps another. The server checks every pose and keeps the boards; this asks for a model's board when the tab
 * shows it, pays First Footing (a cell's discovery money again, for the first fleet ever into it) and frontier
 * bounties when the server says so, and remembers who first reached each cell for the region map.
 *
 * Offline the tab shows the player's own records only.
 */

interface ExplorersHost {
  /** Money in on the books' Exploration line. */
  earn(n: number): void;
  say(title: string, body: string): void;
  float(text: string): void;
  /** The models the fleet owns, most used first: the tab's model picker starts with these. */
  owned(): string[];
  modelName(m: string): string;
  /** A county's name, for the notices and the newspaper. */
  placeName(cx: number, cz: number): string;
  /** The newspaper: a first ever, or the frontier. */
  news(place: string, what: string, weight: number): void;
  /** Something the tab shows has changed. */
  refresh(): void;
  /** The player's own fleet, for its line. */
  me(): { name: string; primary: number; accent: number; logo: string };
}

type View = '' | 'land' | 'water' | 'air' | 'rail' | 'frontier' | 'model';
const KIND_CHIPS: { id: View; label: string }[] = [
  { id: '', label: 'Anything' }, { id: 'land', label: 'Land' }, { id: 'water', label: 'Water' }, { id: 'air', label: 'Air' }, { id: 'rail', label: 'Rail' },
  { id: 'frontier', label: 'Frontier' }, { id: 'model', label: 'By vehicle' },
];
const SHOW = 12;

export class Explorers implements OnlineExtra {
  /** Each model's board as last sent. */
  private boards = new Map<string, { rows: ReachRow[]; you: ReachRow | null; n: number; at: number }>();
  /** Every model that has a board on the server. */
  private models: string[] = [];
  private front: FrontierInfo | null = null;
  /** Who first reached each cell ("cx,cz"), by name, from the cells laid in and the server's news. */
  private firstBy = new Map<string, string>();
  private pendingHome: [number, number] | null = null;
  private homeSent = false;
  private view: View = '';
  private model = '';
  private askedAt = 0;

  constructor(private online: Online, private range: Range, private host: ExplorersHost) {}

  // ---- the session ----

  welcome(w: Welcome): void {
    this.pendingHome = w.rhome ?? null;
    this.front = w.frontier ?? null;
  }

  cell(k: string, doc: CellDoc): void {
    const f = doc.first;
    if (f) this.firstBy.set(k, this.nameOf(f.by));
  }

  ready(): void {
    // the world is up and the save's range is loaded: the server's home wins, if it keeps one
    if (this.pendingHome) { this.range.adoptHome(this.pendingHome[0], this.pendingHome[1]); this.homeSent = true; this.pendingHome = null; }
  }

  frame(): void {
    if (this.homeSent || !this.online.active || !this.range.home) return;
    this.homeSent = true;
    this.online.post({ t: 'rhome', x: this.range.home[0], z: this.range.home[1] });
  }

  forget(): void { /* who first reached a cell is kept for the map, wherever it is */ }

  reset(): void {
    this.boards.clear();
    this.models = [];
    this.front = null;
    this.firstBy.clear();
    this.pendingHome = null;
    this.homeSent = false;
  }

  got(m: ServerMsg): boolean {
    switch (m.t) {
      case 'rhome': this.range.adoptHome(m.x, m.z); this.homeSent = true; return true;
      case 'reach':
        this.boards.set(m.m, { rows: m.rows, you: m.you, n: m.n, at: performance.now() });
        this.models = m.models;
        this.host.refresh();
        return true;
      case 'frontier': this.front = m.f; this.host.refresh(); return true;
      case 'first': {
        const name = m.who.brand?.name ?? m.who.name;
        this.firstBy.set(m.c, name);
        if (m.who.id === this.online.me?.id) {
          const [cx, cz] = m.c.split(',').map(Number);
          const pay = this.range.firstFooting(cx, cz, !!m.sea);
          const place = this.host.placeName(cx, cz);
          this.host.say('First Footing', `No fleet had ever reached ${place} before you · ${money(pay)} more`);
          this.host.news(place, 'the first fleet ever to get there', 3);
        }
        return true;
      }
      case 'bounty': {
        if (m.who.id === this.online.me?.id) {
          this.host.earn(m.prize);
          this.host.float(`+${money(m.prize)} Frontier bounty`);
          this.host.say('Frontier bounty', `${money(m.prize)} for reaching ${m.ring} counties out from the middle of the world before anyone else`);
          this.host.news(`${m.ring} counties out from the middle of the world`, 'further than any fleet had been', 4);
        }
        return true;
      }
      default: return false;
    }
  }

  private nameOf(pid: string): string {
    const w = this.online.people.get(pid);
    return w?.brand?.name ?? w?.name ?? 'another fleet';
  }

  /** Who first set foot in a cell, for the region map: null if nobody is known to have. */
  firstOf(cx: number, cz: number): string | null { return this.firstBy.get(`${cx},${cz}`) ?? null; }

  // ---- the tab ----

  /** The tab has been shown, or its view changed: ask for what it needs. */
  opened(): void {
    if (this.view === 'model') this.ask(this.pickModel());
  }

  private ask(m: string): void {
    if (!m || !this.online.active) return;
    const now = performance.now();
    const had = this.boards.get(m);
    if (had && now - had.at < 4000 && now - this.askedAt < 4000) return;
    this.askedAt = now;
    this.online.post({ t: 'reach', m });
  }

  /** The model the tab shows: the one picked, else the one driven furthest. */
  private pickModel(): string {
    if (this.model) return this.model;
    const best = Object.entries(this.range.model).sort((a, b) => b[1] - a[1])[0];
    this.model = best?.[0] ?? this.host.owned()[0] ?? 'tomato';
    return this.model;
  }

  press(target: HTMLElement): boolean {
    const b = target.closest('[data-xv],[data-xm]') as HTMLElement | null;
    if (!b) return false;
    if (b.dataset.xv !== undefined) this.view = b.dataset.xv as View;
    if (b.dataset.xm) { this.model = b.dataset.xm; this.view = 'model'; }
    this.opened();
    return true;
  }

  /** Every so often while the tab is up: a model's board is asked for again. */
  tick(): void { if (this.view === 'model') this.ask(this.pickModel()); }

  html(rows: () => { id: string; name: string; primary: number; accent: number; logo: string; v?: Record<string, number> }[], me: string | null): string {
    const on = this.online.active;
    const chips = `<div class="scope xchips">${KIND_CHIPS.map((c) => `<button type="button" data-xv="${c.id}" class="${this.view === c.id ? 'on' : ''}">${c.label}</button>`).join('')}</div>`;
    const body = this.view === 'model' ? this.modelHtml(on) : this.kindHtml(on, rows(), me);
    return `${chips}${body}${this.frontierHtml(on)}`;
  }

  /** The best from home in a kind (or from the origin, Frontier): every player's line from the board, yours live. */
  private kindHtml(on: boolean, rows: { id: string; name: string; primary: number; accent: number; logo: string; v?: Record<string, number> }[], me: string | null): string {
    const view = this.view as Exclude<View, 'model'>;
    const key = view === 'frontier' ? FRONTIER_METRIC : RANGE_METRIC[view];
    const mine = view === 'frontier' ? this.range.frontier : view === '' ? this.range.all : this.range.kind[view] ?? 0;
    const label = view === 'frontier' ? 'from the middle of the world' : view === '' ? 'from home, in anything' : `from home, on ${view === 'land' ? 'land' : view === 'water' ? 'water' : view === 'air' ? 'the air' : 'the rails'}`;
    const list: { name: string; livery: [number, number]; logo: string; d: number; you: boolean; pid?: string }[] = on ? rows.filter((r) => r.id !== me && (r.v?.[key] ?? 0) > 0 && inScope(r.id)).map((r) => ({ name: r.name, livery: [r.primary, r.accent] as [number, number], logo: r.logo, d: r.v![key], you: false, pid: r.id })) : [];
    const you = this.host.me();
    list.push({ name: you.name, livery: [you.primary, you.accent], logo: you.logo, d: Math.floor(mine), you: true });
    list.sort((a, b) => b.d - a.d);
    const place = list.findIndex((e) => e.you) + 1;
    const lead = mine > 0
      ? `Your best ${esc(label)}: <b>${esc(tilesText(mine))}</b>${on ? ` · <b>#${place} of ${list.length}</b>` : ''}`
      : `Nothing yet ${esc(label)}: drive out and it counts.`;
    return `<div class="lead">${lead}</div>${this.ranking(list)}
      <p class="foot">${view === 'frontier' ? 'Straight-line tiles from tile 0,0, the middle of the world.' : 'Straight-line tiles from your home, at the wheel yourself.'} Teleports, the garage and the airlift don’t count${on ? '; the server checks every tile.' : '.'}</p>`;
  }

  private modelHtml(on: boolean): string {
    const m = this.pickModel();
    this.ask(m);
    const owned = this.host.owned();
    const driven = Object.keys(this.range.model).filter((x) => !owned.includes(x));
    const boarded = this.models.filter((x) => !owned.includes(x) && !driven.includes(x));
    const pick = (ids: string[], dim = false) => ids.map((id) => `<button type="button" data-xm="${esc(id)}" class="${id === m ? 'on' : ''}${dim ? ' dim' : ''}">${esc(this.host.modelName(id))}</button>`).join('');
    const picker = `<div class="scope xmodels">${pick(owned)}${pick(driven)}${pick(boarded, true)}</div>`;
    const mine = this.range.model[m] ?? 0;
    const paid = this.range.paid[m] ?? 0;
    const rungs = RUNGS.map((r, k) => `<span class="chip${paid & (1 << k) ? ' go' : ''}" title="${money(r.pay)}">${esc(r.name)} · ${r.tiles.toLocaleString('en-US')}</span>`).join('');
    const b = this.boards.get(m);
    let list: { name: string; livery: [number, number]; logo: string; d: number; you: boolean; sub?: string; pid?: string }[] = [];
    let lead: string;
    if (on && b) {
      const me = this.online.me?.id;
      list = b.rows.filter((r) => r.by === me || inScope(r.by)).map((r) => ({ name: r.name, livery: [r.brand?.primary ?? 0x7d8a92, r.brand?.accent ?? 0xffffff] as [number, number], logo: r.brand?.logo ?? '', d: r.d, you: r.by === me, pid: r.by, sub: `reached ${r.c[0]},${r.c[1]}` }));
      if (b.you && !list.some((e) => e.you)) list.push({ name: b.you.name, livery: [b.you.brand?.primary ?? 0xe2412f, b.you.brand?.accent ?? 0xffffff], logo: b.you.brand?.logo ?? '', d: b.you.d, you: true, sub: `#${b.you.place}` });
      lead = b.you
        ? `Your ${esc(this.host.modelName(m))}: <b>${esc(tilesText(b.you.d))}</b> · <b>#${b.you.place} of ${b.n}</b>${b.you.place === 1 ? ' · Pathfinder' : ''}`
        : b.n ? `${b.n} fleet${b.n === 1 ? ' has' : 's have'} taken a ${esc(this.host.modelName(m))} out: ${mine > 0 ? `yours is ${esc(tilesText(mine))} so far` : 'take one out to join them'}.`
          : `Nobody has taken a ${esc(this.host.modelName(m))} anywhere yet.`;
    } else {
      const you = this.host.me();
      if (mine > 0) list.push({ name: you.name, livery: [you.primary, you.accent], logo: you.logo, d: Math.floor(mine), you: true });
      lead = mine > 0 ? `Your ${esc(this.host.modelName(m))}: <b>${esc(tilesText(mine))}</b> from home` : on ? 'Asking the server…' : `Your ${esc(this.host.modelName(m))} hasn’t been out yet.`;
    }
    return `${picker}<div class="lead">${lead}</div><div class="xrungs">${rungs}</div>${this.ranking(list)}`;
  }

  private ranking(list: { name: string; livery: [number, number]; logo: string; d: number; you: boolean; sub?: string; pid?: string }[]): string {
    const shown = list.filter((e, k) => k < SHOW || e.you);
    const top = Math.max(1, ...shown.map((e) => e.d));
    return `<ul class="ranking">${shown.map((e) => {
      const place = list.indexOf(e) + 1;
      return `<li class="${e.you ? 'you' : ''}"><span class="nm"><i>${place}</i>${chip(e.livery, e.logo || undefined)}<b${e.pid && !e.you ? ` data-pid="${esc(e.pid)}"` : ''}>${esc(e.name)}</b>${e.you ? ' <small>you</small>' : ''}${e.sub ? `<span class="sub">${esc(e.sub)}</span>` : ''}</span>
        <em>${e.d.toLocaleString('en-US')}</em><span class="bar"><i style="width:${Math.max(1.5, (e.d / top) * 100).toFixed(1)}%;background:${css(e.livery[0])}"></i></span></li>`;
    }).join('')}</ul>`;
  }

  private frontierHtml(on: boolean): string {
    const f = this.front;
    if (!on || !f) return '';
    const held = f.name ? `${esc(f.name)} holds it at ${f.ring} counties out` : `${f.ring} counties out from the middle`;
    return `<p class="xfront">🧭 <b>Frontier</b> · ${held} · first to ${f.open} out wins <b>${money(f.prize)}</b></p>`;
  }
}
