import * as THREE from 'three';
import { N, CHUNK, RoadType, World, heightOnTile, idx } from '../world/tiles';
import { hash2 } from '../world/rng';
import { hex } from '../world/biomes';
import { SolidBuf } from './lamps';
import type { InterstateInfo, InterstateSign } from '../world/interstatePlan';

/**
 * The generated interstates' signs (world/interstatePlan.ts, docs/interstates.html), one chunk at a time: a green
 * exit board on two posts before each off-ramp ("EXIT 12" over the town it serves), a red-white-and-blue route
 * shield where each on-ramp leaves the county road, and the route's own green board just inside each border it
 * crosses ("I-92" over its name). Posts and board backs are the lamps' lit solids; each face is one quad with its
 * words drawn once onto a small canvas, the texture shared by every sign that says the same thing.
 */

const POST = hex(0x8c939b), BACK = hex(0x5d646c);

interface Face { w: number; h: number; y: number; posts: number; draw: (g: CanvasRenderingContext2D, W: number, H: number) => void }

const GREEN = '#1f6b3a', WHITE = '#f4f6f2';

/** The words on a green board: a big top line and a smaller one under it, white on green with a white rim. */
function greenBoard(top: string, sub: string): Face['draw'] {
  return (g, W, H) => {
    g.fillStyle = GREEN; g.fillRect(0, 0, W, H);
    g.strokeStyle = WHITE; g.lineWidth = Math.max(3, H * 0.04);
    g.strokeRect(g.lineWidth, g.lineWidth, W - g.lineWidth * 2, H - g.lineWidth * 2);
    g.fillStyle = WHITE; g.textAlign = 'center'; g.textBaseline = 'middle';
    const fit = (text: string, size: number, y: number) => {
      g.font = `bold ${size}px "Arial Narrow", Arial, sans-serif`;
      const w = g.measureText(text).width, room = W * 0.88;
      if (w > room) g.font = `bold ${Math.floor(size * room / w)}px "Arial Narrow", Arial, sans-serif`;
      g.fillText(text, W / 2, y);
    };
    fit(top, Math.floor(H * 0.4), H * (sub ? 0.36 : 0.5));
    if (sub) fit(sub, Math.floor(H * 0.26), H * 0.74);
  };
}

/** A route shield: a blue body under a red crown, the number in white. */
function shield(number: string): Face['draw'] {
  return (g, W, H) => {
    g.clearRect(0, 0, W, H);
    const path = () => {
      g.beginPath();
      g.moveTo(W * 0.08, H * 0.06); g.lineTo(W * 0.92, H * 0.06);
      g.quadraticCurveTo(W * 0.98, H * 0.55, W * 0.5, H * 0.96);
      g.quadraticCurveTo(W * 0.02, H * 0.55, W * 0.08, H * 0.06);
      g.closePath();
    };
    path(); g.fillStyle = WHITE; g.fill();
    g.save(); path(); g.clip();
    g.fillStyle = '#1d3f8f'; g.fillRect(0, H * 0.3, W, H);
    g.fillStyle = '#c8282e'; g.fillRect(0, 0, W, H * 0.27);
    g.restore();
    g.lineWidth = W * 0.04; g.strokeStyle = WHITE; path(); g.stroke();
    g.fillStyle = WHITE; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.font = `bold ${Math.floor(H * 0.42)}px "Arial Narrow", Arial, sans-serif`;
    g.fillText(number, W / 2, H * 0.6);
    g.font = `bold ${Math.floor(H * 0.14)}px Arial, sans-serif`;
    g.fillText('INTERSTATE', W / 2, H * 0.165);
  };
}

/** Faces drawn so far, by what they say. Signs are few (two or three a county), so they are kept. */
const MATS = new Map<string, THREE.MeshBasicMaterial>();
function faceMaterial(key: string, f: Face): THREE.MeshBasicMaterial {
  let m = MATS.get(key);
  if (m) return m;
  const c = document.createElement('canvas');
  const H = 128, W = Math.round(H * f.w / f.h);
  c.width = W; c.height = H;
  f.draw(c.getContext('2d')!, W, H);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  m = new THREE.MeshBasicMaterial({ map: tex, transparent: true, alphaTest: 0.4, side: THREE.FrontSide });
  MATS.set(key, m);
  return m;
}

/** What a sign says, and its board's size and height, in tile units. */
function faceOf(info: InterstateInfo, s: InterstateSign): { key: string; face: Face } {
  if (s.kind === 'exit') {
    const e = info.exits[s.exit ?? 0];
    // at a junction, the route it leads on to first
    const top = `EXIT ${e?.number ?? ''}`, sub = (e?.to ? `${e.to} · ${e.town}` : e?.town ?? '').toUpperCase();
    return { key: `exit|${top}|${sub}`, face: { w: 1.5, h: 0.6, y: 0.95, posts: 2, draw: greenBoard(top, sub) } };
  }
  if (s.kind === 'shield') {
    return { key: `shield|${info.number}`, face: { w: 0.36, h: 0.4, y: 0.5, posts: 1, draw: shield(String(info.number)) } };
  }
  return { key: `route|${info.label}|${info.name}`, face: { w: 1.4, h: 0.6, y: 0.85, posts: 2, draw: greenBoard(info.label, info.name.toUpperCase()) } };
}

/** An amber message board's words: what a gantry over the interstate tells the traffic under it. */
const MESSAGES = ['BUCKLE UP', 'DRIVE SAFELY', 'FOG POSSIBLE', 'WATCH FOR DEER', 'NEXT SERVICES 12 MI', 'SLOW TRUCKS KEEP RIGHT', 'CARPOOL LANE AHEAD', 'GOOD LUCK OUT THERE'];
function amberBoard(text: string): Face['draw'] {
  return (g, W, H) => {
    g.fillStyle = '#16181a'; g.fillRect(0, 0, W, H);
    g.fillStyle = '#ffb02e'; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.font = `bold ${Math.floor(H * 0.42)}px "Courier New", monospace`;
    const w = g.measureText(text).width;
    if (w > W * 0.9) g.font = `bold ${Math.floor(H * 0.42 * W * 0.9 / w)}px "Courier New", monospace`;
    g.fillText(text, W / 2, H / 2);
  };
}

/** A county's welcome sign: white words on brown, the county's name under them. */
function welcomeBoard(name: string): Face['draw'] {
  return (g, W, H) => {
    g.fillStyle = '#5a3e2a'; g.fillRect(0, 0, W, H);
    g.strokeStyle = '#f2ede2'; g.lineWidth = H * 0.05; g.strokeRect(g.lineWidth, g.lineWidth, W - g.lineWidth * 2, H - g.lineWidth * 2);
    g.fillStyle = '#f2ede2'; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.font = `bold ${Math.floor(H * 0.2)}px Georgia, serif`;
    g.fillText('WELCOME TO', W / 2, H * 0.32);
    g.font = `bold ${Math.floor(H * 0.3)}px Georgia, serif`;
    const w = g.measureText(name).width;
    if (w > W * 0.88) g.font = `bold ${Math.floor(H * 0.3 * W * 0.88 / w)}px Georgia, serif`;
    g.fillText(name, W / 2, H * 0.66);
  };
}

/** Which side of a sign the carriageway is on (+1 to its right looking at its face, -1 to its left), or 0. */
function roadSide(w: World, s: InterstateSign): number {
  const rx = -s.fz, rz = s.fx;
  for (const d of [1, 1.5, 2]) {
    for (const side of [1, -1]) {
      const x = Math.floor(s.x + rx * d * side), z = Math.floor(s.z + rz * d * side);
      if (x >= 0 && z >= 0 && x < N && z < N && w.road[idx(x, z)]) return side;
    }
  }
  return 0;
}

/**
 * A county's welcome signs: one at the kerb of every paved road coming in over its edge, a few tiles in, facing the
 * traffic arriving (the user, 10 Nov 2026). Only the county's own name is read, so either side of a seam says its own.
 */
function welcomeSigns(w: World): { x: number; z: number; fx: number; fz: number }[] {
  const out: { x: number; z: number; fx: number; fz: number }[] = [];
  const IN = 3;
  for (const r of w.roads) {
    if (r.type === RoadType.Dirt || r.type === RoadType.Ramp || r.limited) continue;
    for (const end of [0, r.nodes.length - 1]) {
      const node = r.nodes[end];
      const x = node % N, z = (node - x) / N;
      if (x > 1 && z > 1 && x < N - 2 && z < N - 2) continue;
      // the way into the county from that edge, and the kerb on the incoming traffic's right
      const fx = x <= 1 ? 1 : x >= N - 2 ? -1 : 0, fz = z <= 1 ? 1 : z >= N - 2 ? -1 : 0;
      if (!fx && !fz) continue;
      const kx = -fz, kz = fx;
      const sx = x + 0.5 + fx * IN + kx * 1.1, sz = z + 0.5 + fz * IN + kz * 1.1;
      const tx = Math.floor(sx), tz = Math.floor(sz);
      if (tx < 0 || tz < 0 || tx >= N || tz >= N || w.road[idx(tx, tz)] || w.blocked[idx(tx, tz)] || w.water[idx(tx, tz)] >= 0) continue;
      out.push({ x: sx, z: sz, fx: -fx, fz: -fz });
    }
  }
  return out;
}

/** The signs standing in chunk (cx, cz) of this county, or null. */
export function buildInterstateSignChunk(w: World, cx: number, cz: number): THREE.Group | null {
  const x0 = cx * CHUNK, z0 = cz * CHUNK;
  const solid = new SolidBuf();
  const faces: THREE.Mesh[] = [];
  // the welcome signs, wherever a road comes in over the county's edge
  if (w.name && (cx === 0 || cz === 0 || cx === N / CHUNK - 1 || cz === N / CHUNK - 1)) {
    for (const s of welcomeSigns(w)) {
      if (s.x < x0 || s.x >= x0 + CHUNK || s.z < z0 || s.z >= z0 + CHUNK) continue;
      const tx = Math.min(N - 1, Math.floor(s.x)), tz = Math.min(N - 1, Math.floor(s.z));
      const ground = heightOnTile(w, tx, tz, s.x, s.z);
      const face: Face = { w: 1.1, h: 0.5, y: 0.6, posts: 2, draw: welcomeBoard(w.name.toUpperCase()) };
      const rx = -s.fz, rz = s.fx;
      for (const o of [-0.4, 0.4]) solid.box(s.x + rx * o - s.fx * 0.06, ground - 0.05, s.z + rz * o - s.fz * 0.06, 0.06, face.y + face.h / 2 + 0.05, 0.06, hex(0x6a4a30));
      const m = new THREE.Mesh(new THREE.PlaneGeometry(face.w, face.h), faceMaterial(`welcome|${w.name}`, face));
      m.position.set(s.x, ground + face.y, s.z);
      m.rotation.y = Math.atan2(s.fx, s.fz);
      faces.push(m);
      const back = new THREE.Mesh(new THREE.PlaneGeometry(face.w, face.h), new THREE.MeshBasicMaterial({ color: 0x4a3222 }));
      back.position.set(s.x - s.fx * 0.01, ground + face.y, s.z - s.fz * 0.01);
      back.rotation.y = Math.atan2(-s.fx, -s.fz);
      faces.push(back);
    }
  }
  for (const info of w.interstates ?? []) {
    for (const s of info.signs ?? []) {
      if (s.x < x0 || s.x >= x0 + CHUNK || s.z < z0 || s.z >= z0 + CHUNK) continue;
      const tx = Math.min(N - 1, Math.floor(s.x)), tz = Math.min(N - 1, Math.floor(s.z));
      const ground = heightOnTile(w, tx, tz, s.x, s.z);
      const { key, face } = faceOf(info, s);
      // an exit's board hangs from a gantry over the carriageway (the user, 10 Nov 2026), and one gantry in four
      // carries an amber message board beside it
      const side = s.kind === 'exit' ? roadSide(w, s) : 0;
      if (side) {
        const rx = -s.fz * side, rz = s.fx * side;
        const span = 2.4, top = 1.55;
        for (const o of [0, span]) solid.box(s.x + rx * o, ground - 0.05, s.z + rz * o, 0.08, top + 0.1, 0.08, POST);
        // the truss across: two chords and their bracing
        for (const y of [top - 0.08, top + 0.04]) {
          const a = [s.x, ground + y, s.z] as const, b = [s.x + rx * span, ground + y, s.z + rz * span] as const;
          solid.box((a[0] + b[0]) / 2, a[1], (a[2] + b[2]) / 2, Math.abs(b[0] - a[0]) + 0.05, 0.04, Math.abs(b[2] - a[2]) + 0.05, POST);
        }
        const mid = span * 0.55;
        const m = new THREE.Mesh(new THREE.PlaneGeometry(face.w, face.h), faceMaterial(key, face));
        m.position.set(s.x + rx * mid + s.fx * 0.06, ground + top - 0.12 - face.h / 2, s.z + rz * mid + s.fz * 0.06);
        m.rotation.y = Math.atan2(s.fx, s.fz);
        faces.push(m);
        solid.box(s.x + rx * mid, ground + top - 0.12 - face.h, s.z + rz * mid, Math.abs(rx) * face.w + 0.04, face.h, Math.abs(rz) * face.w + 0.04, BACK);
        if (hash2(Math.floor(s.x), Math.floor(s.z), 4171) < 0.25) {
          const text = MESSAGES[Math.floor(hash2(Math.floor(s.x), Math.floor(s.z), 4172) * MESSAGES.length) % MESSAGES.length];
          const af: Face = { w: 0.9, h: 0.32, y: 0, posts: 0, draw: amberBoard(text) };
          const am = new THREE.Mesh(new THREE.PlaneGeometry(af.w, af.h), faceMaterial(`amber|${text}`, af));
          const at = span * 0.12;
          am.position.set(s.x + rx * at + s.fx * 0.06, ground + top - 0.12 - af.h / 2, s.z + rz * at + s.fz * 0.06);
          am.rotation.y = Math.atan2(s.fx, s.fz);
          faces.push(am);
        }
        continue;
      }
      // across the face: to its right, looking at it
      const rx = -s.fz, rz = s.fx;
      const postH = face.y + face.h / 2;
      const offs = face.posts === 2 ? [-face.w * 0.36, face.w * 0.36] : [0];
      // the posts stand behind the board, so they never cross its words
      for (const o of offs) solid.box(s.x + rx * o - s.fx * 0.08, ground - 0.05, s.z + rz * o - s.fz * 0.08, 0.05, postH + 0.05, 0.05, POST);
      // the board's back, a little behind its face
      const bx = s.x - s.fx * 0.03, bz = s.z - s.fz * 0.03, by = ground + face.y - face.h / 2;
      if (s.kind !== 'shield') {
        const hw = face.w / 2, d = 0.02;
        const P = (u: number, v: number, y: number): [number, number, number] => [bx + rx * u - s.fx * v, y, bz + rz * u - s.fz * v];
        solid.hull([P(-hw, -d, by), P(hw, -d, by), P(hw, d, by), P(-hw, d, by), P(-hw, -d, by + face.h), P(hw, -d, by + face.h), P(hw, d, by + face.h), P(-hw, d, by + face.h)], BACK);
      }
      // the face, a hair in front of the back, looking along (fx, fz)
      const geo = new THREE.PlaneGeometry(face.w, face.h);
      const m = new THREE.Mesh(geo, faceMaterial(key, face));
      m.position.set(s.x + s.fx * 0.005, ground + face.y, s.z + s.fz * 0.005);
      m.rotation.y = Math.atan2(s.fx, s.fz);
      faces.push(m);
    }
  }
  const body = solid.mesh();
  if (!body && !faces.length) return null;
  const g = new THREE.Group();
  if (body) g.add(body);
  for (const f of faces) g.add(f);
  return g;
}
