import type { Building, World } from '../world/tiles';

/**
 * What the story chains have done to the world (docs/storychains.html), for the drawings to show: which
 * launch pad and which dry dock each chain is bound to, and how many of its steps are done. The launch
 * pad stacks its moon rocket a stage at a time over the last four missions of Stargazers, and the dock
 * builds its submarine over the last four of Still Waters. Written by game/story.ts; the chunk over the
 * structure is rebuilt when it changes, so the next drawing picks it up.
 */
/** A structure, by its cell and the corner of its lot (a wonder's buildings have no uid of their own). */
export interface StoryPlace { cx: number; cz: number; bx: number; bz: number }

export const STORY_MARKS: { moon: number; deep: number; moonAt: StoryPlace | null; deepAt: StoryPlace | null; titles: string[] } = {
  moon: 0, deep: 0, moonAt: null, deepAt: null,
  /** The stories' films, oldest first, for the cinemas' marquees (render/marquee.ts). */
  titles: [],
};

/** Steps done in a chain, if this building is the one it is bound to; 0 for every other. */
export function storyStep(chain: 'moon' | 'deep', w: World | null | undefined, b: Building): number {
  const at = chain === 'moon' ? STORY_MARKS.moonAt : STORY_MARKS.deepAt;
  if (!w || !at || at.cx !== w.cx || at.cz !== w.cz || at.bx !== b.x || at.bz !== b.z) return 0;
  return chain === 'moon' ? STORY_MARKS.moon : STORY_MARKS.deep;
}

/** How far the rocket or the submarine has got: 0 before step 17, then 1 to 4 over steps 17 to 20. */
export const buildStage = (steps: number): number => Math.max(0, Math.min(4, steps - 16));
