import { N, type World, type Building } from './tiles';
import { cellKind, continentality, regionAt } from './macro';
import { cell01, hashCell, hashString, mulberry32 } from './rng';
import type { RegionSpec } from './regions';
import type { WorkSite } from './industry';
import { planMustFlat, planWonder } from './wonders';
import { landformName } from './landforms';
import { INFO_080 } from './kinds080';
import { STRONGHOLD_NAME, STRONGHOLD_OF, gateOut, isStronghold, strongholdPlan, type SPlan, type StrongholdKind } from './strongholdPlans';
import { FACTION_IDS, type FactionId } from '../game/factions/factions';
import { DIRS } from './tiles';

/**
 * The factions' strongholds (docs/strongholds.html, 0.8.0): one great walled headquarters per faction, open only to a
 * player the faction counts Honoured. Placement is the hard part, because no county is ever made from its neighbours:
 *
 * - **The home square** (−10…10 on both axes): each faction's stronghold is *picked*, exactly one, from the macro map
 *   alone (cellKind, regionAt, continentality), so every county in the square agrees on the ten without seeing each
 *   other. A county on the list must then make it (it is planned before the county's other complexes).
 * - **Everywhere else**: each faction rolls about 1 in 400 counties (the home square's density, 10 in 441), and a county
 *   takes at most one.
 *
 * The Army's stronghold is the Air Force Base: an airfield (world/industry.ts cutAirbase) and its walled cantonment.
 */

export const HOME = 10;
const SALT = 0x5401;
/** Each faction's roll outside the home square, over the share of counties that pass the fit test (about 0.8). */
const CHANCE = 0.0025 / 0.8;
/** Counties kept clear round the start (0, 0), so a new player's first drive meets no closed gate. */
const START_CLEAR = 1;

/** A faction's pick moved on by this many counties on a seed where its first pick could not be made (the gate says). */
export const HOME_SKIP: Record<number, Partial<Record<FactionId, number>>> = {
  // online: the Ministry's first pick (0,-8) is six towns, rivers and a ski field with no 28 x 28 of open ground
  // and the Studios' first (-9,6) stood where no road could be laid to its gate
  [hashString('online')]: { ministry: 1, studios: 1 },
};

const DESERT = new Set(['sands', 'saltpan', 'redrock', 'steppe']);
const HIGH = new Set(['heights', 'moors', 'terraces', 'goldhills', 'fjords']);
const WARM = new Set(['sands', 'goldhills', 'terraces', 'mangrove', 'veldt', 'redrock']);

/** Land enough for a stronghold: a continent county or a full island (the Army's needs a continent, for its airfield). */
function fits(seedHash: number, cx: number, cz: number, f: FactionId): boolean {
  const k = cellKind(seedHash, cx, cz);
  if (f === 'army') return k === 'continent';
  return k === 'continent' || k === 'full';
}

/** What each faction would rather have, tried first in the home square. */
function prefers(seedHash: number, cx: number, cz: number, f: FactionId): boolean {
  if (!fits(seedHash, cx, cz, f)) return false;
  const r = regionAt(seedHash, cx, cz) ?? '';
  const k = cellKind(seedHash, cx, cz);
  switch (f) {
    case 'guild': return k === 'full' || continentality(seedHash, cx, cz) < 0.4;
    case 'visitors': return DESERT.has(r) || (k === 'continent' && continentality(seedHash, cx, cz) > 0.7);
    case 'family': return HIGH.has(r) || WARM.has(r) || k === 'continent';
    case 'studios': return WARM.has(r) || k === 'full';
    case 'press': return HIGH.has(r) || k === 'continent';
    default: return k === 'continent' || k === 'full';
  }
}

const HOME_CACHE = new Map<number, Map<string, FactionId>>();

/** The home square's ten strongholds for a seed: county key `cx,cz` → faction. Macro data only, cached per seed. */
export function homeSquare(seedHash: number): Map<string, FactionId> {
  let out = HOME_CACHE.get(seedHash);
  if (out) return out;
  out = new Map();
  const picked: [number, number][] = [];
  // the factions in a seed-shuffled order, the counties walked in a seed-hashed order per faction
  const order = [...FACTION_IDS].sort((a, b) => hashCell(seedHash, FACTION_IDS.indexOf(a), 7, SALT) - hashCell(seedHash, FACTION_IDS.indexOf(b), 7, SALT));
  const cells: [number, number][] = [];
  for (let cz = -HOME; cz <= HOME; cz++) for (let cx = -HOME; cx <= HOME; cx++) cells.push([cx, cz]);
  for (const f of order) {
    const fi = FACTION_IDS.indexOf(f);
    const walk = [...cells].sort((a, b) => hashCell(seedHash, a[0], a[1], SALT + 20 + fi) - hashCell(seedHash, b[0], b[1], SALT + 20 + fi));
    let skip = HOME_SKIP[seedHash]?.[f] ?? 0;
    const tryPass = (test: (cx: number, cz: number) => boolean, apart: number): boolean => {
      for (const [cx, cz] of walk) {
        if (Math.max(Math.abs(cx), Math.abs(cz)) <= START_CLEAR) continue;
        if (out!.has(`${cx},${cz}`)) continue;
        if (picked.some(([px, pz]) => Math.max(Math.abs(px - cx), Math.abs(pz - cz)) < apart)) continue;
        if (!test(cx, cz)) continue;
        if (skip > 0) { skip--; continue; }
        out!.set(`${cx},${cz}`, f);
        picked.push([cx, cz]);
        return true;
      }
      return false;
    };
    tryPass((cx, cz) => prefers(seedHash, cx, cz, f), 4)
      || tryPass((cx, cz) => fits(seedHash, cx, cz, f), 3)
      || tryPass((cx, cz) => fits(seedHash, cx, cz, f), 1);
  }
  HOME_CACHE.set(seedHash, out);
  return out;
}

const inHome = (cx: number, cz: number) => Math.abs(cx) <= HOME && Math.abs(cz) <= HOME;

/** The faction whose stronghold this county is meant to hold, if any (macro data only). */
export function strongholdFactionAt(seedHash: number, cx: number, cz: number): FactionId | null {
  if (inHome(cx, cz)) return homeSquare(seedHash).get(`${cx},${cz}`) ?? null;
  // outside the home square: each faction's roll, in a seed-shuffled order, the first that wins and fits
  const start = Math.floor(cell01(seedHash, cx, cz, SALT + 90) * FACTION_IDS.length);
  for (let k = 0; k < FACTION_IDS.length; k++) {
    const fi = (start + k) % FACTION_IDS.length, f = FACTION_IDS[fi];
    // the Army's needs a continent, rarer than land of any kind, so its roll is that much more generous
    if (cell01(seedHash, cx, cz, SALT + 40 + fi) < CHANCE * (f === 'army' ? 1.25 : 1) && fits(seedHash, cx, cz, f)) return f;
  }
  return null;
}

/** Every county within `r` of (cx, cz) meant to hold a stronghold, nearest first. */
export function strongholdCells(seedHash: number, cx: number, cz: number, r: number): { f: FactionId; cx: number; cz: number }[] {
  const out: { f: FactionId; cx: number; cz: number }[] = [];
  for (let z = cz - r; z <= cz + r; z++) {
    for (let x = cx - r; x <= cx + r; x++) {
      const f = strongholdFactionAt(seedHash, x, z);
      if (f) out.push({ f, cx: x, cz: z });
    }
  }
  return out.sort((a, b) => Math.hypot(a.cx - cx, a.cz - cz) - Math.hypot(b.cx - cx, b.cz - cz));
}

/** The home square's stronghold of a faction (always one), as a county. */
export function homeStronghold(seedHash: number, f: FactionId): { cx: number; cz: number } | null {
  for (const [key, g] of homeSquare(seedHash)) if (g === f) { const [cx, cz] = key.split(',').map(Number); return { cx, cz }; }
  return null;
}

/**
 * Plan this county's stronghold, if it is meant to hold one: its lot levelled as a wonder's is, a work site of kind
 * 'resort' so a paved road comes to its gate. The Army's comes with its airfield (cutAirbase, passed in). Returns the
 * faction it made, or null.
 */
export function planStronghold(
  w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, lakeLvl: Int8Array, works: WorkSite[],
  seedHash: number, band: number, airbase: (rng: () => number) => WorkSite | null,
): FactionId | null {
  const f = strongholdFactionAt(seedHash, w.cx, w.cz);
  if (!f) return null;
  const kind = STRONGHOLD_OF[f];
  const plan = strongholdPlan(kind);
  const [W, D] = INFO_080[kind].size;
  const rng = mulberry32(hashCell(seedHash, w.cx, w.cz, SALT + 100));
  if (f === 'army') {
    const s = airbase(mulberry32(hashCell(seedHash, w.cx, w.cz, SALT + 150)));
    if (s) s.name = `${landformName('wood', seedHash ^ (SALT + 50), w.ox + s.x, w.oz + s.z)} Air Force Base`;
  }
  const spec = (where: 'flat' | 'high') => ({ wonder: { kind, name: [''], w: W, d: D, where } }) as unknown as Pick<RegionSpec, 'wonder'>;
  const got = planWonder(w, land, E, river, lakeLvl, rng, spec(plan.where), band)
    ?? (plan.where === 'high' ? planWonder(w, land, E, river, lakeLvl, rng, spec('flat'), band) : null);
  // one the county is meant to hold is found the hard way when a wonder's search finds no room
  const s = got?.site ?? planMustFlat(w, land, E, river, lakeLvl, rng, kind, W, D, band);
  if (!s) return null;
  s.kind = 'resort';
  // the road comes to its first gate, not the middle of its front (a gate may stand well off to one side)
  const lot = s.lot!, g0 = plan.gates[0], [ox, oz] = gateOut(plan, g0);
  const yaw = Math.atan2(DIRS[s.facing][0], DIRS[s.facing][1]), c = Math.cos(yaw), sn = Math.sin(yaw);
  const px = g0.x + ox * 2.2, pz = g0.z + oz * 2.2;
  const gx = Math.floor(lot.x + lot.w / 2 + px * c + pz * sn), gz = Math.floor(lot.z + lot.d / 2 - px * sn + pz * c);
  if (gx >= 0 && gz >= 0 && gx < N && gz < N) s.gate = gz * N + gx;
  s.name = f === 'army' ? `${landformName('wood', seedHash ^ (SALT + 50), w.ox + s.x, w.oz + s.z)} Cantonment` : STRONGHOLD_NAME[kind];
  works.push(s);
  return f;
}

// ---- the game's view ---------------------------------------------------------------------------------------------

export interface Stronghold { f: FactionId; kind: StrongholdKind; plan: SPlan; b: Building; name: string; w: World }

const FOUND = new WeakMap<World, { n: number; list: Stronghold[] }>();

/** The strongholds standing in a county. */
export function strongholdsIn(w: World): Stronghold[] {
  const had = FOUND.get(w);
  if (had && had.n === w.works.length) return had.list;
  const list: Stronghold[] = [];
  for (const g of w.works) {
    for (const b of g.buildings) {
      if (b.gone || !isStronghold(b.kind)) continue;
      const plan = strongholdPlan(b.kind);
      list.push({ f: plan.faction, kind: b.kind, plan, b, name: g.name, w });
    }
  }
  FOUND.set(w, { n: w.works.length, list });
  return list;
}

/** A world point (tiles, county-local) in a stronghold's model frame. */
export function toPlan(b: Building, lx: number, lz: number): [number, number] {
  const dx = lx - (b.x + b.w / 2), dz = lz - (b.z + b.d / 2);
  const yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]);
  const c = Math.cos(yaw), s = Math.sin(yaw);
  return [dx * c - dz * s, dx * s + dz * c];
}

/** A point in a stronghold's model frame back to county-local tiles. */
export function fromPlan(b: Building, px: number, pz: number): [number, number] {
  const yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]);
  const c = Math.cos(yaw), s = Math.sin(yaw);
  // inverse of the rotation in toPlan
  return [b.x + b.w / 2 + px * c + pz * s, b.z + b.d / 2 - px * s + pz * c];
}

/** The model frame's direction (dx, dz) as a county direction. */
export function dirFromPlan(b: Building, dx: number, dz: number): [number, number] {
  const yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]);
  const c = Math.cos(yaw), s = Math.sin(yaw);
  return [dx * c + dz * s, -dx * s + dz * c];
}

/** Every stronghold in reach of a county-local point, with the point in its frame. */
export function strongholdAt(w: World, lx: number, lz: number, margin = 0): { s: Stronghold; px: number; pz: number } | null {
  for (const s of strongholdsIn(w)) {
    const b = s.b;
    if (lx < b.x - margin || lz < b.z - margin || lx > b.x + b.w + margin || lz > b.z + b.d + margin) continue;
    const [px, pz] = toPlan(b, lx, lz);
    return { s, px, pz };
  }
  return null;
}

