import * as THREE from 'three';
import { N, type World } from '../world/tiles';
import { seabedSites, type SeabedSite } from '../world/seabed';

/**
 * The dive buoys over the seabed sites (docs/underwater.html, world/seabed.ts): an orange float riding the
 * surface with a "divers down" flag on a short mast, red with a white diagonal. Shown only while the player
 * drives a submarine, as helicopter work shows only from a helicopter, out to BUOY_R tiles.
 */

/** How far off a buoy shows, in tiles. */
const BUOY_R = 220;

const FLOAT = new THREE.SphereGeometry(0.22, 14, 10).scale(1, 0.75, 1);
const BAND = new THREE.CylinderGeometry(0.226, 0.226, 0.06, 14);
const MAST = new THREE.CylinderGeometry(0.02, 0.02, 0.8, 6).translate(0, 0.4, 0);
const FLAG = new THREE.PlaneGeometry(0.34, 0.24).translate(0.17, 0, 0);

let flagTex: THREE.Texture | null = null;
/** The divers-down flag: red, a white stripe from top left to bottom right. */
function flagTexture(): THREE.Texture {
  if (flagTex) return flagTex;
  const c = document.createElement('canvas');
  c.width = 96; c.height = 64;
  const g = c.getContext('2d')!;
  g.fillStyle = '#d8262c';
  g.fillRect(0, 0, 96, 64);
  g.strokeStyle = '#ffffff';
  g.lineWidth = 14;
  g.beginPath();
  g.moveTo(-4, -4);
  g.lineTo(100, 68);
  g.stroke();
  flagTex = new THREE.CanvasTexture(c);
  flagTex.colorSpace = THREE.SRGBColorSpace;
  return flagTex;
}

const orange = new THREE.MeshLambertMaterial({ color: 0xff7a1a });
const white = new THREE.MeshLambertMaterial({ color: 0xf4f1ea });
const dark = new THREE.MeshLambertMaterial({ color: 0x1f2b33 });
let flagMat: THREE.MeshBasicMaterial | null = null;

interface Buoy { key: string; g: THREE.Group; site: SeabedSite; ox: number; oz: number; phase: number }

export class SeabedBuoys {
  readonly root = new THREE.Group();
  private buoys = new Map<string, Buoy>();

  constructor(scene: THREE.Scene) {
    this.root.name = 'seabedBuoys';
    scene.add(this.root);
  }

  /** `worlds` in memory; `at` the player in world tiles; `on` whether the player drives a submarine; `t` seconds. */
  update(worlds: World[], at: { x: number; z: number } | null, on: boolean, t: number): void {
    this.root.visible = on && !!at;
    if (!this.root.visible || !at) {
      if (this.buoys.size) this.clear();
      return;
    }
    const want = new Set<string>();
    for (const w of worlds) {
      // a county whose middle is far past the buoys' reach has none to show
      if (Math.hypot(w.ox + N / 2 - at.x, w.oz + N / 2 - at.z) > BUOY_R + N) continue;
      for (const s of seabedSites(w)) {
        const x = w.ox + s.lx, z = w.oz + s.lz;
        if (Math.hypot(x - at.x, z - at.z) > BUOY_R) continue;
        const key = `${w.cx},${w.cz}:${s.kind}`;
        want.add(key);
        if (!this.buoys.has(key)) this.buoys.set(key, this.make(key, s, w.ox, w.oz));
      }
    }
    for (const [key, b] of this.buoys) {
      if (!want.has(key)) { b.g.removeFromParent(); this.buoys.delete(key); continue; }
      // riding the swell, nodding a little
      b.g.position.y = b.site.surface - 0.06 + Math.sin(t * 1.7 + b.phase) * 0.035;
      b.g.rotation.z = Math.sin(t * 1.3 + b.phase) * 0.08;
      b.g.rotation.x = Math.cos(t * 1.1 + b.phase) * 0.06;
    }
  }

  private make(key: string, s: SeabedSite, ox: number, oz: number): Buoy {
    const g = new THREE.Group();
    flagMat ??= new THREE.MeshBasicMaterial({ map: flagTexture(), side: THREE.DoubleSide });
    const float = new THREE.Mesh(FLOAT, orange), band = new THREE.Mesh(BAND, white), mast = new THREE.Mesh(MAST, dark), flag = new THREE.Mesh(FLAG, flagMat);
    flag.position.set(0.02, 0.66, 0);
    g.add(float, band, mast, flag);
    // a little off the ring's middle, so it never sits on the goods
    g.position.set(ox + s.lx + 0.9, s.surface, oz + s.lz + 0.6);
    g.rotation.y = (s.lx * 7 + s.lz * 13) % (Math.PI * 2);
    this.root.add(g);
    return { key, g, site: s, ox, oz, phase: (s.lx * 3.1 + s.lz * 1.7) % 6.28 };
  }

  clear(): void {
    for (const b of this.buoys.values()) b.g.removeFromParent();
    this.buoys.clear();
  }
}
