/**
 * The world's records (docs/toppers.html, the Range Trophies), shared by the game and the server (server/records.ts):
 * what each measures, in what, and the most a world allows, which a sent best is held to. The game reads its own bests
 * from the deeds' record (net/online.ts) and sends them with its save.
 */
export type RecordId = 'high' | 'deep' | 'jump' | 'haul';

export const RECORDS: Record<RecordId, { name: string; unit: string; max: number; fmt: (v: number) => string }> = {
  /** Steps up, in a road vehicle (deeds `altitude`); no corner of the world is above 127. */
  high: { name: 'Highest ground', unit: 'steps', max: 127, fmt: (v) => `${v} steps up` },
  /** Steps of water under a sub (deeds `deepestDive`). */
  deep: { name: 'Deepest dive', unit: 'steps', max: 64, fmt: (v) => `${v} steps down` },
  /** Tenths of a tile, take-off to touch-down (deeds `longestJump`); the widest gap a jump spans is 11 tiles. */
  jump: { name: 'Longest jump', unit: 'tiles', max: 200, fmt: (v) => `${(v / 10).toFixed(1)} tiles` },
  /** Counties from where a load was picked up to where it was delivered (deeds `farthest`). */
  haul: { name: 'Longest delivery', unit: 'counties', max: 200, fmt: (v) => `${v} counties` },
};
export const RECORD_IDS = Object.keys(RECORDS) as RecordId[];

/** The Track Trophies (docs/toppers.html): the most lap records at circuits of each design, of all, and the most drift records. */
export const TRACK_TROPHIES = ['speedway', 'bullring', 'grandprix', 'heritage', 'laps', 'drift'] as const;
export type TrackTrophy = (typeof TRACK_TROPHIES)[number];

/** A held topper's board for the Toppers tab: the topper, who holds it and with what, and this player's own. */
export interface HolderBoard { tp: string; holder: string | null; top: number; you: number }
