import type { World } from './tiles';
import type { Runway } from './runways';

/**
 * Flight decks (the Bastion, the aircraft carrier): a runway that floats. game/carrier.ts rebuilds the
 * list every frame from wherever the fleet's carriers are (the one ridden, parked ones, a hired captain's),
 * and the air physics reads it: the deck is ground for groundY, a strip for the landing aid and the
 * take-off roll, and its floor is "airfield" for taxiing. A jet or a helicopter sitting on a deck moves
 * with it (AirState.carry); a parked jet on a deck is moved by game/carrier.ts.
 *
 * Sizes are in the model's own units (render/vehicleMeshes.ts `carrier`) and multiplied by the def's scale.
 */
export const DECK_MODEL = {
  /** The flight deck's top, above the hull's waterline. */
  top: 0.36,
  /** Half the deck's length (stern to bow tip) and half its width; the bow tapers from `taper` to `tipWid`. */
  halfLen: 1.7, halfWid: 0.56, taper: 1.45, tipWid: 0.3,
  /** The strip: its centreline's offset to port (negative across), half its length and half its width. */
  rwAcross: -0.18, rwHalf: 1.56, rwWid: 0.17,
  /** The island (bridge tower) on the starboard side: centre along, centre across, half length, half width. */
  island: { along: -0.24, across: 0.38, halfLen: 0.25, halfWid: 0.09 },
  /** Parking spots beside the island, (along, across); a parked jet faces the strip and the bow. */
  stands: [[1.16, 0.25], [0.68, 0.25], [-0.96, 0.25]] as [number, number][],
};

/** A jet that needs no more runway than this fits a deck: the catapult and the wires make up the rest. */
export const DECK_TAKES = 24;
/** On a deck the catapult gives at least this take-off push, and the arrestor wires this much stopping, in tiles/s². */
export const CATAPULT = 4;
export const ARREST = 6;

export interface Deck {
  /** The carrier unit's uid, as a string. */
  key: string;
  name: string;
  /** The cell it is in. */
  w: World;
  /** Its centre, world tiles; its heading; the deck surface, world units. */
  x: number; z: number; heading: number; y: number;
  /** The model scale (deck sizes are DECK_MODEL times this). */
  scale: number;
  runway: Runway;
}

/** Every flight deck in the world right now. */
export const DECKS: Deck[] = [];

/** A world point in a deck's frame: tiles forward of its centre, and tiles to starboard. */
export function deckLocal(d: { x: number; z: number; heading: number }, gx: number, gz: number): { along: number; across: number } {
  const dx = gx - d.x, dz = gz - d.z, s = Math.sin(d.heading), c = Math.cos(d.heading);
  return { along: dx * s + dz * c, across: dx * c - dz * s };
}

/** A point of a deck's frame back in world tiles. */
export function deckWorld(d: { x: number; z: number; heading: number }, along: number, across: number): { x: number; z: number } {
  const s = Math.sin(d.heading), c = Math.cos(d.heading);
  return { x: d.x + along * s + across * c, z: d.z + along * c - across * s };
}

/** Is this deck-frame point on the flight deck (inside its outline)? */
function onOutline(d: Deck, along: number, across: number, pad: number): boolean {
  const k = d.scale, m = DECK_MODEL;
  const half = m.halfLen * k + pad;
  if (Math.abs(along) > half) return false;
  let wid = m.halfWid * k;
  if (along > m.taper * k) wid += (m.tipWid - m.halfWid) * k * Math.min(1, (along - m.taper * k) / ((m.halfLen - m.taper) * k));
  return Math.abs(across) <= wid + pad;
}

/** The deck under a world point, if any (the island's roof counts: it is solid). */
export function deckUnder(gx: number, gz: number): Deck | null {
  for (const d of DECKS) {
    const f = deckLocal(d, gx, gz);
    if (onOutline(d, f.along, f.across, 0)) return d;
  }
  return null;
}

/** Somewhere a vehicle on wheels or skids may stand on a deck: on the outline and clear of the island. */
export function deckFloor(gx: number, gz: number): Deck | null {
  const d = deckUnder(gx, gz);
  if (!d) return null;
  const f = deckLocal(d, gx, gz), i = DECK_MODEL.island, k = d.scale;
  if (Math.abs(f.along - i.along * k) <= i.halfLen * k && Math.abs(f.across - i.across * k) <= i.halfWid * k) return null;
  return d;
}

/** The deck's parking spots in world tiles, nose toward the strip and the bow. */
export function deckStands(d: { x: number; z: number; heading: number; scale: number }): { x: number; z: number; heading: number }[] {
  return DECK_MODEL.stands.map(([a, c]) => ({ ...deckWorld(d, a * d.scale, c * d.scale), heading: d.heading - 0.7 }));
}

/** The strip down a deck as a Runway, for the landing aid and the take-off roll. */
export function deckRunway(d: { x: number; z: number; heading: number; y: number; scale: number; name: string; w: World }): Runway {
  const k = d.scale, m = DECK_MODEL;
  const a = deckWorld(d, -m.rwHalf * k, m.rwAcross * k), b = deckWorld(d, m.rwHalf * k, m.rwAcross * k);
  const s = Math.sin(d.heading), c = Math.cos(d.heading);
  return {
    name: d.name, major: false, w: d.w,
    ax: a.x, az: a.z, bx: b.x, bz: b.z,
    ux: s, uz: c, heading: d.heading,
    len: 2 * m.rwHalf * k, half: m.rwWid * k,
    y: d.y, sx: c, sz: -s,
    taxiOff: (m.rwWid + 0.1) * k,
    stands: deckStands(d),
    deck: true,
  };
}
