import { hex, scale, type RGB } from '../../world/biomes';
import type { FactionKind } from '../../world/factionKinds';
import type { Sched } from '../nightLights';
import { BLUE_LIGHT, COOL_GLOW, DARK, GLASS, METAL, RED_LIGHT, SHOP_GLOW, TAU, WARM_GLOW, WATER, car, type Draw, type Kit, type P3 } from './kit';

/**
 * Faction buildings, group A (docs/factions.html, "New buildings"): the Constabulary (white and navy, a
 * chequered band, a blue lamp), the Family (black and gold), the Ministry (navy, stone, a gold crest) and
 * the Visitors (dark green, glowing mint). Each reads as its faction's from the camera's height by its
 * colour blocks and one or two telling shapes: the patrol car, the striped awning, the colonnade, the saucer.
 */

// ---- palettes and hours ---------------------------------------------------------------------------------

const P_WHITE = hex(0xf4f2ec), P_NAVY = hex(0x2a4f8f);
const M_BLACK = hex(0x15161a), GOLD = hex(0xd9b34a);
const G_NAVY = hex(0x2f4d7a), G_STONE = hex(0xd6d0c2), G_GREY = hex(0x9a9d9f);
const V_GREEN = hex(0x2a3b2e), MINT = hex(0x8ef0c8);

const ASPHALT = hex(0x5d6066), CONCRETE = hex(0xbfc0bb), PAVED = hex(0xcfc8b8), LAWN = hex(0x8fc46a), GRAVEL = hex(0xd8ccb0);
const TYRE = hex(0x26282c), LAMP = hex(0xfff2b0), TAIL = hex(0xb02020), AMBER = hex(0xf2a33b), MESH = hex(0x9aa39e);
const OLIVE = hex(0x5d6b3f), OLIVE_DARK = hex(0x46532f), CANVAS = hex(0x7a7f56), EARTH = hex(0x6b5238), EARTH_LIGHT = hex(0x8f7352);
const ORANGE = hex(0xf26a2e), WOODY = hex(0x8d6d48);

const EVENING: Sched = [18, 23.5, 1.4];
const LATE: Sched = [17, 26, 2.2];
const NIGHTLONG: Sched = [17.5, 30.5, 1.8];
const FLOOD: Sched = [17.5, 30.5, 2.4];
const SOFT: Sched = [17.5, 30.5, 1.1];

// ---- shared helpers -------------------------------------------------------------------------------------

/** Letters across a face looking +z, centred on x, standing on y. */
function letters(k: Kit, text: string, x: number, y: number, z: number, cell: number, col: RGB): void {
  if (k.mode === 'derelict') return;
  const chars = [...text], w0 = -(chars.length * cell) / 2;
  chars.forEach((ch, i) => {
    if (ch === ' ') return;
    const xa = x + w0 + i * cell + cell * 0.05, xb = xa + cell * 0.9;
    k.glyph(ch, [xa, y, z], [xb, y, z], [xb, y + cell * 0.9, z], [xa, y + cell * 0.9, z], col);
  });
}

/** The Constabulary's chequered band: two rows of navy squares on a white wall facing +z (face 1) or +x (face 0). */
function chequer(k: Kit, cx: number, cz: number, y: number, len: number, face: 0 | 1, s = 0.05): void {
  const n = Math.max(2, Math.floor(len / s)), h = s * 0.6;
  k.detail(() => {
    for (let i = 0; i < n; i++) {
      const u = -(n * s) / 2 + (i + 0.5) * s;
      const yy = i % 2 ? y + h : y;
      if (face === 1) k.box(cx + u, yy, cz + 0.003, s, h, 0.006, P_NAVY);
      else k.box(cx + 0.003, yy, cz + u, 0.006, h, s, P_NAVY);
    }
  });
}

/** The blue lamp of a police post, with its little cap. */
function blueLamp(k: Kit, x: number, y: number, z: number, s = 1): void {
  k.glowBox(x, y, z, 0.07 * s, 0.08 * s, 0.07 * s, hex(0x3b6fd0), NIGHTLONG, BLUE_LIGHT);
  k.box(x, y + 0.08 * s, z, 0.085 * s, 0.015 * s, 0.085 * s, DARK);
}

/** A straight run of chain-link (or railings) between two points on an axis. */
function fence(k: Kit, x0: number, z0: number, x1: number, z1: number, h: number, post: RGB, fill: RGB, step = 0.55): void {
  const len = Math.hypot(x1 - x0, z1 - z0), n = Math.max(1, Math.round(len / step));
  const alongX = Math.abs(x1 - x0) > Math.abs(z1 - z0);
  const mx = (x0 + x1) / 2, mz = (z0 + z1) / 2;
  for (let i = 0; i <= n; i++) k.box(x0 + ((x1 - x0) * i) / n, 0.02, z0 + ((z1 - z0) * i) / n, 0.035, h + 0.03, 0.035, post);
  k.box(mx, 0.04, mz, alongX ? len : 0.012, h - 0.04, alongX ? 0.012 : len, fill);
  k.box(mx, 0.02 + h, mz, alongX ? len : 0.018, 0.018, alongX ? 0.018 : len, post);
}

/** Iron railings: a top and bottom rail with thin uprights, gold knobs on every fourth. */
function railings(k: Kit, x0: number, z0: number, x1: number, z1: number, h: number): void {
  const len = Math.hypot(x1 - x0, z1 - z0), n = Math.max(1, Math.round(len / 0.12));
  const alongX = Math.abs(x1 - x0) > Math.abs(z1 - z0);
  const mx = (x0 + x1) / 2, mz = (z0 + z1) / 2;
  for (let i = 0; i <= n; i++) {
    const x = x0 + ((x1 - x0) * i) / n, z = z0 + ((z1 - z0) * i) / n;
    k.box(x, 0.02, z, 0.014, h, 0.014, M_BLACK);
    if (i % 4 === 0) k.box(x, 0.02 + h, z, 0.03, 0.03, 0.03, GOLD);
  }
  for (const y of [0.06, h - 0.02]) k.box(mx, y, mz, alongX ? len : 0.02, 0.02, alongX ? 0.02 : len, M_BLACK);
}

/** A hipped roof whose ridge runs along the longer side. */
function hipRoof(k: Kit, x: number, y: number, z: number, w: number, h: number, d: number, col: RGB): void {
  const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2, yt = y + h, I: P3 = [x, y + h / 3, z];
  if (w >= d) {
    const r = (w - d) / 2, A: P3 = [x - r, yt, z], B: P3 = [x + r, yt, z];
    k.quad([x0, y, z1], [x1, y, z1], B, A, col, I);
    k.quad([x0, y, z0], [x1, y, z0], B, A, col, I);
    k.tri([x0, y, z0], [x0, y, z1], A, col, I);
    k.tri([x1, y, z0], [x1, y, z1], B, col, I);
  } else {
    const r = (d - w) / 2, A: P3 = [x, yt, z - r], B: P3 = [x, yt, z + r];
    k.quad([x1, y, z0], [x1, y, z1], B, A, col, I);
    k.quad([x0, y, z0], [x0, y, z1], B, A, col, I);
    k.tri([x0, y, z0], [x1, y, z0], A, col, I);
    k.tri([x0, y, z1], [x1, y, z1], B, col, I);
  }
}

/** An arched roof over a w×d base, its ridge along z, both ends closed. */
function barrel(k: Kit, x: number, y: number, z: number, w: number, rise: number, d: number, col: RGB, end: RGB, n = 8): void {
  const z0 = z - d / 2, z1 = z + d / 2, I: P3 = [x, y - 0.05, z];
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * Math.PI, a1 = ((i + 1) / n) * Math.PI;
    const p0: [number, number] = [x - (Math.cos(a0) * w) / 2, y + Math.sin(a0) * rise];
    const p1: [number, number] = [x - (Math.cos(a1) * w) / 2, y + Math.sin(a1) * rise];
    k.quad([p0[0], p0[1], z0], [p1[0], p1[1], z0], [p1[0], p1[1], z1], [p0[0], p0[1], z1], i % 2 ? col : scale(col, 0.94), I);
    k.tri([x, y, z0], [p0[0], p0[1], z0], [p1[0], p1[1], z0], end, I);
    k.tri([x, y, z1], [p0[0], p0[1], z1], [p1[0], p1[1], z1], end, I);
  }
}

/** A flat ring lying on y (top face only): a crop circle's swathe, a scorched halo. */
function annulus(k: Kit, x: number, z: number, r0: number, r1: number, y: number, col: RGB, seg = 24, glow?: [Sched, RGB]): void {
  const I: P3 = [x, y - 0.05, z];
  for (let i = 0; i < seg; i++) {
    const a0 = (i / seg) * TAU, a1 = ((i + 1) / seg) * TAU;
    const p = (a: number, r: number): P3 => [x + Math.cos(a) * r, y, z + Math.sin(a) * r];
    if (glow) k.glowQuad(p(a0, r0), p(a1, r0), p(a1, r1), p(a0, r1), I, col, glow[0], glow[1]);
    else k.quad(p(a0, r0), p(a1, r0), p(a1, r1), p(a0, r1), col, I);
  }
}

/** A flat disc lying on y (top face only). */
function flatDisc(k: Kit, x: number, z: number, r: number, y: number, col: RGB, seg = 16): void {
  const I: P3 = [x, y - 0.05, z];
  for (let i = 0; i < seg; i++) {
    const a0 = (i / seg) * TAU, a1 = ((i + 1) / seg) * TAU;
    k.tri([x, y, z], [x + Math.cos(a0) * r, y, z + Math.sin(a0) * r], [x + Math.cos(a1) * r, y, z + Math.sin(a1) * r], col, I);
  }
}

/** A flat strip on y from (x0, z0) to (x1, z1), w wide (top face only). */
function strip(k: Kit, x0: number, z0: number, x1: number, z1: number, w: number, y: number, col: RGB): void {
  const len = Math.hypot(x1 - x0, z1 - z0) || 1, px = (-(z1 - z0) / len) * (w / 2), pz = ((x1 - x0) / len) * (w / 2);
  k.quad([x0 + px, y, z0 + pz], [x1 + px, y, z1 + pz], [x1 - px, y, z1 - pz], [x0 - px, y, z0 - pz], col, [(x0 + x1) / 2, y - 0.05, (z0 + z1) / 2]);
}

// ---- vehicles -------------------------------------------------------------------------------------------

type Part = (s: number, y: number, a: number, ws: number, h: number, la: number, c: RGB, top?: RGB) => void;
type GlowPart = (s: number, y: number, a: number, ws: number, h: number, la: number, day: RGB, sc: Sched, g: RGB) => void;

/**
 * A vehicle's own frame at (x, z), its nose toward dir (0 +z, 1 +x, 2 -z, 3 -x): `s` across it, `a` along
 * it toward the nose. Boxes, glowing boxes and bars drawn in it.
 */
function vframe(k: Kit, x: number, z: number, dir: number): { p: Part; g: GlowPart; at: (s: number, y: number, a: number) => P3 } {
  const at = (s: number, y: number, a: number): P3 =>
    dir === 0 ? [x + s, y, z + a] : dir === 2 ? [x - s, y, z - a] : dir === 1 ? [x + a, y, z - s] : [x - a, y, z + s];
  const side = dir === 1 || dir === 3;
  const p: Part = (s, y, a, ws, h, la, c, top = c) => {
    const [X, , Z] = at(s, y, a);
    if (side) k.box(X, y, Z, la, h, ws, c, top);
    else k.box(X, y, Z, ws, h, la, c, top);
  };
  const g: GlowPart = (s, y, a, ws, h, la, day, sc, gl) => {
    const [X, , Z] = at(s, y, a);
    if (side) k.glowBox(X, y, Z, la, h, ws, day, sc, gl);
    else k.glowBox(X, y, Z, ws, h, la, day, sc, gl);
  };
  return { p, g, at };
}

/** A saloon car at the parked cars' size (0.2 × 0.36); a longer `len` makes a limousine. */
function sedan(k: Kit, x: number, z: number, dir: number, paint: RGB, len = 0.36, glass: RGB = GLASS): ReturnType<typeof vframe> {
  const v = vframe(k, x, z, dir), { p } = v;
  const W = 0.2, L = len, y0 = 0.05, bh = 0.07, deck = y0 + bh;
  const ax = L / 2 - 0.075;
  for (const a of [ax, -ax]) p(0, 0, a, W + 0.024, 0.064, 0.064, TYRE);
  p(0, y0, 0, W, bh, L, paint);
  for (const sg of [1, -1]) p(0, y0 - 0.008, sg * (L / 2 + 0.004), W + 0.01, 0.024, 0.012, DARK);
  p(0, y0 + 0.032, L / 2 + 0.002, W * 0.8, 0.018, 0.006, LAMP);
  p(0, y0 + 0.032, -L / 2 - 0.002, W * 0.8, 0.016, 0.006, TAIL);
  p(0, deck, -0.02, W * 0.88, 0.065, L > 0.45 ? L * 0.62 : L * 0.52, glass, paint);
  return v;
}

/** A Constabulary patrol car: white, a navy band down each side, the light bar on its roof. */
function patrolCar(k: Kit, x: number, z: number, dir: number): void {
  const { p, g } = sedan(k, x, z, dir, P_WHITE);
  p(0, 0.068, 0, 0.206, 0.026, 0.25, P_NAVY);
  p(0, 0.12, 0.13, 0.17, 0.003, 0.07, P_NAVY);
  g(-0.035, 0.185, -0.02, 0.06, 0.022, 0.04, hex(0x3b6fd0), NIGHTLONG, BLUE_LIGHT);
  g(0.035, 0.185, -0.02, 0.06, 0.022, 0.04, hex(0xd23a2e), NIGHTLONG, RED_LIGHT);
}

/** A tow truck: cab forward, flat bed, the boom and its wheel-lift, an amber beacon. */
function towTruck(k: Kit, x: number, z: number, dir: number): void {
  const { p, g, at } = vframe(k, x, z, dir);
  for (const a of [0.19, -0.13, -0.21]) p(0, 0, a, 0.23, 0.07, 0.07, TYRE);
  p(0, 0.04, -0.03, 0.18, 0.04, 0.52, DARK);
  p(0, 0.07, 0.17, 0.21, 0.16, 0.16, P_WHITE);
  p(0, 0.15, 0.252, 0.17, 0.06, 0.006, GLASS);
  p(0, 0.1, 0.17, 0.214, 0.03, 0.12, P_NAVY);
  g(0, 0.23, 0.17, 0.09, 0.025, 0.04, AMBER, NIGHTLONG, AMBER);
  p(0, 0.08, -0.1, 0.2, 0.035, 0.34, P_NAVY);
  k.bar(at(0, 0.115, -0.02), at(0, 0.3, -0.24), 0.016, METAL);
  k.bar(at(0, 0.3, -0.24), at(0, 0.16, -0.27), 0.006, DARK);
  p(0, 0.05, -0.3, 0.18, 0.025, 0.05, DARK);
}

/** A grey armoured van: cab, a tall box body with barred windows, a navy band. */
function armouredTruck(k: Kit, x: number, z: number, dir: number): void {
  const { p } = vframe(k, x, z, dir);
  const STEEL = hex(0x8a8f94), STEEL_TOP = hex(0x9fa4a8);
  for (const a of [0.19, -0.16]) p(0, 0, a, 0.26, 0.075, 0.075, TYRE);
  p(0, 0.05, 0, 0.22, 0.03, 0.54, DARK);
  p(0, 0.08, 0.19, 0.23, 0.14, 0.15, STEEL, STEEL_TOP);
  p(0, 0.15, 0.267, 0.19, 0.055, 0.006, GLASS);
  p(0, 0.08, -0.07, 0.25, 0.25, 0.38, STEEL, STEEL_TOP);
  p(0, 0.14, -0.07, 0.256, 0.035, 0.37, G_NAVY);
  p(0, 0.26, -0.26, 0.12, 0.05, 0.006, DARK);
  for (const s of [-0.04, 0, 0.04]) p(s, 0.255, -0.267, 0.012, 0.06, 0.006, METAL);
  for (const sg of [1, -1]) {
    p(sg * 0.128, 0.24, -0.07, 0.006, 0.05, 0.14, DARK);
    for (const a of [-0.11, -0.07, -0.03]) p(sg * 0.134, 0.235, a, 0.006, 0.06, 0.012, METAL);
  }
  p(0, 0.33, -0.07, 0.05, 0.004, 0.05, GOLD);
}

/** An army 4x4: olive body, a glazed cab, canvas over the back, a spare wheel and a white star. */
function army4x4(k: Kit, x: number, z: number, dir: number): void {
  const { p } = vframe(k, x, z, dir);
  for (const a of [0.125, -0.125]) p(0, 0, a, 0.25, 0.08, 0.08, TYRE);
  p(0, 0.05, 0, 0.22, 0.08, 0.4, OLIVE);
  p(0, 0.13, 0.04, 0.2, 0.08, 0.13, GLASS, OLIVE_DARK);
  p(0, 0.13, -0.1, 0.21, 0.1, 0.17, CANVAS);
  p(0, 0.13, 0.15, 0.05, 0.003, 0.05, P_WHITE);
  p(0, 0.07, -0.215, 0.1, 0.1, 0.03, TYRE);
}

