  k.box(0, 0.02, bz, w, 1.06, d, STUCCO);
  // the shopfront: black pilasters, fascia and stall riser; gold lettering, trim and door handle
  k.box(0, 0.02, z1 + 0.012, w + 0.02, 0.56, 0.024, M_BLACK);
  k.box(0, 0.47, z1 + 0.03, w + 0.04, 0.11, 0.024, M_BLACK);
