  // cornice with a gold line, the roof, a chimney
  k.box(0, 1.1, bz, w + 0.05, 0.05, d + 0.05, M_BLACK);
  k.box(0, 1.08, bz, w + 0.03, 0.02, d + 0.03, GOLD);
  k.box(0, 1.15, bz, w - 0.06, 0.01, d - 0.06, hex(0x8a6a50));
  k.box(-0.25, 1.15, z0 + 0.2, 0.14, 0.15, 0.14, scale(STUCCO, 0.85));
