  const fx = 0, fz = 0.5;
  k.band(fx, fz, 0.026, 0.36, 0.11, 0.36, 14, STONE, scale(STONE, 0.85));
  k.hoop(fx, 0.115, fz, 0.36, 0.012, STONE, 14, 'xz');
