  k.box(0, 0.84, bz, bw + 0.08, 0.06, bd + 0.08, scale(STONE, 0.92));
  hipRoof(k, 0, 0.9, bz, bw, 0.3, bd, SLATE);
  for (const s of [-1, 1]) k.box(s * 0.7, 1.0, bz, 0.12, 0.2, 0.12, scale(STONE, 0.85));
  for (const wx of [-0.9, -0.62, 0.62, 0.9]) {
    k.pane(wx, 0.2, fz, 0.12, 0.17, 1, GLASS, EVENING, WARM_GLOW);
    k.pane(wx, 0.53, fz, 0.12, 0.2, 1, GLASS, EVENING, WARM_GLOW);
    k.box(wx, 0.74, fz + 0.01, 0.16, 0.025, 0.02, scale(STONE, 0.8));
  }
  for (const s of [-1, 1]) {
    for (const wz of [-1.0, -0.6, -0.2]) {
      k.pane(s * bw / 2, 0.2, wz, 0.12, 0.17, s > 0 ? 0 : 2, GLASS, EVENING, WARM_GLOW);
      k.pane(s * bw / 2, 0.53, wz, 0.12, 0.2, s > 0 ? 0 : 2, GLASS, EVENING, WARM_GLOW);
    }
  }
  k.pane(0, 0.53, fz, 0.16, 0.2, 1, GLASS, EVENING, WARM_GLOW);
  // the portico: steps, four columns, the pediment with the crest
  const pz = fz + 0.16, pw = 0.84, colH = 0.52;
  k.box(0, 0.02, pz + 0.13, pw + 0.14, 0.04, 0.34, scale(STONE, 0.9));
  k.box(0, 0.02, pz + 0.3, pw + 0.24, 0.02, 0.2, scale(STONE, 0.9));
  for (let i = 0; i < 4; i++) k.cyl(-pw / 2 + 0.07 + (i * (pw - 0.14)) / 3, 0.06, pz + 0.06, 0.04, colH, P_WHITE, 6);
  k.box(0, 0.06 + colH, pz - 0.02, pw + 0.06, 0.07, 0.36, STONE);
  k.gable(0, 0.13 + colH, pz - 0.02, pw + 0.06, 0.2, 0.36, SLATE, STONE, true);
  crest(k, 0, 0.13 + colH + 0.075, pz + 0.16, 0.055);
  // the door, its lamp, and the brass plate beside it
  k.box(0, 0.02, fz + 0.026, 0.18, 0.3, 0.012, G_NAVY);
  k.box(0, 0.32, fz + 0.026, 0.2, 0.02, 0.012, GOLD);
  k.box(0.17, 0.2, fz + 0.006, 0.07, 0.06, 0.008, GOLD);
