  k.box(1.25, 0.02, 0.45, 0.2, 0.03, 0.3, CONCRETE);
  k.box(1.25, 0.05, 0.45, 0.1, 0.24, 0.12, G_NAVY, P_WHITE);
  k.box(1.25, 0.2, 0.45, 0.104, 0.04, 0.124, P_WHITE);
  k.glowBox(1.25, 0.12, 0.513, 0.06, 0.05, 0.006, hex(0xd8e8f0), NIGHTLONG, COOL_GLOW);
  k.box(1.25, 0.02, -0.55, 0.08, 0.04, 0.08, CONCRETE);
  k.box(1.25, 0.06, -0.55, 0.018, 0.92, 0.018, P_WHITE);
  k.box(1.16, 0.84, -0.55, 0.17, 0.12, 0.012, G_NAVY);
  k.box(1.16, 0.88, -0.55, 0.05, 0.04, 0.016, GOLD);
