/**
 * A crash site: a furrow gouged across the field ends in a dark green saucer dug in nose-first, a tarp
 * roped over its tail, its rim lights still glowing mint; cordon tape on posts round it, work lights on
 * tripods, an army 4x4 and a generator.
 */
const crashSite: Draw = (k, W, D) => {
  const SCORCH = hex(0x4a3e30), TARP = hex(0x5d7086), TAPE = hex(0xf2c81e);
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, hex(0x86ab5c));
  k.cyl(0.2, 0.02, 0.15, 1.0, 0.004, SCORCH, 14, SCORCH, 0.85);
  // the furrow from the back corner to the saucer, widening as it goes, with its thrown-up banks
  const x0 = -1.2, z0 = -1.2, x1 = 0.25, z1 = 0.15;
  const len = Math.hypot(x1 - x0, z1 - z0), ux = (x1 - x0) / len, uz = (z1 - z0) / len, px = -uz, pz = ux;
  const I: P3 = [(x0 + x1) / 2, -0.05, (z0 + z1) / 2];
  k.quad([x0 + px * 0.06, 0.028, z0 + pz * 0.06], [x1 + px * 0.24, 0.028, z1 + pz * 0.24], [x1 - px * 0.24, 0.028, z1 - pz * 0.24], [x0 - px * 0.06, 0.028, z0 - pz * 0.06], EARTH, I);
  for (const s of [-1, 1]) {
    k.bar([x0 + s * px * 0.09, 0.02, z0 + s * pz * 0.09], [x1 + s * px * 0.3, 0.03, z1 + s * pz * 0.3], 0.025, scale(EARTH, 1.15));
  }
  for (let i = 0; i < 4; i++) {
    const t = 0.2 + i * 0.2, s = i % 2 ? 1 : -1;
    k.box(x0 + (x1 - x0) * t + s * px * 0.25, 0.02, z0 + (z1 - z0) * t + s * pz * 0.25, 0.08, 0.04, 0.07, EARTH_LIGHT);
  }
  // the saucer, tipped nose-down into the end of the furrow
  const cx = 0.38, cy = 0.12, cz = 0.28, tilt = 0.3, yaw = Math.atan2(ux, uz);
  const ct = Math.cos(tilt), st = Math.sin(tilt), cyw = Math.cos(yaw), syw = Math.sin(yaw);
  const T = (u: number, v: number, w: number): P3 => {
    const v1 = v * ct - w * st, w1 = v * st + w * ct;
    return [cx + u * cyw + w1 * syw, cy + v1, cz - u * syw + w1 * cyw];
  };
  const C = T(0, 0, 0), seg = 14, TARP0 = Math.PI * 1.2, TARP1 = Math.PI * 1.95;
  const ringAt = (r: number, v: number, a: number) => T(Math.cos(a) * r, v, Math.sin(a) * r);
  const surf = (rings: [number, number][], col: RGB, glow?: boolean, a0 = 0, a1 = TAU, n = seg, inside: P3 = C) => {
    for (let j = 0; j < rings.length - 1; j++) {
      const [ra, va] = rings[j], [rb, vb] = rings[j + 1];
      for (let i = 0; i < n; i++) {
        const b0 = a0 + ((a1 - a0) * i) / n, b1 = a0 + ((a1 - a0) * (i + 1)) / n;
        const q: [P3, P3, P3, P3] = [ringAt(ra, va, b0), ringAt(ra, va, b1), ringAt(rb, vb, b1), ringAt(rb, vb, b0)];
        if (glow) k.glowQuad(q[0], q[1], q[2], q[3], inside, hex(0x4f7a66), SOFT, MINT);
        else k.quad(q[0], q[1], q[2], q[3], col, inside);
      }
    }
  };
  surf([[0.6, 0.015], [0.44, 0.065], [0.27, 0.105], [0.16, 0.12]], V_GREEN);
  surf([[0.6, -0.015], [0.3, -0.08], [0.02, -0.1]], scale(V_GREEN, 0.8));
  surf([[0.16, 0.12], [0.12, 0.18], [0.02, 0.21]], MINT, true);
  surf([[0.6, -0.015], [0.6, 0.015]], hex(0x7f9a88));
  surf([[0.36, 0.088], [0.34, 0.093]], hex(0x7f9a88));
  // the rim lights still burning on the side out of the ground
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU, [lx, ly, lz] = ringAt(0.61, 0.0, a);
    const under = a > TARP0 - 0.2 && a < TARP1 + 0.2;
    if (ly > 0.05 && !under) k.glowBox(lx, ly - 0.015, lz, 0.035, 0.03, 0.035, hex(0x6fbfa0), SOFT, MINT);
  }
  // the tarp draped over its tail, roped down to pegs
  const tarpRings: [number, number][] = [[0.68, -0.07], [0.64, 0.03], [0.47, 0.09], [0.3, 0.135], [0.18, 0.2], [0.04, 0.26]];
  surf(tarpRings, TARP, false, TARP0, TARP1, 8, T(0, -0.3, 0));
  for (const a of [TARP0 + 0.1, (TARP0 + TARP1) / 2, TARP1 - 0.1]) {
    const top = ringAt(0.62, 0.0, a), peg: P3 = [top[0] + (top[0] - cx) * 0.4, 0.02, top[2] + (top[2] - cz) * 0.4];
    k.bar(top, peg, 0.005, hex(0xd8d0b0));
    k.box(peg[0], 0.02, peg[2], 0.025, 0.03, 0.025, WOODY);
  }
  // the earth heaped in front of its nose
  const nose = T(0, 0, 0.62);
  k.turned(yaw, () => {
    const nx = nose[0] * Math.cos(yaw) - nose[2] * Math.sin(yaw), nz = nose[0] * Math.sin(yaw) + nose[2] * Math.cos(yaw);
    k.hip(nx, 0.02, nz - 0.02, 0.62, 0.09, 0.3, EARTH_LIGHT);
    k.hip(nx, 0.02, nz + 0.1, 0.44, 0.05, 0.22, EARTH);
  });
  // the cordon: posts round the site and tape between them, open at the front for the trucks
  const R = 1.22, n = 14;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * TAU + Math.PI / 2 + 0.2, b = ((i + 1) / n) * TAU + Math.PI / 2 + 0.2;
    const p0: P3 = [0.05 + Math.cos(a) * R, 0.02, 0.05 + Math.sin(a) * R];
    k.box(p0[0], 0.02, p0[2], 0.03, 0.2, 0.03, i % 2 ? TAPE : DARK);
    if (i < n - 1) k.bar([p0[0], 0.18, p0[2]], [0.05 + Math.cos(b) * R, 0.18, 0.05 + Math.sin(b) * R], 0.007, TAPE);
  }
  // work lights on tripods, turned in on the saucer
  for (const [lx, lz] of [[-0.85, 0.85], [1.08, -0.5], [-0.2, -1.05]] as const) {
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * TAU;
      k.bar([lx + Math.cos(a) * 0.1, 0.02, lz + Math.sin(a) * 0.1], [lx, 0.28, lz], 0.008, DARK);
    }
    k.box(lx, 0.28, lz, 0.02, 0.3, 0.02, DARK);
    const dx = cx - lx, dz = cz - lz, dl = Math.hypot(dx, dz);
    k.box(lx, 0.57, lz, 0.16, 0.02, 0.03, DARK);
    for (const s of [-1, 1]) {
      k.glowBox(lx - (dz / dl) * 0.05 * s + (dx / dl) * 0.02, 0.58, lz + (dx / dl) * 0.05 * s + (dz / dl) * 0.02, 0.07, 0.07, 0.07, hex(0xe8eef2), FLOOD, COOL_GLOW);
    }
  }
  // the army 4x4 and its generator
  army4x4(k, -0.35, 0.95, 1);
  k.box(0.2, 0.02, 1.1, 0.16, 0.1, 0.1, OLIVE_DARK, OLIVE);
  k.bar([0.12, 0.05, 1.08], [-0.85, 0.03, 0.85], 0.006, DARK);
};

/**
 * A landing ring: standing stones in a ring with a trilithon at the back, the grass inside scorched dark,
 * a halo burnt into it and runes cut in the stones that glow a soft mint after dark.
 */
const landingRing: Draw = (k, W, D, _b, r) => {
  const SCORCH = hex(0x3f3a30), STONE = hex(0x8e8f88), RUNE_DAY = hex(0x6f7a72);
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, hex(0x8fb862));
  k.cyl(0, 0.02, 0, 1.0, 0.004, SCORCH, 18);
  annulus(k, 0, 0, 0.5, 0.6, 0.028, hex(0x55604f), 24, [SOFT, MINT]);
  flatDisc(k, 0, 0, 0.1, 0.028, hex(0x55604f), 10);
  k.glowBox(0, 0.02, 0, 0.06, 0.012, 0.06, hex(0x6f8a7a), SOFT, MINT);
  // scorched spokes out from the middle
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU + 0.3;
    strip(k, Math.cos(a) * 0.16, Math.sin(a) * 0.16, Math.cos(a) * 0.46, Math.sin(a) * 0.46, 0.05, 0.027, hex(0x2a2620));
  }
  // the stones, each turned to face the middle, a rune glowing on its inner face
  const R = 1.18, stones = 11;
  for (let i = 0; i < stones; i++) {
    const a = (i / stones) * TAU;
    if (i === 0) continue; // the gap at the front
    const yaw = a;
    k.turned(yaw, () => {
      if (i === Math.round(stones / 2)) {
        // the trilithon at the back
        for (const s of [-1, 1]) k.box(s * 0.14, 0.02, R, 0.14, 0.48, 0.12, STONE);
        k.box(0, 0.5, R, 0.46, 0.09, 0.14, scale(STONE, 0.92));
        k.pane(0, 0.2, R - 0.06, 0.12, 0.2, 3, RUNE_DAY, SOFT, MINT);
        k.glowBox(0, 0.59, R, 0.06, 0.012, 0.06, RUNE_DAY, SOFT, MINT);
      } else {
        const h = 0.36 + r() * 0.2, w = 0.13 + r() * 0.05;
        k.box(0, 0.02, R, w, h, 0.1, i % 3 ? STONE : scale(STONE, 0.9));
        k.box(0, 0.02 + h, R, w * 0.7, 0.03, 0.07, scale(STONE, 0.85));
        k.pane(0, 0.08 + h * 0.3, R - 0.05, 0.04, h * 0.35, 3, RUNE_DAY, SOFT, MINT);
      }
    });
  }
  // one fallen stone, and low glowing marks on the ground at the ring's foot
  k.turned(0.9, () => k.box(0, 0.02, -0.82, 0.38, 0.08, 0.14, scale(STONE, 0.95)));
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + 0.2;
    k.glowBox(Math.cos(a) * 0.8, 0.02, Math.sin(a) * 0.8, 0.04, 0.012, 0.04, hex(0x6f8a7a), SOFT, MINT);
  }
};

/**
 * A crop circle: a field of ripe grain with its tramlines, and pressed into it rings within rings, a
 * pressed centre with a standing tuft, three spokes, three satellite circles and three small outliers.
 */
const cropCircle: Draw = (k, W, D) => {
  const CROP = hex(0xd29c32), CROP_DARK = hex(0xb4822a), PRESSED = hex(0xf2e2a8);
  const w = W - 0.2, d = D - 0.2;
  k.box(0, 0, 0, w, 0.035, d, scale(CROP, 0.85), CROP);
  // drill rows and two tramlines across the field
  for (let i = 0; i < 14; i++) {
    const z = -d / 2 + 0.1 + i * ((d - 0.2) / 13);
    strip(k, -w / 2 + 0.02, z, w / 2 - 0.02, z, 0.025, 0.0365, CROP_DARK);
  }
  for (const x of [-0.75, 0.75]) for (const o of [-0.06, 0.06]) strip(k, x + o, -d / 2 + 0.02, x + o, d / 2 - 0.02, 0.03, 0.038, hex(0xb08a36));
  // the pattern, pressed flat
  const y = 0.041;
  annulus(k, 0, 0, 1.06, 1.18, y, PRESSED, 32);
  annulus(k, 0, 0, 0.66, 0.76, y, PRESSED, 28);
  flatDisc(k, 0, 0, 0.38, y, PRESSED, 20);
  flatDisc(k, 0, 0, 0.09, y + 0.004, CROP, 10);
  annulus(k, 0, 0, 0.2, 0.24, y + 0.004, CROP, 16);
  for (let i = 0; i < 3; i++) {
    const a = (i / 3) * TAU - Math.PI / 2;
    strip(k, Math.cos(a) * 0.37, Math.sin(a) * 0.37, Math.cos(a) * 0.67, Math.sin(a) * 0.67, 0.07, y, PRESSED);
    const b = a + Math.PI / 3;
    flatDisc(k, Math.cos(b) * 0.91, Math.sin(b) * 0.91, 0.13, y, PRESSED, 12);
    const c = a;
    flatDisc(k, Math.cos(c) * 1.3, Math.sin(c) * 1.3, 0.08, y, PRESSED, 10);
  }
};

