/**
 * A race (docs/missions.html, Races): the player against a rival, from a town's square to a finish a
 * few hundred tiles off, any way they like.
 *
 * Built for more than one kind of racer. Everyone in a race is an `Entrant`: the player at this
 * keyboard, a CPU rival driven by `RaceDriver`, or — later — a player on another machine whose car is
 * simulated there and whose position arrives over the wire. The race itself only ever reads positions:
 * who is on the start line, when the lights go, who crosses the finish first. `snapshot()` and
 * `apply()` are that state as plain data, so a server can own it and every machine agree on the result.
 *
 * The CPU rival drives the same physics as the player (CarState, its own tuned definition), along the
 * fastest line for its car over whatever ground is quickest (route.ts). While its cell is in memory it
 * is a real car you can rub against; if it drops out of memory (it pulled away out of sight, or fell far
 * behind) it runs on along its line at the pace the planner expects of it, and becomes a car again when
 * its cell comes back. There is no catch-up: nobody is slowed or hurried to keep it close.
 */
import * as THREE from 'three';
import { N, heightAt, type World } from '../../world/tiles';
import { CarState } from '../car';
import type { LandDef, VehicleDef, VehicleState } from '../vehicles';
import { halfSize } from '../vehicles';
import { buildVehicleMesh, disposeVehicleMesh, poseVehicleMesh, type VehicleMesh } from '../../render/vehicleMeshes';
import { GroundRing, drapeMat, groundOf } from '../../render/drape';
import { fastRoute, along, remaining, HOLD, type Route } from './route';
import { applyTricks, newTricks, TUNE } from '../cpuTricks';
import type { Controls } from '../vehicles';
import type { PlaceRef } from '../missions/model';
import { startPrompt } from '../startPrompt';

type EntrantKind = 'local' | 'cpu' | 'remote';

/** Anyone in a race, however their car is driven. Positions are world tiles. */
interface Entrant {
  id: string;
  name: string;
  kind: EntrantKind;
  pos(): { x: number; z: number; heading: number; v: number } | null;
  /** Seconds from the start to the finish, once over the line. */
  finished: number | null;
}

export type Phase = 'waiting' | 'grid' | 'running' | 'done';

/** The race as data: what a server would send and every machine would agree on. */
interface RaceSnapshot {
  id: number;
  phase: Phase;
  /** Seconds since the lights went (negative on the grid: the countdown). */
  t: number;
  from: PlaceRef;
  to: PlaceRef;
  entrants: { id: string; name: string; kind: EntrantKind; x: number; z: number; heading: number; v: number; finished: number | null }[];
}

interface RaceHost {
  worldAt(cx: number, cz: number): World | null;
  /** The player: world tiles, the vehicle state in its island's frame, and the island. */
  player(): { w: World; state: VehicleState; def: VehicleDef } | null;
  /** Freeze the player's controls (the countdown), or let them go. */
  hold(on: boolean): void;
  /** Enter was pressed this frame. */
  go(): boolean;
  say(title: string, body: string): void;
  /** The player was shoved: the camera, the sound, the pad. */
  bump(strength: number): void;
  /** Traffic in this island's frame, for the rival to brake behind. */
  traffic(w: World): { x: number; z: number }[];
  beep(final: boolean): void;
  /** How it ended: won, and by how many seconds (either way). */
  ended(won: boolean, margin: number): void;
}

/** How near the start line the player must stop, and how near the finish counts as over it. */
const START_R = 6, FINISH_R = 4.5;
const COUNT = 3;

/**
 * The CPU's hands: look ahead along the line, steer at that point, lift and brake for what is coming,
 * burn the nitrous down a long straight, and back out of anything it has driven into.
 */
export class RaceDriver {
  i = 1;
  private stuck = 0;
  private backed = false;
  private bestI = 0;
  private bestD = Infinity;
  private backing = 0;
  private backSteer = 0;
  private boostLeft = 0;
  private boostCool = 4;
  private blocked = 0;
  ghosts = 0;
  /** Times it was put back on its line after running wide into a wall. */
  nudges = 0;
  /** Slide sharp corners on the handbrake (a fitted one), as a skilled hired driver does (cpuTricks.ts). */
  drift = false;
  /** The fastest it may go this frame, tiles a second: a night op holds a car back with it. */
  cap = Infinity;
  private tricks = newTricks();

  constructor(private route: Route, private def: LandDef) {}

  /** Controls for a car at (x, z) world tiles; `ahead` is traffic in the same frame, world tiles. */
  controls(x: number, z: number, heading: number, v: number, dt: number, ahead: { x: number; z: number }[]): { throttle: number; steer: number; boost: number; handbrake: boolean; teleport?: { x: number; z: number; heading: number } } {
    const pts = this.route.pts;
    // move the target on past points already reached (or passed close by)
    while (this.i < pts.length - 1) {
      const p = pts[this.i];
      const d = Math.hypot(p.x - x, p.z - z);
      const n = pts[this.i + 1];
      const dn = Math.hypot(n.x - x, n.z - z);
      if (d < 1.4 || dn < d - 0.2) this.i++;
      else break;
    }
    const look = 1.1 + Math.abs(v) * 0.45;
    const tgt = along(pts, this.i, x, z, look);
    const want = Math.atan2(tgt.x - x, tgt.z - z);
    const err = wrap(want - heading);
    let steer = Math.max(-1, Math.min(1, err * 2.4));
    // the sharpest bend coming up, and the speed that takes it
    const bend = this.bendAhead(x, z, 3 + Math.abs(v) * 1.6);
    const top = this.def.topSpeed;
    let safe = top * Math.max(0.35, 1 - 0.55 * Math.min(1, bend / 1.4));
    if (this.drift && this.def.drift) safe = Math.max(safe, Math.min(top, TUNE.entry));
    let throttle = v < safe ? 1 : v > safe + 0.25 ? -1 : 0;
    if (Math.abs(err) > 1.2 && v > 1) throttle = -1;
    // a car stopped in the way: brake behind it, and after a moment go round (through, if need be)
    const fx = Math.sin(heading), fz = Math.cos(heading);
    let block = false;
    for (const a of ahead) {
      const dx = a.x - x, dz = a.z - z, fwd = dx * fx + dz * fz, side = Math.abs(dx * fz - dz * fx);
      if (fwd > 0.3 && fwd < 1.2 + v * 0.5 && side < 0.45) { block = true; break; }
    }
    this.blocked = block ? this.blocked + dt : 0;
    if (block && this.blocked < 1.6) throttle = v > 0.2 ? -1 : 0;
    // nitrous down a straight
    let boost = 0;
    const nos = this.def.nitrous;
    this.boostCool -= dt;
    if (this.boostLeft > 0) { this.boostLeft -= dt; boost = nos ? nos.mul - 1 : 0; }
    else if (nos && this.boostCool <= 0 && bend < 0.2 && v > top * 0.6 && remaining(pts, this.i, x, z) > 25) {
      this.boostLeft = nos.secs;
      this.boostCool = 16;
    }
    // stuck against something: back out, steering the other way, and in the end jump on down the line
    if (this.backing > 0) {
      this.backing -= dt;
      return { throttle: -1, steer: this.backSteer, boost: 0, handbrake: false };
    }
    // no progress down the line: back out once, and if that doesn't free it, on to the next point of the line
    const toward = Math.hypot(pts[this.i].x - x, pts[this.i].z - z);
    if (this.i > this.bestI || toward < this.bestD - 0.5) { this.bestI = this.i; this.bestD = toward; this.stuck = 0; this.backed = false; }
    else this.stuck += dt;
    if (this.stuck > 6) {
      this.stuck = 0;
      this.backed = false;
      this.ghosts++;
      let k = Math.min(pts.length - 1, this.i + 1);
      while (k < pts.length - 1 && Math.hypot(pts[k].x - x, pts[k].z - z) < 2.5) k++;
      const p = pts[k], q = pts[Math.min(pts.length - 1, k + 1)];
      this.i = k;
      this.bestI = k;
      this.bestD = Infinity;
      return { throttle: 0, steer: 0, boost: 0, handbrake: false, teleport: { x: p.x, z: p.z, heading: Math.atan2(q.x - p.x, q.z - p.z) || 0 } };
    }
    // wedged against a wall a corner too fast: back onto the line where it left it, as a car scrapes off
    if (this.stuck > 1.2 && !this.backed) {
      this.backed = true;
      this.nudges++;
      const a = pts[Math.max(0, this.i - 1)], b = pts[this.i];
      const ex = b.x - a.x, ez = b.z - a.z, l2 = ex * ex + ez * ez || 1;
      const f = Math.max(0, Math.min(1, ((x - a.x) * ex + (z - a.z) * ez) / l2));
      return { throttle: 0, steer: 0, boost: 0, handbrake: false, teleport: { x: a.x + ex * f, z: a.z + ez * f, heading: Math.atan2(ex, ez) || heading } };
    }
    if (boost) steer *= 0.8;
    let handbrake = false;
    if (this.drift && this.def.drift) {
      const c: Controls = { throttle, steer, lift: 0, boost, handbrake: false };
      const target = applyTricks(this.tricks, { nitrous: false, drift: true }, this.def, v, safe, this.cornerAhead(x, z, heading), 0, true, err, dt, c);
      if (c.handbrake) { handbrake = true; steer = c.steer; throttle = v < target ? 1 : 0; }
    }
    if (v > this.cap) throttle = Math.min(throttle, v > this.cap + 0.25 ? -1 : 0);
    return { throttle, steer, boost, handbrake };
  }

  /** The first sharp turn in the next few tiles of line, as the traffic reads a corner: how sharp, and how far. */
  private cornerAhead(x: number, z: number, heading: number): { angle: number; dist: number } | null {
    const pts = this.route.pts;
    let px = x, pz = z;
    for (let d = 0.6; d <= 3.6; d += 0.6) {
      const q = along(pts, this.i, x, z, d);
      if (Math.hypot(q.x - px, q.z - pz) < 0.2) continue;
      const a = Math.abs(wrap(Math.atan2(q.x - px, q.z - pz) - heading));
      if (a > 1.1) return { angle: a, dist: Math.max(0, d - 0.6) };
      px = q.x; pz = q.z;
    }
    return null;
  }

  /** The largest change of direction along the next `range` tiles of line, in radians. */
  private bendAhead(x: number, z: number, range: number): number {
    const pts = this.route.pts;
    let best = 0, lastA = NaN, px = x, pz = z;
    for (let d = 2; d <= range + 2; d += 2) {
      const q = along(pts, this.i, x, z, d);
      const a = Math.atan2(q.x - px, q.z - pz);
      if (Math.hypot(q.x - px, q.z - pz) > 0.5) {
        if (!Number.isNaN(lastA)) best = Math.max(best, Math.abs(wrap(a - lastA)));
        lastA = a;
      }
      px = q.x; pz = q.z;
    }
    return best;
  }
}

/** A CPU racer: a real car while its cell is in memory, a point running down its line while it is not. */
export class CpuRacer implements Entrant {
  kind: EntrantKind = 'cpu';
  finished: number | null = null;
  w: World | null = null;
  state: CarState | null = null;
  mesh: VehicleMesh;
  group = new THREE.Group();
  driver: RaceDriver | null = null;
  route: Route | null = null;
  /** Off screen: seconds along the route it has run, and the cell it vanished into (not looked for again until it has left it). */
  ghostT = 0;
  lost = '';
  x: number; z: number; heading: number;

  constructor(public id: string, public name: string, public def: LandDef, x: number, z: number, heading: number, scene: THREE.Scene) {
    this.x = x; this.z = z; this.heading = heading;
    this.mesh = buildVehicleMesh(def);
    this.group.add(this.mesh.holder);
    scene.add(this.group);
  }

  pos() { return { x: this.x, z: this.z, heading: this.heading, v: this.state?.v ?? (this.route ? 1 : 0) }; }

  /** Put the car down at (x, z) world tiles, heading this way, if its cell is in memory. */
  place(worldAt: RaceHost['worldAt'], x: number, z: number, heading: number): boolean {
    const w = worldAt(Math.floor(x / N), Math.floor(z / N));
    this.x = x; this.z = z; this.heading = heading;
    if (!w) { this.w = null; this.state = null; this.group.visible = false; return false; }
    this.w = w;
    this.state = new CarState(this.def, x - w.ox, z - w.oz, heading, w);
    this.group.visible = true;
    return true;
  }

  /** Hand the car to the next cell when it drives over a border; null when that cell isn't in memory. */
  rebase(worldAt: RaceHost['worldAt']): boolean {
    const s = this.state, w = this.w;
    if (!s || !w) return false;
    if (s.x >= 0 && s.z >= 0 && s.x < N && s.z < N) return true;
    const gx = w.ox + s.x, gz = w.oz + s.z;
    const nw = worldAt(Math.floor(gx / N), Math.floor(gz / N));
    if (!nw) return false;
    s.x = gx - nw.ox;
    s.z = gz - nw.oz;
    this.w = nw;
    return true;
  }

  pose(): void {
    if (!this.state || !this.w) return;
    this.group.position.set(this.w.ox, 0, this.w.oz);
    poseVehicleMesh(this.mesh, this.state, this.def, this.w);
  }

  dispose(): void {
    this.group.parent?.remove(this.group);
    disposeVehicleMesh(this.mesh);
  }
}

/** The player, as an entrant. */
class LocalRacer implements Entrant {
  kind: EntrantKind = 'local';
  finished: number | null = null;
  constructor(public id: string, public name: string, private host: RaceHost) {}
  pos() {
    const p = this.host.player();
    return p ? { x: p.w.ox + p.state.x, z: p.w.oz + p.state.z, heading: p.state.heading, v: p.state.v } : null;
  }
}

/**
 * A racer somewhere else: its position is whatever last arrived. Nothing drives it here; this is the
 * seam a network race plugs into (docs/multiplayer.html), and the race treats it exactly like the others.
 */
class RemoteRacer implements Entrant {
  kind: EntrantKind = 'remote';
  finished: number | null = null;
  last: { x: number; z: number; heading: number; v: number } | null = null;
  constructor(public id: string, public name: string) {}
  pos() { return this.last; }
}

export class Race {
  phase: Phase = 'waiting';
  t = 0;
  readonly entrants: Entrant[] = [];
  private cpu: CpuRacer | null = null;
  private me: LocalRacer;
  private marks = new THREE.Group();
  private finishRing: GroundRing;
  private beam: THREE.Mesh;
  private startRing: GroundRing;
  private count = document.createElement('div');
  private tag = document.createElement('div');
  private lastCount = -1;
  /** The player's average pace so far, for the margin when the rival wins. */
  private meDist = 0;
  private meLast: { x: number; z: number } | null = null;
  private result: { won: boolean; margin: number } | null = null;
  /** Who led when the player was last told (+1 you, −1 the rival), and when: a card as the lead changes. */
  private led = 0;
  private ledAt = -Infinity;

  constructor(
    readonly id: number,
    private host: RaceHost,
    private scene: THREE.Scene,
    readonly from: PlaceRef,
    readonly to: PlaceRef,
    rival: { id: string; name: string; def: LandDef } | null,
    playerName = 'You',
  ) {
    this.me = new LocalRacer('me', playerName, host);
    this.entrants.push(this.me);
    if (rival) {
      // the rival waits beside the start line, facing the way the race goes
      const heading = Math.atan2(to.x - from.x, to.z - from.z);
      const side = 1.3;
      const x = from.x + Math.cos(heading) * side, z = from.z - Math.sin(heading) * side;
      this.cpu = new CpuRacer(rival.id, rival.name, rival.def, x, z, heading, scene);
      this.cpu.place(host.worldAt, x, z, heading);
      this.entrants.push(this.cpu);
    }
    // the rings: a white one on the start line, a yellow one with a beam at the finish, each lying on the
    // ground under it (render/drape.ts) rather than flat at its middle's height, where a slope hid half of it
    this.startRing = new GroundRing(START_R * 0.6, 0.18, drapeMat(0xffffff, 0.9));
    this.finishRing = new GroundRing(FINISH_R, 0.18, drapeMat(0xf5cf3a, 0.9));
    const beamMat = new THREE.MeshBasicMaterial({ color: 0xf5cf3a, transparent: true, opacity: 0.28, depthWrite: false });
    this.beam = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.5, 60, 12, 1, true), beamMat);
    this.marks.add(this.startRing.mesh, this.finishRing.mesh, this.beam);
    scene.add(this.marks);
    this.placeMarks();
    this.count.className = 'race-count';
    this.tag.className = 'race-tag';
    this.count.hidden = true;
    this.tag.hidden = true;
    document.body.append(this.count, this.tag);
  }

  /** The rings sit on the ground where their cells are in memory. */
  private placeMarks(): void {
    const ground = (p: PlaceRef) => {
      const w = this.host.worldAt(Math.floor(p.x / N), Math.floor(p.z / N));
      return w ? heightAt(w, p.x - w.ox, p.z - w.oz) : NaN;
    };
    const yf = ground(this.to);
    const laid = groundOf((cx, cz) => this.host.worldAt(cx, cz));
    this.startRing.mesh.visible = this.phase !== 'running' && this.phase !== 'done' && this.startRing.place(this.from.x, this.from.z, laid);
    this.finishRing.mesh.visible = this.finishRing.place(this.to.x, this.to.z, laid);
    this.beam.visible = !Number.isNaN(yf);
    this.beam.position.set(this.to.x, (Number.isNaN(yf) ? 0 : yf) + 30, this.to.z);
  }

  /** The player is on the line and has pressed go: plan the rival's line and start the countdown. */
  private start(): void {
    const p = this.me.pos();
    if (!p) return;
    if (this.cpu) {
      // line up alongside the player, the way they are facing
      const side = 1.25;
      const x = p.x + Math.cos(p.heading) * side, z = p.z - Math.sin(p.heading) * side;
      if (!this.cpu.place(this.host.worldAt, x, z, p.heading)) this.cpu.place(this.host.worldAt, p.x, p.z, p.heading);
      const route = fastRoute(this.host.worldAt, this.cpu.def, this.cpu.x, this.cpu.z, this.to.x, this.to.z);
      if (!route) {
        this.host.say('No race today', `${this.cpu.name} can’t find a way to ${this.to.name} from here`);
        this.finish(true, 0);
        return;
      }
      this.cpu.route = route;
      this.cpu.driver = new RaceDriver(route, this.cpu.def);
    }
    this.phase = 'grid';
    this.t = -COUNT;
    this.host.hold(true);
    this.meLast = { x: p.x, z: p.z };
  }

  update(dt: number, paused: boolean): void {
    if (this.phase === 'done') return;
    this.placeMarks();
    const p = this.me.pos();
    if (paused) { this.render(p); return; }
    const t = performance.now() / 1000;
    this.beam.scale.x = this.beam.scale.z = 1 + Math.sin(t * 2) * 0.12;
    if (this.phase === 'waiting') {
      // the rival sits on the start line, engine idling; the player pulls up beside and presses Enter
      if (this.cpu && !this.cpu.state) this.cpu.place(this.host.worldAt, this.cpu.x, this.cpu.z, this.cpu.heading);
      const near = p && Math.hypot(p.x - this.from.x, p.z - this.from.z) <= START_R;
      const stopped = !!p && Math.abs(p.v) < 0.6;
      // on the line and stopped: the start prompt (game/startPrompt.ts) for as long as Enter would start it
      if (near && stopped) startPrompt.show(`race${this.id}`, { key: 'Enter', title: this.cpu ? `Race · vs ${this.cpu.name}` : 'Race', action: 'start the race', sub: `First to ${this.to.name}` });
      else startPrompt.hide(`race${this.id}`);
      if (near && stopped && this.host.go()) { startPrompt.hide(`race${this.id}`); this.start(); }
    } else if (this.phase === 'grid') {
      this.t += dt;
      const n = Math.ceil(-this.t);
      if (n !== this.lastCount && n > 0) { this.lastCount = n; this.host.beep(false); }
      if (this.t >= 0) {
        this.phase = 'running';
        this.host.hold(false);
        this.host.beep(true);
        this.lastCount = 0;
      }
    } else if (this.phase === 'running') {
      this.t += dt;
      this.runCpu(dt);
      this.contact();
      if (p && this.meLast) {
        const step = Math.hypot(p.x - this.meLast.x, p.z - this.meLast.z);
        if (step < 5) this.meDist += step;
        this.meLast = { x: p.x, z: p.z };
      }
      this.checkFinish();
    }
    if (this.cpu) this.cpu.pose();
    this.render(p);
  }

  /** The rival's frame: drive it where it is a car, run it down its line where it isn't. */
  private runCpu(dt: number): void {
    const c = this.cpu;
    if (!c || !c.route || !c.driver || c.finished !== null) return;
    if (c.state && c.w) {
      const s = c.state, w = c.w;
      const gx = w.ox + s.x, gz = w.oz + s.z;
      const ahead = this.host.traffic(w).map((a) => ({ x: a.x + w.ox, z: a.z + w.oz }));
      const me = this.me.pos();
      if (me) ahead.push({ x: me.x, z: me.z });
      const k = c.driver.controls(gx, gz, s.heading, s.v, dt, ahead);
      if (k.teleport) {
        if (!c.place(this.host.worldAt, k.teleport.x, k.teleport.z, k.teleport.heading)) {
          c.ghostT = this.timeAt(c.route, c.driver.i);
          c.lost = cellKey(k.teleport.x, k.teleport.z);
        }
      } else {
        s.step(w, { throttle: k.throttle, steer: k.steer, lift: 0, boost: k.boost, handbrake: k.handbrake }, dt);
        if (!c.rebase(this.host.worldAt)) {
          // over a border into a cell not in memory: it runs on down its line from here
          c.lost = cellKey(w.ox + s.x, w.oz + s.z);
          c.state = null;
          c.w = null;
          c.group.visible = false;
          c.ghostT = this.timeAt(c.route, c.driver.i);
        }
      }
      if (c.state && c.w) {
        c.x = c.w.ox + c.state.x;
        c.z = c.w.oz + c.state.z;
        c.heading = c.state.heading;
      }
    } else {
      // off screen: along the line at the planner's pace, which is already the pace a real car holds
      c.ghostT += dt;
      const pts = c.route.pts;
      let k = c.driver.i;
      while (k < pts.length - 1 && pts[k].t < c.ghostT) k++;
      c.driver.i = k;
      const a = pts[Math.max(0, k - 1)], b = pts[k];
      const f = b.t > a.t ? Math.min(1, Math.max(0, (c.ghostT - a.t) / (b.t - a.t))) : 1;
      c.x = a.x + (b.x - a.x) * f;
      c.z = a.z + (b.z - a.z) * f;
      c.heading = Math.atan2(b.x - a.x, b.z - a.z);
      // in a cell that is in memory (and not the one it just vanished into): a car again
      const here = cellKey(c.x, c.z);
      if (here !== c.lost) {
        c.lost = '';
        c.place(this.host.worldAt, c.x, c.z, c.heading);
        if (c.state) c.state.v = c.def.topSpeed * 0.6;
      }
    }
  }

  /** Where the planner expected to be at point i, in seconds. */
  private timeAt(r: Route, i: number): number { return r.pts[Math.min(r.pts.length - 1, i)].t; }

  /** Rubbing is racing: the rival and the player shove each other apart, sharing the knock. */
  private contact(): void {
    const c = this.cpu, pl = this.host.player();
    if (!c || !c.state || !c.w || !pl || pl.w !== c.w) return;
    const a = pl.state, b = c.state;
    const [al, aw] = halfSize(pl.def), [bl, bw] = halfSize(c.def);
    const reach = (Math.max(aw, al * 0.7) + Math.max(bw, bl * 0.7)) * 0.9;
    const dx = b.x - a.x, dz = b.z - a.z, d = Math.hypot(dx, dz);
    if (d >= reach || d < 1e-4) return;
    const nx = dx / d, nz = dz / d, push = reach - d;
    a.x -= nx * push * 0.45; a.z -= nz * push * 0.45;
    b.x += nx * push * 0.55; b.z += nz * push * 0.55;
    const closing = (Math.sin(a.heading) * a.v - Math.sin(b.heading) * b.v) * nx + (Math.cos(a.heading) * a.v - Math.cos(b.heading) * b.v) * nz;
    if (closing > 0.2) {
      a.v *= 0.86; b.v *= 0.86;
      this.host.bump(Math.min(1, closing / 3));
    }
  }

  private checkFinish(): void {
    for (const e of this.entrants) {
      if (e.finished !== null) continue;
      const q = e.pos();
      if (q && Math.hypot(q.x - this.to.x, q.z - this.to.z) <= FINISH_R) e.finished = this.t;
    }
    const me = this.me, c = this.cpu;
    if (me.finished !== null) {
      // the player is over: by how much, from how far the rival still had to run
      let margin = 0;
      if (c && c.finished === null && c.route && c.driver) {
        const left = remaining(c.route.pts, c.driver.i, c.x, c.z);
        const pace = Math.max(0.5, (c.route.tiles / Math.max(1, c.route.seconds)));
        margin = left / pace;
      } else if (c?.finished !== null && c) margin = c.finished - me.finished;
      this.finish(!c || c.finished === null || me.finished <= c.finished, Math.abs(margin));
    } else if (c && c.finished !== null) {
      const p = me.pos();
      const left = p ? Math.hypot(p.x - this.to.x, p.z - this.to.z) * 1.15 : 999;
      const pace = this.meDist > 5 && this.t > 1 ? this.meDist / this.t : Math.max(0.5, c.route ? c.route.tiles / c.route.seconds : 1);
      this.finish(false, left / Math.max(0.3, pace));
    }
  }

  /** Given up (the journal's Abandon, or driving off far enough to call it a day). */
  giveUp(): void {
    if (this.phase === 'done') return;
    this.finish(false, -1);
  }

  private finish(won: boolean, margin: number): void {
    if (this.phase === 'done') return;
    this.phase = 'done';
    this.host.hold(false);
    this.result = { won, margin };
    this.host.ended(won, margin);
  }

  /**
   * The countdown, and a card whenever the lead changes hands (nothing is written along the foot of the
   * screen: the mission tracker has the finish, and the result comes as a card of its own).
   */
  private render(p: { x: number; z: number } | null): void {
    const c = this.cpu;
    this.count.hidden = this.phase !== 'grid' && !(this.phase === 'running' && this.t < 0.8);
    if (!this.count.hidden) {
      const n = Math.ceil(-this.t);
      const txt = this.phase === 'grid' ? String(Math.max(1, n)) : 'GO';
      if (this.count.textContent !== txt) { this.count.textContent = txt; this.count.classList.remove('pop'); void this.count.offsetWidth; this.count.classList.add('pop'); }
    }
    if (this.phase === 'running' && p && c && c.route && c.driver) {
      const left = Math.max(0, Math.hypot(p.x - this.to.x, p.z - this.to.z) - FINISH_R);
      // the gap in seconds: how much further the rival has to go than you, at the rival's pace
      const theirs = remaining(c.route.pts, c.driver.i, c.x, c.z);
      const pace = Math.max(0.5, c.route.tiles / Math.max(1, c.route.seconds));
      const s = (theirs - left * 1.1) / pace;
      // a second either way is noise: only a clear lead counts, and the cards are kept a few seconds apart
      const lead = s > 1 ? 1 : s < -1 ? -1 : this.led;
      if (lead !== this.led && this.t - this.ledAt > 8) {
        const who = c.name.split(' ')[0];
        if (this.led !== 0 || lead < 0) this.host.say(lead > 0 ? '🏁 You lead' : `🏁 ${who} leads`, `${Math.round(left)} tiles to ${this.to.name}`);
        this.led = lead;
        this.ledAt = this.t;
      }
    }
    this.tag.hidden = true;
  }

  /** The rival's name tag, projected over its car. */
  label(camera: THREE.Camera): void {
    const c = this.cpu;
    if (!c || !c.state || !c.w || this.phase === 'done') { this.tag.hidden = true; return; }
    const v = new THREE.Vector3(c.w.ox + c.state.x, c.state.y + 0.9, c.w.oz + c.state.z).project(camera);
    if (v.z > 1) { this.tag.hidden = true; return; }
    this.tag.hidden = false;
    this.tag.textContent = c.name;
    this.tag.style.transform = `translate(${((v.x + 1) / 2) * innerWidth}px, ${((1 - v.y) / 2) * innerHeight}px) translate(-50%, -100%)`;
  }

  /** Where the rival is, for the map and the tracker. */
  rival(): { x: number; z: number } | null { return this.cpu ? { x: this.cpu.x, z: this.cpu.z } : null; }
  get over(): { won: boolean; margin: number } | null { return this.result; }

  // ---- the wire ----

  snapshot(): RaceSnapshot {
    return {
      id: this.id, phase: this.phase, t: this.t, from: this.from, to: this.to,
      entrants: this.entrants.map((e) => { const q = e.pos() ?? { x: 0, z: 0, heading: 0, v: 0 }; return { id: e.id, name: e.name, kind: e.kind, ...q, finished: e.finished }; }),
    };
  }

  /** Take the phase, the clock and the remote racers' positions from a snapshot someone else owns. */
  apply(s: RaceSnapshot): void {
    this.phase = s.phase;
    this.t = s.t;
    for (const q of s.entrants) {
      let e = this.entrants.find((x) => x.id === q.id);
      if (!e) { e = new RemoteRacer(q.id, q.name); this.entrants.push(e); }
      if (e instanceof RemoteRacer) { e.last = { x: q.x, z: q.z, heading: q.heading, v: q.v }; e.finished = q.finished; }
    }
  }

  dispose(): void {
    this.host.hold(false);
    this.cpu?.dispose();
    this.scene.remove(this.marks);
    this.marks.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) { m.geometry.dispose(); (m.material as THREE.Material).dispose(); } });
    this.count.remove();
    this.tag.remove();
    startPrompt.hide(`race${this.id}`);
  }
}

const cellKey = (x: number, z: number) => `${Math.floor(x / N)},${Math.floor(z / N)}`;
const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));
void HOLD;
