import { DEEDS, DEED_GROUPS, deeds, type Deed } from './deeds';
import { PAGE_LABEL, SIGHT_PAGES, SIGNATURES, pageKeys, sights, type SightPage } from './sights';

/**
 * The Passport's treats (the user, 28 Oct 2026): a seal on every page filled, and a treat with it; and for the
 * whole book, every stamp on every page, the Gilded Fleet. A seal is kept once earned (in the deeds' record, so
 * it travels with an online career): a page that grows in an update shows its seal open again until the new
 * stamps are in, but the treat it gave stays.
 *
 * What a treat is lives here; what it looks like lives with what draws it (render/wonderBall.ts, render/paintjob.ts,
 * render/liveryPaint.ts …), each asking `rewards.has(…)`. The perks are small multipliers read where the pay is.
 */

/** A seal: one of the seven sights pages, the signature buildings, a visa page (a group of deeds), or the book. */
export type SealId = SightPage | 'sig' | `visa:${string}` | 'book';

export interface Treat { name: string; icon: string; blurb: string }

