/** The pages that make the whole book: every stamp in it. The visas are deeds' tiers, not stamps, and aren't asked for. */
export const BOOK_PAGES: (SightPage | 'sig')[] = [...SIGHT_PAGES, 'sig'];

const sigKinds = (): string[] => [...new Set([...SIGNATURES.values()].flat())];
const groupDeeds = (g: string): Deed[] => DEEDS.filter((d) => d.group === g);

/** A page's stamps got and the room it has: a visa page counts its deeds' tiers, five a deed. */
export function pageTally(id: SealId): [number, number] {
  if (id === 'book') {
    const t = BOOK_PAGES.map((p) => pageTally(p));
    return [t.reduce((s, [a]) => s + a, 0), t.reduce((s, [, b]) => s + b, 0)];
  }
  if (id === 'sig') { const k = sigKinds(); return [k.filter((x) => sights.has('kind', x)).length, k.length]; }
  if (id.startsWith('visa:')) {
    const list = groupDeeds(id.slice(5));
    return [list.reduce((s, d) => s + deeds.tier(d), 0), list.length * 5];
  }
  const keys = pageKeys(id as SightPage);
  return [keys.filter((k) => sights.has(id as SightPage, k)).length, keys.length];
}

/** Every stamp the page has room for is in. */
export function pageFull(id: SealId): boolean {
  const [got, all] = pageTally(id);
  return all > 0 && got >= all;
}

/** A seal's own name: the page's, or the group's for a visa. */
export function sealLabel(id: SealId): string {
  if (id === 'book') return 'The whole Passport';
  if (id === 'sig') return 'Signature buildings';
  if (id.startsWith('visa:')) return `${id.slice(5)} achievements`;
  return PAGE_LABEL[id as SightPage];
}
