export const treatOf = (id: SealId): Treat => (id.startsWith('visa:') ? VISA_TREATS[id.slice(5)] ?? TREATS.visa : TREATS[id as SightPage | 'sig' | 'book']);

/** Every seal there is, in the book's order. */
export function allSeals(): SealId[] {
  return [...BOOK_PAGES, ...DEED_GROUPS.map((g) => `visa:${g}` as SealId), 'book'];
}

/** Gold, for anything gilded: the paint, the buildings, the name. */
export const GOLD = 0xd4af37, GOLD_DEEP = 0xa8801f;

export class Rewards {
  /** A page sealed this time: the card, the paper, the chat (main.ts). */
  onSeal: ((id: SealId) => void) | null = null;
  private seenRev = '';

  /** A seal earned, ever: its treat is the player's. */
  has(id: SealId): boolean { return deeds.keys('seals').includes(id); }
  /** The visa emblems earned, by group. */
  emblems(): string[] { return deeds.keys('seals').filter((s) => s.startsWith('visa:')).map((s) => s.slice(5)); }
  get gilded(): boolean { return this.has('book'); }

  // the perks: multipliers on what the player is paid, and on what rough ground costs them
  /** On the pace rough ground takes off the player's own vehicles (Expedition, biomes): 10% less of it lost. */
  roughLoss(): number { return this.has('biome') ? 0.9 : 1; }
  /** On a people load's pay (Skyline, town sizes). */
  peopleMul(): number { return this.has('size') ? 1.05 : 1; }
  /** On a load to or from a wonder (the Wonder Ball). */
  wonderMul(): number { return this.has('wonder') ? 1.1 : 1; }
  /** On discovery pay: a new county, a landform, a record (Explorer's lantern). */
  discoveryMul(): number { return this.has('landform') ? 1.1 : 1; }
  /** On an event's prize (Front-row pass). */
  eventMul(): number { return this.has('event') ? 1.1 : 1; }

  /**
   * Look for pages newly filled: each is sealed (kept in the deeds' record) and `onSeal` hears of it, the book's
   * own last. Cheap to call often: it only looks again when a stamp or a deed's tier has changed.
   */
  check(): SealId[] {
    if (!deeds.active) return [];
    const rev = `${sights.revision}|${deeds.revision}`;
    if (rev === this.seenRev) return [];
    this.seenRev = rev;
    const out: SealId[] = [];
    for (const id of allSeals()) {
      if (this.has(id) || !pageFull(id)) continue;
      deeds.mark('seals', id);
      out.push(id);
    }
    for (const id of out) this.onSeal?.(id);
    return out;
  }
}

/** The one set of treats: the current player's. */
export const rewards = new Rewards();
