import * as THREE from 'three';
import { idx, inB, tileAt, type World } from '../world/tiles';
import { joinedByLand, reachOf, OTHER_TAG, type CargoSystem, type CargoTag, type Site } from './cargo';
import { buildCargoMarker, disposeCargoMarker, poseCargoMarker, type CargoMarker } from '../render/cargoMarkers';
import { roadRoute } from './traffic';
import { VEHICLES, type LandDef, type VehicleDef } from './vehicles';
import {
  CONTRABAND, EASY_PACE, HOUR_SECONDS, NIGHT_URGENCY, RUN_MAX, RUN_MIN, SUNRISE,
  byShare, contrabandById, fineFor, honestPrice, isNight, multiplier, nextDawn, offerOpen, payFor,
  type Contraband, type NightUrgency,
} from './nightRules';
import type { Patrol, Police } from './police';
import { deeds } from './deeds';
import { esc, money, type ExtraRow } from './cargoHud';
import { CLASS_LABEL } from './cargoTypes';
import { FACTION_LOOK } from './cargoLook';
import { rand } from '../util/math';

/**
 * Night runs (docs/smuggling.html). After dark, contacts wait at quiet places with contraband: a
 * lantern and a purple ring behind a casino, at the end of a quay, by a barn. Stop in the ring and a
 * card says what it is, where it goes, which towns lie on the way, what it pays and when it must be
 * there; take it and the crates go in the hold, the police come out in force, and the run is on. Stop
 * in the buyer's ring before the deadline (never later than sunrise) and it pays four to ten times an
 * honest load of the same trip, untaxed. Let a patrol car's cone touch you on the way and it is over:
 * sirens, your car brakes to a halt, the car pulls in front, the load is seized and you are fined.
 */

/** Contacts open at once, at most; how long each waits (game hours); how often a new one turns up. */
const MAX_CONTACTS = 3;
const WAIT_HOURS = 3;
const EVERY: [number, number] = [1, 1.8];
/** A contact is somewhere between these many tiles from the player, as the crow flies. */
const NEAR: [number, number] = [12, 90];
/** The buyer is between these many tiles from the contact, as the crow flies (the road is longer). */
const BUYER: [number, number] = [28, 100];
/** How often a contact holds something the player's vehicle could carry. */
const FIT_SHARE = 0.8;
/** Stopped means slower than this (cargo.ts's STOP_SPEED). */
const STOPPED = 0.35;
/** The chasing car aims this far ahead of the player and this far to one side. */
const AHEAD = 2, BESIDE = 0.5;
/** A chase that hasn't got in front by now stops wherever it is. */
const CHASE_MAX = 6;
/** Control comes back this long after the Busted card, which stays this long. */
const CARD_HOLD = 3, CARD_SHOW = 4.5;
/** A night run is the Family's work (docs/cargolook.html): its look, black with a gold rim, on the contact's ring and the buyer's. */
const RUN_LOOK = FACTION_LOOK.family;
/** The bounty over an illegal ring is the Family's gold, to go with the dashed outline and the caution triangle (yellow is missions'). */
const GOLD = '#d9b34a';
/** Taking a run clears every patrol car within this many tiles, so the first mile is the player's. */
const HEAD_START = 20;

interface SmuggleHost {
  /** Game hours since the world began, and the hour of the day. */
  hours(): number;
  hour(): number;
  /** The player in world tiles; null when there is none. */
  player(): { x: number; y: number; z: number; v: number; heading: number } | null;
  def(): VehicleDef;
  /** The camera's yaw, for the chip's arrow. */
  yaw(): number;
  cash(): number;
  earn(n: number): void;
  fine(n: number): void;
  announce(title: string, body: string): void;
  float(text: string, x: number, y: number, z: number, kind: 'cash' | 'fine' | 'info' | 'bad'): void;
  sfx: { chime(tier: number): void; whoop(): void; tick(): void };
  /** Console: set the hour, or move the clock on. */
  setHour(h: number): void;
  advance(hours: number): void;
}

interface Contact {
  id: number;
  kind: Contraband;
  from: Site;
  to: Site;
  tiles: number;
  route: { x: number; z: number }[];
  towns: string[];
  urgency: NightUrgency;
  roll: number;
  pay: number;
  leaves: number;
  marker: CargoMarker;
  lamp: THREE.Group;
  glow: THREE.MeshStandardMaterial;
}

/** A run under way. Everything in world tiles and absolute game hours. */
export interface Run {
  kind: Contraband;
  pay: number;
  urgency: NightUrgency;
  deadline: number;
  dawn: number;
  from: string;
  fromKey: string;
  to: { name: string; x: number; y: number; z: number };
  towns: string[];
  tiles: number;
  route: { x: number; z: number }[] | null;
  /** Near misses on this run: counted for Close Shave if it is delivered. */
  shaves: number;
  /** Put in the hold at a tavern (game/tavern): the police are out for it at any hour. */
  hot?: boolean;
}

interface SmuggleRecord { runs: number; busts: number; earned: number; streak: number; best: number }

export interface SmuggleSave {
  run: {
    k: string; pay: number; u: NightUrgency; deadline: number; dawn: number; from: string; fromKey: string;
    to: { name: string; x: number; y: number; z: number }; towns: string[]; tiles: number; shaves: number; hot?: boolean;
  } | null;
  rec: SmuggleRecord;
}

interface Bust { p: Patrol; t: number; side: number; stage: 'stop' | 'card'; since: number; seized: string; fine: number }

const clock = (s: number) => { const t = Math.max(0, Math.ceil(s)); return `${Math.floor(t / 60)}:${String(t % 60).padStart(2, '0')}`; };
const hhmm = (abs: number) => { const h = ((abs % 24) + 24) % 24; const m = Math.floor((h % 1) * 60); return `${String(Math.floor(h)).padStart(2, '0')}:${String(m).padStart(2, '0')}`; };
const shuffle = <T,>(a: T[]): T[] => { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
const siteKey = (s: Site) => `${s.w.cx},${s.w.cz}:${Math.round(s.lx * 10)},${Math.round(s.lz * 10)}`;

/** The town a site belongs to, as "cx,cz#id", with its name; null out in the country. */
function townOf(s: Site): { key: string; name: string } | null {
  const w = s.w;
  const tiles = s.b ? [[s.b.x, s.b.z], [Math.floor(s.lx), Math.floor(s.lz)]] : [[Math.floor(s.lx), Math.floor(s.lz)]];
  for (const [x, z] of tiles) {
    if (!inB(x, z)) continue;
    const id = w.townId[idx(x, z)];
    if (id >= 0 && w.towns[id]) return { key: `${w.cx},${w.cz}#${id}`, name: w.towns[id].name };
  }
  return null;
}

/** The distinct towns a road route (in w's frame) passes through, in order. */
function townsAlong(w: World, path: { x: number; z: number }[]): Map<string, string> {
  const out = new Map<string, string>();
  for (const p of path) {
    const o = tileAt(w, p.x, p.z);
    const id = o.w.townId[o.i];
    if (id < 0 || !o.w.towns[id]) continue;
    const key = `${o.w.cx},${o.w.cz}#${id}`;
    if (!out.has(key)) out.set(key, o.w.towns[id].name);
  }
  return out;
}

const lengthOf = (path: { x: number; z: number }[]) => path.reduce((s, p, k) => (k ? s + Math.hypot(p.x - path[k - 1].x, p.z - path[k - 1].z) : 0), 0);

export class Smuggling {
  run: Run | null = null;
  /** A run delivered (the Family's thanks), and a bust (the police's), for the factions (docs/factions.html). */
  onRun: ((kind: string, name: string, pay: number, from: string) => void) | null = null;
  onBust: ((name: string, fine: number) => void) | null = null;
  /** What a delivered run's pay is multiplied by (the Family's standing, the vehicle). */
  payMul: (() => number) | null = null;
  record: SmuggleRecord = { runs: 0, busts: 0, earned: 0, streak: 0, best: 0 };
  readonly group = new THREE.Group();
  private contacts: Contact[] = [];
  private nextId = 1;
  private nextAt = 0;
  private time = 0;
  /** Sites whose contact has lost a load tonight: they don't call again until morning. */
  private barred = new Set<string>();
  /** The contact whose card was just turned down: not asked again until the player has left its ring. */
  private dismissed: Contact | null = null;
  private dest: CargoMarker | null = null;
  private bust: Bust | null = null;
  private chipT = 0;
  private card: Contact | null = null;
  private chip: HTMLDivElement;
  private cardEl: HTMLDivElement;
  private bustEl: HTMLDivElement;
  private flashEl: HTMLDivElement;
  private bustTimer = 0;

  constructor(private host: SmuggleHost, private cargo: CargoSystem, private police: Police, scene: THREE.Scene) {
    scene.add(this.group);
    this.chip = document.createElement('div');
    this.chip.className = 'hud chip';
    this.chip.id = 'night-chip';
    this.chip.hidden = true;
    this.chip.addEventListener('click', (e) => { if ((e.target as HTMLElement).closest('button')) this.ditch(); });
    this.cardEl = document.createElement('div');
    this.cardEl.id = 'night-card';
    this.cardEl.hidden = true;
    this.bustEl = document.createElement('div');
    this.bustEl.id = 'bust-card';
    this.bustEl.hidden = true;
    this.flashEl = document.createElement('div');
    this.flashEl.id = 'night-flash';
    this.flashEl.hidden = true;
    document.body.append(this.chip, this.cardEl, this.bustEl, this.flashEl);
    police.onSpotted = (p) => this.spotted(p);
    police.onNearMiss = () => { if (this.run && !this.bust) { this.run.shaves++; this.host.sfx.tick(); } };
  }

  /**
   * How contacts show (set by the missions each frame): 'all' as they are, 'dim' faded behind a mission
   * under way, 'only' not at all — no contact calls during the first drive.
   */
  focus: 'all' | 'dim' | 'only' = 'all';

  /** Is the offer card up? It pauses the world like any other card. */
  get cardOpen(): boolean { return !!this.card; }
  /** A bust is playing out: the player's car is held. */
  get busting(): boolean { return !!this.bust && (this.bust.stage === 'stop' || this.bust.since < CARD_HOLD); }
  /** Contraband aboard, as the police reckon it. */
  get carrying(): boolean { return !!this.run && !this.bust; }

  /** The cargo list is up and shows the run as a card of its own: the chip at the top steps aside (main sets it each frame). */
  listed = false;

  /** The run as a card in the cargo list (game/cargoHud.ts ExtraRow); null with nothing aboard or a bust under way. */
  listRow(): ExtraRow | null {
    const r = this.run;
    if (!r || this.bust) return null;
    const left = (r.deadline - this.host.hours()) * HOUR_SECONDS;
    return {
      icon: r.kind.icon, name: r.kind.name, units: r.kind.units, to: r.to.name, x: r.to.x, z: r.to.z, pay: r.pay,
      note: `Contraband · ${r.deadline >= r.dawn ? 'dawn in' : 'due in'} ${clock(left)} · keep out of the red cones`, late: left < 30,
    };
  }
  /** The run's route in world tiles, for the highway units. */
  routeWorld(): { x: number; z: number }[] | null { return this.run?.route ?? null; }

  /** A new world, or back to the title: nothing waiting, nothing aboard. */
  reset(): void {
    for (const c of this.contacts) this.dropContact(c);
    this.contacts = [];
    this.cargo.extraTags = [];
    this.endRun();
    this.bust = null;
    this.police.busy = false;
    this.barred.clear();
    this.closeCard();
    this.bustEl.hidden = true;
    this.flashEl.hidden = true;
    this.nextAt = 0;
  }

  /**
   * One frame. `dt` is 0 while paused; `live` is false while a menu is up; `worlds` are the cells whose
   * goods are live (a contact whose cell has gone goes with it).
   */
  update(dt: number, live: boolean, worlds: World[]): void {
    const pl = this.host.player();
    if (!pl) { this.cargo.extraTags = []; return; }
    this.time += dt;
    const abs = this.host.hours(), hour = this.host.hour();
    if (dt > 0) {
      // contacts leave after their wait, at dawn, or when their island goes out of range
      for (const c of [...this.contacts]) {
        if (abs >= c.leaves || !isNight(hour) || !worlds.includes(c.from.w)) this.dropContact(c);
      }
      if (!isNight(hour)) { this.barred.clear(); this.nextAt = Math.min(this.nextAt, abs); }
      else if (!this.run && this.focus !== 'only' && this.contacts.length < MAX_CONTACTS && abs >= this.nextAt) {
        this.nextAt = abs + (this.spawn(null, false) ? rand(EVERY[0], EVERY[1]) : 0.2);
      }
    }
    const reach0 = reachOf(this.host.def()), yaw = this.host.yaw();
    const tags: CargoTag[] = [];
    const hidden = this.focus === 'only', dim = this.focus === 'dim';
    for (const c of this.contacts) {
      c.marker.group.visible = c.lamp.visible = !hidden;
      poseCargoMarker(c.marker, this.time, reach0, dim ? 0.4 : 1, yaw);
      c.glow.emissiveIntensity = (1.6 + 0.5 * Math.sin(this.time * 9 + c.id) * Math.sin(this.time * 3.7 + c.id * 2)) * (dim ? 0.4 : 1);
      if (!hidden) tags.push({ key: OTHER_TAG + c.id, text: money(c.pay), pos: new THREE.Vector3(c.from.x, c.from.y + 0.85, c.from.z), goods: true, color: GOLD, dim });
    }
    if (this.dest && this.run) {
      poseCargoMarker(this.dest, this.time, reach0, 1, yaw);
      // the buyer's bounty points the way from the screen edge, like any other destination's
      tags.push({ key: OTHER_TAG, text: money(this.run.pay), pos: new THREE.Vector3(this.run.to.x, this.run.to.y + 0.9, this.run.to.z) });
    }
    this.cargo.extraTags = tags;

    // stopped in a contact's ring with nothing on: the offer
    if (!this.run && !this.card && !this.bust && live && this.focus !== 'only') {
      const reach = reachOf(this.host.def());
      const here = this.contacts.find((c) => Math.hypot(c.from.x - pl.x, c.from.z - pl.z) <= reach);
      if (this.dismissed && (!here || here !== this.dismissed)) this.dismissed = null;
      if (here && here !== this.dismissed && Math.abs(pl.v) < STOPPED) this.openCard(here);
    }

    if (this.bust) this.stepBust(dt, pl);
    else if (this.run && dt > 0) {
      const r = this.run;
      if (abs >= r.deadline) this.fail(r.deadline >= r.dawn);
      else if (live && Math.abs(pl.v) < STOPPED && Math.hypot(r.to.x - pl.x, r.to.z - pl.z) <= reachOf(this.host.def())) this.deliver(pl);
    }
    // the Busted card outlasts the hold on the car by a moment
    if (this.bustTimer > 0) {
      this.bustTimer -= dt;
      if (this.bustTimer <= 0) this.bustEl.hidden = true;
    }
    this.chipT -= dt;
    if (this.chipT <= 0 || dt === 0) { this.chipT = 0.2; this.drawChip(pl); }
  }

  /**
   * Someone the player has done a favour for (a tail that found the fence's drop, game/tail) will deal: after
   * dark, a contact is put out near the player at once; by day, they call at nightfall as contacts do. The line
   * says which.
   */
  invite(): string {
    if (isNight(this.host.hour()) && !this.run) {
      for (let k = 0; k < 6; k++) if (this.spawn(null, true)) return 'A contact is waiting tonight';
    }
    this.nextAt = Math.min(this.nextAt, this.host.hours());
    return 'They’ll call on you after dark';
  }

  // ---- contacts ----

  /**
   * Put a contact out: a kind of contraband, a quiet place near the player, and a buyer in another
   * town whose road route takes in at least two towns and can be driven before dawn. `force` (the
   * console) ignores the hour. False when nothing suitable was found this time.
   */
  spawn(kindId: string | null, force: boolean): boolean {
    const pl = this.host.player();
    if (!pl) return false;
    const hour = this.host.hour();
    const def = this.host.def();
    const land = (def.kind === 'land' ? def : VEHICLES[0]) as LandDef;
    // like any other load, it is usually something the vehicle in hand could take (game/fit.ts)
    const fits = CONTRABAND.filter((c) => def.kind === 'land' && def.holds.includes(c.cls) && c.units <= def.capacity);
    const kind = (kindId && contrabandById(kindId)) || byShare(fits.length && Math.random() < FIT_SHARE ? fits : CONTRABAND, Math.random());
    const froms = shuffle(this.cargo.sitesOfKinds(kind.from).filter((s) => {
      const d = Math.hypot(s.x - pl.x, s.z - pl.z);
      return d >= (force ? 3 : NEAR[0]) && d <= NEAR[1] && !this.barred.has(siteKey(s)) && !this.contacts.some((c) => c.from === s);
    })).slice(0, 2);
    const tos = this.cargo.sitesOfKinds(kind.to);
    let best: { from: Site; to: Site; path: { x: number; z: number }[]; tiles: number; towns: Map<string, string> } | null = null;
    let routes = 0;
    for (const from of froms) {
      const mine = townOf(from);
      const cands = shuffle(tos.filter((s) => {
        if (s === from) return false;
        const d = Math.hypot(s.x - from.x, s.z - from.z);
        if (d < BUYER[0] || d > BUYER[1]) return false;
        if (s.w !== from.w && !joinedByLand(s.w, from.w)) return false;
        const theirs = townOf(s);
        return !!theirs && theirs.key !== mine?.key;
      })).slice(0, 3);
      for (const to of cands) {
        if (++routes > 4) break;
        const path = roadRoute(from.w, land, from.lx, from.lz, to.x - from.w.ox, to.z - from.w.oz);
        if (!path) continue;
        const tiles = lengthOf(path);
        if (tiles < RUN_MIN || tiles > RUN_MAX) continue;
        if (!force && !offerOpen(tiles, hour)) continue;
        const towns = townsAlong(from.w, path);
        const a = townOf(from), b = townOf(to);
        if (a) towns.set(a.key, a.name);
        if (b) towns.set(b.key, b.name);
        if (towns.size < 2) continue;
        if (!best || towns.size > best.towns.size) best = { from, to, path: path.map((p) => ({ x: p.x + from.w.ox, z: p.z + from.w.oz })), tiles, towns };
        if (best.towns.size >= 3) break;
      }
      if (best && best.towns.size >= 3) break;
    }
    if (!best) return false;
    const urgency = byShare((Object.keys(NIGHT_URGENCY) as NightUrgency[]).map((k) => ({ k, share: NIGHT_URGENCY[k].share })), Math.random()).k;
    const roll = Math.random();
    const marker = buildCargoMarker(RUN_LOOK, kind.cls, true);
    marker.group.position.set(best.from.x, best.from.y + 0.04, best.from.z);
    const lamp = new THREE.Group();
    const glow = new THREE.MeshStandardMaterial({ color: 0xffc070, emissive: 0xff9a30, emissiveIntensity: 1.6, roughness: 0.5 });
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, 0.34, 6), new THREE.MeshStandardMaterial({ color: 0x2a2a2e, roughness: 0.9 }));
    pole.position.y = 0.17;
    const bulb = new THREE.Mesh(new THREE.IcosahedronGeometry(0.045, 1), glow);
    bulb.position.y = 0.36;
    lamp.add(pole, bulb);
    lamp.position.set(best.from.x + 0.45, best.from.y, best.from.z + 0.2);
    this.group.add(marker.group, lamp);
    const c: Contact = {
      id: this.nextId++, kind, from: best.from, to: best.to, tiles: Math.round(best.tiles), route: best.path, towns: [...best.towns.values()],
      urgency, roll, pay: payFor(kind, best.tiles, urgency, roll), leaves: this.host.hours() + WAIT_HOURS, marker, lamp, glow,
    };
    this.contacts.push(c);
    const away = Math.round(Math.hypot(c.from.x - pl.x, c.from.z - pl.z));
    this.host.announce('Someone’s waiting', `${c.from.name} · ${away} tiles away · look for the lantern`);
    return true;
  }

  private dropContact(c: Contact): void {
    disposeCargoMarker(c.marker);
    c.lamp.removeFromParent();
    c.lamp.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) { m.geometry.dispose(); (m.material as THREE.Material).dispose(); } });
    this.contacts = this.contacts.filter((q) => q !== c);
    if (this.card === c) this.closeCard();
    if (this.dismissed === c) this.dismissed = null;
  }

  // ---- the offer ----

  /** Why the vehicle in hand can't take this, or null. */
  private whyNot(c: Contact): string | null {
    const def = this.host.def();
    if (def.kind !== 'land') return 'Not in that. Contraband goes by road.';
    if (!def.holds.includes(c.kind.cls)) return `${def.name} can’t carry it.`;
    const free = def.capacity - this.cargo.used();
    if (c.kind.units > free) return `No room: needs ${c.kind.units} unit${c.kind.units === 1 ? '' : 's'}, ${free} free.`;
    return null;
  }

  private openCard(c: Contact): void {
    this.card = c;
    const abs = this.host.hours();
    const dawn = nextDawn(abs);
    const u = NIGHT_URGENCY[c.urgency];
    const est = (c.tiles / EASY_PACE) * (u.slack || 1) + 30;
    const due = u.slack ? Math.min(dawn, abs + est / HOUR_SECONDS) : dawn;
    const why = this.whyNot(c);
    const mult = multiplier(c.kind, c.urgency, c.roll);
    const b = townOf(c.to);
    const panel = document.createElement('div');
    panel.className = 'panel';
    panel.innerHTML = `
      <header><small>A contact · after dark</small><b><span class="ic">${c.kind.icon}</span> ${esc(c.kind.name)}</b></header>
      <div class="stamp">${money(c.pay)}</div>
      <p class="blurb">${esc(c.kind.blurb)}</p>
      <dl>
        <dt>To</dt><dd>${esc(c.to.name)} · ${c.tiles} tiles by road</dd>
        <dt>Through</dt><dd>${c.towns.map(esc).join(' → ')}</dd>
        <dt>Deadline</dt><dd><b class="u-${c.urgency}">${u.label}</b> · by ${hhmm(due)}${due < dawn ? ` · sunrise ${hhmm(dawn)}` : ''}</dd>
        <dt>Time</dt><dd>${clock((due - abs) * HOUR_SECONDS)} to get there</dd>
        <dt>Pays</dt><dd>${mult.toFixed(1)}× an honest load (${money(honestPrice(c.kind, c.tiles))}) · untaxed</dd>
        <dt>Size</dt><dd>${c.kind.units} unit${c.kind.units === 1 ? '' : 's'} of ${CLASS_LABEL[c.kind.cls]}</dd>
      </dl>
      <p class="warn">The police are out${b ? ` in ${esc(b.name)} and on the way` : ''}. If any part of your car is inside a patrol car’s red cone, you’re caught: the load is seized and you’re fined ${money(fineFor(this.host.cash()))}.</p>
      ${why ? `<p class="whynot">${esc(why)}</p>` : ''}
      <div class="acts"><button type="button" class="take"${why ? ' disabled' : ''}>Take it <kbd>Enter</kbd></button><button type="button" class="later">Leave it <kbd>Esc</kbd></button></div>`;
    panel.querySelector('.take')!.addEventListener('click', () => this.take());
    panel.querySelector('.later')!.addEventListener('click', () => this.leave());
    this.cardEl.replaceChildren(panel);
    this.cardEl.hidden = false;
  }

  private closeCard(): void {
    this.card = null;
    this.cardEl.hidden = true;
    this.cardEl.replaceChildren();
  }

  /** Leave it (Esc): the contact stays until it times out, and asks again only once you have driven off and come back. */
  leave(): void {
    this.dismissed = this.card;
    this.closeCard();
  }

  /** Take it (Enter): the load goes in the hold and the run is on. */
  take(): void {
    const c = this.card;
    if (!c || this.whyNot(c)) return;
    const abs = this.host.hours();
    const dawn = nextDawn(abs);
    const u = NIGHT_URGENCY[c.urgency];
    const est = (c.tiles / EASY_PACE) * (u.slack || 1) + 30;
    this.run = {
      kind: c.kind, pay: c.pay, urgency: c.urgency, dawn,
      deadline: u.slack ? Math.min(dawn, abs + est / HOUR_SECONDS) : dawn,
      from: c.from.name, fromKey: siteKey(c.from),
      to: { name: c.to.name, x: c.to.x, y: c.to.y, z: c.to.z },
      towns: c.towns, tiles: c.tiles, route: c.route, shaves: 0,
    };
    this.cargo.extraUnits = c.kind.units;
    this.closeCard();
    this.dropContact(c);
    this.showDest();
    // a fair start: no patrol car is standing over the pickup, and none is put out that close for a while
    const pl = this.host.player();
    if (pl) this.police.clearAround(pl.x, pl.z, HEAD_START);
    this.host.sfx.chime(1);
    this.host.announce(`${c.kind.icon} ${c.kind.name} aboard`, `To ${c.to.name} · keep out of the red cones`);
  }

  /** Whether a tavern's run has the police out by day; the console's own setting is left as it was. */
  private heated = false;
  private heat(on: boolean): void {
    if (on && !this.police.forced) { this.police.forced = true; this.heated = true; }
    else if (!on && this.heated) { this.police.forced = false; this.heated = false; }
  }

  /**
   * A run begun at a tavern (docs: game/tavern): the goods go in the hold right there, whatever the hour,
   * and the police come out for it. A buyer in another town whose road route takes in two towns or more,
   * `tiles` long or near it. The buyer's name and the road tiles, or why nothing could be arranged.
   */
  hotRun(here: World, kindId: string | null, from: { name: string; key: string }, pay: (tiles: number) => number, tiles: [number, number]): { to: string; tiles: number; pay: number; kind: Contraband } | string {
    if (this.run) return 'There is already something in the back';
    const pl = this.host.player();
    const def = this.host.def();
    if (!pl) return 'Not now';
    if (def.kind !== 'land') return 'Not in that. It goes by road.';
    const fits = CONTRABAND.filter((c) => def.holds.includes(c.cls) && c.units <= def.capacity - this.cargo.used());
    const kind = (kindId && fits.find((c) => c.id === kindId)) || (fits.length ? byShare(fits, Math.random()) : null);
    if (!kind) return `No room in the ${def.name} for it`;
    const land = def as LandDef;
    const tos = shuffle(this.cargo.sitesOfKinds(kind.to).filter((s) => {
      const d = Math.hypot(s.x - pl.x, s.z - pl.z);
      return d >= tiles[0] * 0.5 && d <= tiles[1] && (s.w === here || joinedByLand(s.w, here));
    })).slice(0, 6);
    let best: { to: Site; path: { x: number; z: number }[]; tiles: number; towns: Map<string, string> } | null = null;
    for (const to of tos) {
      const path = roadRoute(here, land, pl.x - here.ox, pl.z - here.oz, to.x - here.ox, to.z - here.oz);
      if (!path) continue;
      const len = lengthOf(path);
      if (len < tiles[0] || len > tiles[1] * 1.3) continue;
      const towns = townsAlong(here, path);
      const b = townOf(to);
      if (b) towns.set(b.key, b.name);
      if (!best || towns.size > best.towns.size) best = { to, path: path.map((p) => ({ x: p.x + here.ox, z: p.z + here.oz })), tiles: len, towns };
      if (best.towns.size >= 3) break;
    }
    if (!best) return 'Nobody’s buying in reach tonight';
    const abs = this.host.hours();
    const night = isNight(this.host.hour());
    const dawn = night ? nextDawn(abs) : abs + 48;
    const est = (best.tiles / EASY_PACE) * 1.15 + 40;
    const due = Math.min(dawn, abs + est / HOUR_SECONDS);
    const money0 = pay(best.tiles);
    this.run = {
      kind, pay: money0, urgency: 'hot', dawn, deadline: due,
      from: from.name, fromKey: from.key,
      to: { name: best.to.name, x: best.to.x, y: best.to.y, z: best.to.z },
      towns: [...best.towns.values()], tiles: Math.round(best.tiles), route: best.path, shaves: 0, hot: true,
    };
    this.cargo.extraUnits = kind.units;
    this.heat(true);
    this.showDest();
    this.police.clearAround(pl.x, pl.z, HEAD_START);
    this.host.sfx.chime(1);
    this.host.announce(`${kind.icon} ${kind.name} aboard`, `To ${best.to.name} · keep out of the red cones`);
    return { to: best.to.name, tiles: Math.round(best.tiles), pay: money0, kind };
  }

  private showDest(): void {
    if (this.dest) disposeCargoMarker(this.dest);
    this.dest = null;
    if (!this.run) return;
    this.dest = buildCargoMarker(RUN_LOOK, null, true);
    this.dest.group.position.set(this.run.to.x, this.run.to.y + 0.05, this.run.to.z);
    this.group.add(this.dest.group);
  }

  // ---- the run ----

  private endRun(): void {
    if (this.run?.hot) this.heat(false);
    this.run = null;
    this.cargo.extraUnits = 0;
    if (this.dest) disposeCargoMarker(this.dest);
    this.dest = null;
  }

  private deliver(pl: { x: number; y: number; z: number }): void {
    const r = this.run!;
    // the Family's thanks for a friend, and the hearse's false floor (docs/factions.html)
    r.pay = Math.round(r.pay * (this.payMul?.() ?? 1));
    this.host.earn(r.pay);
    this.host.float(`+${money(r.pay)} ${r.kind.icon}`, pl.x, pl.y + 0.5, pl.z, 'cash');
    this.host.announce('Delivered', `${r.kind.icon} ${r.kind.name} to ${r.to.name} · ${money(r.pay)}, no questions asked`);
    this.record.runs++;
    this.onRun?.(r.kind.id, r.kind.name, r.pay, r.from);
    this.record.earned += r.pay;
    this.record.streak++;
    this.record.best = Math.max(this.record.best, this.record.streak);
    deeds.add('nightRuns');
    deeds.best('cleanHands', this.record.streak);
    if (r.shaves) deeds.add('closeShave', r.shaves);
    const hour = this.host.hour();
    if (hour >= SUNRISE - 1 && hour < SUNRISE) deeds.add('dawnChorus');
    this.endRun();
  }

  /** Too late: the buyer has gone, and so has the load. No fine, no pay. */
  private fail(dawn: boolean): void {
    const r = this.run!;
    this.host.announce(dawn ? 'Sun’s up' : 'Too late', `${dawn ? 'The buyer’s gone with the dark.' : 'The buyer didn’t wait.'} ${r.kind.icon} ${r.kind.name} dumped · no pay`);
    this.barred.add(r.fromKey);
    this.endRun();
  }

  /** Throw the load out: nothing paid, nobody fined, and that contact won't call again tonight. */
  ditch(): void {
    const r = this.run;
    if (!r || this.bust) return;
    this.host.announce('Ditched', `${r.kind.icon} ${r.kind.name} is gone · that contact won’t call again tonight`);
    this.barred.add(r.fromKey);
    this.endRun();
  }

  private drawChip(pl: { x: number; z: number }): void {
    const r = this.run;
    if (this.bust && this.bust.stage === 'stop') {
      this.chip.hidden = false;
      this.chip.className = 'hud chip spotted';
      this.chip.innerHTML = '🚨 <b>SPOTTED</b> · pull over';
      return;
    }
    if (!r || this.listed) { this.chip.hidden = true; return; }
    const abs = this.host.hours();
    const left = (r.deadline - abs) * HOUR_SECONDS;
    const bearing = Math.atan2(r.to.x - pl.x, r.to.z - pl.z);
    const rot = -(bearing - this.host.yaw() - Math.PI);
    const dist = Math.round(Math.hypot(r.to.x - pl.x, r.to.z - pl.z));
    this.chip.className = `hud chip${left < 30 ? ' late' : ''}`;
    this.chip.hidden = false;
    this.chip.innerHTML = `<span class="ic">${r.kind.icon}</span> <b>${esc(r.kind.name)}</b> → ${esc(r.to.name)} · <em>${money(r.pay)}</em>`
      + ` · <span class="arrow" style="transform: rotate(${rot.toFixed(2)}rad)">↑</span> ${dist} tiles`
      + ` · ${r.deadline >= r.dawn ? '🌅 dawn in' : '⏱ due in'} <b>${clock(left)}</b> <button type="button" title="Throw the load out: no pay, no fine">ditch</button>`;
  }

  // ---- the bust ----

  private spotted(p: Patrol): void {
    const pl = this.host.player();
    if (!this.run || this.bust || !pl) return;
    // which side of the player the car is on: it pulls in on that side rather than through them
    const rx = Math.cos(pl.heading), rz = -Math.sin(pl.heading);
    const cx = p.agent.w.ox + p.agent.state.x - pl.x, cz = p.agent.w.oz + p.agent.state.z - pl.z;
    const side = cx * rx + cz * rz >= 0 ? 1 : -1;
    this.bust = { p, t: 0, side, stage: 'stop', since: 0, seized: `${this.run.kind.units} ${this.run.kind.units === 1 ? 'load' : 'crates'} of ${this.run.kind.name.toLowerCase()}`, fine: 0 };
    this.police.busy = true;
    this.police.chase(p, pl);
    this.flashEl.hidden = false;
    this.host.sfx.whoop();
  }

  private stepBust(dt: number, pl: { x: number; y: number; z: number; v: number; heading: number }): void {
    const b = this.bust!;
    b.t += dt;
    if (b.stage === 'card') {
      b.since += dt;
      if (b.since >= CARD_HOLD) {
        this.police.release();
        this.police.busy = false;
        this.flashEl.hidden = true;
        this.bust = null;
      }
      return;
    }
    const fx = Math.sin(pl.heading), fz = Math.cos(pl.heading);
    const rx = Math.cos(pl.heading), rz = -Math.sin(pl.heading);
    const tx = pl.x + fx * AHEAD + rx * b.side * BESIDE, tz = pl.z + fz * AHEAD + rz * b.side * BESIDE;
    const a = b.p.agent;
    const there = Math.hypot(a.w.ox + a.state.x - tx, a.w.oz + a.state.z - tz) < 0.5;
    const held = Math.abs(pl.v) < 0.12;
    const gone = !b.p.traffic.agents.includes(a);
    const stop = (there && held) || b.t > CHASE_MAX || gone;
    if (!gone) this.police.chaseTo(b.p, tx, tz, stop);
    if (held && (stop && (gone || Math.abs(a.state.v) < 0.15 || b.t > CHASE_MAX + 1))) this.resolve(pl);
  }

  /** Both cars stopped: the load is seized and the fine is paid, whether or not the money is there. */
  private resolve(pl: { x: number; y: number; z: number }): void {
    const b = this.bust!;
    const r = this.run;
    b.fine = fineFor(this.host.cash());
    this.host.fine(b.fine);
    this.host.float(`−${money(b.fine)} fine`, pl.x, pl.y + 0.5, pl.z, 'fine');
    this.record.busts++;
    this.onBust?.(r?.kind.name ?? 'a load', b.fine);
    this.record.streak = 0;
    if (r) this.barred.add(r.fromKey);
    const icon = r?.kind.icon ?? '📦';
    this.endRun();
    b.stage = 'card';
    b.since = 0;
    const cash = this.host.cash();
    this.bustEl.innerHTML = `<b>BUSTED</b><p><span class="ic x">${icon}</span> Seized: ${esc(b.seized)}</p>`
      + `<p>Fine <em>−${money(b.fine)}</em> · cash <span class="${cash < 0 ? 'neg' : ''}">${money(cash)}</span></p>`;
    this.bustEl.hidden = false;
    this.bustTimer = CARD_SHOW;
  }

  // ---- the save ----

  toSave(): SmuggleSave {
    const r = this.run;
    return {
      run: r ? {
        k: r.kind.id, pay: r.pay, u: r.urgency, deadline: r.deadline, dawn: r.dawn, from: r.from, fromKey: r.fromKey,
        to: r.to, towns: r.towns, tiles: r.tiles, shaves: r.shaves, hot: r.hot,
      } : null,
      rec: { ...this.record },
    };
  }

  fromSave(s: SmuggleSave | undefined): void {
    this.reset();
    this.record = { runs: 0, busts: 0, earned: 0, streak: 0, best: 0, ...(s?.rec ?? {}) };
    const r = s?.run;
    const kind = r ? contrabandById(r.k) : undefined;
    if (!r || !kind) return;
    this.run = {
      kind, pay: r.pay, urgency: r.u, deadline: r.deadline, dawn: r.dawn, from: r.from, fromKey: r.fromKey,
      to: r.to, towns: r.towns, tiles: r.tiles, route: null, shaves: r.shaves, hot: r.hot,
    };
    this.cargo.extraUnits = kind.units;
    if (r.hot) this.heat(true);
    this.showDest();
  }

  // ---- the console ----

  /** pr.smuggle: night(), offer(kind), cops(on), ghost(on), state() */
  console() {
    return {
      night: () => { this.host.setHour(19); return 'It is 19:00'; },
      skip: (hours: number) => { this.host.advance(hours); return `+${hours} h`; },
      offer: (kind?: string) => {
        for (let k = 0; k < 6; k++) if (this.spawn(kind ?? null, true)) return 'A contact is waiting';
        return 'Nowhere suitable nearby';
      },
      cops: (on = true) => { this.police.forced = on; return on ? 'Police on duty at any hour' : 'Police keep to the night'; },
      ghost: (on = true) => { this.police.ghost = on; return on ? 'Nobody sees anything' : 'The cones see again'; },
      /** The nearest patrol car: its cell, where it is in that cell's frame, and which way it faces. */
      cop: () => {
        const pl = this.host.player();
        if (!pl) return null;
        let best: Patrol | null = null, bestD = Infinity;
        for (const p of this.police.patrols) {
          const d = Math.hypot(p.agent.w.ox + p.agent.state.x - pl.x, p.agent.w.oz + p.agent.state.z - pl.z);
          if (d < bestD) { bestD = d; best = p; }
        }
        const a = best?.agent;
        return a ? { cell: [a.w.cx, a.w.cz], x: +a.state.x.toFixed(2), z: +a.state.z.toFixed(2), heading: +a.state.heading.toFixed(2), mode: best!.mode, tiles: Math.round(bestD) } : null;
      },
      /** Where the nearest contact waits, in its cell's frame. */
      contact: (i = 0) => {
        const c = this.contacts[i];
        return c ? {
          cell: [c.from.w.cx, c.from.w.cz], x: +c.from.lx.toFixed(2), z: +c.from.lz.toFixed(2), to: c.to.name, towns: c.towns,
          toCell: [c.to.w.cx, c.to.w.cz], tx: +c.to.lx.toFixed(2), tz: +c.to.lz.toFixed(2), kind: c.kind.id,
        } : null;
      },
      state: () => ({
        run: this.run && { kind: this.run.kind.id, to: this.run.to.name, pay: this.run.pay, left: Math.round((this.run.deadline - this.host.hours()) * HOUR_SECONDS), shaves: this.run.shaves },
        contacts: this.contacts.map((c) => `${c.kind.icon} ${c.from.name} → ${c.to.name} · ${c.tiles} tiles · ${money(c.pay)} · ${c.towns.join(' → ')}`),
        police: this.police.lines(),
        record: this.record,
      }),
    };
  }
}

