import * as THREE from 'three';

/**
 * Light shafts and pools with no hard edge (floodlights, the heli's searchlight, lighthouses): a shaft
 * fades out over its far part instead of stopping at a ring, and a pool falls off smoothly to nothing at
 * its rim. Both are for additive materials; the shaft's fade is in its vertex colours' alpha, so its
 * material wants `vertexColors: true`.
 */

/**
 * An open cone from its tip at the origin down −y, 1 long with a base radius of 1 (scale it to fit), full
 * strength near the lamp and gone by the end. `from` is where along it the fading starts, 0–1.
 */
export function fadingCone(segments = 20, from = 0.35): THREE.BufferGeometry {
  const rows = 8;
  const g = new THREE.ConeGeometry(1, 1, segments, rows, true).translate(0, -0.5, 0);
  const pos = g.getAttribute('position');
  const col = new Float32Array(pos.count * 4);
  for (let i = 0; i < pos.count; i++) {
    const t = Math.min(1, Math.max(0, -pos.getY(i)));            // 0 at the lamp, 1 at the far end
    const u = Math.min(1, Math.max(0, (t - from) / (1 - from)));
    const a = 1 - u * u * (3 - 2 * u);                           // smoothstep down to nothing
    col.set([1, 1, 1, a], i * 4);
  }
  g.setAttribute('color', new THREE.BufferAttribute(col, 4));
  return g;
}

let pool: THREE.CanvasTexture | null = null;
/** A round falloff for a pool of light: bright in the middle, easing to nothing well inside the rim. */
export function softPoolTexture(): THREE.Texture {
  if (pool) return pool;
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const g = c.getContext('2d')!;
  const r = g.createRadialGradient(64, 64, 0, 64, 64, 63);
  // a long, eased tail: no step anywhere for the eye to catch
  for (const [at, a] of [[0, 1], [0.3, 0.92], [0.5, 0.7], [0.65, 0.45], [0.8, 0.18], [0.92, 0.04], [1, 0]] as const) {
    r.addColorStop(at, `rgba(255,255,255,${a})`);
  }
  g.fillStyle = r;
  g.fillRect(0, 0, 128, 128);
  pool = new THREE.CanvasTexture(c);
  return pool;
}
