import * as THREE from 'three';
import { Biome, N, SEA, STEP, idx, inB, waterDepth, type Building, type World } from '../../world/tiles';
import { hashString, mulberry32 } from '../../world/rng';
import { SECONDS_PER_HOUR } from '../../render/daynight';
import { builtShare } from '../../render/townMesh';
import { cargoById } from '../cargoTypes';
import type { CargoItem, CargoSystem, Rider } from '../cargo';
import type { VehicleDef } from '../vehicles';
import { RUNG } from './factions';
import { reputation } from './reputation';
import { deeds } from '../deeds';

/**
 * What the factions' vehicles do that nothing else does (docs/factions.html, "The thirty"): the Saucer's
 * tractor beam, the Live Truck's and the Eye in the Sky's broadcast fee at a live event, the trawlers'
 * nets at a shoal, the Pelican's beach landings, the Big Hook beside a building site, Star Tours' sights,
 * and the checkpoints and customs posts that stop or wave through a player by their standing.
 */
interface MechHost {
  scene: THREE.Scene;
  /** The player's vehicle in world tiles (as the cargo system reads it), its definition, the island under it and its height above the ground. */
  rider(): (Rider & { heading: number; def: VehicleDef; w: World; above: number }) | null;
  worlds(): World[];
  cargo: CargoSystem;
  /** Shift, Space held this frame; the hour of the day; a storm overhead. */
  shift(): boolean;
  space(): boolean;
  hour(): number;
  storm(): boolean;
  /** Live events in memory: matches, concerts and race meetings, in world tiles. */
  events(): { x: number; z: number; name: string }[];
  earn(n: number, line: string): void;
  float(text: string, x: number, y: number, z: number, kind: 'info' | 'cash' | 'bad'): void;
  announce(title: string, body: string): void;
  /** Hold the player's car for this many seconds (a checkpoint). */
  hold(seconds: number): void;
  fine(n: number, why: string): void;
}

/** A shoal: gulls over a patch of open sea where a trawler can haul. */
interface Shoal { key: string; w: World; x: number; z: number; group: THREE.Group; gulls: THREE.Object3D[]; spent: number }

const SHOAL_R = 2.2, HAUL_SECONDS = 6;
/** A broadcast earns this much a game minute on air, near enough to the event. */
const ON_AIR_PER_MIN = 6, ON_AIR_R = 8, SKY_R = 11;
/** The kinds a Star Tours fare counts as sights. */
const SIGHTS = new Set(['landmark', 'mansion', 'starMansion', 'filmStudio', 'backlot', 'studioGate', 'premiereTheatre', 'observationTower',
  'cathedral', 'operaHouse', 'museum', 'castle', 'moatedCastle', 'clockTower', 'stadium', 'bossVilla', 'embassy', 'parliament', 'statehouse', 'leaningTower']);

export class FactionMechanics {
  private group = new THREE.Group();
  private shoals = new Map<string, Shoal>();
  private shoalT = 0;
  private haul = 0;
  private haulAt = '';
  private beamT = 0;
  private airT = 0;
  private aired = 0;
  private siteT = 0;
  private sightT = 0;
  private landed = 0;
  private gate = new Map<string, number>();
  private clock = 0;
  /** Seen sights per item aboard (Star Tours). */
  readonly sights = new WeakMap<CargoItem, Set<string>>();
  /** The haul under way, 0–1, for the HUD. */
  hauling = 0;

  constructor(private host: MechHost) {
    host.scene.add(this.group);
  }

  clear(): void {
    for (const s of this.shoals.values()) this.group.remove(s.group);
    this.shoals.clear();
    this.haul = 0;
    this.hauling = 0;
  }

  update(dt: number): void {
    if (dt <= 0) return;
    this.clock += dt;
    if ((this.shoalT -= dt) <= 0) { this.shoalT = 3; this.placeShoals(); }
    for (const s of this.shoals.values()) {
      s.group.visible = s.spent <= this.clock;
      s.gulls.forEach((g, k) => { const a = this.clock * 0.6 + k * 2.1; g.position.set(Math.cos(a) * 0.8, 0.9 + 0.15 * Math.sin(this.clock * 2 + k), Math.sin(a) * 0.8); g.rotation.y = -a; });
    }
    const p = this.host.rider();
    this.hauling = 0;
    if (!p) return;
    const d = p.def;
    if (d.trawl) this.trawl(p, dt);
    if (d.beam) this.beam(p, dt);
    if (d.mast) this.broadcast(p, dt);
    if (d.beach) this.beach(p);
    if (d.crane) this.crane(p, dt);
    if (d.sights) this.lookAround(p, dt);
    if (d.kind === 'land') this.checkpoints(p);
  }

  /** What Star Tours' fares are worth extra for the sights they passed. */
  sightShare(it: CargoItem, d: VehicleDef): number {
    if (!d.sights || it.type.cls !== 'people') return 0;
    return Math.min(0.5, (this.sights.get(it)?.size ?? 0) * d.sights);
  }

  // ---- the trawlers ----------------------------------------------------------------------------

  /** Two or three shoals on the open water of each island in memory: the same places for everyone, every day. */
  private placeShoals(): void {
    const live = new Set<string>();
    const day = Math.floor(this.clock / (24 * SECONDS_PER_HOUR));
    for (const w of this.host.worlds()) {
      const r = mulberry32(hashString(`shoal|${w.cx},${w.cz}|${day}`));
      let made = 0;
      for (let t = 0; t < 120 && made < 3; t++) {
        const x = 4 + Math.floor(r() * (N - 8)), z = 4 + Math.floor(r() * (N - 8));
        const i = idx(x, z);
        if (waterDepth(w, i) < 2 || w.coastDist[i] < 4) continue;
        const key = `${w.cx},${w.cz}#${made}|${day}`;
        made++;
        live.add(key);
        if (this.shoals.has(key)) continue;
        this.shoals.set(key, this.makeShoal(key, w, w.ox + x + 0.5, w.oz + z + 0.5));
      }
    }
    for (const [k, s] of this.shoals) if (!live.has(k)) { this.group.remove(s.group); this.shoals.delete(k); }
  }

  private makeShoal(key: string, w: World, x: number, z: number): Shoal {
    const g = new THREE.Group();
    const ripple = new THREE.Mesh(new THREE.RingGeometry(0.6, SHOAL_R, 24).rotateX(-Math.PI / 2), new THREE.MeshBasicMaterial({ color: 0xdff4ff, transparent: true, opacity: 0.35, depthWrite: false }));
    ripple.position.y = 0.02;
    g.add(ripple);
    const gullMat = new THREE.MeshStandardMaterial({ color: 0xf4f2ec, flatShading: true });
    const gulls: THREE.Object3D[] = [];
    for (let k = 0; k < 4; k++) {
      const gull = new THREE.Group();
      const wing = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.02, 0.08), gullMat);
      const body = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.05, 0.16), gullMat);
      gull.add(wing, body);
      g.add(gull);
      gulls.push(gull);
    }
    // on the sea's surface
    void w;
    g.position.set(x, SEA * STEP + 0.02, z);
    this.group.add(g);
    return { key, w, x, z, group: g, gulls, spent: 0 };
  }

  private trawl(p: NonNullable<ReturnType<MechHost['rider']>>, dt: number): void {
    const s = [...this.shoals.values()].find((q) => q.spent <= this.clock && Math.hypot(q.x - p.x, q.z - p.z) <= SHOAL_R);
    if (!s || Math.abs(p.v) > 0.4 || !this.host.space()) { this.haul = 0; this.haulAt = ''; return; }
    if (this.haulAt !== s.key) { this.haulAt = s.key; this.haul = 0; }
    this.haul += dt;
    this.hauling = Math.min(1, this.haul / HAUL_SECONDS);
    if (this.haul < HAUL_SECONDS) return;
    this.haul = 0;
    const t = cargoById('catch');
    const to = this.host.cargo.nearestSite(['fishMarket', 'cannery', 'minorPort'], p.x, p.z);
    if (!t || !to) { this.host.float('Nowhere to land a catch near here', p.x, p.y + 0.6, p.z, 'bad'); return; }
    const big = (p.def.trawl ?? 2) >= 4 && this.host.storm() ? 2 : 1;
    const dist = Math.hypot(to.x - p.x, to.z - p.z);
    const value = Math.round((t.base + t.perTile * dist) * (p.def.trawl ?? 2) / 2 * big);
    const it = this.host.cargo.stow(t, p.def, { w: s.w, x: s.x, y: p.y, z: s.z, name: 'the fishing grounds' }, to, value);
    if (!it) { this.host.float('The hold is full', p.x, p.y + 0.6, p.z, 'bad'); return; }
    s.spent = this.clock + 6 * SECONDS_PER_HOUR;
    reputation.move('guild', 20 * big, 'A net hauled', 'you');
    deeds.add('hauls');
    deeds.mark('tricks', 'trawl');
    this.host.float(`🐟 Catch aboard · $${value}${big > 1 ? ' · storm haul ×2' : ''}`, p.x, p.y + 0.7, p.z, 'cash');
  }

  // ---- the Saucer's beam ----------------------------------------------------------------------

  private beam(p: NonNullable<ReturnType<MechHost['rider']>>, dt: number): void {
    if ((this.beamT -= dt) > 0 || !this.host.shift() || p.above > 3.5) return;
    this.beamT = 0.5;
    const it = this.host.cargo.beamUp(p, p.def, 2.5);
    if (!it) return;
    this.host.float(`🛸 ${it.type.icon} ${it.type.name} beamed aboard`, p.x, p.y + 0.4, p.z, 'info');
    deeds.add('beamed');
    deeds.mark('tricks', 'beam');
  }

  // ---- on air ----------------------------------------------------------------------------------

  private broadcast(p: NonNullable<ReturnType<MechHost['rider']>>, dt: number): void {
    const air = p.def.kind === 'air';
    if (!air && Math.abs(p.v) > 0.3) { this.airT = 0; return; }
    const r = air ? SKY_R : ON_AIR_R;
    const ev = this.host.events().find((e) => Math.hypot(e.x - p.x, e.z - p.z) <= r);
    if (!ev) { this.airT = 0; return; }
    // a game minute is SECONDS_PER_HOUR / 60 real seconds
    this.airT += dt;
    const min = SECONDS_PER_HOUR / 60;
    while (this.airT >= min * 5) {
      this.airT -= min * 5;
      const fee = ON_AIR_PER_MIN * 5;
      this.host.earn(fee, 'other');
      this.aired += 5;
      deeds.add('onAir', fee);
      deeds.mark('tricks', 'onAir');
      reputation.move('press', 25, `On air at ${ev.name}`, 'you');
      this.host.float(`📡 On air · +$${fee}`, p.x, p.y + 0.6, p.z, 'cash');
    }
  }

  // ---- the Pelican -----------------------------------------------------------------------------

  private beach(p: NonNullable<ReturnType<MechHost['rider']>>): void {
    if (Math.abs(p.v) > 0.35 || this.clock - this.landed < 2) return;
    const w = p.w, lx = Math.floor(p.x - w.ox), lz = Math.floor(p.z - w.oz);
    let shore = false;
    for (let dz = -2; dz <= 2 && !shore; dz++) for (let dx = -2; dx <= 2; dx++) {
      const x = lx + dx, z = lz + dz;
      if (inB(x, z) && w.biome[idx(x, z)] === Biome.Beach && waterDepth(w, idx(x, z)) === 0) { shore = true; break; }
    }
    if (!shore) return;
    this.landed = this.clock;
    let n = 0;
    this.host.cargo.landAt(p, p.def, (it) => {
      const ok = it.to.w === w || Math.hypot(it.to.x - p.x, it.to.z - p.z) < 70;
      if (ok) n++;
      return ok;
    });
    if (!n) return;
    this.host.float(`⚓ Landed on the beach · ${n} load${n === 1 ? '' : 's'} ashore`, p.x, p.y + 0.6, p.z, 'info');
    deeds.mark('tricks', 'beach');
  }

  // ---- the Big Hook -----------------------------------------------------------------------------

  private crane(p: NonNullable<ReturnType<MechHost['rider']>>, dt: number): void {
    if (Math.abs(p.v) > 0.2) return;
    this.siteT += dt;
    const w = p.w, lx = p.x - w.ox, lz = p.z - w.oz;
    const hours = dt / SECONDS_PER_HOUR;
    let helping = false;
    for (const b of w.allBuildings) {
      if (b.gone || b.grownAt === undefined || builtShare(b) >= 1) continue;
      const cx = b.x + b.w / 2, cz = b.z + b.d / 2;
      if (Math.hypot(cx - lx, cz - lz) > Math.max(b.w, b.d) / 2 + 3) continue;
      // twice as fast: an extra hour of building for every hour stood beside it
      b.grownAt -= hours;
      helping = true;
    }
    if (helping && this.siteT > 6) { this.siteT = 0; this.host.float('🏗️ The crane lends a hand', p.x, p.y + 0.6, p.z, 'info'); reputation.move('unions', 6, 'A crane at the site', 'you'); deeds.mark('tricks', 'crane'); }
  }

  // ---- Star Tours -----------------------------------------------------------------------------

  private lookAround(p: NonNullable<ReturnType<MechHost['rider']>>, dt: number): void {
    if ((this.sightT -= dt) > 0) return;
    this.sightT = 0.5;
    const aboard = this.host.cargo.hold.filter((it) => it.type.cls === 'people');
    if (!aboard.length) return;
    const w = p.w, lx = p.x - w.ox, lz = p.z - w.oz;
    for (const b of w.allBuildings) {
      if (b.gone || !SIGHTS.has(b.kind)) continue;
      if (Math.hypot(b.x + b.w / 2 - lx, b.z + b.d / 2 - lz) > 6) continue;
      const key = `${w.cx},${w.cz}#${b.uid}`;
      for (const it of aboard) {
        let set = this.sights.get(it);
        if (!set) this.sights.set(it, (set = new Set()));
        if (!set.has(key)) { set.add(key); if (it === aboard[0]) { this.host.float(`📸 ${sightName(b)}`, p.x, p.y + 0.6, p.z, 'info'); deeds.mark('tricks', 'sights'); } }
      }
    }
  }

  // ---- checkpoints and customs --------------------------------------------------------------------

  private checkpoints(p: NonNullable<ReturnType<MechHost['rider']>>): void {
    const w = p.w, lx = p.x - w.ox, lz = p.z - w.oz;
    const hourNow = Math.floor(this.clock / SECONDS_PER_HOUR);
    for (const b of w.allBuildings) {
      if (b.gone || (b.kind !== 'checkpoint' && b.kind !== 'customsPost')) continue;
      if (Math.hypot(b.x + b.w / 2 - lx, b.z + b.d / 2 - lz) > 2.2) continue;
      const key = `${w.cx},${w.cz}#${b.uid}`;
      if (this.gate.get(key) === hourNow) continue;
      this.gate.set(key, hourNow);
      const f = b.kind === 'checkpoint' ? 'army' : 'ministry';
      const r = reputation.rung(f);
      const who = b.kind === 'checkpoint' ? 'The checkpoint' : 'Customs';
      if (r >= RUNG.honoured) { this.host.float(`${who} waves you through`, p.x, p.y + 0.6, p.z, 'info'); deeds.mark('tricks', 'waved'); }
      else if (r <= RUNG.hostile) {
        this.host.hold(6);
        this.host.fine(30, 'Searched');
        this.host.announce(b.kind === 'checkpoint' ? '🚧 Held at the checkpoint' : '🛃 Searched at customs', `${who} has your name on a list: six seconds, a search, and $30 for the trouble`);
      } else if (r < RUNG.friend) {
        this.host.hold(2);
        this.host.float(`${who}: papers, please`, p.x, p.y + 0.6, p.z, 'info');
      }
    }
  }
}

function sightName(b: Building): string {
  const k = b.kind.replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();
  return `The ${k}`;
}
