import {
  FACTIONS, FACTION_IDS, OATH_AT, PACE, PAY_MUL, REP_MAX, REP_MIN, RUNG, RUNGS, SPILL, buildingFactions, cargoFaction, contestFor, isStrongholdCargo, linksOf, rungOf,
  type FactionId,
} from './factions';
import { unlocks } from './unlocks';
import { deeds } from '../deeds';

/**
 * The player's standing with each faction (docs/factions.html, "The ladder"): one integer each, from
 * −6,000 to 10,000, moved only by acts — a delivery, a mission, a night run, a road paid for — each written
 * in a log the Factions screen shows. A gain with one faction spills onto the factions linked to it
 * (factions.ts LINKS), once, never onward. Above zero nothing decays; below it, a bar heals toward Neutral
 * a little each game day nothing new is done against it. The bar stops at 9,999 until the faction's Oath
 * is done (game/factions/oath.ts), and each rung from Friend up unlocks something for good.
 */

export type By = 'you' | 'crew';

interface LogLine {
  /** The faction, the change (after caps and the crew's half), what was done, the game day, and who did it. */
  f: FactionId; d: number; line: string; day: number; by: By;
  /** Spilled from another faction's act, rather than the act itself. */
  spill?: FactionId;
}

export interface SavedReputation {
  rep: Partial<Record<FactionId, number>>;
  log: LogLine[];
  oath: Partial<Record<FactionId, number>>;
  /** Factions whose bar has reached 9,999: their Oath stays open while they still count the player Honoured. */
  ready?: FactionId[];
  met: FactionId[];
  goal: FactionId | null;
  /** The game day each faction was last offended (for healing). */
  hurt: Partial<Record<FactionId, number>>;
}

/** Log lines kept. */
const LOG_MAX = 120;

export class Reputation {
  rep = {} as Record<FactionId, number>;
  log: LogLine[] = [];
  /** Oath steps done (0–5); 5 is Sworn. */
  oath = {} as Record<FactionId, number>;
  /** Factions whose bar has stood at 9,999 (the Oath offered), so a spill that dips it a point doesn't take it away. */
  ready = new Set<FactionId>();
  /** A bar has just reached 9,999 for the first time: the Oath is on offer. */
  onReady: (f: FactionId) => void = () => {};
  met = new Set<FactionId>();
  goal: FactionId | null = null;
  private hurt = {} as Record<FactionId, number>;
  private lastDay = -1;
  /** The game day now, for the log. */
  day: () => number = () => 0;
  /** A bar has crossed into another rung (up or down). */
  onRung: (f: FactionId, from: number, to: number) => void = () => {};
  /** Something changed (the HQ window redraws). */
  onChange: () => void = () => {};
  /** A faction just met (first act, or first building seen). */
  onMet: (f: FactionId) => void = () => {};
  /** Version, bumped on every change, for windows that draw only when it moves. */
  version = 0;

  constructor() { this.clear(); }

  clear(): void {
    for (const f of FACTION_IDS) { this.rep[f] = 0; this.oath[f] = 0; this.hurt[f] = -1; }
    this.log = [];
    this.ready.clear();
    this.met.clear();
    this.goal = null;
    this.lastDay = -1;
    this.version++;
  }

  points(f: FactionId): number { return this.rep[f] ?? 0; }
  rung(f: FactionId): number { return rungOf(this.points(f)); }
  rungName(f: FactionId): string { return RUNGS[this.rung(f)].name; }
  /**
   * Is the faction's Oath open to the player: not yet Sworn, and the bar at 9,999, or there once and still
   * Honoured (a delivery for a rival that knocks a few points off doesn't close it), or a step already done.
   */
  oathOpen(f: FactionId): boolean {
    if (this.oath[f] >= 5) return false;
    return this.oath[f] > 0 || this.points(f) >= OATH_AT - 0.5 || (this.ready.has(f) && this.rung(f) >= RUNG.honoured);
  }
  sworn(f: FactionId): boolean { return this.rung(f) >= RUNG.sworn; }
  /** Factions at or above a rung. */
  atLeast(r: number): FactionId[] { return FACTION_IDS.filter((f) => this.rung(f) >= r); }

  /** Seen one of its buildings or vehicles: the Factions screen stops calling it "not yet met". */
  meet(f: FactionId): void {
    if (this.met.has(f)) return;
    this.met.add(f);
    deeds.mark('facMet', f);
    this.version++;
    this.onMet(f);
    this.onChange();
  }

  /**
   * Move one bar by `delta` for `line`. `by` 'crew' halves it. Spills onto linked factions unless `spill`
   * is false (a spill, or an act that names both sides itself). Returns the change made.
   */
  move(f: FactionId, delta: number, line: string, by: By = 'you', spill = true, cap: number = PACE.cap): number {
    if (!delta) return 0;
    let d = delta * (by === 'crew' ? PACE.crew : 1);
    if (Math.abs(d) > cap && !line.startsWith('Oath')) d = Math.sign(d) * cap;
    const made = this.apply(f, d, line, by);
    if (spill) {
      for (const { other, link } of linksOf(f)) {
        const s = d * SPILL[link];
        if (Math.abs(s) >= 0.5) this.apply(other, s, line, by, f);
      }
    }
    if (made || spill) { this.version++; this.onChange(); }
    return made;
  }

  private apply(f: FactionId, d: number, line: string, by: By, spill?: FactionId): number {
    const was = this.points(f);
    const top = this.oath[f] >= 5 ? REP_MAX : OATH_AT;
    const now = Math.max(REP_MIN, Math.min(top, was + d));
    const made = Math.round((now - was) * 10) / 10;
    if (!made && !(d < 0)) return 0;
    this.rep[f] = now;
    if (d < 0) this.hurt[f] = this.day();
    if (!this.met.has(f)) { this.met.add(f); deeds.mark('facMet', f); }
    if (made) {
      this.log.unshift({ f, d: made, line, day: this.day(), by, ...(spill ? { spill } : {}) });
      if (this.log.length > LOG_MAX) this.log.length = LOG_MAX;
    }
    if (now >= OATH_AT - 0.5 && this.oath[f] < 5 && !this.ready.has(f)) {
      this.ready.add(f);
      this.onReady(f);
    }
    const r0 = rungOf(was), r1 = rungOf(now);
    if (r0 !== r1) {
      if (r1 > r0) for (let r = Math.max(RUNG.friend, r0 + 1); r <= r1; r++) unlocks.add(FACTIONS[f].unlocks[r - RUNG.friend].id);
      this.onRung(f, r0, r1);
    }
    return made;
  }

  /**
   * A delivery: the load's own faction gains its value over PACE.cargo, and the faction of the door it was
   * taken to its value over PACE.door; an act that names both sides (factions.ts CONTESTS) does that instead.
   * Returns the faction that thanked the player most, for the float.
   */
  delivered(cargo: string, cargoName: string, from: string | undefined, to: string, value: number, by: By): { f: FactionId; d: number } | null {
    const base = value / PACE.cargo;
    const c = contestFor(cargo, from, to);
    let best: { f: FactionId; d: number } | null = null;
    const note = (f: FactionId, d: number) => { if (d > 0 && (!best || d > best.d)) best = { f, d }; };
    if (c) {
      for (const [f, k] of Object.entries(c.moves) as [FactionId, number][]) note(f, this.move(f, base * k, c.line ?? cargoName, by, false));
      return best;
    }
    const own = cargoFaction(cargo);
    // a stronghold's load (docs/strongholds.html): its own pace and cap
    if (own && isStrongholdCargo(cargo)) note(own, this.move(own, value / PACE.stronghold, `${cargoName} delivered`, by, true, PACE.strongholdCap));
    else if (own) note(own, this.move(own, base, `${cargoName} delivered`, by));
    for (const f of buildingFactions(to)) {
      if (f === own) continue;
      const shared = buildingFactions(to).length > 1 ? 0.5 : 1;
      note(f, this.move(f, (value / PACE.door) * shared, `${cargoName} to their door`, by));
    }
    return best;
  }

  /**
   * What delivering a load would do, worked out the way `delivered` does it but changing nothing: the faction
   * it would please most (by what that bar can still take, caps and all), and in a contest the one it would
   * cost most. The colour of the load's ring (game/cargoLook.ts); null when it would move nobody.
   */
  favours(cargo: string, from: string | undefined, to: string, value: number, by: By = 'you'): { f: FactionId; d: number; loses?: FactionId } | null {
    const base = value / PACE.cargo;
    const c = contestFor(cargo, from, to);
    let best: { f: FactionId; d: number } | null = null;
    let worst: { f: FactionId; d: number } | null = null;
    const note = (f: FactionId, d: number) => {
      if (d > 0 && (!best || d > best.d)) best = { f, d };
      if (d < 0 && (!worst || d < worst.d)) worst = { f, d };
    };
    if (c) {
      for (const [f, k] of Object.entries(c.moves) as [FactionId, number][]) note(f, this.would(f, base * k, by));
    } else {
      const own = cargoFaction(cargo);
      if (own) note(own, this.would(own, base, by));
      const doors = buildingFactions(to);
      for (const f of doors) if (f !== own) note(f, this.would(f, (value / PACE.door) * (doors.length > 1 ? 0.5 : 1), by));
    }
    const b = best as { f: FactionId; d: number } | null, w = worst as { f: FactionId; d: number } | null;
    return b ? { f: b.f, d: b.d, ...(w ? { loses: w.f } : {}) } : null;
  }

  /** The change `move` would make to one bar (without its spills), and makes none. */
  private would(f: FactionId, delta: number, by: By): number {
    let d = delta * (by === 'crew' ? PACE.crew : 1);
    if (Math.abs(d) > PACE.cap) d = Math.sign(d) * PACE.cap;
    const was = this.points(f);
    const top = this.oath[f] >= 5 ? REP_MAX : OATH_AT;
    return Math.round((Math.max(REP_MIN, Math.min(top, was + d)) - was) * 10) / 10;
  }

  /** What a faction's own cargo pays the player, by the rung now held (1 for cargo no faction owns). */
  payMul(cargo: string): number {
    const f = cargoFaction(cargo);
    if (!f) return 1;
    let m = PAY_MUL[this.rung(f)];
    // the Post's honoured stamp
    if (f === 'post' && this.rung('post') === RUNG.honoured) m += 0.05;
    return m;
  }

  /** May this cargo be made for the player? A faction at Hostile or below offers none of its work. */
  offered(cargo: string): boolean {
    const f = cargoFaction(cargo);
    // a stronghold's loads are only for those it lets in (docs/strongholds.html)
    if (f && isStrongholdCargo(cargo)) return this.rung(f) >= RUNG.honoured;
    return !f || this.rung(f) > RUNG.hostile;
  }

  /** May the player take loads at one of this faction's doors? Not at Hostile or below. */
  doorOpen(kind: string): boolean {
    return buildingFactions(kind).every((f) => this.rung(f) > RUNG.hostile);
  }

  /** The Oath: one step done (the arc's step index, 0–4). The last one gives the 10,000th point. */
  oathStep(f: FactionId, step: number, title: string): void {
    if (this.oath[f] > step) return;
    deeds.add('oathSteps', step + 1 - this.oath[f]);
    this.oath[f] = step + 1;
    if (this.oath[f] >= 5) {
      // the bar's lid comes off, and it is filled
      this.apply(f, REP_MAX - this.points(f), `Oath sworn: ${title}`, 'you');
      this.version++;
      this.onChange();
    } else this.move(f, PACE.oathStep, `Oath: ${title}`, 'you', false);
  }

  /** Once a game day: bars below zero heal toward Neutral if nothing new was done against them yesterday. */
  tickDay(day: number): void {
    if (day === this.lastDay) return;
    const first = this.lastDay < 0;
    this.lastDay = day;
    if (first) return;
    let any = false;
    for (const f of FACTION_IDS) {
      const p = this.points(f);
      if (p >= 0 || this.hurt[f] >= day - 1) continue;
      this.rep[f] = Math.min(0, p + PACE.heal);
      any = true;
      const r0 = rungOf(p), r1 = rungOf(this.rep[f]);
      if (r0 !== r1) this.onRung(f, r0, r1);
    }
    if (any) { this.version++; this.onChange(); }
  }

  /** The last lines for one faction (its own acts and the spills onto it). */
  lines(f: FactionId, n = 8): LogLine[] { return this.log.filter((l) => l.f === f).slice(0, n); }

  toSave(): SavedReputation {
    const rep: Partial<Record<FactionId, number>> = {}, oath: Partial<Record<FactionId, number>> = {}, hurt: Partial<Record<FactionId, number>> = {};
    for (const f of FACTION_IDS) {
      if (this.rep[f]) rep[f] = Math.round(this.rep[f] * 10) / 10;
      if (this.oath[f]) oath[f] = this.oath[f];
      if (this.hurt[f] >= 0) hurt[f] = this.hurt[f];
    }
    return { rep, log: this.log.slice(0, LOG_MAX), oath, ...(this.ready.size ? { ready: [...this.ready] } : {}), met: [...this.met], goal: this.goal, hurt };
  }

  fromSave(s: SavedReputation | undefined): void {
    this.clear();
    if (!s) return;
    for (const f of FACTION_IDS) {
      const v = Number(s.rep?.[f] ?? 0);
      this.rep[f] = Number.isFinite(v) ? Math.max(REP_MIN, Math.min(REP_MAX, v)) : 0;
      this.oath[f] = Math.max(0, Math.min(5, Number(s.oath?.[f] ?? 0) | 0));
      this.hurt[f] = Number(s.hurt?.[f] ?? -1);
    }
    if (Array.isArray(s.log)) this.log = s.log.filter((l) => l && FACTION_IDS.includes(l.f)).slice(0, LOG_MAX);
    if (Array.isArray(s.met)) for (const f of s.met) if (FACTION_IDS.includes(f)) this.met.add(f);
    if (Array.isArray(s.ready)) for (const f of s.ready) if (FACTION_IDS.includes(f)) this.ready.add(f);
    // a save from before `ready`: a bar at 9,999 now has its Oath open (said again on the next point, not on load)
    for (const f of FACTION_IDS) if (this.points(f) >= OATH_AT - 0.5 && this.oath[f] < 5) this.ready.add(f);
    this.goal = s.goal && FACTION_IDS.includes(s.goal) ? s.goal : null;
    // the shelf catches up with the bars (a save from another machine, or one from before the shelf)
    for (const f of FACTION_IDS) for (let r = RUNG.friend; r <= this.rung(f); r++) unlocks.add(FACTIONS[f].unlocks[r - RUNG.friend].id);
    this.version++;
  }
}

export const reputation = new Reputation();
