import { hex, scale } from '../../world/biomes';
import type { WorksKind } from '../../world/tiles';
import { Vis } from '../nightLights';
import { launchPad, navalDock, smallDockSub } from './space';
import {
  BRICK, CARS, DARK, GLASS, METAL, ROOF_GREY, SHOP_GLOW, STONE, TAU, TRUNK, WARM_GLOW, WHITE, WOOD,
  car, pick, row, win, type Draw, type Kit,
} from './kit';

/**
 * The working country and the road hauler's own stops: a mine's headframe, a lumber yard, a cannery, a
 * grain elevator, a harbour's dry dock, a nuclear station's cooling towers, an offshore rig, a launch
 * pad, a county customs post, and the truck stop, weighbridge, car wash and scrapyard along the road.
 */

const RUST = hex(0x8a4f32), STEEL = hex(0x9aa0a6), CONCRETE = hex(0xb9b3a8), YELLOW = hex(0xf2b33b);
const OIL = hex(0x2f3338), SIGN_BLUE = hex(0x2f5d8a);

/** A lattice leg or strut: a bar with its X bracing, the shape all this metalwork is made of. */
function lattice(k: Kit, x: number, z: number, y0: number, y1: number, r: number, col: ReturnType<typeof hex>, bays = 3): void {
  k.bar([x, y0, z], [x, y1, z], r, col);
  const step = (y1 - y0) / bays;
  for (let i = 0; i < bays; i++) {
    const a = y0 + i * step;
    k.bar([x - r * 2, a, z], [x + r * 2, a + step, z], r * 0.5, col);
    k.bar([x, a, z - r * 2], [x, a + step, z + r * 2], r * 0.5, col);
  }
}

// ---- mine headframe ----------------------------------------------------------------------------

/**
 * A shaft mine's headframe: the steel A-frame over the cage, its winding wheels up top, the hoist
 * house beside it and the ore bins the skips tip into.
 */
const mineHeadframe: Draw = (k, W, D, _b, r) => {
  const frame = RUST, H = Math.min(1.6, 0.9 + Math.min(W, D) * 0.2);
  // the four legs of the tower, and the back braces that take the rope's pull
  const half = Math.min(0.32, W / 2 - 0.2);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    k.bar([sx * half, 0, sz * half], [sx * half * 0.55, H, sz * half * 0.55], 0.035, frame);
  }
  for (let i = 1; i < 4; i++) {
    const y = (H * i) / 4, t = 1 - (i / 4) * 0.45;
    for (const s of [-1, 1]) {
      k.bar([-half * t, y, s * half * t], [half * t, y, s * half * t], 0.02, frame);
      k.bar([s * half * t, y, -half * t], [s * half * t, y, half * t], 0.02, frame);
    }
  }
  // the back stay, leaning away to the hoist house
  const bz = -Math.min(D / 2 - 0.2, 0.9);
  for (const sx of [-1, 1]) k.bar([sx * half * 0.5, H, half * 0.5], [sx * 0.18, 0, bz], 0.03, frame);
  // the sheave wheels and the cage rope
  k.box(0, H, 0, half * 1.4, 0.1, half * 1.4, scale(frame, 0.9));
  for (const sx of [-1, 1]) {
    k.hoop(sx * 0.1, H + 0.18, 0, 0.14, 0.03, STEEL, 12, 'zy');
    k.bar([sx * 0.1, H + 0.18, 0], [sx * 0.1, H + 0.18, bz * 0.6], 0.008, DARK);
  }
  k.bar([0, H + 0.16, 0], [0, 0.1, 0], 0.01, DARK);
  k.box(0, 0, 0, 0.3, 0.12, 0.3, DARK);
  // hoist house and ore bins, with a skip road under them
  k.box(0, 0, bz, 0.9, 0.42, 0.55, pick(r, BRICK), ROOF_GREY);
  win(k, _b, r, 0, 0.12, bz + 0.28, 0.5, 0.14, 1);
  const ox = Math.min(W / 2 - 0.4, 1.0);
  for (const sx of [-1, 1]) {
    k.box(sx * ox, 0.2, D / 2 - 0.5, 0.5, 0.36, 0.5, STEEL);
    k.wedge(sx * ox, 0.06, D / 2 - 0.5, 0.5, 0.14, 0.5, scale(STEEL, 0.85));
    for (const s2 of [-1, 1]) k.box(sx * ox + s2 * 0.22, 0, D / 2 - 0.5, 0.05, 0.2, 0.05, DARK);
    k.box(sx * ox, 0.56, D / 2 - 0.5, 0.52, 0.06, 0.52, hex(0x6b5a48));
  }
  // spoil heaps and the lamp over the shaft
  for (const sx of [-1, 1]) k.cone(sx * (W / 2 - 0.3), 0, -D / 2 + 0.35, 0.3, 0.3, hex(0x7a6a58), 7);
  k.tagged(Vis.Always, () => k.glowBox(0, H * 0.55, half * 0.7, 0.07, 0.07, 0.05, hex(0xf2c14e), [0, 24, 2.4], WARM_GLOW));
};

// ---- lumber yard -------------------------------------------------------------------------------

/** Stacks of sawn boards under open shelters, a log deck, a stacker and the weigh office at the gate. */
const lumberYard: Draw = (k, W, D, b, r) => {
  const plank = hex(0xd8b27a);
  // two open-sided shelters full of banded board stacks
  for (const sx of [-1, 1]) {
    const x = sx * (W / 4);
    const sw = Math.min(W / 2 - 0.3, 1.6), sd = Math.min(D - 1.0, 1.6);
    for (const cx of [-1, 1]) for (const cz of [-1, 1]) k.box(x + cx * (sw / 2 - 0.05), 0, -0.2 + cz * (sd / 2 - 0.05), 0.06, 0.5, 0.06, WOOD);
    k.gable(x, 0.5, -0.2, sw, 0.16, sd, ROOF_GREY, WOOD, true);
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 4; j++) k.box(x - sw / 4 + (i * sw) / 4, j * 0.1, -0.2, sw / 5, 0.1, sd - 0.3, scale(plank, 1 - j * 0.03));
    }
  }
  // the log deck at the back, chained
  for (let row2 = 0; row2 < 3; row2++) {
    for (let i = 0; i < 4 - row2; i++) {
      const z = -D / 2 + 0.35;
      k.bar([-1.0 + row2 * 0.1, 0.06 + row2 * 0.1, z + i * 0.12], [1.0 - row2 * 0.1, 0.06 + row2 * 0.1, z + i * 0.12], 0.05, i % 2 ? TRUNK : scale(TRUNK, 1.08));
    }
  }
  // the gate office, the yard stacker and a load going out
  k.box(W / 2 - 0.35, 0, D / 2 - 0.35, 0.44, 0.3, 0.36, WHITE, ROOF_GREY);
  win(k, b, r, W / 2 - 0.35, 0.1, D / 2 - 0.17, 0.2, 0.12, 1);
  k.box(-W / 2 + 0.5, 0, D / 2 - 0.4, 0.34, 0.2, 0.5, YELLOW, DARK);
  k.box(-W / 2 + 0.5, 0.2, D / 2 - 0.5, 0.26, 0.16, 0.26, DARK);
  for (const sx of [-1, 1]) k.bar([-W / 2 + 0.5 + sx * 0.1, 0.06, D / 2 - 0.65], [-W / 2 + 0.5 + sx * 0.1, 0.06, D / 2 - 0.05], 0.03, STEEL);
  k.glowBox(W / 2 - 0.35, 0.3, D / 2 - 0.35, 0.1, 0.05, 0.1, hex(0xf2c14e), [17, 23, 2], WARM_GLOW);
};

// ---- cannery -----------------------------------------------------------------------------------

/** A long shed on the quay, its roof vents steaming, with fish crates and an ice hopper outside. */
const cannery: Draw = (k, W, D, b, r) => {
  const wall = hex(0xd9dde0), roof = hex(0x5f6b73);
  const bw = W - 0.5, bd = Math.min(D - 0.6, 2.2);
  k.box(0, 0, -D / 2 + bd / 2 + 0.3, bw, 0.5, bd, wall, roof);
  k.gable(0, 0.5, -D / 2 + bd / 2 + 0.3, bw, 0.22, bd, roof, scale(wall, 0.95));
  row(k, b, r, 0, 0.16, -D / 2 + bd + 0.29, bw - 0.6, 0.18, Math.max(3, Math.round(bw)), 1);
  // roof vents and the boiler chimney
  for (let i = 0; i < 3; i++) k.cyl(-bw / 4 + (i * bw) / 4, 0.62, -D / 2 + bd / 2 + 0.3, 0.06, 0.12, METAL, 6);
  k.cyl(bw / 2 - 0.3, 0.5, -D / 2 + 0.5, 0.09, 0.7, pick(r, BRICK), 8);
  // the loading apron: crates of fish, an ice hopper and a lorry bay
  for (let i = 0; i < 4; i++) k.box(-bw / 2 + 0.3 + i * 0.35, 0, D / 2 - 0.45, 0.28, 0.12, 0.28, hex(0x9fb8c4), WHITE);
  k.box(bw / 2 - 0.5, 0, D / 2 - 0.5, 0.4, 0.4, 0.4, STEEL, WHITE);
  k.wedge(bw / 2 - 0.5, 0.4, D / 2 - 0.5, 0.4, 0.12, 0.4, scale(STEEL, 1.05));
  k.box(0, 0.5, -D / 2 + bd + 0.24, 0.9, 0.16, 0.06, SIGN_BLUE);
  k.glowBox(0, 0.5, -D / 2 + bd + 0.21, 0.86, 0.12, 0.02, hex(0xe8f0f4), [16, 23, 1.8], SHOP_GLOW);
};

// ---- grain elevator ----------------------------------------------------------------------------

/** A row of tall concrete silos with the head house over them, a tipping shed and an auger. */
const grainElevator: Draw = (k, W, D, _b, r) => {
  const R = 0.3, H = Math.min(1.8, 1.1 + W * 0.12);
  const n = Math.max(3, Math.min(5, Math.floor(W / 0.62)));
  const span = (n - 1) * R * 2;
  for (let i = 0; i < n; i++) {
    const x = -span / 2 + i * R * 2;
    k.cyl(x, 0, -0.1, R, H, CONCRETE, 10, scale(CONCRETE, 1.05));
  }
  // the head house along the top, and the leg that lifts the grain into it
  k.box(0, H, -0.1, span + R * 2, 0.34, R * 2.1, scale(CONCRETE, 0.95), ROOF_GREY);
  k.box(span / 2 + R * 0.6, 0, -0.1, 0.26, H + 0.6, 0.26, scale(CONCRETE, 0.9), ROOF_GREY);
  k.box(span / 2 + R * 0.6, H + 0.6, -0.1, 0.3, 0.06, 0.3, ROOF_GREY);
  for (let i = 0; i < n; i++) k.glowBox(-span / 2 + i * R * 2, H + 0.12, -0.1 + R, 0.12, 0.1, 0.02, hex(0xf2c14e), [17, 23.5, 1.8], WARM_GLOW);
  // the tipping shed at the front, an auger out to a heap, and a trailer waiting
  k.box(0, 0, D / 2 - 0.5, Math.min(W - 0.6, 1.8), 0.4, 0.7, hex(0xb5543f), ROOF_GREY);
  k.box(0, 0, D / 2 - 0.16, 0.7, 0.34, 0.04, DARK);
  k.bar([-W / 2 + 0.4, 0.06, -D / 2 + 0.4], [-W / 2 + 0.9, 0.5, -D / 2 + 0.9], 0.05, STEEL);
  k.cone(-W / 2 + 0.45, 0, -D / 2 + 0.45, 0.3, 0.26, hex(0xd8a742), 8);
  k.tagged(Vis.Always, () => k.glowBox(0, H + 0.34, -0.1, 0.06, 0.06, 0.06, hex(0xff3b30), [0, 24, 3], hex(0xff3b30)));
  void r;
};

// ---- dry dock ----------------------------------------------------------------------------------

/**
 * A harbour's dry dock: a cut in the quay with stepped sides and a caisson gate, a hull up on blocks
 * inside it under a gantry, and the fitting shop beside it.
 */
const dryDock: Draw = (k, W, D, _b, r) => {
  const quay = pick(r, STONE), deep = hex(0x4a4a4a);
  const dw = Math.min(W - 0.8, 2.0), dd = Math.min(D - 0.8, 3.0);
  // the dock floor, sunk, with steps down its long sides
  k.box(0, -0.42, 0, dw, 0.42, dd, deep, deep);
  for (const sx of [-1, 1]) {
    for (let i = 0; i < 3; i++) {
      k.box(sx * (dw / 2 - 0.04 - i * 0.05), -0.14 - i * 0.14, 0, 0.08, 0.14, dd, scale(quay, 0.9 - i * 0.05));
    }
    k.box(sx * (dw / 2 + 0.18), 0, 0, 0.3, 0.06, dd + 0.4, quay);
  }
  // the caisson gate at the sea end
  k.box(0, -0.42, dd / 2, dw + 0.1, 0.5, 0.18, RUST, METAL);
  // the hull on its keel blocks (or the story's submarine, when Still Waters is bound to this dock)
  const hl = dd * 0.62;
  for (let i = 0; i < 5; i++) k.box(0, -0.42, -hl / 2 + (i * hl) / 4, 0.3, 0.1, 0.12, WOOD);
  if (!smallDockSub(k, _b, dw, dd)) {
    k.box(0, -0.32, 0, dw * 0.55, 0.34, hl, hex(0x7a3f36), hex(0x3f4a52));
    k.wedge(0, -0.32, -hl / 2 - 0.18, dw * 0.55, 0.34, 0.36, hex(0x7a3f36));
    k.box(0, 0.02, hl / 2 - 0.3, dw * 0.35, 0.22, 0.5, WHITE, hex(0x3f4a52));
  }
  // the gantry over the dock and a welder's spark under it
  const gy = 0.55;
  for (const sx of [-1, 1]) lattice(k, sx * (dw / 2 + 0.2), -dd * 0.15, 0, gy, 0.04, YELLOW, 3);
  k.box(0, gy, -dd * 0.15, dw + 0.6, 0.12, 0.2, YELLOW);
  k.bar([0, gy, -dd * 0.15], [0, 0.1, -dd * 0.15], 0.008, DARK);
  k.tagged(Vis.Always, () => k.glowBox(0, 0.05, -dd * 0.15, 0.08, 0.08, 0.08, hex(0xbfe4ff), [0, 24, 4], hex(0xbfe4ff)));
  // the fitting shop along the back
  k.box(0, 0, -D / 2 + 0.35, W - 0.8, 0.44, 0.5, hex(0xcfd4d8), ROOF_GREY);
  k.gable(0, 0.44, -D / 2 + 0.35, W - 0.8, 0.16, 0.5, ROOF_GREY, hex(0xcfd4d8));
};

// ---- cooling towers ----------------------------------------------------------------------------

/**
 * A nuclear station: two hyperbolic cooling towers trailing steam, the reactor dome beside them and a
 * switchyard of pylons and transformers.
 */
const coolingTowers: Draw = (k, W, D, _b, r) => {
  const shell = hex(0xc8c3b8);
  const H = Math.min(2.2, 1.2 + Math.min(W, D) * 0.16), R = Math.min(0.62, W / 4 - 0.1);
  const towerAt = (x: number, z: number) => {
    // the waist: wide at the foot, pinched two thirds up, flaring to the rim
    const prof: [number, number][] = [[0, 1], [0.25, 0.78], [0.55, 0.62], [0.8, 0.62], [1, 0.72]];
    // open at the top, so it is drawn inside too, in shade, over a dark basin
    k.cyl(x, 0, z, R * 0.99, 0.02, scale(shell, 0.35), 12);
    for (let i = 0; i < prof.length - 1; i++) {
      const [t0, s0] = prof[i], [t1, s1] = prof[i + 1];
      k.band(x, z, H * t0, R * s0, H * t1, R * s1, 12, i === 0 ? scale(shell, 0.94) : shell, scale(shell, 0.45 + 0.08 * i));
    }
    // the air inlets round the foot, and the steam standing over the rim
    for (let a = 0; a < 8; a++) {
      const ang = (a / 8) * TAU;
      k.box(x + Math.cos(ang) * R * 0.95, 0, z + Math.sin(ang) * R * 0.95, 0.1, H * 0.12, 0.1, DARK);
    }
    k.tagged(Vis.Always, () => {
      for (let i = 0; i < 3; i++) k.dome(x + (i - 1) * R * 0.3, H + i * 0.1, z + (i % 2) * R * 0.2, R * (0.5 - i * 0.08), WHITE, 8, 2);
    });
  };
  const gap = Math.min(W / 2 - R - 0.2, R * 1.5);
  towerAt(-gap, -D / 2 + R + 0.4);
  towerAt(gap, -D / 2 + R + 0.4);
  // the reactor hall: a long block with the containment dome on it
  k.box(0, 0, D / 2 - 0.9, W - 1.0, 0.5, 0.9, hex(0xdad6cc), ROOF_GREY);
  k.cyl(-W / 4, 0, D / 2 - 0.9, 0.34, 0.55, WHITE, 12);
  k.dome(-W / 4, 0.55, D / 2 - 0.9, 0.34, scale(WHITE, 0.95), 12, 4);
  k.tagged(Vis.Always, () => k.glowBox(-W / 4, 0.92, D / 2 - 0.9, 0.05, 0.05, 0.05, hex(0xff3b30), [0, 24, 3], hex(0xff3b30)));
  // the switchyard: transformers and a line of pylons out of the lot
  for (let i = 0; i < 3; i++) {
    const x = W / 4 - 0.1 + (i - 1) * 0.34;
    k.box(x, 0, D / 2 - 0.4, 0.24, 0.26, 0.24, STEEL);
    for (const sx of [-1, 1]) k.bar([x + sx * 0.08, 0.26, D / 2 - 0.4], [x + sx * 0.08, 0.42, D / 2 - 0.4], 0.012, METAL);
  }
  void r;
};

// ---- oil rig -----------------------------------------------------------------------------------

/**
 * An offshore platform on its legs: the deck with its derrick, the flare boom out to one side, the
 * accommodation block and a helideck over the water. Stands on a patch of raised sea bed, so the legs
 * go down into the water round the lot.
 */
const oilRig: Draw = (k, W, D, _b, r) => {
  const deck = hex(0x6b7076), leg = RUST;
  const hw = Math.min(W / 2 - 0.15, 1.2), hd = Math.min(D / 2 - 0.15, 1.2);
  const dy = 0.45;
  // the jacket: four legs braced down into the water
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    k.bar([sx * hw * 0.8, -0.6, sz * hd * 0.8], [sx * hw * 0.7, dy, sz * hd * 0.7], 0.06, leg);
    k.bar([sx * hw * 0.8, -0.3, sz * hd * 0.8], [-sx * hw * 0.8, -0.1, sz * hd * 0.8], 0.025, leg);
    k.bar([sx * hw * 0.8, -0.3, sz * hd * 0.8], [sx * hw * 0.8, -0.1, -sz * hd * 0.8], 0.025, leg);
  }
  // the deck and its handrails
  k.box(0, dy, 0, hw * 2, 0.12, hd * 2, deck, scale(deck, 1.1));
  for (const sx of [-1, 1]) {
    k.box(sx * hw, dy + 0.12, 0, 0.03, 0.12, hd * 2, METAL);
    k.box(0, dy + 0.12, sx * hd, hw * 2, 0.12, 0.03, METAL);
  }
  // the derrick over the well bay
  const by = dy + 0.12;
  const dxp = -hw * 0.35;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    k.bar([dxp + sx * 0.22, by, sz * 0.22], [dxp + sx * 0.08, by + 0.95, sz * 0.08], 0.025, YELLOW);
  }
  for (let i = 1; i < 4; i++) {
    const y = by + (0.95 * i) / 4, t = 0.22 - (i / 4) * 0.14;
    for (const s of [-1, 1]) {
      k.bar([dxp - t, y, s * t], [dxp + t, y, s * t], 0.012, YELLOW);
      k.bar([dxp + s * t, y, -t], [dxp + s * t, y, t], 0.012, YELLOW);
    }
  }
  k.box(dxp, by + 0.95, 0, 0.2, 0.08, 0.2, STEEL);
  // the accommodation block, the helideck over the corner and the crane
  k.box(hw * 0.45, by, -hd * 0.4, hw * 0.8, 0.34, hd * 0.8, WHITE, hex(0x2f5d8a));
  for (let i = 0; i < 2; i++) k.box(hw * 0.45, by + 0.08 + i * 0.14, -hd * 0.4 + hd * 0.4, hw * 0.7, 0.07, 0.02, GLASS);
  k.cyl(hw * 0.5, by + 0.34, hd * 0.55, 0.42, 0.06, hex(0x3f7d3a), 8, hex(0x3f7d3a));
  k.box(hw * 0.5, by + 0.4, hd * 0.55, 0.3, 0.012, 0.06, WHITE);
  k.box(hw * 0.5, by + 0.4, hd * 0.55, 0.06, 0.012, 0.3, WHITE);
  // the flare boom, lit day and night
  k.bar([-hw * 0.9, by, hd * 0.6], [-hw * 1.5, by + 0.55, hd * 1.1], 0.035, leg);
  k.tagged(Vis.Always, () => {
    k.cone(-hw * 1.5, by + 0.55, hd * 1.1, 0.09, 0.26, hex(0xff8a2a), 6);
    k.glowBox(-hw * 1.5, by + 0.6, hd * 1.1, 0.12, 0.2, 0.12, hex(0xff8a2a), [0, 24, 4], hex(0xff6a1a));
    k.glowBox(hw * 0.45, by + 0.36, -hd * 0.4, 0.06, 0.06, 0.06, hex(0xff3b30), [0, 24, 3], hex(0xff3b30));
  });
  // a supply boat tied up alongside
  k.box(-hw * 0.2, -0.12, hd + 0.45, 0.32, 0.16, 0.9, hex(0xe2412f), WHITE);
  k.box(-hw * 0.2, 0.04, hd + 0.75, 0.24, 0.16, 0.24, WHITE, DARK);
  void r;
};

// ---- launch pad: see buildings/space.ts ---------------------------------------------------------

// ---- customs post ------------------------------------------------------------------------------

/** A county border post: booths either side of the road under a canopy, a barrier and a flag. */
const customsPost: Draw = (k, W, D, b, r) => {
  const booth = WHITE, trim = SIGN_BLUE;
  const lane = Math.min(W * 0.5, 1.2);
  // the canopy over the road on its posts
  const cy = 0.6;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * (W / 2 - 0.15), 0, sz * (D / 2 - 0.25), 0.08, cy, 0.08, METAL);
  k.box(0, cy, 0, W - 0.1, 0.1, D - 0.4, trim, scale(trim, 1.1));
  k.box(0, cy - 0.04, 0, W - 0.2, 0.04, D - 0.5, WHITE);
  // the booths: one each side of the lane, with a lit window
  for (const sx of [-1, 1]) {
    const x = sx * (lane / 2 + 0.3);
    k.box(x, 0, 0, 0.42, 0.5, 0.5, booth, trim);
    k.glowBox(x - sx * 0.22, 0.2, 0, 0.02, 0.18, 0.34, hex(0xdfe8ee), [0, 24, 2.2], SHOP_GLOW);
    win(k, b, r, x, 0.2, 0.26, 0.24, 0.16, 1);
  }
  // the barrier across the lane, red and white, and the sign over it
  k.box(0, 0.22, D / 2 - 0.45, lane * 0.95, 0.05, 0.05, hex(0xe2412f));
  for (let i = 0; i < 4; i++) k.box(-lane / 2 + 0.12 + i * (lane / 4), 0.22, D / 2 - 0.45, lane / 8, 0.053, 0.053, i % 2 ? WHITE : hex(0xe2412f));
  k.box(0, cy + 0.1, -D / 2 + 0.3, 0.9, 0.22, 0.04, trim);
  k.tagged(Vis.Always, () => k.glowBox(0, cy + 0.1, -D / 2 + 0.28, 0.86, 0.18, 0.02, hex(0xe8f0f4), [0, 24, 1.6], SHOP_GLOW));
  // a flag on a pole beside the post
  k.box(W / 2 - 0.25, 0, -D / 2 + 0.3, 0.04, 0.9, 0.04, WHITE);
  k.box(W / 2 - 0.13, 0.72, -D / 2 + 0.3, 0.24, 0.14, 0.01, pick(r, [0xe2412f, 0x2f7fb5, 0x3f9b4a]));
};

// ---- truck stop --------------------------------------------------------------------------------

/** A diner and fuel island for lorries: a long canopy over the pumps, parking bays and a tall sign. */
const truckStop: Draw = (k, W, D, b, r) => {
  const wall = hex(0xf1ede4), roof = hex(0xb5543f);
  // the diner at the back, with its window band
  const dz = -D / 2 + 0.6;
  k.box(-W / 4, 0, dz, Math.min(W / 2, 2.0), 0.42, 0.9, wall, roof);
  k.box(-W / 4, 0.42, dz, Math.min(W / 2, 2.0) + 0.14, 0.06, 1.0, roof);
  row(k, b, r, -W / 4, 0.14, dz + 0.45, Math.min(W / 2, 2.0) - 0.4, 0.2, 4, 1, hex(0x9cc6d9));
  k.glowBox(-W / 4, 0.44, dz + 0.4, 0.7, 0.14, 0.04, hex(0xf2c14e), [0, 24, 2.6], SHOP_GLOW);
  // the fuel island: a canopy on posts over two pumps
  const cx = W / 4, cy = 0.62;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(cx + sx * 0.55, 0, sz * 0.5, 0.07, cy, 0.07, METAL);
  k.box(cx, cy, 0, 1.5, 0.12, 1.4, WHITE, hex(0xe2412f));
  k.box(cx, cy - 0.03, 0, 1.4, 0.03, 1.3, hex(0xe2412f));
  k.tagged(Vis.Always, () => k.glowBox(cx, cy - 0.06, 0, 1.3, 0.04, 1.2, hex(0xfff6d8), [17, 6, 2.4], SHOP_GLOW));
  for (const sz of [-1, 1]) {
    k.box(cx, 0, sz * 0.3, 0.5, 0.3, 0.16, hex(0xd9dde0), DARK);
    k.box(cx, 0.3, sz * 0.3, 0.44, 0.06, 0.14, DARK);
  }
  // lorries in the bays along the front, and the pole sign at the entrance
  for (let i = 0; i < 2; i++) car(k, -W / 2 + 0.6 + i * 0.8, D / 2 - 0.5, false, hex(CARS[(b.seed + i) % CARS.length]));
  const px = W / 2 - 0.3, pz = D / 2 - 0.3;
  k.box(px, 0, pz, 0.08, 1.1, 0.08, METAL);
  k.box(px, 1.1, pz, 0.5, 0.34, 0.06, SIGN_BLUE);
  k.tagged(Vis.Always, () => k.glowBox(px, 1.1, pz - 0.04, 0.46, 0.3, 0.02, hex(0xffe9a8), [0, 24, 2.8], SHOP_GLOW));
};

// ---- weigh station -----------------------------------------------------------------------------

/** A weighbridge on the hard shoulder: the plate in the road, the inspector's office and a signal. */
const weighStation: Draw = (k, W, D, b, r) => {
  const plate = hex(0x9aa0a6);
  // the weighbridge deck, with its kerbs and the pit joint across the middle
  k.box(0, 0, 0.1, Math.min(W - 0.5, 2.2), 0.05, Math.min(D - 0.6, 1.1), plate, scale(plate, 1.08));
  for (const sx of [-1, 1]) k.box(sx * (Math.min(W - 0.5, 2.2) / 2), 0.05, 0.1, 0.06, 0.06, Math.min(D - 0.6, 1.1), YELLOW);
  k.box(0, 0.05, 0.1, Math.min(W - 0.5, 2.2), 0.012, 0.04, DARK);
  // the office, raised a step, looking down the bridge
  const ox = -W / 2 + 0.45;
  k.box(ox, 0, -D / 2 + 0.45, 0.6, 0.06, 0.6, CONCRETE);
  k.box(ox, 0.06, -D / 2 + 0.45, 0.5, 0.38, 0.5, WHITE, hex(0x3f5a73));
  win(k, b, r, ox, 0.16, -D / 2 + 0.7, 0.3, 0.18, 1);
  k.box(ox, 0.44, -D / 2 + 0.45, 0.56, 0.05, 0.56, hex(0x3f5a73));
  // the sign gantry over the bridge with its lit STOP/GO
  const gy = 0.7;
  for (const sx of [-1, 1]) k.box(sx * (W / 2 - 0.2), 0, D / 2 - 0.3, 0.07, gy, 0.07, METAL);
  k.box(0, gy, D / 2 - 0.3, W - 0.3, 0.08, 0.08, METAL);
  k.tagged(Vis.Always, () => {
    k.glowBox(-0.3, gy - 0.12, D / 2 - 0.3, 0.16, 0.16, 0.04, hex(0x7a1a14), [0, 24, 2.6], hex(0xff4a3a));
    k.glowBox(0.3, gy - 0.12, D / 2 - 0.3, 0.16, 0.16, 0.04, hex(0x1a5a24), [0, 24, 2], hex(0x4ade5a));
  });
  void r;
};

// ---- car wash ----------------------------------------------------------------------------------

/** A drive-through wash: the tunnel with its brushes, a vacuum bay and a spinning sign. */
const carWash: Draw = (k, W, D, b, r) => {
  const wall = hex(0xdfe8ee), band = hex(0x2bb3a3);
  const tw = Math.min(W - 0.5, 1.3), tl = Math.min(D - 0.4, 2.2);
  // the tunnel: two side walls and a flat roof, open at both ends
  for (const sx of [-1, 1]) k.box(sx * (tw / 2), 0, 0, 0.12, 0.5, tl, wall, band);
  k.box(0, 0.5, 0, tw + 0.2, 0.08, tl + 0.1, band);
  k.box(0, 0.44, 0, tw + 0.22, 0.05, tl + 0.12, WHITE);
  // the brushes inside, and the water running off the sill
  for (let i = 0; i < 3; i++) {
    const z = -tl / 2 + 0.4 + i * (tl / 3);
    for (const sx of [-1, 1]) k.cyl(sx * (tw / 2 - 0.05), 0.04, z, 0.08, 0.4, hex(0x3f7fb5), 8, hex(0x9cc6d9));
  }
  k.box(0, 0.006, tl / 2 + 0.2, tw, 0.012, 0.4, hex(0x8fb8c2));
  // the vacuum bay beside it
  const vx = -W / 2 + 0.35;
  if (W >= 2.4) {
    k.box(vx, 0, D / 2 - 0.6, 0.3, 0.5, 0.3, hex(0xe2412f), DARK);
    k.bar([vx, 0.5, D / 2 - 0.6], [vx + 0.2, 0.3, D / 2 - 0.35], 0.02, DARK);
  }
  // the sign at the kerb, turning
  k.box(W / 2 - 0.3, 0, D / 2 - 0.3, 0.07, 0.6, 0.07, METAL);
  k.spin(W / 2 - 0.3, 0.6, D / 2 - 0.3, 'y', 0.8, (s) => {
    s.box(0, 0, 0, 0.42, 0.24, 0.05, band, WHITE);
    s.glowBox(0, 0, -0.03, 0.38, 0.2, 0.02, hex(0xe8fbf7), [0, 24, 2.2], SHOP_GLOW);
  });
  // a car waiting its turn, off to the side: the lane itself is left clear to drive through
  if (W >= 2.8) car(k, -W / 2 + 0.4, -tl / 2 - 0.25, false, hex(CARS[b.seed % CARS.length]));
  void r;
};

// ---- scrapyard ---------------------------------------------------------------------------------

/** A yard of crushed cars in stacks, a grab crane on tracks, the parts hut and a hoarding fence. */
const scrapyard: Draw = (k, W, D, b, r) => {
  const fence = hex(0x6b6f76);
  // the hoarding round three sides
  for (const sx of [-1, 1]) k.box(sx * (W / 2 - 0.06), 0, 0, 0.06, 0.34, D - 0.2, fence, scale(fence, 1.1));
  k.box(0, 0, -D / 2 + 0.06, W - 0.2, 0.34, 0.06, fence, scale(fence, 1.1));
  // stacks of flattened cars
  for (let i = 0; i < 4; i++) {
    const x = -W / 2 + 0.6 + (i % 2) * 0.8, z = -D / 2 + 0.6 + Math.floor(i / 2) * 0.8;
    const n = 2 + ((b.seed + i) % 3);
    for (let j = 0; j < n; j++) {
      k.box(x + ((b.seed + j) % 3) * 0.02, j * 0.11, z, 0.48, 0.11, 0.34, hex(CARS[(b.seed + i * 2 + j) % CARS.length]), DARK);
    }
  }
  // the grab crane: a tracked base, a slewing cab and a boom with its magnet
  const gx = W / 2 - 0.7, gz = -0.1;
  k.box(gx, 0, gz, 0.5, 0.14, 0.7, DARK);
  k.spin(gx, 0.14, gz, 'y', 0.25, (s) => {
    s.box(0, 0, 0, 0.36, 0.3, 0.44, YELLOW, DARK);
    s.bar([0, 0.3, 0.1], [0, 0.8, 0.7], 0.05, YELLOW);
    s.bar([0, 0.8, 0.7], [0, 0.55, 1.15], 0.04, YELLOW);
    s.bar([0, 0.55, 1.15], [0, 0.3, 1.15], 0.008, DARK);
    s.cyl(0, 0.22, 1.15, 0.12, 0.08, hex(0x8a2a2a), 8);
  });
  // the parts hut and the pile of tyres by the gate
  k.box(-W / 2 + 0.5, 0, D / 2 - 0.4, 0.5, 0.34, 0.4, hex(0xb5a88f), RUST);
  win(k, b, r, -W / 2 + 0.5, 0.1, D / 2 - 0.2, 0.2, 0.12, 1);
  for (let i = 0; i < 3; i++) k.cyl(W / 2 - 0.45, i * 0.07, D / 2 - 0.4, 0.14, 0.07, OIL, 8);
  void WOOD;
};

