/**
 * Small SVG charts as strings, for the HQ window's Books (docs/hqwindow.html, "The charts"): stacked
 * columns, lines on one axis, a 100% bar, and the table behind each. No library.
 *
 * Colours are CSS variables (--c1 … --c8) holding the validated categorical palette in its fixed order,
 * so a series keeps its colour whatever the filter; the dark UI gives them their own dark steps instead
 * of inverting (index.html, #hq .chart). Thin marks, a 2px gap between segments, the baseline the only
 * rule, a legend always, and a hover tip with the whole column's breakdown.
 */
import { esc, money } from './cargoHud';

export interface Series { label: string; colour: number; values: number[] }

const W = 560;
const PAD = { l: 52, r: 8, t: 10, b: 22 };

const col = (k: number): string => `var(--c${k})`;

/** A round dollar figure for an axis: $0, $500, $1.2k, $34k, $1.5M. */
function axisMoney(v: number): string {
  const a = Math.abs(v);
  if (a >= 1e6) return `$${(v / 1e6).toFixed(a >= 1e7 ? 0 : 1)}M`;
  if (a >= 1e3) return `$${(v / 1e3).toFixed(a >= 1e4 ? 0 : 1)}k`;
  return `$${Math.round(v)}`;
}

/** A top for an axis that is three round steps ($250, $500, $750; $2k, $4k, $6k): its gridlines read cleanly. */
function niceMax(v: number): number {
  if (!(v > 0)) return 300;
  const step = v / 3, p = 10 ** Math.floor(Math.log10(step));
  for (const m of [1, 2, 2.5, 5, 10]) if (m * p >= step) return m * p * 3;
  return 30 * p;
}

function grid(max: number, h: number): string {
  let out = '';
  for (let k = 1; k <= 3; k++) {
    const v = (max * k) / 3, y = PAD.t + (h - PAD.t - PAD.b) * (1 - k / 3);
    out += `<line class="gl" x1="${PAD.l}" x2="${W - PAD.r}" y1="${y.toFixed(1)}" y2="${y.toFixed(1)}"/><text class="ax" x="${PAD.l - 6}" y="${(y + 4).toFixed(1)}" text-anchor="end">${axisMoney(v)}</text>`;
  }
  const y0 = h - PAD.b;
  out += `<line class="base" x1="${PAD.l}" x2="${W - PAD.r}" y1="${y0}" y2="${y0}"/><text class="ax" x="${PAD.l - 6}" y="${y0 + 4}" text-anchor="end">$0</text>`;
  return out;
}

/** Column labels along the bottom, thinned so they never collide. */
function xLabels(cats: string[], x: (i: number) => number, h: number): string {
  const every = Math.max(1, Math.ceil(cats.length / 10));
  return cats.map((c, i) => (i % every === 0 || i === cats.length - 1 ? `<text class="ax" x="${x(i).toFixed(1)}" y="${h - 6}" text-anchor="middle">${esc(c)}</text>` : '')).join('');
}

export function legend(series: Series[]): string {
  return `<div class="legend">${series.map((s) => `<span><i style="background:${col(s.colour)}"></i>${esc(s.label)}</span>`).join('')}</div>`;
}

/** The hover tip for a column: its total, then every series in it that isn't nothing, biggest first. */
function tip(cat: string, series: Series[], i: number): string {
  const rows = series.map((s) => ({ s, v: s.values[i] ?? 0 })).filter((r) => Math.abs(r.v) >= 0.5).sort((a, b) => b.v - a.v);
  const total = rows.reduce((t, r) => t + r.v, 0);
  return esc(`<b>${esc(cat)} · ${money(total)}</b>${rows.map((r) => `<span><i style="background:${col(r.s.colour)}"></i>${esc(r.s.label)}<em>${money(r.v)}</em></span>`).join('')}`);
}

/** Stacked columns, one per category, segments in series order from the baseline up. */
export function stacked(cats: string[], series: Series[], h = 190): string {
  const n = Math.max(1, cats.length);
  const totals = cats.map((_, i) => series.reduce((t, s) => t + Math.max(0, s.values[i] ?? 0), 0));
  const max = niceMax(Math.max(...totals, 0));
  const plotW = W - PAD.l - PAD.r, plotH = h - PAD.t - PAD.b;
  const slot = plotW / n, bw = Math.max(3, Math.min(36, slot - 4));
  const x = (i: number) => PAD.l + slot * (i + 0.5);
  let bars = '';
  cats.forEach((c, i) => {
    let y = h - PAD.b;
    const segs = series.map((s) => ({ s, v: Math.max(0, s.values[i] ?? 0) })).filter((r) => r.v > 0);
    segs.forEach((r, k) => {
      const hh = (r.v / max) * plotH;
      // a 2px surface gap between segments; the top one rounded
      const gap = k ? 2 : 0;
      const top = y - hh;
      if (hh - gap > 0.4) bars += `<rect x="${(x(i) - bw / 2).toFixed(1)}" y="${top.toFixed(1)}" width="${bw.toFixed(1)}" height="${(hh - gap).toFixed(1)}" rx="${k === segs.length - 1 ? Math.min(3, bw / 3) : 0}" fill="${col(r.s.colour)}"/>`;
      y = top;
    });
    bars += `<rect class="hit" data-tip="${tip(c, series, i)}" x="${(x(i) - slot / 2).toFixed(1)}" y="${PAD.t}" width="${slot.toFixed(1)}" height="${plotH}"/>`;
  });
  return `<svg class="chart" viewBox="0 0 ${W} ${h}" role="img">${grid(max, h)}${bars}${xLabels(cats, x, h)}</svg>`;
}

/** Lines on one dollar axis (never two): 2px, with a dot on the last point. */
export function lines(cats: string[], series: Series[], h = 170): string {
  const n = Math.max(1, cats.length);
  const max = niceMax(Math.max(0, ...series.flatMap((s) => s.values)));
  const plotW = W - PAD.l - PAD.r, plotH = h - PAD.t - PAD.b;
  const x = (i: number) => PAD.l + (n === 1 ? plotW / 2 : (plotW * i) / (n - 1));
  const y = (v: number) => h - PAD.b - (Math.max(0, v) / max) * plotH;
  const paths = series.map((s) => {
    const d = s.values.map((v, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(' ');
    const last = s.values.length - 1;
    return `<path d="${d}" fill="none" stroke="${col(s.colour)}" stroke-width="2" stroke-linejoin="round"/>${last >= 0 ? `<circle cx="${x(last).toFixed(1)}" cy="${y(s.values[last]).toFixed(1)}" r="4" fill="${col(s.colour)}" class="ring"/>` : ''}`;
  }).join('');
  const slot = plotW / n;
  const hits = cats.map((c, i) => `<rect class="hit" data-tip="${esc(`<b>${esc(c)}</b>${series.map((s) => `<span><i style="background:${col(s.colour)}"></i>${esc(s.label)}<em>${money(s.values[i] ?? 0)}</em></span>`).join('')}`)}" x="${(x(i) - slot / 2).toFixed(1)}" y="${PAD.t}" width="${slot.toFixed(1)}" height="${plotH}"/>`).join('');
  return `<svg class="chart" viewBox="0 0 ${W} ${h}" role="img">${grid(max, h)}${paths}${hits}${xLabels(cats, x, h)}</svg>`;
}

/** One horizontal bar split into shares of the whole, with the shares written under it. */
export function shareBar(parts: { label: string; colour: number; value: number }[]): string {
  const live = parts.filter((p) => p.value > 0.5);
  const total = live.reduce((t, p) => t + p.value, 0);
  if (!total) return '<p class="none">Nothing yet in this range.</p>';
  let x = 0;
  const bars = live.map((p, k) => {
    const w = (p.value / total) * 100;
    // the colour inline: a style beats the charts' CSS, which makes every other hover target see-through. No
    // rounding here: the bar is stretched to fit (the svg's own corners are rounded instead)
    const r = `<rect x="${x.toFixed(2)}%" y="0" width="${Math.max(0, w - (k < live.length - 1 ? 0.4 : 0)).toFixed(2)}%" height="18" style="fill:${col(p.colour)}" class="seg" data-tip="${esc(`<b>${esc(p.label)}</b><span>${money(p.value)}<em>${Math.round((p.value / total) * 100)}%</em></span>`)}"/>`;
    x += w;
    return r;
  }).join('');
  const keys = live.map((p) => `<span><i style="background:${col(p.colour)}"></i>${esc(p.label)} <b>${Math.round((p.value / total) * 100)}%</b> <small>${money(p.value)}</small></span>`).join('');
  return `<svg class="chart share" viewBox="0 0 100 18" preserveAspectRatio="none" role="img">${bars}</svg><div class="legend">${keys}</div>`;
}

/** The table behind a chart: a row per category, a column per series, and the total. */
export function table(cats: string[], series: Series[], total = true): string {
  const head = `<tr><th></th>${series.map((s) => `<th class="num">${esc(s.label)}</th>`).join('')}${total ? '<th class="num">Total</th>' : ''}</tr>`;
  const rows = cats.map((c, i) => `<tr><td>${esc(c)}</td>${series.map((s) => `<td class="num">${money(s.values[i] ?? 0)}</td>`).join('')}${total ? `<td class="num"><b>${money(series.reduce((t, s) => t + (s.values[i] ?? 0), 0))}</b></td>` : ''}</tr>`).join('');
  return `<div class="tablewrap"><table class="hq-table">${head}${rows}</table></div>`;
}
