import { hex, scale, type RGB } from '../../../world/biomes';
import type { Building, BuildingKind } from '../../../world/tiles';
import type { Rng } from '../../../world/rng';
import { FLOOR } from '../../../world/towns';
import {
  BRIGHT, DARK, windowSched, windowGlow, GLASS_LIGHT, ROOF_GREY, GLASSES, SHOP_GLOW, WARM_GLOW, COOL_GLOW, WOOD, cur, pick, row, win, tower, topOff,
  roofOver, veranda, porch, balcony, engawa, corners, pennant, styleGlass, styleRoof, styleTrim, styleWall,
  type Draw, type Kit, type P3,
} from '../kit';

/**
 * Alternative models for the storey-driven town blocks: apartments, offices and shops. Each is drawn
 * in the original's frame on the same lot (the whole lot is solid: none of these has a SHAPES entry),
 * with the same number of storeys, so a street mixes them freely.
 */

// ---------------------------------------------------------------------------------------------
// shared pieces

/** Crowns that are no more than a flat roof and its edge; a model with its own crown draws it over these. */
const FLAT_CROWNS = new Set(['flat', 'parapet', 'wall', 'dome', 'sawtooth']);

/**
 * A wing of flats w×d standing on y, `floors` storeys, glazed only on the faces listed (0 +x, 1 +z,
 * 2 -x, 3 -z), so a wall a wing shares with its neighbour carries no hidden windows; plinthed, ribbed,
 * coursed and skirted the way `tower` does it (a `plain` wing has no ribs, courses or skirts, and its
 * windows further apart). Its roof is
 * laid in `top`. Returns the top.
 */
function flats(k: Kit, b: Building, r: Rng, x: number, y: number, z: number, w: number, d: number, floors: number, body: RGB, glass: RGB, faces: readonly number[], top: RGB = body, plain = false): number {
  const h = floors * FLOOR;
  if (cur.plinth && y < FLOOR * 0.5 && floors > 1) {
    k.box(x, y, z, w, FLOOR, d, pick(r, cur.plinth));
    k.box(x, y + FLOOR, z, w, h - FLOOR, d, body, top);
  } else k.box(x, y, z, w, h, d, body, top);
  if (cur.massing === 'ribbed' && !plain) {
    // piers up the corners where two glazed faces meet
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      if (!faces.includes(sx > 0 ? 0 : 2) || !faces.includes(sz > 0 ? 1 : 3)) continue;
      k.box(x + sx * (w / 2 - 0.025), y, z + sz * (d / 2 - 0.025), 0.07, h + 0.02, 0.07, styleTrim());
    }
  }
  const wide = Math.max(0.08, cur.band);
  const sp = plain ? 0.4 : 0.3, nx = Math.max(1, Math.round(w / sp)), nz = Math.max(1, Math.round(d / sp));
  for (let f = 0; f < floors; f++) {
    const fy = y + f * FLOOR + 0.07;
    if (faces.includes(1)) row(k, b, r, x, fy, z + d / 2, w - 0.04, wide, nx, 1, glass);
    if (faces.includes(3)) row(k, b, r, x, fy, z - d / 2, w - 0.04, wide, nx, 3, glass);
    if (faces.includes(0)) row(k, b, r, x + w / 2, fy, z, d - 0.04, wide, nz, 0, glass);
    if (faces.includes(2)) row(k, b, r, x - w / 2, fy, z, d - 0.04, wide, nz, 2, glass);
    if (cur.course > 0.3 && f > 0 && !plain) {
      const t = 0.014 * cur.course;
      k.box(x, y + f * FLOOR - t / 2, z, w + 0.025, t, d + 0.025, styleTrim());
    }
  }
  if (cur.crown === 'curved' && !plain) {
    const skirt = scale(pick(r, cur.roofs), 0.9);
    for (let f = 3; f < floors; f += 3) k.box(x, y + f * FLOOR - 0.01, z, w + 0.1, 0.022, d + 0.1, skirt);
  }
  return y + h;
}

/** A square pier or post with its front and two sides (its back and top are never seen), s across. */
function post(k: Kit, x: number, z: number, s: number, h: number, col: RGB): void {
  const x0 = x - s / 2, x1 = x + s / 2, z0 = z - s / 2, z1 = z + s / 2, I: P3 = [x, h / 2, z];
  k.quad([x0, 0, z1], [x1, 0, z1], [x1, h, z1], [x0, h, z1], col, I);
  k.quad([x1, 0, z0], [x1, 0, z1], [x1, h, z1], [x1, h, z0], col, I);
  k.quad([x0, 0, z0], [x0, 0, z1], [x0, h, z1], [x0, h, z0], col, I);
}

/** The lit glass door of a block, on a front facing +z at z. */
const lobby = (k: Kit, x: number, z: number, w = 0.3) =>
  k.glowBox(x, 0, z, w, 0.24, 0.06, GLASS_LIGHT, [16.5, 30, 1.2], WARM_GLOW);

// ---------------------------------------------------------------------------------------------
// apartments

/**
 * Stepped flats: the lower storeys fill the lot and the upper ones step back from the street (and,
 * on a wide lot, from one end) in two or three tiers, each setback a railed roof terrace with a planter.
 */
const steppedFlats: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), glass = styleGlass(r), deck = scale(pick(r, cur.roofs), 0.96), trim = styleTrim();
  const sx = r() < 0.5 ? -1 : 1, wide = W > 1.5;
  const tiers = b.floors >= 6 ? 3 : 2;
  const lower = Math.max(2, Math.ceil(b.floors * (tiers === 3 ? 0.45 : 0.6)));
  const rest = b.floors - lower, mid = tiers === 3 ? Math.ceil(rest / 2) : rest;
  const split = tiers === 3 ? [lower, mid, rest - mid] : [lower, rest];
  let x = 0, z = -0.02, w = W - 0.16, d = D - 0.2, y = 0;
  lobby(k, 0, z + d / 2 + 0.02);
  for (let i = 0; i < split.length; i++) {
    const n = split[i];
    if (n <= 0) break;
    const last = i === split.length - 1 || split[i + 1] <= 0;
    // the lowest tier is a full tower (its turrets, arcade, veranda and balconies); the setbacks are plain
    y = i === 0 ? tower(k, b, r, x, 0, z, w, d, n, wall, glass, 0.08) : flats(k, b, r, x, y, z, w, d, n, wall, glass, [0, 1, 2, 3], last ? wall : deck);
    if (last) { topOff(k, r, x, y, z, w, d, wall); break; }
    // the next tier steps back from the front, and on a wide lot from one end as well
    const back = Math.min(0.3, d * 0.3), end = wide ? Math.min(0.4, w * 0.22) : 0;
    const front = z + d / 2;
    k.box(x, y, front - 0.012, w, 0.07, 0.024, trim);
    if (end) k.box(x + sx * (w / 2 - 0.012), y, z, 0.024, 0.07, d, trim);
    // a planter along the terrace
    k.box(x - sx * w * 0.15, y, front - 0.06, w * 0.4, 0.05, 0.05, hex(0x5f9a4e), hex(0x6fae57));
    x -= sx * end / 2; w -= end; z -= back / 2; d -= back;
  }
};

/**
 * Courtyard flats: an L of wings round a court opening on the street (a U on a wide lot, a C round a
 * side court on a deep one), behind a low garden wall with a gate; a stair tower rises in the court's
 * inner corner, and in a style with balconies the range across the court carries them.
 */
const courtyardFlats: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), glass = styleGlass(r), trim = styleTrim(), low = scale(wall, 0.84);
  const sx = r() < 0.5 ? -1 : 1, f = b.floors;
  const w = W - 0.16, d = D - 0.2, cz = -0.02, z0 = cz - d / 2, z1 = cz + d / 2;
  /** x, z, w, d, glazed faces; the first is the main range, which takes the style's crown and courses. */
  const wings: [number, number, number, number, number[]][] = [];
  // the court's x, z, w, d, the wall closing it, and the front of the range across it
  let court: [number, number, number, number], fence: [number, number, number, number], across: number;
  /** The walls facing the court, glazed only where they show: x, z, width, face. */
  const courtWalls: [number, number, number, 1 | 3][] = [];
  const ww = W > 1.5 ? (D > 1.5 ? 0.55 : 0.42) : 0.36;
  if (D < 1.5 || W > 1.5) {
    // the court opens on the street between the wings (one wing on a narrow lot)
    const rb = D > 1.5 ? 0.55 : Math.min(0.44, d * 0.55), bf = z0 + rb, wd = z1 - bf;
    wings.push([0, z0 + rb / 2, w, rb, [0, 2, 3]]);
    const sides = W > 1.5 ? [-1, 1] : [sx];
    for (const s of sides) wings.push([s * (w / 2 - ww / 2), bf + wd / 2, ww, wd, [0, 1, 2]]);
    const cw = w - sides.length * ww, cx = sides.length === 2 ? 0 : -sx * ww / 2;
    court = [cx, bf + wd / 2, cw, wd];
    fence = [cx, z1 - 0.02, cw, 0.04];
    across = bf;
    courtWalls.push([cx, bf, cw, 1]);
  } else {
    // a deep lot: a range on the street, one at the back, a wing down one flank and the court on the other
    const rf = 0.42, ff = z1 - rf, bf = z0 + rf, wd = ff - bf;
    wings.push([0, z1 - rf / 2, w, rf, [0, 1, 2]]);
    wings.push([0, z0 + rf / 2, w, rf, [0, 2, 3]]);
    wings.push([sx * (w / 2 - ww / 2), bf + wd / 2, ww, wd, [0, 2]]);
    court = [-sx * ww / 2, bf + wd / 2, w - ww, wd];
    fence = [-sx * (w / 2 - 0.02), court[1], 0.04, wd];
    across = bf;
    courtWalls.push([court[0], bf, w - ww, 1], [court[0], ff, w - ww, 3]);
  }
  // the garden wall, a dark iron gate in its middle
  const [fx, fz, fw, fd] = fence;
  k.box(fx, 0, fz, fw, 0.3, fd, low, trim);
  if (fw > fd) k.box(fx, 0, fz + 0.022, Math.min(0.2, fw * 0.4), 0.26, 0.012, DARK);
  else k.box(fx - sx * 0.022, 0, fz, 0.012, 0.26, Math.min(0.2, fd * 0.4), DARK);
  let top = 0;
  wings.forEach(([x, z, ww2, wd, faces], i) => {
    top = flats(k, b, r, x, 0, z, ww2, wd, f, wall, glass, faces, wall, i > 0);
    // the style's crown on the main range; a plain coping on the rest where that crown is flat or ornate
    const plainTop = FLAT_CROWNS.has(cur.crown) || cur.crown === 'step' || cur.crown === 'spire' || cur.crown === 'battlement';
    if (i === 0 || !plainTop) topOff(k, r, x, top, z, ww2, wd, wall);
    else k.box(x, top, z, ww2 + 0.03, 0.05, wd + 0.03, scale(wall, 0.9));
  });
  const wide = Math.max(0.08, cur.band);
  for (const [x, z, cw, face] of courtWalls) {
    const n = Math.max(1, Math.round(cw / 0.3));
    for (let i = 0; i < f; i++) row(k, b, r, x, i * FLOOR + 0.07, z, cw - 0.06, wide, n, face, glass);
  }
  if (cur.massing === 'veranda') veranda(k, r, 0, 0, wings[0][1], w, wings[0][3], FLOOR * 0.92);
  // balconies on the range across the court, looking out over it
  if (cur.balcony && f >= cur.balcony.min) for (let i = 1; i < f; i++) balcony(k, court[0], i * FLOOR, across, court[2] * 0.7, 1);
  // the stair tower in the court's inner corner, a storey over the roofs, a slit lit on each landing
  const ts = 0.17, tx = court[0] + sx * (court[2] / 2 - ts / 2), tz = across + ts / 2;
  const th = top + FLOOR * 0.8;
  if (cur.massing === 'turret') {
    const cone = cur.pennant ? pick(r, cur.pennant) : styleRoof(r);
    k.cyl(tx, 0, tz, ts * 0.6, th, wall, 8);
    k.cone(tx, th, tz, ts * 0.72, ts * 1.6, cone, 8);
    if (cur.pennant) pennant(k, tx, th + ts * 1.6, tz, 0.14, pick(r, cur.pennant));
  } else {
    k.box(tx, 0, tz, ts, th, ts, scale(wall, 0.94));
    if (FLAT_CROWNS.has(cur.crown) || cur.form === 'flat') k.box(tx, th, tz, ts + 0.03, 0.03, ts + 0.03, trim);
    else k.hip(tx, th, tz, ts + 0.05, 0.12, ts + 0.05, styleRoof(r));
  }
  for (let i = 1; i <= f; i++) win(k, b, r, tx, i * FLOOR - 0.02, tz + ts / 2, 0.06, 0.12, 1, glass);
  lobby(k, tx, tz + ts / 2, 0.1);
};

/**
 * Deck-access slab: a plain slab whose storeys open onto long access decks along its street face (along
 * one flank on a deep lot), a blank stair-and-lift core at one end rising over the roof, and a water
 * tank on the core's flat top.
 */
export const deckSlab: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), glass = styleGlass(r), trim = styleTrim(), f = b.floors, h = f * FLOOR;
  const flank = D > W * 1.5, sx = r() < 0.5 ? -1 : 1;
  const w = W - 0.16, d = D - 0.2, z = -0.02, gd = 0.11, cs = 0.2;
  const deck = cur.balcony ? hex(cur.balcony.rail) : scale(trim, 0.92);
  // the slab, set back behind its decks, and its core at one end
  let bx = 0, bz = z, bw = w, bd = d;
  let core: [number, number, number, number];
  if (flank) {
    bw = w - gd; bx = -sx * gd / 2;
    core = [bx, z - d / 2 + cs / 2, bw, cs];
    bd = d - cs; bz = z + cs / 2;
  } else {
    bd = d - gd; bz = z - gd / 2;
    core = [sx * (w / 2 - cs / 2), bz, cs, bd];
    bw = w - cs; bx = -sx * cs / 2;
  }
  const faces = flank ? [0, 1, 2] : [1, 3, sx > 0 ? 2 : 0];
  const top = flats(k, b, r, bx, 0, bz, bw, bd, f, wall, glass, faces);
  topOff(k, r, bx, top, bz, bw, bd, wall);
  if (cur.massing === 'veranda') veranda(k, r, bx, 0, bz, bw, bd, FLOOR * 0.92);
  // the decks: a slab and solid parapet in one at each storey, the lowest on posts
  for (let i = 1; i < f; i++) {
    const y = i * FLOOR - 0.014;
    if (flank) k.box(bx + sx * (bw / 2 + gd / 2), y, bz, gd, 0.06, bd, deck, scale(deck, 0.8));
    else k.box(bx, y, bz + bd / 2 + gd / 2, bw, 0.06, gd, deck, scale(deck, 0.8));
  }
  for (const s of [-0.5, 0.5]) {
    if (flank) post(k, bx + sx * (bw / 2 + gd - 0.02), bz + s * (bd - 0.06), 0.03, FLOOR - 0.014, trim);
    else post(k, bx + s * (bw - 0.06), bz + bd / 2 + gd - 0.02, 0.03, FLOOR - 0.014, trim);
  }
  // the core: blank walls a storey over the roof, a slit lit on each landing, a water tank on its top
  const [cx, czz, cw, cd] = core, ch = h + FLOOR * 0.7;
  k.box(cx, 0, czz, cw, ch, cd, scale(wall, 0.86), trim);
  for (let i = 0; i < f; i++) win(k, b, r, cx, i * FLOOR + 0.12, czz + cd / 2, 0.06, 0.12, 1, glass);
  lobby(k, cx, czz + cd / 2 + 0.02, 0.14);
  if (r() < 0.75) {
    k.cyl(cx, ch, czz, 0.085, 0.16, WOOD, 6);
    k.cone(cx, ch + 0.16, czz, 0.095, 0.06, WOOD, 6);
  }
};

// ---------------------------------------------------------------------------------------------
// offices

/**
 * Podium and tower: two storeys filling the lot, lit shopfronts along the street, and a slimmer tower
 * set back on the podium roof, crowned in the style's way.
 */
const podiumOffice: Draw = (k, W, D, b, r) => {
  const body = styleWall(r), glass = cur.modernTall && b.floors > 12 ? pick(r, GLASSES) : styleGlass(r), trim = styleTrim();
  const pw = W - 0.14, pd = D - 0.14, pf = 2, ph = pf * FLOOR, front = pd / 2;
  const base = cur.plinth ? pick(r, cur.plinth) : scale(body, 0.9);
  k.box(0, 0, 0, pw, ph, pd, base, scale(pick(r, cur.roofs), 0.95));
  k.box(0, ph, 0, pw + 0.03, 0.05, pd + 0.03, trim);
  // shopfronts all along the street at ground level, offices lit above them
  const n = Math.max(2, Math.round(pw / 0.34));
  row(k, b, r, 0, 0.03, front, pw - 0.1, 0.17, n, 1, GLASS_LIGHT);
  k.glowBox(0, 0.21, front + 0.03, pw * 0.7, 0.03, 0.06, trim, [16.5, 22, 1.4], SHOP_GLOW);
  const nz = Math.max(1, Math.round(pd / 0.34));
  for (const s of [-1, 1]) row(k, b, r, s * pw / 2, FLOOR + 0.07, 0, pd - 0.1, 0.11, nz, s > 0 ? 0 : 2, glass);
  row(k, b, r, 0, FLOOR + 0.07, front, pw - 0.1, 0.11, n, 1, glass);
  row(k, b, r, 0, FLOOR + 0.07, -front, pw - 0.1, 0.11, n, 3, glass);
  if (cur.massing === 'veranda') veranda(k, r, 0, 0, 0, pw, pd, FLOOR * 0.92);
  if (cur.massing === 'porch') porch(k, r, 0, 0, 0, pw, pd, FLOOR * 0.92);
  // the tower, back from the street
  const tw = pw * 0.64, td = pd * 0.64, tz = -pd * 0.08;
  const top = tower(k, b, r, 0, ph + 0.05, tz, tw, td, Math.max(1, b.floors - pf), body, glass, 0.15);
  const roof = topOff(k, r, 0, top, tz, tw, td, body);
  if (FLAT_CROWNS.has(cur.crown) && r() < 0.5) k.box(tw * 0.2, roof, tz - td * 0.2, 0.26, 0.14, 0.22, hex(0x9aa0a6));
  // a planted edge on the podium roof in front of the tower
  k.box(0, ph + 0.05, front - 0.06, pw * 0.8, 0.04, 0.06, hex(0x5f9a4e), hex(0x6fae57));
};

/**
 * Finned tower with an offset core: the glazed office floors hung off a blank service core at one end
 * that rises over them, vertical fins down the long faces, and (where the style's crown is flat) a
 * stepped crown with a lit band.
 */
const finnedOffice: Draw = (k, W, D, b, r) => {
  const body = styleWall(r), glass = cur.modernTall && b.floors > 12 ? pick(r, GLASSES) : styleGlass(r), trim = styleTrim();
  const sx = r() < 0.5 ? -1 : 1, f = b.floors, h = f * FLOOR;
  const w = W - 0.14, d = D - 0.14, cw = Math.min(0.5, w * 0.26), mw = w - cw, mx = -sx * cw / 2;
  // the core: blank but for a slit per floor, a floor and a half over the offices
  const cx = sx * (w / 2 - cw / 2), ch = h + FLOOR * 1.5, coreCol = scale(body, 0.82);
  k.box(cx, 0, 0, cw, ch, d * 0.86, coreCol);
  k.box(cx, ch, 0, cw + 0.02, 0.04, d * 0.86 + 0.02, trim);
  const top = tower(k, b, r, mx, 0, 0, mw, d, f, body, glass, 0.15);
  // fins down the front and back, between the window bays
  const nx = Math.max(1, Math.round(mw / 0.3)), fin = scale(trim, 0.95);
  for (let i = 1; i < nx; i++) {
    const fx = mx - mw / 2 + (mw * i) / nx;
    for (const sz of [-1, 1]) k.box(fx, FLOOR, sz * (d / 2 + 0.02), 0.022, h - FLOOR, 0.04, fin);
  }
  if (FLAT_CROWNS.has(cur.crown)) {
    // a stepped crown, two tiers each narrower, a lit band under the first
    k.glowBox(mx, top, 0, mw - 0.02, 0.05, d - 0.02, glass, [17, 24, 1.4], COOL_GLOW);
    k.box(mx, top + 0.05, 0, mw, 0.08, d, body);
    k.box(mx, top + 0.13, 0, mw * 0.72, 0.1, d * 0.72, trim);
    k.box(mx, top + 0.23, 0, mw * 0.44, 0.1, d * 0.44, body);
  } else topOff(k, r, mx, top, 0, mw, d, body);
  // the lobby under a canopy
  const front = d / 2;
  k.glowBox(mx, 0, front + 0.02, Math.min(0.4, mw * 0.5), 0.22, 0.05, GLASS_LIGHT, [16.5, 22, 1.4], COOL_GLOW);
  k.box(mx, 0.24, front + 0.05, Math.min(0.5, mw * 0.6), 0.02, 0.1, trim);
};

// ---------------------------------------------------------------------------------------------
// shops

/** Four walls of a block, no top: for a storey another stands on. */
function walls(k: Kit, x: number, y: number, z: number, w: number, h: number, d: number, col: RGB): void {
  const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2, y1 = y + h, I: P3 = [x, y + h / 2, z];
  k.quad([x0, y, z1], [x1, y, z1], [x1, y1, z1], [x0, y1, z1], col, I);
  k.quad([x0, y, z0], [x1, y, z0], [x1, y1, z0], [x0, y1, z0], col, I);
  k.quad([x1, y, z0], [x1, y, z1], [x1, y1, z1], [x1, y1, z0], col, I);
  k.quad([x0, y, z0], [x0, y, z1], [x0, y1, z1], [x0, y1, z0], col, I);
}

/**
 * A five-sided block: a box from x0..x1, z0..z1 with the corner at (side, z1) cut off `c` along both
 * walls, and its top in `top` unless that is null (a storey stands on it).
 */
function cutBlock(k: Kit, x0: number, x1: number, z0: number, z1: number, y: number, h: number, c: number, side: number, col: RGB, top: RGB | null): void {
  const pts: [number, number][] = side > 0
    ? [[x0, z0], [x1, z0], [x1, z1 - c], [x1 - c, z1], [x0, z1]]
    : [[x0, z0], [x1, z0], [x1, z1], [x0 + c, z1], [x0, z1 - c]];
  const I: P3 = [(x0 + x1) / 2, y + h / 2, (z0 + z1) / 2], y1 = y + h;
  for (let i = 0; i < 5; i++) {
    const [ax, az] = pts[i], [bx, bz] = pts[(i + 1) % 5];
    k.quad([ax, y, az], [bx, y, bz], [bx, y1, bz], [ax, y1, az], col, I);
  }
  if (top) for (let i = 1; i < 4; i++) k.tri([pts[0][0], y1, pts[0][1]], [pts[i][0], y1, pts[i][1]], [pts[i + 1][0], y1, pts[i + 1][1]], top, I);
}

/** The awning colour a shop takes, as the original does: the style's shutters or roofs, else a bright stripe. */
const awningOf = (r: Rng): RGB => cur.shutter ? hex(cur.shutter[0]) : cur.form ? pick(r, cur.roofs) : pick(r, BRIGHT);

/**
 * Corner shop: the street corner cut away full height for a canted door (in a half-timbered style,
 * only the shop floor is cut and the storeys above are jettied over it on a corner post), shop windows
 * round both faces, and a little square belvedere turned to the corner over the roof (an oriel on the
 * front where the style's roofs would not take one).
 */
const cornerShop: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), floors = Math.max(1, b.floors), h = floors * FLOOR + 0.06, trim = styleTrim();
  const sx = r() < 0.5 ? -1 : 1, w = 0.86, d = 0.8, z = -0.05, front = z + d / 2, c = 0.2;
  const jetty = !!cur.timber && floors > 1;
  const roofTop = cur.form ? wall : ROOF_GREY;
  if (jetty) {
    cutBlock(k, -w / 2, w / 2, z - d / 2, front, 0, FLOOR, c, sx, wall, null);
    k.box(0, FLOOR, z, w, h - FLOOR, d, wall);
    post(k, sx * (w / 2 - 0.018), front - 0.018, 0.036, FLOOR, trim);
  } else if (cur.plinth && floors > 1) {
    cutBlock(k, -w / 2, w / 2, z - d / 2, front, 0, FLOOR, c, sx, pick(r, cur.plinth), null);
    cutBlock(k, -w / 2, w / 2, z - d / 2, front, FLOOR, h - FLOOR, c, sx, wall, roofTop);
  } else cutBlock(k, -w / 2, w / 2, z - d / 2, front, 0, h, c, sx, wall, roofTop);
  if (cur.form && cur.massing === 'ribbed') corners(k, 0, z, w, d, h);
  // the canted face, in a frame turned to face the corner: the door, a window on each floor over it, the belvedere
  const a = (sx * Math.PI) / 4, mx = sx * (w / 2 - c / 2), mz = front - c / 2;
  const px = mx * Math.cos(a) - mz * Math.sin(a), pz = mx * Math.sin(a) + mz * Math.cos(a);
  const upstairs: Building = { ...b, kind: 'apartment' };
  const oriel = cur.form === 'curved' || cur.form === 'dutch' || cur.form === 'false' || cur.form === 'low';
  k.turned(a, () => {
    k.pane(px, 0.02, pz, 0.12, 0.19, 1, GLASS_LIGHT, windowSched(b.kind, r), windowGlow(b.kind, r));
    if (cur.noren) {
      const cloth = pick(r, cur.noren);
      for (let i = 0; i < 3; i++) k.box(px - 0.045 + i * 0.045, 0.14, pz + 0.012, 0.04, 0.07, 0.008, cloth);
    }
    if (!jetty) for (let fl = 1; fl < floors; fl++) win(k, upstairs, r, px, 0.08 + fl * FLOOR, pz, 0.1, 0.13, 1);
    if (!oriel) {
      // the belvedere stands on the cant, over the eaves, under a little pyramid (a dome on a white island)
      const bs = c * Math.SQRT2 * 0.9, top = cur.form && cur.form !== 'flat' ? h + Math.min(0.3, 0.8 * cur.pitch * 0.9) * 0.7 : h + 0.14;
      k.box(px, h - 0.02, pz - bs / 2, bs, top - h + 0.02, bs, wall, trim);
      if (cur.form === 'flat') {
        if (cur.crown === 'dome') k.dome(px, top, pz - bs / 2, bs * 0.4, trim, 6, 2);
      } else k.hip(px, top, pz - bs / 2, bs + 0.04, 0.12, bs + 0.04, cur.pennant ? pick(r, cur.pennant) : styleRoof(r));
    }
  });
  // shop windows round both faces, the flats above keeping home hours
  const sideFace = sx > 0 ? 0 : 2;
  win(k, b, r, -sx * 0.1, 0.03, front, 0.5, 0.17, 1, GLASS_LIGHT);
  win(k, b, r, sx * w / 2, 0.03, z - 0.1, 0.42, 0.17, sideFace, GLASS_LIGHT);
  if (!cur.noren && cur.massing !== 'veranda' && cur.massing !== 'porch') k.box(-sx * 0.1, 0.22, front + 0.06, 0.56, 0.025, 0.12, awningOf(r));
  for (let fl = 1; fl < floors; fl++) {
    const y = 0.08 + fl * FLOOR;
    if (!oriel) win(k, upstairs, r, -sx * 0.2, y, front, 0.16, 0.13, 1);
    if (jetty || oriel) win(k, upstairs, r, sx * w / 2, y, z - 0.12, 0.16, 0.13, sideFace);
  }
  if (cur.form) roofOver(k, r, 0, h, z, w, d, wall, styleRoof(r));
  if (oriel && floors > 1) {
    // an oriel hung out over the street at the far end of the front
    const ow = 0.26, ox = -sx * (w / 2 - ow / 2 - 0.04), oy = FLOOR + 0.03, oh = h - FLOOR - 0.08;
    k.box(ox, oy, front + 0.04, ow, oh, 0.08, wall, trim);
    for (let fl = 1; fl < floors; fl++) win(k, upstairs, r, ox, 0.08 + fl * FLOOR, front + 0.08, 0.18, 0.13, 1);
  }
  if (cur.balcony && floors >= cur.balcony.min) for (let fl = 1; fl < floors; fl++) balcony(k, -sx * 0.2, fl * FLOOR, front, 0.3, 1);
  if (cur.massing === 'veranda') veranda(k, r, 0, 0, z, w, d, FLOOR * 0.92);
  if (cur.massing === 'porch') porch(k, r, 0, 0, z, w, d, FLOOR * 0.92);
  if (cur.engawa !== undefined) engawa(k, 0, z, w, d, floors > 1, styleRoof(r));
};

/**
 * Arcade shop: the shop floor set deep behind a row of piers carrying the storeys above, lit at the
 * back of the arcade, and a parapet over the street with the shop's sign on it, lit after dark (under a
 * style with its own small roof: that roof, and the sign on the fascia over the arcade).
 */
const arcadeShop: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), floors = Math.max(1, b.floors), h = floors * FLOOR + 0.06, trim = styleTrim();
  const w = 0.88, d = 0.8, z = -0.05, front = z + d / 2, deep = 0.14;
  const brand = cur.form ? awningOf(r) : pick(r, BRIGHT);
  // the shop, back behind the arcade
  const shopFront = front - deep;
  walls(k, 0, 0, z - deep / 2, w - 0.02, FLOOR, d - deep, cur.plinth ? pick(r, cur.plinth) : scale(wall, 0.92));
  win(k, b, r, 0, 0.03, shopFront, 0.64, 0.18, 1, GLASS_LIGHT);
  if (cur.noren) {
    const cloth = pick(r, cur.noren);
    for (let i = 0; i < 3; i++) k.box(-0.1 + i * 0.1, 0.13, shopFront + 0.012, 0.09, 0.08, 0.008, cloth);
  }
  // the storeys above on their piers, a parapet standing up over the street where the roof is flat
  const para = cur.form ? 0 : 0.13;
  k.box(0, FLOOR, z, w, h - FLOOR + para, d, wall, cur.form ? wall : ROOF_GREY);
  if (cur.form && cur.massing === 'ribbed') corners(k, 0, z, w, d, h);
  const pier = cur.plinth ? pick(r, cur.plinth) : trim;
  for (let i = 0; i < 3; i++) post(k, (i - 1) * (w / 2 - 0.03), front - 0.03, 0.055, FLOOR, pier);
  const upstairs: Building = { ...b, kind: 'apartment' };
  for (let fl = 1; fl < floors; fl++) for (const px of [-0.22, 0.22]) win(k, upstairs, r, px, 0.08 + fl * FLOOR, front, 0.16, 0.13, 1);
  // the sign, lit after dark with the shop: on the parapet, or on the fascia over the arcade
  const sy = cur.form ? FLOOR + 0.015 : h + 0.02, sh = cur.form ? 0.05 : 0.09;
  k.pane(0, sy, front, w * 0.62, sh, 1, brand, [16.5, 22.5, 1.6], SHOP_GLOW);
  if (cur.form) roofOver(k, r, 0, h, z, w, d, wall, styleRoof(r));
  if (cur.balcony && floors >= cur.balcony.min) for (let fl = 1; fl < floors; fl++) balcony(k, 0, fl * FLOOR, front, w * 0.8, 1);
  if (cur.engawa !== undefined) engawa(k, 0, z, w, d, floors > 1, styleRoof(r));
};

export const BLOCK_VARIANTS: Partial<Record<BuildingKind, Draw[]>> = {
  apartment: [steppedFlats, courtyardFlats, deckSlab],
  office: [podiumOffice, finnedOffice],
  shop: [cornerShop, arcadeShop],
};
