import { hex, scale, type RGB } from '../../world/biomes';
import type { Building, Town } from '../../world/tiles';
import {
  BOWL_H, GRID_LOWER, GRID_TOP, GRID_UPPER, PILLOW_IN, PILLOW_OUT, PILLOW_ROOF, fieldPt, gridStands, parkOf, pillowAt, pillowAxes,
  stadiumDesignOf, stadiumPlan, teamOf, type FieldRect, type StadiumPlan, type Team,
} from '../../world/stadiums';
import type { Sched } from '../nightLights';
import { COOL_GLOW, DARK, METAL, TAU, WHITE, type Draw, type Kit, type P3 } from './kit';

/**
 * The four stadiums (world/stadiums.ts has their plans): the old open oval, a two-tier gridiron under a
 * canopy with a video board hung over the field, a brick ballpark with a green wall in left, and a ring of
 * inflated cushions that glows in the team's colour after dark. Each carries its team's name out front.
 */

const GRASS = hex(0x5fb04c), GRASS2 = hex(0x6cc25a), GRASS3 = hex(0x58a647), DIRT = hex(0xc08a5a), CONCRETE = hex(0xcfcac0);
const BRICK_RED = hex(0xa4583f), PARK_GREEN = hex(0x2f6b3a), IVY = hex(0x3d7f3a), SEAT_GREEN = hex(0x2f6e48), POST_YELLOW = hex(0xf2d230);
/** Floodlights on game nights. */
const lightsFor = (r: () => number): Sched => [18 + r(), 22 + r() * 1.5, 2.6];

/** The home team, from the town the stadium stands in. */
export function homeTeam(t: Town | null): Team | null {
  return t ? teamOf(t.name, undefined, t.accent) : null;
}

/** The board out front with the team's name across it in white capitals. */
function signBoard(k: Kit, p: StadiumPlan, text: string, lit = true): void {
  const s = p.sign;
  k.box(s.x, s.y, s.z, s.w, s.h, 0.06, hex(s.col));
  if (lit) k.glowBox(s.x, s.y - 0.025, s.z + 0.02, s.w * 0.92, 0.02, 0.03, WHITE, [17.5, 24, 1.6], COOL_GLOW);
  letters(k, text, s.x, s.y + s.h / 2, s.z + 0.032, s.w * 0.92, s.h * 0.8);
}

/** Capitals centred on (x, y) on a face looking +z, fitted into w × h. */
export function letters(k: Kit, text: string, x: number, y: number, z: number, w: number, h: number): void {
  const t = text.toUpperCase().replace(/[^A-Z0-9& ]/g, '');
  if (!t) return;
  const ADV = 0.56;
  const size = Math.min(h, w / (t.length * ADV + (1 - ADV)));
  const span = size * (t.length * ADV + (1 - ADV));
  let cx = x - span / 2 + size / 2;
  const yb = y - size / 2, yt = y + size / 2;
  for (const ch of t) {
    if (ch !== ' ') k.glyph(ch, [cx - size / 2, yb, z], [cx + size / 2, yb, z], [cx + size / 2, yt, z], [cx - size / 2, yt, z]);
    cx += size * ADV;
  }
}

/** A lit floodlight bank on a mast. */
function mast(k: Kit, x: number, y0: number, z: number, h: number, game: Sched): void {
  k.cyl(x, y0, z, 0.04, h, METAL, 6);
  k.glowBox(x, y0 + h, z, 0.32, 0.18, 0.32, hex(0xfff4c2), game, COOL_GLOW);
}

/** Stripes of mown grass, end lines and a halfway line: a soccer pitch in a field rectangle. */
function soccerPitch(k: Kit, f: FieldRect, team: RGB): void {
  const at = (a: number, c: number) => fieldPt(f, a, c);
  const n = 10;
  for (let i = 0; i < n; i++) {
    const a = -f.len / 2 + (i + 0.5) * (f.len / n), p = at(a, 0);
    const [w, d] = f.axis === 'x' ? [f.len / n, f.wid] : [f.wid, f.len / n];
    k.box(p.x, 0, p.z, w, 0.03, d, i % 2 ? GRASS2 : GRASS3);
  }
  const line = (a0: number, c0: number, a1: number, c1: number) => {
    const p = at((a0 + a1) / 2, (c0 + c1) / 2);
    const la = Math.abs(a1 - a0) + 0.03, lc = Math.abs(c1 - c0) + 0.03;
    k.box(p.x, 0.03, p.z, f.axis === 'x' ? la : lc, 0.005, f.axis === 'x' ? lc : la, WHITE);
  };
  const L = f.len / 2 - 0.08, C = f.wid / 2 - 0.08;
  line(-L, -C, L, -C); line(-L, C, L, C); line(-L, -C, -L, C); line(L, -C, L, C); line(0, -C, 0, C);
  for (const s of [-1, 1]) {
    const box = Math.min(0.55, f.len * 0.13), bw = C * 0.6;
    line(s * L, -bw, s * (L - box), -bw); line(s * L, bw, s * (L - box), bw); line(s * (L - box), -bw, s * (L - box), bw);
  }
  const m = at(0, 0);
  k.hoop(m.x, 0.035, m.z, Math.min(0.42, C * 0.4), 0.012, WHITE, 18, 'xz');
  k.disc(m.x, 0.034, m.z, 0.12, team, 12);
}

// ---- the open oval --------------------------------------------------------------------------------

const bowl = (k: Kit, W: number, D: number, team: Team | null, r: () => number): void => {
  const p = stadiumPlan('bowl', W, D);
  const ax = W / 2 - 0.25, az = D / 2 - 0.25, ix = ax * 0.64, iz = az * 0.6, H = BOWL_H, seg = 36;
  const seats = [team ? hex(team.colour) : hex(0x2f7fb5), WHITE], wall = CONCRETE;
  const at = (a: number, sx: number, sz: number): [number, number] => [Math.cos(a) * sx, Math.sin(a) * sz];
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU, am = (a0 + a1) / 2;
    const [o0x, o0z] = at(a0, ax, az), [o1x, o1z] = at(a1, ax, az);
    const [i0x, i0z] = at(a0, ix, iz), [i1x, i1z] = at(a1, ix, iz);
    const out: P3 = [Math.cos(am) * ax * 1.6, 0, Math.sin(am) * az * 1.6];
    k.tri([0, 0.012, 0], [i0x, 0.012, i0z], [i1x, 0.012, i1z], GRASS, [0, -1, 0]);
    k.quad([i0x, 0.15, i0z], [i1x, 0.15, i1z], [o1x, H, o1z], [o0x, H, o0z], seats[Math.floor(s / 3) % 2], out);
    k.quad([o0x, 0, o0z], [o1x, 0, o1z], [o1x, H, o1z], [o0x, H, o0z], wall, [0, H / 2, 0]);
    k.quad([i0x, 0, i0z], [i1x, 0, i1z], [i1x, 0.15, i1z], [i0x, 0.15, i0z], wall, out);
    k.quad([o0x, H, o0z], [o1x, H, o1z], [o1x * 1.04, H + 0.07, o1z * 1.04], [o0x * 1.04, H + 0.07, o0z * 1.04], WHITE, [0, 0, 0]);
  }
  soccerPitch(k, p.field, seats[0]);
  const game = lightsFor(r);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) mast(k, sx * (W / 2 - 0.2), 0, sz * (D / 2 - 0.2), 2.1, game);
  k.glowBox(0, H, -az * 0.98, 1.2, 0.45, 0.08, DARK, game, hex(0x8fd0ff));
  if (team) signBoard(k, p, team.nick);
};

// ---- the gridiron ---------------------------------------------------------------------------------

/**
 * A band round the field like a picture frame: from the rectangle ±(ix, iz) at y0 to ±(ox, oz) at y1,
 * mitred at the corners. `inside` says which way is solid: below the band (a rake), or within it.
 */
function frame(k: Kit, ix: number, iz: number, y0: number, ox: number, oz: number, y1: number, col: RGB | ((side: number) => RGB), inside: 'below' | 'in' | 'out'): void {
  const sides: [number, number][] = [[1, 0], [0, 1], [-1, 0], [0, -1]];
  sides.forEach(([sx, sz], i) => {
    // the side's two inner and two outer corners
    const ia: P3 = sx ? [sx * ix, y0, -iz] : [-ix, y0, sz * iz], ib: P3 = sx ? [sx * ix, y0, iz] : [ix, y0, sz * iz];
    const oa: P3 = sx ? [sx * ox, y1, -oz] : [-ox, y1, sz * oz], ob: P3 = sx ? [sx * ox, y1, oz] : [ox, y1, sz * oz];
    const I: P3 = inside === 'below' ? [sx * Math.max(ix, ox) * 1.02, Math.min(y0, y1) - 0.5, sz * Math.max(iz, oz) * 1.02]
      : inside === 'in' ? [0, (y0 + y1) / 2, 0] : [sx * (ox + 3), (y0 + y1) / 2, sz * (oz + 3)];
    k.quad(ia, ib, ob, oa, typeof col === 'function' ? col(i) : col, I);
  });
}

const gridiron = (k: Kit, W: number, D: number, team: Team | null, r: () => number): void => {
  const p = stadiumPlan('gridiron', W, D), s = gridStands(W, D);
  const c = team ? hex(team.colour) : hex(0x1f4e9a), alt = team ? hex(team.alt) : WHITE;
  const ring = (t: number) => [s.IX + t * s.sd, s.IZ + t * s.sd] as const;
  const [lx, lz] = ring(GRID_LOWER), [cx, cz] = ring(GRID_LOWER + 0.05), [ux, uz] = ring(GRID_UPPER);
  const game = lightsFor(r);
  // the turf, its stripes and end zones
  k.box(0, 0, 0, 2 * s.IX, 0.025, 2 * s.IZ, GRASS);
  const f = p.field, n = 10, zone = f.len / 12, play = f.len - 2 * zone;
  for (let i = 0; i < n; i++) {
    const a = -play / 2 + (i + 0.5) * (play / n), q = fieldPt(f, a, 0);
    const [w, d] = f.axis === 'x' ? [play / n, f.wid] : [f.wid, play / n];
    k.box(q.x, 0, q.z, w, 0.03, d, i % 2 ? GRASS2 : GRASS3);
  }
  for (const e of [-1, 1]) {
    const q = fieldPt(f, e * (play / 2 + zone / 2), 0);
    k.box(q.x, 0, q.z, f.axis === 'x' ? zone : f.wid, 0.032, f.axis === 'x' ? f.wid : zone, e < 0 ? c : scale(c, 0.8));
    // the goal posts on the end line
    const g = fieldPt(f, e * (f.len / 2 - 0.02), 0), cb = fieldPt(f, e * (f.len / 2 - 0.02), 0);
    k.cyl(g.x, 0, g.z, 0.018, 0.22, POST_YELLOW, 6);
    const half = Math.min(0.2, f.wid * 0.1);
    const [ax, az] = f.axis === 'x' ? [0, half] : [half, 0];
    k.bar([cb.x - ax, 0.22, cb.z - az], [cb.x + ax, 0.22, cb.z + az], 0.012, POST_YELLOW);
    for (const sgn of [-1, 1]) k.bar([cb.x + sgn * ax, 0.22, cb.z + sgn * az], [cb.x + sgn * ax, 0.62, cb.z + sgn * az], 0.01, POST_YELLOW);
  }
  for (let i = 0; i <= n; i++) {
    const q = fieldPt(f, -play / 2 + i * (play / n), 0);
    k.box(q.x, 0.032, q.z, f.axis === 'x' ? 0.02 : f.wid, 0.004, f.axis === 'x' ? f.wid : 0.02, WHITE);
  }
  for (const e of [-1, 1]) {
    const q = fieldPt(f, 0, e * (f.wid / 2));
    k.box(q.x, 0.032, q.z, f.axis === 'x' ? f.len : 0.025, 0.004, f.axis === 'x' ? 0.025 : f.len, WHITE);
  }
  k.disc(0, 0.034, 0, Math.min(0.3, f.wid * 0.12), c, 14);
  // the field wall, the lower bowl, the club level's glass, the upper deck
  frame(k, s.IX, s.IZ, 0, s.IX, s.IZ, 0.1, alt, 'out');
  frame(k, s.IX, s.IZ, 0.1, lx, lz, 0.65, c, 'below');
  frame(k, lx, lz, 0.65, cx, cz, 0.65, CONCRETE, 'below');
  frame(k, cx, cz, 0.65, cx, cz, 0.8, DARK, 'out');
  for (const [sx, sz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const len = sx ? 2 * cz : 2 * cx, nWin = Math.floor(len / 0.3);
    for (let i = 0; i < nWin; i++) {
      const o = -len / 2 + (i + 0.5) * (len / nWin);
      k.pane(sx ? sx * cx : o, 0.68, sz ? sz * cz : o, 0.2, 0.09, sx > 0 ? 2 : sx < 0 ? 0 : sz > 0 ? 3 : 1, hex(0x4a5560), [17.5, 24, 1.4], hex(0xffe2a8));
    }
  }
  frame(k, cx, cz, 0.8, ux, uz, 0.8, CONCRETE, 'below');
  frame(k, ux, uz, 0.8, s.OX, s.OZ, GRID_TOP, scale(c, 0.78), 'below');
  // the outside: concrete, a band in the team's colour, dark glass at the top
  frame(k, s.OX, s.OZ, 0, s.OX, s.OZ, GRID_TOP, CONCRETE, 'in');
  frame(k, s.OX + 0.012, s.OZ + 0.012, 0.52, s.OX + 0.012, s.OZ + 0.012, 0.62, c, 'in');
  frame(k, s.OX + 0.012, s.OZ + 0.012, 1.05, s.OX + 0.012, s.OZ + 0.012, GRID_TOP - 0.05, hex(0x3c4650), 'in');
  // the canopy over the upper deck, on its four corner pylons
  const [rx, rz] = ring(0.62), RY = 1.78;
  frame(k, rx, rz, RY, s.OX + 0.05, s.OZ + 0.05, RY - 0.08, WHITE, 'below');
  frame(k, rx, rz, RY - 0.03, s.OX + 0.05, s.OZ + 0.05, RY - 0.11, hex(0xb9bec6), 'out');
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    k.box(sx * (s.OX - 0.02), 0, sz * (s.OZ - 0.02), 0.16, RY + 0.25, 0.16, CONCRETE);
    k.glowBox(sx * (s.OX - 0.05), RY + 0.25, sz * (s.OZ - 0.05), 0.4, 0.14, 0.4, hex(0xfff4c2), game, COOL_GLOW);
  }
  // the video board, hung over the middle of the field from the canopy's corners
  const B = p.board, bw = B.w, bd = B.w * 0.55;
  const [bx, bz] = B.yaw ? [bd, bw] : [bw, bd];
  k.box(0, B.y - B.h / 2 - 0.06, 0, bx + 0.06, 0.06, bz + 0.06, c);
  k.glowBox(0, B.y - B.h / 2, 0, bx, B.h, bz, DARK, [6, 30, 1.2], hex(0x9fd8ff));
  k.box(0, B.y + B.h / 2, 0, bx + 0.06, 0.06, bz + 0.06, c);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.bar([sx * bx / 2, B.y + B.h / 2 + 0.06, sz * bz / 2], [sx * rx, RY - 0.05, sz * rz], 0.008, METAL);
  if (team) signBoard(k, p, team.nick);
};

// ---- the ballpark ---------------------------------------------------------------------------------

const ballpark = (k: Kit, W: number, D: number, team: Team | null, r: () => number): void => {
  const p = stadiumPlan('ballpark', W, D), q = parkOf(W, D);
  const S = Math.SQRT1_2, home: [number, number] = [0, q.zH];
  // along the lines: u toward first base, v toward third
  const P = (u: number, v: number, y = 0): P3 => [home[0] + S * (u - v), y, home[1] - S * (u + v)];
  const dir = (th: number, rr: number, y = 0): P3 => [Math.sin(th) * rr, y, home[1] - Math.cos(th) * rr];
  const game = lightsFor(r);
  const base = p.diamond!.base, R = q.R, f = q.f, sd = q.sd, L = q.L;
  const down: P3 = [0, -1, 0];
  // the grass: fair territory a fan, the foul ground along the lines and behind the plate
  const seg = 24;
  for (let i = 0; i < seg; i++) {
    const a0 = -Math.PI / 4 + (i / seg) * (Math.PI / 2), a1 = -Math.PI / 4 + ((i + 1) / seg) * (Math.PI / 2);
    k.tri(P(0, 0, 0.012), dir(a0, R, 0.012), dir(a1, R, 0.012), Math.floor(i / 3) % 2 ? GRASS2 : GRASS3, down);
  }
  k.quad(P(-f, -f, 0.01), P(R, -f, 0.01), P(R, 0, 0.01), P(-f, 0, 0.01), GRASS, down);
  k.quad(P(-f, 0, 0.01), P(0, 0, 0.01), P(0, R, 0.01), P(-f, R, 0.01), GRASS, down);
  // the infield: a dirt arc, the grass square inside the bases, the mound, the plate
  for (let i = 0; i < 12; i++) {
    const a0 = -Math.PI / 4 + (i / 12) * (Math.PI / 2), a1 = -Math.PI / 4 + ((i + 1) / 12) * (Math.PI / 2);
    k.tri(P(0, 0, 0.018), dir(a0, base * 1.5, 0.018), dir(a1, base * 1.5, 0.018), DIRT, down);
  }
  const g = 0.09;
  k.quad(P(g, g, 0.022), P(base - g, g, 0.022), P(base - g, base - g, 0.022), P(g, base - g, 0.022), GRASS2, down);
  const mound = P(base * 0.47, base * 0.47);
  k.cyl(mound[0], 0.018, mound[2], 0.1, 0.02, DIRT, 10);
  k.cyl(home[0], 0.016, home[1], 0.2, 0.008, DIRT, 12);
  for (const [u, v] of [[0, 0], [base, 0], [base, base], [0, base]]) { const b = P(u, v); k.box(b[0], 0.02, b[2], 0.06, 0.012, 0.06, WHITE); }
  // the foul lines out to the poles, and the poles
  k.bar(P(0, 0, 0.026), P(R, 0, 0.026), 0.008, WHITE);
  k.bar(P(0, 0, 0.026), P(0, R, 0.026), 0.008, WHITE);
  for (const pole of [P(R, 0), P(0, R)]) k.cyl(pole[0], 0, pole[2], 0.015, 0.95, POST_YELLOW, 6);
  // the grandstand wrapped round the plate and down both lines: two raked strips mitred behind home
  const strips: [number, number, number, number][] = [[L, -f, -f, -f], [-f, -f, -f, L]];
  const back = (u: number, v: number) => [u === -f ? -f - sd : u, v === -f ? -f - sd : v] as const;
  const rake = (u0: number, v0: number, u1: number, v1: number, t0: number, t1: number, y0: number, y1: number, col: RGB) => {
    const lerp = (u: number, v: number, t: number) => { const [bu, bv] = back(u, v); return [u + (bu - u) * t, v + (bv - v) * t] as const; };
    const [a0, b0] = lerp(u0, v0, t0), [a1, b1] = lerp(u1, v1, t0), [c0, d0] = lerp(u0, v0, t1), [c1, d1] = lerp(u1, v1, t1);
    k.quad(P(a0, b0, y0), P(a1, b1, y0), P(c1, d1, y1), P(c0, d0, y1), col, P(-f - sd - 1, -f - sd - 1, -1));
  };
  for (const [u0, v0, u1, v1] of strips) {
    rake(u0, v0, u1, v1, 0, 0.5, 0.12, 0.545, SEAT_GREEN);
    rake(u0, v0, u1, v1, 0.5, 1, 0.545, 0.97, scale(SEAT_GREEN, 0.88));
    // the padded wall along the line, and the brick back wall
    const [bu0, bv0] = back(u0, v0), [bu1, bv1] = back(u1, v1);
    k.quad(P(u0, v0, 0), P(u1, v1, 0), P(u1, v1, 0.12), P(u0, v0, 0.12), PARK_GREEN, P(-f - 2, -f - 2, 0.06));
    k.quad(P(bu0, bv0, 0), P(bu1, bv1, 0), P(bu1, bv1, 0.97), P(bu0, bv0, 0.97), BRICK_RED, P(0, 0, 0.4));
    // dark arches along the brick
    const len = Math.hypot(bu1 - bu0, bv1 - bv0), n = Math.floor(len / 0.42);
    for (let i = 0; i < n; i++) {
      const t = (i + 0.5) / n, w = P(bu0 + (bu1 - bu0) * t, bv0 + (bv1 - bv0) * t);
      k.box(w[0], 0.08, w[2], 0.13, 0.22, 0.13, hex(0x3a2a24));
    }
  }
  // the ends of the strips, out by the foul poles
  for (const [u, v, bu, bv] of [[L, -f, L, -f - sd], [-f, L, -f - sd, L]]) {
    k.quad(P(u, v, 0), P(bu, bv, 0), P(bu, bv, 0.97), P(u, v, 0.12), BRICK_RED, P(u - 1, v - 1, 0.3));
  }
  // the grandstand roof, on posts, with the old light towers on top
  const RY = 1.22;
  for (const [u0, v0, u1, v1] of strips) {
    const lerp = (u: number, v: number, t: number) => { const [bu, bv] = back(u, v); return [u + (bu - u) * t, v + (bv - v) * t] as const; };
    const [a0, b0] = lerp(u0, v0, 0.6), [a1, b1] = lerp(u1, v1, 0.6), [c0, d0] = lerp(u0, v0, 1.04), [c1, d1] = lerp(u1, v1, 1.04);
    k.quad(P(a0, b0, RY), P(a1, b1, RY), P(c1, d1, RY + 0.06), P(c0, d0, RY + 0.06), PARK_GREEN, P(-f - sd - 1, -f - sd - 1, 0));
    k.quad(P(a0, b0, RY - 0.03), P(a1, b1, RY - 0.03), P(c1, d1, RY + 0.03), P(c0, d0, RY + 0.03), scale(PARK_GREEN, 0.7), P(a0, b0, RY + 3));
    const n = Math.max(2, Math.floor(Math.hypot(a1 - a0, b1 - b0) / 0.9));
    for (let i = 0; i <= n; i++) {
      const t = i / n, w = P(a0 + (a1 - a0) * t, b0 + (b1 - b0) * t);
      k.cyl(w[0], 0.6, w[2], 0.018, RY - 0.6, PARK_GREEN, 5);
    }
  }
  for (const [u, v] of [[L * 0.82, -f - sd * 0.8], [-f - sd * 0.8, L * 0.82], [-f - sd * 0.8, -f - sd * 0.8]]) {
    const w = P(u, v);
    mast(k, w[0], RY + 0.06, w[2], 0.85, game);
  }
  // the outfield: a tall green wall in left, an ivied fence round to right, bleachers behind it
  const split = Math.atan2(-0.38, 1.62);
  const fseg = 30;
  for (let i = 0; i < fseg; i++) {
    const a0 = -Math.PI / 4 + (i / fseg) * (Math.PI / 2), a1 = -Math.PI / 4 + ((i + 1) / fseg) * (Math.PI / 2);
    const monster = (a0 + a1) / 2 < split;
    const h = monster ? 0.62 : 0.22, col = monster ? PARK_GREEN : IVY;
    const i0 = dir(a0, R), i1 = dir(a1, R), o0 = dir(a0, R + 0.08), o1 = dir(a1, R + 0.08);
    k.quad(i0, i1, [i1[0], h, i1[2]], [i0[0], h, i0[2]], col, dir((a0 + a1) / 2, R + 1, h / 2));
    k.quad(o0, o1, [o1[0], h, o1[2]], [o0[0], h, o0[2]], col, dir((a0 + a1) / 2, R - 1, h / 2));
    k.quad([i0[0], h, i0[2]], [i1[0], h, i1[2]], [o1[0], h, o1[2]], [o0[0], h, o0[2]], scale(col, 0.85), dir((a0 + a1) / 2, R + 0.04, 0));
    if (!monster) {
      // bleachers, cut off where the lot ends
      const reach = (a: number) => {
        let rr = R + 0.1 + q.bl;
        for (; rr > R + 0.3; rr -= 0.05) { const pt = dir(a, rr); if (Math.abs(pt[0]) <= q.OX && pt[2] >= -q.OZ) break; }
        return rr;
      };
      const r0 = reach(a0), r1 = reach(a1);
      if (r0 > R + 0.3 && r1 > R + 0.3) {
        const y = (rr: number) => 0.08 + ((rr - R - 0.1) / q.bl) * 0.42;
        k.quad(dir(a0, R + 0.1, 0.08), dir(a1, R + 0.1, 0.08), dir(a1, r1, y(r1)), dir(a0, r0, y(r0)), i % 2 ? hex(0x7f8c7a) : hex(0x8b9886), dir((a0 + a1) / 2, R + 0.3, -1));
        k.quad(dir(a0, r0, 0), dir(a1, r1, 0), dir(a1, r1, y(r1)), dir(a0, r0, y(r0)), BRICK_RED, dir((a0 + a1) / 2, R, 0.2));
      }
    }
  }
  // the hand-turned scoreboard in centre, on its legs
  const B = p.board;
  for (const sx of [-1, 1]) k.box(B.x + sx * B.w * 0.4, 0, B.z - 0.04, 0.06, B.y - B.h / 2, 0.06, PARK_GREEN);
  k.box(B.x, B.y - B.h / 2 - 0.06, B.z - 0.05, B.w + 0.14, B.h + 0.2, 0.08, PARK_GREEN);
  k.glowBox(B.x, B.y - B.h / 2, B.z, B.w, B.h, 0.02, hex(0x23402c), game, hex(0xfff4c2));
  k.glowBox(B.x, B.y + B.h / 2 + 0.14, B.z - 0.05, 0.18, 0.12, 0.05, WHITE, [17.5, 30, 2], WHITE);
  // the red marquee out front, with bulbs under it
  const s = p.sign;
  for (const sx of [-1, 1]) k.box(s.x + sx * 0.7, 0, s.z, 0.05, s.y, 0.05, DARK);
  signBoard(k, p, team?.nick ?? 'BALLPARK', false);
  for (let i = 0; i < 9; i++) k.glowBox(s.x - s.w * 0.44 + i * (s.w * 0.88 / 8), s.y - 0.03, s.z + 0.035, 0.03, 0.03, 0.03, WHITE, [17 + (i % 3) * 0.02, 24, 2.4], hex(0xfff0b0));
};

// ---- the pillow -----------------------------------------------------------------------------------

const pillow = (k: Kit, W: number, D: number, team: Team | null, r: () => number): void => {
  const p = stadiumPlan('pillow', W, D);
  const { A, B } = pillowAxes(W, D);
  const c = team ? hex(team.colour) : hex(0xd63a2f);
  const seg = 48, at = (a: number, f: number) => pillowAt(A, B, a, f);
  const game = lightsFor(r);
  const H = 1.62, rings = 6;
  const bulge = (y: number) => 0.955 + 0.045 * Math.sin((Math.PI * y) / H);
  const seatH = (f: number) => 0.12 + ((f - PILLOW_IN) / (PILLOW_OUT - PILLOW_IN)) * 1.15;
  const tiers: [number, number, RGB][] = [[PILLOW_IN, 0.66, hex(0x6b707a)], [0.66, 0.8, c], [0.8, PILLOW_OUT, hex(0x5a5f69)]];
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU, am = (a0 + a1) / 2;
    const out = at(am, 3);
    const OUT: P3 = [out[0], -1, out[1]];
    // the pitch's surround, the stands in three tiers, the wall at their foot
    const [p0x, p0z] = at(a0, PILLOW_IN), [p1x, p1z] = at(a1, PILLOW_IN);
    k.tri([0, 0.01, 0], [p0x, 0.01, p0z], [p1x, 0.01, p1z], GRASS, [0, -1, 0]);
    k.quad([p0x, 0, p0z], [p1x, 0, p1z], [p1x, 0.12, p1z], [p0x, 0.12, p0z], hex(0x3a3f45), OUT);
    for (const [f0, f1, col] of tiers) {
      const [a0x, a0z] = at(a0, f0), [a1x, a1z] = at(a1, f0), [b0x, b0z] = at(a0, f1), [b1x, b1z] = at(a1, f1);
      k.quad([a0x, seatH(f0), a0z], [a1x, seatH(f0), a1z], [b1x, seatH(f1), b1z], [b0x, seatH(f1), b0z], col, OUT);
    }
    // the roof over the stands, white on top and grey beneath, its inner lip lit for night games
    const [r0x, r0z] = at(a0, PILLOW_ROOF), [r1x, r1z] = at(a1, PILLOW_ROOF), [e0x, e0z] = at(a0, 0.955), [e1x, e1z] = at(a1, 0.955);
    k.quad([r0x, 1.5, r0z], [r1x, 1.5, r1z], [e1x, H, e1z], [e0x, H, e0z], hex(0xe9edf0), [0, 0, 0]);
    k.quad([r0x, 1.47, r0z], [r1x, 1.47, r1z], [e1x, H - 0.03, e1z], [e0x, H - 0.03, e0z], hex(0x8c9198), [0, 4, 0]);
    k.quad([r0x, 1.47, r0z], [r1x, 1.47, r1z], [r1x, 1.5, r1z], [r0x, 1.5, r0z], hex(0xc9ced4), [out[0], 1.5, out[1]]);
    if (s % 4 === 0) k.glowBox(r0x * 0.99, 1.4, r0z * 0.99, 0.12, 0.06, 0.12, hex(0xfff4c2), game, COOL_GLOW);
    // the skin: rows of cushions, offset row on row so the seams run as diamonds, lit in the team's colour after dark
    for (let j = 0; j < rings; j++) {
      const y0 = (j / rings) * H, y1 = ((j + 1) / rings) * H;
      const off = j % 2 ? 0.5 : 0;
      const b0 = ((s + off) / seg) * TAU, b1 = ((s + 1 + off) / seg) * TAU;
      const [q0x, q0z] = at(b0, bulge(y0)), [q1x, q1z] = at(b1, bulge(y0)), [w0x, w0z] = at(b0, bulge(y1)), [w1x, w1z] = at(b1, bulge(y1));
      const [mx, mz] = at((b0 + b1) / 2, bulge((y0 + y1) / 2) + 0.02), ym = (y0 + y1) / 2;
      const day = (s + j) % 2 ? hex(0xeef2f5) : hex(0xdfe5ea), glow = (s + j) % 3 === 0 ? scale(c, 0.85) : c;
      const I: P3 = [0, ym, 0];
      // each cushion puffs out at its middle: four facets to a point
      const m: P3 = [mx, ym, mz], sch: Sched = [17.5, 29.5, 1.5];
      k.glowTri([q0x, y0, q0z], [q1x, y0, q1z], m, I, day, sch, glow);
      k.glowTri([q1x, y0, q1z], [w1x, y1, w1z], m, I, day, sch, glow);
      k.glowTri([w1x, y1, w1z], [w0x, y1, w0z], m, I, day, sch, glow);
      k.glowTri([w0x, y1, w0z], [q0x, y0, q0z], m, I, day, sch, glow);
    }
  }
  soccerPitch(k, p.field, c);
  // the screen hung under the roof at the back, and the doors out front
  const Bd = p.board;
  k.glowBox(Bd.x, Bd.y - Bd.h / 2, Bd.z, Bd.w, Bd.h, 0.05, DARK, [6, 30, 1.2], hex(0x9fd8ff));
  k.glowBox(0, 0, B * 0.985, Math.min(1.4, A * 0.5), 0.2, 0.06, hex(0x4a5560), [17, 24, 1.4], hex(0xffe2a8));
  if (team) signBoard(k, p, team.nick);
};

// ---- which one ------------------------------------------------------------------------------------

/** A stadium: whichever of the four its seed chose, in its home team's colours. */
export const stadium: Draw = (k, W, D, b: Building, r, t) => {
  const team = homeTeam(t);
  const d = stadiumDesignOf(b);
  if (d === 'gridiron') gridiron(k, W, D, team, r);
  else if (d === 'ballpark') ballpark(k, W, D, team, r);
  else if (d === 'pillow') pillow(k, W, D, team, r);
  else bowl(k, W, D, team, r);
};
