import type { CargoFactions, CargoItem } from '../cargo';
import type { Mission } from '../missions/model';
import type { Smuggling } from '../smuggling';
import { FACTIONS, LINKED, PACE, RUNG, RUNGS, cargoFaction, contestFor, missionFaction, type FactionId } from './factions';
import { reputation, type By } from './reputation';
import { unlocks } from './unlocks';
import { UNLOCKS } from './factions';
import { deeds } from '../deeds';
import { NEXT_080 } from '../../world/nextWorld';

/** The Oath's step a mission is ("oath:post:3" → the Post, step 3), or null. Parsed here so this file needn't load the templates. */
function oathOf(tpl: string): { f: FactionId; i: number } | null {
  const m = /^oath:([a-z]+):(\d)$/.exec(tpl);
  return m && m[1] in FACTIONS ? { f: m[1] as FactionId, i: Number(m[2]) - 1 } : null;
}

/** What each step of a faction's introduction pays it: 1,150 over the five, a Friend by the end. */
const RISE_REP = [150, 175, 225, 300, 300];

/**
 * The factions plugged into the game (docs/factions.html, "How standing moves"): the cargo system asks
 * what a load pays and is told when one is delivered, a mission done tells its faction, a night run tells
 * the Family and a bust the Constabulary, and money spent on roads and earthworks is the Brotherhood's.
 * Every bar that moves past a rung says so in a notification, and anything newly unlocked with it.
 */
interface FactionWireHost {
  /** The game day (for the log and the healing). */
  day(): number;
  /** The hour of the day (the Guild's morning auction). */
  hour(): number;
  /** A notification: title, line, how long, kept in the log, its group. */
  announce(title: string, body: string, ms?: number, keep?: boolean, group?: string): void;
  /** A little float over the player's vehicle. */
  float(text: string, at: { x: number; y: number; z: number }, kind: 'info' | 'tax'): void;
  /** Something about the factions changed: the HQ window redraws if it is up. */
  changed(): void;
}

/** The minimum change shown as a float over the vehicle. */
const FLOAT_MIN = 4;
/** The darker of a faction's two colours, darkened further while it is pale: it is read against a white halo. */
function readable(a: number, b: number): string {
  const lum = (c: number) => (((c >> 16) & 255) * 0.299 + ((c >> 8) & 255) * 0.587 + (c & 255) * 0.114) / 255;
  const c = lum(a) <= lum(b) ? a : b;
  const k = Math.min(1, 0.42 / Math.max(0.01, lum(c)));
  const ch = (s: number) => Math.round(((c >> s) & 255) * k).toString(16).padStart(2, '0');
  return `#${ch(16)}${ch(8)}${ch(0)}`;
}

/** A driver's gain shows over their dock square from this much (it is half the player's, PACE.crew). */
const CREW_FLOAT_MIN = 2;

export class FactionWire implements CargoFactions {
  constructor(private host: FactionWireHost) {
    reputation.day = () => host.day();
    reputation.onChange = () => host.changed();
    reputation.onRung = (f, from, to) => this.rungChanged(f, from, to);
    reputation.onReady = (f) => this.oathReady(f);
  }

  /**
   * A bar has just reached 9,999: say so loudly, with what to do next (a player at 9,999 with the Deuce had no
   * idea how to begin the Army's Oath, 7 Nov 2026). The first step's diamond goes up at the faction's hall.
   */
  private oathReady(f: FactionId): void {
    const def = FACTIONS[f];
    const ride = def.unlocks[1];
    this.host.announce(`${def.icon} ${def.name}: the Oath`,
      NEXT_080
        ? `9,999: their ${def.giver.toLowerCase()} will swear you in. Five tasks, three of them at their stronghold: the first is posted at a ◆ at their hall. Two are begun there in the ${ride.name}. H → Factions shows the way.`
        : `9,999: their ${def.giver.toLowerCase()} will swear you in. Five tasks, each begun at their hall in the ${ride.name}: the first is posted at a ◆ there once a ${ride.name} is in your fleet. H → Factions shows the way.`,
      12000, true, 'factions');
  }

  // ---- the cargo system's questions ------------------------------------------------------------

  payMul(it: CargoItem): number {
    let m = reputation.payMul(it.type.id);
    // the Guild's morning auction (Sworn): anything of theirs landed at a market or cannery before the eight o'clock bell pays double
    if (cargoFaction(it.type.id) === 'guild' && reputation.sworn('guild') && (it.to.kind === 'fishMarket' || it.to.kind === 'cannery' || it.to.kind === 'minorPort')) {
      const h = this.host.hour();
      if (h >= 4 && h < 8) m *= 2;
    }
    return m;
  }

  name(it: CargoItem): string | null {
    const f = cargoFaction(it.type.id);
    return f ? FACTIONS[f].short : null;
  }

  favours(it: CargoItem): { f: FactionId; loses?: FactionId } | null {
    return reputation.favours(it.type.id, it.from?.kind as string | undefined, it.to.kind as string, it.value0);
  }

  version(): number { return reputation.version; }

  offered(t: { id: string }, from: { kind: string } | null, to: { kind: string }): boolean {
    if (!reputation.offered(t.id)) return false;
    if (from && !reputation.doorOpen(from.kind)) return false;
    return reputation.doorOpen(to.kind);
  }

  delivered(it: CargoItem, by: By, at: { x: number; y: number; z: number }): { text: string; colour: string } | null {
    // the Factions shelf: their work by the player's own hand, and the loads that cost one side what they pay the other
    if (by === 'you' && cargoFaction(it.type.id)) { deeds.add('facLoads'); deeds.mark('facCargo', it.type.id); }
    const grey = contestFor(it.type.id, it.from?.kind as string | undefined, it.to.kind as string);
    if (by === 'you' && grey && Object.values(grey.moves).some((k) => (k ?? 0) < 0)) deeds.add('greyActs');
    const best = reputation.delivered(it.type.id, it.type.name, it.from?.kind as string | undefined, it.to.kind as string, it.value0, by);
    if (!best || best.d < (by === 'crew' ? CREW_FLOAT_MIN : FLOAT_MIN)) return null;
    const f = FACTIONS[best.f];
    const text = `${f.icon} ${f.short} +${Math.round(best.d)}`;
    if (by === 'you') this.host.float(text, { x: at.x, y: at.y + 0.4, z: at.z }, 'info');
    // a driver's: the game shows it over their square in the dock, after their pay (main.ts)
    return { text, colour: readable(f.colour, f.accent) };
  }

  // ---- the other acts ------------------------------------------------------------------------------

  /** A share more for what happened on the way (Star Tours' sights): set by the mechanics. */
  extra: ((it: CargoItem, def: import('../vehicles').VehicleDef) => number) | undefined = undefined;

  /** A mission done: its faction's thanks, as a line for the card. */
  missionDone(m: Mission): string | null {
    const f = missionFaction(m.tpl, m.giver.who);
    if (!f) return null;
    // the Oath pays its own (game/missions/factionTemplates.ts): a step, and the fifth makes the player Sworn
    const o = oathOf(m.tpl);
    if (o) {
      reputation.oathStep(o.f, o.i, m.title);
      return o.i >= 4 ? `${FACTIONS[o.f].icon} Sworn to ${FACTIONS[o.f].name}` : `${FACTIONS[o.f].icon} The Oath: ${o.i + 1} of 5`;
    }
    // a step of a faction's introduction (missions/factionChains.ts): more each step, about a Friend's worth over the five
    const rise = /^rise:[a-z]+:(\d)$/.exec(m.tpl);
    if (rise) {
      // the fifth step is the meeting at the leader's table
      if (rise[1] === '5') deeds.mark('leaders', f);
      const d = reputation.move(f, RISE_REP[Number(rise[1]) - 1] ?? 150, `${m.title} done`, 'you');
      return d > 0 ? `${FACTIONS[f].icon} ${FACTIONS[f].name} +${Math.round(d)}` : null;
    }
    const n = Math.min(PACE.cap, 100 + 50 * Math.max(0, m.objs.length - 1));
    const d = reputation.move(f, n, `${m.title} done`, 'you');
    return d > 0 ? `${FACTIONS[f].icon} ${FACTIONS[f].name} +${Math.round(d)}` : null;
  }

  /** Wire up the night runs. */
  smuggling(s: Smuggling, ride: () => string): void {
    s.payMul = () => {
      const r = reputation.rung('family');
      return (r >= RUNG.sworn ? 1.25 : r >= RUNG.honoured ? 1.1 : 1) * (ride() === 'undertaker' ? 1.25 : 1);
    };
    s.onRun = (_kind, name) => {
      reputation.move('family', 150, `${name} delivered after dark`, 'you');
      // delivered unbusted in the hearse: the false floor did its work
      if (ride() === 'undertaker') deeds.mark('tricks', 'falseFloor');
    };
    s.onBust = (name) => {
      // the bust is a case for the police; the fine paid is restitution
      reputation.move('police', -100, `Caught carrying ${name}`, 'you', false);
      reputation.move('police', 25, 'Paid the fine', 'you', false);
    };
  }

  /** A wallet movement: roads and earthworks are the Brotherhood's work. */
  money(kind: 'in' | 'out' | 'cap', line: string, amount: number): void {
    if (kind !== 'out' || amount <= 0) return;
    if (line === 'roads' || line === 'earthworks') {
      reputation.move('unions', Math.min(PACE.cap, amount * PACE.perDollar), line === 'roads' ? 'Road work paid for' : 'Earthworks paid for', 'you');
    }
  }

  /** Once a frame, cheaply: the day's healing. */
  tick(): void { reputation.tickDay(this.host.day()); }

  // ---- telling the player --------------------------------------------------------------------------

  private rungChanged(f: FactionId, from: number, to: number): void {
    const def = FACTIONS[f];
    const up = to > from;
    const name = RUNGS[to].name;
    // the Factions shelf: every rung ever reached, every faction ever made an enemy of, both sides of a link held at once
    if (to >= RUNG.friend) deeds.mark('facFriend', f);
    if (to >= RUNG.honoured) deeds.mark('facHonoured', f);
    if (to >= RUNG.sworn) deeds.mark('facSworn', f);
    if (to <= RUNG.hostile) deeds.mark('burned', f);
    for (const [a, b] of LINKED) if (reputation.rung(a) >= RUNG.friend && reputation.rung(b) >= RUNG.friend) deeds.mark('bothSides', `${a}|${b}`);
    let line = up
      ? to === RUNG.friend ? `They count you a friend now. ${def.wants}`
        : to === RUNG.honoured ? `Honoured: ${def.honoured}`
          : to === RUNG.sworn ? `Sworn: ${def.sworn}`
            : `You’re ${name.toLowerCase()} with them now.`
      : to <= RUNG.hostile ? `Hostile: ${def.hostile}` : `You’re ${name.toLowerCase()} with them now.`;
    if (up && to >= RUNG.friend) {
      const u = def.unlocks[to - RUNG.friend];
      line += ` · Unlocked: ${u.name}${u.kind === 'job' ? ' paintjob' : ', on sale at any dealer that stocks it'}`;
    }
    this.host.announce(`${def.icon} ${def.name}: ${name}`, line, 7000, true, 'factions');
  }

  /** Console: set a bar outright (testing). */
  set(f: FactionId, n: number): void {
    reputation.rep[f] = n;
    if (n >= 10000) reputation.oath[f] = 5;
    for (let r = RUNG.friend; r <= reputation.rung(f); r++) unlocks.add(FACTIONS[f].unlocks[r - RUNG.friend].id);
    reputation.version++;
    this.host.changed();
  }

  /** Console: everything about the factions in one object. */
  console(): unknown {
    return {
      rep: { ...reputation.rep }, oath: { ...reputation.oath }, unlocks: unlocks.list(), log: reputation.log.slice(0, 10),
      set: (f: FactionId, n: number) => this.set(f, n), unlockAll: () => { for (const id of UNLOCKS.keys()) unlocks.add(id); }, clearUnlocks: () => unlocks.clear(),
    };
  }
}
