import type { Player, SlotRef } from './api';
import { LEGACY_KEY, SLOTS, clearSlot, readSlot, slotKey, slotState } from '../game/save';
import { forgetDeeds } from '../game/deeds';

/**
 * The players of this browser (docs/title.html, "Players and slots"): up to six, each with a name,
 * a colour and three save slots. Stored as one small record; the slots themselves are save.ts's.
 */

const KEY = 'pocket-roads-players';
export const MAX_PLAYERS = 6;
const NAME_MAX = 16;

/** The seventeen vehicle colours, in the order vehicles.ts lists the vehicles. */
export const PLAYER_COLOURS: number[] = [
  0xe2412f, // Tomato
  0x4a6fa5, // Mule
  0x6f9e6b, // Bramble
  0x2bb3a3, // Zippy
  0xf2a93b, // Big Bertha
  0x8e5cc7, // Stomper
  0xf7c5d4, // Sundae
  0x3f9b4a, // Clod
  0xf28c38, // Sandy
  0xf5cf3a, // Pip
  0xf6d04d, // Puddle Duck
  0xf4f2ec, // Splash
  0x2f4d7a, // Breeze
  0x2e4b7a, // Big Blue
  0xa7dcc8, // Marshmallow
  0x3f78c0, // Barnstormer
  0xef6a4c, // Dragonfly
];

interface Roster { players: Player[]; current: string }

function load(): Roster {
  try {
    const text = localStorage.getItem(KEY);
    if (text) {
      const r = JSON.parse(text) as Partial<Roster>;
      const players = Array.isArray(r.players)
        ? r.players.filter((p): p is Player => !!p && typeof p.id === 'string' && typeof p.name === 'string')
        : [];
      return { players, current: typeof r.current === 'string' ? r.current : players[0]?.id ?? '' };
    }
  } catch { /* unreadable or blocked: start over in memory */ }
  return { players: [], current: '' };
}

/** When storage is blocked the roster lives here for the session, so the game still has a player. */
let memory: Roster | null = null;

function get(): Roster {
  const r = load();
  if (r.players.length || !memory) return r;
  return { players: memory.players.map((p) => ({ ...p })), current: memory.current };
}

function put(r: Roster): void {
  memory = { players: r.players.map((p) => ({ ...p })), current: r.current };
  try { localStorage.setItem(KEY, JSON.stringify(r)); } catch { /* kept in memory only */ }
}

const cleanName = (name: string): string => name.trim().replace(/\s+/g, ' ').slice(0, NAME_MAX).trim();

const newId = (): string => `p${Date.now().toString(36)}${Math.floor(Math.random() * 36 ** 4).toString(36).padStart(4, '0')}`;

/** A colour nobody has yet, or any colour when all are taken. */
function freeColour(players: Player[]): number {
  const used = new Set(players.map((p) => p.colour));
  const free = PLAYER_COLOURS.filter((c) => !used.has(c));
  const pool = free.length ? free : PLAYER_COLOURS;
  return pool[Math.floor(Math.random() * pool.length)];
}

/**
 * Move the single save of older builds into this player's slot 1 (or the first free slot), stamp
 * it so Continue finds it, and delete the old key. A save that won't parse is moved as it is, so
 * the slot card can say so rather than it vanishing.
 */
function migrateLegacy(player: Player): void {
  let text: string | null;
  try { text = localStorage.getItem(LEGACY_KEY); } catch { return; }
  if (text === null) return;
  for (const slot of SLOTS) {
    const key = slotKey({ player: player.id, slot });
    try {
      if (localStorage.getItem(key) !== null) continue;
      let out = text;
      try {
        const s = JSON.parse(text) as Record<string, unknown>;
        if (s && typeof s === 'object' && typeof s.saved !== 'number') { s.saved = Date.now(); out = JSON.stringify(s); }
      } catch { /* move it unparsed */ }
      localStorage.setItem(key, out);
      localStorage.removeItem(LEGACY_KEY);
    } catch { /* storage refused: leave the old key where it is and try next boot */ }
    return;
  }
}

export function listPlayers(): Player[] {
  return get().players;
}

/** The player the game is for. Creates "Player 1" if there is nobody, and moves an old save across. */
export function currentPlayer(): Player {
  const r = get();
  let p = r.players.find((q) => q.id === r.current) ?? r.players[0];
  if (!p) {
    const now = Date.now();
    p = { id: newId(), name: 'Player 1', colour: PLAYER_COLOURS[0], created: now, lastPlayed: now };
    r.players.push(p);
  }
  r.current = p.id;
  put(r);
  migrateLegacy(r.players[0]);
  return p;
}

export function setCurrentPlayer(id: string): void {
  const r = get();
  if (!r.players.some((p) => p.id === id)) return;
  r.current = id;
  put(r);
}

/**
 * Add a player. The name is trimmed to 16 characters, and an empty one becomes "Player N"; the
 * colour defaults to one nobody has. Throws an Error (message fit to show) when there are already six.
 */
export function addPlayer(name: string, colour?: number): Player {
  const r = get();
  if (r.players.length >= MAX_PLAYERS) throw new Error(`Six players is the most one browser keeps.`);
  let n = cleanName(name);
  if (!n) {
    let i = r.players.length + 1;
    while (r.players.some((p) => p.name === `Player ${i}`)) i++;
    n = `Player ${i}`;
  }
  const now = Date.now();
  const p: Player = { id: newId(), name: n, colour: colour ?? freeColour(r.players), created: now, lastPlayed: 0 };
  r.players.push(p);
  if (!r.current) r.current = p.id;
  put(r);
  return p;
}

/** Rename; an empty name leaves the old one. */
export function renamePlayer(id: string, name: string): void {
  const n = cleanName(name);
  if (!n) return;
  const r = get();
  const p = r.players.find((q) => q.id === id);
  if (!p) return;
  p.name = n;
  put(r);
}

export function recolourPlayer(id: string, colour: number): void {
  const r = get();
  const p = r.players.find((q) => q.id === id);
  if (!p) return;
  p.colour = colour;
  put(r);
}

/** Remove a player and their three saves. If they were current, the next player is. */
export function removePlayer(id: string): void {
  const r = get();
  const i = r.players.findIndex((p) => p.id === id);
  if (i < 0) return;
  for (const slot of SLOTS) clearSlot({ player: id, slot });
  forgetDeeds(id);
  r.players.splice(i, 1);
  if (r.current === id) r.current = r.players[Math.min(i, r.players.length - 1)]?.id ?? '';
  put(r);
}

/** A name the game gave, not one somebody chose: "Player 1", "Player 2"... */
const generic = (name: string): boolean => /^Player \d+$/.test(name);

/**
 * Signed in online as `name`: from now on this browser plays as the player of that name, whose
 * achievements, stamps, faction unlocks and bookmarks are kept under their id. An existing player
 * of that name is switched to; an untouched "Player N" the game made (no saves) is renamed;
 * otherwise one is made (quietly, with a colour nobody has).
 * Never another named player, renamed or played on: a second account signed in on the same browser
 * took the first one's shelf that way (the user, 5 Nov 2026: a brand-new "Joe" had Jack's Honoured
 * faction vehicles unlocked, and the next save sent them up to Joe's career).
 * `renamed`: the account itself was just renamed (a one-click fleet kept under a name), so the
 * player playing it is renamed with it, mid-game, and keeps what it has.
 */
export function adoptOnlineName(name: string, renamed = false): Player {
  const cur = currentPlayer();
  const n = cleanName(name);
  if (!n || cur.name.toLowerCase() === n.toLowerCase()) return cur;
  if (renamed) { renamePlayer(cur.id, n); touchPlayer(cur.id); return currentPlayer(); }
  const r = get();
  const known = r.players.find((p) => p.name.toLowerCase() === n.toLowerCase());
  if (known) { setCurrentPlayer(known.id); touchPlayer(known.id); return known; }
  // a "Player N" the game made and nobody has saved a game as is simply that player, renamed: no
  // leftover Player 1 beside them; one with saves of its own keeps them, and a new player is made
  const untouched = (id: string) => SLOTS.every((slot) => slotState({ player: id, slot }).state === 'empty');
  if (generic(cur.name) && untouched(cur.id)) { renamePlayer(cur.id, n); touchPlayer(cur.id); return currentPlayer(); }
  // six here already: the longest unplayed goes (one with no saves first). Online, what it kept is a
  // copy of its career's on the server, which comes back the next time that name signs in.
  if (r.players.length >= MAX_PLAYERS) {
    const others = r.players.filter((p) => p.id !== cur.id).sort((a, b) => (a.lastPlayed || 0) - (b.lastPlayed || 0));
    const gone = others.find((p) => untouched(p.id)) ?? others[0];
    if (gone) removePlayer(gone.id);
  }
  const p = addPlayer(n);
  setCurrentPlayer(p.id);
  touchPlayer(p.id);
  return p;
}

export function touchPlayer(id: string): void {
  const r = get();
  const p = r.players.find((q) => q.id === id);
  if (!p) return;
  p.lastPlayed = Date.now();
  put(r);
}

/**
 * What Continue loads: the most recently saved loadable slot of the most recently played player,
 * or failing that the most recently saved loadable slot of anyone. Null when there is nothing.
 */
export function mostRecent(): SlotRef | null {
  const players = [...get().players].sort((a, b) => (b.lastPlayed || 0) - (a.lastPlayed || 0));
  const best = (ids: string[]): SlotRef | null => {
    let out: SlotRef | null = null, at = -1;
    for (const player of ids) {
      for (const slot of SLOTS) {
        const s = readSlot({ player, slot });
        if (s && (s.saved ?? 0) > at) { at = s.saved ?? 0; out = { player, slot }; }
      }
    }
    return out;
  };
  if (!players.length) return null;
  return best([players[0].id]) ?? best(players.map((p) => p.id));
}
