export interface Draft {
  /** `why` is the card's up-to-three lines; `details` the story behind "More details", before the how-to. */
  title: string; why: string; details?: string; giver: Giver; hero: HeroSpec; caption: string; objs: Obj[]; reward: Reward[];
  /** A deadline, in game hours from when it is taken; none for races, tows and trips. */
  hours?: number;
  /** A story step bound in its helicopter, boat or submarine form (story/kit.ts formIn): only that kind can take it. */
  form?: 'heli' | 'boat' | 'sub';
  /** The mission's notes to start with: an act's ride's deadline on the clock (`by`) and what it carries (missions/actTemplates.ts). */
  notes?: Record<string, number>;
}

type TownPick = { w: World; t: Town };

export interface Template {
  id: string;
  thread: Thread;
  also?: Thread;
  kind: Kind;
  /** The arc it is a step of. */
  arc?: string;
  /** Offered by thread hunger when there is room. */
  side?: boolean;
  /** A town's ladder: offered by a town whose standing is this. */
  ladder?: number;
  /** Hours before it may be offered again once done (a side job that repeats). */
  cooldown?: number;
  /** Why it can't be offered at all now, or null. */
  gate(c: MissionCtx, ms: Missions, town?: TownPick): string | null;
  bind(c: MissionCtx, h: number, ms: Missions, town?: TownPick): Draft | null;
}

// ---- finding things -------------------------------------------------------------------------------

export const townRef = (w: World, t: Town): TownRef => ({ cell: [w.cx, w.cz], id: t.id, name: plainTown(t.name) });

/** The town's square: the road tile nearest its middle, in world tiles. */
export function squareOf(w: World, t: Town, name = 'the square'): PlaceRef {
  const cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2;
  let best = -1, bestD = Infinity;
  for (let z = t.z0; z < t.z0 + t.size; z++) {
    for (let x = t.x0; x < t.x0 + t.size; x++) {
      if (!inB(x, z)) continue;
      const i = idx(x, z);
      if (!w.road[i] || w.blocked[i] || w.deckAxis[i]) continue;
      const d = Math.hypot(x + 0.5 - cx, z + 0.5 - cz);
      if (d < bestD) { bestD = d; best = i; }
    }
  }
  const x = best >= 0 ? (best % N) + 0.5 : cx, z = best >= 0 ? Math.floor(best / N) + 0.5 : cz;
  return { x: w.ox + x, z: w.oz + z, cell: [w.cx, w.cz], name };
}

/** Every town in memory, nearest the player first. */
export function townsNear(c: MissionCtx, max = 300): TownPick[] {
  const out: (TownPick & { d: number })[] = [];
  for (const w of c.worlds) {
    for (const t of w.towns) {
      const d = Math.hypot(w.ox + t.x0 + t.size / 2 - c.at.x, w.oz + t.z0 + t.size / 2 - c.at.z);
      if (d <= max) out.push({ w, t, d });
    }
  }
  return out.sort((a, b) => a.d - b.d);
}

export const siteRef = (s: Site): SiteRef => ({ x: s.x, z: s.z, cell: [s.w.cx, s.w.cz], name: shortSite(String(s.kind), s.port >= 0, s.major), kind: String(s.kind) });
const inTown = (s: Site, w: World, t: Town) => s.w === w && s.lx >= t.x0 - 4 && s.lx <= t.x0 + t.size + 4 && s.lz >= t.z0 - 4 && s.lz <= t.z0 + t.size + 4;

interface PairSpec { types: string[]; fromTown?: boolean; toTown?: boolean; fromKinds?: string[]; toKinds?: string[]; to?: Site }

/** One delivery for a town: a cargo it has both ends of, near it, that the player can reach. */
function pair(c: MissionCtx, spec: PairSpec, w: World, t: Town, used: Set<Site>): { type: CargoType; from: Site; to: Site; value: number } | null {
  const mid = { x: w.ox + t.x0 + t.size / 2, z: w.oz + t.z0 + t.size / 2 };
  const near = (s: Site) => Math.hypot(s.x - mid.x, s.z - mid.z);
  for (const id of spec.types) {
    const type = cargoById(id);
    // long-haul and Ultra-Bulk work have their own spawners and prices: never a town's errand
    if (!type || type.heli || type.sub || type.longHaul || type.ultra) continue;
    let froms = c.sites(type.from as string[]);
    let tos = spec.to ? (type.to.includes(spec.to.kind) ? [spec.to] : []) : c.sites(type.to as string[]);
    if (spec.fromKinds) froms = froms.filter((s) => spec.fromKinds!.includes(String(s.kind)));
    if (spec.toKinds) tos = tos.filter((s) => spec.toKinds!.includes(String(s.kind)));
    if (spec.fromTown) froms = froms.filter((s) => inTown(s, w, t));
    if (spec.toTown && !spec.to) tos = tos.filter((s) => inTown(s, w, t));
    froms = froms.filter((s) => !used.has(s) && near(s) < 130).sort((a, b) => near(a) - near(b)).slice(0, 8);
    tos = tos.filter((s) => !used.has(s) && near(s) < 130).sort((a, b) => near(a) - near(b)).slice(0, 8);
    for (const from of froms) {
      for (const to of tos) {
        if (to === from || spanOf(from, to) < 6) continue;
        if (to.port >= 0 && from.port >= 0 && to.port === from.port) continue;
        const fit = offerable(c.def, c.at, from, to, type, true);
        if (!fit.ok || !fit.urgency) continue;
        return { type, from, to, value: valueOf(type, fit.dist, fit.urgency, fit.seconds) };
      }
    }
  }
  return null;
}

/** The objective line for a delivery: "🥖 Bread → Grocery", shortened to fit. */
function deliverObj(p: { type: CargoType; from: Site; to: Site; value: number }, n = 1): Obj {
  const to = siteRef(p.to);
  let label = `${n > 1 ? `${n}× ` : ''}${p.type.name} → ${to.name}`;
  if (label.length > 28) label = `${p.type.name} → ${to.name.split(' ')[0]}`;
  if (label.length > 28) label = `Deliver ${p.type.name.toLowerCase()}`.slice(0, 28);
  return { t: 'deliver', label, icon: p.type.icon, cargo: p.type.id, from: siteRef(p.from), to, n, value: p.value };
}

/** A building's hero: itself, in its town's style. */
const buildingHero = (b: Building, arch: Arch): HeroSpec => ({ kind: 'building', b: b.kind, arch, w: b.w, d: b.d, floors: b.floors });

/** The biggest ordinary building of a town that nobody owns: what the town gives away. */
function giftOf(c: MissionCtx, w: World, t: Town, not?: Building): Building | null {
  const trade = new Set(CARGO.flatMap((q) => [...q.from, ...q.to]).map(String));
  return t.buildings.filter((b) => !b.gone && b.solid && b.uid >= 0 && b !== not && !c.owns(w, b.uid) && trade.has(b.kind) && b.kind !== 'cityHall')
    .sort((a, b) => b.w * b.d * b.floors - a.w * a.d * a.floors)[0] ?? null;
}

const bref = (w: World, b: Building, name: string) => ({ cell: [w.cx, w.cz] as [number, number], uid: b.uid, kind: b.kind, name });
export const cap = (s: string) => s[0].toUpperCase() + s.slice(1);
const r10 = (v: number) => Math.round(v / 10) * 10;

/** The rival's car as a vehicle hero. */
const rivalHero = (id: string, tier: 1 | 2 | 3): HeroSpec => { const r = rivalById(id); return { kind: 'vehicle', model: rivalModel(r, tier), parts: rivalParts(r, tier) }; };
const modelName = (id: string) => ALL_VEHICLES.find((v) => v.id === id)?.name ?? id;

/**
 * A finish line far off: a wonder, a named landform, another town or a harbour, 100–380 tiles from the
 * start on the islands in memory, that this rival's car can actually get to. Wonders first, since a race
 * to a pyramid is a better story than a race to a dock, and longer before shorter.
 */
function finishFor(c: MissionCtx, from: PlaceRef, h: number, def: LandDef): PlaceRef | null {
  const cands: { p: PlaceRef; score: number }[] = [];
  const far = (x: number, z: number) => Math.hypot(x - from.x, z - from.z);
  const ok = (x: number, z: number) => { const d = far(x, z); return d >= 100 && d <= 380; };
  for (const w of c.worlds) {
    for (const g of w.works) {
      if (g.kind !== 'wonder') continue;
      // the finish is at the wonder's gate, where a road runs to it
      const gate = g.gate >= 0 ? { x: w.ox + (g.gate % N) + 0.5, z: w.oz + Math.floor(g.gate / N) + 0.5 } : { x: w.ox + g.x, z: w.oz + g.z };
      if (ok(gate.x, gate.z)) cands.push({ p: { ...gate, cell: [w.cx, w.cz], name: cap(g.name) }, score: 4 });
    }
    for (const l of w.landmarks) {
      if (!LANDFORM_LABEL[l.kind] || !l.name) continue;
      const i = roadNear(w, l.x, l.z, Math.min(24, Math.max(6, l.r)));
      if (i < 0) continue;
      const x = w.ox + (i % N) + 0.5, z = w.oz + Math.floor(i / N) + 0.5;
      if (ok(x, z)) cands.push({ p: { x, z, cell: [w.cx, w.cz], name: l.name }, score: 3 });
    }
    for (const t of w.towns) {
      const sq = squareOf(w, t, plainTown(t.name));
      if (ok(sq.x, sq.z)) cands.push({ p: sq, score: t.kind === 'city' || t.kind === 'metro' || t.kind === 'mega' ? 2 : 1 });
    }
  }
  if (!cands.length) return null;
  // the best kind of place first, the longer run first within it, and the hash to vary it
  cands.sort((a, b) => b.score - a.score || far(b.p.x, b.p.z) - far(a.p.x, a.p.z));
  const worldAt = (cx: number, cz: number) => c.worlds.find((w) => w.cx === cx && w.cz === cz) ?? null;
  // one flood tells which of them the rival's car can get to at all; the full line is planned at the start
  const top = cands.slice(0, 24);
  const ok2 = reachAmong(worldAt, def, from.x, from.z, top.map((q) => q.p));
  const good = top.filter((_, k) => ok2[k]);
  if (!good.length) return null;
  const best = good.filter((q) => q.score === good[0].score);
  return best[h % Math.min(3, best.length)].p;
}

/** A heavy road vehicle's stats, for asking where a tow can go: nothing a lorry couldn't drag it over. */
const TOW_DEF = (ALL_VEHICLES.find((v) => v.id === 'bertha') ?? ALL_VEHICLES[0]) as LandDef;

/**
 * Where a load can be dragged from `from`: every tile a lorry could cross that is dry and is not a
 * bridge deck (no span in the county was built for a church bell). Flooded once per bind.
 */
export function towable(w: World, fromTile: number, limit = 9000): Map<number, number> {
  const seen = new Map<number, number>([[fromTile, 0]]);
  const q = [fromTile];
  while (q.length && seen.size < limit) {
    const a = q.shift()!;
    const ax = a % N, az = (a - ax) / N;
    for (let d = 0; d < 4; d++) {
      const bx = ax + DIRS[d][0], bz = az + DIRS[d][1];
      if (!inB(bx, bz)) continue;
      const b = idx(bx, bz);
      if (seen.has(b) || w.deckAxis[b] || waterDepth(w, b) > 0 || w.blocked[b]) continue;
      if (!canCross(w, a, d, TOW_DEF)) continue;
      seen.set(b, seen.get(a)! + 1);
      q.push(b);
    }
  }
  return seen;
}

/** A clear road tile near (x, z) in w's own tiles, for a load to sit on. */
export function roadNear(w: World, x: number, z: number, r = 8): number {
  let best = -1, bestD = Infinity;
  for (let dz = -r; dz <= r; dz++) {
    for (let dx = -r; dx <= r; dx++) {
      const tx = Math.floor(x) + dx, tz = Math.floor(z) + dz;
      if (!inB(tx, tz) || tx < 3 || tz < 3 || tx > N - 4 || tz > N - 4) continue;
      const i = idx(tx, tz);
      if (!w.road[i] || w.blocked[i] || w.deckAxis[i] || waterDepth(w, i) > 0) continue;
      const d = Math.hypot(dx, dz);
      if (d < bestD) { bestD = d; best = i; }
    }
  }
  return best;
}

/**
 * A tow: the load on a road near `from`, and a place to take it `lo`–`hi` tiles away that a lorry
 * could drag it to without a bridge or a ford. The places a town would want it, first.
 */
function towRoute(w: World, fx: number, fz: number, targets: { x: number; z: number; name: string }[], lo: number, hi: number): { from: PlaceRef; to: PlaceRef } | null {
  const a = roadNear(w, fx, fz);
  if (a < 0) return null;
  const reach = towable(w, a);
  const ax = a % N, az = Math.floor(a / N);
  for (const tg of targets) {
    const b = roadNear(w, tg.x, tg.z, 6);
    if (b < 0 || !reach.has(b)) continue;
    const bx = b % N, bz = Math.floor(b / N);
    const straight = Math.hypot(bx - ax, bz - az);
    const walked = reach.get(b)!;
    if (straight < lo || straight > hi || walked > straight * 2.2) continue;
    return {
      from: { x: w.ox + ax + 0.5, z: w.oz + az + 0.5, cell: [w.cx, w.cz], name: 'the load' },
      to: { x: w.ox + bx + 0.5, z: w.oz + bz + 0.5, cell: [w.cx, w.cz], name: tg.name },
    };
  }
  return null;
}

const crewed = (c: MissionCtx) => c.units.filter((u) => u.crew && u.land).length;
const arcAt = (ms: Missions, arc: string, id: string) => (ms.arcs.get(arc) ?? 0) === ARCS.find((a) => a.id === arc)!.tpls.indexOf(id);

