/** What a town sells or builds with, for its errands. */
const SHOPS = ['grocery', 'store', 'generalStore', 'marketSquare', 'marketHall', 'farmShop', 'departmentStore', 'souk', 'bigBox', 'diner', 'cafe', 'bakery'];
const WORKS = ['sawmill', 'warehouse', 'logisticsDepot', 'garage', 'factory', 'brewery', 'shop', 'store', 'grocery'];

interface Ladder {
  id: string; level: number; title: string; why: string; steps: PairSpec[]; effect: Extract<Reward, { r: 'effect' }>['effect']; effectLine: string;
  needsBlight?: boolean; needsPort?: boolean; needsGraduation?: boolean;
}

