// ---- Something Fast: the car arc, and the rivals ---------------------------------------------------

/** The mechanic's garage: a garage or a gas station in the nearest town, as a site. */
function garageOf(c: MissionCtx): { w: World; t: Town; site: Site } | null {
  // a town with no garage: the mechanic works out of the back of its store
  for (const kinds of [['garage', 'gas'], ['store', 'generalStore', 'shop', 'grocery', 'warehouse']]) {
    for (const { w, t } of townsNear(c, 200)) {
      const s = c.sites(kinds).find((q) => inTown(q, w, t));
      if (s) return { w, t, site: s };
    }
  }
  return null;
}

/**
 * The first-drive tutorial's plan (game/tutorial.ts): the road tile the goods wait on and the town the
 * auto shop is in. Set by the tutorial just before it offers the first job; no other template reads it,
 * and the first job is never offered without it.
 */
let firstPlan: { pickup: { x: number; z: number; cell: [number, number] }; town: number } | null = null;
export function setFirstPlan(p: typeof firstPlan): void { firstPlan = p; }

/** The auto shop of the first job's town: its garage, else its filling station, else a store. */
function autoShopOf(c: MissionCtx, w: World, t: Town): Site | null {
  // the county's own Auto Shop, whose ring is the same door, when it stands in this town
  const own = c.sites(['garage']).find((q) => inTown(q, w, t) && q.b?.storefront === 'shop');
  if (own) return own;
  for (const kinds of [['garage'], ['gas'], ['carDealership'], ['store', 'generalStore', 'shop', 'grocery']]) {
    const s = c.sites(kinds).filter((q) => inTown(q, w, t))
      .sort((a, b) => Math.hypot(a.x - firstPlan!.pickup.x, a.z - firstPlan!.pickup.z) - Math.hypot(b.x - firstPlan!.pickup.x, b.z - firstPlan!.pickup.z))[0];
    if (s) return s;
  }
  return null;
}

