/** The first job's Auto Shop and its town, found from that finished job (or, headless, the first drive's plan). */
function firstShop(c: MissionCtx, ms: Missions): { w: World; t: Town; shop: SiteRef; mech: string } | null {
  const m = (ms.list ?? []).find((q) => q.tpl === 'first:parts');
  const o = m?.objs[0];
  if (m && m.giver.town && o && o.t === 'deliver') {
    const tr = m.giver.town;
    const w = c.worlds.find((q) => q.cx === tr.cell[0] && q.cz === tr.cell[1]);
    const t = w?.towns[tr.id];
    if (w && t) return { w, t, shop: o.to, mech: m.giver.name.replace(/ the mechanic$/, '') };
  }
  const plan = firstPlan;
  if (!plan) return null;
  const w = c.worlds.find((q) => q.cx === plan.pickup.cell[0] && q.cz === plan.pickup.cell[1]);
  const t = w?.towns[plan.town];
  const s = w && t ? autoShopOf(c, w, t) : null;
  return w && t && s ? { w, t, shop: { ...siteRef(s), name: 'the Auto Shop' }, mech: personName(`mech|${t.name}`).split(' ')[0] } : null;
}

/**
 * The handbrake's and the drift's shop (game/driftLessons.ts, offered long after the first drive since 8 Nov 2026):
 * the first job's, or for a game without one (the tutorial skipped) the nearest town's garage, filling station or
 * car dealer to the player.
 */
function lessonShop(c: MissionCtx, ms: Missions): { w: World; t: Town; shop: SiteRef; mech: string } | null {
  const f = firstShop(c, ms);
  if (f) return f;
  const sites = c.sites(['garage', 'gas', 'carDealership']);
  for (const { w, t } of townsNear(c, 200)) {
    const s = sites.filter((q) => inTown(q, w, t)).sort((a, b) => Math.hypot(a.x - c.at.x, a.z - c.at.z) - Math.hypot(b.x - c.at.x, b.z - c.at.z))[0];
    if (s) return { w, t, shop: { ...siteRef(s), name: 'the Auto Shop' }, mech: personName(`mech|${t.name}`).split(' ')[0] };
  }
  return null;
}

/** The speed the nitrous mission asks for: past anything the car makes flat out on the best road, within reach of one bottle. */
export const nitrousTarget = (top: number): number => Math.floor(top * 12 * 1.25 * 1.07);

/** The friend's first name, never the same as the first mechanic's. */
function friendName(t: Town, not: string): string {
  const a = personName(`mech|${t.name}`).split(' ')[0];
  return a !== not ? a : personName(`friend|${t.name}`).split(' ')[0];
}

/**
 * The friend's Auto Shop: a garage (or filling station, or car dealer) in another town, ideally 50–100
 * tiles from the first one by the roads of the same county, so the arrows can lead the whole way.
 */
function friendShop(c: MissionCtx, from: { w: World; t: Town; shop: SiteRef }): { w: World; t: Town; site: Site; far: number } | null {
  const cands: { w: World; t: Town; site: Site; far: number; score: number }[] = [];
  const sites = c.sites(['garage', 'gas', 'carDealership']);
  for (const w of c.worlds) {
    for (const t of w.towns) {
      if (w === from.w && t === from.t) continue;
      const site = sites.filter((s) => inTown(s, w, t)).sort((a, b) => Math.hypot(a.x - from.shop.x, a.z - from.shop.z) - Math.hypot(b.x - from.shop.x, b.z - from.shop.z))[0];
      if (!site) continue;
      const far = Math.hypot(site.x - from.shop.x, site.z - from.shop.z);
      if (far < 30 || far > 220) continue;
      const out = far < 50 ? 50 - far : far > 100 ? far - 100 : 0;
      const score = out * 2 + (w === from.w ? 0 : 60) - (t.kind === 'city' || t.kind === 'metro' || t.kind === 'mega' ? 8 : 0) + Math.abs(far - 75) * 0.1;
      cands.push({ w, t, site, far, score });
    }
  }
  cands.sort((a, b) => a.score - b.score);
  // the first that the roads of this county join to the first shop within FIRST_DRIVE_MAX road tiles (the
  // user, 7 Oct 2026: a new player's first drive never sends them further); the start was chosen so one does
  for (const q of cands) {
    if (q.w !== from.w || q.far > FIRST_DRIVE_MAX) continue;
    const r = roadRoute(q.w, from.shop.x - q.w.ox, from.shop.z - q.w.oz, q.site.lx, q.site.lz);
    if (r && r.length - 1 <= FIRST_DRIVE_MAX) return q;
  }
  // a start from before the rule: the nearest by the score that is no further as the crow flies, or the best there is
  return cands.find((q) => q.far <= FIRST_DRIVE_MAX) ?? cands[0] ?? null;
}

