// ---- the helping hand: a second load that needs a second car, and with it the first driver ------------

/**
 * A Helping Hand (docs/helpinghand.html, the user, 1 Nov 2026): right after the nitrous bet, the woman who runs
 * the Auto Shop's deliveries has an order that is two Tomato-loads. Both lie on the road ahead; the player's car
 * takes one and hers, tucked in behind in Follow mode, takes the other (`deliver.also` + `with: 1`). She joins the
 * fleet the moment the card is accepted (missions/wire.ts joinHand) and says so at the door.
 */
/**
 * Where the order goes: a garage, dealer, filling station or shop, HAND_MIN–HAND_MAX road tiles from the car, as
 * near HAND_AIM as there is (the user, 2 Nov 2026: at least 50 tiles, up to 200; the old 25–60 was too short).
 */
const HAND_DROPS = ['garage', 'carDealership', 'gas', 'store', 'generalStore', 'shop', 'grocery'];
const HAND_MIN = 50, HAND_MAX = 200, HAND_AIM = 90;
/** As the crow flies, the furthest door looked at, and the distance the likeliest doors are sorted round. */
const HAND_FAR_CROW = 170, HAND_CROW_AIM = 65;
/** The player's share of her load. */
export const HAND_SHARE = 0.4;
/** The goods' spot, set by the tutorial from where the car faces when the card comes up (as the first job's is). */
let handPlan: { pickup: { x: number; z: number; cell: [number, number] } } | null = null;
export function setHandPlan(p: typeof handPlan): void { handPlan = p; }
/**
 * The hand's name: a woman's from the book, drawn at random when her card is first made (the user, 2 Nov 2026: no
 * two players should share their first driver). Not from the world seed: every online fleet shares the seed
 * "online". The card and her driver are saved, so she keeps the name.
 */
export const handName = (seed: string): string => womanName(`hand|${seed}|${Math.floor(Math.random() * 1e9)}`);
/** The town a site stands in, or null. */
function townOfSite(s: Site): Town | null {
  const id = s.w.townId[Math.floor(s.lz) * N + Math.floor(s.lx)];
  return id >= 0 ? s.w.towns[id] ?? null : null;
}

/** The drop for the order: by road from where the goods wait, another town's door before the same town's. */
function handDrop(c: MissionCtx, f: { w: World; t: Town; shop: SiteRef }, from: { lx: number; lz: number; x: number; z: number }): { site: Site; route: number[] } | null {
  const w = c.at.w;
  // the likeliest first (as the crow flies near the middle of the range), each measured by road
  const cands = c.sites(HAND_DROPS)
    .filter((s) => s.w === w && !s.quay && Math.hypot(s.x - f.shop.x, s.z - f.shop.z) > 2)
    .map((s) => ({ s, crow: Math.hypot(s.x - from.x, s.z - from.z), other: townOfSite(s) !== f.t }))
    .filter((q) => q.crow >= 12 && q.crow <= HAND_FAR_CROW)
    .sort((a, b) => Math.abs(a.crow - HAND_CROW_AIM) - Math.abs(b.crow - HAND_CROW_AIM))
    .slice(0, 64);
  const measured = cands.map((q) => ({ ...q, r: roadRoute(w, from.lx, from.lz, q.s.lx, q.s.lz) })).filter((q) => !!q.r);
  // only inside the range; another town's door beats one in the same town; then nearest the aim. None, and the
  // hand isn't offered (the friend's handbrake comes next)
  let best: { site: Site; route: number[] } | null = null, bs = Infinity;
  for (const q of measured) {
    const len = q.r!.length - 1;
    if (len < HAND_MIN || len > HAND_MAX) continue;
    const s = (q.other ? 0 : 10) + Math.abs(len - HAND_AIM) * 0.2;
    if (s < bs) { bs = s; best = { site: q.s, route: q.r! }; }
  }
  return best;
}

