/** A race: meet the rival on a town's square, then first to the finish. */
function raceTemplate(id: string, rival: string, tier: 1 | 2 | 3, o: { arc?: string; side?: boolean; stage?: number; title: string; why: (to: string) => string; reward: (c: MissionCtx) => Reward[]; after?: string[] }): Template {
  return {
    id, thread: 'car', also: tier === 3 ? 'fleet' : undefined, kind: 'race', arc: o.arc, side: o.side, cooldown: o.side ? 72 : undefined,
    gate(c, ms) {
      if (c.def.kind !== 'land') return 'road cars only';
      if (o.arc && !arcAt(ms, o.arc, id)) return 'not yet';
      if (o.stage !== undefined && c.stage < o.stage) return 'later';
      if (o.after && !o.after.some((r) => ms.beaten.has(r))) return 'beat someone first';
      if (tier === 3 && ms.done.get(id)) return 'already won';
      return null;
    },
    bind(c, h) {
      const towns = townsNear(c, 160);
      if (!towns.length) return null;
      const r = rivalById(rival);
      const { w, t } = towns[h % Math.min(2, towns.length)];
      const from = squareOf(w, t, 'the start line');
      const to = finishFor(c, from, h, applyParts(ALL_VEHICLES.find((v) => v.id === rivalModel(r, tier))!, rivalParts(r, tier)) as LandDef);
      if (!to) return null;
      const label = `Race to ${to.name}`;
      return {
        title: o.title, why: o.why(to.name).length <= 130 ? o.why(to.name) : o.why('the finish'),
        giver: { who: 'rival', name: r.name, at: from, town: townRef(w, t) },
        hero: rivalHero(rival, tier), caption: `${r.short}’s ${modelName(rivalModel(r, tier))}`,
        objs: [
          { t: 'reach', label: `Meet ${r.short} at the square`, icon: '🏁', at: from, r: 5 },
          { t: 'race', label: label.length <= 28 ? label : 'Race to the finish', icon: '🏎️', rival, tier, from, to },
        ],
        reward: o.reward(c),
      };
    },
  };
}

