/** The widest water a bridge lesson asks for: a two-lane road's deck reaches 12, the abutments take the rest. */
const LESSON_GAP = [3, 10] as const;
/** How far from the player a lesson's site may be, tiles. */
const LESSON_NEAR = 90;

/**
 * Water worth bridging near the player, for the bridge lesson: land a road comes near on both banks, 3 to 10
 * tiles of water straight across, no deck over it yet, and the way round by road at least three times as
 * long (or none at all). The nearest river crossing, else the nearest over other water (a lake, the sea), or
 * null (the user, 28 Oct 2026: a player was sent to bridge a lake with a river near).
 */
export function bridgeSite(c: MissionCtx): { w: World; a: number; b: number; gap: number; river: boolean; mid: PlaceRef } | null {
  const w = c.at.w, px = Math.floor(c.at.lx), pz = Math.floor(c.at.lz);
  const land = (i: number) => w.water[i] < 0 && !w.blocked[i];
  const cands: { a: number; b: number; gap: number; d: number; river: boolean }[] = [];
  for (let z = Math.max(6, pz - LESSON_NEAR); z <= Math.min(N - 7, pz + LESSON_NEAR); z += 2) {
    for (let x = Math.max(6, px - LESSON_NEAR); x <= Math.min(N - 7, px + LESSON_NEAR); x += 2) {
      const a = idx(x, z);
      if (!land(a) || roadNear(w, x, z, 3) < 0) continue;
      for (const [dx, dz] of [DIRS[0], DIRS[1]]) {
        let k = 1, river = false;
        while (k <= LESSON_GAP[1] + 1 && inB(x + dx * k, z + dz * k)) {
          const i = idx(x + dx * k, z + dz * k);
          if (w.water[i] < 0 || w.deckAxis[i] || w.road[i] || waterDepth(w, i) <= 0) break;
          if (w.flags[i] & (Flag.River | Flag.Stream)) river = true;
          k++;
        }
        const gap = k - 1, bx = x + dx * k, bz = z + dz * k;
        if (gap < LESSON_GAP[0] || gap > LESSON_GAP[1] || bx < 6 || bz < 6 || bx > N - 7 || bz > N - 7) continue;
        const b = idx(bx, bz);
        if (!land(b) || roadNear(w, bx, bz, 3) < 0) continue;
        cands.push({ a, b, gap, river, d: Math.hypot(x + (dx * k) / 2 - px, z + (dz * k) / 2 - pz) });
      }
    }
  }
  cands.sort((p, q) => p.d - q.d);
  // a river first, then any water; and the way round by road: a crossing beside an existing bridge saves nothing
  for (const river of [true, false]) {
    for (const s of cands.filter((q) => q.river === river).slice(0, 10)) {
      const route = roadRoute(w, s.a % N, Math.floor(s.a / N), s.b % N, Math.floor(s.b / N));
      if (route && route.length < s.gap * 3 + 25) continue;
      // and the builder's own road, bank to bank, must bridge: where it would go round by land instead, no
      // bridge is ever built and the step can't be done (the user, 29 Oct 2026)
      if (!builderBridges(w, s.a, s.b)) continue;
      const mx = ((s.a % N) + (s.b % N)) / 2 + 0.5, mz = (Math.floor(s.a / N) + Math.floor(s.b / N)) / 2 + 0.5;
      return { w, a: s.a, b: s.b, gap: s.gap, river, mid: { x: w.ox + mx, z: w.oz + mz, cell: [w.cx, w.cz], name: river ? 'the river to bridge' : 'the water to bridge' } };
    }
  }
  return null;
}

/** Whether the builder's default road (two-lane, Shortest viable) from bank `a` to bank `b` crosses the water rather than going round. */
function builderBridges(w: World, a: number, b: number): boolean {
  // a whole cell's route plan is a few hundred ms: worked out once a site for as long as the island stands as it is
  const key = `${w.cx},${w.cz},${w.revision},${a},${b}`;
  const known = bridgesKnown.get(key);
  if (known !== undefined) return known;
  const plan = planRoutes(w, a, shapeOf(RoadType.TwoLane), 'short', ROAD_INFO[RoadType.TwoLane].span);
  const nodes = routeTo(plan, b);
  let ok = false;
  for (let k = 1; nodes && k < nodes.length && !ok; k++) {
    const d = Math.abs(nodes[k] - nodes[k - 1]);
    ok = (d !== 1 && d !== N) || w.water[nodes[k]] >= 0;   // a leap over what lies between, or a deck tile
  }
  if (bridgesKnown.size > 200) bridgesKnown.clear();
  bridgesKnown.set(key, ok);
  return ok;
}
const bridgesKnown = new Map<string, boolean>();

/** A lot's side, tiles: the terrain lesson's patch is LOT x LOT. */
export const LOT = 4;

/**
 * Rough ground near the player, for the terrain lesson: a LOT x LOT patch of open country the terrain tool may
 * dig (no building, road, rail, water or town land), 2 to 5 steps from its lowest corner to its highest. Null
 * when there is none.
 */
export function roughLot(c: MissionCtx): { w: World; x0: number; z0: number; at: PlaceRef } | null {
  const w = c.at.w, px = Math.floor(c.at.lx), pz = Math.floor(c.at.lz);
  const fixed = fixedMask(w);
  let best: { x0: number; z0: number; d: number } | null = null;
  for (let z0 = Math.max(4, pz - 70); z0 <= Math.min(N - 4 - LOT, pz + 70); z0 += 3) {
    for (let x0 = Math.max(4, px - 70); x0 <= Math.min(N - 4 - LOT, px + 70); x0 += 3) {
      const d = Math.hypot(x0 + LOT / 2 - px, z0 + LOT / 2 - pz);
      if (d < 8 || (best && d >= best.d)) continue;
      let lo = Infinity, hi = -Infinity, ok = true;
      for (let z = z0; z < z0 + LOT && ok; z++) {
        for (let x = x0; x < x0 + LOT; x++) {
          const i = idx(x, z);
          if (fixed[i] || w.water[i] >= 0 || w.road[i] || w.rail[i] || w.blocked[i] || w.deckAxis[i] || w.townId[i] >= 0 || steepness(w, i) > 3) { ok = false; break; }
          lo = Math.min(lo, minCorner(w, i));
          hi = Math.max(hi, maxCorner(w, i));
        }
      }
      if (ok && hi - lo >= 2 && hi - lo <= 5) best = { x0, z0, d };
    }
  }
  if (!best) return null;
  return { w, x0: best.x0, z0: best.z0, at: { x: w.ox + best.x0 + LOT / 2, z: w.oz + best.z0 + LOT / 2, cell: [w.cx, w.cz], name: 'the rough ground' } };
}

/** Is the lot round `at` (LOT x LOT, as roughLot marks it) level now: every corner of every tile at one height? */
export function lotLevel(w: World, at: { x: number; z: number }): boolean {
  const x0 = Math.round(at.x - w.ox - LOT / 2), z0 = Math.round(at.z - w.oz - LOT / 2);
  let h: number | null = null;
  for (let z = z0; z < z0 + LOT; z++) {
    for (let x = x0; x < x0 + LOT; x++) {
      if (!inB(x, z)) return false;
      const i = idx(x, z);
      if (steepness(w, i) !== 0) return false;
      if (h === null) h = minCorner(w, i);
      else if (minCorner(w, i) !== h) return false;
    }
  }
  return true;
}

