/** A tow on the fleet thread: the load near a town and where it goes. */
function towTemplate(id: string, load: HaulKind, min: number, o: {
  arc?: string; thread?: Thread; also?: Thread; side?: boolean; title: string; why: string; caption: string;
  targets: (c: MissionCtx, w: World, t: Town) => { x: number; z: number; name: string }[];
  start: (w: World, t: Town) => { x: number; z: number } | null;
  reward: (c: MissionCtx, w: World, t: Town) => Reward[];
  lo?: number; hi?: number; town?: (c: MissionCtx) => TownPick[];
}): Template {
  return {
    id, thread: o.thread ?? 'fleet', also: o.also, kind: 'tow', arc: o.arc, side: o.side, cooldown: o.side ? 96 : undefined,
    gate(c, ms) {
      if (o.arc && !arcAt(ms, o.arc, id)) return 'not yet';
      if (crewed(c) < min - 1) return `needs ${min - 1} crew`;
      return null;
    },
    bind(c, h) {
      const towns = (o.town ?? ((q) => townsNear(q, 200)))(c);
      for (let k = 0; k < towns.length; k++) {
        const { w, t } = towns[(h + k) % towns.length];
        if (w.cx !== c.home.cx || w.cz !== c.home.cz) continue;
        const s = o.start(w, t);
        if (!s) continue;
        const route = towRoute(w, s.x, s.z, o.targets(c, w, t), o.lo ?? 25, o.hi ?? 70);
        if (!route) continue;
        const y = yardOf(c);
        return {
          title: o.title, why: o.why,
          giver: o.arc === 'heavy' && y ? bram(y) : { who: 'mayor', name: `Mayor ${mayorOf(t.name).short}`, at: squareOf(w, t, 'the town hall'), town: townRef(w, t) },
          hero: { kind: 'load', load }, caption: o.caption,
          objs: [
            { t: 'crew', label: `Bring ${min} vehicles`, icon: '🚚', n: min },
            { t: 'tow', label: `Tow it to the ${route.to.name}`.length <= 28 ? `Tow it to the ${route.to.name}` : 'Tow it home', icon: '⛓️', load, from: route.from, to: route.to, min, need: 0 },
          ],
          reward: o.reward(c, w, t),
        };
      }
      return null;
    },
  };
}

/** Where a town would want a heavy thing: its church, its hall, its works, by kind, in its own tiles. */
function placesIn(w: World, t: Town, kinds: string[], name?: string): { x: number; z: number; name: string }[] {
  return t.buildings.filter((b) => kinds.includes(b.kind) && !b.gone)
    .map((b) => ({ x: b.x + b.w / 2, z: b.z + b.d / 2, name: name ?? shortSite(b.kind).toLowerCase() }));
}
/** The edge of a town, where a thing that is not wanted in it is left: the four roads out. */
function outskirts(w: World, t: Town): { x: number; z: number; name: string }[] {
  return t.entry.map((i) => ({ x: (i % N) + 0.5, z: Math.floor(i / N) + 0.5, name: 'edge of town' }));
}

