/** The nearest things of each kind the Passport hasn't got: a biome, a style, a wonder. */
function freshStamps(c: MissionCtx): Obj[] {
  const out: Obj[] = [];
  const byDist = <T extends { x: number; z: number }>(a: T[]) => a.sort((p, q) => Math.hypot(p.x - c.at.x, p.z - c.at.z) - Math.hypot(q.x - c.at.x, q.z - c.at.z));
  // a biome: an island (or a county) of one this save hasn't been to
  const biomes = byDist(c.worlds.filter((w) => w.region && !c.passport.has('biome', w.region) && w.towns.length)
    .map((w) => ({ w, ...squareOf(w, w.towns[0], w.name) })));
  if (biomes[0]?.w.region) {
    const b = biomes[0];
    const label = `Visit ${REGIONS[b.w.region!].title}`;
    out.push({ t: 'visit', label: label.length <= 28 ? label : 'Visit a new biome', icon: '🧭', what: 'biome', key: b.w.region!, at: { x: b.x, z: b.z, cell: b.cell, name: b.w.name } });
  }
  // a style: the nearest town built in one not stamped
  const styles = byDist(c.worlds.flatMap((w) => w.towns.filter((t) => !c.passport.has('arch', t.style)).map((t) => ({ w, t, ...squareOf(w, t, plainTown(t.name)) }))));
  if (styles[0]) {
    const s = styles[0];
    out.push({ t: 'visit', label: `Visit a ${ARCH_LABEL[s.t.style]} town`.slice(0, 28), icon: '🏘️', what: 'arch', key: s.t.style, at: { x: s.x, z: s.z, cell: s.cell, name: s.name } });
  }
  // a wonder
  const wonders = byDist(c.worlds.flatMap((w) => w.works.filter((g) => g.kind === 'wonder' && g.buildings[0] && !c.passport.has('wonder', g.buildings[0].kind))
    .map((g) => ({ w, g, x: w.ox + g.x, z: w.oz + g.z }))));
  if (wonders[0]) {
    const g = wonders[0];
    const label = `Reach ${cap(g.g.name)}`;
    out.push({ t: 'visit', label: label.length <= 28 ? label : 'Reach a wonder', icon: '🗿', what: 'wonder', key: g.g.buildings[0].kind, at: { x: g.x, z: g.z, cell: [g.w.cx, g.w.cz], name: cap(g.g.name) } });
  }
  return out;
}

