/**
 * Open water a boat can reach from a harbour's pier: searched outward over the water from the pier's end,
 * tiles `near`–`far` steps out and deep enough, one picked by `h`. Null when the sea there is too small.
 */
export function offshore(w: World, root: number, dir: number, h: number, near: number, far: number): { lx: number; lz: number } | null {
  const [dx, dz] = DIRS[dir];
  let sx = root % N, sz = Math.floor(root / N), start = -1;
  for (let k = 1; k <= 8; k++) {
    sx += dx; sz += dz;
    if (!inB(sx, sz)) return null;
    if (waterDepth(w, idx(sx, sz)) > 0.6) { start = idx(sx, sz); break; }
  }
  if (start < 0) return null;
  const dist = new Map<number, number>([[start, 0]]);
  const queue = [start];
  const out: number[] = [];
  for (let q = 0; q < queue.length; q++) {
    const i = queue[q], d = dist.get(i)!;
    if (d >= near && waterDepth(w, i) > 1) out.push(i);
    if (d >= far) continue;
    const x = i % N, z = Math.floor(i / N);
    for (const [ex, ez] of DIRS) {
      const nx = x + ex, nz = z + ez;
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (dist.has(j) || waterDepth(w, j) <= 0.6) continue;
      dist.set(j, d + 1);
      queue.push(j);
    }
  }
  if (out.length < 4) return null;
  const i = out[h % out.length];
  return { lx: (i % N) + 0.5, lz: Math.floor(i / N) + 0.5 };
}

/** A harbour of the player's island and a boater stranded off it, for a rescue. */
function rescueAt(c: MissionCtx, h: number): { site: Site; at: PlaceRef } | null {
  const harbours = c.sites(['minorPort', 'majorPort']).filter((s) => s.w === c.home)
    .sort((a, b) => Math.hypot(a.x - c.at.x, a.z - c.at.z) - Math.hypot(b.x - c.at.x, b.z - c.at.z));
  for (const site of harbours.slice(0, 3)) {
    const p = site.w.ports.find((q) => q.id === site.port);
    if (!p) continue;
    const spot = offshore(site.w, p.root, p.dir, h, 18, 55);
    if (spot) return { site, at: { x: site.w.ox + spot.lx, z: site.w.oz + spot.lz, cell: [site.w.cx, site.w.cz], name: 'offshore' } };
  }
  return null;
}

