export const templateById = (id: string): Template | undefined => TEMPLATES.find((t) => t.id === id);

/** A reward's worth in dollars, for the balance check. */
export function worth(r: Reward): number {
  switch (r.r) {
    case 'cash': return r.n;
    case 'vehicle': return priceOf(r.model) * 0.6;
    case 'part': return 400 * r.tier;
    case 'standing': return 400 * r.n;
    default: return 300;
  }
}

